#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define CE_PIN 8

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(CE_PIN, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting soil moisture sensor monitoring...\n");

    while (keep_running) {
        unsigned char tx[3] = {1, (1 << 7) | (SPI_CHANNEL << 4), 0};
        unsigned char rx[3] = {0};

        if (spiXfer(spi_handle, tx, rx, 3) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            break;
        }

        int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        printf("%s - ADC Value: %d\n", timestamp, adc_value);

        gpioSleep(1, 0, 100000000); // Sleep for 1 second
    }

    spiClose(spi_handle);
    gpioTerminate();
    printf("Monitoring stopped\n");

    return EXIT_SUCCESS;
}

