#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define MLX91219_SENSITIVITY 0.040 // 40mV/A
#define SAMPLE_INTERVAL_MS 500
#define PGA_GAIN 4.096
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_CONFIG_REG 0x01

volatile int keepRunning = 1;

void signalHandler(int signum) {
    keepRunning = 0;
}

int configureADS1115(int i2cHandle) {
    uint16_t config = 0x8583; // Single-shot mode, AIN0, PGA=±4.096V, 128SPS
    return i2cWriteI2CBlockData(i2cHandle, ADS1115_ADDR, ADS1115_CONFIG_REG, (char *)&config, 2);
}

int readADC(int i2cHandle) {
    char buffer[2];
    if (i2cReadI2CBlockData(i2cHandle, ADS1115_ADDR, ADS1115_CONVERSION_REG, buffer, 2) < 0) {
        return -1;
    }
    return (buffer[0] << 8) | buffer[1];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2cHandle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (configureADS1115(i2cHandle) < 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signalHandler);

    while (keepRunning) {
        int adcValue = readADC(i2cHandle);
        if (adcValue < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
        } else {
            float voltage = (adcValue * PGA_GAIN) / 32767.0;
            float current = (voltage - 2.048) * MLX91219_SENSITIVITY;
            printf("Current: %.3f A\n", current);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    i2cClose(i2cHandle);
    gpioTerminate();
    return 0;
}

