#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define KY026_PIN 4
#define MCP3008_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LOG_FILE "flame_data.csv"

static volatile int keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = 0;
    }
}

int main() {
    FILE *log_file;
    time_t raw_time;
    struct tm *time_info;
    char timestamp[20];
    int adc_value;
    int flame_detected;
    float temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(KY026_PIN, PI_INPUT);
    gpioSetPullUpDown(KY026_PIN, PI_PUD_DOWN);

    if (gpioHardwareRevision() == 0) {
        fprintf(stderr, "pigpio not running on a Raspberry Pi\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_CHANNEL, PI_ALT0) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (keep_running) {
        time(&raw_time);
        time_info = localtime(&raw_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        flame_detected = gpioRead(KY026_PIN);

        adc_value = gpioSPIxfer(SPI_CHANNEL, (MCP3008_CHANNEL << 4) | 0x1, 2);
        if (adc_value < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        adc_value = ((adc_value & 0x3) << 8) | (gpioSPIxfer(SPI_CHANNEL, 0, 2) & 0xFF);

        temperature = 10.0 + (adc_value * (40.0 - 10.0) / 1023.0);

        fprintf(log_file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
        fflush(log_file);

        gpioSleep(PI_TIME_RELATIVE, 1, 0);
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

