#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define I2C_ADDR 0x48
#define ADC_CONFIG 0x01
#define ADC_CONVERT 0x00
#define TEMP_THRESHOLD 60.0
#define POLL_INTERVAL_MS 100
#define DEBOUNCE_TIME_MS 50

static volatile int running = 1;
static time_t last_flame_event_time = 0;

void handle_sigint(int signo) {
    running = 0;
}

void flame_isr(int gpio, int level, uint32_t tick) {
    time_t now = time(NULL);
    if (difftime(now, last_flame_event_time) >= DEBOUNCE_TIME_MS / 1000.0) {
        last_flame_event_time = now;
        printf("Flame event detected at %s", ctime(&now));
    }
}

float adc_to_temperature(uint16_t adc_value) {
    // Map ADC value (0-4095) to temperature (20-80°C)
    return 20.0 + (adc_value * (80.0 - 20.0) / 4095.0);
}

int main() {
    FILE *log_file = NULL;
    int i2c_handle = -1;
    uint16_t adc_value = 0;
    float temperature = 0.0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, PI_LOW);

    if (gpioSetISRFunc(FLAME_SENSOR_PIN, FALLING_EDGE, 0, flame_isr) < 0) {
        fprintf(stderr, "Failed to set ISR for flame sensor\n");
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("fire_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (running) {
        int flame_detected = !gpioRead(FLAME_SENSOR_PIN);

        if (i2cWriteWordData(i2c_handle, ADC_CONFIG, 0x8583) < 0) {
            fprintf(stderr, "Failed to configure ADC\n");
            continue;
        }

        sleep(1); // Wait for conversion to complete

        if (i2cReadWordData(i2c_handle, ADC_CONVERT, &adc_value) < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        temperature = adc_to_temperature(adc_value);

        if (flame_detected && temperature > TEMP_THRESHOLD) {
            time_t now = time(NULL);
            fprintf(log_file, "Fire detected at %s", ctime(&now));
            fflush(log_file);
            gpioWrite(BUZZER_PIN, PI_HIGH);
            sleep(2);
            gpioWrite(BUZZER_PIN, PI_LOW);
        } else if (flame_detected) {
            fprintf(log_file, "Flame detected!\n");
            fflush(log_file);
        } else if (temperature > TEMP_THRESHOLD) {
            fprintf(log_file, "Temperature: %.2f°C\n", temperature);
            fflush(log_file);
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    gpioWrite(BUZZER_PIN, PI_LOW);
    gpioSetISRFunc(FLAME_SENSOR_PIN, 0, 0, NULL);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

