#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define DEFAULT_SENSITIVITY 100.0f // mV/A
#define DEFAULT_THRESHOLD 5.0f     // A
#define SPI_SPEED 1000000          // 1 MHz
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define ADC_COMMAND 0x018000
#define ADC_CHANNEL 0

static volatile sig_atomic_t keep_running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *fan_line = NULL;

void signal_handler(int signum) {
    keep_running = 0;
}

int setup_spi() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_adc() {
    uint8_t tx[3] = { (ADC_COMMAND >> 16) & 0xFF, (ADC_COMMAND >> 8) & 0xFF, ADC_COMMAND & 0xFF };
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to transfer SPI data");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

int setup_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip gpiochip4, trying gpiochip0\n");
        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            perror("Failed to open GPIO chip");
            return -1;
        }
    }

    fan_line = gpiod_chip_get_line(chip, 18);
    if (!fan_line) {
        perror("Failed to get GPIO line for fan");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(fan_line, "fan-control", 0) < 0) {
        perror("Failed to request GPIO line for fan");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void cleanup() {
    if (fan_line) {
        gpiod_line_set_value(fan_line, 0);
        gpiod_line_release(fan_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

int main(int argc, char *argv[]) {
    float sensitivity = DEFAULT_SENSITIVITY;
    float threshold = DEFAULT_THRESHOLD;
    int opt;

