#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define ADC_ADDR 0x48
#define ADC_CONFIG 0x01
#define ADC_CONV 0x00
#define LOG_FILE "co_log.txt"
#define READ_INTERVAL 5

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int read_adc(int channel) {
    uint16_t config = (1 << 15) | (channel << 12) | 0x0200; // Start single conversion
    i2cWriteWordData(ADC_ADDR, ADC_CONFIG, config);
    gpioSleep(1, 0, 100000); // Wait for conversion to complete (100ms)
    return i2cReadWordData(ADC_ADDR, ADC_CONV);
}

double convert_to_ppm(int raw_value) {
    // Calibration curve: y = a * log(x) + b
    // Replace with actual calibration constants
    double a = 0.0001;
    double b = 0.1;
    return a * log(raw_value) + b;
}

int main() {
    FILE *log_file;
    time_t raw_time;
    struct tm *time_info;
    char time_str[26];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (i2cOpen(I2C_BUS, ADC_ADDR) < 0) {
        fprintf(stderr, "Failed to open ADC I2C bus\n");
        i2cClose(I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(ADC_ADDR);
        i2cClose(I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        int raw_value = read_adc(0); // Assuming CO sensor is on channel 0
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read from ADC\n");
            break;
        }

        double ppm = convert_to_ppm(raw_value);

        time(&raw_time);
        time_info = localtime(&raw_time);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);

        fprintf(log_file, "%s, %.2f\n", time_str, ppm);
        fflush(log_file);

        gpioSleep(1, READ_INTERVAL, 0);
    }

    fclose(log_file);
    i2cClose(ADC_ADDR);
    i2cClose(I2C_ADDR);
    gpioTerminate();

    return 0;
}

