#include <errno.h>

#define KY026_PIN 4
#define MCP3008_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define CSV_FILE "flame_data.csv"

static volatile int keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = 0;
    }
}

int main() {
    FILE *csv_file;
    time_t raw_time;
    struct tm *time_info;
    char time_str[20];
    int spi_handle;
    unsigned char spi_buf[3];
    unsigned char adc_value;
    int flame_detected;
    float temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI handle: %s\n", strerror(errno));
        fclose(csv_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        flame_detected = gpioRead(KY026_PIN);

        spi_buf[0] = 0x01;
        spi_buf[1] = (MCP3008_CHANNEL << 4) | 0x08;
        spi_buf[2] = 0x00;

        if (spiXfer(spi_handle, spi_buf, (char *)spi_buf, 3) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
        } else {
            adc_value = ((spi_buf[1] & 0x03) << 8) | spi_buf[2];
            temperature = 30.0 + (adc_value * (40.0 - 30.0) / 1023.0);

            time(&raw_time);
            time_info = localtime(&raw_time);
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);

            fprintf(csv_file, "%s,%d,%.1f\n", time_str, flame_detected, temperature);
            fflush(csv_file);
        }

        time_sleep(1);
    }

    spiClose(spi_handle);
    fclose(csv_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

