#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS 1
#define MICS4514_ADDR 0x19
#define CO_ADC_REG 0x04
#define NO2_ADC_REG 0x05
#define CO_SENSITIVITY 1.1
#define NO2_SENSITIVITY 0.5
#define ALERT_THRESHOLD 25
#define LOG_INTERVAL 5

static volatile int keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int read_sensor(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (i2cReadI2CBlockData(fd, MICS4514_ADDR, reg, 2, buf) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int log_co_level(float co_ppm) {
    FILE *file = fopen("co_log.txt", "a");
    if (!file) {
        fprintf(stderr, "Error opening co_log.txt: %s\n", strerror(errno));
        return -1;
    }
    time_t now = time(NULL);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0';  // Remove newline
    fprintf(file, "[%s] CO level: %.2f PPM\n", time_str, co_ppm);
    fclose(file);
    return 0;
}

int log_alert(float co_ppm) {
    FILE *file = fopen("alert_log.txt", "a");
    if (!file) {
        fprintf(stderr, "Error opening alert_log.txt: %s\n", strerror(errno));
        return -1;
    }
    time_t now = time(NULL);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0';  // Remove newline
    fprintf(file, "[%s] ALERT: CO level %.2f PPM exceeds threshold\n", time_str, co_ppm);
    fclose(file);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, MICS4514_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        uint16_t co_adc, no2_adc;
        if (read_sensor(i2c_handle, CO_ADC_REG, &co_adc) < 0 ||
            read_sensor(i2c_handle, NO2_ADC_REG, &no2_adc) < 0) {
            sleep(1);
            continue;
        }

        float co_ppm = co_adc * CO_SENSITIVITY;
        if (log_co_level(co_ppm) < 0) {
            keep_running = 0;
            break;
        }

        if (co_ppm > ALERT_THRESHOLD) {
            if (log_alert(co_ppm) < 0) {
                keep_running = 0;
                break;
            }
        }

        sleep(LOG_INTERVAL);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

