#define SENSOR2_ADDR 0x49
#define REGISTER 0x00
#define SAMPLE_INTERVAL_MS 100
#define MIC_SENSITIVITY -38.0 // dBV/Pa
#define REF_PRESSURE 20e-6 // Pa

volatile int keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        keep_running = 0;
    }
}

int read_microphone(int i2c_bus, int address) {
    char buf[2];
    if (i2c_read_i2c_block(i2c_bus, address, REGISTER, 2, buf) < 0) {
        return -999;
    }
    return (buf[0] << 8) | buf[1];
}

double raw_to_db(int raw_value) {
    if (raw_value == -999) return -999.0;
    double voltage = (double)raw_value / 32768.0 * 2.5; // Assuming 2.5V reference
    double pressure = voltage * pow(10, MIC_SENSITIVITY / 20.0);
    return 20 * log10(pressure / REF_PRESSURE);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (i2cOpen(I2C_BUS, SENSOR1_ADDR, 0) < 0 || i2cOpen(I2C_BUS, SENSOR2_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen("audio_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(I2C_BUS, SENSOR1_ADDR);
        i2cClose(I2C_BUS, SENSOR2_ADDR);
        gpioTerminate();
        return 1;
    }

    time_t last_log_time = time(NULL);

    while (keep_running) {
        int raw1 = read_microphone(I2C_BUS, SENSOR1_ADDR);
        int raw2 = read_microphone(I2C_BUS, SENSOR2_ADDR);

        double db1 = raw_to_db(raw1);
        double db2 = raw_to_db(raw2);

        time_t current_time = time(NULL);
        if (current_time - last_log_time >= 1) {
            fprintf(log_file, "[%ld] Sensor1: %.1f dB, Sensor2: %.1f dB\n", 
                    (long)current_time, db1, db2);
            fflush(log_file);
            last_log_time = current_time;
        }

        time_sleep(SAMPLE_INTERVAL_MS / 1000.0);
    }

    fclose(log_file);
    i2cClose(I2C_BUS, SENSOR1_ADDR);
    i2cClose(I2C_BUS, SENSOR2_ADDR);
    gpioTerminate();

    return 0;
}

