#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define NUM_SAMPLES 100
#define SAMPLE_INTERVAL_MS 1
#define RMS_THRESHOLD 0.7
#define LED_PIN 27
#define CSV_FILE "audio_events.csv"

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

double calculate_rms(int16_t *samples, int num_samples) {
    double sum_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double sample = (double)samples[i];
        sum_squares += sample * sample;
    }
    return sqrt(sum_squares / num_samples);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_LOW);

    FILE *csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        gpioTerminate();
        return 1;
    }
    fprintf(csv_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        fclose(csv_file);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    int16_t mic1_samples[NUM_SAMPLES];
    int16_t mic2_samples[NUM_SAMPLES];
    char buffer[3];
    time_t start_time = time(NULL);

    while (keep_running) {
        time_t current_time = time(NULL);
        struct tm *time_info = localtime(&current_time);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        for (int i = 0; i < NUM_SAMPLES; i++) {
            buffer[0] = 0x01;  // Start bit
            buffer[1] = 0x80;  // Single-ended, channel 0
            buffer[2] = 0x00;  // Dummy byte

            if (spiXfer(spi_handle, buffer, buffer, 3) < 0) {
                fprintf(stderr, "SPI transfer failed\n");
                break;
            }
            mic1_samples[i] = ((buffer[1] & 0x03) << 8) | buffer[2];

            buffer[1] = 0x01;  // Start bit
            buffer[2] = 0x00;  // Dummy byte

            if (spiXfer(spi_handle, buffer, buffer, 3) < 0) {
                fprintf(stderr, "SPI transfer failed\n");
                break;
            }
            mic2_samples[i] = ((buffer[1] & 0x03) << 8) | buffer[2];

            gpioDelay(SAMPLE_INTERVAL_MS * 1000);
        }

        double mic1_rms = calculate_rms(mic1_samples, NUM_SAMPLES);
        double mic2_rms = calculate_rms(mic2_samples, NUM_SAMPLES);

        fprintf(csv_file, "%s,%.4f,%.4f\n", timestamp, mic1_rms, mic2_rms);
        fflush(csv_file);

        if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
            gpioWrite(LED_PIN, PI_HIGH);
            gpioDelay(500000);
            gpioWrite(LED_PIN, PI_LOW);
        }

        if (difftime(time(NULL), start_time) >= 100) {
            break;
        }
    }

    spiClose(spi_handle);
    fclose(csv_file);
    gpioWrite(LED_PIN, PI_LOW);
    gpioTerminate();

    return 0;
}

