#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>

#define I2C_BUS 1
#define ADS1115_ADDRESS 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define SAMPLE_RATE_HZ 10
#define BUFFER_SIZE 100
#define CURRENT_THRESHOLD 50.0
#define WARNING_LED_PIN 17

volatile int keep_running = 1;
float current_buffer[BUFFER_SIZE] = {0};
int buffer_index = 0;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = 0;
    }
}

int init_ads1115() {
    unsigned char config[3];
    config[0] = ADS1115_CONFIG_REG;
    config[1] = 0x83; // Start single-shot conversion, A0 input, 128SPS
    config[2] = 0x80;

    if (i2cWriteDevice(I2C_BUS, ADS1115_ADDRESS, config, 3) < 0) {
        fprintf(stderr, "Failed to write to ADS1115\n");
        return -1;
    }
    return 0;
}

float read_ads1115() {
    unsigned char data[3];
    int raw_adc;

    if (i2cWriteDevice(I2C_BUS, ADS1115_ADDRESS, (unsigned char[]){ADS1115_CONVERSION_REG}, 1) < 0) {
        fprintf(stderr, "Failed to write to ADS1115\n");
        return -1;
    }

    gpioDelay(10000); // Wait for conversion to complete

    if (i2cReadDevice(I2C_BUS, ADS1115_ADDRESS, data, 2) < 0) {
        fprintf(stderr, "Failed to read from ADS1115\n");
        return -1;
    }

    raw_adc = (data[0] << 4) | (data[1] >> 4);
    return (raw_adc * 4.5) / 32767.0; // Convert to voltage
}

float calculate_current(float voltage) {
    return (voltage - 0.5) / 4.0 * 100.0; // Convert voltage to current
}

void update_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

float calculate_average_current() {
    float sum = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (init_ads1115() < 0) {
        gpioTerminate();
        return 1;
    }

    gpioSetMode(WARNING_LED_PIN, PI_OUTPUT);
    gpioWrite(WARNING_LED_PIN, PI_LOW);

    signal(SIGINT, signal_handler);

    struct timespec start, end;
    long elapsed_ns;

    while (keep_running) {
        clock_gettime(CLOCK_MONOTONIC, &start);

        float voltage = read_ads1115();
        if (voltage < 0) {
            fprintf(stderr, "Failed to read sensor\n");
            continue;
        }

        float current = calculate_current(voltage);
        update_buffer(current);

        float avg_current = calculate_average_current();
        if (avg_current > CURRENT_THRESHOLD) {
            gpioWrite(WARNING_LED_PIN, PI_HIGH);
        } else {
            gpioWrite(WARNING_LED_PIN, PI_LOW);
        }

        printf("Current: %.2f A, Avg Current: %.2f A\n", current, avg_current);

        clock_gettime(CLOCK_MONOTONIC, &end);
        elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000L + (end.tv_nsec - start.tv_nsec);
        if (elapsed_ns < (1000000000L / SAMPLE_RATE_HZ)) {
            gpioDelay((1000000000L / SAMPLE_RATE_HZ) - elapsed_ns);
        }
    }

    gpioWrite(WARNING_LED_PIN, PI_LOW);
    gpioTerminate();
    return 0;
}

