#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x29
#define ID_REG 0x12
#define ATIME_REG 0x01
#define CONTROL_REG 0x0F
#define ENABLE_REG 0x00
#define CLEAR_DATA_REG 0x14
#define CSV_FILENAME "color_log.csv"

static int i2c_handle;
static FILE *csv_file;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int i2c_read_retry(int fd, uint8_t reg, uint8_t *data, int retries) {
    int retries_left = retries;
    while (retries_left > 0) {
        if (i2cReadI2CBlock(fd, reg, data, 1) == 1) {
            return 0;
        }
        fprintf(stderr, "Warning: I2C read failed, retrying...\n");
        retries_left--;
        gpioSleep(PI_TIME_MILLISECOND, 100, 0);
    }
    return -1;
}

int i2c_write_retry(int fd, uint8_t reg, uint8_t data, int retries) {
    int retries_left = retries;
    while (retries_left > 0) {
        if (i2cWriteByteData(fd, reg, data) == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: I2C write failed, retrying...\n");
        retries_left--;
        gpioSleep(PI_TIME_MILLISECOND, 100, 0);
    }
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    uint8_t id;
    if (i2c_read_retry(i2c_handle, ID_REG, &id, 3) != 0 || (id & 0x0F) != 0x44) {
        fprintf(stderr, "Sensor ID mismatch\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2c_write_retry(i2c_handle, ATIME_REG, 0xFF, 3) != 0 ||
        i2c_write_retry(i2c_handle, CONTROL_REG, 0x01, 3) != 0 ||
        i2c_write_retry(i2c_handle, ENABLE_REG, 0x03, 3) != 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSleep(PI_TIME_MILLISECOND, 3, 0);

    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "YYYY-MM-DD HH:MM:SS,clear,red,green,blue\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_read_time = 0;
