int i2c_read_retry(int fd, uint8_t reg, uint8_t *data, int retries) {
    int retries_left = retries;
    while (retries_left > 0) {
        if (i2cReadI2CBlock(fd, reg, data, 1) == 1) {
            return 0;
        }
        fprintf(stderr, "Warning: I2C read failed, retrying...\n");
        retries_left--;
        gpioSleep(PI_TIME_MILLISECOND, 100, 0);
    }
    return -1;
}

int i2c_write_retry(int fd, uint8_t reg, uint8_t data, int retries) {
    int retries_left = retries;
    while (retries_left > 0) {
        if (i2cWriteByteData(fd, reg, data) == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: I2C write failed, retrying...\n");
        retries_left--;
        gpioSleep(PI_TIME_MILLISECOND, 100, 0);
    }
    return -1;
}

