#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CHIP_SELECT_PIN 8
#define MOISTURE_SENSOR_1_CHANNEL 0
#define MOISTURE_SENSOR_2_CHANNEL 1
#define SPI_SPEED 500000
#define LOG_FILE "moisture_log.csv"
#define SAMPLE_INTERVAL 5

static int spi_fd;
static struct gpiod_line *cs_line;

void cleanup(int signum) {
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(EXIT_SUCCESS);
}

int spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    int adc_value;

    tx[0] = 0x01;
    tx[1] = (channel << 4) | 0x00;
    tx[2] = 0x00;

    if (spi_transfer(tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

int map_adc_to_moisture(int adc_value) {
    // Assuming a linear mapping for simplicity
    return (adc_value * 100) / 1023;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    cs_line = gpiod_chip_get_line(chip, CHIP_SELECT_PIN);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(cs_line, "MCP3008_CS", 1) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup(0);
    }

    fprintf(log_file, "Timestamp,Moisture1,Moisture2\n");

    while (1) {
        gpiod_line_set_value(cs_line, 0);
        int moisture1 = read_adc(MOISTURE_SENSOR_1_CHANNEL);
        int moisture2 = read_adc(MOISTURE_SENSOR_2_CHANNEL);
        gpiod_line_set_value(cs_line, 1);

        if (moisture1 < 0 || moisture2 < 0) {
            fprintf(stderr, "Failed to read moisture sensors\n");
        } else {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[26];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s,%d,%d\n", timestamp, map_adc_to_moisture(moisture1), map_adc_to_moisture(moisture2));
            fflush(log_file);
        }

        sleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    cleanup(0);
    return EXIT_SUCCESS;
}

