#define SPI_DEVICE "/dev/spidev0.0"
#define MCP3008_CHANNEL 0
#define CURRENT_SENSOR_SENSITIVITY 0.1
#define CURRENT_SENSOR_OFFSET 0.05
#define OVERCURRENT_THRESHOLD 10.0
#define MOTOR_SHUTDOWN_PIN 17
#define LOG_FILE "current_log.csv"
#define SPI_RETRIES 3

static int spi_fd;
static int motor_shutdown_fd;
static FILE *log_file;
static struct gpiod_line *motor_shutdown_line;

void cleanup(void) {
    if (log_file) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (motor_shutdown_fd >= 0) {
        gpiod_line_release(motor_shutdown_line);
        gpiod_line_release_request(motor_shutdown_line);
        gpiod_chip_close(motor_shutdown_line->chip);
        close(motor_shutdown_fd);
    }
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = 500000,
        .bits_per_word = 8,
    };

    int retries = 0;
    while (retries < SPI_RETRIES) {
        int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
        if (ret == len) {
            return 0;
        }
        retries++;
        usleep(100000); // 100ms delay before retry
    }
    return -1;
}

float read_current_sensor(void) {
    unsigned char tx[3] = {1, (MCP3008_CHANNEL << 4) | 0x01, 0};
    unsigned char rx[3] = {0};

    if (spi_transfer(tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    unsigned int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    float voltage = (float)adc_value * 3.3 / 1023.0;
    return (voltage - CURRENT_SENSOR_OFFSET) / CURRENT_SENSOR_SENSITIVITY;
}

int main(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request motor shutdown line
    motor_shutdown_line = gpiod_chip_get_line(chip, MOTOR_SHUTDOWN_PIN);
    if (!motor_shutdown_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        cleanup();
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_output(motor_shutdown_line, "motor_shutdown", 1);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(motor_shutdown_line);
        gpiod_chip_close(chip);
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Write header if file is empty
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,current_in_Amperes\n");
    }

    while (1) {
        float current = read_current_sensor();
        if (current < 0) {
            fprintf(stderr, "Failed to read current sensor\n");
            sleep(1);
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.2f\n", timestamp, current);
        fflush(log_file);

        if (current > OVERCURRENT_THRESHOLD) {
            gpiod_line_set_value(motor_shutdown_line, 0);
            fprintf(log_file, "%s,Overcurrent detected! Motor disabled.\n", timestamp);
            fflush(log_file);
            sleep(1);
            gpiod_line_set_value(motor_shutdown_line, 1);
            fprintf(log_file, "%s,Motor re-enabled.\n", timestamp);
            fflush(log_file);
        }

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

