    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
        fflush(log_file);
    }

