#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define ADS1115_ADDRESS 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define PRESSURE_CHANNEL 0
#define TEMP_CHANNEL 1
#define WARNING_LED_PIN 17
#define MAX_RETRIES 3
#define SAMPLE_RATE 128
#define SAMPLE_INTERVAL_MS 1000

static volatile int keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = 0;
    }
}

int configure_ads1115(int i2c_handle) {
    uint16_t config = 0x8583; // Single-shot mode, AIN0, gain=2/3, 128 SPS
    return i2cWriteWordData(i2c_handle, ADS1115_CONFIG_REG, config);
}

int read_adc(int i2c_handle, int channel) {
    uint16_t config = 0x8583 | (channel << 12);
    if (i2cWriteWordData(i2c_handle, ADS1115_CONFIG_REG, config) < 0) {
        return -1;
    }

    time_t start_time = time(NULL);
    int16_t adc_value = 0;
    int retries = 0;

    while (time(NULL) - start_time < 1) {
        adc_value = i2cReadWordData(i2c_handle, ADS1115_CONVERSION_REG);
        if (adc_value >= 0) {
            return adc_value;
        }
        if (++retries >= MAX_RETRIES) {
            return -1;
        }
        gpioDelay(10000); // 10ms delay before retry
    }
    return -1;
}

float adc_to_pressure(int adc_value) {
    return (float)adc_value * 400.0 / 32767.0;
}

float adc_to_temperature(int adc_value) {
    return (float)adc_value * 100.0 / 32767.0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(1, ADS1115_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (configure_ads1115(i2c_handle) < 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(WARNING_LED_PIN, PI_OUTPUT);
    gpioWrite(WARNING_LED_PIN, PI_LOW);

    signal(SIGINT, signal_handler);

    while (keep_running) {
        int pressure_adc = read_adc(i2c_handle, PRESSURE_CHANNEL);
        int temp_adc = read_adc(i2c_handle, TEMP_CHANNEL);

        if (pressure_adc < 0 || temp_adc < 0) {
            fprintf(stderr, "Failed to read ADC values\n");
        } else {
            float pressure = adc_to_pressure(pressure_adc);
            float temperature = adc_to_temperature(temp_adc);

            printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

            if (pressure > 105.0) {
                gpioWrite(WARNING_LED_PIN, PI_HIGH);
            } else {
                gpioWrite(WARNING_LED_PIN, PI_LOW);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

