#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_MAX_VALUE 1023
#define VOLTAGE_REF 3.3
#define CURRENT_SENSITIVITY 0.066 // 66 mV/A
#define CURRENT_THRESHOLD 10.0 // 10 A
#define LOG_FILE "current_log.txt"
#define OVERCURRENT_GPIO 27

static int spi_handle;
static FILE *log_file;

void cleanup(int signum) {
    if (spi_handle >= 0) {
        close(spi_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioWrite(OVERCURRENT_GPIO, LOW);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

float adc_to_current(uint16_t adc_value) {
    float voltage = (float)adc_value * VOLTAGE_REF / ADC_MAX_VALUE;
    float current = (voltage - VOLTAGE_REF / 2) / CURRENT_SENSITIVITY;
    return current;
}

int main() {
    struct timespec ts;
    uint8_t spi_buf[3];
    uint16_t adc_value;
    float current;
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(OVERCURRENT_GPIO, PI_OUTPUT);
    gpioWrite(OVERCURRENT_GPIO, LOW);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        spi_buf[0] = 0x01;
        spi_buf[1] = 0x80; // Start bit + single-ended channel 0
        spi_buf[2] = 0x00; // Zero pad byte

        if (spiXfer(spi_handle, spi_buf, (char *)spi_buf, 3) < 0) {
            fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
            cleanup(0);
        }

        adc_value = ((spi_buf[1] & 0x03) << 8) | spi_buf[2];
        if (adc_value > ADC_MAX_VALUE) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            cleanup(0);
        }

        current = adc_to_current(adc_value);

        time(&now);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s, %.3f A\n", timestamp, current);
        fflush(log_file);

        if (current > CURRENT_THRESHOLD) {
            gpioWrite(OVERCURRENT_GPIO, HIGH);
            fprintf(log_file, "%s, OVERCURRENT event\n", timestamp);
            fflush(log_file);
            cleanup(0);
        }

        nanosleep(&(struct timespec){0, 100000000}, &ts); // 100ms
    }

    return EXIT_SUCCESS;
}

