#include <time.h>
#include <errno.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ALARM_PIN 4
#define ADC_VOLTAGE_REF 3.3
#define ADC_MAX_VALUE 1023
#define CO_ALARM_THRESHOLD 2.5
#define LOG_FILE_NAME "co_log.txt"

static int spi_handle;
static FILE *log_file;

void cleanup(int signum) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioWrite(ALARM_PIN, LOW);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void log_reading(double voltage) {
    time_t now;
    struct tm *tm_info;
    char time_str[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,Voltage: %.2f V\n", time_str, voltage);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for alarm pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3] = {0};
    int retry_count = 0;

    while (1) {
        if (spiXfer(spi_handle, tx, rx, 3) < 0) {
            if (retry_count < 5) {
                fprintf(stderr, "SPI transfer failed, retrying...\n");
                gpioWrite(ALARM_PIN, LOW);
                retry_count++;
                time_sleep(1);
                continue;
            } else {
                fprintf(stderr, "SPI transfer failed after retries\n");
                gpioWrite(ALARM_PIN, LOW);
                time_sleep(1);
                retry_count = 0;
                continue;
            }
        }

        retry_count = 0;

        int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        double voltage = (adc_value * ADC_VOLTAGE_REF) / ADC_MAX_VALUE;

        log_reading(voltage);

        if (voltage > CO_ALARM_THRESHOLD) {
            gpioWrite(ALARM_PIN, HIGH);
        } else {
            gpioWrite(ALARM_PIN, LOW);
        }

        time_sleep(1);
    }

    return EXIT_SUCCESS;
}

