                fprintf(stderr, "SPI transfer failed, retrying...\n");
                gpioWrite(ALARM_PIN, LOW);
                retry_count++;
                time_sleep(1);
                continue;
            } else {
                fprintf(stderr, "SPI transfer failed after retries\n");
                gpioWrite(ALARM_PIN, LOW);
                time_sleep(1);
                retry_count = 0;
                continue;
            }
        }

        retry_count = 0;

        int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        double voltage = (adc_value * ADC_VOLTAGE_REF) / ADC_MAX_VALUE;

        log_reading(voltage);

        if (voltage > CO_ALARM_THRESHOLD) {
            gpioWrite(ALARM_PIN, HIGH);
        } else {
            gpioWrite(ALARM_PIN, LOW);
        }

        time_sleep(1);
    }

    return EXIT_SUCCESS;
}
