#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define ADS1115_ADDRESS 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define SENSOR_PIN 0
#define SAMPLE_RATE 1000000 // 1Hz
#define MIN_PRESSURE 0.0
#define MAX_PRESSURE 100.0
#define OFFSET_VOLTAGE 0.5
#define SENSITIVITY 0.1

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }
    if (i2cOpen(I2C_BUS, ADS1115_ADDRESS) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

int configure_ads1115() {
    uint16_t config = 0x8400; // Single-shot mode, AIN0, 128SPS
    if (i2cWriteWordData(I2C_BUS, ADS1115_ADDRESS, ADS1115_CONFIG_REG, config) < 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        return -1;
    }
    return 0;
}

int read_adc() {
    if (i2cWriteByte(I2C_BUS, ADS1115_ADDRESS, ADS1115_CONVERSION_REG) < 0) {
        fprintf(stderr, "Failed to start ADC conversion\n");
        return -1;
    }
    gpioSleep(PI_TIME_RELATIVE, 0, 1000000); // Wait for conversion (1 second)
    int16_t raw_value = i2cReadWordData(I2C_BUS, ADS1115_ADDRESS, ADS1115_CONVERSION_REG);
    if (raw_value < 0) {
        fprintf(stderr, "Failed to read ADC value\n");
        return -1;
    }
    return raw_value;
}

float convert_to_pressure(int raw_value) {
    float voltage = (raw_value * 4.096) / 32767.0; // Assuming VDD = 3.3V
    float pressure = (voltage - OFFSET_VOLTAGE) / SENSITIVITY;
    if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
        return -1; // Invalid pressure range
    }
    return pressure;
}

void log_pressure(float pressure) {
    FILE *file = fopen("pressure_log.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    fprintf(file, "%s %.2f kPa\n", timestamp, pressure);
    fclose(file);
}

int main() {
    if (init_i2c() < 0) return EXIT_FAILURE;
    if (configure_ads1115() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (keep_running) {
        int raw_value = read_adc();
        if (raw_value >= 0) {
            float pressure = convert_to_pressure(raw_value);
            if (pressure >= 0) {
                log_pressure(pressure);
            }
        }
        gpioSleep(PI_TIME_RELATIVE, 0, SAMPLE_RATE);
    }

    i2cClose(I2C_BUS, ADS1115_ADDRESS);
    gpioTerminate();
    return EXIT_SUCCESS;
}

