#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>
#include <string.h>
#include <syslog.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define HIH4602_HUMIDITY_PIN 0
#define HIH4602_TEMPERATURE_PIN 1
#define HUMIDITY_THRESHOLD 80.0
#define EMAIL_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_COMMAND "echo 'Humidity exceeds threshold' | ssmtp user@example.com"

static volatile int keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        keep_running = 0;
    }
}

double read_adc(int channel) {
    unsigned char tx[3], rx[3];
    int adc_value;

    tx[0] = 0x06 | ((channel & 0x07) << 4);
    tx[1] = 0x00;
    tx[2] = 0x00;

    if (spiXfer(SPI_CHANNEL, tx, rx, 3) < 0) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }

    adc_value = ((rx[0] & 0x0F) << 8) | rx[1];
    return (double)adc_value * 5.0 / 4095.0;
}

double calculate_humidity(double voltage) {
    return (voltage - 0.824) / 0.0315;
}

double calculate_temperature(double voltage) {
    double resistance = (5.0 - voltage) * 10000.0 / voltage;
    double temp = 1.0 / (1.0 / (25.0 + 273.15) + 1.0 / 3950.0 * log(resistance / 10000.0));
    return temp - 273.15;
}

void log_readings(double humidity, double temperature) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        syslog(LOG_ERR, "Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fclose(file);
}

void send_email_alert(double humidity) {
    if (humidity > EMAIL_THRESHOLD) {
        system(EMAIL_COMMAND);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        syslog(LOG_ERR, "Failed to open SPI channel");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        double humidity_voltage = read_adc(HIH4602_HUMIDITY_PIN);
        double temperature_voltage = read_adc(HIH4602_TEMPERATURE_PIN);

        if (humidity_voltage < 0 || temperature_voltage < 0) {
            syslog(LOG_ERR, "Failed to read ADC values");
            continue;
        }

        double humidity = calculate_humidity(humidity_voltage);
        double temperature = calculate_temperature(temperature_voltage);

        log_readings(humidity, temperature);
        send_email_alert(humidity);

        sleep(60);  // Wait for 1 minute before next reading
    }

    spiClose(SPI_CHANNEL);
    gpioTerminate();
    return 0;
}

