#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "/dev/gpiochip4"
#define MCP3208_CS_PIN 8
#define VREF 3.3
#define ADC_MAX_VALUE 4095
#define TEMP_COEFFICIENT 0.01
#define TEMP_OFFSET 0.5
#define LOG_FILE "temperature_log.csv"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000

static int spi_fd;
static struct gpiod_line *cs_line;
static FILE *log_file;

void cleanup(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int ret;
    struct spi_ioc_transfer xfer = {
        .bits_per_word = SPI_BITS_PER_WORD,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI max speed");
        return -1;
    }

    return 0;
}

int init_gpio() {
    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, MCP3208_CS_PIN);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line for CS\n");
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_request_output(cs_line, "MCP3208_CS", 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line for CS\n");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

int read_adc(uint16_t *value) {
    uint8_t tx[3] = {0x06, 0x00, 0x00};
    uint8_t rx[3] = {0};

    gpiod_line_set_value(cs_line, 0);
    int ret = write(spi_fd, tx, sizeof(tx));
    if (ret != sizeof(tx)) {
        perror("Failed to write to SPI device");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    ret = read(spi_fd, rx, sizeof(rx));
    if (ret != sizeof(rx)) {
        perror("Failed to read from SPI device");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    gpiod_line_set_value(cs_line, 1);

    *value = ((rx[0] & 0x0F) << 8) | rx[1];
    return 0;
}

float adc_to_temperature(uint16_t adc_value) {
    float voltage = (float)adc_value * VREF / ADC_MAX_VALUE;
    return (voltage - TEMP_OFFSET) / TEMP_COEFFICIENT;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (init_spi() < 0) {
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

