static int spi_fd;
static struct gpiod_line *cs_line;
static FILE *log_file;

void cleanup(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int ret;
    struct spi_ioc_transfer xfer = {
        .bits_per_word = SPI_BITS_PER_WORD,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI max speed");
        return -1;
    }

    return 0;
}

int init_gpio() {
    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, MCP3208_CS_PIN);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line for CS\n");
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_request_output(cs_line, "MCP3208_CS", 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line for CS\n");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
