}

double voltage_to_acceleration(double voltage) {
    return (voltage - ADXL335_0G_VOLTAGE) / ADXL335_SENSITIVITY;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

