        fprintf(stderr, "Failed to set mode for CS pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(CS_PIN, PI_HIGH);

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    unsigned char spi_buf[3];
    int adc_values[3];
    double accelerations[3];
    double magnitude;
    time_t now;
    struct tm *timeinfo;
    char timestamp[26];

    while (1) {
        for (int i = 0; i < 3; i++) {
            spi_buf[0] = 0x01;
            spi_buf[1] = (i << 4) | 0x08;
            spi_buf[2] = 0x00;

            gpioWrite(CS_PIN, PI_LOW);
            int count = spiXfer(spi_handle, spi_buf, spi_buf, 3);
            gpioWrite(CS_PIN, PI_HIGH);

            if (count < 0) {
                fprintf(stderr, "SPI transfer failed\n");
                signal_handler(SIGINT);
            }

            adc_values[i] = ((spi_buf[1] & 0x03) << 8) | spi_buf[2];
            if (adc_values[i] < 0 || adc_values[i] > ADC_MAX) {
                fprintf(stderr, "ADC read out of range\n");
                signal_handler(SIGINT);
            }

            accelerations[i] = voltage_to_acceleration(adc_to_voltage(adc_values[i]));
        }

        magnitude = sqrt(accelerations[0] * accelerations[0] +
                         accelerations[1] * accelerations[1] +
                         accelerations[2] * accelerations[2]);

        time(&now);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%d,%d,%d,%.2f", timestamp, adc_values[0], adc_values[1], adc_values[2], magnitude);
        if (magnitude > IMPACT_THRESHOLD) {
            fprintf(log_file, ",IMPACT DETECTED");
        }
        fprintf(log_file, "\n");
        fflush(log_file);

        time_sleep(0.01); // Sleep for 100 Hz
    }

    signal_handler(SIGINT);
    return EXIT_SUCCESS;
}

