#define CMD_REG 0xC0
#define FIFO_REG 0xC1
#define LOG_FILE "biometric_log.csv"

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    FILE *log_file;
    int i2c_handle, ret;
    unsigned char cmd, fifo_data[8];
    time_t raw_time;
    struct tm *time_info;
    char time_str[26];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "Timestamp,HR (bpm),SpO2 (%%),Error Flag\n");
    fflush(log_file);

    signal(SIGINT, signal_handler);

    while (keep_running) {
        // Trigger measurement
        cmd = 0x01; // Start measurement command
        ret = i2cWriteByteData(i2c_handle, CMD_REG, cmd);
        if (ret < 0) {
            fprintf(stderr, "Failed to write command to sensor\n");
            ret = 2; // Sensor absent/uninitialized
        } else {
            // Read FIFO data
            ret = i2cReadI2CBlock(i2c_handle, FIFO_REG, fifo_data, 8);
            if (ret < 0) {
                fprintf(stderr, "Failed to read FIFO data\n");
                ret = 1; // Read error
            } else {
                // Extract IR and RED values (16-bit each)
                unsigned int ir_value = (fifo_data[0] << 8) | fifo_data[1];
                unsigned int red_value = (fifo_data[2] << 8) | fifo_data[3];

                // Log data
                time(&raw_time);
                time_info = localtime(&raw_time);
                strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);

                // Note: This is a placeholder. Actual HR/SpO2 calculation is not implemented.
                fprintf(log_file, "%s,%u,%u,%d\n", time_str, ir_value, red_value, 0);
                fflush(log_file);

                ret = 0; // OK
            }
        }

        // Log error if occurred
        if (ret != 0) {
            time(&raw_time);
            time_info = localtime(&raw_time);
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);
            fprintf(log_file, "%s,,,%d\n", time_str, ret);
            fflush(log_file);
        }

        sleep(1); // Sample once per second
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

