#include <time.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_COMMAND 0x01
#define ADC_FULL_SCALE 1023
#define FLOW_MIN 0.0
#define FLOW_MAX 5.0
#define LOG_FILE "flow_log.csv"

static int spi_handle;
static FILE *log_file;

void cleanup(int sig) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int read_adc() {
    char buf[3];
    int count;

    buf[0] = 0x01;
    buf[1] = 0x80;
    buf[2] = 0x00;

    count = spiXfer(SPI_CHANNEL, buf, buf, 3);
    if (count < 0) {
        fprintf(stderr, "SPI transfer error: %s\n", strerror(errno));
        return -1;
    }

    return ((buf[1] & 0x03) << 8) | buf[2];
}

double adc_to_flow(int adc_value) {
    if (adc_value == 0 || adc_value == ADC_FULL_SCALE) {
        fprintf(stderr, "Sensor absent or malfunctioning\n");
        return -1;
    }
    return (double)adc_value / ADC_FULL_SCALE * FLOW_MAX;
}

int main() {
    struct timespec ts;
    struct tm *tm_info;
    char timestamp[30];
    double flow_rate;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            continue;
        }

        flow_rate = adc_to_flow(adc_value);
        if (flow_rate < 0 || flow_rate > FLOW_MAX) {
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        tm_info = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(log_file, "%s.%06ld,%.2f\n", timestamp, ts.tv_nsec / 1000, flow_rate);
        fflush(log_file);

        gpioSleep(Time_Relative, 1, 0);
    }

    return EXIT_SUCCESS;
}

