#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_COMMAND 0x01
#define BUFFER_SIZE 1024

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    int adc_value;

    tx[0] = 0x01;
    tx[1] = (MCP3008_COMMAND << 4) | (channel & 0x07);
    tx[2] = 0x00;

    if (spiXfer(SPI_CHANNEL, tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <gain>\n", argv[0]);
        return EXIT_FAILURE;
    }

    float gain = atof(argv[1]);
    if (gain <= 0) {
        fprintf(stderr, "Invalid gain value\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    int mic1, mic2;
    int i;

    printf("Time,Channel1,Channel2,Difference\n");

    for (i = 0; keep_running && i < BUFFER_SIZE; i++) {
        mic1 = read_adc(0);
        if (mic1 < 0) {
            fprintf(stderr, "Error reading from microphone 1\n");
            break;
        }

        mic2 = read_adc(1);
        if (mic2 < 0) {
            fprintf(stderr, "Error reading from microphone 2\n");
            break;
        }

        int diff = (int)((mic1 - mic2) * gain);
        printf("%d,%d,%d,%d\n", i, mic1, mic2, diff);
        fflush(stdout);

        gpioDelay(1000);  // 1ms delay
    }

    spiClose(SPI_CHANNEL);
    gpioTerminate();

    return EXIT_SUCCESS;
}

