    }

    if (gpioSetMode(SPI_CHANNEL, PI_SPI) != 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetSPISpeed(SPI_CHANNEL, SPI_SPEED) != 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        adc_command[0] = 0x01;
        adc_command[1] = 0x80;
        adc_command[2] = 0x00;

        if (gpioSPIXfer(SPI_CHANNEL, adc_command, adc_result, 3) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            break;
        }

        adc_value = ((adc_result[0] & 0x03) << 8) | adc_result[1];

        if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
