        if (fprintf(log_file, "%s,%d\n", timestamp, adc_value) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
            break;
        }

        fflush(log_file);
        time_sleep(1);
        time_sleep(SAMPLE_INTERVAL - 1);
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

