#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define BUZZER_PIN 18
#define FLAME_THRESHOLD_VOLTAGE 1.0
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL_MS 500

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

float read_ambient_temperature() {
    FILE *file = fopen("ambient_temp.txt", "r");
    if (!file) {
        return 25.0;
    }

    float temp;
    if (fscanf(file, "%f", &temp) != 1) {
        temp = 25.0;
    }

    fclose(file);
    return temp;
}

int spi_transfer(int fd, unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    return ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
}

int main() {
    int spi_fd, buzzer_fd;
    struct gpiod_line *buzzer_line;
    struct gpiod_chip *chip;
    unsigned char tx[3], rx[3];
    FILE *log_file;
    time_t raw_time;
    struct tm *time_info;
    char time_str[20];
    float ambient_temp, voltage, compensated_voltage;
    int adc_value, retry_count;
    int flame_detected;

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode and speed
    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000) < 0) {
        perror("Failed to set SPI mode/speed");
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        return 1;
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(spi_fd);
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to get buzzer GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Failed to request buzzer GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(buzzer_line);
        fclose(log_file);
        close(spi_fd);
        return 1;
    }

    ambient_temp = read_ambient_temperature();

    while (keep_running) {
        retry_count = 0;
        do {
            tx[0] = 0x01;
            tx[1] = 0x80;
            tx[2] = 0x00;

            if (spi_transfer(spi_fd, tx, rx, 3) < 0) {
                fprintf(stderr, "SPI transfer failed\n");
                fprintf(log_file, "SPI transfer failed\n");
                gpiod_line_set_value(buzzer_line, 0);
                usleep(SAMPLE_INTERVAL_MS * 1000);
                continue;
            }

            adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            retry_count++;
        } while (adc_value < 0 || adc_value > 1023 && retry_count < RETRY_COUNT);

        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "ADC value out of range: %d\n", adc_value);
            fprintf(log_file, "ADC value out of range: %d\n", adc_value);
            gpiod_line_set_value(buzzer_line, 0);
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        voltage = adc_value * (3.3 / 1023.0);
        compensated_voltage = voltage + (ambient_temp - 25.0) * 0.001;
        flame_detected = compensated_voltage > FLAME_THRESHOLD_VOLTAGE;

        time(&raw_time);
        time_info = localtime(&raw_time);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);

        fprintf(log_file, "%s,%d,%.3f,%.3f,%.1f,%d\n",
                time_str, adc_value, voltage, compensated_voltage, ambient_temp, flame_detected);
        fflush(log_file);

        gpiod_line_set_value(buzzer_line, flame_detected);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Clean up
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    close(spi_fd);

    return 0;
