#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define WATER_LEVEL_PIN 17
#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023
#define WATER_LEVEL_THRESHOLD_HIGH 75
#define WATER_LEVEL_THRESHOLD_LOW 70
#define JSON_FILE "water_levels.json"
#define READ_INTERVAL_MS 5000
#define SPI_TRANSFER_SIZE 3
#define SIG_CLEANUP_HANDLER(signum) \
    void sig_##signum##_handler(int signum) { \
        running = 0; \
    }

static volatile int running = 1;
SIG_CLEANUP_HANDLER(int)
SIG_CLEANUP_HANDLER(term)

void log_water_level(int water_level) {
    FILE *file = fopen(JSON_FILE, "a");
    if (!file) {
        pigpio_error("Failed to open JSON file for writing");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(file, "{\"timestamp\":\"%s.%03ld\",\"water_level\":%d}",
            timestamp, (long)(tm_info->tm_usec / 1000), water_level);

    if (ftell(file) > 1) {
        fputs(",", file);
    }
    fflush(file);
    fclose(file);
}

int read_adc(int channel) {
    unsigned char tx[SPI_TRANSFER_SIZE] = {0x01, 0x80 | (channel << 4), 0x00};
    unsigned char rx[SPI_TRANSFER_SIZE] = {0};

    if (spiXfer(SPI_CHANNEL, tx, rx, SPI_TRANSFER_SIZE) < 0) {
        pigpio_error("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main() {
    if (gpioInitialise() < 0) {
        pigpio_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(WATER_LEVEL_PIN, PI_OUTPUT) < 0) {
        pigpio_error("Failed to set mode for LED pin");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(WATER_LEVEL_PIN, PI_PUD_OFF) < 0) {
        pigpio_error("Failed to set pull-up/down for LED pin");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS) < 0) {
        pigpio_error("Failed to open SPI channel");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_int_handler);
    signal(SIGTERM, sig_term_handler);

    FILE *json_file = fopen(JSON_FILE, "a");
    if (!json_file) {
        pigpio_error("Failed to open JSON file");
        spiClose(SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fseek(json_file, 0, SEEK_END) != 0 || ftell(json_file) == 0) {
        fputs("[", json_file);
    }
    fflush(json_file);

    int last_led_state = -1;

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value >= 0) {
            int water_level = (adc_value * 100) / ADC_MAX_VALUE;
            printf("Water Level: %d%%\n", water_level);
            log_water_level(water_level);

            int led_state = (water_level > WATER_LEVEL_THRESHOLD_HIGH) ? 1 : 0;
            if (led_state != last_led_state) {
                if (gpioWrite(WATER_LEVEL_PIN, led_state) < 0) {
                    pigpio_error("Failed to write to LED pin");
                }
                last_led_state = led_state;
            }
        }

        gpioDelay(READ_INTERVAL_MS * 1000);
    }

    fputs("\n]", json_file);
    fclose(json_file);

    if (gpioWrite(WATER_LEVEL_PIN, 0) < 0) {
        pigpio_error("Failed to turn off LED pin");
    }

    spiClose(SPI_CHANNEL);
    gpioTerminate();

    return EXIT_SUCCESS;
}

