#define DEFAULT_MIN_CALIBRATION 300
#define DEFAULT_MAX_CALIBRATION 700
#define DEFAULT_MOISTURE_THRESHOLD 30
#define DEFAULT_LOG_FREQUENCY 60

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

double calculate_moisture_percent(int raw_value, int min_calibration, int max_calibration) {
    if (raw_value <= min_calibration) return 100.0;
    if (raw_value >= max_calibration) return 0.0;
    return 100.0 * (max_calibration - raw_value) / (double)(max_calibration - min_calibration);
}

void send_email_alert(const char *recipient, const char *email_body, const char *msmtp_config) {
    char command[256];
    snprintf(command, sizeof(command), "MSMTP_CONFIGFILE=%s msmtp -C %s %s < %s", msmtp_config, msmtp_config, recipient, email_body);

    FILE *fp = popen(command, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open pipe to msmtp\n");
        return;
    }

    int status = pclose(fp);
    if (status != 0) {
        fprintf(stderr, "Email alert failed with status %d\n", status);
    }
}

int main(int argc, char *argv[]) {
    int spi_channel = DEFAULT_SPI_CHANNEL;
    int adc_channel = DEFAULT_ADC_CHANNEL;
    int min_calibration = DEFAULT_MIN_CALIBRATION;
    int max_calibration = DEFAULT_MAX_CALIBRATION;
    int moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
    int log_frequency = DEFAULT_LOG_FREQUENCY;
    const char *recipient_email = NULL;
    const char *msmtp_config = NULL;

    if (argc < 8) {
        fprintf(stderr, "Usage: %s <spi_channel> <adc_channel> <min_calibration> <max_calibration> <moisture_threshold> <log_frequency> <recipient_email> <msmtp_config>\n", argv[0]);
        return EXIT_FAILURE;
    }

    spi_channel = atoi(argv[1]);
    adc_channel = atoi(argv[2]);
    min_calibration = atoi(argv[3]);
    max_calibration = atoi(argv[4]);
    moisture_threshold = atoi(argv[5]);
    log_frequency = atoi(argv[6]);
    recipient_email = argv[7];
    msmtp_config = argv[8];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(spi_channel, PI_SPI) != 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSPIOpen(spi_channel, 500000, 0) < 0) {
        fprintf(stderr, "Failed to open SPI connection\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen("plant_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioSPIClose(spi_channel);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    time_t last_log_time = time(NULL);
    char email_body[256];

    while (keep_running) {
        unsigned char tx[3] = {1, (1 + adc_channel) << 4, 0};
        unsigned char rx[3] = {0};

        if (gpioSPIDataRW(spi_channel, tx, 3) < 3) {
            fprintf(stderr, "Failed to read from ADC\n");
