            int raw_adc = ((rx[1] & 0x03) << 8) + rx[2];
            double moisture_percent = calculate_moisture_percent(raw_adc, min_calibration, max_calibration);

            time_t current_time = time(NULL);
            if (current_time - last_log_time >= log_frequency) {
                struct tm *timeinfo = localtime(&current_time);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percent);
                fflush(log_file);

                last_log_time = current_time;

                if (moisture_percent < moisture_threshold) {
                    snprintf(email_body, sizeof(email_body), "Alert: Soil moisture is below threshold! Current moisture: %.2f%%", moisture_percent);
                    send_email_alert(recipient_email, email_body, msmtp_config);
                }
            }
        }

        time_t sleep_time = log_frequency - (time(NULL) - last_log_time);
        if (sleep_time > 0) {
            sleep(sleep_time);
        }
    }

    fclose(log_file);
    gpioSPIClose(spi_channel);
    gpioTerminate();

    return EXIT_SUCCESS;
}

