#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>

#define SPI_CHANNEL 0
#define CE_PIN 8
#define MISO_PIN 9
#define MOSI_PIN 10
#define SCLK_PIN 11

#define ADC_MIN 0
#define ADC_MAX 1023
#define ADC_VOLTAGE_MIN 0.0
#define ADC_VOLTAGE_MAX 3.3
#define PRESSURE_MIN 10.0
#define PRESSURE_MAX 150.0
#define VOLTAGE_MIN 0.5
#define VOLTAGE_MAX 4.5

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

double adc_to_voltage(int adc_value) {
    return (double)adc_value * (ADC_VOLTAGE_MAX - ADC_VOLTAGE_MIN) / (ADC_MAX - ADC_MIN) + ADC_VOLTAGE_MIN;
}

double voltage_to_pressure(double voltage) {
    return (voltage - VOLTAGE_MIN) * (PRESSURE_MAX - PRESSURE_MIN) / (VOLTAGE_MAX - VOLTAGE_MIN) + PRESSURE_MIN;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(CE_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MISO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(MOSI_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(SCLK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "GPIO mode setting failed\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        gpioWrite(CE_PIN, PI_LOW);
        gpioSleep(PI_TIME_RELATIVE, 0, 500000);  // 0.5 second delay
        gpioWrite(CE_PIN, PI_HIGH);

        unsigned char tx[3] = {0x01, 0x80, 0x00};
        unsigned char rx[3] = {0};

        if (gpioSPIxfer(SPI_CHANNEL, tx, rx, 3) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        int adc_value = ((rx[0] & 0x03) << 8) | rx[1];

        if (adc_value < ADC_MIN || adc_value > ADC_MAX) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        double voltage = adc_to_voltage(adc_value);

        if (voltage <= ADC_VOLTAGE_MIN || voltage >= ADC_VOLTAGE_MAX) {
            fprintf(stderr, "Sensor absent or stuck at %fV\n", voltage);
            continue;
        }

        double pressure = voltage_to_pressure(voltage);

        time_t now;
        struct tm *tm_info;
        char timestamp[64];

        time(&now);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

        printf("%s, Pressure: %.2f kPa\n", timestamp, pressure);
    }

    gpioTerminate();
    return 0;
}

