#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <spi/spi.h>

#define CHIP "/dev/gpiochip0"
#define CE_PIN 8
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define MIN_ADC_VALUE 300
#define MAX_ADC_VALUE 700
#define READ_INTERVAL 5

static int keep_running = 1;
static struct spi_ioc_transfer xfer;
static int spi_fd;
static struct gpiod_line *ce_line;

void signal_handler(int signum) {
    keep_running = 0;
}

int setup_spi() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_adc(int channel) {
    unsigned char tx[3] = {1, (8 + channel) << 4, 0};
    unsigned char rx[3] = {0};

    xfer.tx_buf = (unsigned long)tx;
    xfer.rx_buf = (unsigned long)rx;
    xfer.len = 3;
    xfer.delay_usecs = 0;
    xfer.speed_hz = SPI_SPEED;
    xfer.bits_per_word = 8;
    xfer.cs_change = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) + rx[2];
}

float adc_to_moisture(int adc_value) {
    if (adc_value <= MIN_ADC_VALUE) return 100.0;
    if (adc_value >= MAX_ADC_VALUE) return 0.0;
    return 100.0 - ((float)(adc_value - MIN_ADC_VALUE) / (MAX_ADC_VALUE - MIN_ADC_VALUE)) * 100.0;
}

int setup_gpio() {
    struct gpiod_chip *chip = gpiod_chip_open(CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    ce_line = gpiod_chip_get_line(chip, CE_PIN);
    if (!ce_line) {
        perror("Failed to get CE line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(ce_line, "SPI_CE0", 1) < 0) {
        perror("Failed to request CE line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

void cleanup() {
    if (ce_line) {
        gpiod_line_release(ce_line);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

int main() {
    if (setup_gpio() < 0 || setup_spi() < 0) {
        fprintf(stderr, "Failed to initialize hardware\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        gpiod_line_set_value(ce_line, 0);
        int adc_value = read_adc(0);
        gpiod_line_set_value(ce_line, 1);

        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC\n");
            sleep(READ_INTERVAL);
            continue;
        }

        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Warning: ADC value at extremes, possible wiring issue\n");
        }

        float moisture = adc_to_moisture(adc_value);
        time_t now = time(NULL);
        printf("%s, ADC: %d, Moisture: %.2f%%\n", ctime(&now), adc_value, moisture);

        sleep(READ_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

