#define SPI_DEVICE "/dev/spidev0.0"
#define CHIP_SELECT_PIN 8
#define NUM_SENSORS 4
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define VREF 3.3

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int setup_spi(int *spi_fd) {
    *spi_fd = open(SPI_DEVICE, O_RDWR);
    if (*spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int mode = SPI_MODE;
    if (ioctl(*spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(*spi_fd);
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(*spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(*spi_fd);
        return -1;
    }

    return 0;
}

int read_adc(int spi_fd, int channel) {
    unsigned char tx[3] = {
        0x01,
        (channel << 4) | 0x00,
        0x00
    };
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int spi_fd;
    FILE *file;
    struct timespec ts;
    struct tm *tm_info;
    char timestamp[64];

    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return 1;
    }

    // Set up SPI
    if (setup_spi(&spi_fd) < 0) {
        return 1;
    }

    // Set up GPIO for chip select
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }

    line = gpiod_chip_get_line(chip, CHIP_SELECT_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(line, "MCP3008_CS", 1) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Open CSV file
    file = fopen("environmental_data.csv", "w");
    if (!file) {
        perror("Failed to open CSV file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    fprintf(file, "Timestamp,Sensor0,Sensor1,Sensor2,Sensor3\n");

    while (keep_running) {
        int adc_values[NUM_SENSORS] = {0};

        // Deselect the ADC
        gpiod_line_set_value(line, 1);

        for (int i = 0; i < NUM_SENSORS; i++) {
            // Select the ADC
            gpiod_line_set_value(line, 0);

            adc_values[i] = read_adc(spi_fd, i);
            if (adc_values[i] < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
                keep_running = 0;
                break;
            }

            // Deselect the ADC
            gpiod_line_set_value(line, 1);

            usleep(1000); // Small delay between sensor readings
        }

        if (keep_running) {
            // Get current time
            clock_gettime(CLOCK_REALTIME, &ts);
            tm_info = localtime(&ts.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            // Write to CSV
            fprintf(file, "%s,%.3f,%.3f,%.3f,%.3f\n",
                    timestamp,
                    adc_values[0] * VREF / 1023.0,
                    adc_values[1] * VREF / 1023.0,
                    adc_values[2] * VREF / 1023.0,
                    adc_values[3] * VREF / 1023.0);

            fflush(file);
            sleep(1); // Wait for 1 second before next reading
        }
    }

    // Clean up
    fclose(file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

