#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <string.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MOISTURE_LOW_THRESHOLD 300
#define MOISTURE_HIGH_THRESHOLD 600
#define SAMPLE_INTERVAL_MS 5000
#define BUFFER_SIZE 20

typedef struct {
    time_t timestamp;
    uint16_t moisture_level;
    int pump_state;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int log_index = 0;
int buffer_full = 0;

int spi_fd;
int pump_gpio = 17;

void log_event(uint16_t moisture_level, int pump_state) {
    time_t now = time(NULL);
    log_buffer[log_index].timestamp = now;
    log_buffer[log_index].moisture_level = moisture_level;
    log_buffer[log_index].pump_state = pump_state;

    log_index = (log_index + 1) % BUFFER_SIZE;
    if (log_index == 0) {
        buffer_full = 1;
    }
}

void print_log_buffer() {
    printf("Timestamp\tMoisture\tPump State\n");
    for (int i = 0; i < (buffer_full ? BUFFER_SIZE : log_index); i++) {
        int idx = (log_index - 1 - i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("%ld\t\t%d\t\t%d\n", 
               log_buffer[idx].timestamp, 
               log_buffer[idx].moisture_level, 
               log_buffer[idx].pump_state);
    }
}

void cleanup(int signum) {
    gpioSetMode(pump_gpio, PI_INPUT);
    gpioWrite(pump_gpio, PI_LOW);
    gpioTerminate();
    close(spi_fd);
    exit(0);
}

void sample_moisture() {
    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3] = {0};
    int retry_count = 3;

    while (retry_count > 0) {
        if (spiXfer(SPI_CHANNEL, tx, rx, 3) == 3) {
            uint16_t adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            int pump_state = gpioRead(pump_gpio);

            if (adc_value < MOISTURE_LOW_THRESHOLD) {
                if (pump_state == PI_LOW) {
                    gpioWrite(pump_gpio, PI_HIGH);
                    log_event(adc_value, 1);
                }
            } else if (adc_value > MOISTURE_HIGH_THRESHOLD) {
                if (pump_state == PI_HIGH) {
                    gpioWrite(pump_gpio, PI_LOW);
                    log_event(adc_value, 0);
                }
            } else {
                log_event(adc_value, pump_state);
            }

            print_log_buffer();
            break;
        }
        retry_count--;
    }

    if (retry_count == 0) {
        fprintf(stderr, "SPI transfer failed after 3 attempts\n");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if ((spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0)) < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(pump_gpio, PI_OUTPUT);
    gpioWrite(pump_gpio, PI_LOW);

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (gpioSetTimerFunc(SAMPLE_INTERVAL_MS, sample_moisture) < 0) {
        fprintf(stderr, "Failed to set timer function\n");
        cleanup(0);
    }

    while (1) {
        time_sleep(1);
    }

    return 0;
}

