            if (adc_value < MOISTURE_LOW_THRESHOLD) {
                if (pump_state == PI_LOW) {
                    gpioWrite(pump_gpio, PI_HIGH);
                    log_event(adc_value, 1);
                }
            } else if (adc_value > MOISTURE_HIGH_THRESHOLD) {
                if (pump_state == PI_HIGH) {
                    gpioWrite(pump_gpio, PI_LOW);
                    log_event(adc_value, 0);
                }
            } else {
                log_event(adc_value, pump_state);
            }

            print_log_buffer();
            break;
        }
        retry_count--;
    }

    if (retry_count == 0) {
        fprintf(stderr, "SPI transfer failed after 3 attempts\n");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if ((spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0)) < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(pump_gpio, PI_OUTPUT);
    gpioWrite(pump_gpio, PI_LOW);

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (gpioSetTimerFunc(SAMPLE_INTERVAL_MS, sample_moisture) < 0) {
        fprintf(stderr, "Failed to set timer function\n");
        cleanup(0);
    }

    while (1) {
        time_sleep(1);
    }

    return 0;
}
