                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
                fprintf(logFile, "[%s] SpO2: %.2f%% HR: %.0f BPM\n", timestamp, spo2, hr);
                fflush(logFile);
            }
        }

        time_sleep(1);
    }

    return EXIT_SUCCESS;
}

