#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_SPEED 1000000
#define VREF 3.3
#define NUM_CHANNELS 3
#define LOG_INTERVAL_MS 500

static int spi_handle;
static FILE *log_file;

void cleanup(int signum) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (gpioInitialised()) {
        gpioTerminate();
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        return -1;
    }

    unsigned char tx[3] = {0x01, (channel << 4) & 0x70, 0x00};
    unsigned char rx[3] = {0};
    int retry_count = 3;

    while (retry_count > 0) {
        int result = spiXfer(SPI_CHANNEL, tx, rx, 3);
        if (result < 0) {
            retry_count--;
            gpioDelay(100000); // 100ms delay before retry
        } else {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
    }

    return -1; // Return -1 if all retries fail
}

void log_voltage(int channel, float voltage) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(log_file, "%s,%d,%.3f\n", timestamp, channel, voltage);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_CE, SPI_SPEED);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("analog_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Channel,Voltage\n");
    fflush(log_file);

    signal(SIGINT, cleanup);

    while (1) {
        for (int channel = 0; channel < NUM_CHANNELS; channel++) {
            int adc_value = read_adc(channel);
            if (adc_value >= 0) {
                float voltage = (adc_value * VREF) / 1023.0;
                log_voltage(channel, voltage);
            } else {
                fprintf(stderr, "Failed to read ADC channel %d\n", channel);
            }
        }
        gpioDelay(LOG_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

