#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADC_CONFIG 0x01
#define ADC_CONVERSION 0x00
#define BASELINE_SAMPLES 10
#define BASELINE_DELAY_MS 50
#define POLL_INTERVAL_MS 200
#define RELAY_PIN 17
#define DOOR_SENSOR_PIN 27
#define THRESHOLD_MULTIPLIER 0.8
#define RELAY_DURATION_MS 3000
#define LOG_FILE "/var/log/door_events.log"

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static struct gpiod_line *door_sensor_line;

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(log_file, "[%s.%03ld] %s\n", timestamp, (long)(now * 1000 % 1000), message);
        fclose(log_file);
    }
}

int read_adc(int channel) {
    uint16_t config = (1 << 15) | (channel << 12) | (1 << 11) | (1 << 9); // AINx, 128SPS, continuous
    char buf[3];
    buf[0] = ADC_CONFIG;
    buf[1] = config >> 8;
    buf[2] = config & 0xFF;

    if (write(i2c_fd, buf, 3) != 3) {
        log_event("Failed to write to ADS1115");
        return -1;
    }

    usleep(10000); // Wait for conversion

    buf[0] = ADC_CONVERSION;
    if (write(i2c_fd, buf, 1) != 1) {
        log_event("Failed to request ADC conversion");
        return -1;
    }

    if (read(i2c_fd, buf, 2) != 2) {
        log_event("Failed to read ADC conversion");
        return -1;
    }

    return (buf[0] << 4) | (buf[1] >> 4);
}

void setup_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(relay_line, "relay_control", 0) < 0) {
        fprintf(stderr, "Failed to request relay line as output\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    door_sensor_line = gpiod_chip_get_line(chip, DOOR_SENSOR_PIN);
    if (!door_sensor_line) {
        fprintf(stderr, "Failed to get door sensor line\n");
        gpiod_line_release(relay_line);
