int read_adc(int channel) {
    uint16_t config = (1 << 15) | (channel << 12) | (1 << 11) | (1 << 9); // AINx, 128SPS, continuous
    char buf[3];
    buf[0] = ADC_CONFIG;
    buf[1] = config >> 8;
    buf[2] = config & 0xFF;

    if (write(i2c_fd, buf, 3) != 3) {
        log_event("Failed to write to ADS1115");
        return -1;
    }

    usleep(10000); // Wait for conversion

    buf[0] = ADC_CONVERSION;
    if (write(i2c_fd, buf, 1) != 1) {
        log_event("Failed to request ADC conversion");
        return -1;
    }

    if (read(i2c_fd, buf, 2) != 2) {
        log_event("Failed to read ADC conversion");
        return -1;
    }

    return (buf[0] << 4) | (buf[1] >> 4);
