#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>

#define RELAY_PIN 18
#define MCP3008_SPI_CHANNEL 0
#define MCP3008_SPI_CE 8
#define MCP3008_SPI_CLOCK 1000000
#define MCP3008_SPI_MODE 0
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define DRY_RAW 200
#define WET_RAW 800

static volatile int keep_running = 1;
static int threshold = DEFAULT_THRESHOLD;
static int duration_seconds = DEFAULT_DURATION;
static int sleep_interval = DEFAULT_SLEEP_INTERVAL;

void log_message(const char *message) {
    FILE *log_file = fopen("irrigation.log", "a");
    if (log_file) {
        time_t now = time(NULL);
        char *time_str = ctime(&now);
        time_str[strlen(time_str) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] %s\n", time_str, message);
        fclose(log_file);
    }
}

int read_adc(int channel) {
    unsigned char buf[3];
    int adc_value = -1;
    int retries = 3;

    while (retries > 0 && adc_value == -1) {
        buf[0] = 0x01;
        buf[1] = (channel << 4) | 0x00;
        buf[2] = 0x00;

        int count = spiXfer(MCP3008_SPI_CE, buf, buf, 3);
        if (count == 3) {
            adc_value = ((buf[0] & 0x03) << 8) | buf[1];
        } else {
            retries--;
            log_message("SPI read failed, retrying...");
        }
    }

    if (adc_value == -1) {
        log_message("SPI read failed after retries.");
    }

    return adc_value;
}

int adc_to_moisture(int adc_value) {
    if (adc_value <= DRY_RAW) return 100;
    if (adc_value >= WET_RAW) return 0;
    return (int)((100.0 * (WET_RAW - adc_value)) / (WET_RAW - DRY_RAW));
}

void pump_control(int on) {
    gpioWrite(RELAY_PIN, on ? 1 : 0);
    log_message(on ? "Pump activated" : "Pump deactivated");
}

void signal_handler(int signo) {
    keep_running = 0;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't': threshold = atoi(optarg); break;
            case 'd': duration_seconds = atoi(optarg); break;
            case 's': sleep_interval = atoi(optarg); break;
            default: fprintf(stderr, "Usage: %s [-t threshold] [-d duration_seconds] [-s sleep_interval]\n", argv[0]); exit(EXIT_FAILURE);
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for RELAY_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MCP3008_SPI_CE, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for MCP3008_SPI_CE\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(MCP3008_SPI_CE, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set pull-up/down for MCP3008_SPI_CE\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (spiOpen(MCP3008_SPI_CE, MCP3008_SPI_CLOCK, MCP3008_SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    pump_control(0); // Ensure pump is off at start

    while (keep_running) {
        int adc_value = read_adc(MCP3008_SPI_CHANNEL);
        if (adc_value != -1) {
            int moisture = adc_to_moisture(adc_value);
            char message[100];
            snprintf(message, sizeof(message), "Moisture: %d%% (ADC: %d)", moisture, adc_value);
            log_message(message);

            if (moisture < threshold) {
                pump_control(1);
                time_t start_time = time(NULL);
                while (time(NULL) - start_time < duration_seconds && keep_running) {
                    gpioDelay(100000); // 100ms delay
                }
                pump_control(0);
            }
        }

        time_t sleep_start = time(NULL);
        while (time(NULL) - sleep_start < sleep_interval && keep_running) {
            gpioDelay(100000); // 100ms delay
        }
    }

    pump_control(0); // Ensure pump is off on exit
    spiClose(MCP3008_SPI_CE);
    gpioTerminate();
    return EXIT_SUCCESS;
}

