#include <time.h>
#include <errno.h>
#include <string.h>

#define SPI_CHANNEL 0
#define CE_PIN 8
#define CLK_PIN 11
#define MOSI_PIN 10
#define MISO_PIN 9
#define SAMPLE_INTERVAL_MS 10
#define EMA_ALPHA 0.1
#define THRESHOLD_MULTIPLIER 1.2

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(CE_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(CLK_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOSI_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MISO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioHardwareSPI(SPI_CHANNEL, 500000, 0, 0, 0) < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("/var/log/sound_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float ema = 0.0;
    unsigned char adc_buffer[3];
    adc_buffer[0] = 0x01; // Start bit, single-ended mode
    adc_buffer[1] = 0x80; // MCP3008 channel 0
    adc_buffer[2] = 0x00;

    while (keep_running) {
        gpioWrite(CE_PIN, PI_LOW);
        gpioWrite(CE_PIN, PI_HIGH);

        int count = gpioSPI(SPI_CHANNEL, adc_buffer, 3);
        if (count < 0) {
            fprintf(stderr, "SPI communication failed\n");
            break;
        }

        int adc_value = ((adc_buffer[1] & 0x03) << 8) | adc_buffer[2];

        ema = EMA_ALPHA * adc_value + (1 - EMA_ALPHA) * ema;

        if (adc_value > ema * THRESHOLD_MULTIPLIER) {
            time_t now = time(NULL);
            struct tm *tm_info = gmtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

            fprintf(log_file, "%s, %d\n", timestamp, adc_value);
            fflush(log_file);
        }

        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_MS / 1000, (SAMPLE_INTERVAL_MS % 1000) * 1000);
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

