#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48
#define SAMPLE_INTERVAL_MS 100

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void cleanup(int signum) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_FAILURE);
}

int main() {
    struct i2c_msg messages[2];
    __u8 data[2];
    int ret;

    signal(SIGINT, cleanup);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address for PCF8591
    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, PCF8591_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup(SIGINT);
    }

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup(SIGINT);
    }

    line = gpiod_chip_get_line(chip, 17); // Assuming GPIO 17 is used
    if (!line) {
        perror("Failed to get GPIO line");
        cleanup(SIGINT);
    }

    ret = gpiod_line_request_input(line, "PCF8591_MONITOR");
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        cleanup(SIGINT);
    }

    while (1) {
        // Dummy read
        messages[0].addr = PCF8591_ADDR;
        messages[0].flags = 0;
        messages[0].len = 1;
        messages[0].buf = data;

        // Read current sample
        messages[1].addr = PCF8591_ADDR;
        messages[1].flags = I2C_M_RD;
        messages[1].len = 1;
        messages[1].buf = data + 1;

        ret = ioctl(i2c_fd, I2C_RDWR, messages);
        if (ret < 0) {
            perror("Failed to perform I2C transaction");
            cleanup(SIGINT);
        }

        printf("Sample: %d\n", data[1]);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    return 0;
}

