#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

#define I2C_BUS 1
#define ADS1115_ADDRESS 0x48
#define SS49E_VOLTAGE_ZERO 2.5
#define SS49E_SENSITIVITY 0.0014
#define BUFFER_SIZE 10
#define THRESHOLD_GAUSS 500.0

typedef struct {
    float values[BUFFER_SIZE];
    int index;
    int count;
} CircularBuffer;

static volatile int keep_running = 1;
static CircularBuffer buffer = { .index = 0, .count = 0 };

void signal_handler(int signum) {
    keep_running = 0;
}

float convert_voltage_to_gauss(float voltage) {
    return (voltage - SS49E_VOLTAGE_ZERO) / SS49E_SENSITIVITY;
}

void add_to_buffer(CircularBuffer *buffer, float value) {
    buffer->values[buffer->index] = value;
    buffer->index = (buffer->index + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

float calculate_average(CircularBuffer *buffer) {
    float sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->values[i];
    }
    return sum / buffer->count;
}

int main() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    if (setlogmask(LOG_UPTO(LOG_INFO)) == -1) {
        syslog(LOG_ERR, "Failed to set log mask");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    openlog("ss49e_monitor", LOG_CONS | LOG_PID | LOG_NDELAY, LOG_USER);

    gpioSetMode(27, PI_OUTPUT);
    gpioWrite(27, PI_LOW);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDRESS, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C handle");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    uint16_t config = 0xC3E3; // Single-shot mode, AIN0, 128SPS, Vcc/2 gain
    i2cWriteWordData(i2c_handle, 1, config);

    while (keep_running) {
        i2cWriteWordData(i2c_handle, 1, config);
        usleep(8000); // Wait for conversion to complete

        uint16_t raw_adc = i2cReadWordData(i2c_handle, 0);
        float voltage = (raw_adc * 3.3) / 32767.0;

        if (voltage < 0.0 || voltage > 3.3) {
            syslog(LOG_WARNING, "Invalid voltage reading: %.3f V", voltage);
            continue;
        }

        float gauss = convert_voltage_to_gauss(voltage);
        add_to_buffer(&buffer, gauss);

        syslog(LOG_INFO, "Voltage: %.3f V, Field: %.2f Gauss", voltage, gauss);

        if (buffer.count == BUFFER_SIZE) {
            float average = calculate_average(&buffer);
            syslog(LOG_INFO, "Rolling average: %.2f Gauss", average);

            if (average > THRESHOLD_GAUSS) {
                gpioWrite(27, PI_HIGH);
                syslog(LOG_WARNING, "Threshold exceeded: %.2f Gauss", average);
            } else {
                gpioWrite(27, PI_LOW);
            }
        }

        sleep(1);
    }

    i2cClose(i2c_handle);
    gpioWrite(27, PI_LOW);
    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

