#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_THRESHOLD 300
#define PUMP_PIN 18
#define WATERING_INTERVAL 60
#define PUMP_DURATION 10

static volatile int keep_running = 1;

void signal_handler(int signo) {
    keep_running = 0;
}

void log_event(const char *message) {
    FILE *file = fopen("watering_events.txt", "a");
    if (file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0';  // Remove newline
        fprintf(file, "[%s] %s\n", timestamp, message);
        fclose(file);
    }
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char buf[3];
    buf[0] = 0x01;
    buf[1] = (channel + 0x18) << 4;
    buf[2] = 0x00;

    int count = spiXfer(SPI_CHANNEL, buf, buf, 3);
    if (count < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", spiError());
        return -1;
    }

    int adc_value = ((buf[1] & 0x03) << 8) | buf[2];
    if (adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1;
    }

    return adc_value;
}

void activate_pump() {
    gpioWrite(PUMP_PIN, PI_HIGH);
    time_sleep(PUMP_DURATION);
    gpioWrite(PUMP_PIN, PI_LOW);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(PUMP_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set pump pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(PUMP_PIN, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set pump pin pull-up/down\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(PUMP_PIN, PI_LOW) < 0) {
        fprintf(stderr, "Failed to initialize pump state\n");
        gpioTerminate();
        return 1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
