#include <time.h>

#define ADC_CHANNEL 0
#define PWM_PIN 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PWM_FREQUENCY 1000
#define ADC_MAX_VALUE 1023
#define UPDATE_INTERVAL_MS 100

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI handle initialization failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PWM mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioHardwarePWM(PWM_PIN, PWM_FREQUENCY, 0) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct timespec sleep_time = {0, UPDATE_INTERVAL_MS * 1000000};

    while (keep_running) {
        unsigned char adc_command[3] = {0x01, (ADC_CHANNEL << 4) | 0x01, 0x00};
        unsigned char adc_result[3] = {0};

        int retry_count = 0;
        int transfer_result;

        do {
            transfer_result = spiXfer(spi_handle, adc_command, adc_result, 3);
            if (transfer_result < 0) {
                fprintf(stderr, "SPI transfer error: %d\n", transfer_result);
                retry_count++;
                usleep(1000); // Wait 1ms before retrying
            }
        } while (transfer_result < 0 && retry_count < 5);

        if (transfer_result < 0) {
            fprintf(stderr, "Failed to read ADC after multiple retries\n");
            break;
        }

        int adc_value = ((adc_result[1] & 0x03) << 8) | adc_result[2];
        unsigned int duty_cycle = (unsigned int)((float)adc_value / ADC_MAX_VALUE * 1023);

        if (gpioPWM(PWM_PIN, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            break;
        }

        printf("ADC Value: %d, PWM Duty Cycle: %u\n", adc_value, duty_cycle);

        nanosleep(&sleep_time, NULL);
    }

    gpioSetPWMdutycycle(PWM_PIN, 0);
    gpioSetMode(PWM_PIN, PI_INPUT);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

