#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <getopt.h>

#define I2C_BUS 1
#define ADS1115_ADDRESS 0x48
#define SENSOR_PIN 0
#define LED_PIN 17
#define ADC_CONFIG 0x0123 // Example configuration for ADS1115
#define READ_INTERVAL_MS 100
#define BLINK_DURATION_MS 1000
#define BLINK_INTERVAL_MS 50

static volatile int keep_running = 1;
static float threshold = 100.0;

void signal_handler(int signo) {
    keep_running = 0;
}

int init_i2c() {
    if (i2cOpen(I2C_BUS, ADS1115_ADDRESS) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return -1;
    }
    return 0;
}

int read_adc(int handle) {
    char buf[3];
    if (i2cReadDevice(handle, ADC_CONFIG, buf, 3) < 0) {
        fprintf(stderr, "Failed to read from ADS1115\n");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

float adc_to_gauss(int adc_value) {
    // Convert ADC value to voltage
    float voltage = (adc_value * 4.096) / 32767.0;
    // Convert voltage to Gauss
    return (voltage - 1.65) / 0.001;
}

void blink_led() {
    gpioWrite(LED_PIN, PI_HIGH);
    usleep(BLINK_INTERVAL_MS * 1000);
    gpioWrite(LED_PIN, PI_LOW);
    usleep(BLINK_INTERVAL_MS * 1000);
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_LOW);

    int i2c_handle = init_i2c();
    if (i2c_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        int adc_value = read_adc(i2c_handle);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            break;
        }

        float field_strength = adc_to_gauss(adc_value);
        printf("Magnetic field strength: %.2f Gauss\n", field_strength);

        if (field_strength > threshold) {
            int blink_count = 0;
            while (blink_count < 20 && keep_running) { // 1 second / 50 ms = 20 blinks
                blink_led();
                blink_count++;
            }
        }

        usleep(READ_INTERVAL_MS * 1000);
    }

    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, PI_LOW);
    gpioTerminate();

    return EXIT_SUCCESS;
}

