#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <paho-mqtt/mqtt_client.h>
#include <syslog.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define RELAY_PIN 17
#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_CLIENT_ID "soil_moisture_controller"
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"
#define MQTT_QOS 1
#define MQTT_KEEP_ALIVE_INTERVAL 60

static volatile sig_atomic_t keep_running = 1;
static mqtt_client* mqtt_client_handle = NULL;
static int spi_handle = -1;

void signal_handler(int signal) {
    keep_running = 0;
}

int read_moisture() {
    unsigned char tx[3] = {1, (SPI_CHANNEL << 4) | 0x01, 0};
    unsigned char rx[3] = {0};
    int ret;

    ret = spi_xfer(spi_handle, tx, rx, 3);
    if (ret < 0) {
        syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

void set_relay(int state) {
    int ret = gpioWrite(RELAY_PIN, state);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set relay state: %s", strerror(errno));
    }
}

void mqtt_message_arrived(void* context, struct mqtt_response_publish* message) {
    char* payload = (char*)message->payload.payload;
    int payload_len = message->payload.payloadlen;

    if (strcmp(message->topic_name, MQTT_TOPIC_PUMP_CONTROL) == 0) {
        if (payload_len == 4 && strncmp(payload, "on", 2) == 0) {
            set_relay(1);
        } else if (payload_len == 5 && strncmp(payload, "off", 3) == 0) {
            set_relay(0);
        }
    }
}

int mqtt_connected(void* context, struct mqtt_response_connect* response) {
    int ret;

    ret = mqtt_subscribe(mqtt_client_handle, MQTT_TOPIC_PUMP_CONTROL, MQTT_QOS);
    if (ret != MQTT_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to MQTT topic: %s", MQTT_TOPIC_PUMP_CONTROL);
        return MQTT_FAILURE;
    }

    return MQTT_SUCCESS;
}

int main() {
    int ret;
    int last_moisture = -1;
    struct sigaction sa;

    openlog("soil_moisture_controller", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    set_relay(0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "Failed to open SPI device: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mqtt_client_handle = mqtt_client_create(MQTT_BROKER, MQTT_CLIENT_ID, MQTT_KEEP_ALIVE_INTERVAL);
    if (mqtt_client_handle == NULL) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mqtt_client_set_on_connected(mqtt_client_handle, mqtt_connected);
    mqtt_client_set_on_message_arrived(mqtt_client_handle, mqtt_message_arrived);

    ret = mqtt_client_connect(mqtt_client_handle, NULL, NULL, NULL);
    if (ret != MQTT_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        mqtt_client_destroy(&mqtt_client_handle);
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (keep_running) {
        int moisture = read_moisture();
        if (moisture < 0) {
            syslog(LOG_ERR, "Failed to read moisture sensor");
        } else {
            syslog(LOG_INFO, "Moisture: %d%%", moisture);

            if (moisture < MOISTURE_THRESHOLD_LOW && last_moisture >= MOISTURE_THRESHOLD_LOW) {
                set_relay(1);
            } else if (moisture > MOISTURE_THRESHOLD_HIGH && last_moisture <= MOISTURE_THRESHOLD_HIGH) {
                set_relay(0);
