#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define CHANNEL 0
#define VREF 3.3
#define BUFFER_SIZE 3
#define READ_INTERVAL_MS 500000

static int spi_fd;

void cleanup(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct spi_ioc_transfer spi;
    uint8_t tx[BUFFER_SIZE] = {0x01, (0x08 | CHANNEL) << 4, 0x00};
    uint8_t rx[BUFFER_SIZE] = {0};
    int ret;

    signal(SIGINT, cleanup);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        goto error;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        goto error;
    }

    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = BUFFER_SIZE;
    spi.delay_usecs = 0;
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = 8;
    spi.cs_change = 0;

    while (1) {
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi);
        if (ret < 0) {
            perror("SPI transfer failed");
            goto error;
        }

        uint16_t adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        float voltage = adc_value * VREF / 1024.0;

        printf("Raw Value: %d, Voltage: %.3f V\n", adc_value, voltage);

        usleep(READ_INTERVAL_MS);
    }

error:
    close(spi_fd);
    return EXIT_FAILURE;
}

