#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define CE_PIN 8
#define VREF 3.3
#define RESOLUTION 1024
#define LOG_INTERVAL 5

static volatile int keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        keep_running = 0;
    }
}

int main() {
    FILE *file;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    unsigned char tx[3], rx[3];
    int handle, i, adc_value;
    double voltage;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    file = fopen("sensor_data.csv", "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(file, "Timestamp,Channel 0,Channel 1,Channel 2\n");

    handle = spiOpen(CE_PIN, 1000000, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        fclose(file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        for (i = 0; i < 3; i++) {
            tx[0] = 0x01;
            tx[1] = (i << 4) | 0x80;
            tx[2] = 0x00;

            if (spiXfer(handle, tx, rx, 3) < 0) {
                fprintf(stderr, "SPI transfer failed for channel %d\n", i);
                spiClose(handle);
                fclose(file);
                gpioTerminate();
                return EXIT_FAILURE;
            }

            adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            voltage = (adc_value * VREF) / RESOLUTION;

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(file, "%s,%.3f", timestamp, voltage);
            if (i < 2) fprintf(file, ",");
        }
        fprintf(file, "\n");
        fflush(file);

        time_sleep(LOG_INTERVAL);
    }

    spiClose(handle);
    fclose(file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

