#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define ADC_CHANNEL 0
#define MOTOR_PIN_1 17
#define MOTOR_PIN_2 27
#define NOISE_THRESHOLD 500
#define ADC_MAX 1023
#define PWM_FREQUENCY 100
#define SAMPLE_INTERVAL_MS 10

static int spi_fd;
static FILE *log_file;

void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpioInitialised()) {
        gpioHardwarePWM(MOTOR_PIN_1, 0, 0);
        gpioHardwarePWM(MOTOR_PIN_2, 0, 0);
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

int spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = 500000,
        .bits_per_word = 8,
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

int read_adc(int channel) {
    unsigned char tx[3] = {1, (8 + channel) << 4, 0};
    unsigned char rx[3] = {0};
    int ret;

    ret = spi_transfer(tx, rx, 3);
    if (ret < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

void log_event(int adc_value) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "[%s] Noise level: %d, PWM duty cycle: %d%%\n",
            timestamp, adc_value, (int)((float)adc_value / ADC_MAX * 100));
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(MOTOR_PIN_1, PI_OUTPUT);
    gpioSetMode(MOTOR_PIN_2, PI_OUTPUT);

    gpioHardwarePWM(MOTOR_PIN_1, PWM_FREQUENCY, 0);
    gpioHardwarePWM(MOTOR_PIN_2, PWM_FREQUENCY, 0);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("SPI device open failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("vibration_log.txt", "a");
    if (!log_file) {
        perror("Log file open failed");
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, skipping iteration\n");
        } else if (adc_value > NOISE_THRESHOLD) {
            unsigned int duty_cycle = (unsigned int)((float)adc_value / ADC_MAX * 1000000);
            gpioHardwarePWM(MOTOR_PIN_1, PWM_FREQUENCY, duty_cycle);
            gpioHardwarePWM(MOTOR_PIN_2, PWM_FREQUENCY, duty_cycle);
            log_event(adc_value);
        } else {
            gpioHardwarePWM(MOTOR_PIN_1, PWM_FREQUENCY, 0);
            gpioHardwarePWM(MOTOR_PIN_2, PWM_FREQUENCY, 0);
        }

        time_sleep(SAMPLE_INTERVAL_MS / 1000.0);
    }

    return EXIT_SUCCESS;
}

