#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define MCP3008_SPI_BUS 0
#define MCP3008_SPI_CS 0
#define MCP3008_SPI_SPEED 1000000
#define BH1750_I2C_ADDR 0x23
#define BH1750_I2C_BUS "/dev/i2c-1"
#define LOG_FILE "tamper_log.csv"
#define LOG_INTERVAL 5
#define ADC_COMMAND 0x01
#define ADC_CHANNEL 0x00

static int spi_fd;
static int i2c_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void cleanup(int signum) {
    if (spi_fd >= 0) close(spi_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file) fclose(log_file);
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

int init_spi() {
    char spi_device[20];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d.%d", MCP3008_SPI_BUS, MCP3008_SPI_CS);
    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("SPI open");
        return -1;
    }

    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, MCP3008_SPI_SPEED) < 0) {
        perror("SPI ioctl");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int init_i2c() {
    i2c_fd = open(BH1750_I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("I2C open");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_I2C_ADDR) < 0) {
        perror("I2C ioctl");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int read_adc() {
    unsigned char tx[3] = {1, (ADC_CHANNEL << 4) | 0x01, 0};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = MCP3008_SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("SPI transfer");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

float adc_to_db(int adc_value) {
    // Assuming a linear relationship for simplicity
    return (float)adc_value * 100.0 / 1023.0;
}

int read_bh1750() {
    unsigned char cmd = 0x11; // Continuous high-resolution mode 2
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("BH1750 write command");
        return -1;
    }

    usleep(180000); // 180 ms

    unsigned char data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("BH1750 read data");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (init_spi() < 0 || init_i2c() < 0) {
        fprintf(stderr, "Initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Log file open");
        cleanup(0);
    }

    fprintf(log_file, "timestamp,sound_level_db,light_level_lux,error_code\n");

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        int adc_value = read_adc();
        float sound_level = adc_value >= 0 ? adc_to_db(adc_value) : -1;

        int light_value = read_bh1750();
        float light_level = light_value >= 0 ? (float)light_value / 1.2 : -1;

        int error_code = 0;
        if (adc_value < 0) error_code |= 1;
        if (light_value < 0) error_code |= 2;

        fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, sound_level, light_level, error_code);
        fflush(log_file);

        sleep(LOG_INTERVAL);
    }

    return EXIT_SUCCESS;
}

