#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MOISTURE_THRESHOLD 30
#define MOISTURE_PIN 17
#define MAX_RETRIES 3

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int read_moisture(int spi_channel) {
    unsigned char tx[3] = {1, (8 + 0) << 4, 0};
    unsigned char rx[3] = {0};
    int retries = 0;
    int adc_value = -1;

    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_channel, tx, rx, 3) == 3) {
            adc_value = ((rx[1] & 3) << 8) + rx[2];
            break;
        }
        retries++;
        usleep(100000); // 100ms delay before retry
    }

    return adc_value;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(MOISTURE_PIN, PI_OUTPUT);
    gpioWrite(MOISTURE_PIN, PI_LOW);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_reading_time = time(NULL);

    while (keep_running) {
        int moisture_value = read_moisture(spi_handle);
        if (moisture_value >= 0) {
            float voltage = (float)moisture_value * 3.3 / 1023.0;
            float moisture_percent = 100.0 - (voltage / 3.3) * 100.0;

            time_t current_time = time(NULL);
            if (difftime(current_time, last_reading_time) >= 60) {
                printf("[%s] Moisture: %.2f%%\n", ctime(&current_time), moisture_percent);
                last_reading_time = current_time;

                if (moisture_percent < MOISTURE_THRESHOLD) {
                    gpioWrite(MOISTURE_PIN, PI_HIGH);
                    printf("Moisture below threshold. Pump activated.\n");
                } else {
                    gpioWrite(MOISTURE_PIN, PI_LOW);
                    printf("Moisture above threshold. Pump deactivated.\n");
                }
            }
        } else {
            fprintf(stderr, "Failed to read moisture sensor\n");
        }

        sleep(1);
    }

    gpioWrite(MOISTURE_PIN, PI_LOW);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

