#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>

#define MCP3008_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define CO2_THRESHOLD 700
#define FAN_PIN 18
#define LOG_FILE "air_quality.log"
#define RETRY_DELAY 5

static volatile int keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        keep_running = 0;
    }
}

double adc_to_co2(int adc_value) {
    return 0.5 * adc_value - 50;
}

int main() {
    FILE *log_file;
    time_t raw_time;
    struct tm *time_info;
    char timestamp[20];
    int adc_value;
    double co2_ppm;
    int fan_state;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioWrite(FAN_PIN, PI_LOW);

    if (gpioSetMode(SPI_CHANNEL, PI_SPI) < 0) {
        fprintf(stderr, "SPI mode setting failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioHardwareSPI(SPI_CHANNEL, SPI_SPEED, 0, 0) < 0) {
        fprintf(stderr, "SPI hardware configuration failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        int retry_count = 0;
        while (retry_count < 3) {
            adc_value = gpioSPIx(SPI_CHANNEL, (MCP3008_CHANNEL << 4) | 0x1, 2);
            if (adc_value >= 0 && adc_value <= 1023) {
                break;
            }
            retry_count++;
            fprintf(stderr, "Invalid ADC value: %d, retrying...\n", adc_value);
            gpioDelay(RETRY_DELAY * 1000000);
        }

        if (retry_count == 3) {
            fprintf(stderr, "Failed to get valid ADC value after 3 attempts\n");
            continue;
        }

        co2_ppm = adc_to_co2(adc_value);
        fan_state = (co2_ppm > CO2_THRESHOLD) ? PI_HIGH : PI_LOW;
        gpioWrite(FAN_PIN, fan_state);

        time(&raw_time);
        time_info = localtime(&raw_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        fprintf(log_file, "%s,%.2f,%s\n", timestamp, co2_ppm, fan_state ? "ON" : "OFF");
        fflush(log_file);

        gpioDelay(5000000);  // 5 seconds
    }

    fclose(log_file);
    gpioWrite(FAN_PIN, PI_LOW);
    gpioTerminate();

    return 0;
}

