#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <gpiod.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define RELAY_PIN 17
#define DOOR_SENSOR_PIN 27
#define SPI_SPEED 1000000
#define POLL_INTERVAL_MS 100
#define DEBOUNCE_DELAY_MS 1000
#define PROXIMITY_THRESHOLD 20

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int setup_gpio(struct gpiod_chip **chip, struct gpiod_line **relay_line, struct gpiod_line **sensor_line) {
    *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!*chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    *relay_line = gpiod_chip_get_line(*chip, RELAY_PIN);
    if (!*relay_line) {
        perror("Failed to get relay line");
        return -1;
    }

    *sensor_line = gpiod_chip_get_line(*chip, DOOR_SENSOR_PIN);
    if (!*sensor_line) {
        perror("Failed to get sensor line");
        return -1;
    }

    if (gpiod_line_request_output(*relay_line, "relay_control", 0) < 0) {
        perror("Failed to request relay line as output");
        return -1;
    }

    if (gpiod_line_request_input(*sensor_line, "door_sensor") < 0) {
        perror("Failed to request sensor line as input");
        return -1;
    }

    return 0;
}

int setup_spi(int *spi_fd) {
    *spi_fd = open(SPI_DEVICE, O_RDWR);
    if (*spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int mode = SPI_MODE_0;
    if (ioctl(*spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        return -1;
    }

    int bits = 8;
    if (ioctl(*spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(*spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        return -1;
    }

    return 0;
}

int read_adc(int spi_fd, uint8_t channel) {
    uint8_t tx[3] = {
        0x01,
        (channel << 4) | 0x08,
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("Failed to transfer SPI data");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

void log_event(const char *message) {
    FILE *log_file = fopen("door_events.log", "a");
