#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PWM_PIN 17
#define ADC_CHANNELS 3
#define LOG_FILE "irrigation.log"
#define READ_INTERVAL 5
#define PWM_FREQUENCY 100
#define PWM_RANGE 100

static int spi_handle;
static FILE *log_file;

void signal_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        gpioPWM(PWM_PIN, 0);  // Close the valve
        gpioSetMode(PWM_PIN, PI_INPUT);
        spiClose(spi_handle);
        fclose(log_file);
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    int adc_value = -1;

    tx[0] = 0x01;
    tx[1] = (channel << 4) | 0x0;
    tx[2] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 3) == 3) {
        adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    }

    return adc_value;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    time_t last_log_time = time(NULL);

    while (1) {
        int adc_values[ADC_CHANNELS] = {0};
        int valid_readings = 0;
        int sum = 0;

        for (int i = 0; i < ADC_CHANNELS; i++) {
            adc_values[i] = read_adc(i);
            if (adc_values[i] >= 0) {
                sum += adc_values[i];
                valid_readings++;
            }
        }

        if (valid_readings > 0) {
            int average = sum / valid_readings;
            int valve_position = PWM_RANGE - (average * PWM_RANGE / 1023);

            time_t current_time = time(NULL);
            if (current_time - last_log_time >= READ_INTERVAL) {
                fprintf(log_file, "%ld, %d, %d, %d, %d\n",
                        (long)current_time,
                        adc_values[0], adc_values[1], adc_values[2],
                        average, valve_position);
                fflush(log_file);
                last_log_time = current_time;
            }

            gpioPWM(PWM_PIN, valve_position);
        }

        sleep(1);
    }

    return EXIT_SUCCESS;
}

