#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define CHANNEL 0
#define MAX_RETRIES 5
#define MOISTURE_MIN 300
#define MOISTURE_MAX 700

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    int retries = 0;
    int adc_value = -1;

    while (retries < MAX_RETRIES && adc_value == -1) {
        tx[0] = 0x01;
        tx[1] = (channel << 4) | 0x00;
        tx[2] = 0x00;

        if (spiXfer(SPI_CHANNEL, tx, rx, 3) == 3) {
            adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            if (adc_value < 0 || adc_value > 1023) {
                adc_value = -1;
            }
        }

        if (adc_value == -1) {
            retries++;
            usleep(100000 * (1 << retries));  // Exponential backoff
        }
    }

    return adc_value;
}

double adc_to_moisture(int adc_value) {
    if (adc_value < MOISTURE_MIN) adc_value = MOISTURE_MIN;
    if (adc_value > MOISTURE_MAX) adc_value = MOISTURE_MAX;
    return 100.0 * (1.0 - (double)(adc_value - MOISTURE_MIN) / (MOISTURE_MAX - MOISTURE_MIN));
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *file = fopen("soil_data.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open soil_data.txt\n");
        spiClose(SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    time_t last_log_time = time(NULL);

    while (keep_running) {
        int adc_value = read_adc(CHANNEL);
        if (adc_value != -1) {
            double moisture = adc_to_moisture(adc_value);
            time_t current_time = time(NULL);

            if (current_time - last_log_time >= 5) {
                fprintf(file, "%ld, %d, %.2f%%\n", (long)current_time, adc_value, moisture);
                fflush(file);
                last_log_time = current_time;
            }
        } else {
            fprintf(stderr, "Failed to read ADC value after %d attempts\n", MAX_RETRIES);
        }

        sleep(1);
    }

    fclose(file);
    spiClose(SPI_CHANNEL);
    gpioTerminate();
    return 0;
}

