#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define LDR_CHANNEL 0
#define SPI_BUS 0
#define SPI_DEVICE 0
#define MIN_FREQ 220
#define MAX_FREQ 880
#define CALIBRATION_FILE "theremin_config.txt"

static volatile int keep_running = 1;
static int pwm_fd;
static int spi_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *trig_line;
static struct gpiod_line *echo_line;

void cleanup(int signum) {
    keep_running = 0;
    if (pwm_fd >= 0) close(pwm_fd);
    if (spi_fd >= 0) close(spi_fd);
    if (chip) gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

int setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);

    if (!trig_line || !echo_line) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_request_output(trig_line, "theremin_trig", 0);
    gpiod_line_request_input(echo_line, "theremin_echo");

    return 0;
}

int setup_pwm() {
    pwm_fd = open("/sys/class/pwm/pwm0/export", O_WRONLY);
    if (pwm_fd < 0) {
        perror("Failed to export PWM0");
        return -1;
    }

    if (write(pwm_fd, "0", 1) < 0) {
        perror("Failed to enable PWM0");
        close(pwm_fd);
        return -1;
    }

    close(pwm_fd);

    pwm_fd = open("/sys/class/pwm/pwm0/duty_cycle", O_WRONLY);
    if (pwm_fd < 0) {
        perror("Failed to open PWM0 duty cycle");
        return -1;
    }

    int period = 20000000; // 20ms period
    FILE *period_fd = fopen("/sys/class/pwm/pwm0/period", "w");
    if (!period_fd) {
        perror("Failed to set PWM0 period");
        close(pwm_fd);
        return -1;
    }
    fprintf(period_fd, "%d", period);
    fclose(period_fd);

    FILE *enable_fd = fopen("/sys/class/pwm/pwm0/enable", "w");
    if (!enable_fd) {
        perror("Failed to enable PWM0");
        close(pwm_fd);
        return -1;
    }
    fprintf(enable_fd, "1");
    fclose(enable_fd);

    return 0;
}

int setup_spi() {
    char spi_device[20];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d.%d", SPI_BUS, SPI_DEVICE);
    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int mode = SPI_MODE_0;
    int bits = 8;
    int speed = 500000;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI parameters");
        close(spi_fd);
        return -1;
    }

    return 0;
}

