#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define MCP3008_SPI_CHANNEL 0
#define MCP3008_SPI_SPEED 1000000
#define MCP3008_SPI_MODE 0
#define FAN_PIN 18
#define AQI_THRESHOLD 100
#define MAX_RETRIES 3
#define RETRY_DELAY 1

static FILE *log_file;
static int spi_handle;

void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        gpioSetMode(FAN_PIN, PI_INPUT);
        gpioWrite(FAN_PIN, PI_LOW);
        close(spi_handle);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int read_adc(int channel) {
    unsigned char tx[3], rx[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        tx[0] = 0x01;
        tx[1] = (0x08 | ((channel & 0x07) << 4));
        tx[2] = 0x00;

        if (spiXfer(spi_handle, tx, rx, 3) == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }

        retries++;
        sleep(RETRY_DELAY);
    }

    return -1;
}

int map_adc_to_aqi(int adc_value) {
    return (adc_value * 500) / 1023;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioWrite(FAN_PIN, PI_LOW);

    log_file = fopen("air_quality.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(MCP3008_SPI_CHANNEL, MCP3008_SPI_SPEED, MCP3008_SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            cleanup(0);
        }

        int aqi = map_adc_to_aqi(adc_value);
        time_t now = time(NULL);
        struct tm *t = localtime(&now);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, AQI: %d\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                t->tm_hour, t->tm_min, t->tm_sec, aqi);
        fflush(log_file);

        if (aqi > AQI_THRESHOLD) {
            gpioWrite(FAN_PIN, PI_HIGH);
        } else {
            gpioWrite(FAN_PIN, PI_LOW);
        }

        sleep(5);
    }

    return EXIT_SUCCESS;
}

