#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN 8
#define CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SAMPLE_INTERVAL 1
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

static int spi_fd;
static int gpio_fd;
static int running = 1;

void signal_handler(int signum) {
    running = 0;
}

int setup_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int ret;
    struct spi_ioc_transfer xfer = {
        .bits_per_word = SPI_BITS_PER_WORD,
        .speed_hz = SPI_SPEED,
        .mode = SPI_MODE,
    };

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &xfer.mode);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &xfer.speed_hz);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &xfer.bits_per_word);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    int ret = gpiod_line_request_output(line, "mq3-alcohol-sensor", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_chip_close(chip);
        return -1;
    }

    gpio_fd = gpiod_line_get_fd(line);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to get GPIO line file descriptor\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int read_adc() {
    unsigned char tx[3] = {0x01, (CHANNEL << 4) | 0x80, 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 0,
    };

    int retries = 0;
    while (retries < RETRY_COUNT) {
        int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
        if (ret < 0) {
            perror("SPI transfer failed");
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Sensor absent or malfunctioning\n");
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        return adc_value;
    }

    fprintf(stderr, "Failed to read ADC after %d retries\n", RETRY_COUNT);
    return -1;
}

void log_reading(int adc_value, float ppm) {
    FILE *log_file = fopen("alcohol_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(log_file, "%s,ADC: %d,PPM: %.2f,", timestamp, adc_value, ppm);

    if (ppm > 50) {
        fprintf(log_file, "Alcohol detected! Limit exceeded.\n");
    } else if (ppm < 20) {
        fprintf(log_file, "Sobriety confirmed.\n");
    } else {
        fprintf(log_file, "Alcohol level within acceptable range.\n");
    }

    fclose(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_spi() < 0) {
        return EXIT_FAILURE;
    }

    if (setup_gpio() < 0) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("alcohol_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        gpiod_line_release(gpiod_chip_get_line(gpiod_chip_open(GPIO_CHIP), GPIO_PIN));
        gpiod_chip_close(gpiod_chip_open(GPIO_CHIP));
        return EXIT_FAILURE;
    }
    fclose(log_file);

    while (running) {
        int adc_value = read_adc();
        if (adc_value >= 0) {
            float ppm = (adc_value * 0.5) - 10.0;
            log_reading(adc_value, ppm);
        }

        sleep(SAMPLE_INTERVAL);
    }

    close(spi_fd);
    gpiod_line_release(gpiod_chip_get_line(gpiod_chip_open(GPIO_CHIP), GPIO_PIN));
    gpiod_chip_close(gpiod_chip_open(GPIO_CHIP));

    return EXIT_SUCCESS;
}

