#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

#define MIN_SPEED 50
#define MAX_SPEED 255
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL_1 0
#define ADC_CHANNEL_2 1
#define NUM_SAMPLES 10
#define DELAY_MS 2000
#define ACCELERATION_TIME_MS 2000
#define DECELERATION_TIME_MS 2000
#define REVERSE_DELAY_MS 5000

static volatile int keep_running = 1;

void signal_handler(int signo) {
    keep_running = 0;
}

double map_speed(int adc_value) {
    double normalized = (double)adc_value / 1023.0;
    return log10(1 + normalized * 9) / log10(10);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int adc_value1 = 0, adc_value2 = 0;
        for (int i = 0; i < NUM_SAMPLES; i++) {
            int result1 = spiXfer(spi_handle, (char[]){1, (1 << 7) | ADC_CHANNEL_1, 0, 0}, (char[4]){0}, 4);
            int result2 = spiXfer(spi_handle, (char[]){1, (1 << 7) | ADC_CHANNEL_2, 0, 0}, (char[4]){0}, 4);
            if (result1 < 0 || result2 < 0) {
                fprintf(stderr, "SPI transfer failed\n");
                break;
            }
            adc_value1 += ((result1[1] & 0x03) << 8) | result1[2];
            adc_value2 += ((result2[1] & 0x03) << 8) | result2[2];
        }
        adc_value1 /= NUM_SAMPLES;
        adc_value2 /= NUM_SAMPLES;

        double speed_factor1 = map_speed(adc_value1);
        double speed_factor2 = map_speed(adc_value2);

        int target_speed1 = (int)(MIN_SPEED + speed_factor1 * (MAX_SPEED - MIN_SPEED));
        int target_speed2 = (int)(MIN_SPEED + speed_factor2 * (MAX_SPEED - MIN_SPEED));

        // Motor 1 forward, Motor 2 backward
        gpioWrite(MOTOR1_DIRECTION, PI_HIGH);
        gpioWrite(MOTOR2_DIRECTION, PI_LOW);

        for (int speed = MIN_SPEED; speed <= target_speed1; speed += 5) {
            gpioPWM(MOTOR1_ENABLE, speed);
            gpioPWM(MOTOR2_ENABLE, speed);
            gpioSleep(PI_TIME_RELATIVE, 0, ACCELERATION_TIME_MS / 1000);
        }

        gpioSleep(PI_TIME_RELATIVE, 2, 0);

        for (int speed = target_speed1; speed >= MIN_SPEED; speed -= 5) {
            gpioPWM(MOTOR1_ENABLE, speed);
            gpioPWM(MOTOR2_ENABLE, speed);
            gpioSleep(PI_TIME_RELATIVE, 0, DECELERATION_TIME_MS / 1000);
        }

        gpioSleep(PI_TIME_RELATIVE, 5, 0);

        // Reverse directions
        gpioWrite(MOTOR1_DIRECTION, PI_LOW);
        gpioWrite(MOTOR2_DIRECTION, PI_HIGH);

        for (int speed = MIN_SPEED; speed <= target_speed2; speed += 5) {
            gpioPWM(MOTOR1_ENABLE, speed);
            gpioPWM(MOTOR2_ENABLE, speed);
            gpioSleep(PI_TIME_RELATIVE, 0, ACCELERATION_TIME_MS / 1000);
        }

        gpioSleep(PI_TIME_RELATIVE, 2, 0);

        for (int speed = target_speed2; speed >= MIN_SPEED; speed -= 5) {
            gpioPWM(MOTOR1_ENABLE, speed);
            gpioPWM(MOTOR2_ENABLE, speed);
            gpioSleep(PI_TIME_RELATIVE, 0, DECELERATION_TIME_MS / 1000);
        }

        gpioSleep(PI_TIME_RELATIVE, 5, 0);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

