#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MCP3008_CS 8
#define LED_PIN 17
#define DEBOUNCE_TIME_MS 10
#define CALIBRATION_TIME_SEC 5
#define NOISE_THRESHOLD_PERCENT 10

volatile int keepRunning = 1;

void signalHandler(int signum) {
    keepRunning = 0;
}

int readADC(int channel) {
    unsigned char tx[3], rx[3];
    int adcValue = 0;

    tx[0] = 0x01;
    tx[1] = (channel << 4) | 0x00;
    tx[2] = 0x00;

    if (spiXfer(MCP3008_CS, tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    adcValue = ((rx[1] & 0x03) << 8) | rx[2];
    return adcValue;
}

double calibrateAmbientLevel() {
    int sum = 0;
    int samples = CALIBRATION_TIME_SEC * 100; // 100 samples per second

    for (int i = 0; i < samples; i++) {
        int value = readADC(0);
        if (value < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            return -1;
        }
        sum += value;
        usleep(10000); // 10ms delay
    }

    return (double)sum / samples;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(MCP3008_CS, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "GPIO mode setting failed\n");
        gpioTerminate();
        return 1;
    }

    int spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spiHandle < 0) {
        fprintf(stderr, "SPI handle creation failed\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signalHandler);

    double ambientLevel = calibrateAmbientLevel();
    if (ambientLevel < 0) {
        fprintf(stderr, "Calibration failed\n");
        spiClose(spiHandle);
        gpioTerminate();
        return 1;
    }

    double noiseThreshold = ambientLevel * (1 + NOISE_THRESHOLD_PERCENT / 100.0);
    printf("Ambient level: %.2f, Noise threshold: %.2f\n", ambientLevel, noiseThreshold);

    int ledState = LOW;
    unsigned long lastToggleTime = 0;

    while (keepRunning) {
        int value = readADC(0);
        if (value < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            break;
        }

        if (value > noiseThreshold) {
            unsigned long currentTime = gpioTick();
            if (currentTime - lastToggleTime > DEBOUNCE_TIME_MS * 1000) {
                ledState = !ledState;
                gpioWrite(LED_PIN, ledState);
                lastToggleTime = currentTime;
            }
        } else {
            gpioWrite(LED_PIN, LOW);
        }

        usleep(10000); // 10ms delay
    }

    gpioWrite(LED_PIN, LOW);
    spiClose(spiHandle);
    gpioTerminate();
    return 0;
}

