    return adcValue;
}

double calibrateAmbientLevel() {
    int sum = 0;
    int samples = CALIBRATION_TIME_SEC * 100; // 100 samples per second

    for (int i = 0; i < samples; i++) {
        int value = readADC(0);
        if (value < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            return -1;
        }
        sum += value;
        usleep(10000); // 10ms delay
    }

    return (double)sum / samples;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(MCP3008_CS, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "GPIO mode setting failed\n");
        gpioTerminate();
        return 1;
    }

    int spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spiHandle < 0) {
        fprintf(stderr, "SPI handle creation failed\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signalHandler);

    double ambientLevel = calibrateAmbientLevel();
    if (ambientLevel < 0) {
        fprintf(stderr, "Calibration failed\n");
        spiClose(spiHandle);
        gpioTerminate();
        return 1;
    }

    double noiseThreshold = ambientLevel * (1 + NOISE_THRESHOLD_PERCENT / 100.0);
    printf("Ambient level: %.2f, Noise threshold: %.2f\n", ambientLevel, noiseThreshold);

    int ledState = LOW;
    unsigned long lastToggleTime = 0;

    while (keepRunning) {
        int value = readADC(0);
        if (value < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            break;
        }

        if (value > noiseThreshold) {
            unsigned long currentTime = gpioTick();
            if (currentTime - lastToggleTime > DEBOUNCE_TIME_MS * 1000) {
                ledState = !ledState;
                gpioWrite(LED_PIN, ledState);
                lastToggleTime = currentTime;
            }
        } else {
            gpioWrite(LED_PIN, LOW);
        }

        usleep(10000); // 10ms delay
    }

    gpioWrite(LED_PIN, LOW);
    spiClose(spiHandle);
    gpioTerminate();
    return 0;
}
