        fprintf(stderr, "ERROR: Failed to open log file\n");
        spiClose(spiHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    while (1) {
        float voltage = readADC();
        if (voltage < 0) {
            time_t now;
            struct tm *tm_info;
            char timestamp[20];

            time(&now);
            tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(logFile, "%s, ERROR: ADC read failed\n", timestamp);
            fflush(logFile);
        } else {
            logAirflow(voltage);
