#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_CS 8
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000
#define SAMPLE_RATE_HZ 1000
#define SAMPLE_PERIOD_NS (1000000000 / SAMPLE_RATE_HZ)

static int spi_fd;
static int gpio_fd;
static struct gpiod_line *cs_line;
static FILE *log_file;

static void cleanup(int signum) {
    if (cs_line) gpiod_line_release(cs_line);
    if (gpio_fd >= 0) close(gpio_fd);
    if (spi_fd >= 0) close(spi_fd);
    if (log_file) fclose(log_file);
    exit(EXIT_SUCCESS);
}

static int setup_spi() {
    int ret;
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_MAX_SPEED_HZ;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        perror("Failed to set SPI max speed");
        return -1;
    }

    return 0;
}

static int setup_gpio() {
    gpio_fd = gpiod_open(GPIO_CHIP);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    cs_line = gpiod_get_line(gpio_fd, GPIO_CS);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        return -1;
    }

    int ret = gpiod_line_request_output(cs_line, "MCP3008_CS", 1);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        return -1;
    }

    return 0;
}

static int read_adc(uint16_t *value) {
    uint8_t tx_buf[3] = {0x01, 0x80, 0x00};
    uint8_t rx_buf[3] = {0};
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    gpiod_line_set_value(cs_line, 0);
    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
    gpiod_line_set_value(cs_line, 1);

    if (ret < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    *value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return 0;
}

int main() {
    struct timespec next_sample;
    struct timespec current_time;
    struct timespec sleep_time;
    int64_t timestamp_ns;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (setup_spi() < 0) return EXIT_FAILURE;
    if (setup_gpio() < 0) return EXIT_FAILURE;

    log_file = fopen("audio_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup(0);
    }

    clock_gettime(CLOCK_MONOTONIC_RAW, &next_sample);

    while (1) {
        uint16_t adc_value;
        if (read_adc(&adc_value) < 0) continue;

        clock_gettime(CLOCK_MONOTONIC_RAW, &current_time);
        timestamp_ns = (int64_t)current_time.tv_sec * 1000000000LL + current_time.tv_nsec;

        fprintf(log_file, "%lld|%u\n", timestamp_ns, adc_value);
        fflush(log_file);

        next_sample.tv_nsec += SAMPLE_PERIOD_NS;
        if (next_sample.tv_nsec >= 1000000000) {
            next_sample.tv_sec += 1;
            next_sample.tv_nsec -= 1000000000;
        }

        sleep_time.tv_sec = next_sample.tv_sec - current_time.tv_sec;
        sleep_time.tv_nsec = next_sample.tv_nsec - current_time.tv_nsec;
        if (sleep_time.tv_nsec < 0) {
            sleep_time.tv_sec--;
            sleep_time.tv_nsec += 1000000000;
        }

        nanosleep(&sleep_time, NULL);
    }

    return EXIT_SUCCESS;
}

