#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define VREF 3.3
#define ADC_MAX 1023
#define LOG_FILE "gas_log.txt"
#define RETRY_DELAY_MS 100

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = 0;
    }
}

int main() {
    FILE *log_file;
    time_t raw_time;
    struct tm *time_info;
    char time_str[26];
    unsigned char spi_buf[3];
    unsigned int adc_value;
    float voltage, ppm;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(SPI_CHANNEL, PI_SPI) != 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetSPISpeed(SPI_CHANNEL, SPI_SPEED) != 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (keep_running) {
        spi_buf[0] = 0x01;
        spi_buf[1] = 0x80;
        spi_buf[2] = 0x00;

        if (gpioSPIxfer(SPI_CHANNEL, spi_buf, (char *)spi_buf, 3) < 0) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        adc_value = ((spi_buf[1] & 0x03) << 8) | spi_buf[2];
        voltage = (adc_value * VREF) / ADC_MAX;
        ppm = voltage * 1000.0;

        time(&raw_time);
        time_info = localtime(&raw_time);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);

        fprintf(log_file, "%s, %.3f, %.2f\n", time_str, voltage, ppm);
        printf("Voltage: %.3f V, PPM: %.2f\n", voltage, ppm);

        fflush(log_file);
        sleep(1);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

