#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <math.h>

#define MCP3008_CS 8
#define MCP3008_MOSI 10
#define MCP3008_MISO 9
#define MCP3008_SCLK 11

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000

#define ADXL335_SENSITIVITY 0.3 // mV/g
#define ADXL335_ZERO_G_BIAS 1.5 // V

#define KALMAN_Q 0.1
#define KALMAN_R 0.1
#define KALMAN_P 1.0

#define SAMPLE_RATE 10
#define SAMPLE_INTERVAL (1.0 / SAMPLE_RATE)

typedef struct {
    double x, y, z;
} Vector3D;

typedef struct {
    double q;
    double r;
    double p;
    double k;
    double x;
} KalmanFilter;

KalmanFilter kf = {KALMAN_Q, KALMAN_R, KALMAN_P, 0, 0};

void kalman_filter_update(KalmanFilter *kf, double measurement) {
    kf->p = kf->p + kf->q;
    kf->k = kf->p / (kf->p + kf->r);
