#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>
#include <time.h>

#define NUM_SENSORS 3
#define GPIO_PINS[NUM_SENSORS] = {4, 17, 27}
#define V_QUIESCENT 1.65
#define SENSITIVITY 0.025
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "magnetic_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_SENSORS];
static FILE *log_file;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

double read_sensor(int index) {
    int value;
    int ret;

    ret = gpiod_line_get_value(lines[index]);
    if (ret < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_PINS[index], strerror(errno));
        return -1;
    }

    value = ret ? 3.3 : 0.0;
    return (value - V_QUIESCENT) / SENSITIVITY;
}

int init_gpio() {
    int i;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    for (i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line for GPIO %d: %s\n", GPIO_PINS[i], strerror(errno));
            goto error;
        }

        ret = gpiod_line_request_input(lines[i], "DRV5055VA_Hall_Effect");
        if (ret < 0) {
            fprintf(stderr, "Error requesting input for GPIO %d: %s\n", GPIO_PINS[i], strerror(errno));
            goto error;
        }
    }

    return 0;

error:
    for (int j = 0; j < i; j++) {
        if (lines[j]) {
            gpiod_line_release(lines[j]);
        }
    }
    gpiod_chip_close(chip);
    return -1;
}

void cleanup_gpio() {
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    double sensor_values[NUM_SENSORS];
    struct timespec sleep_time = {0, SAMPLE_INTERVAL_MS * 1000000};
    struct timespec remaining;

    signal(SIGINT, signal_handler);

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int valid_readings = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            double value = read_sensor(i);
            if (value >= -100 && value <= 100) {
                sensor_values[i] = value;
                valid_readings++;
            } else {
                fprintf(stderr, "Warning: Sensor %d value out of range: %.2f mT\n", i + 1, value);
            }
        }

        if (valid_readings == NUM_SENSORS) {
            fprintf(log_file, "%.2f,%.2f,%.2f\n", 
                    sensor_values[0], sensor_values[1], sensor_values[2]);
            fflush(log_file);
        }

        nanosleep(&sleep_time, &remaining);
    }

    fclose(log_file);
    cleanup_gpio();
    return EXIT_SUCCESS;
}

