#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define MOISTURE_SENSOR_CHANNEL 0
#define PUMP_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MOISTURE_THRESHOLD 30
#define CHECK_INTERVAL 60

static volatile int keep_running = 1;

void log_event(const char *message) {
    FILE *log_file = fopen("watering.log", "a");
    if (log_file) {
        time_t now;
        time(&now);
        char *time_str = ctime(&now);
        time_str[strlen(time_str) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] %s\n", time_str, message);
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for pump GPIO\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(PUMP_GPIO, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set pull-up/down for pump GPIO\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(PUMP_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to turn off pump\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started");

    while (keep_running) {
        int adc_value = gpioSPIx(MOISTURE_SENSOR_CHANNEL, SPI_CHANNEL, SPI_SPEED, 0, 0);
        if (adc_value < 0) {
            log_event("Failed to read ADC value");
        } else {
            float moisture_percentage = (float)adc_value / 10.23;
            char message[100];
            snprintf(message, sizeof(message), "Moisture level: %.2f%%", moisture_percentage);
            log_event(message);

            if (moisture_percentage < MOISTURE_THRESHOLD) {
                if (gpioWrite(PUMP_GPIO, 1) < 0) {
                    log_event("Failed to turn on pump");
                } else {
                    log_event("Pump turned on");
                }
            } else {
                if (gpioWrite(PUMP_GPIO, 0) < 0) {
                    log_event("Failed to turn off pump");
                } else {
                    log_event("Pump turned off");
                }
            }
        }

        sleep(CHECK_INTERVAL);
    }

    if (gpioWrite(PUMP_GPIO, 0) < 0) {
        log_event("Failed to turn off pump on exit");
    }

    log_event("Program terminated");
    gpioTerminate();
    return 0;
}

