    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_adc(int channel) {
    unsigned char tx[3] = {0x01, 0x80 | (channel << 4), 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main() {
    signal(SIGINT, cleanup);

    if (init_spi() < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return EXIT_FAILURE;
    }

    csv_file = fopen("sensor_data.csv", "w");
    if (!csv_file) {
        perror("Error opening CSV file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "Timestamp,Channel0,Channel1,Channel2\n");

    while (1) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        int adc_values[CHANNELS];
        for (int i = 0; i < CHANNELS; i++) {
            adc_values[i] = read_adc(i);
            if (adc_values[i] < 0) {
                fprintf(stderr, "Failed to read ADC channel %d\n", i);
                cleanup(0);
            }
        }

        fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, adc_values[0], adc_values[1], adc_values[2]);
        fflush(csv_file);

        sleep(LOG_INTERVAL);
    }

    return EXIT_SUCCESS;
}
