#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>

#define LED_PIN 17
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MAX_RECONNECT_DELAY 60

mosquitto *mosq = NULL;
bool running = true;
int reconnect_delay = 1;

void log_error(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(stderr, "[%s] ERROR: %s\n", time_str, message);
}

void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == 0) {
        log_error("Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_error("Failed to connect to MQTT broker");
    }
}

void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *msg) {
    cJSON *json = cJSON_Parse((const char *)msg->payload);
    if (json == NULL) {
        log_error("Failed to parse JSON");
        return;
    }

    cJSON *led_state = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (cJSON_IsBool(led_state) && cJSON_IsObject(json) && cJSON_GetArraySize(json) == 1) {
        gpioWrite(LED_PIN, cJSON_IsTrue(led_state) ? 1 : 0);
        reconnect_delay = 1; // Reset reconnect delay on successful message
    } else {
        log_error("Invalid JSON payload");
    }

    cJSON_Delete(json);
}

void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    log_error("Disconnected from MQTT broker");
    while (running) {
        log_error("Attempting to reconnect...");
        if (mosquitto_reconnect(mosq) == MOSQ_ERR_SUCCESS) {
            break;
        }
        sleep(reconnect_delay);
        if (reconnect_delay < MAX_RECONNECT_DELAY) {
            reconnect_delay *= 2;
        }
    }
}

void signal_handler(int signum) {
    running = false;
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Turn off LED on startup

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create Mosquitto instance");
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 0) != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    mosquitto_loop_start(mosq);

    while (running) {
        sleep(1);
    }

    mosquitto_loop_stop(mosq, true);
    mosquitto_destroy(mosq);
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();
    mosquitto_lib_cleanup();

    return 0;
}

