#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18
#define DELAY_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *sound_sensor_line;
static struct gpiod_line *alarm_led_line;

void cleanup(int signum) {
    if (alarm_led_line) {
        gpiod_line_release(alarm_led_line);
    }
    if (sound_sensor_line) {
        gpiod_line_release(sound_sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    int value;
    struct sigaction sa;

    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sound_sensor_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_sensor_line) {
        fprintf(stderr, "Error getting sound sensor line\n");
        goto error;
    }

    alarm_led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!alarm_led_line) {
        fprintf(stderr, "Error getting alarm LED line\n");
        goto error;
    }

    if (gpiod_line_request_input(sound_sensor_line, "sound_sensor") < 0) {
        fprintf(stderr, "Error requesting sound sensor line as input\n");
        goto error;
    }

    if (gpiod_line_request_output(alarm_led_line, "alarm_led", 0) < 0) {
        fprintf(stderr, "Error requesting alarm LED line as output\n");
        goto error;
    }

    while (1) {
        value = gpiod_line_get_value(sound_sensor_line);
        if (value < 0) {
            fprintf(stderr, "Error reading sound sensor line\n");
            goto error;
        }

        printf("Sound level: %d\n", value);

        if (value == 0) {
            gpiod_line_set_value(alarm_led_line, 1);
            usleep(1000000);
            gpiod_line_set_value(alarm_led_line, 0);
        }

        usleep(DELAY_MS * 1000);
    }

error:
    cleanup(0);
    return EXIT_FAILURE;
}

