#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>

#define GPIO_CHIP_PATH "/dev/gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE_PATH "/var/log/vibration_shutdown.log"

volatile sig_atomic_t exit_flag = 0;

void signal_handler(int signum) {
    exit_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    FILE *log_file;
    struct sigaction sa;
    int ret;

    // Set up signal handlers
    memset(&sa, 0, sizeof(struct sigaction));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handlers");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP_PATH);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for input with event detection
    ret = gpiod_line_request_falling_edge_events(line, "vibration-monitor");
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE_PATH, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Monitoring vibration sensor on GPIO %d...\n", GPIO_LINE_OFFSET);

    while (!exit_flag) {
        // Wait for event
        ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            perror("Failed to wait for event");
            break;
        }

        // Read event
        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            perror("Failed to read event");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            time_t now;
            struct tm *tm_info;
            char timestamp[64];

            time(&now);
            tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            const char *log_message = "Vibration detected at %s\n";
            printf(log_message, timestamp);

            if (fprintf(log_file, log_message, timestamp) < 0) {
                perror("Failed to write to log file");
            }

            fflush(log_file);

            // Initiate system shutdown
            if (fork() == 0) {
                // Child process
                setsid();
                execl("/bin/sh", "sh", "-c", "sudo shutdown -h now", (char *)NULL);
                perror("Failed to execute shutdown command");
                exit(EXIT_FAILURE);
            } else {
                // Parent process
                int status;
                waitpid(-1, &status, 0);
            }
        }
    }

    // Clean up
    if (log_file) {
        fclose(log_file);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

