#define BMP280_ADDRESS 0x76
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_CALIB_REG 0x88
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_PRESSURE_REG 0xF7
#define BMP280_TEMPERATURE_REG 0xFA

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
} bmp280_calib_data;

bmp280_calib_data calib;
int i2c_handle;
FILE *log_file;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        close(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (gpioInitialised()) {
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

int read_calibration_data() {
    uint8_t calib_data[24];
    if (i2cReadI2CBlock(i2c_handle, BMP280_ADDRESS, BMP280_CALIB_REG, 24, calib_data) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        return -1;
