#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define BUFFER_SIZE 120
#define READ_INTERVAL 5
#define TEMP_SENSOR_VOLTAGE_PER_CELSIUS 0.010
#define MCP3008_VREF 3.3

volatile sig_atomic_t keep_running = 1;

float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_to_file() {
    FILE *file = fopen("temp_log.dat", "wb+");
    if (file == NULL) {
        fprintf(stderr, "Error opening file for writing\n");
        return;
    }
    if (fwrite(temperature_buffer, sizeof(float), BUFFER_SIZE, file) != BUFFER_SIZE) {
        fprintf(stderr, "Error writing to file\n");
    }
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        unsigned char tx[3] = {0x01, 0x80, 0x00};
        unsigned char rx[3] = {0};

        if (spiXfer(spi_handle, tx, rx, 3) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            sleep(READ_INTERVAL);
            continue;
        }

        int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        float voltage = (adc_value * MCP3008_VREF) / 1023.0;
        float temperature = voltage / TEMP_SENSOR_VOLTAGE_PER_CELSIUS;

        printf("Temperature: %.2f °C\n", temperature);

        temperature_buffer[buffer_index] = temperature;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        if (buffer_index == 0) {
            log_to_file();
        }

        sleep(READ_INTERVAL);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

