#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x23
#define SPI_BUS "/dev/spidev0.0"
#define LOG_FILE "environmental_log.txt"

static int i2c_fd;
static int spi_fd;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_init() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int read_bh1750() {
    unsigned char buf[2];
    buf[0] = 0x23; // Power on, reset
    buf[1] = 0x80; // Start measurement at 1x resolution

    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write to BH1750");
        return -1;
    }

    usleep(180000); // Wait for measurement

    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read from BH1750");
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

int spi_init() {
    spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI bus");
        return -1;
    }

    int mode = SPI_MODE_0;
    int bits = 8;
    int speed = 500000;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI parameters");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_max4466() {
    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = 500000,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to transfer SPI data");
        return -1;
    }

    return ((rx[0] & 0x0F) << 8) | rx[1];
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (i2c_init() < 0 || spi_init() < 0) {
        fprintf(stderr, "Failed to initialize sensors\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup(0);
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    while (1) {
        int light = read_bh1750();
        int sound = read_max4466();

        if (light >= 0 && sound >= 0) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s, Light: %d, Sound: %d\n", timestamp, light, sound);
            fflush(log_file);
        }

        sleep(1);
    }

    return EXIT_SUCCESS;
}

