        return -1;
    }

    int mode = SPI_MODE_0;
    int bits = 8;
    int speed = 500000;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI parameters");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_max4466() {
    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = 500000,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to transfer SPI data");
        return -1;
    }

    return ((rx[0] & 0x0F) << 8) | rx[1];
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (i2c_init() < 0 || spi_init() < 0) {
        fprintf(stderr, "Failed to initialize sensors\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup(0);
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    while (1) {
        int light = read_bh1750();
        int sound = read_max4466();

        if (light >= 0 && sound >= 0) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s, Light: %d, Sound: %d\n", timestamp, light, sound);
            fflush(log_file);
        }

        sleep(1);
    }

    return EXIT_SUCCESS;
}
