#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define TMP36_CHANNEL 0
#define MCP3008_SPI_CHANNEL 0
#define MCP4725_I2C_ADDR 0x62
#define I2C_BUS 1
#define SPI_SPEED 500000
#define SAMPLE_INTERVAL_MS 500
#define TEMP_MIN 0.0
#define TEMP_MAX 50.0
#define DAC_MIN 0
#define DAC_MAX 4095

static FILE *log_file;

void log_message(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] %s\n", time_str, message);
    fflush(log_file);
    printf("%s\n", message);
}

void cleanup(int spi_handle, int i2c_handle) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    int spi_handle = spiOpen(MCP3008_SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        log_message("Failed to open SPI");
        cleanup(spi_handle, -1);
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, MCP4725_I2C_ADDR);
    if (i2c_handle < 0) {
        log_message("Failed to open I2C");
        cleanup(spi_handle, i2c_handle);
        return 1;
    }

    uint8_t adc_cmd[3] = {1, (TMP36_CHANNEL << 4) | 0x1, 0};
    uint8_t adc_result[3];
    int retry_count = 0;
    const int max_retries = 3;

    while (1) {
        if (spiXfer(spi_handle, adc_cmd, 3, adc_result, 3) < 0) {
            if (++retry_count >= max_retries) {
                log_message("SPI transfer failed after max retries");
                cleanup(spi_handle, i2c_handle);
                return 1;
            }
            usleep(100000); // 100ms delay before retry
            continue;
        }
        retry_count = 0;

        int adc_value = ((adc_result[1] & 0x3) << 8) | adc_result[2];
        float voltage = adc_value * (3.3 / 1023.0);
        float temperature = voltage * 100.0 - 500.0;

        if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
            log_message("Temperature out of range");
            continue;
        }

        int dac_value = (int)((temperature - TEMP_MIN) / (TEMP_MAX - TEMP_MIN) * DAC_MAX);
        uint8_t dac_cmd[3] = {0x60, (dac_value >> 4) & 0xFF, (dac_value << 4) & 0xFF};

        if (i2cWriteDevice(i2c_handle, dac_cmd, 3) < 0) {
            log_message("I2C write to DAC failed");
        }

        char log_buf[256];
        snprintf(log_buf, sizeof(log_buf), "Raw: %d, Temp: %.2f°C, DAC: %.3fV", adc_value, temperature, voltage);
        log_message(log_buf);

        time_sleep(SAMPLE_INTERVAL_MS / 1000.0);
    }

    cleanup(spi_handle, i2c_handle);
    return 0;
}

