#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define NUM_SENSORS 3
#define CHANNELS[NUM_SENSORS] = {0, 1, 2}
#define MOISTURE_CALC(adc_value) ((1.0 - (adc_value / 1023.0)) * 100.0)

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int spi_handle;
    FILE *log_file;
    time_t raw_time;
    struct tm *time_info;
    char time_str[20];
    unsigned char spi_data[3];
    int adc_values[NUM_SENSORS];
    double moisture_values[NUM_SENSORS];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("soil_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            spi_data[0] = 0x01;
            spi_data[1] = (CHANNELS[i] + 0x08) << 4;
            spi_data[2] = 0x00;

            if (spiXfer(spi_handle, spi_data, (char *)adc_values, 3) < 0) {
                fprintf(stderr, "SPI transfer failed for sensor %d\n", i);
                continue;
            }

            adc_values[i] = ((spi_data[1] & 0x03) << 8) | spi_data[2];

            if (adc_values[i] < 0 || adc_values[i] > 1023) {
                fprintf(stderr, "Invalid ADC value for sensor %d: %d\n", i, adc_values[i]);
                continue;
            }

            moisture_values[i] = MOISTURE_CALC(adc_values[i]);

            time(&raw_time);
            time_info = localtime(&raw_time);
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);

            fprintf(log_file, "%s Sensor %d: %.2f%%\n", time_str, i, moisture_values[i]);
        }

        fflush(log_file);
        gpioDelay(60000000); // 60 seconds
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated. Goodbye!\n");
    return 0;
}

