#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define RELAY_PINS[NUM_RELAYS] = {17, 22, 23, 24}
#define ACTIVE_HIGH 1
#define INACTIVE_LOW 0
#define DELAY_SECONDS 1

// GPIO chip and line structures
struct gpiod_chip *chip;
struct gpiod_line *lines[NUM_RELAYS];

// Function to handle cleanup and exit
void cleanup_and_exit(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);

    // Set all relays to inactive
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_set_value(lines[i], INACTIVE_LOW);
    }

    // Release all GPIO lines
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_release(lines[i]);
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);

    exit(EXIT_SUCCESS);
}

int main() {
    int relay_pins[NUM_RELAYS] = {17, 22, 23, 24};

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines for each relay
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for pin %d\n", relay_pins[i]);
            cleanup_and_exit(SIGINT);
        }

        int ret = gpiod_line_request_output(lines[i], "relay_control", INACTIVE_LOW);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line for pin %d\n", relay_pins[i]);
            cleanup_and_exit(SIGINT);
        }
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        cleanup_and_exit(SIGINT);
    }

    // Main loop for relay sequencing
    while (1) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            // Activate relay
            gpiod_line_set_value(lines[i], ACTIVE_HIGH);
            sleep(DELAY_SECONDS);

            // Deactivate relay
            gpiod_line_set_value(lines[i], INACTIVE_LOW);
            sleep(DELAY_SECONDS);
        }
    }

    return EXIT_SUCCESS;
}

