        int ret = gpiod_line_request_output(lines[i], "relay_control", INACTIVE_LOW);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line for pin %d\n", relay_pins[i]);
            cleanup_and_exit(SIGINT);
        }
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        cleanup_and_exit(SIGINT);
    }

    // Main loop for relay sequencing
    while (1) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            // Activate relay
            gpiod_line_set_value(lines[i], ACTIVE_HIGH);
            sleep(DELAY_SECONDS);

            // Deactivate relay
            gpiod_line_set_value(lines[i], INACTIVE_LOW);
            sleep(DELAY_SECONDS);
        }
    }

    return EXIT_SUCCESS;
}
