#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27
#define PWM_RANGE 255
#define PWM_DUTY 150
#define RAIN_THRESHOLD 5
#define POLL_INTERVAL 1

volatile sig_atomic_t terminate = 0;

void signalHandler(int signum) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (setmode(BCM_MODE) < 0) {
        fprintf(stderr, "Failed to set BCM mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_ENA, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_ENA, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *logFile = fopen("rain_log.txt", "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spiHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3];
    int rainLevel = 0;
    int motorState = 0; // 0: open, 1: closing, 2: closed, 3: opening

    while (!terminate) {
        if (spiXfer(spiHandle, tx, rx, 3) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            break;
        }

        int adcValue = ((rx[1] & 0x03) << 8) | rx[2];
        rainLevel = 10 - (adcValue * 10 / 1023);

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        if (fprintf(logFile, "%s, %d\n", timestamp, rainLevel) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
        }
        fflush(logFile);

        if (rainLevel >= RAIN_THRESHOLD && motorState != 2) {
            if (motorState != 1) {
                gpioWrite(MOTOR_IN1, 1);
                gpioWrite(MOTOR_IN2, 0);
                gpioPWM(MOTOR_ENA, PWM_DUTY);
                motorState = 1;
            }
            sleep(3);
            motorState = 2;
        } else if (rainLevel < RAIN_THRESHOLD && motorState != 0) {
            if (motorState != 3) {
                gpioWrite(MOTOR_IN1, 0);
                gpioWrite(MOTOR_IN2, 1);
                gpioPWM(MOTOR_ENA, PWM_DUTY);
                motorState = 3;
            }
            sleep(3);
            motorState = 0;
        }

        sleep(POLL_INTERVAL);
    }

    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, 0);

    if (logFile) {
        fclose(logFile);
    }
    spiClose(spiHandle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

