        exit(EXIT_FAILURE);
    }

    close(fd);
}

void unexport_gpio() {
    int fd = open(SYSFS_GPIO_UNEXPORT, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open unexport file");
        return;
    }

    char buf[4];
    snprintf(buf, sizeof(buf), "%d", GPIO_PIN);
    if (write(fd, buf, strlen(buf)) < 0) {
        perror("Failed to unexport GPIO");
    }

    close(fd);
}

void set_gpio_direction() {
    char path[100];
    snprintf(path, sizeof(path), "%s/direction", SYSFS_GPIO_PIN_PATH);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO direction file");
        exit(EXIT_FAILURE);
    }

    if (write(fd, "in", 2) < 0) {
        perror("Failed to set GPIO direction");
        close(fd);
        exit(EXIT_FAILURE);
    }

    close(fd);
}

int read_gpio_value() {
    int fd = open(VALUE_FILE, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open GPIO value file");
        return -1;
    }

    char buf[4];
    ssize_t bytes_read = read(fd, buf, sizeof(buf) - 1);
    close(fd);

    if (bytes_read < 0) {
        perror("Failed to read GPIO value");
        return -1;
    }

    buf[bytes_read] = '\0';
    return atoi(buf);
}

double compute_distance(double voltage) {
    return A / voltage + B;
}

void log_distance(double distance) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, distance);
    fclose(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    export_gpio();
    set_gpio_direction();

    while (keep_running) {
        int gpio_value = read_gpio_value();
        if (gpio_value < 0) {
            sleep(1);
            continue;
        }

        double voltage = gpio_value ? 3.3 : 0.0;
        double distance = compute_distance(voltage);
        log_distance(distance);

        if (distance < PROXIMITY_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    unexport_gpio();
    return 0;
}
