#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_CHANNEL 0
#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "magnetic_log.txt"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define ADC_COMMAND 0x0180
#define VREF 3300
#define DRV5055_VOUT_QUIESCENT 1650
#define SAMPLE_INTERVAL_MS 500

static int spi_fd;
static struct gpiod_line *cs_line;
static FILE *log_file;

static void cleanup(int signum) {
    if (cs_line) gpiod_line_release(cs_line);
    if (spi_fd >= 0) close(spi_fd);
    if (log_file) fclose(log_file);
    exit(EXIT_SUCCESS);
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int read_adc(void) {
    uint8_t tx[3] = {1, (ADC_COMMAND >> 4) & 0xF, (ADC_COMMAND << 4) & 0xF0};
    uint8_t rx[3] = {0};

    if (spi_transfer(tx, rx, sizeof(tx)) < 0) return -1;

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open gpiochip");
        return EXIT_FAILURE;
    }

    cs_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(cs_line, "DRV5055_CS", 1) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_RD_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error\n");
        } else {
            int vout_mv = (adc_value * VREF * 1000) / 1023;
            int b_mt = ((vout_mv - DRV5055_VOUT_QUIESCENT) * 100) / 100;

            struct timeval tv;
            gettimeofday(&tv, NULL);
            long unix_epoch = tv.tv_sec;

            fprintf(log_file, "%ld,%d.%02d\n", unix_epoch, b_mt / 100, b_mt % 100);
            fflush(log_file);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

