        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error\n");
        } else {
            int vout_mv = (adc_value * VREF * 1000) / 1023;
            int b_mt = ((vout_mv - DRV5055_VOUT_QUIESCENT) * 100) / 100;

            struct timeval tv;
            gettimeofday(&tv, NULL);
            long unix_epoch = tv.tv_sec;

            fprintf(log_file, "%ld,%d.%02d\n", unix_epoch, b_mt / 100, b_mt % 100);
            fflush(log_file);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}
