#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MOISTURE_PIN 0
#define LOG_FILE "moisture_log.txt"
#define READ_INTERVAL 60

static volatile int keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = 0;
    }
}

void log_message(const char *message) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(file, "[%s] %s\n", timestamp, message);
    fclose(file);
}

int read_adc(int channel) {
    unsigned char tx_buf[3] = {0x01, 0x80 | (channel << 4), 0x00};
    unsigned char rx_buf[3] = {0};
    int adc_value = -1;

    if (spiXfer(SPI_CHANNEL, tx_buf, rx_buf, 3) == 3) {
        adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    }

    return adc_value;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (keep_running) {
        int adc_value = read_adc(MOISTURE_PIN);

        if (adc_value >= 0) {
            char message[50];
            snprintf(message, sizeof(message), "ADC Value: %d", adc_value);
            log_message(message);
        } else {
            log_message("ADC Read Failed");
        }

        time_sleep(READ_INTERVAL);
    }

    spiClose(SPI_CHANNEL);
    gpioTerminate();
    return EXIT_SUCCESS;
}

