#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP 0
#define GPIO_LINE 17
#define LOG_FILE "current_log.txt"
#define ADC_CHANNEL 0
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define BUFFER_SIZE 3
#define SAMPLE_INTERVAL 1

static int spi_fd;
static struct gpiod_line *gpio_line;
static FILE *log_file;

void cleanup(int signum) {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

int read_adc(int channel) {
    unsigned char tx[3] = {
        0x01,
        (channel << 4) | 0x00,
        0x00,
    };
    unsigned char rx[3] = {0};
    int ret;

    ret = spi_transfer(tx, rx, 3);
    if (ret < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_number(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    gpio_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(gpio_line, "MLX91209", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(gpio_line);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        gpiod_line_release(gpio_line);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float voltage = adc_value * (3.3 / 1023.0);
        float current = voltage / 0.1; // 100 mV/A sensitivity

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.3f\n", timestamp, current);
        fflush(log_file);

        sleep(SAMPLE_INTERVAL);
    }

    return EXIT_SUCCESS;
}

