#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL 100000 // 100 ms

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int spi_handle;
    FILE *log_file;
    time_t raw_time;
    struct tm *time_info;
    char time_buffer[20];
    unsigned char tx[3], rx[3];
    float voltage, current;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open SPI0 (CE0) at 1 MHz, mode 0
    spi_handle = spiOpen(0, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI0\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (keep_running) {
        // Prepare SPI transfer
        tx[0] = 0x01;
        tx[1] = 0x80 | (CHANNEL << 4);
        tx[2] = 0x00;

        // Perform SPI transfer
        if (spiXfer(spi_handle, tx, rx, 3) < 0) {
            fprintf(stderr, "SPI transfer error\n");
            continue;
        }

        // Compute 10-bit result
        int raw_value = ((rx[1] & 0x03) << 8) | rx[2];

        // Convert to voltage (0-5V)
        voltage = (float)raw_value * 5.0 / 1023.0;

        // Check voltage range
        if (voltage < 0.0 || voltage > 5.0) {
            fprintf(stderr, "Warning: Voltage out of range: %.2fV\n", voltage);
            continue;
        }

        // Convert voltage to current (0-50A)
        current = (voltage - 2.5) * (50.0 / 2.5);

        // Get current time
        time(&raw_time);
        time_info = localtime(&raw_time);
        strftime(time_buffer, sizeof(time_buffer), "%Y-%m-%d %H:%M:%S", time_info);

        // Write to log file
        fprintf(log_file, "%s %.2f A\n", time_buffer, current);
        fflush(log_file);

        // Delay for next sample
        gpioDelay(SAMPLE_INTERVAL);
    }

    // Clean up
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

