    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int read_sensor(struct gpiod_line *line) {
    int count_low = 0;
    for (int i = 0; i < SAMPLES; i++) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading sensor: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }
        if (value == 0) {
            count_low++;
        }
        usleep(DEBOUNCE_DELAY_MS * 1000);
    }
    return (count_low > SAMPLES / 2) ? 0 : 1;
}

