    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_number(CHIP_NUMBER);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        fprintf(stderr, "Error getting line for sensor 1: %s\n", strerror(errno));
        goto error;
    }

