#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t terminate = 0;

void signal_handler(int signal) {
    terminate = 1;
}

int read_mcp3008(int channel) {
    unsigned char tx[3] = {0x01, 0x80 | (channel << 4), 0x00};
    unsigned char rx[3] = {0};
    int adc_value = 0;

    if (spiXfer(SPI_CHANNEL, tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC) adc_value = MIN_ADC;
    if (adc_value > MAX_ADC) adc_value = MAX_ADC;

    return 100.0 - ((double)(adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
}

void log_data(double moisture_level) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(file, "%s,%.2f\n", timestamp, moisture_level);
    printf("%s,%.2f\n", timestamp, moisture_level);

    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_BAUD, 0) < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            double moisture_level = calculate_moisture_level(adc_value);
            log_data(moisture_level);
        }
        sleep(READ_DELAY);
    }

    spiClose(SPI_CHANNEL);
    gpioTerminate();
    return 0;
}

