#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>

#define PIR_PIN 17
#define CAPTURE_DIR "/home/pi/security_cam/"
#define CAPTURE_WIDTH 1280
#define CAPTURE_HEIGHT 720
#define DEBOUNCE_TIME 200
#define POLL_INTERVAL 50

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "PIR motion detection system started");

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct stat st = {0};
    if (stat(CAPTURE_DIR, &st) == -1) {
        if (mkdir(CAPTURE_DIR, 0700) != 0) {
            syslog(LOG_ERR, "Failed to create capture directory: %s", strerror(errno));
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    int last_state = gpioRead(PIR_PIN);
    time_t last_motion_time = 0;

    while (keep_running) {
        int current_state = gpioRead(PIR_PIN);
        if (current_state != last_state) {
            time_t now = time(NULL);
            if (difftime(now, last_motion_time) >= DEBOUNCE_TIME / 1000.0) {
                current_state = gpioRead(PIR_PIN);
                if (current_state != last_state) {
                    if (current_state == PI_HIGH) {
                        syslog(LOG_INFO, "Motion detected");
                        char filename[256];
                        time_t capture_time = time(NULL);
                        struct tm *tm_info = localtime(&capture_time);
                        strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S.jpg", tm_info);

                        char filepath[512];
                        snprintf(filepath, sizeof(filepath), "%s%s", CAPTURE_DIR, filename);

                        pid_t pid = fork();
                        if (pid == 0) {
                            // Child process
                            char *args[] = {
                                "libcamera-still",
                                "-o", filepath,
                                "--width", "1280",
                                "--height", "720",
                                "--timestamp",
                                NULL
                            };
                            execvp(args[0], args);
                            syslog(LOG_ERR, "Failed to execute libcamera-still: %s", strerror(errno));
                            exit(EXIT_FAILURE);
                        } else if (pid > 0) {
                            // Parent process
                            int status;
                            waitpid(pid, &status, 0);
                            if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
                                syslog(LOG_INFO, "Image captured successfully: %s", filepath);
                            } else {
                                syslog(LOG_ERR, "Image capture failed");
                            }
                        } else {
                            syslog(LOG_ERR, "Failed to fork for image capture: %s", strerror(errno));
                        }
                    }
                    last_motion_time = now;
                }
            }
            last_state = current_state;
        }
        time_sleep(POLL_INTERVAL / 1000.0);
    }

    gpioTerminate();
    syslog(LOG_INFO, "PIR motion detection system stopped");
    closelog();
    return EXIT_SUCCESS;
}

