static char *buffer = NULL;
static struct v4l2_buffer buf;
static int frame_count = 0;
static int running = 1;

static void cleanup(int exit_code) {
    if (buffer) {
        munmap(buffer, IMAGE_SIZE);
    }
    if (fd != -1) {
        close(fd);
    }
    exit(exit_code);
}

static void signal_handler(int signum) {
    running = 0;
}

static int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (-1 == r && EINTR == errno);
    return r;
}

int main(int argc, char **argv) {
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct sigaction sa_int, sa_term;

    if (argc > 1) {
        device = argv[1];
    }

    fd = open(device, O_RDWR);
    if (fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        cleanup(EXIT_FAILURE);
    }

    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        cleanup(EXIT_FAILURE);
    }

    buffer = mmap(NULL, IMAGE_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        cleanup(EXIT_FAILURE);
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        cleanup(EXIT_FAILURE);
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        cleanup(EXIT_FAILURE);
    }

    sa_int.sa_handler = signal_handler;
    sigemptyset(&sa_int.sa_mask);
    sa_int.sa_flags = 0;
    sigaction(SIGINT, &sa_int, NULL);

    sa_term.sa_handler = signal_handler;
    sigemptyset(&sa_term.sa_mask);
    sa_term.sa_flags = 0;
    sigaction(SIGTERM, &sa_term, NULL);

    while (running) {
        fd_set fds;
        struct timeval tv;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2;
        tv.tv_usec = 0;

        int r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (-1 == r) {
            perror("select");
            break;
        }

        if (0 == r) {
            fprintf(stderr, "select timeout\n");
            continue;
        }

        if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            switch (errno) {
                case EAGAIN:
                    continue;
                default:
                    perror("VIDIOC_DQBUF");
                    break;
            }
            break;
        }

        char filename[256];
        snprintf(filename, sizeof(filename), "image_%04d.pgm", ++frame_count);
        FILE *file = fopen(filename, "wb");
        if (!file) {
            perror("fopen");
            xioctl(fd, VIDIOC_QBUF, &buf);
            continue;
        }

        fprintf(file, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);
        fwrite(buffer, IMAGE_SIZE, 1, file);
        fclose(file);

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            break;
        }
    }

    enum v4l2_buf_type type_off = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    xioctl(fd, VIDIOC_STREAMOFF, &type_off);

    cleanup(EXIT_SUCCESS);
}
