static volatile int keep_running = 1;

static void sigint_handler(int signum) {
    keep_running = 0;
}

static int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (-1 == r && EINTR == errno);
    return r;
}

static void errno_exit(const char *s) {
    fprintf(stderr, "%s error %d, %s\n", s, errno, strerror(errno));
    exit(EXIT_FAILURE);
}

static int init_device() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    if ((fd = open(dev_name, O_RDWR)) == -1) {
        errno_exit("Opening video device");
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        errno_exit("Querying Capabilities");
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", dev_name);
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", dev_name);
        exit(EXIT_FAILURE);
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        errno_exit("Setting Pixel Format");
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        errno_exit("Requesting Buffers");
    }

    n_buffers = req.count;

    for (int i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            errno_exit("Querying Buffer");
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            errno_exit("Mapping buffer");
        }
    }

    for (int i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            errno_exit("Queueing Buffer");
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        errno_exit("Starting Stream");
    }

    return 0;
}

static void close_device() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        errno_exit("Stopping Stream");
    }

    for (int i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            errno_exit("Unmapping buffer");
        }
    }

    if (close(fd) == -1) {
        errno_exit("Closing device");
    }
}

static void send_frame(int frame_index, void *data, size_t size) {
    struct {
        uint32_t frame_index;
        uint32_t fragment_index;
        uint32_t total_fragments;
        uint32_t payload_size;
    } header;

    uint32_t total_fragments = (size + FRAGMENT_SIZE - 1) / FRAGMENT_SIZE;
    uint32_t fragment_index = 0;
    uint8_t *ptr = (uint8_t *)data;

    while (size > 0) {
        size_t fragment_size = (size < FRAGMENT_SIZE) ? size : FRAGMENT_SIZE;
        header.frame_index = frame_index;
        header.fragment_index = fragment_index;
        header.total_fragments = total_fragments;
        header.payload_size = fragment_size;

        if (sendto(sockfd, &header, sizeof(header), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
            errno_exit("Sending header");
        }

        if (sendto(sockfd, ptr, fragment_size, 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
            errno_exit("Sending fragment");
        }

        ptr += fragment_size;
        size -= fragment_size;
        fragment_index++;
    }
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (init_device() == -1) {
        fprintf(stderr, "Failed to initialize device\n");
        exit(EXIT_FAILURE);
    }

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd == -1) {
        errno_exit("Creating socket");
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(atoi(argv[2]));
    if (inet_pton(AF_INET, argv[1], &server_addr.sin_addr) <= 0) {
        errno_exit("Invalid address/ Address not supported");
    }

    int frame_index = 0;
    while (keep_running) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            switch (errno) {
                case EAGAIN:
                    continue;
                case EIO:
                    fprintf(stderr, "I/O error\n");
                    exit(EXIT_FAILURE);
                default:
                    errno_exit("Dequeuing Buffer");
            }
        }

        send_frame(frame_index, buffers[buf.index].start, buf.bytesused);

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            errno_exit("Queueing Buffer");
        }

        frame_index++;
    }

    close_device();
    close(sockfd);

    return 0;
}
