#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>

#define CHIP "gpiochip0"
#define PAN_PIN 4
#define TILT_PIN 5
#define BUTTON_UP_PIN 6
#define BUTTON_DOWN_PIN 7
#define BUTTON_LEFT_PIN 8
#define BUTTON_RIGHT_PIN 9
#define PWM_PERIOD_US 20000
#define MIN_DUTY 50
#define MAX_DUTY 100
#define MID_DUTY 75
#define DUTY_RANGE 1000
#define POSITION_STEP 5
#define MIN_POSITION 25
#define MAX_POSITION 125
#define POLL_INTERVAL_US 50000

static struct gpiod_chip *chip;
static struct gpiod_line *pan_line, *tilt_line;
static struct gpiod_line *button_up, *button_down, *button_left, *button_right;
static int pan_position = MID_DUTY;
static int tilt_position = MID_DUTY;

void cleanup(int signum) {
    gpiod_line_release(pan_line);
    gpiod_line_release(tilt_line);
    gpiod_line_release(button_up);
    gpiod_line_release(button_down);
    gpiod_line_release(button_left);
    gpiod_line_release(button_right);
    gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

void set_servo_position(struct gpiod_line *line, int *position, int new_position) {
    if (new_position < MIN_POSITION) new_position = MIN_POSITION;
    if (new_position > MAX_POSITION) new_position = MAX_POSITION;
    *position = new_position;
    int duty_cycle = (*position * DUTY_RANGE) / 100;
    gpiod_line_set_value(line, duty_cycle);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    pan_line = gpiod_chip_get_line(chip, PAN_PIN);
    tilt_line = gpiod_chip_get_line(chip, TILT_PIN);
    button_up = gpiod_chip_get_line(chip, BUTTON_UP_PIN);
    button_down = gpiod_chip_get_line(chip, BUTTON_DOWN_PIN);
    button_left = gpiod_chip_get_line(chip, BUTTON_LEFT_PIN);
    button_right = gpiod_chip_get_line(chip, BUTTON_RIGHT_PIN);

    if (!pan_line || !tilt_line || !button_up || !button_down || !button_left || !button_right) {
        perror("gpiod_chip_get_line");
        cleanup(0);
    }

    if (gpiod_line_request_output(pan_line, "pan_servo", 0) < 0 ||
        gpiod_line_request_output(tilt_line, "tilt_servo", 0) < 0 ||
        gpiod_line_request_input(button_up, "button_up") < 0 ||
        gpiod_line_request_input(button_down, "button_down") < 0 ||
        gpiod_line_request_input(button_left, "button_left") < 0 ||
        gpiod_line_request_input(button_right, "button_right") < 0) {
        perror("gpiod_line_request");
        cleanup(0);
    }

    gpiod_line_set_value(pan_line, MID_DUTY);
    gpiod_line_set_value(tilt_line, MID_DUTY);

    while (1) {
        if (!gpiod_line_get_value(button_up))
            set_servo_position(tilt_line, &tilt_position, tilt_position - POSITION_STEP);
        if (!gpiod_line_get_value(button_down))
            set_servo_position(tilt_line, &tilt_position, tilt_position + POSITION_STEP);
        if (!gpiod_line_get_value(button_left))
            set_servo_position(pan_line, &pan_position, pan_position - POSITION_STEP);
        if (!gpiod_line_get_value(button_right))
            set_servo_position(pan_line, &pan_position, pan_position + POSITION_STEP);

        usleep(POLL_INTERVAL_US);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

