voidYUYVtoRGB24(unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    int i, j;
    unsigned char y, u, v, r, g, b;

    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j += 2) {
            y = yuyv[0];
            u = yuyv[1];
            v = yuyv[3];

            r = y + (1.370705 * (v - 128));
            g = y - (0.698001 * (v - 128)) - (0.337633 * (u - 128));
            b = y + (1.732446 * (u - 128));

            rgb[0] = (r > 255) ? 255 : r;
            rgb[1] = (g > 255) ? 255 : g;
            rgb[2] = (b > 255) ? 255 : b;

            y = yuyv[2];
            u = yuyv[1];
            v = yuyv[3];

            r = y + (1.370705 * (v - 128));
            g = y - (0.698001 * (v - 128)) - (0.337633 * (u - 128));
            b = y + (1.732446 * (u - 128));

            rgb[3] = (r > 255) ? 255 : r;
            rgb[4] = (g > 255) ? 255 : g;
            rgb[5] = (b > 255) ? 255 : b;

            yuyv += 4;
            rgb += 6;
        }
    }
}

void apply_box_blur(unsigned char *input, unsigned char *output, int width, int height) {
    int i, j, k, l, m, n;
    int sum_r, sum_g, sum_b;
    int radius = 2;

    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j++) {
            sum_r = sum_g = sum_b = 0;
            for (k = -radius; k <= radius; k++) {
                for (l = -radius; l <= radius; l++) {
                    m = i + k;
                    n = j + l;
                    if (m < 0) m = 0;
                    if (m >= height) m = height - 1;
                    if (n < 0) n = 0;
                    if (n >= width) n = width - 1;
                    sum_r += input[(m * width + n) * 3];
                    sum_g += input[(m * width + n) * 3 + 1];
                    sum_b += input[(m * width + n) * 3 + 2];
                }
            }
            output[(i * width + j) * 3] = sum_r / ((2 * radius + 1) * (2 * radius + 1));
            output[(i * width + j) * 3 + 1] = sum_g / ((2 * radius + 1) * (2 * radius + 1));
            output[(i * width + j) * 3 + 2] = sum_b / ((2 * radius + 1) * (2 * radius + 1));
        }
    }
}

