#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <curl/curl.h>
#include <sys/stat.h>
#include <errno.h>

#define PIR_PIN 17
#define DEBOUNCE_TIME_MS 2000
#define POLL_INTERVAL_MS 100
#define SNAPSHOT_DIR "motion_captures"
#define SNAPSHOT_QUALITY 85
#define SNAPSHOT_WIDTH 640
#define SNAPSHOT_HEIGHT 480

static volatile int keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        keep_running = 0;
    }
}

int create_directory(const char *path) {
    struct stat st = {0};
    if (stat(path, &st) == -1) {
        if (mkdir(path, 0700) != 0) {
            fprintf(stderr, "Failed to create directory %s: %s\n", path, strerror(errno));
            return -1;
        }
    } else if (!S_ISDIR(st.st_mode)) {
        fprintf(stderr, "Path %s exists but is not a directory\n", path);
        return -1;
    }
    return 0;
}

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((char*)userp)[0] = '\0';
    return 0;
}

int send_http_request(const char *server_ip, int server_port, const char *filename, const char *timestamp) {
    CURL *curl;
    CURLcode res;
    char post_data[256];
    char url[256];

    snprintf(url, sizeof(url), "http://%s:%d/upload", server_ip, server_port);
    snprintf(post_data, sizeof(post_data),
             "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion\":true,\"gpio_pin\":%d}",
             filename, timestamp, PIR_PIN);

    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "curl_easy_init() failed\n");
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, post_data);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_cleanup(curl);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN);

    if (create_directory(SNAPSHOT_DIR) != 0) {
        gpioTerminate();
        return 1;
    }

    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        gpioTerminate();
        return 1;
    }

    time_t last_motion_time = 0;
    char snapshot_filename[256];
    char timestamp[64];

    while (keep_running) {
        if (gpioRead(PIR_PIN) == PI_HIGH) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_motion_time) >= DEBOUNCE_TIME_MS / 1000.0) {
                last_motion_time = current_time;

                struct tm tm_info;
                struct timespec ts;
                clock_gettime(CLOCK_REALTIME, &ts);
                gmtime_r(&ts.tv_sec, &tm_info);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
                snprintf(snapshot_filename, sizeof(snapshot_filename), "%s/motion_%s.jpg",
                         SNAPSHOT_DIR, timestamp);

                char command[512];
                snprintf(command, sizeof(command),
                         "libcamera-still -o %s -n -t 1 -q %d --width %d --height %d",
                         snapshot_filename, SNAPSHOT_QUALITY, SNAPSHOT_WIDTH, SNAPSHOT_HEIGHT);

                if (system(command) != 0) {
                    fprintf(stderr, "Failed to capture snapshot\n");
                } else {
                    if (send_http_request(server_ip, server_port, snapshot_filename, timestamp) != 0) {
                        fprintf(stderr, "Failed to send HTTP request\n");
                    }
                }
            }
        }
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    curl_global_cleanup();
    gpioTerminate();
    return 0;
}

