#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <sys/wait.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define GPIO_PIN 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_TIME_MS 50

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_fd = NULL;

void log_message(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_fd, "[%s] %s\n", time_str, message);
    fflush(log_fd);
}

void cleanup(int signum) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_fd) {
        fclose(log_fd);
    }
    log_message("Cleanup completed.");
    exit(EXIT_SUCCESS);
}

void capture_image() {
    time_t now;
    time(&now);
    struct tm *tm_info = localtime(&now);
    char filename[64];
    snprintf(filename, sizeof(filename), "%s/%04d%02d%02d_%02d%02d%02d_%03ld.jpg",
             IMAGE_DIR, tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
             tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, tm_info->tm_mday);

    char command[256];
    snprintf(command, sizeof(command),
             "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview",
             filename);

    int result = system(command);
    if (result == 0) {
        log_message("Image captured successfully.");
    } else {
        log_message("Failed to capture image.");
    }
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    log_fd = fopen(LOG_FILE, "a");
    if (!log_fd) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_message("Failed to open GPIO chip.");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        log_message("Failed to get GPIO line.");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(line, "PIR-Sensor");
    if (ret < 0) {
        log_message("Failed to request GPIO line as input.");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_message("PIR motion sensor monitoring started.");

    while (1) {
        ret = gpiod_line_event_wait(line, (const struct timespec[]){ {0, 0} });
        if (ret < 0) {
            log_message("Error waiting for GPIO event.");
            continue;
        }

