static int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct sigaction sa;

    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    fd = open("/dev/video0", O_RDWR);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        goto error;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a V4L2 video capture device\n");
        goto error;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto error;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto error;
    }

    if (req.count < 1) {
        fprintf(stderr, "Device returned %d buffers\n", req.count);
        goto error;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        goto error;
    }

    buffer_size = buf.length;
    buffer = mmap(NULL, buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        goto error;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        goto error;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto error;
    }

    fd_set fds;
    struct timeval tv;
    int ret;

    while (1) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2;
        tv.tv_usec = 0;

        ret = select(fd + 1, &fds, NULL, NULL, &tv);

        if (ret == -1) {
            perror("select");
            goto error;
        }

        if (ret == 0) {
            fprintf(stderr, "Timeout\n");
            continue;
        }

        if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            perror("VIDIOC_DQBUF");
            goto error;
        }

        if (buf.index != 0) {
            fprintf(stderr, "Unexpected buffer index %d\n", buf.index);
            goto error;
        }

        if (buf.bytesused != FRAME_WIDTH * FRAME_HEIGHT * 2) {
            fprintf(stderr, "Unexpected frame size %d\n", buf.bytesused);
            goto error;
        }

        if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
            fprintf(stderr, "Unexpected pixel format\n");
            goto error;
        }

        FILE *outfile = fopen(OUTPUT_FILE, "wb");
        if (!outfile) {
            perror("fopen");
            goto error;
        }

        for (int y = CROP_Y; y < CROP_Y + CROPPED_HEIGHT; y++) {
            for (int x = CROP_X; x < CROP_X + CROPPED_WIDTH; x += 2) {
                int src_index = (y * FRAME_WIDTH + x) * 2;
                int dst_index = ((y - CROP_Y) * CROPPED_WIDTH + (x - CROP_X)) * 2;
                fwrite(buffer + src_index, 4, 1, outfile);
            }
        }

        fclose(outfile);

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            goto error;
        }
    }

error:
    cleanup(0);
    return EXIT_FAILURE;
}

