#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <termios.h>

#define PAN_PIN 17
#define TILT_PIN 18
#define PWM_FREQ 50
#define NEUTRAL_ANGLE 90
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define PWM_MIN 500
#define PWM_MAX 2500

int pan_angle = NEUTRAL_ANGLE;
int tilt_angle = NEUTRAL_ANGLE;

void set_servo_angle(int pin, int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d)\n", angle);
        return;
    }
    int pulse_width = PWM_MIN + (angle * (PWM_MAX - PWM_MIN) / (MAX_ANGLE - MIN_ANGLE));
    if (gpioSetServoPulsewidth(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: Failed to set PWM for pin %d\n", pin);
    }
}

void cleanup(int status) {
    set_servo_angle(PAN_PIN, NEUTRAL_ANGLE);
    set_servo_angle(TILT_PIN, NEUTRAL_ANGLE);
    gpioTerminate();
    exit(status);
}

int kbhit(void) {
    struct termios oldt, newt;
    int ch;
    int oldf;

    tcgetattr(STDIN_FILENO, &oldt);
    newt = oldt;
    newt.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &newt);
    oldf = fcntl(STDIN_FILENO, F_GETFL, 0);
    fcntl(STDIN_FILENO, F_SETFL, oldf | O_NONBLOCK);

    ch = getchar();

    tcsetattr(STDIN_FILENO, TCSANOW, &oldt);
    fcntl(STDIN_FILENO, F_SETFL, oldf);

    if(ch != EOF) {
        ungetc(ch, stdin);
        return 1;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, cleanup);

    gpioSetMode(PAN_PIN, PI_OUTPUT);
    gpioSetMode(TILT_PIN, PI_OUTPUT);

    set_servo_angle(PAN_PIN, pan_angle);
    set_servo_angle(TILT_PIN, tilt_angle);

    printf("Use arrow keys to control the camera mount. Press 'q' to quit.\n");

    while (1) {
        if (kbhit()) {
            char c = getchar();
            switch (c) {
                case 'q':
                    cleanup(0);
                    break;
                case 'A': // Left
                    pan_angle = (pan_angle > MIN_ANGLE) ? pan_angle - 5 : MIN_ANGLE;
                    set_servo_angle(PAN_PIN, pan_angle);
                    break;
                case 'D': // Right
                    pan_angle = (pan_angle < MAX_ANGLE) ? pan_angle + 5 : MAX_ANGLE;
                    set_servo_angle(PAN_PIN, pan_angle);
                    break;
                case 'W': // Up
                    tilt_angle = (tilt_angle < MAX_ANGLE) ? tilt_angle + 5 : MAX_ANGLE;
                    set_servo_angle(TILT_PIN, tilt_angle);
                    break;
                case 'S': // Down
                    tilt_angle = (tilt_angle > MIN_ANGLE) ? tilt_angle - 5 : MIN_ANGLE;
                    set_servo_angle(TILT_PIN, tilt_angle);
                    break;
            }
        }
        usleep(100000); // 100ms delay
    }

    return 0;
}

