#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define FLOW_SENSOR_PIN 17
#define PULSES_PER_LITER 450
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define LOG_INTERVAL 1
#define LCD_UPDATE_INTERVAL 10

volatile sig_atomic_t keep_running = 1;
volatile unsigned int pulse_count = 0;
volatile double total_volume = 0.0;

void signal_handler(int signum) {
    keep_running = 0;
}

void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

void update_lcd(double flow_rate, double volume) {
    char buffer[16];
    snprintf(buffer, sizeof(buffer), "Flow: %.2f L/min", flow_rate);
    gpioI2CWriteI2CBlock(I2C_ADDR, 0x00, buffer, 16);
    snprintf(buffer, sizeof(buffer), "Vol: %.2f L", volume);
    gpioI2CWriteI2CBlock(I2C_ADDR, 0x40, buffer, 16);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-up/down\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(FLOW_SENSOR_PIN, pulse_callback) < 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_log_time = time(NULL);
    time_t last_lcd_update = time(NULL);

    while (keep_running) {
        time_t current_time = time(NULL);

        if (current_time - last_log_time >= LOG_INTERVAL) {
            double flow_rate = (double)pulse_count / PULSES_PER_LITER / LOG_INTERVAL;
            total_volume += flow_rate * LOG_INTERVAL;

            printf("Current Flow Rate: %.2f L/min, Total Volume: %.2f L\n", flow_rate, total_volume);

            pulse_count = 0;
            last_log_time = current_time;
        }

        if (current_time - last_lcd_update >= LCD_UPDATE_INTERVAL) {
            double flow_rate = (double)pulse_count / PULSES_PER_LITER / LCD_UPDATE_INTERVAL;
            update_lcd(flow_rate, total_volume);
            last_lcd_update = current_time;
        }

        gpioDelay(100000); // 100ms delay to prevent busy-waiting
    }

    gpioSetAlertFunc(FLOW_SENSOR_PIN, NULL);
    gpioTerminate();
    return 0;
}

