#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <errno.h>

#define I2C_ADDR 0x27
#define I2C_BUS 1
#define WIND_SPEED_PIN 17
#define ADC_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SAMPLE_INTERVAL_MS 500

static volatile int running = 1;
static volatile int pulse_count = 0;
static int i2c_handle;
static int spi_handle;

void signal_handler(int signo) {
    running = 0;
}

void wind_speed_isr(int gpio, int level, uint32_t tick) {
    pulse_count++;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(WIND_SPEED_PIN, PI_INPUT);
    gpioSetPullUpDown(WIND_SPEED_PIN, PI_PUD_OFF);
    gpioSetAlertFunc(WIND_SPEED_PIN, wind_speed_isr);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C device open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI device open failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        pulse_count = 0;
        gpioDelay(SAMPLE_INTERVAL_MS * 1000);

        float wind_speed = pulse_count * 0.5;
        printf("Wind Speed: %.2f m/s\n", wind_speed);

        unsigned char adc_cmd[3] = {1, (ADC_CHANNEL << 4) | 0x01, 0};
        unsigned char adc_data[3] = {0};

        if (spiXfer(spi_handle, adc_cmd, adc_data, 3) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        int adc_value = ((adc_data[1] & 0x03) << 8) | adc_data[2];
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "ADC reading error: %d\n", adc_value);
            continue;
        }

        float wind_direction = (adc_value / 1023.0) * 360.0;
        printf("Wind Direction: %.2f degrees\n", wind_direction);

        char lcd_buffer[17];
        snprintf(lcd_buffer, sizeof(lcd_buffer), "Spd:%.2f Dir:%.0f", wind_speed, wind_direction);

        if (i2cWriteDevice(i2c_handle, lcd_buffer, strlen(lcd_buffer)) < 0) {
            fprintf(stderr, "I2C write failed\n");
        }
    }

    spiClose(spi_handle);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

