#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define SCAN_DELAY_US 800

const int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
const int col_pins[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

struct gpiod_chip *chip;
struct gpiod_line *row_lines[NUM_ROWS];
struct gpiod_line *col_lines[NUM_COLS];

void cleanup() {
    for (int i = 0; i < NUM_ROWS; i++) {
        gpiod_line_release(row_lines[i]);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        gpiod_line_release(col_lines[i]);
    }
    gpiod_chip_close(chip);
}

void error_exit(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    cleanup();
    exit(EXIT_FAILURE);
}

void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        error_exit("Failed to open GPIO chip");
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            error_exit("Failed to get row line");
        }
        if (gpiod_line_request_output(row_lines[i], "row", 0) < 0) {
            error_exit("Failed to request row line as output");
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            error_exit("Failed to get column line");
        }
        if (gpiod_line_request_output(col_lines[i], "col", 1) < 0) {
            error_exit("Failed to request column line as output");
        }
    }
}

void display_frame(const bool frame[NUM_ROWS][NUM_COLS]) {
    for (int row = 0; row < NUM_ROWS; row++) {
        gpiod_line_set_value(row_lines[row], 1);  // Set row HIGH

        for (int col = 0; col < NUM_COLS; col++) {
            gpiod_line_set_value(col_lines[col], !frame[row][col]);  // Set column LOW if LED should be on
        }

        usleep(SCAN_DELAY_US);

        for (int col = 0; col < NUM_COLS; col++) {
            gpiod_line_set_value(col_lines[col], 1);  // Set column HIGH
        }

        gpiod_line_set_value(row_lines[row], 0);  // Set row LOW
    }
}

void wave_pattern(bool left_to_right) {
    bool frame[NUM_ROWS][NUM_COLS] = {0};

    while (1) {
        for (int i = 0; i < NUM_COLS; i++) {
            int col = left_to_right ? i : NUM_COLS - 1 - i;
            for (int row = 0; row < NUM_ROWS; row++) {
                frame[row][col] = true;
            }
            display_frame(frame);
            for (int row = 0; row < NUM_ROWS; row++) {
                frame[row][col] = false;
            }
        }
    }
}

volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
}

int main() {
    signal(SIGINT, signal_handler);

    setup_gpio();

    printf("Starting wave animation. Press Ctrl+C to exit.\n");

    while (keep_running) {
        wave_pattern(true);   // Left to right
        wave_pattern(false);  // Right to left
    }

    cleanup();
    return 0;
}

