#define COL_PINS[NUM_COLS] = {14, 15, 18, 23, 24, 25, 8, 7}
#define DELAY_MS 150

struct gpiod_chip *chip;
struct gpiod_line *row_lines[NUM_ROWS];
struct gpiod_line *col_lines[NUM_COLS];

void cleanup(int signum) {
    printf("Cleaning up...\n");

    for (int i = 0; i < NUM_ROWS; i++) {
        gpiod_line_release(row_lines[i]);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        gpiod_line_release(col_lines[i]);
    }
    gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, ROW_PINS[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get line for row %d\n", i);
            cleanup(0);
        }
        int ret = gpiod_line_request_output(row_lines[i], "row", 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to request output for row %d\n", i);
            cleanup(0);
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, COL_PINS[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get line for column %d\n", i);
            cleanup(0);
        }
        int ret = gpiod_line_request_output(col_lines[i], "col", 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to request output for column %d\n", i);
            cleanup(0);
        }
    }

    while (1) {
        for (int col = 0; col < NUM_COLS; col++) {
            // Set current column cathode LOW
            gpiod_line_set_value(col_lines[col], 0);

            // Set all row anodes HIGH
            for (int row = 0; row < NUM_ROWS; row++) {
                gpiod_line_set_value(row_lines[row], 1);
            }

            usleep(DELAY_MS * 1000);

            // Clear the matrix
            for (int row = 0; row < NUM_ROWS; row++) {
                gpiod_line_set_value(row_lines[row], 0);
            }
            gpiod_line_set_value(col_lines[col], 1);
        }
    }

    return EXIT_SUCCESS;
}

