#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define SENSOR_ADDRESS 0x29
#define MEASUREMENT_INTERVAL_MS 100

// VL53L3CX Register Addresses (example, adjust as needed)
#define VL53L3CX_MODEL_ID 0xC0
#define VL53L3CX_RESULT_INTERRUPT_STATUS 0x13
#define VL53L3CX_RANGE_STATUS 0x14
#define VL53L3CX_DISTANCE 0x15

// Function prototypes
static void signal_handler(int signo);
static int i2c_read_word(int fd, uint8_t reg, uint16_t *value);
static int i2c_write_word(int fd, uint8_t reg, uint16_t value);
static int initialize_sensor(int i2c_fd);
static void read_sensor_data(int i2c_fd);

// Global flag for graceful shutdown
volatile sig_atomic_t keep_running = 1;

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_fd = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    if (initialize_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        read_sensor_data(i2c_fd);
        gpioSleep(PI_TIME_RELATIVE, 0, MEASUREMENT_INTERVAL_MS * 1000);
    }

    i2cClose(i2c_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

static void signal_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = 0;
    }
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    int ret;
    uint8_t buffer[2];

    ret = i2cReadI2CBlockData(fd, reg, buffer, 2);
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    *value = (buffer[0] << 8) | buffer[1];
    return 0;
}

static int i2c_write_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buffer[3];

    buffer[0] = reg;
    buffer[1] = (value >> 8) & 0xFF;
    buffer[2] = value & 0xFF;

    int ret = i2cWriteI2CBlockData(fd, buffer[0], &buffer[1], 2);
    if (ret < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int initialize_sensor(int i2c_fd) {
    uint16_t model_id;

    // Read and verify model ID
    if (i2c_read_word(i2c_fd, VL53L3CX_MODEL_ID, &model_id) != 0) {
        return -1;
    }

    if (model_id != 0xEEAA) {  // Example expected value, adjust as needed
        fprintf(stderr, "Invalid sensor model ID: 0x%04X\n", model_id);
        return -1;
    }

    // TODO: Implement full sensor initialization sequence
    // This is a placeholder for the complex proprietary initialization
    printf("Sensor initialized. Model ID: 0x%04X\n", model_id);

    return 0;
}

static void read_sensor_data(int i2c_fd) {
    uint16_t interrupt_status, range_status, distance;
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    if (i2c_read_word(i2c_fd, VL53L3CX_RESULT_INTERRUPT_STATUS, &interrupt_status) != 0 ||
        i2c_read_word(i2c_fd, VL53L3CX_RANGE_STATUS, &range_status) != 0 ||
        i2c_read_word(i2c_fd, VL53L3CX_DISTANCE, &distance) != 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return;
    }

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    printf("%s, Interrupt: 0x%04X, Range: 0x%04X, Distance: %d mm\n",
           timestamp, interrupt_status, range_status, distance);
}

