        fclose(log_file);
    }
    if (gpioInitialised()) {
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = gpioI2COpen(I2C_BUS, SENSOR_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", gpioGetErrorText(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
    }

    signal(SIGINT, cleanup);

    time_t last_sample_time = time(NULL);
    while (1) {
        time_t current_time = time(NULL);
        if (difftime(current_time, last_sample_time) * 1000 >= SAMPLE_INTERVAL_MS) {
            char buffer[3];
            int bytes_written = gpioI2CWriteByteData(i2c_handle, REGISTER_ADDR);
            if (bytes_written < 0) {
                fprintf(stderr, "Failed to write register address: %s\n", gpioGetErrorText(bytes_written));
                fprintf(log_file, "%ld,-1\n", (long)current_time);
                fflush(log_file);
                gpioI2CClose(i2c_handle);
                i2c_handle = gpioI2COpen(I2C_BUS, SENSOR_ADDR);
                if (i2c_handle < 0) {
                    fprintf(stderr, "Failed to re-open I2C device: %s\n", gpioGetErrorText(i2c_handle));
                    continue;
                }
            } else {
                int bytes_read = gpioI2CReadI2CBlock(i2c_handle, REGISTER_ADDR, buffer, 2);
                if (bytes_read == 2) {
                    int distance = (buffer[0] << 8) | buffer[1];
                    fprintf(log_file, "%ld,%d\n", (long)current_time, distance);
                    fflush(log_file);
                } else {
                    fprintf(stderr, "Failed to read distance: %s\n", gpioGetErrorText(bytes_read));
                    fprintf(log_file, "%ld,-1\n", (long)current_time);
                    fflush(log_file);
                }
            }
            last_sample_time = current_time;
        }
        gpioSleep(PI_TIME_RELATIVE, 0, SAMPLE_INTERVAL_MS / 1000);
    }

    return EXIT_SUCCESS;
}

