#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define SENSOR_PIN 4
#define LED_PIN 17
#define POLL_INTERVAL_MS 100
#define LOG_FILE "proximity.log"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm tm_info;
    gmtime_r(&now, &tm_info);

    char timestamp[64];
    size_t len = strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_info);
    if (len == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(log_file);
        return;
    }

    fprintf(log_file, "%s %s\n", timestamp, message);
    fclose(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip4, trying gpiochip0\n");
        chip = gpiod_chip_open_by_name("gpiochip0");
        if (chip == NULL) {
            fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (sensor_line == NULL) {
        fprintf(stderr, "Error getting sensor line: %s\n", strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        fprintf(stderr, "Error getting LED line: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor_line, "IR Sensor") < 0) {
        fprintf(stderr, "Error requesting sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    int last_state = 1;  // Assume HIGH (no object) initially

    while (keep_running) {
        int current_state = gpiod_line_get_value(sensor_line);
        if (current_state < 0) {
            fprintf(stderr, "Error reading sensor line: %s\n", strerror(errno));
            break;
        }

        if (current_state == 0 && last_state == 1) {  // LOW to HIGH transition
            log_event("Object detected");
            gpiod_line_set_value(led_line, 1);
            usleep(100000);  // 100ms
            gpiod_line_set_value(led_line, 0);
        }

        last_state = current_state;
        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

