#define PART_ID_REG 0x00
#define HW_KEY_REG 0x07
#define CH_LIST_REG 0x4F
#define COMMAND_REG 0x30
#define PS1_DATA_REG 0x18
#define ALS_VIS_DATA_REG 0x22

#define EXPECTED_PART_ID 0x45
#define ALS_FORCE 0x06
#define PS_FORCE 0x07

static int i2cHandle;
static FILE *logFile;

void cleanup(int sig) {
    if (i2cHandle >= 0) {
        i2cClose(i2cHandle);
    }
    if (logFile) {
        fclose(logFile);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2cHandle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Verify PART_ID
    char partId;
    if (i2cReadByteData(i2cHandle, PART_ID_REG, &partId) < 0 || partId != EXPECTED_PART_ID) {
        fprintf(stderr, "PART_ID verification failed\n");
        cleanup(0);
    }

    // Write to HW_KEY
    if (i2cWriteByteData(i2cHandle, HW_KEY_REG, 0x17) < 0) {
        fprintf(stderr, "Failed to write to HW_KEY\n");
        cleanup(0);
    }

    // Set CH_LIST
    if (i2cWriteByteData(i2cHandle, CH_LIST_REG, 0x07) < 0) {
        fprintf(stderr, "Failed to set CH_LIST\n");
        cleanup(0);
    }

    // Open log file
    logFile = fopen("biometric_data.log", "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
    }

    // Set up signal handler
    signal(SIGINT, cleanup);

    while (1) {
        // Trigger ALS and PS measurements
        if (i2cWriteByteData(i2cHandle, COMMAND_REG, ALS_FORCE) < 0 ||
            i2cWriteByteData(i2cHandle, COMMAND_REG, PS_FORCE) < 0) {
            fprintf(stderr, "Failed to trigger measurements\n");
            cleanup(0);
