static int i2cHandle;
static FILE *logFile;

void cleanup(int sig) {
    if (i2cHandle >= 0) {
        i2cClose(i2cHandle);
    }
    if (logFile) {
        fclose(logFile);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2cHandle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Verify PART_ID
    char partId;
    if (i2cReadByteData(i2cHandle, PART_ID_REG, &partId) < 0 || partId != EXPECTED_PART_ID) {
        fprintf(stderr, "PART_ID verification failed\n");
        cleanup(0);
    }

    // Write to HW_KEY
    if (i2cWriteByteData(i2cHandle, HW_KEY_REG, 0x17) < 0) {
        fprintf(stderr, "Failed to write to HW_KEY\n");
        cleanup(0);
    }

    // Set CH_LIST
    if (i2cWriteByteData(i2cHandle, CH_LIST_REG, 0x07) < 0) {
        fprintf(stderr, "Failed to set CH_LIST\n");
        cleanup(0);
    }

    // Open log file
    logFile = fopen("biometric_data.log", "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
    }

    // Set up signal handler
    signal(SIGINT, cleanup);

    while (1) {
        // Trigger ALS and PS measurements
        if (i2cWriteByteData(i2cHandle, COMMAND_REG, ALS_FORCE) < 0 ||
            i2cWriteByteData(i2cHandle, COMMAND_REG, PS_FORCE) < 0) {
            fprintf(stderr, "Failed to trigger measurements\n");
            cleanup(0);
        }

        // Read ALS_VIS data
        unsigned char alsVisData[2];
        if (i2cReadI2CBlockData(i2cHandle, ALS_VIS_DATA_REG, 2, alsVisData) < 0) {
            fprintf(stderr, "Failed to read ALS_VIS data\n");
            cleanup(0);
        }
        unsigned int alsVis = (unsigned int)alsVisData[1] << 8 | alsVisData[0];

        // Read PS1 data
        unsigned char ps1Data[2];
        if (i2cReadI2CBlockData(i2cHandle, PS1_DATA_REG, 2, ps1Data) < 0) {
            fprintf(stderr, "Failed to read PS1 data\n");
            cleanup(0);
        }
        unsigned int ps1 = (unsigned int)ps1Data[1] << 8 | ps1Data[0];

        // Log data
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        fprintf(logFile, "%s,%u,%u\n", timestamp, ps1, alsVis);
        fflush(logFile);

        gpioSleep(1, 0, 100000000); // Sleep for 1 second
    }

    return EXIT_SUCCESS;
}
