#define TIMEOUT_US 30000
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 400
#define WATER_THRESHOLD_CM 15
#define POLL_INTERVAL_SEC 60
#define LOG_FILE "distance_log.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;
static volatile sig_atomic_t keep_running = 1;

void log_message(const char *message) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    struct gpiod_line_request_config trigger_config = {
        .consumer = "HC-SR04 Trigger",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .flags = 0,
    };

    struct gpiod_line_request_config echo_config = {
        .consumer = "HC-SR04 Echo",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
    };

    struct timespec timeout = {
        .tv_sec = 0,
        .tv_nsec = TIMEOUT_US * 1000,
    };

    struct timespec start_time, end_time;
    long long pulse_duration_ns;
    double distance_cm;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(trigger_line, &trigger_config, 0) < 0) {
        fprintf(stderr, "Failed to request trigger line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(echo_line, &echo_config, 0) < 0) {
        fprintf(stderr, "Failed to request echo line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Send trigger pulse
        gpiod_line_set_value(trigger_line, 1);
        nanosleep(&(struct timespec){0, TRIGGER_PULSE_US * 1000}, NULL);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for echo start
        if (gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, &timeout) < 0) {
            log_message("Error waiting for echo start");
            continue;
        }

        if (gpiod_line_event_get_time(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, &start_time) < 0) {
            log_message("Error getting echo start time");
            continue;
        }

        // Wait for echo end
        if (gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE, &timeout) < 0) {
            log_message("Error waiting for echo end");
            continue;
        }

        if (gpiod_line_event_get_time(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE, &end_time) < 0) {
            log_message("Error getting echo end time");
            continue;
        }

        // Calculate pulse duration
        pulse_duration_ns = (end_time.tv_sec - start_time.tv_sec) * 1000000000LL +
                            (end_time.tv_nsec - start_time.tv_nsec);

        // Calculate distance
        distance_cm = (pulse_duration_ns / 1000000000.0) * 34300.0 / 2.0;

        // Validate distance
        if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Invalid distance: %.2f cm", distance_cm);
            log_message(msg);
            continue;
        }

        // Log distance
        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg), "Distance: %.2f cm", distance_cm);
        log_message(log_msg);

        // Check if it's time to water
        if (distance_cm < WATER_THRESHOLD_CM) {
            log_message("Time to water the plant!");
        }

        // Wait before next measurement
        sleep(POLL_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

