#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define SENSOR_ADDR 0x39
#define SENSOR_ID_REG 0x92
#define SENSOR_ID 0xAB
#define ENABLE_REG 0x80
#define ENABLE_VAL 0x03
#define ATIME_REG 0x81
#define ATIME_VAL 0xDB
#define WTIME_REG 0x83
#define WTIME_VAL 0xF6
#define PPULSE_REG 0x8E
#define PPULSE_VAL 0x87
#define CONTROL_REG 0xF1
#define CONTROL_VAL 0x03
#define CONFIG2_REG 0x90
#define CONFIG2_VAL 0x01
#define PROXIMITY_REG 0x9C
#define PROXIMITY_THRESHOLD 200
#define RGB_DATA_START_REG 0x96
#define I2C_BUS 1
#define LOG_FILE "color_proximity_log.csv"
#define LOG_INTERVAL_MS 100

static int i2cHandle;
static FILE *logFile;

void cleanup(int signum) {
    if (i2cHandle >= 0) {
        gpioI2CClose(i2cHandle);
    }
    if (logFile) {
        fclose(logFile);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int initializeSensor() {
    unsigned char data;
    int retries = 3;

    while (retries--) {
        if (gpioI2CReadByteData(i2cHandle, SENSOR_ID_REG) == SENSOR_ID) {
            gpioI2CWriteByteData(i2cHandle, ENABLE_REG, ENABLE_VAL);
            gpioI2CWriteByteData(i2cHandle, ATIME_REG, ATIME_VAL);
            gpioI2CWriteByteData(i2cHandle, WTIME_REG, WTIME_VAL);
            gpioI2CWriteByteData(i2cHandle, PPULSE_REG, PPULSE_VAL);
            gpioI2CWriteByteData(i2cHandle, CONTROL_REG, CONTROL_VAL);
            gpioI2CWriteByteData(i2cHandle, CONFIG2_REG, CONFIG2_VAL);
            return 0;
        }
        sleep(1);
    }
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2cHandle = gpioI2COpen(I2C_BUS, SENSOR_ADDR);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initializeSensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup(0);
    }

    logFile = fopen(LOG_FILE, "w");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
    }

    fprintf(logFile, "Timestamp,Red,Green,Blue,Proximity\n");

    unsigned char data[8];
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    while (1) {
        if (gpioI2CReadI2CBlock(i2cHandle, PROXIMITY_REG, data, 7) == 7) {
            unsigned int proximity = data[0];
            if (proximity > PROXIMITY_THRESHOLD) {
                time(&now);
                timeinfo = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
                fprintf(logFile, "%s,%d,%d,%d,%d\n", timestamp, data[1], data[2], data[3], proximity);
                fflush(logFile);
            }
        } else {
            fprintf(stderr, "I2C read error, reinitializing sensor\n");
            gpioI2CClose(i2cHandle);
            i2cHandle = gpioI2COpen(I2C_BUS, SENSOR_ADDR);
            if (i2cHandle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus\n");
                cleanup(0);
            }
            if (initializeSensor() != 0) {
                fprintf(stderr, "Sensor re-initialization failed\n");
                cleanup(0);
            }
        }
        time_sleep(100);
    }

    return EXIT_SUCCESS;
}

