#define SLAVE_ADDR 0x5A
#define PART_ID_REG 0x00
#define EXPECTED_PART_ID 0x81
#define MEAS_RATE0_REG 0x08
#define MEAS_RATE0_VALUE 0x00 // Set to a suitable value for your application
#define COMMAND_REG 0x47
#define COMMAND_RESET 0x01
#define PS_DATA0_REG 0x24
#define PS_DATA1_REG 0x25
#define SAMPLE_INTERVAL_MS 100

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

uint16_t combine_bytes(uint8_t low, uint8_t high) {
    return (high << 8) | low;
}

int main() {
    int i2c_fd, csv_fd;
    char filename[] = "heartrate.csv";
    struct i2c_smbus_data data;
    struct timeval tv;
    struct tm *tm_info;
    char timestamp[64];
    uint16_t proximity;
    uint16_t bpm; // Placeholder for BPM calculation

