    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SLAVE_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_smbus_read_byte_data(i2c_fd, PART_ID_REG) != EXPECTED_PART_ID) {
        fprintf(stderr, "Si1182 part ID mismatch\n");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_smbus_write_byte_data(i2c_fd, MEAS_RATE0_REG, MEAS_RATE0_VALUE) < 0) {
        perror("Failed to set measurement rate");
        close(i2c_fd);
        gpioTerminate();
