#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>

#define I2C_BUS 1
#define VL53L0X_ADDRESS 0x29
#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B

volatile int keepRunning = 1;

void intHandler(int dummy) {
    keepRunning = 0;
}

int i2cWrite(int fd, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    int bytesWritten = i2cWriteDevice(fd, VL53L0X_ADDRESS, buf, 2);
    if (bytesWritten < 0) {
        fprintf(stderr, "Error writing to VL53L0X: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2cRead(int fd, uint8_t reg, uint8_t *buf, int len) {
    int bytesRead = i2cReadI2CBlockData(fd, VL53L0X_ADDRESS, reg, buf, len);
    if (bytesRead < 0) {
        fprintf(stderr, "Error reading from VL53L0X: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int checkSensorPresence(int fd) {
    uint8_t buf[1];
    if (i2cRead(fd, SYSRANGE_START, buf, 1) != 0) {
        return -1;
    }
    return 0;
}

int startRangeMeasurement(int fd) {
    return i2cWrite(fd, SYSRANGE_START, 0x01);
}

int waitForInterrupt(int fd) {
    uint8_t status;
    struct timespec start, current;
    clock_gettime(CLOCK_MONOTONIC, &start);
    do {
        if (i2cRead(fd, RESULT_INTERRUPT_STATUS, &status, 1) != 0) {
            return -1;
        }
        clock_gettime(CLOCK_MONOTONIC, &current);
        if ((current.tv_sec - start.tv_sec) > 0 || (current.tv_nsec - start.tv_nsec) > 100000000) {
            fprintf(stderr, "Timeout waiting for interrupt\n");
            return -1;
        }
        usleep(1000); // 1ms delay
    } while (!(status & 0x01));
    return 0;
}

int readDistance(int fd, uint16_t *distance) {
    uint8_t buf[14];
    if (i2cRead(fd, RESULT_RANGE_STATUS, buf, 14) != 0) {
        return -1;
    }
    *distance = (buf[10] << 8) | buf[11];
    return 0;
}

int clearInterrupt(int fd) {
    return i2cWrite(fd, SYSTEM_INTERRUPT_CLEAR, 0x01);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(17, PI_INPUT);
    gpioSetPullUpDown(17, PI_PUD_UP);
    gpioSetAlertFunc(17, intHandler);

    int i2cHandle = i2cOpen(I2C_BUS, VL53L0X_ADDRESS, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (checkSensorPresence(i2cHandle) != 0) {
        fprintf(stderr, "VL53L0X sensor not found at address 0x%02X\n", VL53L0X_ADDRESS);
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    FILE *logFile = fopen("distance_log.txt", "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    time_t lastLogTime = 0;

    while (keepRunning) {
        gpioWaitForEdge(17, EITHER_EDGE, 1000);

        if (startRangeMeasurement(i2cHandle) != 0) {
            continue;
        }

        if (waitForInterrupt(i2cHandle) != 0) {
            continue;
        }

        uint16_t distance;
        if (readDistance(i2cHandle, &distance) != 0) {
            continue;
        }

        if (clearInterrupt(i2cHandle) != 0) {
            continue;
        }

        time_t now = time(NULL);
        if (now != lastLogTime) {
            fprintf(logFile, "%ld,%u\n", (long)now, distance);
            fflush(logFile);
            lastLogTime = now;
        }
    }

    fclose(logFile);
    i2cClose(i2cHandle);
    gpioTerminate();
    return 0;
}

