    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR_PIN_1, PI_INPUT);
    gpioSetMode(SENSOR_PIN_2, PI_INPUT);

    signal(SIGINT, signal_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fclose(log_file);

    while (keep_running) {
        int sensor1_value = gpioRead(SENSOR_PIN_1);
        if (sensor1_value == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading sensor 1\n");
