#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define I2C_BUS 1
#define SENSOR_ADDRESS 0x6A
#define WHO_AM_I_REG 0x00
#define DISTANCE_REG 0x11
#define DEFAULT_THRESHOLD 100
#define LOG_FILE "tof_log.txt"
#define MEASUREMENT_INTERVAL_MS 50

static volatile int keep_running = 1;
static int i2c_handle;
static int gpio_led;
static int distance_threshold;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = 0;
    }
}

int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }
    return 0;
}

void cleanup_pigpio() {
    gpioTerminate();
}

int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        return -1;
    }
    return 0;
}

void cleanup_i2c() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
}

int initialize_gpio() {
    gpio_led = 17;
    gpioSetMode(gpio_led, PI_OUTPUT);
    gpioWrite(gpio_led, PI_LOW);
    return 0;
}

void cleanup_gpio() {
    gpioWrite(gpio_led, PI_LOW);
}

int verify_sensor() {
    char who_am_i;
    int rc = i2cReadByteData(i2c_handle, WHO_AM_I_REG, &who_am_i);
    if (rc < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x20) {
        fprintf(stderr, "Invalid WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }
    return 0;
}

int read_distance(int *distance) {
    unsigned char data[2];
    int rc = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, 2, data);
    if (rc < 0) {
        fprintf(stderr, "Failed to read distance\n");
        return -1;
    }
    *distance = (data[0] << 8) | data[1];
    return 0;
}

void log_distance(int distance) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0';  // Remove newline
    fprintf(log_file, "[%s] Distance: %d mm\n", timestamp, distance);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    if (initialize_pigpio() < 0) {
        return EXIT_FAILURE;
    }

    if (initialize_i2c() < 0) {
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        cleanup_i2c();
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    if (verify_sensor() < 0) {
        cleanup_gpio();
        cleanup_i2c();
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    distance_threshold = (argc > 1) ? atoi(argv[1]) : DEFAULT_THRESHOLD;
    signal(SIGINT, signal_handler);

    while (keep_running) {
        int distance;
        if (read_distance(&distance) == 0) {
            log_distance(distance);
            if (distance < distance_threshold) {
                gpioWrite(gpio_led, PI_HIGH);
            } else {
                gpioWrite(gpio_led, PI_LOW);
            }
        }
        time_sleep(MEASUREMENT_INTERVAL_MS / 1000.0);
    }

    cleanup_gpio();
    cleanup_i2c();
    cleanup_pigpio();
    return EXIT_SUCCESS;
}

