#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x50
#define CMD_FRAME_SIZE 4
#define RESP_FRAME_SIZE 15
#define SAMPLE_COUNT 10
#define MIN_DISTANCE 1000
#define LOG_FILE "intrusion_log.txt"
#define CYCLE_DELAY_MS 100

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int write_command(int fd) {
    uint8_t cmd_frame[CMD_FRAME_SIZE] = {0x50, 0x0A, 0x00, 0x01};
    if (write(fd, cmd_frame, CMD_FRAME_SIZE) != CMD_FRAME_SIZE) {
        perror("Failed to write command frame");
        return -1;
    }
    return 0;
}

int read_response(int fd, uint8_t *response) {
    if (read(fd, response, RESP_FRAME_SIZE) != RESP_FRAME_SIZE) {
        perror("Failed to read response frame");
        return -1;
    }
    return 0;
}

uint16_t extract_distance(uint8_t *response) {
    return (response[11] << 8) | response[12];
}

void log_intrusion(double avg_distance) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0';  // Remove newline

    fprintf(log_file, "[%s] Average distance: %.2f mm\n", timestamp, avg_distance);
    fclose(log_file);
}

int main() {
    int fd;
    uint8_t response[RESP_FRAME_SIZE];
    double total_distance = 0;
    int sample_count = 0;

    signal(SIGINT, signal_handler);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE_FORCE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        total_distance = 0;
        sample_count = 0;

        for (int i = 0; i < SAMPLE_COUNT; i++) {
            if (write_command(fd) < 0) {
                break;
            }

            usleep(10000);  // 10 ms delay

            if (read_response(fd, response) < 0) {
                break;
            }

            if (response[0] != SENSOR_ADDR) {
                fprintf(stderr, "Invalid sensor response\n");
                break;
            }

            uint16_t distance = extract_distance(response);
            total_distance += distance;
            sample_count++;
        }

        if (sample_count > 0) {
            double avg_distance = total_distance / sample_count;
            if (avg_distance < MIN_DISTANCE) {
                log_intrusion(avg_distance);
            }
        }

        usleep(CYCLE_DELAY_MS * 1000);  // 100 ms delay between cycles
    }

    close(fd);
    return EXIT_SUCCESS;
}

