#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define VL53L0X_ADDRESS 0x29
#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B
#define MODEL_ID_REGISTER 0xC0
#define EXPECTED_MODEL_ID 0xEE
#define POLL_TIMEOUT_MS 100
#define MEASUREMENT_INTERVAL_MS 500

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t model_id;
    if (i2cReadByteData(i2c_handle, MODEL_ID_REGISTER, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID: 0x%02X\n", model_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_measurement_time = time(NULL);

    while (keep_running) {
        if (time(NULL) - last_measurement_time >= MEASUREMENT_INTERVAL_MS / 1000) {
            if (i2cWriteByteData(i2c_handle, SYSRANGE_START, 0x01) < 0) {
                fprintf(stderr, "Failed to start ranging: %s\n", strerror(errno));
                continue;
            }

            struct timespec start, current;
            clock_gettime(CLOCK_MONOTONIC, &start);

            do {
                uint8_t interrupt_status;
                if (i2cReadByteData(i2c_handle, RESULT_INTERRUPT_STATUS, &interrupt_status) < 0) {
                    fprintf(stderr, "Failed to read interrupt status: %s\n", strerror(errno));
                    break;
                }

                if (interrupt_status & 0x01) {
                    uint16_t distance;
                    if (i2cReadWordData(i2c_handle, RESULT_RANGE_STATUS, &distance) < 0) {
                        fprintf(stderr, "Failed to read distance: %s\n", strerror(errno));
                        break;
                    }

                    time_t now = time(NULL);
                    struct tm *tm_info = localtime(&now);
                    char timestamp[20];
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

                    printf("%s Distance: %u mm\n", timestamp, distance);

                    if (i2cWriteByteData(i2c_handle, SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
                        fprintf(stderr, "Failed to clear interrupt: %s\n", strerror(errno));
                    }

                    last_measurement_time = now;
                    break;
                }

                clock_gettime(CLOCK_MONOTONIC, &current);
                if ((current.tv_sec - start.tv_sec) * 1000 + (current.tv_nsec - start.tv_nsec) / 1000000 > POLL_TIMEOUT_MS) {
                    fprintf(stderr, "Timeout waiting for interrupt\n");
                    break;
                }

                gpioDelay(1000); // 1ms delay
            } while (keep_running);
        } else {
            gpioDelay(100000); // 100ms delay
        }
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

