#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x39
#define CONFIG_REG 0x18
#define IRQ_STATUS_REG 0x25
#define PROXIMITY_DATA_LSB 0x2A
#define PROXIMITY_DATA_MSB 0x2B
#define PROXIMITY_MODE 0x01
#define DATA_READY_BIT 0x01
#define POLL_INTERVAL_MS 500

static int i2cHandle;

void signalHandler(int signo) {
    if (i2cHandle >= 0) {
        i2cClose(i2cHandle);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signalHandler);

    i2cHandle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Initialize sensor
    char initCmd[] = {CONFIG_REG, PROXIMITY_MODE};
    if (i2cWriteDevice(i2cHandle, initCmd, 2) < 0) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    unsigned char irqStatus;
    unsigned char proximityData[2];

    while (1) {
        // Check if data is ready
        if (i2cReadByteData(i2cHandle, IRQ_STATUS_REG, &irqStatus) < 0) {
            fprintf(stderr, "Failed to read IRQ status\n");
            continue;
        }

        if (irqStatus & DATA_READY_BIT) {
            // Read proximity data
            if (i2cReadI2CBlockData(i2cHandle, PROXIMITY_DATA_LSB, proximityData, 2) < 0) {
                fprintf(stderr, "Failed to read proximity data\n");
                continue;
            }

            unsigned int proximityValue = (proximityData[1] << 8) | proximityData[0];
            printf("Proximity: %u\n", proximityValue);
        }

        gpioSleep(PI_TIME_RELATIVE, 0, POLL_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

