#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <stdint.h>

#define I2C_BUS "/dev/i2c-1"
#define SLAVE_ADDRESS 0x4C
#define REGISTER_DISTANCE 0x00
#define CONVERSION_FACTOR 0.125
#define READ_INTERVAL_NS 500000000L // 500 ms in nanoseconds

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int file;
    uint16_t distance_raw;
    float distance_mm;
    struct timespec sleep_time = {0, READ_INTERVAL_NS};

    // Open I2C bus
    file = open(I2C_BUS, O_RDWR);
    if (file < 0) {
        perror("Failed to open the I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(file, I2C_SLAVE, SLAVE_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(file);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        // Read the distance register
        if (read(file, &distance_raw, 2) != 2) {
            perror("Failed to read from the I2C device");
        } else {
            // Convert raw value to millimeters
            distance_mm = distance_raw * CONVERSION_FACTOR;
            printf("Distance: %.2f mm\n", distance_mm);
        }

        // Sleep for the specified interval
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    close(file);
    return 0;
}

