#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define OPT3101_ADDRESS 0x44
#define READ_INTERVAL_MS 500

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        keep_running = 0;
    }
}

int read_sensor_data(int i2c_handle, uint16_t *distance, uint16_t *ambient_light, uint16_t *error_flags) {
    int result;
    uint8_t buffer[6];

    result = i2cReadI2CBlock(i2c_handle, OPT3101_ADDRESS, buffer, 6);
    if (result < 0) {
        return -1;
    }

    *distance = (buffer[0] << 8) | buffer[1];
    *ambient_light = (buffer[2] << 8) | buffer[3];
    *error_flags = (buffer[4] << 8) | buffer[5];

    return 0;
}

int main() {
    int i2c_handle;
    uint16_t distance, ambient_light, error_flags;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (keep_running) {
        if (read_sensor_data(i2c_handle, &distance, &ambient_light, &error_flags) == 0) {
            printf("Distance: %u mm, Ambient Light: %u, Error Flags: 0x%04X\n", distance, ambient_light, error_flags);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioSleep(PI_TIME_RELATIVE, READ_INTERVAL_MS / 1000, (READ_INTERVAL_MS % 1000) * 1000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

