#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define MAX_DISTANCE_CM 500
#define TIMEOUT_US 200000
#define PULSE_DURATION_US 10
#define SPEED_OF_SOUND_CM_US 0.0343

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

double measure_distance() {
    long start_tick, end_tick, pulse_us;
    int timeout = 0;

    gpioWrite(TRIGGER_PIN, PI_HIGH);
    gpioDelay(PULSE_DURATION_US * 1000);
    gpioWrite(TRIGGER_PIN, PI_LOW);

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Echo rising-edge timeout\n");
            return -1;
        }
    }

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Echo falling-edge timeout\n");
            return -1;
        }
    }

    end_tick = gpioTick();
    pulse_us = end_tick - start_tick;

    if (pulse_us <= 0 || pulse_us > 38000) {
        fprintf(stderr, "Invalid pulse duration: %ld us\n", pulse_us);
        return -1;
    }

    return (pulse_us * SPEED_OF_SOUND_CM_US) / 2.0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_log_time = time(NULL);

    while (keep_running) {
        double distance = measure_distance();
        time_t current_time = time(NULL);

        if (distance >= 0) {
            printf("[%ld] Distance: %.2f cm\n", (long)current_time, distance);
        }

        if (current_time - last_log_time >= 1) {
            last_log_time = current_time;
        }

        gpioDelay(1000000); // 1 second delay
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

