#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>

#define UART_DEV "/dev/serial0"
#define BUFFER_SIZE 136
#define MAGIC_WORD_SIZE 8
#define RANGE_PROFILE_SIZE 128
#define DISTANCE_THRESHOLD 1.0
#define LED_PIN 17
#define LOG_FILE "intrusion_log.csv"

static int uart_fd = -1;
static FILE *log_file = NULL;

void cleanup(int signum) {
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int init_uart() {
    struct termios options;

    uart_fd = open(UART_DEV, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("Error opening UART device");
        return -1;
    }

    if (tcgetattr(uart_fd, &options) == -1) {
        perror("Error getting UART attributes");
        close(uart_fd);
        return -1;
    }

    cfsetispeed(&options, B115200);
    cfsetospeed(&options, B115200);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;
    options.c_cc[VMIN] = 0;
    options.c_cc[VTIME] = 10;

    if (tcsetattr(uart_fd, TCSANOW, &options) == -1) {
        perror("Error setting UART attributes");
        close(uart_fd);
        return -1;
    }

    return 0;
}

int read_range_profile(uint16_t *range_profile) {
    uint8_t buffer[BUFFER_SIZE];
    uint8_t magic_word[MAGIC_WORD_SIZE] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    ssize_t bytes_read;

    bytes_read = read(uart_fd, buffer, BUFFER_SIZE);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read != BUFFER_SIZE) {
        fprintf(stderr, "Unexpected number of bytes read: %zd\n", bytes_read);
        return -1;
    }

    if (memcmp(buffer, magic_word, MAGIC_WORD_SIZE) != 0) {
        fprintf(stderr, "Invalid magic word\n");
        return -1;
    }

    for (int i = 0; i < RANGE_PROFILE_SIZE / 2; i++) {
        range_profile[i] = (buffer[MAGIC_WORD_SIZE + 2 * i + 1] << 8) | buffer[MAGIC_WORD_SIZE + 2 * i];
    }

    return 0;
}

void log_intrusion(double distance) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s,%.3f\n", timestamp, distance);
    fflush(log_file);
}

int main() {
    uint16_t range_profile[RANGE_PROFILE_SIZE / 2];
    double distance;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    if (init_uart() != 0) {
        fprintf(stderr, "Error initializing UART\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        if (read_range_profile(range_profile) != 0) {
            fprintf(stderr, "Error reading range profile\n");
            continue;
        }

        for (int i = 0; i < RANGE_PROFILE_SIZE / 2; i++) {
            distance = i * 0.0486;
            if (distance <= DISTANCE_THRESHOLD) {
                gpioWrite(LED_PIN, 1);
                log_intrusion(distance);
                usleep(2000000);
                gpioWrite(LED_PIN, 0);
                break;
            }
        }
    }

    return EXIT_SUCCESS;
}

