#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x69
#define DISTANCE_HIGH_REG 0x31
#define DISTANCE_LOW_REG 0x32
#define ALERT_PIN 17
#define SAMPLE_INTERVAL_MS 100
#define DISTANCE_THRESHOLD 10.0

static volatile int keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        keep_running = 0;
    }
}

int read_distance(int i2c_handle) {
    uint8_t high_byte, low_byte;
    int ret;

    ret = i2cReadByteData(i2c_handle, DISTANCE_HIGH_REG, &high_byte);
    if (ret < 0) {
        fprintf(stderr, "Error reading high byte: %s\n", strerror(errno));
        return -1;
    }

    ret = i2cReadByteData(i2c_handle, DISTANCE_LOW_REG, &low_byte);
    if (ret < 0) {
        fprintf(stderr, "Error reading low byte: %s\n", strerror(errno));
        return -1;
    }

    return (high_byte << 8) | low_byte;
}

int main() {
    int i2c_handle, gpio_handle;
    FILE *log_file;
    time_t now;
    struct tm *tm_info;
    char timestamp[64];
    int distance;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpio_set_mode(ALERT_PIN, PI_OUTPUT);

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d for device 0x%02X: %s\n", I2C_BUS, SENSOR_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        distance = read_distance(i2c_handle);
        if (distance < 0) {
            continue;
        }

        time(&now);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

        fprintf(log_file, "%s, %d\n", timestamp, distance);
        fflush(log_file);

        if (distance < DISTANCE_THRESHOLD) {
            gpioWrite(ALERT_PIN, 1);
        } else {
            gpioWrite(ALERT_PIN, 0);
        }

        gpioSleep(PI_TIME_RELATIVE, 0, SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

