#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <string.h>

#define I2C_BUS 1
#define VL53L1X_ADDRESS 0x29
#define MODEL_ID_REGISTER 0x010F
#define MODEL_ID_VALUE 0xEA
#define SYSTEM_RESET_REGISTER 0x0000
#define SYSTEM_MODE_START_REGISTER 0x007
#define SYSRANGE__START_REGISTER 0x000
#define RESULT__INTERRUPT_STATUS_REGISTER 0x013
#define RESULT__RANGE_STATUS_REGISTER 0x078
#define SYSTEM__INTERRUPT_CLEAR_REGISTER 0x014

#define POLL_TIMEOUT_MS 100
#define LOG_FILE_NAME "distance_log.csv"

static int i2cHandle;
static FILE *logFile;

void cleanup(int signum) {
    if (i2cHandle >= 0) {
        i2cClose(i2cHandle);
    }
    if (logFile) {
        fclose(logFile);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2cHandle = i2cOpen(I2C_BUS, VL53L1X_ADDRESS, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t modelId;
    if (i2cReadWordData(i2cHandle, MODEL_ID_REGISTER, &modelId) < 0 || modelId != MODEL_ID_VALUE) {
        fprintf(stderr, "VL53L1X sensor not found or incorrect model ID\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2cHandle, SYSTEM_RESET_REGISTER, 0x00) < 0) {
        fprintf(stderr, "Failed to reset VL53L1X sensor\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    time_sleep(2);

    if (i2cWriteByteData(i2cHandle, SYSTEM_MODE_START_REGISTER, 0x01) < 0) {
        fprintf(stderr, "Failed to start VL53L1X sensor\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    unsigned char startStatus;
    do {
        if (i2cReadByteData(i2cHandle, SYSRANGE__START_REGISTER, &startStatus) < 0) {
            fprintf(stderr, "Failed to read SYSRANGE__START register\n");
            i2cClose(i2cHandle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        time_sleep(POLL_TIMEOUT_MS / 1000.0);
    } while (startStatus & 0x01);

    logFile = fopen(LOG_FILE_NAME, "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ftell(logFile) == 0) {
        fprintf(logFile, "timestamp,distance_mm\n");
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        unsigned char interruptStatus;
        if (i2cReadByteData(i2cHandle, RESULT__INTERRUPT_STATUS_REGISTER, &interruptStatus) < 0) {
            fprintf(stderr, "Failed to read RESULT__INTERRUPT_STATUS register\n");
            continue;
