#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define SENSOR_ADDR 0x45
#define I2C_BUS 1
#define LED_PIN 18
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

volatile int keep_running = 1;

void signal_handler(int signo) {
    keep_running = 0;
}

int i2c_retry(int fd, char *buf, int count, int retry_count) {
    int retries = 0;
    while (retries < retry_count) {
        if (i2cReadI2CBlock(fd, SENSOR_ADDR, buf, count) == count) {
            return 0;
        }
        gpioSleep(MILLISECONDS, 0, RETRY_DELAY_MS);
        retries++;
    }
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_LOW);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct timespec start, current;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (keep_running) {
        unsigned char buf[2];
        if (i2c_retry(i2c_handle, buf, 2, MAX_RETRIES) != 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            continue;
        }

        unsigned short distance = (buf[0] << 8) | buf[1];
        clock_gettime(CLOCK_MONOTONIC, &current);
        double elapsed = (current.tv_sec - start.tv_sec) + (current.tv_nsec - start.tv_nsec) / 1e9;

        double blink_freq;
        if (distance <= 50) {
            blink_freq = 10.0;
        } else if (distance <= 500) {
            blink_freq = 10.0 - (distance - 50) / 450.0 * 9.0;
        } else {
            blink_freq = 1.0;
        }

        int blink_duration = (int)(1000.0 / (2.0 * blink_freq));
        gpioWrite(LED_PIN, PI_HIGH);
        gpioSleep(MILLISECONDS, 0, blink_duration);
        gpioWrite(LED_PIN, PI_LOW);
        gpioSleep(MILLISECONDS, 0, blink_duration);

        printf("%.3f: Distance: %d mm, Blink Frequency: %.2f Hz\n", elapsed, distance, blink_freq);

        gpioSleep(MILLISECONDS, 0, SAMPLE_INTERVAL_MS);
    }

    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, PI_LOW);
    gpioTerminate();

    return 0;
}

