    int retries = 0;
    int result;
    do {
        result = i2cReadDevice(i2c_handle, buf, len);
        if (result < 0) {
            fprintf(stderr, "I2C read error: %s\n", gpioStrError(result));
            usleep(RETRY_DELAY_MS * 1000);
        }
    } while (result < 0 && retries++ < RETRY_COUNT);
    return result;
}

