#include <time.h>
#include <unistd.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 27
#define POLL_INTERVAL_MS 10
#define DEBOUNCE_TIME_MS 50

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_event(int sensor_id, const char* event_type) {
    FILE* log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now;
    struct tm* utc_time;
    char timestamp[64];

    time(&now);
    utc_time = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0 || gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int sensor_1_state = gpioRead(SENSOR_1_PIN);
    int sensor_2_state = gpioRead(SENSOR_2_PIN);
    time_t last_change_1 = time(NULL);
    time_t last_change_2 = time(NULL);

    while (keep_running) {
        int current_sensor_1_state = gpioRead(SENSOR_1_PIN);
        int current_sensor_2_state = gpioRead(SENSOR_2_PIN);

        if (current_sensor_1_state != sensor_1_state) {
            time_t now = time(NULL);
            if (difftime(now, last_change_1) * 1000 >= DEBOUNCE_TIME_MS) {
                if (current_sensor_1_state == PI_LOW) {
                    log_event(1, "DETECTED");
                } else {
                    log_event(1, "CLEARED");
                }
                sensor_1_state = current_sensor_1_state;
                last_change_1 = now;
            }
        }

        if (current_sensor_2_state != sensor_2_state) {
            time_t now = time(NULL);
            if (difftime(now, last_change_2) * 1000 >= DEBOUNCE_TIME_MS) {
                if (current_sensor_2_state == PI_LOW) {
                    log_event(2, "DETECTED");
                } else {
                    log_event(2, "CLEARED");
                }
                sensor_2_state = current_sensor_2_state;
                last_change_2 = now;
            }
        }

        time_sleep(POLL_INTERVAL_MS / 1000.0);
    }

    gpioTerminate();
    return 0;
}

