#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x49
#define MEAS_TRIGGER_REG 0x04
#define MEAS_STATUS_REG 0x06
#define DIST_HIGH_REG 0x08
#define DIST_LOW_REG 0x09
#define DATA_READY_BIT 0x01
#define MEASUREMENT_TIMEOUT_MS 50
#define SAMPLE_INTERVAL_MS 500

static int i2c_fd;
static FILE *csv_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (csv_file) {
        fflush(csv_file);
        fclose(csv_file);
    }
    syslog(LOG_INFO, "Shutting down gracefully.");
