#include <errno.h>
#include <string.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define VL53L5CX_I2C_ADDR 0x29
#define VL53L5CX_RESULT__RANGE_STATUS 0x14
#define VL53L5CX_NUMBER_OF_ZONES 64
#define READ_INTERVAL_MS 500

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int i2c_write(int file, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    return write(file, buf, 2);
}

int i2c_read(int file, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(file, &reg, 1) != 1) {
        return -1;
    }
    return read(file, buf, len);
}

int init_sensor(int file) {
    // Power on the sensor
    if (i2c_write(file, 0x0000, 0x01) != 2) return -1;
    usleep(10000); // 10ms delay

    // Set the sensor to continuous mode
    if (i2c_write(file, 0x0001, 0x00) != 2) return -1;
    usleep(10000); // 10ms delay

    // Configure the sensor for 8x8 zones
    if (i2c_write(file, 0x001E, 0x01) != 2) return -1;
    if (i2c_write(file, 0x001F, 0x01) != 2) return -1;

    return 0;
}

int main() {
    int file;
    uint8_t buf[2];
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    file = open(I2C_BUS, O_RDWR);
    if (file < 0) {
        perror("Failed to open the I2C bus");
        return 1;
    }

    if (ioctl(file, I2C_SLAVE, VL53L5CX_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return 1;
    }

    if (init_sensor(file) != 0) {
        fprintf(stderr, "Failed to initialize the sensor\n");
        close(file);
        return 1;
    }

    printf("Reading distances from VL53L5CX sensor...\n");

    while (keep_running) {
        for (int zone = 0; zone < VL53L5CX_NUMBER_OF_ZONES; zone++) {
            if (i2c_read(file, VL53L5CX_RESULT__RANGE_STATUS + zone * 2, buf, 2) != 2) {
                fprintf(stderr, "Failed to read distance for zone %d\n", zone);
                close(file);
                return 1;
            }
            uint16_t distance = (buf[1] << 8) | buf[0];
            printf("Zone %2d: %5d mm\n", zone, distance);
        }
        printf("\n");
        usleep(READ_INTERVAL_MS * 1000);
    }

    close(file);
    return 0;
}

