#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define SENSOR_ADDRESS 0x4C
#define MEASUREMENT_INTERVAL_MS 100
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int i2c_read_retry(int handle, uint8_t *buf, int count) {
    int retries = 0;
    int result;
    do {
        result = i2cReadI2CBlock(handle, SENSOR_ADDRESS, buf, count);
        if (result < 0) {
            gpioDelay(RETRY_DELAY_MS * 1000);
            retries++;
        }
    } while (result < 0 && retries < MAX_RETRIES);
    return result;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    uint8_t buffer[2];
    struct timespec ts;
    long long last_time_ms = 0;

    while (keep_running) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        long long current_time_ms = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

        if (current_time_ms - last_time_ms >= MEASUREMENT_INTERVAL_MS) {
            int result = i2c_read_retry(i2c_handle, buffer, 2);
            if (result == 2) {
                int distance = (buffer[0] << 8) | buffer[1];
                printf("%lld: Distance: %d mm\n", current_time_ms, distance);
            } else {
                fprintf(stderr, "Failed to read from sensor\n");
            }
            last_time_ms = current_time_ms;
        }
        gpioDelay(1000); // Sleep for 1ms to avoid busy-waiting
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

