#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define I2C_BUS 1
#define SENSOR_ADDRESS 0x29
#define SOFT_RESET_REG 0x7FFF
#define START_RANGING_REG 0x0009
#define INTERRUPT_STATUS_REG 0x0046
#define DISTANCE_HIGH_REG 0x0096
#define DISTANCE_LOW_REG 0x0097

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_distance(uint16_t distance) {
    struct timespec ts;
    char timestamp[64];

    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm *tm_info = localtime(&ts.tv_sec);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    printf("Timestamp: %s.%06ld, Distance: %u mm\n", timestamp, ts.tv_nsec / 1000, distance);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Soft reset
    if (i2cWriteWordData(i2c_handle, SOFT_RESET_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to perform soft reset\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    time_sleep(10);

    // Start ranging
    if (i2cWriteWordData(i2c_handle, START_RANGING_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        uint8_t interrupt_status;
        if (i2cReadByteData(i2c_handle, INTERRUPT_STATUS_REG, &interrupt_status) < 0) {
            fprintf(stderr, "Failed to read interrupt status\n");
            continue;
        }

        if (interrupt_status & 0x01) {
            uint16_t distance;
            uint8_t high_byte, low_byte;

            if (i2cReadByteData(i2c_handle, DISTANCE_HIGH_REG, &high_byte) < 0 ||
                i2cReadByteData(i2c_handle, DISTANCE_LOW_REG, &low_byte) < 0) {
                fprintf(stderr, "Failed to read distance data\n");
                continue;
            }

            distance = (high_byte << 8) | low_byte;
            log_distance(distance);
        }

        time_sleep(500);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

