#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17
#define SPEED_OF_SOUND 343.0 // m/s
#define MIN_DISTANCE 2 // cm
#define MAX_DISTANCE 400 // cm
#define TIMEOUT 50000 // 50 ms in microseconds
#define LOG_INTERVAL 200 // ms

volatile int keep_running = 1;

void signal_handler(int signo) {
    keep_running = 0;
}

double measure_distance() {
    gpioWrite(TRIG_PIN, PI_HIGH);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIG_PIN, PI_LOW);

    long start_tick = gpioTick();
    long end_tick;
    int timeout = 0;

    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT) {
            timeout = 1;
            break;
        }
    }

    if (timeout) return -1.0; // Sentinel value for timeout

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT) {
            timeout = 1;
            break;
        }
    }

    if (timeout) return -1.0; // Sentinel value for timeout

    end_tick = gpioTick();
    long travel_time = end_tick - start_tick;
    double distance = (travel_time * SPEED_OF_SOUND) / 20000.0; // Convert to cm

    return distance;
}

int map_distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE) return -90;
    if (distance > MAX_DISTANCE) return 90;
    return (int)((distance - MIN_DISTANCE) * 180 / (MAX_DISTANCE - MIN_DISTANCE)) - 90;
}

void set_servo_angle(int angle) {
    int pulse_width = 500 + angle * 2000 / 180; // Map -90 to 1 ms, 90 to 2 ms
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIG_PIN, PI_LOW);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen("sensor_data.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    time_t last_log_time = time(NULL);

    while (keep_running) {
        double distance = measure_distance();
        if (distance >= 0) {
            int angle = map_distance_to_angle(distance);
            set_servo_angle(angle);

            time_t current_time = time(NULL);
            if (difftime(current_time, last_log_time) >= LOG_INTERVAL / 1000.0) {
                fprintf(log_file, "[%ld] Distance: %.2f cm, Angle: %d degrees\n",
                        (long)current_time, distance, angle);
                fflush(log_file);
                last_log_time = current_time;
            }
        }
        gpioDelay(10000); // 10 ms delay between readings
    }

    fclose(log_file);
    set_servo_angle(0); // Stop the servo
    gpioTerminate();
    return 0;
}

