#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <mqueue.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define VL53L1X_ADDRESS 0x29
#define MODEL_ID_REG 0x010F
#define MODEL_ID_EXPECTED 0xEA
#define SOFT_RESET_REG 0x0000
#define SOFT_RESET_CMD1 0x00
#define SOFT_RESET_CMD2 0x01
#define TIMING_BUDGET_REG 0x0009
#define TIMING_BUDGET_VALUE 0x32
#define SYSTEM_INTERRUPT_REG 0x0089
#define SYSTEM_INTERRUPT_READY 0x01
#define RESULT_RANGE_STATUS_REG 0x0096
#define BUZZER_PIN 23
#define MQ_NAME "/vl53l1x_distance"

static int i2cHandle;
static mqd_t mq;

void cleanup(int signum) {
    if (mq != (mqd_t)-1) {
        mq_close(mq);
        mq_unlink(MQ_NAME);
    }
    if (i2cHandle >= 0) {
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2cHandle = i2cOpen(I2C_BUS, VL53L1X_ADDRESS, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "I2C device open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct mq_attr attr = {
        .mq_flags = 0,
        .mq_maxmsg = 10,
        .mq_msgsize = sizeof(int),
        .mq_curmsgs = 0,
    };

    mq = mq_open(MQ_NAME, O_CREAT | O_RDWR, 0644, &attr);
    if (mq == (mqd_t)-1) {
        fprintf(stderr, "Message queue creation failed\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t modelId;
    if (i2cReadByteData(i2cHandle, MODEL_ID_REG, &modelId) < 0 || modelId != MODEL_ID_EXPECTED) {
        fprintf(stderr, "Sensor model ID check failed\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2cHandle, SOFT_RESET_REG, SOFT_RESET_CMD1) < 0 ||
        i2cWriteByteData(i2cHandle, SOFT_RESET_REG, SOFT_RESET_CMD2) < 0) {
        fprintf(stderr, "Software reset failed\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    if (i2cWriteByteData(i2cHandle, TIMING_BUDGET_REG, TIMING_BUDGET_VALUE) < 0) {
        fprintf(stderr, "Timing budget configuration failed\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2cHandle, SYSTEM_INTERRUPT_REG, 0x01) < 0) {
        fprintf(stderr, "Start ranging failed\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t interruptStatus;
        if (i2cReadByteData(i2cHandle, SYSTEM_INTERRUPT_REG, &interruptStatus) < 0 ||
            (interruptStatus & SYSTEM_INTERRUPT_READY) == 0) {
            usleep(50000);
            continue;
        }

        uint16_t distance;
        if (i2cReadWordData(i2cHandle, RESULT_RANGE_STATUS_REG, &distance) < 0) {
            fprintf(stderr, "Failed to read distance\n");
            continue;
        }

        if (mq_send(mq, (char *)&distance, sizeof(distance), 0) == -1) {
            fprintf(stderr, "Failed to send message to queue\n");
        }

        if (distance < 100) {
            gpioWrite(BUZZER_PIN, PI_HIGH);
        } else {
            gpioWrite(BUZZER_PIN, PI_LOW);
        }

        i2cWriteByteData(i2cHandle, SYSTEM_INTERRUPT_REG, 0x01);
        usleep(50000);
    }

    return EXIT_SUCCESS;
}

