volatile uint32_t start_tick = 0;
volatile uint32_t end_tick = 0;
volatile int timeout = 0;

void trigger_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        start_tick = tick;
    } else {
        end_tick = tick;
        trigger_high = 0;
    }
}

void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        start_tick = tick;
    } else {
        end_tick = tick;
        trigger_high = 0;
    }
}

uint32_t get_tick_diff(uint32_t start, uint32_t end) {
    if (end >= start) {
        return end - start;
    } else {
        return (0xFFFFFFFF - start) + end + 1;
    }
}

void handle_sigint(int signo) {
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "GPIO mode configuration failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Failed to set echo alert function\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        gpioWrite(TRIG_PIN, 0);
        gpioSleep(1, 0, 50000); // 50 ms delay

        gpioWrite(TRIG_PIN, 1);
        gpioSleep(1, 0, 10); // 10 microsecond pulse
        gpioWrite(TRIG_PIN, 0);

        trigger_high = 1;
        timeout = 0;

        gpioSetAlertFuncEx(ECHO_PIN, echo_callback);

        gpioSleep(1, 0, 100000); // Wait for echo or timeout

        uint32_t duration = get_tick_diff(start_tick, end_tick);
        float distance = (float)duration / 1000000.0 * SPEED_OF_SOUND;

        if (timeout) {
            printf("Sensor timeout or no echo\n");
        } else if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Invalid reading: %.2f cm\n", distance);
        } else {
            printf("Distance: %.2f cm\n", distance);
            if (distance < BUZZER_THRESHOLD) {
                gpioWrite(BUZZER_PIN, 1);
            } else {
                gpioWrite(BUZZER_PIN, 0);
            }
        }

        gpioSleep(1, 0, MEASURE_INTERVAL - 100000); // Adjust for processing time
    }

    return 0;
}
