#define MAX_RETRIES 3
#define DISTANCE_THRESHOLD 2000 // 20 cm in mm

static VL53L1_Dev_t dev;
static volatile sig_atomic_t keep_running = 1;
static MQTTClient client;

void log_event(const char* event) {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        time_t now = time(NULL);
        char* timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] %s\n", timestamp, event);
        fclose(log_file);
    }
}

int init_vl53l1x() {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (VL53L1_Initialize(&dev) == VL53L1_ERROR_NONE) {
            if (VL53L1_SetDeviceAddress(&dev, VL53L1X_ADDR) == VL53L1_ERROR_NONE) {
                if (VL53L1_DataInitialization(&dev) == VL53L1_ERROR_NONE) {
                    VL53L1_SetDeviceMode(&dev, VL53L1_DEVICEMODE_SINGLE_RANGING);
                    return 0;
                }
            }
        }
        gpioDelay(1000000); // 1 second delay
        retries++;
    }
    return -1;
}

uint16_t read_distance() {
    VL53L1_RangingMeasurementData_t measure;
    if (VL53L1_PerformSingleRangingMeasurement(&dev, &measure) == VL53L1_ERROR_NONE) {
        return measure.RangeMilliMeter;
    }
    return 0xFFFF; // Indicate error
}

void set_servo(int position) {
    gpioServoWrite(SERVO_PIN, position);
}

void open_gate() {
    set_servo(180); // Assuming 180 degrees is open
    log_event("Gate opened");
}

void close_gate() {
    set_servo(0); // Assuming 0 degrees is closed
    log_event("Gate closed");
}

int mqtt_connected(void* context, MQTTClient client) {
    MQTTClient_subscribe(client, MQTT_TOPIC, 0, NULL);
    return 1;
}

void mqtt_message_arrived(void* context, char* topicName, int topicLen, MQTTClient_message* message) {
    char* payload = (char*)message->payload;
    if (strcmp(payload, "force_open") == 0) {
        open_gate();
    } else if (strcmp(payload, "force_close") == 0) {
        close_gate();
    } else if (strcmp(payload, "status_request") == 0) {
        // Implement status reporting logic here
    }
    MQTTClient_freeMessage(&message);
    MQTTClient_free(topicName);
}

void signal_handler(int signo) {
    keep_running = 0;
