    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50Hz for SG90 servo

    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        gpioTerminate();
        return 1;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    conn_opts.onConnected = mqtt_connected;

    if (MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID,
                          MQTTCLIENT_PERSISTENCE_NONE, NULL) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client\n");
        VL53L1_ShutdownDevice(&dev);
        gpioTerminate();
        return 1;
    }

    if (MQTTClient_setCallbacks(client, NULL, mqtt_message_arrived, NULL) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to set MQTT callbacks\n");
        MQTTClient_destroy(&client);
        VL53L1_ShutdownDevice(&dev);
        gpioTerminate();
        return 1;
    }

    if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        MQTTClient_destroy(&client);
        VL53L1_ShutdownDevice(&dev);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        uint16_t distance = read_distance();
        if (distance == 0xFFFF) {
            fprintf(stderr, "Error reading distance\n");
        } else if (distance <= DISTANCE_THRESHOLD) {
            open_gate();
        } else {
            close_gate();
        }
        gpioDelay(1000000); // 1 second delay between checks
    }

    MQTTClient_disconnect(client, 10000);
    MQTTClient_destroy(&client);
    VL53L1_ShutdownDevice(&dev);
    gpioTerminate();
    return 0;
}

