#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define MEASURE_INTERVAL 200000 // 200 ms
#define TIMEOUT 60000 // 60 ms
#define MIN_PULSE_WIDTH 100 // microseconds
#define MAX_PULSE_WIDTH 30000 // microseconds
#define SPEED_OF_SOUND 0.0343 // cm/us

static FILE *log_file;

void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void alert_callback(int gpio, int level, uint32_t tick) {
    static uint32_t rising_tick = 0;
    static uint32_t falling_tick = 0;

    if (level == PI_HIGH) {
        rising_tick = tick;
    } else if (level == PI_LOW) {
        falling_tick = tick;
        if (rising_tick != 0) {
            uint32_t duration = gpioTickDiff(falling_tick, rising_tick);
            if (duration >= MIN_PULSE_WIDTH && duration <= MAX_PULSE_WIDTH) {
                double distance = (duration * SPEED_OF_SOUND) / 2.0;
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                char timestamp[64];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

                fprintf(stdout, "%s Distance: %.2f cm\n", timestamp, distance);
                fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
                fflush(log_file);
            } else {
                fprintf(stdout, "Warning: Invalid pulse width %u us\n", duration);
                fprintf(log_file, "Warning: Invalid pulse width %u us\n", duration);
                fflush(log_file);
            }
        }
        rising_tick = 0;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    gpioSetAlertFunc(ECHO_PIN, alert_callback);

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        gpioWrite(TRIG_PIN, PI_HIGH);
        gpioDelay(10); // 10 microseconds
        gpioWrite(TRIG_PIN, PI_LOW);

        gpioDelay(TIMEOUT);

        if (gpioRead(ECHO_PIN) == PI_LOW) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

            fprintf(stdout, "%s Warning: No valid echo received\n", timestamp);
            fprintf(log_file, "%s Warning: No valid echo received\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(MEASURE_INTERVAL - TIMEOUT);
    }

    return EXIT_SUCCESS;
}

