#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <vl53l1_platform.h>
#include <vl53l1_api.h>

#define VL53L1X_ADDR 0x29
#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24
#define SERVO_PIN 18
#define OPEN_ANGLE 1200
#define CLOSED_ANGLE 600
#define OPEN_DISTANCE 50
#define CLOSED_DISTANCE 60

VL53L1_Dev_t dev;
FILE *logfile;

void log_state(const char *state, int distance) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0';
    fprintf(logfile, "[%s] State: %s, Distance: %d cm\n", time_str, state, distance);
    fflush(logfile);
}

void set_servo_angle(int angle) {
    gpioServo(SERVO_PIN, angle);
}

void open_gate() {
    set_servo_angle(OPEN_ANGLE);
    log_state("OPEN", 0);
}

void close_gate() {
    set_servo_angle(CLOSED_ANGLE);
    log_state("CLOSED", 0);
}

void handle_interrupt(int gpio, int level, uint32_t tick) {
    VL53L1_UINT16 distance;
    VL53L1_GetDistance(&dev, &distance);
    if (distance < OPEN_DISTANCE) {
        open_gate();
    } else if (distance > CLOSED_DISTANCE) {
        close_gate();
    }
}

void cleanup(int signum) {
    VL53L1_StopMeasurement(&dev);
    VL53L1_ShutdownDevice(&dev);
    gpioSetMode(SHUTDOWN_PIN, PI_INPUT);
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_INPUT);
    gpioTerminate();
    fclose(logfile);
    exit(0);
}

int main() {
    VL53L1_UINT8 sensor_id;
    VL53L1_UINT16 distance;
    VL53L1_Error status;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    logfile = fopen("parking_log.txt", "a");
    if (!logfile) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT);
    gpioWrite(SHUTDOWN_PIN, 1);
    gpioSleep(1, 1);

    status = VL53L1_Init(&dev, VL53L1X_ADDR);
    if (status != VL53L1_ERROR_NONE) {
        fprintf(stderr, "VL53L1 initialization failed: %d\n", status);
        cleanup(0);
        return 1;
    }

    status = VL53L1_GetSensorId(&dev, &sensor_id);
    if (status != VL53L1_ERROR_NONE || sensor_id != 0xEB) {
        fprintf(stderr, "Invalid sensor ID: 0x%02X\n", sensor_id);
        cleanup(0);
        return 1;
    }

    status = VL53L1_StartMeasurement(&dev);
    if (status != VL53L1_ERROR_NONE) {
        fprintf(stderr, "Failed to start VL53L1 measurement: %d\n", status);
        cleanup(0);
        return 1;
    }

    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_DOWN);
    gpioSetAlertFunc(INTERRUPT_PIN, handle_interrupt);

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 50);

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        gpioSleep(1, 1);
    }

    return 0;
}

