#define OPEN_GPIO 18
#define CLOSE_GPIO 19
#define DISTANCE_REGISTER 0x14
#define TIMING_BUDGET_REGISTER 0x000D
#define TIMING_BUDGET 50000 // 50 ms
#define POLL_INTERVAL_MS 500
#define MAX_DISTANCE 200 // 200 mm

static FILE *logfile;
static int i2c_handle;

void log_event(const char *event) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(logfile, "%s: %s\n", timestamp, event);
    fflush(logfile);
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_event("Shutting down");
        gpioWrite(OPEN_GPIO, 0);
        gpioWrite(CLOSE_GPIO, 0);
        gpioTerminate();
        if (i2c_handle >= 0) {
            close(i2c_handle);
        }
        if (logfile) {
            fclose(logfile);
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpioSetMode(OPEN_GPIO, PI_OUTPUT);
    gpioSetMode(CLOSE_GPIO, PI_OUTPUT);

    logfile = fopen("gate_events.log", "a");
    if (!logfile) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        fclose(logfile);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // VL53L1X soft reset
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x00) < 0) {
        fprintf(stderr, "Failed to reset VL53L1X\n");
        close(i2c_handle);
        fclose(logfile);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    usleep(10000); // 10 ms delay

    // Configure timing budget
    if (i2cWriteWordData(i2c_handle, TIMING_BUDGET_REGISTER, TIMING_BUDGET) < 0) {
        fprintf(stderr, "Failed to set timing budget\n");
        close(i2c_handle);
        fclose(logfile);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, 0x001E, 0x01) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        close(i2c_handle);
        fclose(logfile);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Gate control system started");

    while (1) {
        uint16_t distance;
        int rc = i2cReadWordData(i2c_handle, DISTANCE_REGISTER);
        if (rc < 0) {
            fprintf(stderr, "Failed to read distance\n");
            log_event("Error reading distance");
        } else {
            distance = rc;
            if (distance <= MAX_DISTANCE) {
                gpioWrite(OPEN_GPIO, 1);
                gpioWrite(CLOSE_GPIO, 0);
                log_event("Gate opened");
            } else {
                gpioWrite(OPEN_GPIO, 0);
                gpioWrite(CLOSE_GPIO, 1);
                log_event("Gate closed");
            }
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

