#include <unistd.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SOFT_RESET_REG 0x0000
#define START_MEAS_REG 0x0000
#define RESULT_REG 0x0089
#define DISTANCE_REG 0x0096
#define GPIO_TRIGGER 24
#define GPIO_FORWARD 17
#define GPIO_BACKWARD 18

volatile int keep_running = 1;

void signal_handler(int signo) {
    keep_running = 0;
}

int i2c_write_word(int fd, uint16_t reg, uint16_t value) {
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    int retries = 0;
    int max_retries = 5;
    int delay_ms = 10;

    while (retries < max_retries) {
        int result = i2cWriteI2CBlock(fd, VL53L1X_ADDR, buf, 4);
        if (result >= 0) return 0;
        retries++;
        usleep(delay_ms * 1000);
        delay_ms *= 2;
    }

    return -1;
}

uint16_t i2c_read_word(int fd, uint16_t reg) {
    uint8_t buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;

    int retries = 0;
    int max_retries = 5;
    int delay_ms = 10;

    while (retries < max_retries) {
        int result = i2cWriteI2CBlock(fd, VL53L1X_ADDR, buf, 2);
        if (result < 0) {
            retries++;
            usleep(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        result = i2cReadI2CBlock(fd, VL53L1X_ADDR, buf, 2);
        if (result >= 0) {
            return (buf[0] << 8) | buf[1];
        }

        retries++;
        usleep(delay_ms * 1000);
        delay_ms *= 2;
    }

    return 0xFFFF;
}

void set_motor(int forward, int backward) {
    gpioWrite(GPIO_FORWARD, forward);
    gpioWrite(GPIO_BACKWARD, backward);
}

void read_distance(int fd) {
    if (i2c_write_word(fd, SOFT_RESET_REG, 0x00) != 0) {
        fprintf(stderr, "Failed to soft reset sensor\n");
        return;
    }
    time_sleep(0.001);

    if (i2c_write_word(fd, START_MEAS_REG, 0x01) != 0) {
        fprintf(stderr, "Failed to start measurement\n");
        return;
    }

    while ((i2c_read_word(fd, RESULT_REG) & 0x01) == 0) {
        // Wait for data ready
    }

    uint16_t distance = i2c_read_word(fd, DISTANCE_REG);
    printf("Distance: %d mm\n", distance);

    if (distance < 100) {
        set_motor(1, 0);
        printf("Motor: Forward\n");
    } else if (distance > 300) {
        set_motor(0, 1);
        printf("Motor: Backward\n");
    } else {
        set_motor(0, 0);
        printf("Motor: Stopped\n");
    }
}

void isr_callback(int gpio, int level, uint32_t tick) {
    static int fd = -1;
    if (fd == -1) {
        fd = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
        if (fd < 0) {
            fprintf(stderr, "Failed to open I2C device\n");
            return;
        }
    }
    read_distance(fd);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_DOWN);
    gpioSetMode(GPIO_FORWARD, PI_OUTPUT);
    gpioSetMode(GPIO_BACKWARD, PI_OUTPUT);
    set_motor(0, 0);

    if (gpioSetISRFunc(GPIO_TRIGGER, RISING_EDGE, 0, isr_callback) < 0) {
        fprintf(stderr, "Failed to set ISR\n");
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        gpioSleep(PI_TIME_SECONDS, 1, 0);
    }

    gpioSetISRFunc(GPIO_TRIGGER, 0, 0, NULL);
    set_motor(0, 0);
    gpioTerminate();
    return 0;
}

