#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_I2C_ADDR 0x5A
#define SENSOR_PRESENCE_REG 0x2B
#define SENSOR_RESET_REG 0x80
#define ELECONFIG0_REG 0x5B
#define MHDR_REG 0x27
#define NHDR_REG 0x28
#define NCLR_REG 0x29
#define FDLR_REG 0x2A
#define AUTO_CONFIG_0_REG 0x5A
#define AUTO_CONFIG_1_REG 0x5D
#define AUTO_CONFIG_2_REG 0x5E
#define AUTO_CONFIG_3_REG 0x5F
#define TOUCH_STATUS_0_REG 0x00
#define TOUCH_STATUS_1_REG 0x01

#define NUM_ELECTRODES 12
#define POLL_INTERVAL_MS 50

static int i2c_fd;
static struct gpiod_line *gpio_lines[4];
static FILE *log_file;

void cleanup(int signum) {
    printf("Cleaning up...\n");

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    if (log_file) {
        fclose(log_file);
    }

    for (int i = 0; i < 4; i++) {
        if (gpio_lines[i]) {
            gpiod_line_release(gpio_lines[i]);
        }
    }

    exit(EXIT_SUCCESS);
}

int i2c_write(int reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(i2c_fd, buf, sizeof(buf));
}

int i2c_read(int reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        return -1;
    }
    return read(i2c_fd, value, 1);
}

int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int init_gpio() {
    struct gpiod_chip *chip;
    int gpio_pins[4] = {17, 18, 27, 22};

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    for (int i = 0; i < 4; i++) {
        gpio_lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!gpio_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", gpio_pins[i]);
            gpiod_chip_close(chip);
            return -1;
        }

        if (gpiod_line_request_output(gpio_lines[i], "mpr121_led", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d\n", gpio_pins[i]);
            gpiod_chip_close(chip);
            return -1;
        }
    }

    gpiod_chip_close(chip);
    return 0;
}

int init_sensor() {
    uint8_t value;

    // Soft reset
    if (i2c_write(SENSOR_RESET_REG, 0x63) != 2) {
        fprintf(stderr, "Failed to reset sensor\n");
        return -1;
    }
    usleep(10000); // Wait 10ms for reset

    // Verify sensor presence
    if (i2c_read(SENSOR_PRESENCE_REG, &value) != 1 || value != 0x94) {
        fprintf(stderr, "Sensor not found or communication error\n");
        return -1;
    }

    // Initialize sensor
    if (i2c_write(ELECONFIG0_REG, 0x00) != 2 ||
        i2c_write(MHDR_REG, 0x01) != 2 ||
        i2c_write(NHDR_REG, 0x01) != 2 ||
        i2c_write(NCLR_REG, 0x0E) != 2 ||
        i2c_write(FDLR_REG, 0x00) != 2 ||
        i2c_write(AUTO_CONFIG_0_REG, 0x0B) != 2 ||
        i2c_write(AUTO_CONFIG_1_REG, 0xC8) != 2 ||
        i2c_write(AUTO_CONFIG_2_REG, 0x82) != 2 ||
        i2c_write(AUTO_CONFIG_3_REG, 0xB4) != 2 ||
        i2c_write(ELECONFIG0_REG, 0x0C) != 2) {
        fprintf(stderr, "Failed to initialize sensor\n");
        return -1;
    }

    return 0;
}

void set_led_pattern(uint8_t pattern) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(gpio_lines[i], (pattern & (1 << i)) ? 1 : 0);
    }
}

void log_event(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] %s\n", time_str, message);
    fflush(log_file);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    log_file = fopen("mpr121_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0 || init_gpio() < 0 || init_sensor() < 0) {
        cleanup(0);
    }

    log_event("Sensor initialized and ready");

    uint8_t touch_status[2];
    while (1) {
        if (i2c_read(TOUCH_STATUS_0_REG, &touch_status[0]) != 1 ||
