        i2c_write(AUTO_CONFIG_2_REG, 0x82) != 2 ||
        i2c_write(AUTO_CONFIG_3_REG, 0xB4) != 2 ||
        i2c_write(ELECONFIG0_REG, 0x0C) != 2) {
