#define MPR121_SFI 0x2D
#define MPR121_ESI 0x2E
#define MPR121_DEBOUNCE 0x5B
#define MPR121_AFE_CONFIG 0x5C
#define MPR121_BASELINE_FILTER 0x5D
#define MPR121_TOUCH_STATUS 0x00
#define LED_PIN 27

static volatile int keep_running = 1;

void signal_handler(int signo) {
    keep_running = 0;
}

int i2c_write_byte(int i2c_handle, int reg, int data) {
    char buf[2];
    buf[0] = reg;
    buf[1] = data;
    return i2cWriteDevice(i2c_handle, buf, 2);
}

int i2c_read_byte(int i2c_handle, int reg) {
    char buf[1];
    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) {
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 1) < 0) {
        return -1;
    }
    return buf[0];
}

int main() {
    int i2c_handle;
    int device_id;
    time_t now;
    struct tm *timeinfo;
    char timestamp[80];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_LOW);

    i2c_handle = i2cOpen(1, MPR121_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C bus 1 open failed\n");
        gpioTerminate();
        return 1;
    }

    device_id = i2c_read_byte(i2c_handle, 0xFFFFFF);
    if (device_id < 0) {
        fprintf(stderr, "Failed to read MPR121 device ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("MPR121 Device ID: 0x%02X\n", device_id);

    if (i2c_write_byte(i2c_handle, MPR121_FFI, 0x04) < 0 ||
        i2c_write_byte(i2c_handle, MPR121_SFI, 0x04) < 0 ||
        i2c_write_byte(i2c_handle, MPR121_ESI, 0x04) < 0 ||
        i2c_write_byte(i2c_handle, MPR121_DEBOUNCE, 0x00) < 0 ||
        i2c_write_byte(i2c_handle, MPR121_AFE_CONFIG, 0x0C) < 0 ||
        i2c_write_byte(i2c_handle, MPR121_BASELINE_FILTER, 0x01) < 0) {
        fprintf(stderr, "Failed to configure MPR121\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2c_write_byte(i2c_handle, 0x41, MPR121_TOUCH_THRESHOLD) < 0 ||
        i2c_write_byte(i2c_handle, 0x42, MPR121_RELEASE_THRESHOLD) < 0) {
        fprintf(stderr, "Failed to set touch/release thresholds\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        int touch_status = i2c_read_byte(i2c_handle, MPR121_TOUCH_STATUS);
        if (touch_status < 0) {
            fprintf(stderr, "Failed to read touch status\n");
            break;
        }

        if (touch_status & 0x01) {
            gpioWrite(LED_PIN, PI_HIGH);
            time(&now);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            FILE *log_file = fopen("proximity.log", "a");
            if (log_file) {
                fprintf(log_file, "Proximity detected at %s\n", timestamp);
                fclose(log_file);
            }
            sleep(1);
            gpioWrite(LED_PIN, PI_LOW);
        }

        usleep(100000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

