#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TRIGGER_PULSE_US 10
#define TRIGGER_DELAY_US 5
#define ECHO_TIMEOUT_US 30000
#define MEASUREMENT_TIMEOUT_US 30000
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 400
#define SPEED_OF_SOUND_CM_US 0.0343

volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int signum) {
    exit_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    struct gpiod_line_request_config trigger_config, echo_config;
    FILE *log_file;
    struct timespec start_time, end_time;
    long pulse_us;
    double distance_cm;
    char timestamp[64];
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        goto cleanup;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        goto cleanup;
    }

    memset(&trigger_config, 0, sizeof(trigger_config));
    trigger_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    trigger_config.flags = GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN;

    memset(&echo_config, 0, sizeof(echo_config));
    echo_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    echo_config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    if (gpiod_line_request(trigger_line, &trigger_config, "HC-SR04 Trigger") < 0) {
        fprintf(stderr, "Failed to request trigger line\n");
        goto cleanup;
    }

    if (gpiod_line_request(echo_line, &echo_config, "HC-SR04 Echo") < 0) {
        fprintf(stderr, "Failed to request echo line\n");
        goto cleanup;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        goto cleanup;
    }

    while (!exit_flag) {
        gpiod_line_set_value(trigger_line, 0);
        usleep(TRIGGER_DELAY_US);
        gpiod_line_set_value(trigger_line, 1);
        usleep(TRIGGER_PULSE_US);
        gpiod_line_set_value(trigger_line, 0);

        if (clock_gettime(CLOCK_MONOTONIC, &start_time) != 0) {
            perror("clock_gettime");
            goto cleanup;
        }

        int echo_value = gpiod_line_get_value(echo_line);
        while (echo_value == 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &end_time) != 0) {
                perror("clock_gettime");
                goto cleanup;
            }
            if ((end_time.tv_sec - start_time.tv_sec) * 1000000 +
                (end_time.tv_nsec - start_time.tv_nsec) / 1000 >= ECHO_TIMEOUT_US) {
                fprintf(stderr, "Echo timeout\n");
                break;
            }
            echo_value = gpiod_line_get_value(echo_line);
        }

        if (echo_value == 0) {
            continue;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &start_time) != 0) {
            perror("clock_gettime");
            goto cleanup;
        }

        echo_value = gpiod_line_get_value(echo_line);
        while (echo_value == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &end_time) != 0) {
                perror("clock_gettime");
                goto cleanup;
            }
            if ((end_time.tv_sec - start_time.tv_sec) * 1000000 +
                (end_time.tv_nsec - start_time.tv_nsec) / 1000 >= MEASUREMENT_TIMEOUT_US) {
                fprintf(stderr, "Measurement timeout\n");
                break;
            }
            echo_value = gpiod_line_get_value(echo_line);
        }

        pulse_us = (end_time.tv_sec - start_time.tv_sec) * 1000000 +
                   (end_time.tv_nsec - start_time.tv_nsec) / 1000;

        distance_cm = (pulse_us * SPEED_OF_SOUND_CM_US) / 2.0;

        if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
            fprintf(stderr, "Invalid distance: %.2f cm\n", distance_cm);
        } else {
            time_t now = time(NULL);
            struct tm *tm_info = gmtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);
            fprintf(log_file, "%s %.2f cm\n", timestamp, distance_cm);
            fflush(log_file);
        }

        sleep(1);
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

