        perror("fopen");
        goto cleanup;
    }

    while (!exit_flag) {
        gpiod_line_set_value(trigger_line, 0);
        usleep(TRIGGER_DELAY_US);
        gpiod_line_set_value(trigger_line, 1);
        usleep(TRIGGER_PULSE_US);
        gpiod_line_set_value(trigger_line, 0);

        if (clock_gettime(CLOCK_MONOTONIC, &start_time) != 0) {
            perror("clock_gettime");
            goto cleanup;
        }

        int echo_value = gpiod_line_get_value(echo_line);
        while (echo_value == 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &end_time) != 0) {
                perror("clock_gettime");
                goto cleanup;
            }
            if ((end_time.tv_sec - start_time.tv_sec) * 1000000 +
                (end_time.tv_nsec - start_time.tv_nsec) / 1000 >= ECHO_TIMEOUT_US) {
                fprintf(stderr, "Echo timeout\n");
                break;
            }
            echo_value = gpiod_line_get_value(echo_line);
        }

        if (echo_value == 0) {
            continue;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &start_time) != 0) {
            perror("clock_gettime");
            goto cleanup;
        }

        echo_value = gpiod_line_get_value(echo_line);
        while (echo_value == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &end_time) != 0) {
                perror("clock_gettime");
                goto cleanup;
            }
            if ((end_time.tv_sec - start_time.tv_sec) * 1000000 +
                (end_time.tv_nsec - start_time.tv_nsec) / 1000 >= MEASUREMENT_TIMEOUT_US) {
                fprintf(stderr, "Measurement timeout\n");
                break;
            }
            echo_value = gpiod_line_get_value(echo_line);
        }

        pulse_us = (end_time.tv_sec - start_time.tv_sec) * 1000000 +
                   (end_time.tv_nsec - start_time.tv_nsec) / 1000;

        distance_cm = (pulse_us * SPEED_OF_SOUND_CM_US) / 2.0;

        if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
            fprintf(stderr, "Invalid distance: %.2f cm\n", distance_cm);
        } else {
            time_t now = time(NULL);
            struct tm *tm_info = gmtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);
            fprintf(log_file, "%s %.2f cm\n", timestamp, distance_cm);
            fflush(log_file);
        }

        sleep(1);
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}
