#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define SENSOR_ADDR 0x29
#define TRIGGER_PIN 27
#define I2C_BUS 1
#define REG_CONTINUOUS_MODE 0x0018
#define REG_NO_TIMEOUT 0x0019
#define REG_START_RANGING 0x0020
#define REG_DISTANCE 0x0014
#define REG_STATUS 0x0016

static int i2c_handle;

void signal_handler(int signo) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    closelog();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    openlog("VL53L1X", LOG_CONS | LOG_PID | LOG_NDELAY, LOG_USER);

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioWrite(TRIGGER_PIN, PI_HIGH);

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, REG_CONTINUOUS_MODE, 0x00) < 0 ||
        i2cWriteByteData(i2c_handle, REG_NO_TIMEOUT, 0x00) < 0 ||
        i2cWriteByteData(i2c_handle, REG_START_RANGING, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to initialize sensor");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char distance[2], status;
    int read_result;

    while (1) {
        read_result = i2cReadI2CBlock(i2c_handle, REG_DISTANCE, distance, 2);
        if (read_result < 0) {
            syslog(LOG_ERR, "Failed to read distance: %s", strerror(errno));
        } else {
            int distance_mm = distance[0] | (distance[1] << 8);
            read_result = i2cReadByteData(i2c_handle, REG_STATUS, &status);
            if (read_result < 0) {
                syslog(LOG_ERR, "Failed to read status: %s", strerror(errno));
            } else {
                syslog(LOG_INFO, "Distance: %d mm, Status: 0x%02X", distance_mm, status);
            }
        }

        usleep(100000); // 100 ms
    }

    return EXIT_SUCCESS;
}

