#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define SENSOR_ADDR 0x29
#define MODEL_ID_REG 0x010F
#define EXPECTED_MODEL_ID 0xEA
#define RANGE_MODE_REG 0x0021
#define SHORT_RANGE_MODE 0x00
#define RANGE_COMMAND_REG 0x0015
#define START_RANGING 0x01
#define DISTANCE_HIGH_REG 0x0089
#define DISTANCE_LOW_REG 0x008A
#define GATE_PIN 24
#define LOG_FILE "gate_log.txt"
#define CHECK(x) do { if ((x) != 0) { log_message("Error: %s\n", strerror(errno)); gpioTerminate(); exit(EXIT_FAILURE); } } while (0)

FILE *log_file;

void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    time_t now = time(NULL);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] ", time_str);
    vfprintf(log_file, format, args);
    fflush(log_file);
    va_end(args);
}

void signal_handler(int signum) {
    log_message("Received signal %d, shutting down...\n", signum);
    gpioWrite(GATE_PIN, LOW);
    gpioTerminate();
    fclose(log_file);
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(GATE_PIN, PI_OUTPUT);
    gpioWrite(GATE_PIN, LOW); // Start with gate closed

    int i2c_handle = i2cOpen(1, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Read and verify model ID
    uint16_t model_id;
    CHECK(i2cReadWordData(i2c_handle, MODEL_ID_REG, &model_id));
    if (model_id != EXPECTED_MODEL_ID) {
        log_message("Unexpected model ID: 0x%04X\n", model_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }
    log_message("Sensor initialized, model ID: 0x%04X\n", model_id);

    // Set ranging mode to short
    CHECK(i2cWriteWordData(i2c_handle, RANGE_MODE_REG, SHORT_RANGE_MODE));

    // Start ranging
    CHECK(i2cWriteWordData(i2c_handle, RANGE_COMMAND_REG, START_RANGING));

    while (1) {
        uint16_t distance_high, distance_low;
        CHECK(i2cReadWordData(i2c_handle, DISTANCE_HIGH_REG, &distance_high));
        CHECK(i2cReadWordData(i2c_handle, DISTANCE_LOW_REG, &distance_low));

        uint32_t distance_mm = ((uint32_t)distance_high << 16) | distance_low;
        float distance_cm = distance_mm / 10.0f;

        log_message("Distance: %.1f cm\n", distance_cm);

        if (distance_cm < 20.0f) {
            gpioWrite(GATE_PIN, HIGH);
            log_message("Gate opened\n");
        } else {
            gpioWrite(GATE_PIN, LOW);
            log_message("Gate closed\n");
        }

        gpioSleep(PI_TIME_RELATIVE, 0, 100000000); // Sleep for 100ms
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    return EXIT_SUCCESS;
}

