#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <math.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define TRIGGER_DURATION 10 // microseconds
#define SPEED_OF_SOUND 34300 // cm/s
#define MIN_DISTANCE 2 // cm
#define MAX_DISTANCE 400 // cm
#define MEASUREMENT_TIMEOUT 30000 // microseconds
#define TRIGGER_INTERVAL 100000 // microseconds
#define MOVING_AVERAGE_SAMPLES 5
#define SERVO_MIN_PULSE 500 // microseconds
#define SERVO_MAX_PULSE 2500 // microseconds
#define SERVO_DEFAULT_ANGLE 90

volatile sig_atomic_t stop_flag = 0;
volatile uint32_t last_echo_tick = 0;
volatile int32_t pulse_width = -1;
volatile int pulse_width_ready = 0;

static void signal_handler(int signo) {
    if (signo == SIGINT) {
        stop_flag = 1;
    }
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        last_echo_tick = tick;
    } else if (level == 0) {
        pulse_width = (int32_t)tick - (int32_t)last_echo_tick;
        if (pulse_width < 0) {
            pulse_width += (1ULL << 32);
        }
        pulse_width_ready = 1;
    }
}

static double get_distance(int32_t pulse_width) {
    if (pulse_width < 0 || pulse_width > MEASUREMENT_TIMEOUT) {
        return -1.0;
    }
    double distance = (double)pulse_width * SPEED_OF_SOUND / (2.0 * 10000.0);
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0;
    }
    return distance;
}

static int map_distance_to_angle(double distance) {
    if (distance < 0) {
        return SERVO_DEFAULT_ANGLE;
    }
