#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>

#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define PROXIMITY_REG_HIGH 0x08
#define PROXIMITY_REG_LOW 0x09
#define GPIO_PIN 27

static volatile int keep_running = 1;
static int i2c_handle;
static FILE *log_file;
static int threshold;
static int i2c_address;

static void signal_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = 0;
    }
}

static int read_proximity(int i2c_handle) {
    unsigned char high, low;
    if (i2c_read_i2c_block(i2c_handle, PROXIMITY_REG_HIGH, 1, &high) < 0 ||
        i2c_read_i2c_block(i2c_handle, PROXIMITY_REG_LOW, 1, &low) < 0) {
        fprintf(stderr, "Error reading proximity registers\n");
        return -1;
    }
    return (high << 8) | low;
}

static void log_proximity(int value) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];
    const char *status = (value <= threshold) ? "SAFE" : "ALERT";

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (fprintf(log_file, "%s, %d, %s\n", timestamp, value, status) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    }
    fflush(log_file);
}

static void gpio_callback(int gpio, int level, uint32_t tick) {
    static int last_value = -1;
    int value;

    value = read_proximity(i2c_handle);
    if (value < 0) return;

    if (value != last_value) {
        log_proximity(value);
        last_value = value;
    }
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a <i2c_address>] [-t <threshold>]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (i2c_address == 0) i2c_address = DEFAULT_I2C_ADDRESS;
    if (threshold == 0) threshold = DEFAULT_THRESHOLD;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("proximity.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0 ||
        gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(GPIO_PIN, gpio_callback) < 0) {
        fprintf(stderr, "Failed to set GPIO alert function\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (keep_running) {
        gpioSleep(PI_TIME_RELATIVE, 1, 0);
    }

    gpioSetAlertFunc(GPIO_PIN, NULL);
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

