#include <math.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SPEAKER_PIN 18
#define MIN_DISTANCE 2
#define MAX_DISTANCE 200
#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000
#define DUTY_CYCLE 50
#define TRIGGER_PULSE_WIDTH 10
#define TIMEOUT_MS 200

volatile int keep_running = 1;

void sigint_handler(int signo) {
    keep_running = 0;
}

double map_distance_to_frequency(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1;
    }
    return 200 * exp(distance / 50);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SPEAKER_PIN, PI_ALT0) < 0) {
        fprintf(stderr, "GPIO mode setting failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_OFF) < 0) {
        fprintf(stderr, "GPIO pull-up/down setting failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioHardwarePWM(SPEAKER_PIN, 0, DUTY_CYCLE * 10000) < 0) {
        fprintf(stderr, "Hardware PWM setup failed\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    double previous_frequency = MIN_FREQUENCY;
    uint32_t last_tick;

    while (keep_running) {
        gpioWrite(TRIG_PIN, PI_LOW);
        gpioDelay(5);
        gpioWrite(TRIG_PIN, PI_HIGH);
        gpioDelay(TRIGGER_PULSE_WIDTH);
        gpioWrite(TRIG_PIN, PI_LOW);

        last_tick = gpioTick();
        while (gpioRead(ECHO_PIN) == 0) {
            if (gpioTick() - last_tick > TIMEOUT_MS * 10000) {
                break;
            }
        }

        uint32_t start_tick = gpioTick();
        last_tick = start_tick;
        while (gpioRead(ECHO_PIN) == 1) {
            if (gpioTick() - last_tick > TIMEOUT_MS * 10000) {
                break;
            }
        }

        uint32_t end_tick = gpioTick();
        uint32_t echo_duration = end_tick - start_tick;

        if (echo_duration > 0) {
            double distance = echo_duration * 0.0343 / 2;
            double frequency = map_distance_to_frequency(distance);
            if (frequency > 0) {
                previous_frequency = frequency;
            }
        }

        uint32_t period_us = (uint32_t)(1000000 / previous_frequency);
        if (gpioHardwarePWM(SPEAKER_PIN, period_us, DUTY_CYCLE * 10000) < 0) {
            fprintf(stderr, "Failed to update PWM frequency\n");
        }

        gpioDelay(1000);
    }

    gpioHardwarePWM(SPEAKER_PIN, 0, 0);
    gpioTerminate();
    return 0;
}
