#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

#define MIN_DIST 5
#define MAX_DIST 50
#define MIN_FREQ 200
#define MAX_FREQ 2000
#define TIMEOUT_US 100000
#define DELAY_MS 10

volatile bool keep_running = true;

void sigint_handler(int signo) {
    keep_running = false;
}

double measure_distance() {
    gpioWrite(TRIGGER_PIN, PI_HIGH);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, PI_LOW);

    clock_t start_time = clock();
    long long start_tick = gpioTick();
    long long end_tick;

    while (gpioRead(ECHO_PIN) == PI_LOW) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Echo pulse timeout\n");
            return -1;
        }
    }

    start_time = clock();
    while (gpioRead(ECHO_PIN) == PI_HIGH) {
        end_tick = gpioTick();
        if (end_tick - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Echo pulse timeout\n");
            return -1;
        }
    }

    double pulse_width = (double)(end_tick - start_tick) / 1000.0;
    double distance = pulse_width * 343.0 / 2.0;

    if (distance < MIN_DIST || distance > MAX_DIST) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1;
    }

    return distance;
}

