        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_ALT0);

    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    gpioWrite(TRIGGER_PIN, PI_LOW);

    signal(SIGINT, sigint_handler);

    double last_valid_distance = MIN_DIST;
    double frequency;

    while (keep_running) {
        double distance = measure_distance();
        if (distance < 0) {
            distance = last_valid_distance;
        } else {
            last_valid_distance = distance;
        }

        frequency = map_distance_to_frequency(distance);
        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);

        gpioHardwarePWM(BUZZER_PIN, frequency * 2, frequency * 2 / 2);

        gpioDelay(DELAY_MS * 1000);
    }

    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioTerminate();

    return 0;
}

