#include <stdio.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define MEASURE_INTERVAL_MS 500
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_MS 50
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 400
#define TOO_CLOSE_DISTANCE_CM 10

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioWrite(TRIGGER_PIN, PI_LOW);

    signal(SIGINT, signal_handler);

    while (keep_running) {
        gpioWrite(TRIGGER_PIN, PI_HIGH);
        gpioDelay(TRIGGER_PULSE_US * 1000);
        gpioWrite(TRIGGER_PIN, PI_LOW);

        long pulse_width = gpioGpioClock(ECHO_PIN, PI_TIME_1US);
        if (pulse_width < 0) {
            fprintf(stderr, "Timeout waiting for echo pulse\n");
            continue;
        }

        float distance_cm = pulse_width / 2.0 / 29.1;

        if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
            printf("Invalid reading\n");
        } else {
            printf("Distance: %.2f cm\n", distance_cm);
            if (distance_cm < TOO_CLOSE_DISTANCE_CM) {
                printf("Too close!\n");
            }
        }

        gpioDelay(MEASURE_INTERVAL_MS * 1000);
    }

    gpioTerminate();
    return 0;
}

