#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define CS_PIN 8
#define REG_CONTROL 0x01
#define REG_RANGE 0x02
#define REG_TRIGGER 0x00
#define REG_DISTANCE_LOW 0x0C
#define REG_DISTANCE_HIGH 0x0D
#define MEASUREMENT_DELAY_MS 100

static FILE *log_file = NULL;
static int spi_handle = -1;

void cleanup(int signum) {
    if (spi_handle >= 0) {
        gpioSetMode(CS_PIN, PI_INPUT);
        gpioWrite(CS_PIN, PI_LOW);
        close(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int init_sensor() {
    unsigned char init_data[2];
    int ret;

    // Set continuous measurement mode
    init_data[0] = REG_CONTROL;
    init_data[1] = 0x01;
    ret = gpioSPIXfer(spi_handle, init_data, 2, NULL, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set continuous measurement mode: %s\n", strerror(errno));
        return -1;
    }

    // Set 5m range
    init_data[0] = REG_RANGE;
    init_data[1] = 0x00;
    ret = gpioSPIXfer(spi_handle, init_data, 2, NULL, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set range: %s\n", strerror(errno));
        return -1;
    }

    // Trigger first measurement
    init_data[0] = REG_TRIGGER;
    init_data[1] = 0x01;
    ret = gpioSPIXfer(spi_handle, init_data, 2, NULL, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to trigger first measurement: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int read_distance(unsigned short *distance) {
    unsigned char tx_data[2], rx_data[2];
    int ret;

    // Read distance low byte
    tx_data[0] = REG_DISTANCE_LOW;
    tx_data[1] = 0x00;
    ret = gpioSPIXfer(spi_handle, tx_data, 2, rx_data, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read distance low byte: %s\n", strerror(errno));
        return -1;
    }
    *distance = rx_data[1];

    // Read distance high byte
    tx_data[0] = REG_DISTANCE_HIGH;
    tx_data[1] = 0x00;
    ret = gpioSPIXfer(spi_handle, tx_data, 2, rx_data, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read distance high byte: %s\n", strerror(errno));
        return -1;
    }
    *distance |= (unsigned short)rx_data[1] << 8;

    return 0;
}

int main() {
    struct sigaction sa;
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];
    unsigned short distance;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, PI_HIGH);

    spi_handle = gpioSPIOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor() < 0) {
        cleanup(0);
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup(0);
        return EXIT_FAILURE;
    }

    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        if (read_distance(&distance) < 0) {
            fprintf(stderr, "Failed to read distance\n");
        } else {
            time(&now);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s,%u\n", timestamp, distance);
            fflush(log_file);
        }

        gpioDelay(MEASUREMENT_DELAY_MS * 1000);
    }

    return EXIT_SUCCESS;
}

