#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x60
#define ALS_VISIBLE_LOW_REG 0x22
#define ALS_VISIBLE_HIGH_REG 0x23
#define LOG_FILE "proximity_log.csv"
#define READ_INTERVAL 5

static int i2c_fd;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, value, 1);
}

uint16_t read_als_visible(int fd) {
    uint8_t low, high;
    if (i2c_read(fd, ALS_VISIBLE_LOW_REG, &low) != 1 ||
        i2c_read(fd, ALS_VISIBLE_HIGH_REG, &high) != 1) {
        return 0xFFFF; // Indicate error
    }
    return (high << 8) | low;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SI1175_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,als_visible\n");
    fflush(log_file);

    while (1) {
        uint16_t als_visible = read_als_visible(i2c_fd);
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        if (als_visible == 0xFFFF) {
            fprintf(stderr, "Error reading ALS visible value\n");
        } else {
            fprintf(log_file, "%s,%u\n", timestamp, als_visible);
            fflush(log_file);
        }

        sleep(READ_INTERVAL);
    }

    return EXIT_SUCCESS;
}

