#define ALS_HIGH_REG 0x23
#define PS1_LOW_REG 0x18
#define PS1_HIGH_REG 0x19
#define PART_ID_REG 0x00
#define RESET_REG 0x30
#define EXPECTED_PART_ID 0x41
#define I2C_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 500

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

uint16_t read_register(int i2c_handle, uint8_t reg) {
    uint8_t buffer[2];
    int retries = 0;
    while (retries < I2C_RETRIES) {
        if (i2cReadI2CBlock(i2c_handle, SI1120_ADDR, reg, 2, buffer) == 2) {
            return (buffer[1] << 8) | buffer[0];
        }
        retries++;
        gpioSleep(MILLISECONDS, RETRY_DELAY_MS, 0);
    }
    fprintf(stderr, "Failed to read register 0x%02X after %d attempts\n", reg, I2C_RETRIES);
    return 0;
}

int write_register(int i2c_handle, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    int retries = 0;
    while (retries < I2C_RETRIES) {
        if (i2cWriteI2CBlock(i2c_handle, SI1120_ADDR, buffer, 2) == 2) {
            return 0;
        }
        retries++;
        gpioSleep(MILLISECONDS, RETRY_DELAY_MS, 0);
    }
    fprintf(stderr, "Failed to write register 0x%02X after %d attempts\n", reg, I2C_RETRIES);
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_register(i2c_handle, RESET_REG, 0x01) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSleep(MILLISECONDS, 10, 0);  // Wait for reset to complete

    uint16_t part_id = read_register(i2c_handle, PART_ID_REG);
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Invalid part ID: 0x%02X\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("si1120_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    time_t last_sample_time = time(NULL);

    while (keep_running) {
        time_t current_time = time(NULL);
        if (difftime(current_time, last_sample_time) >= SAMPLE_INTERVAL_MS / 1000.0) {
            uint16_t als = read_register(i2c_handle, ALS_LOW_REG);
            uint16_t ps1 = read_register(i2c_handle, PS1_LOW_REG);

            time_t now;
            struct tm *tm_info;
            char timestamp[20];

            time(&now);
            tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s ALS: %d PS1: %d\n", timestamp, als, ps1);
            fflush(log_file);

            last_sample_time = current_time;
        }
        gpioSleep(MILLISECONDS, 10, 0);  // Small delay to prevent busy-waiting
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

