#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <syslog.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x39
#define PART_ID_REG 0x00
#define MEAS_RATE_REG 0x08
#define AMBIENT_LIGHT_REG 0x22
#define PROXIMITY_REG 0x24

static int i2c_fd;
static FILE *log_file;

void signal_handler(int signo) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    syslog(LOG_INFO, "Exiting on signal %d", signo);
    closelog();
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, buf, len);
}

uint16_t read_le16(const uint8_t *buf) {
    return buf[0] | (buf[1] << 8);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    openlog("si1182_logger", LOG_PID | LOG_CONS, LOG_USER);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SI1182_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    uint8_t part_id;
    if (i2c_read(i2c_fd, PART_ID_REG, &part_id, 1) != 1) {
        syslog(LOG_ERR, "Failed to read part ID");
        close(i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    if (part_id != 0x82) {
        syslog(LOG_ERR, "Invalid part ID: 0x%02X", part_id);
        close(i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, MEAS_RATE_REG, 0x07) != 2) {
        syslog(LOG_ERR, "Failed to set measurement rate");
        close(i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        close(i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    time_t now;
    struct tm *tm_info;
    char timestamp[20];
    uint8_t buf[4];

    while (1) {
        if (i2c_read(i2c_fd, AMBIENT_LIGHT_REG, buf, 2) != 2 ||
            i2c_read(i2c_fd, PROXIMITY_REG, buf + 2, 2) != 2) {
            syslog(LOG_ERR, "Failed to read sensor data");
            continue;
        }

        uint16_t ambient_light = read_le16(buf);
        uint16_t proximity = read_le16(buf + 2);
        float lux = ambient_light * 0.1f;

        time(&now);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.1f,%d\n", timestamp, lux, proximity);
        printf("%s,%.1f,%d\n", timestamp, lux, proximity);
        fflush(log_file);

        usleep(100000);
    }

    return EXIT_SUCCESS;
}

