#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define I2C_ADDRESS 0x60
#define LOG_FILE "proximity_log.txt"
#define MAX_RETRIES 3

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_error(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        time_t now = time(NULL);
        char timestamp[26];
        ctime_r(&now, timestamp);
        timestamp[24] = '\0';
        fprintf(log_file, "[%s] ERROR: %s\n", timestamp, message);
        fclose(log_file);
    }
}

int i2c_write_retry(int i2c_handle, uint8_t reg, uint8_t data) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteByteData(i2c_handle, reg, data) == 0) {
            return 0;
        }
        sleep(1);
    }
    return -1;
}

int i2c_read_retry(int i2c_handle, uint8_t reg, uint8_t *data) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cReadByteData(i2c_handle, reg, data) == 0) {
            return 0;
        }
        sleep(1);
    }
    return -1;
}

int initialize_sensor(int i2c_handle) {
    const uint8_t init_sequence[][2] = {
        {0x07, 0x03}, {0x06, 0x02}, {0x1A, 0x00}, {0x21, 0x0B},
        {0x24, 0x00}, {0x22, 0x49}, {0x0C, 0x03}, {0x0F, 0x0F},
        {0x11, 0x03}, {0x0D, 0x07}, {0x80, 0x03}
    };

    for (size_t i = 0; i < sizeof(init_sequence) / sizeof(init_sequence[0]); i++) {
        if (i2c_write_retry(i2c_handle, init_sequence[i][0], init_sequence[i][1]) != 0) {
            log_error("Failed to initialize sensor");
            return -1;
        }
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(1, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        uint8_t low_byte, high_byte;
        if (i2c_read_retry(i2c_handle, 0x16, &low_byte) != 0 ||
            i2c_read_retry(i2c_handle, 0x17, &high_byte) != 0) {
            log_error("Failed to read proximity data");
            break;
        }

        uint16_t proximity = (high_byte << 8) | low_byte;

        time_t now = time(NULL);
        char timestamp[26];
        ctime_r(&now, timestamp);
        timestamp[24] = '\0';

        fprintf(log_file, "[%s] Proximity: %u\n", timestamp, proximity);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

