#include <stdio.h>
#include <pigpio.h>
#include <signal.h>
#include <stdbool.h>

#define TRIG_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18
#define MAX_DISTANCE_CM 200
#define MIN_DISTANCE_CM 20
#define UPDATE_INTERVAL_MS 100

volatile bool keep_running = true;

void cleanup(int signum) {
    keep_running = false;
}

float measure_distance() {
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioWrite(TRIG_PIN, PI_LOW);
    gpioDelay(2);

    gpioWrite(TRIG_PIN, PI_HIGH);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, PI_LOW);

    long start_tick = gpioTick();
    long end_tick;

    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > 1000000) {
            return -1.0; // Timeout
        }
    }

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        end_tick = gpioTick();
        if (end_tick - start_tick > 1000000) {
            return -1.0; // Timeout
        }
    }

    long travel_time = end_tick - start_tick;
    float distance = (travel_time * 343.0) / 20000.0; // Speed of sound ~343 m/s

    return distance;
}

void set_servo_angle(float distance) {
    int pulse_width;
    if (distance <= MIN_DISTANCE_CM) {
        pulse_width = 2500; // 180 degrees
    } else if (distance >= MAX_DISTANCE_CM) {
        pulse_width = 500; // 0 degrees
    } else {
        pulse_width = 1500 + (int)((distance - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM) * 1000);
    }

    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, cleanup);

    while (keep_running) {
        float distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Error measuring distance\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            set_servo_angle(distance);
        }
        gpioDelay(UPDATE_INTERVAL_MS * 1000);
    }

    gpioSetServoPulsewidth(SERVO_PIN, 0); // Stop servo
    gpioTerminate();
    return 0;
}

