#define VL53L1X_MODEL_ID_REG 0x010F
#define VL53L1X_TIMING_BUDGET_REG 0x0009
#define VL53L1X_RESULT_RANGE_STATUS_REG 0x0014
#define VL53L1X_RESULT_RANGE_REG 0x0010

#define SERVO_PIN 18
#define SERVO_CLOSED_PULSE 1000
#define SERVO_OPEN_PULSE 2000
#define DISTANCE_THRESHOLD_OPEN 200
#define DISTANCE_THRESHOLD_CLOSE 250

#define I2C_BUS 1

static int i2c_handle;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int write_i2c_reg(int reg, uint8_t value) {
    int ret = i2cWriteByteData(i2c_handle, reg, value);
    if (ret < 0) {
        fprintf(stderr, "I2C write error: %d\n", ret);
    }
    return ret;
}

int read_i2c_reg(int reg, uint8_t *value) {
    int ret = i2cReadByteData(i2c_handle, reg, value);
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %d\n", ret);
    }
    return ret;
}

int read_i2c_word(int reg, uint16_t *value) {
    uint8_t msb, lsb;
    if (read_i2c_reg(reg, &msb) < 0 || read_i2c_reg(reg + 1, &lsb) < 0) {
        return -1;
    }
    *value = (msb << 8) | lsb;
    return 0;
}

void log_event(const char *event) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0';  // Remove newline
    fprintf(log_file, "[%s] %s\n", time_str, event);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C device open failed\n");
        cleanup(0);
    }

    log_file = fopen("gate_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
    }

    uint8_t model_id;
    if (read_i2c_reg(VL53L1X_MODEL_ID_REG, &model_id) < 0 || model_id != 0xEA) {
        fprintf(stderr, "Invalid VL53L1X model ID\n");
        cleanup(0);
    }

    // Set timing budget (e.g., 50ms)
    if (write_i2c_reg(VL53L1X_TIMING_BUDGET_REG, 0x32) < 0) {
        cleanup(0);
    }

    // Start ranging
    if (write_i2c_reg(0x0000, 0x00) < 0) {
        cleanup(0);
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 50);  // 50Hz for servo

    uint16_t last_distance = 0;
    while (1) {
        uint16_t distance;
        if (read_i2c_word(VL53L1X_RESULT_RANGE_REG, &distance) < 0) {
            cleanup(0);
        }

        if (distance < DISTANCE_THRESHOLD_OPEN && last_distance >= DISTANCE_THRESHOLD_OPEN) {
            gpioServoPulse(SERVO_PIN, SERVO_OPEN_PULSE);
            log_event("Gate opened");
        } else if (distance > DISTANCE_THRESHOLD_CLOSE && last_distance <= DISTANCE_THRESHOLD_CLOSE) {
            gpioServoPulse(SERVO_PIN, SERVO_CLOSED_PULSE);
            log_event("Gate closed");
        }

        last_distance = distance;
        gpioSleep(PI_TIME_RELATIVE, 0, 100000000);  // 0.1s delay
    }

    return EXIT_SUCCESS;
}

