#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 200.0
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define SPEED_OF_SOUND 343.0
#define TRIGGER_PULSE_WIDTH 10
#define TIMEOUT_US 50000
#define MEASUREMENT_DELAY_MS 100

volatile int keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        gpioServo(SERVO_PIN, 0);
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

double measure_distance() {
    long start_tick, end_tick;
    double pulse_duration_us;

    gpioWrite(TRIG_PIN, PI_HIGH);
    gpioDelay(TRIGGER_PULSE_WIDTH * 10);
    gpioWrite(TRIG_PIN, PI_LOW);

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == PI_LOW) {
        if (gpioTick() - start_tick > TIMEOUT_US) return -1.0;
    }

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == PI_HIGH) {
        if (gpioTick() - start_tick > TIMEOUT_US) return -1.0;
    }

    end_tick = gpioTick();
    pulse_duration_us = (double)(end_tick - start_tick);

    return (pulse_duration_us * SPEED_OF_SOUND) / 20000.0;
}

int map_distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE) return MIN_ANGLE;
    if (distance > MAX_DISTANCE) return MAX_ANGLE;

    double ratio = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
    return (int)(MIN_ANGLE + ratio * (MAX_ANGLE - MIN_ANGLE));
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIG_PIN, PI_LOW);

    while (keep_running) {
        double distance = measure_distance();
        if (distance < 0) {
            printf("Sensor timeout\n");
        } else {
            int angle = map_distance_to_angle(distance);
            int pulse_width = (angle == MIN_ANGLE) ? 500 : 2500;
            gpioServo(SERVO_PIN, pulse_width);
            printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        }
        gpioDelay(MEASUREMENT_DELAY_MS * 1000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

