            fprintf(stderr, "Failed to read temperature\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus\n");
                gpioTerminate();
                return 1;
            }
            continue;
        }
        float temperature = (175.72 * temp_raw) / 65536.0 - 46.85;

        // Read humidity
        int hum_raw = i2cReadWordData(i2c_handle, HUM_REG);
        if (hum_raw < 0) {
            fprintf(stderr, "Failed to read humidity\n");
