            i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus\n");
                gpioTerminate();
                return 1;
            }
            continue;
        }
        float humidity = (125.0 * hum_raw) / 65536.0 - 6.0;

        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);
        time_sleep(LOG_INTERVAL);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
