#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <errno.h>

#define MPU6050_ADDR 0x68
#define WHO_AM_I_REG 0x75
#define PWR_MGMT_1_REG 0x6B
#define SMPLRT_DIV_REG 0x19
#define ACCEL_CONFIG_REG 0x1C
#define GYRO_CONFIG_REG 0x1B
#define ACCEL_OUT_REG 0x3B
#define GYRO_OUT_REG 0x43
#define TEMP_OUT_REG 0x41

#define SAMPLE_RATE_DIV 7
#define ACCEL_FS_SEL 0x00 // ±2g
#define GYRO_FS_SEL 0x00  // ±250 deg/s

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int16_t combine_bytes(uint8_t high, uint8_t low) {
    return (int16_t)((high << 8) | low);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    printf("MPU-6050 data logger starting...\n");

    if (setmode(2, PI_I2C) != 0 || setmode(3, PI_I2C) != 0) {
        fprintf(stderr, "GPIO mode setting failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C device open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Verify sensor presence
    uint8_t who_am_i;
    if (i2cReadByteData(i2c_handle, WHO_AM_I_REG, &who_am_i) < 0 || who_am_i != MPU6050_ADDR) {
        fprintf(stderr, "MPU-6050 not detected\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Reset device
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1_REG, 0x80) < 0) {
        fprintf(stderr, "Failed to reset MPU-6050\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    sleep(1);

    // Clear sleep bit
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to clear sleep bit\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set sample rate
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV_REG, SAMPLE_RATE_DIV) < 0) {
        fprintf(stderr, "Failed to set sample rate\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set accelerometer range
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG_REG, ACCEL_FS_SEL) < 0) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set gyroscope range
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG_REG, GYRO_FS_SEL) < 0) {
        fprintf(stderr, "Failed to set gyroscope range\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t data[14];
    while (keep_running) {
        if (i2cReadI2CBlockData(i2c_handle, ACCEL_OUT_REG, data, 14) < 0) {
            fprintf(stderr, "I2C read error\n");
            continue;
        }

        int16_t accel_x = combine_bytes(data[0], data[1]);
        int16_t accel_y = combine_bytes(data[2], data[3]);
        int16_t accel_z = combine_bytes(data[4], data[5]);
        int16_t temp = combine_bytes(data[6], data[7]);
        int16_t gyro_x = combine_bytes(data[8], data[9]);
        int16_t gyro_y = combine_bytes(data[10], data[11]);
        int16_t gyro_z = combine_bytes(data[12], data[13]);

        printf("Accel: X=%d Y=%d Z=%d | Temp: %d | Gyro: X=%d Y=%d Z=%d\n",
               accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z);

        usleep(100000); // 100ms
    }

    printf("MPU-6050 data logger shutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

