#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <errno.h>

#define SHT40_I2C_ADDR 0x44
#define I2C_BUS 1
#define MEASURE_CMD 0xFD
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define MEASUREMENT_DELAY_MS 10
#define LOG_INTERVAL_SEC 5

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sht40(int i2c_handle) {
    uint8_t cmd = MEASURE_CMD;
    uint8_t data[6];

    if (i2cWriteDevice(i2c_handle, &cmd, 1) < 0) {
        fprintf(stderr, "Error writing to SHT40\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000);

    if (i2cReadDevice(i2c_handle, data, 6) < 0) {
        fprintf(stderr, "Error reading from SHT40\n");
        return -1;
    }

    if (calculate_crc8(data, 2) != data[2] || calculate_crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    uint16_t raw_temp = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    float temperature = -45.0 + 175.0 * raw_temp / 65535.0;
    float humidity = -6.0 + 125.0 * raw_humidity / 65535.0;

    if (temperature < 0) temperature = 0;
    if (temperature > 100) temperature = 100;
    if (humidity < 0) humidity = 0;
    if (humidity > 100) humidity = 100;

    printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SHT40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        if (read_sht40(i2c_handle) != 0) {
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, SHT40_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus\n");
                break;
            }
        }
        sleep(LOG_INTERVAL_SEC);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

