#define SAMPLE_INTERVAL 5
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

static FILE *log_file = NULL;
static FILE *error_log_file = NULL;

void log_error(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(error_log_file, "[%s] %s\n", time_str, message);
    fflush(error_log_file);
}

void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (error_log_file) {
        fclose(error_log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (!log_file || !error_log_file) {
        fprintf(stderr, "Failed to open log files\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        int handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
        if (handle < 0) {
            log_error("Failed to open I2C device");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        unsigned char cmd[2] = {0x30, 0xA2}; // Command to trigger temperature measurement
        if (i2cWriteDevice(handle, cmd, 2) < 0) {
            log_error("Failed to send command to STS30");
            i2cClose(handle);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        sleep(1); // Wait for measurement to complete

        unsigned char data[3];
        if (i2cReadDevice(handle, data, 3) < 0) {
            log_error("Failed to read from STS30");
            i2cClose(handle);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        i2cClose(handle);

        uint16_t temp_raw = (data[0] << 8) | data[1];
        float temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;

        time_t now;
        time(&now);
        char *time_str = ctime(&now);
        time_str[strlen(time_str) - 1] = '\0'; // Remove newline

        fprintf(log_file, "[%s] Temperature: %.2f°C\n", time_str, temperature);
        fflush(log_file);

        sleep(SAMPLE_INTERVAL);
    }

    return EXIT_SUCCESS;
}

