#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define SENSOR_ADDR 0x25
#define I2C_BUS 1
#define MEASURE_CMD 0x3608
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (i2cOpen(I2C_BUS, SENSOR_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("pressure_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Differential Pressure (Pa),Temperature (°C)\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        uint8_t cmd[2] = {0x36, 0x08};
        if (i2cWriteDevice(I2C_BUS, SENSOR_ADDR, cmd, 2) < 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            break;
        }

        gpioSleep(Time_release, 1, 0);

        uint8_t data[9];
        if (i2cReadDevice(I2C_BUS, SENSOR_ADDR, data, 9) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        uint8_t crc_diff_pressure = calculate_crc8(data, 2);
        uint8_t crc_temperature = calculate_crc8(data + 3, 2);
        uint8_t crc_scale_factors = calculate_crc8(data + 6, 2);

        if (crc_diff_pressure != data[2] || crc_temperature != data[5] || crc_scale_factors != data[8]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        int16_t diff_pressure_raw = (data[0] << 8) | data[1];
        int16_t temperature_raw = (data[3] << 8) | data[4];
        int16_t scale_factors_raw = (data[6] << 8) | data[7];

        float diff_pressure = diff_pressure_raw * (1.0f + scale_factors_raw / 16384.0f);
        float temperature = temperature_raw * (1.0f + scale_factors_raw / 16384.0f) / 200.0f;

        time_t now = time(NULL);
        struct tm *utc_time = gmtime(&now);
        char timestamp[26];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, diff_pressure, temperature);
        fflush(log_file);

        gpioSleep(Time_release, 1, 0);
    }

    fclose(log_file);
    i2cClose(I2C_BUS);
    gpioTerminate();
    return 0;
}

