#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

uint8_t calculate_crc(uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

int main() {
    int i2c_fd, log_fd;
    struct i2c_msg messages[1];
    uint8_t write_buf[1] = {MEASURE_CMD};
    uint8_t read_buf[6];
    FILE *log_file;
    time_t last_log_time = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SHT40_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("sht40_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        messages[0].addr = SHT40_ADDR;
        messages[0].flags = 0;
        messages[0].len = sizeof(write_buf);
        messages[0].buf = write_buf;

        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            fprintf(stderr, "Failed to write to I2C device\n");
            sleep(1);
            continue;
        }

        usleep(10000);  // Wait 10ms for measurement

        messages[0].flags = I2C_M_RD;
        messages[0].len = sizeof(read_buf);
        messages[0].buf = read_buf;

        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
            sleep(1);
            continue;
        }

        uint16_t raw_temp = (read_buf[0] << 8) | read_buf[1];
        uint16_t raw_hum = (read_buf[3] << 8) | read_buf[4];

        if (calculate_crc(read_buf, 2) != read_buf[2] ||
            calculate_crc(read_buf + 3, 2) != read_buf[5]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        float temp = -45.0f + 175.0f * raw_temp / 65535.0f;
        float hum = 100.0f * raw_hum / 65535.0f;

        time_t current_time = time(NULL);
        if (current_time - last_log_time >= 5) {
            fprintf(log_file, "[%s] Temperature: %.2f°C, Humidity: %.2f%%\n",
                    ctime(&current_time), temp, hum);
            fflush(log_file);
            last_log_time = current_time;
        }

        sleep(1);
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

