#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x40
#define TEMP_COMMAND 0xF3
#define HUMIDITY_COMMAND 0xF5
#define SAMPLE_INTERVAL 5
#define MAX_RETRIES 3

static int i2cHandle;
static FILE *file;

void cleanup(int sig) {
    if (i2cHandle >= 0) {
        gpioI2CClose(i2cHandle);
    }
    if (file) {
        fclose(file);
    }
    if (gpioInitialised()) {
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

int read_sensor_data(uint8_t command, float *value) {
    int retries = 0;
    int raw;
    while (retries < MAX_RETRIES) {
        if (gpioI2CWriteByte(i2cHandle, command) < 0) {
            fprintf(stderr, "I2C write error: %s\n", pigpio_error());
            retries++;
            usleep(100000); // 100ms
            continue;
        }
        usleep(20000); // 20ms wait for measurement

        if (gpioI2CReadWordData(i2cHandle, command, &raw) < 0) {
            fprintf(stderr, "I2C read error: %s\n", pigpio_error());
            retries++;
            usleep(100000); // 100ms
            continue;
        }
        *value = (command == TEMP_COMMAND) ? (175.72 * raw / 65536.0) - 46.85 : (125.0 * raw / 65536.0) - 6.0;
        if (command != TEMP_COMMAND) {
            if (*value < 0.0) *value = 0.0;
            if (*value > 100.0) *value = 100.0;
        }
        return 0;
    }
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed: %s\n", pigpio_error());
        return EXIT_FAILURE;
    }

    i2cHandle = gpioI2COpen(I2C_BUS, SENSOR_ADDR);
    if (i2cHandle < 0) {
        fprintf(stderr, "I2C open error: %s\n", pigpio_error());
        gpioTerminate();
        return EXIT_FAILURE;
    }

    file = fopen("sensor_data.txt", "a");
    if (!file) {
        fprintf(stderr, "File open error: %s\n", strerror(errno));
        gpioI2CClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    time_t lastSampleTime = time(NULL);
    float temperature, humidity;

    while (1) {
        time_t currentTime = time(NULL);
        if (currentTime - lastSampleTime >= SAMPLE_INTERVAL) {
            if (read_sensor_data(TEMP_COMMAND, &temperature) == 0) {
                if (read_sensor_data(HUMIDITY_COMMAND, &humidity) == 0) {
                    time_t now;
                    struct tm *tm_info;
                    char timestamp[26];

                    time(&now);
                    tm_info = localtime(&now);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

                    printf("%s - Temperature: %.2f°C, Humidity: %.2f%%\n", timestamp, temperature, humidity);
                    fprintf(file, "%s - Temperature: %.2f°C, Humidity: %.2f%%\n", timestamp, temperature, humidity);
                    fflush(file);
                } else {
                    fprintf(stderr, "Failed to read humidity after retries\n");
                }
            } else {
                fprintf(stderr, "Failed to read temperature after retries\n");
            }
            lastSampleTime = currentTime;
        }
        usleep(100000); // 100ms sleep to prevent busy-waiting
    }

    return EXIT_SUCCESS;
}

