#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDRESS 0x25
#define MEASURE_COMMAND 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define CRC8_FINAL_XOR 0x00

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc ^ CRC8_FINAL_XOR;
}

int validate_crc8(const uint8_t *data, size_t len) {
    return calculate_crc8(data, len - 1) == data[len - 1];
}

int main() {
    int i2c_fd, log_fd;
    struct i2c_msg messages[1];
    uint8_t buffer[9];
    FILE *log_file;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SDP800_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("airflow_data.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (°C)\n");
    fflush(log_file);

    log_fd = fileno(log_file);

    while (keep_running) {
        buffer[0] = MEASURE_COMMAND >> 8;
        buffer[1] = MEASURE_COMMAND & 0xFF;

        messages[0].addr = SDP800_ADDRESS;
        messages[0].flags = 0;
        messages[0].len = 2;
        messages[0].buf = buffer;

        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            perror("Failed to send measurement command");
            sleep(1);
            continue;
        }

        usleep(45000);

        messages[0].flags = I2C_M_RD;
        messages[0].len = 9;

        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            perror("Failed to read sensor data");
            sleep(1);
            continue;
        }

        if (!validate_crc8(buffer, 3) || !validate_crc8(buffer + 3, 3) || !validate_crc8(buffer + 6, 3)) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        uint32_t pressure_raw = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
        uint32_t temperature_raw = (buffer[3] << 16) | (buffer[4] << 8) | buffer[5];
        uint32_t scale_factor = (buffer[6] << 16) | (buffer[7] << 8) | buffer[8];

        double pressure_pa = (double)pressure_raw / scale_factor;
        double temperature_c = (double)temperature_raw / 200.0 - 45.0;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        char log_entry[100];
        snprintf(log_entry, sizeof(log_entry), "%s,%.2f,%.2f\n", timestamp, pressure_pa, temperature_c);

        if (write(log_fd, log_entry, strlen(log_entry)) < 0) {
            perror("Failed to write to log file");
        }

        usleep(100000);
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

