#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

uint8_t calculate_crc(uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

int main() {
    int file;
    uint8_t write_buf[1] = {MEASURE_CMD};
    uint8_t read_buf[6];
    FILE *log_file;
    struct timespec ts;
    char timestamp[64];

    signal(SIGINT, signal_handler);

    file = open(I2C_BUS, O_RDWR);
    if (file < 0) {
        perror("Failed to open the I2C bus");
        return 1;
    }

    if (ioctl(file, I2C_SLAVE_FORCE, SHT40_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return 1;
    }

    log_file = fopen("sht40_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(file);
        return 1;
    }

    while (keep_running) {
        if (write(file, write_buf, 1) != 1) {
            perror("Failed to write to the I2C bus");
            continue;
        }

        usleep(8500);  // 8.5 ms delay

        if (read(file, read_buf, 6) != 6) {
            perror("Failed to read from the I2C bus");
            continue;
        }

        uint16_t raw_temp = (read_buf[0] << 8) | read_buf[1];
        uint16_t raw_hum = (read_buf[3] << 8) | read_buf[4];

        if (calculate_crc(read_buf, 2) != read_buf[2] ||
            calculate_crc(read_buf + 3, 2) != read_buf[5]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        float temperature = -45.0 + 175.0 * raw_temp / 65535.0;
        float humidity = 100.0 * raw_hum / 65535.0;

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        fprintf(log_file, "%s, Temperature: %.2f°C, Humidity: %.2f%%\n",
                timestamp, temperature, humidity);
        fflush(log_file);

        sleep(5);
    }

    fclose(log_file);
    close(file);
    return 0;
}

