#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_REG 0xE3
#define HUM_REG 0xE5
#define FAN_PIN 18
#define BUFFER_SIZE 60

typedef struct {
    float temperature;
    float humidity;
    time_t timestamp;
} SensorData;

SensorData circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

void log_and_print_data(float temp, float hum) {
    time_t now = time(NULL);
    circular_buffer[buffer_index] = (SensorData){temp, hum, now};
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    printf("Temperature: %.2f°C, Humidity: %.2f%%, Time: %s",
           temp, hum, ctime(&now));
}

void control_fan(float temp) {
    static int fan_state = 0;
    if (temp > 28.0 && !fan_state) {
        gpioWrite(FAN_PIN, 1);
        fan_state = 1;
    } else if (temp < 27.0 && fan_state) {
        gpioWrite(FAN_PIN, 0);
        fan_state = 0;
    }
}

int read_sensor(int handle, uint8_t reg, uint16_t *value) {
    int retries = 3;
    int result;

    do {
        result = i2cWriteByteData(handle, reg, 0);
        if (result >= 0) {
            usleep(10000);  // 10ms delay
            result = i2cReadWordData(handle, reg);
            if (result >= 0) {
                *value = (uint16_t)result;
                return 0;
            }
        }
        retries--;
        usleep(100000);  // 100ms delay before retry
    } while (retries > 0);

    return -1;
}

void signal_handler(int signo) {
    if (signo == SIGINT) {
        gpioWrite(FAN_PIN, 0);
        gpioTerminate();
        exit(0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for fan\n");
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        uint16_t raw_temp, raw_hum;

        if (read_sensor(i2c_handle, TEMP_REG, &raw_temp) == 0) {
            float temp = 175.72 * raw_temp / 65536.0 - 46.85;
            control_fan(temp);

            if (read_sensor(i2c_handle, HUM_REG, &raw_hum) == 0) {
                float hum = 125.0 * raw_hum / 65536.0 - 6.0;
                log_and_print_data(temp, hum);
            } else {
                fprintf(stderr, "Failed to read humidity\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        sleep(2);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

