#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define SCD40_I2C_ADDR 0x62
#define BUFFER_SIZE 20
#define CO2_THRESHOLD 1000
#define MEASUREMENT_INTERVAL 5

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} SensorData;

SensorData circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

volatile sig_atomic_t keep_running = 1;

void sigint_handler(int signum) {
    keep_running = 0;
}

uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int validate_crc(const uint8_t *data, int len) {
    uint8_t received_crc = data[len - 1];
    uint8_t calculated_crc = crc8(data, len - 1);
    return received_crc == calculated_crc;
}

void log_data(const SensorData *data) {
    circular_buffer[buffer_index] = *data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

void print_data(const SensorData *data) {
    printf("CO2: %d ppm, Temperature: %.2f C, Humidity: %.2f %%\n",
           data->co2, data->temperature, data->humidity);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        fprintf(stderr, "GPIO setup failed\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    int i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C device open failed\n");
        gpioTerminate();
        return 1;
    }

    uint8_t start_cmd[] = {0x21, 0xB1};
    if (i2cWriteDevice(i2c_handle, start_cmd, 2) != 2) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        uint8_t status_cmd[] = {0xE4, 0xB8};
        if (i2cWriteDevice(i2c_handle, status_cmd, 2) != 2) {
            fprintf(stderr, "Failed to request data ready status\n");
            continue;
        }

        uint8_t status[3];
        if (i2cReadDevice(i2c_handle, status, 3) != 3) {
            fprintf(stderr, "Failed to read data ready status\n");
            continue;
        }

        if (!validate_crc(status, 3)) {
            fprintf(stderr, "CRC validation failed for data ready status\n");
            continue;
        }

        if (!(status[0] & 0x01)) {
            usleep(100000);
            continue;
        }

        uint8_t read_cmd[] = {0xEC, 0x05};
        if (i2cWriteDevice(i2c_handle, read_cmd, 2) != 2) {
            fprintf(stderr, "Failed to request measurement\n");
            continue;
        }

        uint8_t measurement[9];
        if (i2cReadDevice(i2c_handle, measurement, 9) != 9) {
            fprintf(stderr, "Failed to read measurement\n");
            continue;
        }

        if (!validate_crc(measurement, 3) || !validate_crc(measurement + 3, 3)) {
            fprintf(stderr, "CRC validation failed for measurement data\n");
            continue;
        }

        SensorData data;
        data.co2 = (measurement[0] << 8) | measurement[1];
        data.temperature = -45 + 175 * ((float)(measurement[3] << 8 | measurement[4]) / 65536.0);
        data.humidity = 100 * ((float)(measurement[6] << 8 | measurement[7]) / 65536.0);

        log_data(&data);
        print_data(&data);

        if (data.co2 > CO2_THRESHOLD) {
            gpioWrite(17, PI_HIGH);
        } else {
            gpioWrite(17, PI_LOW);
        }

        sleep(MEASUREMENT_INTERVAL);
    }

    uint8_t stop_cmd[] = {0x3F, 0x86};
    i2cWriteDevice(i2c_handle, stop_cmd, 2);

    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

