#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SENSOR_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 5000000 // 5 seconds in microseconds
#define TIMEOUT 50000 // 50 ms in microseconds
#define VALID_MIN -40.0
#define VALID_MAX 150.0

static FILE *log_file;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

double read_temperature() {
    uint32_t start_tick, end_tick, high_tick, low_tick;
    int level, timeout;

    start_tick = gpioTick();
    level = gpioRead(SENSOR_PIN);
    timeout = 0;

    while (gpioTick() - start_tick < TIMEOUT) {
        if (gpioRead(SENSOR_PIN) != level) {
            end_tick = gpioTick();
            if (level == 0) {
                high_tick = end_tick - start_tick;
            } else {
                low_tick = end_tick - start_tick;
            }
            level = 1 - level;
            start_tick = gpioTick();
            timeout = 0;
        } else {
            timeout++;
        }
    }

    if (timeout >= TIMEOUT) {
        return -999.0; // Sensor malfunction
    }

    uint32_t total_tick = high_tick + low_tick;
    if (total_tick == 0) {
        return -999.0; // Avoid division by zero
    }

    double temperature = 4215.0 - (2143.0 * high_tick / total_tick);
    return temperature;
}

void log_temperature(double temperature) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    if (temperature < VALID_MIN || temperature > VALID_MAX) {
        fprintf(log_file, "%s - ERROR: Temperature out of range: %.2f°C\n", timestamp, temperature);
    } else {
        fprintf(log_file, "%s - Temperature: %.2f°C\n", timestamp, temperature);
    }
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_OFF);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int consecutive_failures = 0;

    while (keep_running) {
        double temperature = read_temperature();

        if (temperature == -999.0) {
            consecutive_failures++;
            if (consecutive_failures >= 3) {
                time_t now;
                struct tm *tm_info;
                char timestamp[64];

                time(&now);
                tm_info = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

                fprintf(log_file, "%s - SENSOR MALFUNCTION\n", timestamp);
                fflush(log_file);
                consecutive_failures = 0;
            }
        } else {
            log_temperature(temperature);
            consecutive_failures = 0;
        }

        time_sleep(1); // Sleep for 1 second to maintain 5-second intervals
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

