static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        crc = crc8_table[crc];
    }
    return crc;
}

float convert_temperature(uint16_t raw) {
    return 175.0f * raw / 65535.0f - 45.0f;
}

