            float elapsed_hours = difftime(time(NULL), start_time) / 3600.0f;
            simulated_offset_temp = 2.0f * sin(2 * M_PI * elapsed_hours / 24.0f);
            simulated_offset_hum = 5.0f * sin(2 * M_PI * elapsed_hours / 24.0f);

            temperature += simulated_offset_temp;
            humidity += simulated_offset_hum;

            time_t now;
            struct tm *tm_info;
            char timestamp[64];

            time(&now);
            tm_info = gmtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

            fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
            fflush(log_file);
        } else {
            fprintf(log_file, "%s,NaN,NaN\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(LOG_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

