#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CONVERSION_TIME_MS 45
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    int i2c_fd;
    FILE *csv_file;
    struct i2c_msg messages[1];
    uint8_t buffer[9];
    time_t last_log_time = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SDP810_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    csv_file = fopen("airflow.csv", "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "Timestamp,Pressure (Pa),Temperature (°C)\n");

    while (keep_running) {
        buffer[0] = MEASURE_CMD >> 8;
        buffer[1] = MEASURE_CMD & 0xFF;

        messages[0].addr = SDP810_ADDR;
        messages[0].flags = 0;
        messages[0].len = 2;
        messages[0].buf = buffer;

        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            perror("I2C write error");
            continue;
        }

        usleep(CONVERSION_TIME_MS * 1000);

        messages[0].flags = I2C_M_RD;
        messages[0].len = 9;

        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            perror("I2C read error");
            continue;
        }

        for (int i = 0; i < 3; i++) {
            if (calculate_crc8(buffer + i * 3, 2) != buffer[i * 3 + 2]) {
                fprintf(stderr, "CRC check failed for data set %d\n", i);
                continue;
            }
        }

        int32_t pressure_raw = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
        int32_t temperature_raw = (buffer[3] << 16) | (buffer[4] << 8) | buffer[5];

        float pressure = (float)pressure_raw / 100.0f;
        float temperature = (float)temperature_raw / 200.0f + 273.15f;

        time_t current_time = time(NULL);
        if (current_time - last_log_time >= 1) {
            fprintf(csv_file, "%ld,%f,%f\n", (long)current_time, pressure, temperature - 273.15f);
            fflush(csv_file);
            last_log_time = current_time;
        }
    }

    fclose(csv_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

