#include <sys/ioctl.h>
#include <sys/time.h>
#include <errno.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x40
#define HUMIDITY_CMD 0xF5
#define TEMPERATURE_CMD 0xE0
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0x00
#define TIMEOUT_MS 100
#define LOG_FILE "environment.log"
#define LOG_INTERVAL 5

static int i2c_fd;

void sigint_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

uint8_t calculate_crc8(uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor(int cmd, uint8_t *buffer, int len) {
    struct i2c_msg messages[1];
    struct i2c_rdwr_ioctl_data packets;

    messages[0].addr = SENSOR_ADDR;
    messages[0].flags = 0;
    messages[0].len = 1;
    messages[0].buf = &cmd;

    packets.msgs = messages;
    packets.nmsgs = 1;

    if (ioctl(i2c_fd, I2C_RDWR, &packets) < 0) {
        perror("ioctl write error");
        return -1;
    }

    messages[0].flags = I2C_M_RD;
    messages[0].len = len;

    packets.msgs = messages;
    packets.nmsgs = 1;

    if (ioctl(i2c_fd, I2C_RDWR, &packets) < 0) {
        perror("ioctl read error");
        return -1;
    }

    return 0;
}

int reset_sensor() {
    uint8_t reset_cmd = 0xFE;
    if (write(i2c_fd, &reset_cmd, 1) != 1) {
        perror("write reset command error");
        return -1;
    }
    usleep(50000); // 50ms delay
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction error");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus error");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("set I2C slave address error");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("open log file error");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (fprintf(log_file, "timestamp,temperature_C,humidity_percent\n") < 0) {
        perror("write log header error");
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t buffer[3];
    struct timeval start, end;
    double temperature, humidity;

    while (1) {
        gettimeofday(&start, NULL);

        if (read_sensor(HUMIDITY_CMD, buffer, 3) < 0 || calculate_crc8(buffer, 2) != buffer[2]) {
            fprintf(stderr, "ERROR: Failed to read or verify humidity\n");
            if (reset_sensor() < 0) {
                fprintf(stderr, "ERROR: Failed to reset sensor\n");
            }
            fprintf(log_file, "%s,ERROR,ERROR\n", ctime(&start.tv_sec));
        } else {
            humidity = 125.0 * ((buffer[0] << 8) | buffer[1]) / 65536.0 - 6.0;

            if (read_sensor(TEMPERATURE_CMD, buffer, 3) < 0 || calculate_crc8(buffer, 2) != buffer[2]) {
                fprintf(stderr, "ERROR: Failed to read or verify temperature\n");
                if (reset_sensor() < 0) {
                    fprintf(stderr, "ERROR: Failed to reset sensor\n");
                }
                fprintf(log_file, "%s,ERROR,%.2f\n", ctime(&start.tv_sec), humidity);
            } else {
                temperature = 175.72 * ((buffer[0] << 8) | buffer[1]) / 65536.0 - 46.85;
                fprintf(log_file, "%s,%.2f,%.2f\n", ctime(&start.tv_sec), temperature, humidity);
            }
        }

        fflush(log_file);

        gettimeofday(&end, NULL);
        long elapsed_ms = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_usec - start.tv_usec) / 1000;
        if (elapsed_ms < LOG_INTERVAL * 1000) {
            usleep((LOG_INTERVAL * 1000 - elapsed_ms) * 1000);
        }
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

