#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <stdint.h>
#include <string.h>

#define SENSOR_ADDRESS 0x25
#define CONVERSION_TIME_MS 10
#define I2C_BUS 1
#define LOG_FILE "airflow.dat"

static int i2c_handle;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "ab");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    uint8_t command[] = {0x36, 0x2F};
    if (i2cWriteDevice(i2c_handle, command, sizeof(command)) != sizeof(command)) {
        fprintf(stderr, "Failed to send command to sensor\n");
        cleanup(0);
    }

    while (1) {
        time_sleep(CONVERSION_TIME_MS / 1000.0);

        uint8_t buffer[9];
        if (i2cReadDevice(i2c_handle, buffer, sizeof(buffer)) != sizeof(buffer)) {
            fprintf(stderr, "Failed to read from sensor\n");
            continue;
        }

        uint16_t raw_pressure = (buffer[0] << 8) | buffer[1];
        uint16_t raw_temperature = (buffer[3] << 8) | buffer[4];

        if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        uint32_t scale_factor = (buffer[6] << 16) | (buffer[7] << 8) | buffer[8];

        float pressure = (float)raw_pressure / scale_factor - 1000.0f;
        float temperature = (float)raw_temperature / 200.0f - 45.0f;

        if (fwrite(&pressure, sizeof(float), 1, log_file) != 1 ||
            fwrite(&temperature, sizeof(float), 1, log_file) != 1) {
            fprintf(stderr, "Failed to write to log file\n");
        }

        fflush(log_file);
        sleep(1);
    }

    return EXIT_SUCCESS;
}

