#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define SENSOR_ADDR 0x25
#define I2C_BUS 1
#define CONVERSION_TIME_MS 45
#define CRC_POLYNOMIAL 0x31
#define LOG_INTERVAL_SEC 5
#define SCALE_FACTOR 60.0

static FILE *log_file;
static int i2c_handle;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        gpI2CClose(i2c_handle);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    gpTerminate();
    exit(EXIT_SUCCESS);
}

uint8_t calculate_crc8(const uint8_t *data, int length) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = gpI2COpen(I2C_BUS, SENSOR_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpI2CClose(i2c_handle);
        gpTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    uint8_t command[] = {0x36, 0x03};
    uint8_t buffer[9];
    time_t last_log_time = time(NULL);

    while (1) {
        if (gpI2CWriteDevice(i2c_handle, command, 2) < 0) {
            fprintf(stderr, "Failed to send command to sensor\n");
            sleep(1);
            continue;
        }

        time_sleep(CONVERSION_TIME_MS / 1000.0);

        int bytes_read = gpI2CReadDevice(i2c_handle, buffer, 9);
        if (bytes_read != 9) {
            fprintf(stderr, "Failed to read from sensor\n");
            sleep(1);
            continue;
        }

        uint8_t crc = calculate_crc8(buffer, 8);
        if (crc != buffer[8]) {
            fprintf(stderr, "CRC check failed\n");
            sleep(1);
            continue;
        }

        uint32_t pressure_raw = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
        float pressure_pa = pressure_raw * SCALE_FACTOR;

        time_t current_time = time(NULL);
        if (current_time - last_log_time >= LOG_INTERVAL_SEC) {
            fprintf(log_file, "[%ld] Pressure: %.2f Pa\n", (long)current_time, pressure_pa);
            fflush(log_file);
            last_log_time = current_time;
        }

        sleep(1);
    }

    return EXIT_SUCCESS;
}

