#include <errno.h>
#include <unistd.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x28
#define FAN_PIN 18
#define SAMPLE_INTERVAL_MS 100
#define MIN_FLOW_COUNTS 1638
#define MAX_FLOW_COUNTS 14745
#define MIN_FLOW_RATE 0.0
#define MAX_FLOW_RATE 10.0

static FILE *log_file;
static volatile int keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

double convert_counts_to_flow_rate(uint16_t counts) {
    return (counts - MIN_FLOW_COUNTS) * (MAX_FLOW_RATE - MIN_FLOW_RATE) / (MAX_FLOW_COUNTS - MIN_FLOW_COUNTS) + MIN_FLOW_RATE;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

