#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define LPS33HW_ADDRESS 0x5D
#define WHO_AM_I_REG 0x0F
#define CTRL_REG1_REG 0x10
#define PRESS_OUT_XL_REG 0x28
#define PRESS_OUT_L_REG 0x29
#define PRESS_OUT_H_REG 0x2A
#define TEMP_OUT_L_REG 0x2B
#define TEMP_OUT_H_REG 0x2C

#define LOG_FILE "environmental_data.txt"

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_error(const char *message) {
    time_t now;
    struct tm tm_info;
    char timestamp[26];
    FILE *log_file = fopen(LOG_FILE, "a");

    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time(&now);
    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(stderr, "%s, ERROR: %s\n", timestamp, message);
    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
    fclose(log_file);
}

int main() {
    int i2c_handle;
    FILE *log_file;
    time_t now;
    struct tm tm_info;
    char timestamp[26];
    char buffer[64];
    int16_t raw_temp;
    int32_t raw_pressure;
    float pressure_hPa, temperature_C;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize gpio\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LPS33HW_ADDRESS, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    char who_am_i;
    if (i2cReadByteData(i2c_handle, WHO_AM_I_REG, &who_am_i) < 0 || who_am_i != 0xB1) {
        log_error("WHO_AM_I check failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, CTRL_REG1_REG, 0xB0) < 0) {
        log_error("Failed to configure LPS33HW");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (keep_running) {
        if (i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL_REG, buffer, 3) < 0) {
            log_error("Failed to read pressure data");
            continue;
        }
        raw_pressure = (buffer[0] | (buffer[1] << 8) | (buffer[2] << 16)) >> 4;
        pressure_hPa = raw_pressure / 4096.0;

        if (i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L_REG, buffer, 2) < 0) {
            log_error("Failed to read temperature data");
            continue;
        }
        raw_temp = buffer[0] | (buffer[1] << 8);
        temperature_C = 42.5 + (float)raw_temp / 480.0;

        time(&now);
        localtime_r(&now, &tm_info);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

        fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure_hPa, temperature_C);
        fflush(log_file);

        gpioDelay(1000000000); // 1 second delay
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

