#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x48
#define TEMP_REGISTER 0x00
#define BUFFER_SIZE 10
#define LED_PIN 17
#define TEMP_THRESHOLD 28.0

typedef struct {
    float temperatures[BUFFER_SIZE];
    int index;
    int count;
} CircularBuffer;

CircularBuffer buffer = { .index = 0, .count = 0 };

void cleanup(int signum) {
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

float compute_average(CircularBuffer *buffer) {
    float sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->temperatures[i];
    }
    return sum / buffer->count;
}

void update_buffer(CircularBuffer *buffer, float new_temp) {
    buffer->temperatures[buffer->index] = new_temp;
    buffer->index = (buffer->index + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        int16_t raw_temp;
        if (i2cReadWordData(i2c_handle, TEMP_REGISTER, &raw_temp) == 0) {
            // Swap bytes
            raw_temp = ((raw_temp & 0xFF) << 8) | ((raw_temp >> 8) & 0xFF);
            // Convert to Celsius
            float temp_c = ((float)raw_temp >> 7) / 2.0;
            update_buffer(&buffer, temp_c);

            float avg_temp = compute_average(&buffer);
            gpioWrite(LED_PIN, avg_temp > TEMP_THRESHOLD ? 1 : 0);

            printf("Temperature: %.2f°C, Average: %.2f°C\n", temp_c, avg_temp);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        sleep(1);
    }

    return EXIT_SUCCESS;
}

