#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define SCD30_I2C_ADDR 0x61
#define SCD30_MEASUREMENT_INTERVAL 2000
#define LOG_FILE "air_quality.log"
#define CO2_THRESHOLD_LOW 800
#define CO2_THRESHOLD_HIGH 1200

// CRC-8 calculation
uint8_t scd30_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Write command with CRC
int scd30_write_command(int i2c_handle, uint16_t command, uint8_t *data, int data_len) {
    uint8_t buffer[5];
    buffer[0] = (command >> 8) & 0xFF;
    buffer[1] = command & 0xFF;
    for (int i = 0; i < data_len; i++) {
        buffer[2 + i] = data[i];
    }
    buffer[2 + data_len] = scd30_crc8(buffer, 2 + data_len);

    return i2cWriteDevice(i2c_handle, buffer, 3 + data_len);
}

// Read command with CRC verification
int scd30_read_command(int i2c_handle, uint16_t command, uint8_t *buffer, int buffer_len) {
    uint8_t cmd_buffer[2];
    cmd_buffer[0] = (command >> 8) & 0xFF;
    cmd_buffer[1] = command & 0xFF;

    if (i2cWriteDevice(i2c_handle, cmd_buffer, 2) < 0) {
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buffer, buffer_len) < 0) {
        return -1;
    }

    for (int i = 0; i < buffer_len - 2; i += 3) {
        if (scd30_crc8(buffer + i, 2) != buffer[i + 2]) {
            return -1;
        }
    }

    return 0;
}

// Set measurement interval
int scd30_set_measurement_interval(int i2c_handle, uint16_t interval) {
    uint8_t data[2];
    data[0] = (interval >> 8) & 0xFF;
    data[1] = interval & 0xFF;
    return scd30_write_command(i2c_handle, 0x4600, data, 2);
}

// Start continuous measurement
int scd30_start_measurement(int i2c_handle) {
    uint8_t data[2] = {0x00, 0x00}; // Ambient pressure compensation disabled
    return scd30_write_command(i2c_handle, 0x0010, data, 2);
}

// Check data ready
int scd30_check_data_ready(int i2c_handle) {
    uint8_t buffer[3];
    if (scd30_read_command(i2c_handle, 0x0202, buffer, 3) < 0) {
        return -1;
    }
    return buffer[1] << 8 | buffer[0];
}

// Read measurement
int scd30_read_measurement(int i2c_handle, float *co2, float *temperature, float *humidity) {
    uint8_t buffer[18];
    if (scd30_read_command(i2c_handle, 0x0300, buffer, 18) < 0) {
        return -1;
    }

    *co2 = (buffer[0] << 8) | buffer[1];
    *temperature = (buffer[3] << 8 | buffer[4]) / 100.0;
    *humidity = (buffer[6] << 8 | buffer[7]) / 100.0;

    return 0;
}

// Simulate ventilation system
void simulate_ventilation_system(float co2) {
    if (co2 < CO2_THRESHOLD_LOW) {
        printf("Ventilation System: OFF\n");
    } else if (co2 < CO2_THRESHOLD_HIGH) {
        printf("Ventilation System: LOW\n");
    } else {
        printf("Ventilation System: HIGH\n");
    }
}

// Log data
void log_data(FILE *log_file, float co2, float temperature, float humidity) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);
}

// Signal handler
volatile sig_atomic_t keep_running = 1;
void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 0;
    }

    int i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 0;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (scd30_set_measurement_interval(i2c_handle, SCD30_MEASUREMENT_INTERVAL) < 0 ||
        scd30_start_measurement(i2c_handle) < 0) {
        fprintf(stderr, "Failed to configure SCD30 sensor\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    while (keep_running) {
        if (scd30_check_data_ready(i2c_handle) > 0) {
            float co2, temperature, humidity;
            if (scd30_read_measurement(i2c_handle, &co2, &temperature, &humidity) == 0) {
                log_data(log_file, co2, temperature, humidity);
                simulate_ventilation_system(co2);
            } else {
                fprintf(stderr, "Failed to read measurement from SCD30\n");
            }
        } else {
            fprintf(stderr, "SCD30 data not ready\n");
        }
        time_sleep(1);
    }

    fclose(log_file);
