    // ... (remaining 240 entries)
};

// Function to calculate CRC-8
uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc = crc8_table[crc ^ data[i]];
    }
    return crc;
}

