    uint8_t start_cmd[] = {0x36, 0x2F};
    if (i2cWriteDevice(i2c_handle, start_cmd, 2) < 0) {
        fprintf(stderr, "Failed to start continuous measurement\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        if (read_sensor_data(i2c_handle, buffer) < 0) {
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Verify CRC for pressure, temperature, and scale factor
        if (verify_crc(buffer, 3) < 0 || verify_crc(buffer + 3, 3) < 0 || verify_crc(buffer + 6, 3) < 0) {
            fprintf(stderr, "CRC check failed\n");
            continue;
