    signal(SIGTERM, signal_handler);

    uint8_t write_buf[2] = {MEASURE_CMD >> 8, MEASURE_CMD & 0xFF};
    uint8_t read_buf[9];

    while (keep_running) {
        if (i2cWriteDevice(i2c_handle, write_buf, 2) < 0) {
            fprintf(stderr, "Failed to write to sensor\n");
