#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <signal.h>
#include <sys/time.h>

#define I2C_BUS "/dev/i2c-1"
#define HDC1000_ADDR 0x40
#define TEMP_REG 0x00
#define CONFIG_REG 0x02
#define MEASUREMENT_CONFIG 0x1000
#define CONVERSION_DELAY_MS 20

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int fd;
    uint16_t data[2];
    struct i2c_msg messages[1];
    struct i2c_rdwr_ioctl_data packets;
    char buf[10];

    // Open I2C bus
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address for the device
    if (ioctl(fd, I2C_SLAVE_FORCE, HDC1000_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return EXIT_FAILURE;
    }

    // Configure sensor
    uint16_t config = MEASUREMENT_CONFIG;
    if (write(fd, &CONFIG_REG, 1) != 1 || write(fd, &config, 2) != 2) {
        perror("Failed to configure sensor");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        // Prepare I2C message to read temperature
        messages[0].addr = HDC1000_ADDR;
        messages[0].flags = 0;
        messages[0].len = 1;
        messages[0].buf = TEMP_REG;

        packets.msgs = messages;
        packets.nmsgs = 1;

        // Send read request
        if (ioctl(fd, I2C_RDWR, &packets) < 0) {
            fprintf(stderr, "Failed to send read request\n");
            continue;
        }

        // Wait for conversion
        usleep(CONVERSION_DELAY_MS * 1000);

        // Read data
        messages[0].flags = I2C_M_RD;
        messages[0].len = 4;
        messages[0].buf = (uint8_t *)data;

        if (ioctl(fd, I2C_RDWR, &packets) < 0) {
            fprintf(stderr, "Failed to read data\n");
            continue;
        }

        // Convert and print data
        float temp = (float)data[0] / 65536.0 * 165.0 - 40.0;
        float humidity = (float)data[1] / 65536.0 * 100.0;

