#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define SENSOR_ADDRESS 0x60
#define READ_INTERVAL_MS 500

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_read_time = time(NULL);

    while (keep_running) {
        time_t current_time = time(NULL);
        if (difftime(current_time, last_read_time) >= READ_INTERVAL_MS / 1000.0) {
            char buffer[2];
            int bytes_read = i2cReadDevice(SENSOR_ADDRESS, buffer, 2);

            if (bytes_read == 2) {
                int pressure = (buffer[0] << 8) | buffer[1];
                time_t now;
                time(&now);
                printf("Timestamp: %sPressure: %d Pa\n", ctime(&now), pressure);
            } else if (bytes_read == -1) {
                fprintf(stderr, "I2C read error\n");
            } else {
                fprintf(stderr, "Unexpected I2C read result\n");
            }

            last_read_time = current_time;
        }
        gpioSleep(PI_TIME_RELATIVE, 0, 100000); // Sleep for 100ms
    }

    i2cClose(SENSOR_ADDRESS);
    gpioTerminate();
    return EXIT_SUCCESS;
}

