#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDRESS 0x63
#define CALIBRATION_COMMAND 0x50
#define MEASUREMENT_COMMAND 0x40
#define MEASUREMENT_WAIT_MS 7
#define CALIBRATION_DATA_SIZE 8
#define MEASUREMENT_DATA_SIZE 6

typedef struct {
    int32_t T1;
    int32_t T2;
    int32_t T3;
    int32_t P1;
    int32_t P2;
    int32_t P3;
    int32_t P4;
    int32_t P5;
    int32_t P6;
    int32_t P7;
    int32_t P8;
    int32_t P9;
} CalibrationData;

typedef struct {
    int32_t scale_factor_lut;
    int32_t scale_factor_h;
    int32_t scale_factor_p;
} ScalingFactors;

CalibrationData calibration_data;
ScalingFactors scaling_factors;
int i2c_handle;

void read_calibration_data() {
    char buffer[CALIBRATION_DATA_SIZE];
    int result = i2cReadI2CBlock(i2c_handle, SENSOR_ADDRESS, CALIBRATION_COMMAND, buffer, CALIBRATION_DATA_SIZE);
    if (result < 0) {
        fprintf(stderr, "Error reading calibration data: %s\n", gpioStrError(result));
        exit(EXIT_FAILURE);
    }

    calibration_data.T1 = (buffer[0] << 8) | buffer[1];
    calibration_data.T2 = (buffer[2] << 8) | buffer[3];
    calibration_data.T3 = (buffer[4] << 8) | buffer[5];
    calibration_data.P1 = (buffer[6] << 8) | buffer[7];
}

void compute_scaling_factors() {
    scaling_factors.scale_factor_lut = (calibration_data.T1 + calibration_data.T2 + calibration_data.T3) / 3;
    scaling_factors.scale_factor_h = 32768;
    scaling_factors.scale_factor_p = 65536;
}

void read_sensor_data() {
    char buffer[MEASUREMENT_DATA_SIZE];
    int result = i2cWriteByte(i2c_handle, SENSOR_ADDRESS, MEASUREMENT_COMMAND);
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %s\n", gpioStrError(result));
        return;
    }

    gpioSleep(PI_TIME_MILLISECONDS, MEASUREMENT_WAIT_MS, 0);

    result = i2cReadI2CBlock(i2c_handle, SENSOR_ADDRESS, 0x00, buffer, MEASUREMENT_DATA_SIZE);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %s\n", gpioStrError(result));
        return;
    }

    if (buffer[0] == 0xFF && buffer[1] == 0xFF && buffer[2] == 0xFF && buffer[3] == 0xFF && buffer[4] == 0xFF && buffer[5] == 0xFF) {
        fprintf(stderr, "Sensor read error: All bytes are 0xFF\n");
        return;
    }

    int32_t raw_temp = (buffer[0] << 8) | buffer[1];
    int32_t raw_pressure = (buffer[2] << 16) | (buffer[3] << 8) | buffer[4];

    float temperature = ((float)raw_temp / scaling_factors.scale_factor_lut) + 25.0;
    float pressure = ((float)raw_pressure / scaling_factors.scale_factor_p) + calibration_data.P1;

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
}

void signal_handler(int signum) {
    printf("Shutting down...\n");
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C handle creation failed: %s\n", gpioStrError(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    read_calibration_data();
    compute_scaling_factors();

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        read_sensor_data();
        gpioSleep(PI_TIME_SECONDS, 5, 0);
    }

    return EXIT_SUCCESS;
}

