#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x60
#define PRESSURE_REG_MSB 0xAA
#define PRESSURE_REG_LSB 0xAB
#define SCALING_FACTOR 0.1
#define MEASUREMENT_INTERVAL 1

static int i2c_fd;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read_word(int fd, uint8_t reg_msb, uint8_t reg_lsb) {
    uint8_t buf[2];
    if (write(fd, &reg_msb, 1) != 1 || read(fd, buf, 2) != 2) {
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (i2c_write(i2c_fd, 0x00, 0x00) != 1) {
            fprintf(stderr, "Failed to trigger measurement\n");
        } else {
            usleep(10000);  // Wait 10ms for measurement to complete

            int raw_pressure = i2c_read_word(i2c_fd, PRESSURE_REG_MSB, PRESSURE_REG_LSB);
            if (raw_pressure < 0) {
                fprintf(stderr, "Failed to read pressure value\n");
            } else {
                double pressure_kpa = raw_pressure * SCALING_FACTOR;
                time_t now = time(NULL);
                printf("%s: Pressure: %.1f kPa\n", ctime(&now), pressure_kpa);
            }
        }

        sleep(MEASUREMENT_INTERVAL);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

