#define SENSOR_ADDR 0x25
#define I2C_BUS 1
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define MEASUREMENT_DELAY_MS 8
#define LOG_FILE "airflow_log.csv"

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (i2cOpen(I2C_BUS, SENSOR_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Pressure(Pa)\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_log_time = 0;

    while (keep_running) {
        if (i2cWriteByteData(I2C_BUS, SENSOR_ADDR, 0x36) < 0 ||
            i2cWriteByteData(I2C_BUS, SENSOR_ADDR, 0x2F) < 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            break;
        }

        gpioSleep(PI_TIME_MILLISECONDS, MEASUREMENT_DELAY_MS);

        uint8_t data[3];
        if (i2cReadI2CBlock(I2C_BUS, SENSOR_ADDR, data, 3) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        uint16_t raw_value = (data[0] << 8) | data[1];
        uint8_t received_crc = data[2];
        uint8_t calculated_crc = calculate_crc8(data, 2);

        if (calculated_crc != received_crc) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        float pressure = (float)raw_value / 60.0;

        time_t current_time = time(NULL);
        if (current_time - last_log_time >= 1) {
            struct tm *tm_info = localtime(&current_time);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
            fflush(log_file);

            last_log_time = current_time;
        }
    }

    fclose(log_file);
    i2cClose(I2C_BUS);
    gpioTerminate();

    return EXIT_SUCCESS;
}

