#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define SENSOR_ADDRESS 0x40
#define PRESSURE_REGISTER 0x00
#define SCALE_FACTOR 0.01
#define SAFE_MIN_PRESSURE 200.0
#define SAFE_MAX_PRESSURE 250.0
#define LOG_FILE "pressure_log.csv"

static int i2c_handle;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "r+");
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "w");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        fprintf(log_file, "timestamp,pressure_kPa\n");
    } else {
        fseek(log_file, 0, SEEK_END);
        if (ftell(log_file) == 0) {
            fprintf(log_file, "timestamp,pressure_kPa\n");
        }
        fclose(log_file);
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file for appending\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        char buffer[3];
        int retry_count = 0;

        while (retry_count < 2) {
            if (i2cReadI2CBlockData(i2c_handle, PRESSURE_REGISTER, buffer, 3) == 3) {
                unsigned int raw_pressure = (buffer[0] << 8) | buffer[1];
                float pressure_kPa = raw_pressure * SCALE_FACTOR;

                time_t now = time(NULL);
                struct tm *utc_time = gmtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", utc_time);

                fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa);
                fflush(log_file);

                if (pressure_kPa < SAFE_MIN_PRESSURE || pressure_kPa > SAFE_MAX_PRESSURE) {
                    fprintf(stderr, "WARNING: Tire pressure out of safe range: %.2f kPa\n", pressure_kPa);
                }

                break;
            } else {
                fprintf(stderr, "I2C read failed, retrying...\n");
                i2cClose(i2c_handle);
                i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
                if (i2c_handle < 0) {
                    fprintf(stderr, "Failed to reopen I2C bus\n");
                    sleep(1);
                    continue;
                }
                retry_count++;
            }
        }

        if (retry_count == 2) {
            fprintf(stderr, "Failed to read pressure after retries\n");
        }

        sleep(1);
    }

    return EXIT_SUCCESS;
}

