#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x27
#define MEASUREMENT_TRIGGER 0x00
#define MEASUREMENT_DELAY_MS 40
#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE 1048576 // 1 MB

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_data(const char *timestamp, float temperature, float humidity) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    struct stat st;
    if (fstat(fileno(log_file), &st) == 0 && st.st_size >= MAX_LOG_SIZE) {
        fclose(log_file);
        remove(LOG_FILE);
        log_file = fopen(LOG_FILE, "w");
        if (log_file == NULL) {
            fprintf(stderr, "Error recreating log file: %s\n", strerror(errno));
            return;
        }
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (i2cOpen(I2C_BUS, SENSOR_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (keep_running) {
        char buf[4];
        time_t now;
        struct tm *tm_info;
        char timestamp[20];

        if (i2cWriteByte(SENSOR_ADDR, MEASUREMENT_TRIGGER) < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            sleep(5);
            continue;
        }

        time_msleep(MEASUREMENT_DELAY_MS);

        int bytes_read = i2cReadDevice(SENSOR_ADDR, buf, 4);
        if (bytes_read != 4) {
            fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
            sleep(5);
            continue;
