#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>

#define GPIO_PIN 4
#define TICK_TIME_US 3
#define SYNC_PULSE_TICKS 56
#define NIBBLE_MIN_TICKS 12
#define NIBBLE_MAX_TICKS 271
#define CHECKSUM_MODULO 16
#define RAW_SCALE 0.1 // Example scale factor
#define RAW_OFFSET 0.0 // Example offset

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int read_nibble(int *ticks) {
    int width = gpioTick() - *ticks;
    if (width < NIBBLE_MIN_TICKS || width > NIBBLE_MAX_TICKS) {
        return -1;
    }
    *ticks = gpioTick();
    return width / 12;
}

int read_sensor_data(int *data, int data_size) {
    int ticks = gpioTick();
    int nibble;
    int sum = 0;

    for (int i = 0; i < data_size; i++) {
        nibble = read_nibble(&ticks);
        if (nibble < 0) return -1;
        data[i] = nibble;
        sum += nibble;
    }

    nibble = read_nibble(&ticks);
    if (nibble < 0) return -1;
    int checksum = nibble;

    return (sum % CHECKSUM_MODULO == checksum) ? 0 : -1;
}

void log_pressure(double pressure) {
    FILE *log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f Pa\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, pressure);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_OFF);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        int sync_ticks = gpioWaitForEdge(GPIO_PIN, EITHER_EDGE, SYNC_PULSE_TICKS * TICK_TIME_US);
        if (sync_ticks < 0) {
            fprintf(stderr, "Sensor timeout or error\n");
            continue;
        }

        int data[3];
        if (read_sensor_data(data, 3) == 0) {
            int raw_value = (data[0] << 8) | data[1];
            double pressure = raw_value * RAW_SCALE + RAW_OFFSET;
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Checksum error or invalid pulse width\n");
        }
    }

    gpioTerminate();
    return 0;
}

