#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define SHT40_ADDRESS 0x44
#define MEASURE_CMD 0xFD
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

static int i2cHandle;
static FILE *logFile;

void cleanup(int signum) {
    if (i2cHandle >= 0) {
        gpioI2CClose(i2cHandle);
    }
    if (logFile != NULL) {
        fclose(logFile);
    }
    if (gpioInitialised()) {
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

uint8_t calculate_crc(uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2cHandle = gpioI2COpen(1, SHT40_ADDRESS, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    logFile = fopen("environmental_data.txt", "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    while (1) {
        char buf[6];
        if (gpioI2CWriteByte(i2cHandle, MEASURE_CMD) < 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            continue;
        }

        gpioSleep(PI_TIME_RELATIVE, 0, 8500000);

        if (gpioI2CReadDevice(i2cHandle, buf, 6) < 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            continue;
        }

        uint8_t temp_crc = calculate_crc(buf, 2);
        uint8_t hum_crc = calculate_crc(buf + 3, 2);

        if (buf[2] != temp_crc || buf[5] != hum_crc) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        uint16_t raw_temp = (buf[0] << 8) | buf[1];
        uint16_t raw_hum = (buf[3] << 8) | buf[4];

        float temperature = -45.0 + 175.0 * (float)raw_temp / 65535.0;
        float humidity = -6.0 + 125.0 * (float)raw_hum / 65535.0;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(logFile, "%s, Temperature: %.2f°C, Humidity: %.2f%%\n", timestamp, temperature, humidity);
        fflush(logFile);

        gpioSleep(PI_TIME_RELATIVE, 5, 0);
    }

    return EXIT_SUCCESS;
}

