#include <string.h>

#define I2C_BUS 1
#define TMP117_ADDRESS 0x48
#define TEMP_REGISTER 0x00
#define SAMPLE_INTERVAL 5
#define BUFFER_SIZE 100

typedef struct {
    int16_t temperature;
    time_t timestamp;
} SensorReading;

SensorReading circular_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;

void save_buffer_to_file() {
    FILE *file = fopen("temperature_log.dat", "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        fwrite(&circular_buffer[idx], sizeof(SensorReading), 1, file);
    }

    fclose(file);
}

void signal_handler(int signum) {
    save_buffer_to_file();
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        uint8_t data[2];
        if (i2cReadI2CBlock(i2c_handle, TEMP_REGISTER, data, 2) == 2) {
            int16_t raw_temp = (data[0] << 8) | data[1];
            float temperature = raw_temp * 0.0078125;

            circular_buffer[buffer_index].temperature = raw_temp;
            circular_buffer[buffer_index].timestamp = time(NULL);

            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            if (buffer_count < BUFFER_SIZE) {
                buffer_count++;
            }

            save_buffer_to_file();
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    return 0;
}
