#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define SHTC3_I2C_ADDR 0x70
#define SHTC3_I2C_BUS 1
#define SHTC3_MEASURE_CMD 0x7866
#define SHTC3_MEASURE_WAIT_MS 12
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static int i2cHandle;
static FILE *logFile;

void cleanup(int sig) {
    if (i2cHandle >= 0) {
        i2cClose(i2cHandle);
    }
    if (logFile) {
        fclose(logFile);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(float *temperature, float *humidity) {
    uint8_t buffer[6];
    int ret;

    ret = i2cWriteWordData(i2cHandle, SHTC3_MEASURE_CMD);
    if (ret < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }

    gpioSleep(PI_TIME_MILLISECONDS, SHTC3_MEASURE_WAIT_MS, 0);

    ret = i2cReadDevice(i2cHandle, buffer, sizeof(buffer));
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw_temp = (buffer[0] << 8) | buffer[1];
    uint16_t raw_hum = (buffer[3] << 8) | buffer[4];

    if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    *temperature = 175.0f * raw_temp / 65535.0f - 45.0f;
    *humidity = 100.0f * raw_hum / 65535.0f;

    if (*temperature < -40.0f || *temperature > 125.0f || *humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Sensor reading out of range\n");
        return -1;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2cHandle = i2cOpen(SHTC3_I2C_BUS, SHTC3_I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "I2C open error: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    logFile = fopen("shtc3_environment.log", "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    time_t lastLogTime = 0;

    while (1) {
        float temperature, humidity;
        if (read_sensor_data(&temperature, &humidity) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timeStr[20];
            strftime(timeStr, sizeof(timeStr), "%Y-%m-%d %H:%M:%S", tm_info);

            printf("%s,%.2f,%.2f\n", timeStr, temperature, humidity);

            if (difftime(now, lastLogTime) >= 5) {
                fprintf(logFile, "%s,%.2f,%.2f\n", timeStr, temperature, humidity);
                fflush(logFile);
                lastLogTime = now;
            }
        }
        sleep(1);
    }

    return EXIT_SUCCESS;
}

