#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>
#include <time.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x40
#define LOG_FILE "mag_temp_log.csv"
#define READ_INTERVAL_MS 1000

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int i2c_handle, file;
    char log_header[] = "Timestamp,Magnetic Field (G),Temperature (C)\n";
    char log_entry[100];
    time_t now;
    struct tm *timeinfo;
    int raw_value;
    double field_gauss, temp_celsius;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        gpioTerminate();
        return 1;
    }

    file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (ftell(file) == 0) {
        if (fwrite(log_header, sizeof(char), strlen(log_header), file) != strlen(log_header)) {
            fprintf(stderr, "Failed to write header to log file\n");
        }
    }

    signal(SIGINT, signal_handler);

    while (keep_running) {
        raw_value = i2cReadWordData(i2c_handle, 0x00);
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            field_gauss = NAN;
            temp_celsius = NAN;
        } else {
            field_gauss = raw_value * 0.1;
            temp_celsius = raw_value * 0.01 - 25.0;
        }

        time(&now);
        timeinfo = localtime(&now);
        strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S,", timeinfo);
        snprintf(log_entry + strlen(log_entry), sizeof(log_entry) - strlen(log_entry),
                 "%.1f,%.2f\n", field_gauss, temp_celsius);

        if (fwrite(log_entry, sizeof(char), strlen(log_entry), file) != strlen(log_entry)) {
            fprintf(stderr, "Failed to write to log file\n");
        }
        fflush(file);

        gpioSleep(PI_TIME_RELATIVE, READ_INTERVAL_MS / 1000, (READ_INTERVAL_MS % 1000) * 1000);
    }

    fclose(file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

