#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REGISTER 0x00
#define TEMP_RESOLUTION 0.0078125
#define MAX_REINIT_ATTEMPTS 3

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        keep_running = 0;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    int i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int reinit_attempts = 0;
    while (keep_running) {
        int16_t raw_temp;
        if (i2cReadWordData(i2c_handle, TEMP_REGISTER, &raw_temp) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            if (++reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max reinitialization attempts reached\n");
                break;
            }
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to reinitialize I2C device: %s\n", strerror(errno));
                break;
            }
            continue;
        }

        reinit_attempts = 0;  // Reset reinit attempts on successful read

        float temperature = raw_temp * TEMP_RESOLUTION;

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s, Temperature: %.2f C\n", timestamp, temperature);
        fflush(log_file);

        time_sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

