#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL 1000000 // 1 second in microseconds

static int i2c_handle;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    time_t last_read_time = 0;
    int read_count = 0;

    while (1) {
        char buffer[4];
        int bytes_read = i2cReadDevice(i2c_handle, buffer, 4);

        if (bytes_read == 4) {
            uint16_t raw_flow = (buffer[0] << 8) | buffer[1];
            uint16_t raw_temp = (buffer[2] << 8) | buffer[3];

            float flow_rate = ((raw_flow / 16384.0) - 0.1) / 0.8 * 25.0;
            float temperature = ((raw_temp / 4096.0) - 0.1) / 0.8 * 80.0 - 40.0;

            time_t current_time = time(NULL);
            if (current_time != last_read_time || read_count < 2) {
                fprintf(log_file, "[%ld] Flow: %.2f SLPM, Temperature: %.2f °C\n",
                        (long)current_time, flow_rate, temperature);
                fflush(log_file);
                last_read_time = current_time;
                read_count++;
            }
        } else {
            fprintf(log_file, "[%ld] I2C read error: %s\n", (long)time(NULL), strerror(errno));
            fflush(log_file);
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to reinitialize I2C device: %s\n", strerror(errno));
                cleanup(0);
            }
        }

        gpioSleep(Time_Relative, 0, SAMPLE_INTERVAL);
    }

    return EXIT_SUCCESS;
}

