#define DATA_BIT_HIGH_US_1 70
#define SAMPLE_INTERVAL 2

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_message(const char *message) {
    FILE *log_file = fopen("dht11_errors.log", "a");
    if (log_file) {
        time_t now = time(NULL);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fclose(log_file);
    }
}

int read_dht11(uint8_t *humidity, uint8_t *temperature) {
    uint8_t data[5] = {0};
    uint32_t start_time, current_time, bit_time;
    int bit_count = 0, byte_count = 0;

    gpioWrite(DHT_PIN, PI_LOW);
    gpioSleep(PI_TIME_MICROSECONDS, START_SIGNAL_US);
    gpioSetMode(DHT_PIN, PI_INPUT);

    start_time = gpioTick();
    while (gpioRead(DHT_PIN) == PI_LOW) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            log_message("Timeout waiting for response start");
            return -1;
        }
    }

    start_time = gpioTick();
    while (gpioRead(DHT_PIN) == PI_HIGH) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            log_message("Timeout waiting for response end");
            return -1;
        }
    }

    for (byte_count = 0; byte_count < 5; byte_count++) {
        for (bit_count = 0; bit_count < 8; bit_count++) {
            start_time = gpioTick();
            while (gpioRead(DHT_PIN) == PI_LOW) {
                if (gpioTick() - start_time > TIMEOUT_US) {
                    log_message("Timeout waiting for data bit start");
                    return -1;
                }
            }

            bit_time = gpioTick();
            while (gpioRead(DHT_PIN) == PI_HIGH) {
                if (gpioTick() - bit_time > TIMEOUT_US) {
                    log_message("Timeout waiting for data bit end");
                    return -1;
                }
            }

            if (gpioTick() - bit_time > DATA_BIT_HIGH_US_1) {
                data[byte_count] |= (1 << (7 - bit_count));
            }
        }
    }

    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        log_message("Checksum error");
        return -1;
    }

    *humidity = data[0];
    *temperature = data[2];
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        uint8_t humidity, temperature;
        if (read_dht11(&humidity, &temperature) == 0) {
            FILE *readings_file = fopen("dht11_readings.txt", "a");
            if (readings_file) {
                time_t now = time(NULL);
                char timestamp[64];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
                fprintf(readings_file, "%s, %d, %d\n", timestamp, humidity, temperature);
                fclose(readings_file);
            }
        }
        sleep(SAMPLE_INTERVAL);
    }

    gpioTerminate();
    return 0;
}

