#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define SHT31_ADDR 0x44
#define I2C_BUS 1
#define MEASURE_CMD 0x2C06
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define RETRY_LIMIT 3
#define LOG_FILE "sht31d_data.log"
#define LOG_INTERVAL 5

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_log_time = time(NULL);

    while (keep_running) {
        uint8_t write_buf[2] = {MEASURE_CMD >> 8, MEASURE_CMD & 0xFF};
        uint8_t read_buf[6];

        int retries = 0;
        while (retries < RETRY_LIMIT) {
            if (i2cWriteDevice(i2c_handle, write_buf, 2) < 0) {
                retries++;
                continue;
            }
            usleep(15000);  // 15 ms delay

            if (i2cReadDevice(i2c_handle, read_buf, 6) == 6) {
                break;
            }
            retries++;
        }

        if (retries == RETRY_LIMIT) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(stderr, "[%s] Error: Failed to read from SHT31-D sensor\n", timestamp);
            sleep(1);
            continue;
        }

        uint8_t temp_crc = calculate_crc8(read_buf, 2);
        uint8_t hum_crc = calculate_crc8(read_buf + 3, 2);

        if (temp_crc != read_buf[2] || hum_crc != read_buf[5]) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(stderr, "[%s] Error: CRC check failed\n", timestamp);
            continue;
        }

        uint16_t raw_temp = (read_buf[0] << 8) | read_buf[1];
        uint16_t raw_hum = (read_buf[3] << 8) | read_buf[4];

        float temperature = -45.0 + 175.0 * raw_temp / 65535.0;
        float humidity = 100.0 * raw_hum / 65535.0;

        time_t now = time(NULL);
        if (now - last_log_time >= LOG_INTERVAL) {
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(log_file, "[%s],%.2f,%.2f\n", timestamp, temperature, humidity);
            fflush(log_file);
            last_log_time = now;
        }

        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

