#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SENSOR_1_ADDR 0x64
#define SENSOR_2_ADDR 0x65
#define DEVICE_ID_REG 0x00
#define DEVICE_ID 0x2A
#define RED_REG 0x64
#define GREEN_REG 0x66
#define BLUE_REG 0x68
#define I2C_BUS 1
#define LOG_FILE "cct_log.csv"
#define LOG_INTERVAL 1000000000L // 1 second in nanoseconds

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

double calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    double X = (-0.14282) * red + (1.54924) * green + (-0.95641) * blue;
    double Y = (-0.32466) * red + (1.57837) * green + (-0.73191) * blue;
    double Z = (-0.68202) * red + (0.77073) * green + (0.56332) * blue;

    double x = X / (X + Y + Z);
    double y = Y / (X + Y + Z);

    double n = (x - 0.3320) / (0.1858 - y);

    double cct = 449.0 * n * n * n + 3525.0 * n * n + 6823.3 * n + 5520.33;

    return cct;
}

void log_cct(double cct) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Error opening log file");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

    fprintf(file, "%s,%f\n", timestamp, cct);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (i2cOpen(I2C_BUS, SENSOR_1_ADDR, 0) < 0 || i2cOpen(I2C_BUS, SENSOR_2_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(I2C_BUS, SENSOR_1_ADDR);
        i2cClose(I2C_BUS, SENSOR_2_ADDR);
        gpioTerminate();
        return 1;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }
    fclose(log_file);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        uint8_t data[2];
        double cct_sum = 0.0;
        int valid_sensors = 0;

        for (int addr : (int[]){SENSOR_1_ADDR, SENSOR_2_ADDR}) {
            if (i2cWriteByteData(I2C_BUS, addr, DEVICE_ID_REG) < 0 ||
                i2cReadByteData(I2C_BUS, addr, DEVICE_ID_REG) != DEVICE_ID) {
                fprintf(stderr, "Sensor at address 0x%02X not found or error reading device ID\n", addr);
                continue;
            }

            for (int reg : (int[]){RED_REG, GREEN_REG, BLUE_REG}) {
                if (i2cReadI2CBlockData(I2C_BUS, addr, reg, 2, data) < 0) {
                    fprintf(stderr, "Error reading data from sensor at address 0x%02X\n", addr);
                    goto next_sensor;
                }
            }

            uint16_t red = data[0] | (data[1] << 8);
            uint16_t green = data[0] | (data[1] << 8);
            uint16_t blue = data[0] | (data[1] << 8);

            double cct = calculate_cct(red, green, blue);
            cct_sum += cct;
            valid_sensors++;

        next_sensor:
            continue;
        }

        if (valid_sensors > 0) {
            double average_cct = cct_sum / valid_sensors;
            log_cct(average_cct);
        }

        time_sleep(1);
    }

    i2cClose(I2C_BUS, SENSOR_1_ADDR);
    i2cClose(I2C_BUS, SENSOR_2_ADDR);
    gpioTerminate();
    return 0;
}

