        i2cClose(I2C_BUS, SENSOR_2_ADDR);
        gpioTerminate();
        return 1;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }
    fclose(log_file);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        uint8_t data[2];
        double cct_sum = 0.0;
        int valid_sensors = 0;

        for (int addr : (int[]){SENSOR_1_ADDR, SENSOR_2_ADDR}) {
            if (i2cWriteByteData(I2C_BUS, addr, DEVICE_ID_REG) < 0 ||
                i2cReadByteData(I2C_BUS, addr, DEVICE_ID_REG) != DEVICE_ID) {
                fprintf(stderr, "Sensor at address 0x%02X not found or error reading device ID\n", addr);
                continue;
            }

            for (int reg : (int[]){RED_REG, GREEN_REG, BLUE_REG}) {
                if (i2cReadI2CBlockData(I2C_BUS, addr, reg, 2, data) < 0) {
                    fprintf(stderr, "Error reading data from sensor at address 0x%02X\n", addr);
                    goto next_sensor;
                }
            }

            uint16_t red = data[0] | (data[1] << 8);
            uint16_t green = data[0] | (data[1] << 8);
            uint16_t blue = data[0] | (data[1] << 8);

            double cct = calculate_cct(red, green, blue);
            cct_sum += cct;
            valid_sensors++;

        next_sensor:
            continue;
        }

        if (valid_sensors > 0) {
            double average_cct = cct_sum / valid_sensors;
            log_cct(average_cct);
        }

        time_sleep(1);
    }

    i2cClose(I2C_BUS, SENSOR_1_ADDR);
    i2cClose(I2C_BUS, SENSOR_2_ADDR);
    gpioTerminate();
    return 0;
}
