#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 60
#define FAN_PIN 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 26.0

typedef struct {
    float temperatures[BUFFER_SIZE];
    int index;
    int count;
} CircularBuffer;

CircularBuffer buffer = { .index = 0, .count = 0 };

void cleanup(int status) {
    gpioWrite(FAN_PIN, 0);
    gpioTerminate();
    exit(status);
}

void signalHandler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        cleanup(0);
    }
}

float readLM75B(int i2cHandle) {
    char data[2];
    if (i2cReadI2CBlock(i2cHandle, LM75B_ADDR, TEMP_REG, 2, data) < 0) {
        fprintf(stderr, "Failed to read temperature\n");
        return -1;
    }
    int raw = (data[0] << 8) | data[1];
    raw >>= 5; // Align to 9-bit signed format
    return raw * 0.5;
}

void updateBuffer(float temp) {
    buffer.temperatures[buffer.index] = temp;
    buffer.index = (buffer.index + 1) % BUFFER_SIZE;
    if (buffer.count < BUFFER_SIZE) {
        buffer.count++;
    }
}

float computeAverage() {
    float sum = 0.0;
    for (int i = 0; i < buffer.count; i++) {
        sum += buffer.temperatures[i];
    }
    return sum / buffer.count;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2cHandle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioWrite(FAN_PIN, 0);

    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    float lastAvg = 0.0;
    int fanState = 0;

    while (1) {
        float temp = readLM75B(i2cHandle);
        if (temp < 0) {
            sleep(1);
            continue;
        }

        updateBuffer(temp);
        float avg = computeAverage();

        if (avg > TEMP_THRESHOLD_HIGH && !fanState) {
            gpioWrite(FAN_PIN, 1);
            fanState = 1;
        } else if (avg < TEMP_THRESHOLD_LOW && fanState) {
            gpioWrite(FAN_PIN, 0);
            fanState = 0;
        }

        lastAvg = avg;
        sleep(1);
    }

    cleanup(0);
    return 0;
}

