#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>

#define SDP810_I2C_ADDR 0x25
#define SDP810_MEASURE_CMD 0x362F
#define SDP810_WAIT_TIME 45
#define SDP810_DATA_SIZE 9
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("airflow.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, SDP810_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t cmd[2] = {SDP810_MEASURE_CMD >> 8, SDP810_MEASURE_CMD & 0xFF};
    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Failed to send measurement command\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    time_t last_log_time = 0;

    while (keep_running) {
        usleep(SDP810_WAIT_TIME * 1000);

        uint8_t data[SDP810_DATA_SIZE];
        if (i2cReadDevice(i2c_handle, data, SDP810_DATA_SIZE) != SDP810_DATA_SIZE) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        for (int i = 0; i < 3; i++) {
            if (calculate_crc8(data + i * 3, 2) != data[i * 3 + 2]) {
                fprintf(stderr, "CRC mismatch for data set %d\n", i + 1);
                continue;
            }
        }

        int16_t pressure = (data[0] << 8) | data[1];
        int16_t temperature = (data[3] << 8) | data[4];

        float pressure_pa = pressure * 60.0f;
        float temperature_c = temperature * 200.0f / 100.0f;

        time_t current_time = time(NULL);
        if (current_time - last_log_time >= 1) {
            fprintf(log_file, "%ld,%f,%f\n", (long)current_time, pressure_pa, temperature_c);
            fflush(log_file);

            if (pressure_pa > 5.0f) {
                fprintf(stderr, "WARNING: Pressure exceeds 5.0 Pa at %f Pa\n", pressure_pa);
            }

            last_log_time = current_time;
        }

        if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
            fprintf(stderr, "Failed to send measurement command\n");
            break;
        }
    }

    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

