#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x4A
#define TEMP_REG 0x00
#define LED_GPIO 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define MAX_RETRIES 3

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;

void cleanup(int signum) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int read_i2c_register(int reg) {
    unsigned char buf[2];
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to I2C register");
        return -1;
    }
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read from I2C register");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

int main() {
    int retries = 0;
    int16_t raw_temp;
    float temperature;
    int led_state = 0;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        raw_temp = read_i2c_register(TEMP_REG);
        if (raw_temp < 0) {
            if (++retries >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                cleanup(0);
            }
            fprintf(stderr, "I2C read error. Retrying...\n");
            sleep(1);
            continue;
        }
        retries = 0;

        temperature = (float)(raw_temp >> 4) * 0.0625;
        printf("Temperature: %.2f°C\n", temperature);

