#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define SENSOR_ADDRESS 0x25
#define I2C_BUS 1
#define DIFF_PRESSURE_COMMAND 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

static volatile int keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = 0;
    }
}

uint8_t calculate_crc8(const uint8_t *data, int length) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    FILE *file = fopen("flow_data.txt", "w");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        if (i2cWriteWordData(I2C_BUS, SENSOR_ADDRESS, DIFF_PRESSURE_COMMAND) < 0) {
            fprintf(stderr, "Failed to send command\n");
            break;
        }

        usleep(45000);  // 45 ms

        uint8_t buffer[9];
        if (i2cReadDevice(I2C_BUS, SENSOR_ADDRESS, buffer, 9) < 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            break;
        }

        if (calculate_crc8(buffer, 2) != buffer[2] || calculate_crc8(buffer + 3, 2) != buffer[5]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        int32_t diff_pressure = (buffer[0] << 8) | buffer[1];
        int32_t scale_factor = (buffer[6] << 8) | buffer[7];
        float pressure = diff_pressure / (float)scale_factor;

        int16_t raw_temp = (buffer[3] << 8) | buffer[4];
        float temperature = raw_temp / 200.0f;

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(file, "%s, Pressure: %.2f Pa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
        fflush(file);
    }

    fclose(file);
    i2cClose(I2C_BUS);
    gpioTerminate();
    return 0;
}

