#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define SENSOR_ADDR 0x40
#define I2C_BUS 1
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL 60
#define LOG_FILE "environment.log"

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int i2c_retry(int fd, char *buf, int count, int retries) {
    int result;
    for (int i = 0; i < retries; i++) {
        result = i2cReadDevice(fd, buf, count);
        if (result >= 0) return result;
        usleep(10000); // 10ms delay before retry
    }
    return -1;
}

int read_sensor(int fd, uint8_t command, uint16_t *value) {
    uint8_t buf[3];
    buf[0] = command;

    if (i2cWriteDevice(fd, buf, 1) < 0) return -1;
    usleep(20000); // 20ms delay for no-hold mode

    if (i2c_retry(fd, buf, 3, MAX_RETRIES) < 0) return -1;

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

void log_message(const char *message) {
    time_t now;
    time(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

    fprintf(stderr, "[%s] %s\n", timestamp, message);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fflush(log_file);
        fclose(log_file);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize gpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    // Validate sensor presence
    uint8_t buf[1];
    if (i2c_retry(i2c_handle, buf, 1, MAX_RETRIES) < 0 || buf[0] != 0x0D) {
        log_message("Sensor not found or communication error");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        uint16_t raw_temp, raw_humidity;
        float temperature, humidity;

        if (read_sensor(i2c_handle, 0xF5, &raw_humidity) == 0 &&
            read_sensor(i2c_handle, 0xE0, &raw_temp) == 0) {

            temperature = 175.72 * raw_temp / 65536.0 - 46.85;
            humidity = 125.0 * raw_humidity / 65536.0 - 6.0;

            if (temperature < 0) temperature = 0;
            if (temperature > 100) temperature = 100;
            if (humidity < 0) humidity = 0;
            if (humidity > 100) humidity = 100;

            time_t now;
            time(&now);
            char timestamp[26];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

            printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);
            fflush(stdout);

            log_message("Sensor reading successful");
        } else {
            log_message("Failed to read sensor data");
        }

        sleep(SAMPLE_INTERVAL);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

