#include <unistd.h>

#define I2C_BUS 1
#define SDP810_ADDRESS 0x25
#define MEASURE_COMMAND 0x3615
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, int length) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("hvac_pressure_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    uint8_t command[2] = {MEASURE_COMMAND >> 8, MEASURE_COMMAND & 0xFF};
    uint8_t buffer[9];

    while (keep_running) {
        if (i2cWriteDevice(i2c_handle, command, 2) < 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        usleep(50000);  // 50 ms delay

        if (i2cReadDevice(i2c_handle, buffer, 9) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        uint8_t pressure_crc = buffer[2];
        uint8_t temperature_crc = buffer[5];
        uint8_t scale_crc = buffer[8];

        if (calculate_crc8(buffer, 2) != pressure_crc ||
            calculate_crc8(buffer + 3, 2) != temperature_crc ||
            calculate_crc8(buffer + 6, 3) != scale_crc) {
            fprintf(stderr, "CRC error at %s\n", timestamp);
            continue;
        }

        int32_t raw_pressure = (buffer[0] << 8) | buffer[1];
        int32_t raw_temperature = (buffer[3] << 8) | buffer[4];
        int32_t scale_factor = (buffer[6] << 16) | (buffer[7] << 8) | buffer[8];

        float pressure = (float)raw_pressure / scale_factor;
        float temperature = (float)raw_temperature / 200.0;

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

