#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define BUFFER_CAPACITY 100
#define LOG_FILE "/var/log/scd40_error.log"
#define DATA_DIR "/var/log/scd40_data/"
#define DATA_FILE_PREFIX "scd40_data_"
#define DATA_FILE_SUFFIX ".csv"
#define LOG_INTERVAL 60

typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} SensorData;

typedef struct {
    SensorData data[BUFFER_CAPACITY];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

volatile sig_atomic_t running = 1;
CircularBuffer buffer = {.head = 0, .tail = 0, .count = 0};

void log_error(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "[%s] %s\n", time_str, message);
        fclose(log_file);
    }
}

uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void *logging_thread(void *arg) {
    while (running) {
        sleep(LOG_INTERVAL);

        time_t now;
        time(&now);
        struct tm *tm_info = localtime(&now);
        char filename[256];
        snprintf(filename, sizeof(filename), "%s%s%04d%02d%02d_%02d%02d%02d%s",
                 DATA_DIR, DATA_FILE_PREFIX,
                 tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                 tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, DATA_FILE_SUFFIX);

        mkdir(DATA_DIR, 0755); // Create directory if it doesn't exist

        FILE *file = fopen(filename, "w");
        if (file) {
            fprintf(file, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%)\n");

            pthread_mutex_lock(&buffer.mutex);
            for (int i = 0; i < buffer.count; i++) {
                int index = (buffer.head + i) % BUFFER_CAPACITY;
                const SensorData *data = &buffer.data[index];
                fprintf(file, "%ld,%f,%.2f,%.2f\n", data->timestamp, data->co2, data->temperature, data->humidity);
            }
            pthread_mutex_unlock(&buffer.mutex);

            fclose(file);
        } else {
            log_error("Failed to open data file for writing");
        }
    }
    return NULL;
}

void handle_sigint(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    pthread_t log_thread;
    if (pthread_create(&log_thread, NULL, logging_thread, NULL) != 0) {
        log_error("Failed to create logging thread");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    uint8_t start_cmd[] = {0x21, 0xB1};
    if (i2cWriteDevice(i2c_handle, start_cmd, sizeof(start_cmd)) < 0) {
        log_error("Failed to send start command");
    } else {
        sleep(1); // Wait at least 1 second
    }

    while (running) {
        uint8_t read_cmd[] = {0xE0, 0x00};
        if (i2cWriteDevice(i2c_handle, read_cmd, sizeof(read_cmd)) < 0) {
            log_error("Failed to send read command");
            sleep(5);
            continue;
        }

        uint8_t data[9];
        if (i2cReadDevice(i2c_handle, data, sizeof(data)) < 0) {
            log_error("Failed to read data from sensor");
            sleep(5);
            continue;
        }

        // Validate CRC for each 3-byte value
        if (calculate_crc8(data, 2) != data[2] ||
            calculate_crc8(data + 3, 2) != data[5] ||
            calculate_crc8(data + 6, 2) != data[8]) {
            log_error("CRC check failed");
            sleep(5);
            continue;
        }

        uint16_t co2 = (data[0] << 8) | data[1];
        uint16_t temperature = (data[3] << 8) | data[4];
        uint16_t humidity = (data[6] << 8) | data[7];

        SensorData sensor_data = {
            .timestamp = time(NULL),
            .co2 = co2,
            .temperature = -45.0 + 175.0 * temperature / 65535.0,
            .humidity = 100.0 * humidity / 65535.0
        };

        pthread_mutex_lock(&buffer.mutex);
        if (buffer.count < BUFFER_CAPACITY) {
            buffer.data[buffer.tail] = sensor_data;
            buffer.tail = (buffer.tail + 1) % BUFFER_CAPACITY;
            buffer.count++;
        } else {
            buffer.head = (buffer.head + 1) % BUFFER_CAPACITY;
            buffer.data[buffer.tail] = sensor_data;
            buffer.tail = (buffer.tail + 1) % BUFFER_CAPACITY;
        }
        pthread_mutex_unlock(&buffer.mutex);

        sleep(5);
    }

    // Stop periodic measurement
    uint8_t stop_cmd[] = {0x3F, 0x86};
    i2cWriteDevice(i2c_handle, stop_cmd, sizeof(stop_cmd));

    pthread_join(log_thread, NULL);

    // Flush remaining buffer data to final CSV file
    time_t now;
    time(&now);
    struct tm *tm_info = localtime(&now);
    char filename[256];
    snprintf(filename, sizeof(filename), "%s%s%04d%02d%02d_%02d%02d%02d%s",
             DATA_DIR, DATA_FILE_PREFIX,
             tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
             tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, DATA_FILE_SUFFIX);

    FILE *file = fopen(filename, "w");
    if (file) {
        fprintf(file, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%)\n");

        pthread_mutex_lock(&buffer.mutex);
        for (int i = 0; i < buffer.count; i++) {
            int index = (buffer.head + i) % BUFFER_CAPACITY;
            const SensorData *data = &buffer.data[index];
            fprintf(file, "%ld,%f,%.2f,%.2f\n", data->timestamp, data->co2, data->temperature, data->humidity);
        }
        pthread_mutex_unlock(&buffer.mutex);

        fclose(file);
    } else {
        log_error("Failed to open final data file for writing");
    }

    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

