#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define I2C_BUS 1
#define SENSOR_ADDRESS 0x63
#define WHO_AM_I_REG 0x08
#define CALIB_COEFF_START_REG 0x05
#define CALIB_COEFF_COUNT 4
#define MEASURE_REG 0x00
#define DATA_COUNT 6
#define SAMPLE_INTERVAL 5

volatile sig_atomic_t exit_flag = 0;

void signal_handler(int signum) {
    exit_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i;
    if (i2cReadByteData(i2c_handle, WHO_AM_I_REG, &who_am_i) < 0 || who_am_i != 0x08) {
        fprintf(stderr, "Sensor identity verification failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int16_t calib_coeff[CALIB_COEFF_COUNT];
    if (i2cReadI2CBlockData(i2c_handle, CALIB_COEFF_START_REG, (char *)calib_coeff, CALIB_COEFF_COUNT * 2) < 0) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    FILE *file = fopen("environmental_data.txt", "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    uint8_t data[DATA_COUNT];
    while (!exit_flag) {
        if (i2cWriteByteData(i2c_handle, MEASURE_REG, 0x00) < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue;
        }

        gpioSleep(PI_TIME_RELATIVE, 0, 10000);

        if (i2cReadI2CBlockData(i2c_handle, MEASURE_REG, (char *)data, DATA_COUNT) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        int32_t pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
        int16_t temperature = ((int16_t)data[3] << 8) | data[4];

        float pressure_hPa = (float)pressure / 256.0f;
        float temperature_C = (float)temperature / 256.0f;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        fprintf(file, "%s, %.2f hPa, %.2f C\n", timestamp, pressure_hPa, temperature_C);
        fflush(file);

        printf("%s, %.2f hPa, %.2f C\n", timestamp, pressure_hPa, temperature_C);

        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL, 0);
    }

    fclose(file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

