#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define ICP10125_ADDR 0x63
#define OTP_COEFF_REG 0x66
#define MEASURE_CMD 0x4011
#define CRC_POLYNOMIAL 0x1021
#define CRC_INIT 0xFFFF

static int i2c_fd;
static struct gpiod_line *led_line;

void cleanup(int signum) {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

uint16_t calculate_crc(uint8_t *data, int length) {
    uint16_t crc = CRC_INIT;
    for (int i = 0; i < length; i++) {
        crc ^= (uint16_t)data[i] << 8;
        for (int j = 0; j < 8; j++) {
            if (crc & 0x8000) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_i2c(uint8_t reg, uint8_t *buf, int len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

int write_i2c(uint8_t reg, uint8_t *buf, int len) {
    uint8_t write_buf[len + 1];
    write_buf[0] = reg;
    memcpy(&write_buf[1], buf, len);
    if (write(i2c_fd, write_buf, len + 1) != len + 1) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

int main() {
    struct i2c_msg messages[2];
    uint8_t buf[8];
    int16_t pressure, temperature;
    uint16_t crc;
    struct gpiod_chip *chip;
    struct timespec led_on, led_off;
    int led_state = 0;

    signal(SIGINT, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, ICP10125_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (read_i2c(OTP_COEFF_REG, buf, 8) < 0) {
        cleanup(0);
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup(0);
    }

    led_line = gpiod_chip_get_line(chip, 17);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        cleanup(0);
    }

    if (gpiod_line_request_output(led_line, "ICP10125_LED", 0) < 0) {
        perror("Failed to request LED line");
        gpiod_chip_close(chip);
        cleanup(0);
    }

    led_on.tv_sec = 0;
    led_on.tv_nsec = 500000000;
    led_off.tv_sec = 0;
    led_off.tv_nsec = 500000000;

    while (1) {
        if (write_i2c(0x10, (uint8_t *)&MEASURE_CMD, 2) < 0) {
            cleanup(0);
        }

        usleep(20000);

        messages[0].addr = ICP10125_ADDR;
        messages[0].flags = 0;
        messages[0].len = 6;
        messages[0].buf = buf;

        messages[1].addr = ICP10125_ADDR;
        messages[1].flags = I2C_M_RD;
        messages[1].len = 6;
        messages[1].buf = buf;

        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            perror("Failed to perform I2C transaction");
            cleanup(0);
        }

        pressure = (int16_t)((buf[0] << 8) | buf[1]);
        temperature = (int16_t)((buf[2] << 8) | buf[3]);
        crc = (uint16_t)((buf[4] << 8) | buf[5]);

        if (calculate_crc(buf, 4) != crc) {
            fprintf(stderr, "CRC check failed\n");
            cleanup(0);
        }

        float pressure_pa = pressure * 25.0f + 101325.0f;
        float temperature_c = temperature / 100.0f;

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure_pa, temperature_c);

        if (pressure_pa < 95000) {
            nanosleep(&led_on, NULL);
            gpiod_line_set_value(led_line, 1);
            nanosleep(&led_off, NULL);
            gpiod_line_set_value(led_line, 0);
            nanosleep(&led_on, NULL);
            gpiod_line_set_value(led_line, 1);
            nanosleep(&led_off, NULL);
            gpiod_line_set_value(led_line, 0);
        } else {
            nanosleep(&led_on, NULL);
            gpiod_line_set_value(led_line, 1);
            nanosleep(&led_off, NULL);
            gpiod_line_set_value(led_line, 0);
        }

        sleep(1);
    }

    cleanup(0);
}

