#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_PIN 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

double read_temperature(int i2c_handle, uint8_t reg) {
    uint16_t raw;
    int retries = 0;

    do {
        if (i2c_read_word_data(i2c_handle, reg, &raw) == 0) {
            return raw * 0.02 - 273.15;
        }
        gpioDelay(RETRY_DELAY_MS * 1000);
    } while (++retries < RETRY_COUNT);

    return -273.15; // Invalid temperature
}

int main() {
    int i2c_handle;
    double ambient_temp, object_temp;
    FILE *log_file;
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];
    int fan_state = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioWrite(FAN_PIN, 0);

    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        ambient_temp = read_temperature(i2c_handle, AMBIENT_TEMP_REG);
        object_temp = read_temperature(i2c_handle, OBJECT_TEMP_REG);

        if (ambient_temp > -273.15 && object_temp > -273.15) {
            time(&now);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s, Ambient: %.2f°C, Object: %.2f°C\n", timestamp, ambient_temp, object_temp);
            fflush(log_file);

            if (object_temp > TEMP_THRESHOLD_HIGH && !fan_state) {
                gpioWrite(FAN_PIN, 1);
                fan_state = 1;
            } else if (object_temp < TEMP_THRESHOLD_LOW && fan_state) {
                gpioWrite(FAN_PIN, 0);
                fan_state = 0;
            }
        }

        sleep(2);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioWrite(FAN_PIN, 0);
    gpioTerminate();

    return 0;
}

