#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define SHT40_ADDR 0x44
#define SHT40_MEASURE_CMD 0xFD
#define SHT40_RETRIES 3
#define SHT40_DELAY_MS 10
#define SERVER_PORT 8080
#define BUFFER_SIZE 1024

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int i2c_read_sht40(int fd, uint16_t *temp, uint16_t *humidity) {
    uint8_t buffer[6];
    int retries = 0;

    while (retries < SHT40_RETRIES) {
        if (i2cWrite(fd, &SHT40_MEASURE_CMD, 1) < 0) {
            fprintf(stderr, "I2C write error\n");
            retries++;
            continue;
        }

        gpioDelay(SHT40_DELAY_MS * 1000);

        if (i2cRead(fd, buffer, 6) < 0) {
            fprintf(stderr, "I2C read error\n");
            retries++;
            continue;
        }

        uint16_t raw_temp = (buffer[0] << 8) | buffer[1];
        uint16_t raw_humidity = (buffer[3] << 8) | buffer[4];

        *temp = -45 + 175 * raw_temp / 65535;
        *humidity = -6 + 125 * raw_humidity / 65535;

        if (*humidity > 100) {
            *humidity = 100;
        }

        return 0;
    }

    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Socket creation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(SERVER_PORT);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 1) < 0) {
        perror("Listen failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", SERVER_PORT);

    while (keep_running) {
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            perror("Accept failed");
            continue;
        }

        uint16_t temp, humidity;
        if (i2c_read_sht40(i2c_handle, &temp, &humidity) == 0) {
            char response[BUFFER_SIZE];
            snprintf(response, sizeof(response),
                     "HTTP/1.1 200 OK\r\n"
                     "Content-Type: text/html\r\n"
                     "Connection: close\r\n"
                     "\r\n"
                     "<html><body><h1>Temperature and Humidity</h1>"
                     "<p>Temperature: %d°C</p>"
                     "<p>Humidity: %d%%</p></body></html>",
                     temp, humidity);

            send(client_fd, response, strlen(response), 0);
        } else {
            const char *error_msg = "HTTP/1.1 500 Internal Server Error\r\n"
                                    "Content-Type: text/plain\r\n"
                                    "Connection: close\r\n"
                                    "\r\n"
                                    "Failed to read sensor data";
            send(client_fd, error_msg, strlen(error_msg), 0);
        }

        close(client_fd);
    }

    close(server_fd);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

