#define TMP102_ADDR 0x48
#define TMP102_REG_TEMP 0x00
#define I2C_BUS 1
#define LOG_FILE "temperature_log.csv"
#define READ_INTERVAL 5

static volatile int keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = 0;
    }
}

int main() {
    FILE *log_file;
    time_t raw_time;
    struct tm *time_info;
    char timestamp[20];
    int i2c_handle;
    int16_t raw_temp;
    float temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (keep_running) {
        if (i2cReadWordData(i2c_handle, TMP102_REG_TEMP, &raw_temp) < 0) {
            fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
        } else {
            temperature = ((float)raw_temp >> 4) * 0.0625;

            time(&raw_time);
            time_info = localtime(&raw_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

            fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
            fflush(log_file);
        }

        time_sleep(READ_INTERVAL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

