#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x40
#define MEASUREMENT_CONFIG_REG 0x0E
#define CONFIG_REG 0x0F
#define TEMP_REG 0x00
#define HUM_REG 0x02
#define MAX_RETRIES 3
#define TIMEOUT_MS 500

volatile sig_atomic_t terminate = 0;

void signalHandler(int signum) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (setmode(0, PI_ALT0) < 0 || setmode(1, PI_ALT0) < 0) {
        fprintf(stderr, "Failed to set I2C mode\n");
        gpioTerminate();
        return 1;
    }

    int i2cHandle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signalHandler);

    uint8_t config[2] = {CONFIG_REG, 0x00}; // Heater disabled, 14-bit resolution
    if (i2cWriteDevice(i2cHandle, config, 2) < 0) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    while (!terminate) {
        uint8_t trigger[2] = {MEASUREMENT_CONFIG_REG, 0x01};
        if (i2cWriteDevice(i2cHandle, trigger, 2) < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue;
        }

        int retries = 0;
        while (retries < MAX_RETRIES) {
            uint8_t status;
