#include <unistd.h>
#include <stdint.h>

#define SENSOR_ADDR 0x25
#define I2C_BUS 1
#define MEASURE_CMD 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define LOG_INTERVAL_MS 500
#define MEASUREMENT_DELAY_MS 45

// Function to calculate CRC-8
uint8_t calculate_crc8(const uint8_t *data, int length) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to handle SIGINT
void signal_handler(int signo) {
    if (signo == SIGINT) {
        printf("Shutting down...\n");
        gpioTerminate();
        exit(0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    uint8_t cmd[2] = {MEASURE_CMD >> 8, MEASURE_CMD & 0xFF};
    uint8_t read_buffer[6];

    while (1) {
        if (i2cWriteDevice(i2c_handle, cmd, 2) < 0) {
            fprintf(stderr, "Failed to write to sensor\n");
            break;
        }

        usleep(MEASUREMENT_DELAY_MS * 1000);

        if (i2cReadDevice(i2c_handle, read_buffer, 6) < 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            break;
        }

        uint8_t pressure_crc = read_buffer[2];
        uint8_t temp_crc = read_buffer[5];

        if (calculate_crc8(read_buffer, 2) != pressure_crc || calculate_crc8(read_buffer + 3, 2) != temp_crc) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        int16_t pressure = (read_buffer[0] << 8) | read_buffer[1];
        int16_t temperature = (read_buffer[3] << 8) | read_buffer[4];

        printf("Pressure: %d, Temperature: %d\n", pressure, temperature);

        usleep(LOG_INTERVAL_MS * 1000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

