#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN 17
#define PID_KP 1.0
#define PID_KI 0.1
#define PID_KD 0.01
#define PROFILE_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"

typedef struct {
    double kp, ki, kd;
    double integral, previous_error;
} PIDController;

typedef struct {
    int time_seconds;
    double target_temp_celsius;
} ProfileEntry;

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "reflow_relay", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

int setup_spi() {
    int spi_fd;
    int mode = SPI_MODE_0;
    int bits = 8;
    int speed = 500000;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        return -1;
    }

    return spi_fd;
}

double read_temperature(int spi_fd) {
    uint8_t tx[3] = {0x00, 0x00, 0x00};
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = 500000,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to transfer SPI data");
        return -1;
    }

    uint16_t raw = (rx[0] << 8) | rx[1];
    if (raw & 0x4) {
        fprintf(stderr, "Thermocouple open-circuit detected\n");
        return -1;
    }

    return (raw >> 3) * 0.25;
}

void pid_init(PIDController *pid, double kp, double ki, double kd) {
    pid->kp = kp;
    pid->ki = ki;
    pid->kd = kd;
    pid->integral = 0;
    pid->previous_error = 0;
}

double pid_compute(PIDController *pid, double setpoint, double measured_value, double dt) {
    double error = setpoint - measured_value;
    pid->integral += error * dt;
    double derivative = (error - pid->previous_error) / dt;
    double output = pid->kp * error + pid->ki * pid->integral + pid->kd * derivative;
    pid->previous_error = error;
    return output;
}

int main() {
    int spi_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    FILE *profile_fp, *log_fp;
    ProfileEntry profile[100];
    int profile_count = 0;
    PIDController pid;
    time_t start_time, current_time;
    double current_temp, pid_output;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_gpio() < 0) {
        fprintf(stderr, "Failed to setup GPIO\n");
        return 1;
    }

    spi_fd = setup_spi();
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to setup SPI\n");
        return 1;
    }

    profile_fp = fopen(PROFILE_FILE, "r");
    if (!profile_fp) {
        perror("Failed to open profile file");
        close(spi_fd);
        return 1;
    }

    while (fscanf(profile_fp, "%d,%lf", &profile[profile_count].time_seconds, &profile[profile_count].target_temp_celsius) == 2) {
        profile_count++;
    }
    fclose(profile_fp);

    log_fp = fopen(LOG_FILE, "w");
    if (!log_fp) {
        perror("Failed to open log file");
        close(spi_fd);
        return 1;
    }

    fprintf(log_fp, "Time,Target Temp,Actual Temp,PID Output\n");

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_fp);
        close(spi_fd);
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        fclose(log_fp);
        close(spi_fd);
        return 1;
    }

    pid_init(&pid, PID_KP, PID_KI, PID_KD);
    start_time = time(NULL);

    while (keep_running) {
        current_time = time(NULL);
        int elapsed_time = (int)(current_time - start_time);
        int profile_index = 0;

        while (profile_index < profile_count && elapsed_time >= profile[profile_index].time_seconds) {
            profile_index++;
        }

        if (profile_index < profile_count) {
            current_temp = read_temperature(spi_fd);
            if (current_temp >= 0) {
                double dt = 1.0;
                pid_output = pid_compute(&pid, profile[profile_index].target_temp_celsius, current_temp, dt);
                pid_output = pid_output < 0.0 ? 0.0 : (pid_output > 1.0 ? 1.0 : pid_output);

                int relay_state = (int)(pid_output * 100) % 2;
                gpiod_line_set_value(line, relay_state);

                fprintf(log_fp, "%d,%lf,%lf,%lf\n", elapsed_time, profile[profile_index].target_temp_celsius, current_temp, pid_output);
                fflush(log_fp);
            }
        }

        sleep(1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_fp);
    close(spi_fd);
    return 0;
}

