#include <fcntl.h>

#define I2C_BUS "/dev/i2c-1"
#define AHT20_ADDR 0x38
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define RELAY_GPIO 17
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define MEASUREMENT_DELAY_MS 80
#define POLL_INTERVAL_SEC 5

static int i2c_fd;
static struct gpiod_line *relay_line;

void cleanup(int signum) {
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

int i2c_write(const uint8_t *data, size_t len) {
    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        if (write(i2c_fd, data, len) == len) {
            return 0;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int i2c_read(uint8_t *data, size_t len) {
    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        if (read(i2c_fd, data, len) == len) {
            return 0;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int aht20_init() {
    uint8_t init_cmd[] = {0xBE, 0x08, 0x00};
    return i2c_write(init_cmd, sizeof(init_cmd));
}

int aht20_measure() {
    uint8_t trigger_cmd[] = {0xAC, 0x33, 0x00};
    uint8_t data[6];

    if (i2c_write(trigger_cmd, sizeof(trigger_cmd)) != 0) {
        return -1;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000);

    if (i2c_read(data, sizeof(data)) != 0) {
        return -1;
    }

    if ((data[0] & 0x80) != 0) {
        return -1; // Sensor not calibrated or busy
    }

    uint32_t raw_humidity = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
    float humidity = (float)raw_humidity / 1048576.0 * 100.0;

    return humidity;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (aht20_init() != 0) {
        fprintf(stderr, "Failed to initialize AHT20 sensor\n");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "dehumidifier-relay", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        float humidity = aht20_measure();
        time_t now = time(NULL);
        char timestamp[26];
        ctime_r(&now, timestamp);
        timestamp[24] = '\0'; // Remove newline

        if (humidity < 0) {
            fprintf(stderr, "[%s] Error reading humidity\n", timestamp);
        } else {
            printf("[%s] Humidity: %.2f%%\n", timestamp, humidity);
            if (humidity > HUMIDITY_THRESHOLD_HIGH) {
                gpiod_line_set_value(relay_line, 1);
            } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
                gpiod_line_set_value(relay_line, 0);
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    return 0;
}

