#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <syslog.h>
#include <errno.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x40
#define SENSOR_READ_RETRIES 3
#define HTTP_SERVER "api.example.com"
#define HTTP_PORT 80
#define POST_PATH "/humidity"
#define POST_INTERVAL 60

static int i2c_fd;
static int sock_fd;

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (sock_fd >= 0) {
        close(sock_fd);
    }
    syslog(LOG_INFO, "Cleanup complete.");
}

void signal_handler(int signo) {
    syslog(LOG_INFO, "Received signal %d, shutting down.", signo);
    cleanup();
    exit(EXIT_SUCCESS);
}

int i2c_init() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int read_humidity() {
    uint8_t buf[3];
    int retries = 0;

    while (retries < SENSOR_READ_RETRIES) {
        buf[0] = 0xE5; // Humidity measurement command
        if (write(i2c_fd, buf, 1) != 1) {
            syslog(LOG_ERR, "Failed to write to I2C device: %s", strerror(errno));
            retries++;
            continue;
        }

        usleep(50000); // Wait for conversion

        if (read(i2c_fd, buf, 3) != 3) {
            syslog(LOG_ERR, "Failed to read from I2C device: %s", strerror(errno));
            retries++;
            continue;
        }

        // Check CRC (simplified, actual CRC check should be implemented)
        if (buf[2] != ((buf[0] ^ buf[1]) & 0xFF)) {
            syslog(LOG_WARNING, "CRC mismatch, retrying...");
            retries++;
            continue;
        }

        // Convert to percentage
        uint16_t raw = (buf[0] << 8) | buf[1];
        return (int)((-6.0 + 125.0 * (float)raw / 65536.0));
    }

    syslog(LOG_ERR, "Failed to read humidity after %d retries", SENSOR_READ_RETRIES);
    return -1;
}

int http_post(int humidity) {
    char post_data[100];
    snprintf(post_data, sizeof(post_data),
             "POST %s HTTP/1.1\r\n"
             "Host: %s\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: %zu\r\n"
             "\r\n"
             "{\"humidity\": %d}",
             POST_PATH, HTTP_SERVER, strlen(post_data) - 2, humidity);

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(HTTP_PORT);
    inet_pton(AF_INET, HTTP_SERVER, &server_addr.sin_addr);

    sock_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (sock_fd < 0) {
        syslog(LOG_ERR, "Failed to create socket: %s", strerror(errno));
        return -1;
    }

    if (connect(sock_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Failed to connect to server: %s", strerror(errno));
        close(sock_fd);
        return -1;
    }

    if (send(sock_fd, post_data, strlen(post_data), 0) < 0) {
        syslog(LOG_ERR, "Failed to send data: %s", strerror(errno));
        close(sock_fd);
        return -1;
    }

    char response[1024];
    ssize_t bytes_received = recv(sock_fd, response, sizeof(response) - 1, 0);
    if (bytes_received < 0) {
        syslog(LOG_ERR, "Failed to receive response: %s", strerror(errno));
    } else {
        response[bytes_received] = '\0';
        syslog(LOG_INFO, "HTTP Response: %s", response);
    }

    close(sock_fd);
    return 0;
}

int main() {
    openlog("htu21d_post", LOG_PID | LOG_CONS, LOG_USER);

    if (i2c_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        int humidity = read_humidity();
        if (humidity >= 0) {
            if (http_post(humidity) < 0) {
                syslog(LOG_ERR, "Failed to POST humidity data");
            }
        }

        sleep(POST_INTERVAL);
    }

    cleanup();
    closelog();
    return EXIT_SUCCESS;
}

