        fprintf(stderr, "Error reading TMP117\n");
        return 0;
    }
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    return raw_temp * 0.0078125;
}

int read_aht20(int i2c_fd, float *humidity, float *temperature) {
    uint8_t buf[7];
    if (i2c_write(i2c_fd, AHT20_MEASURE_CMD, 3) < 0) {
        fprintf(stderr, "Error sending measure command to AHT20\n");
        return -1;
    }

    do {
        if (i2c_read(i2c_fd, buf, 7) < 0) {
            fprintf(stderr, "Error reading AHT20\n");
            return -1;
        }
    } while (buf[0] & 0x80);

    uint32_t raw_humidity = ((buf[1] << 12) | (buf[2] << 4) | (buf[3] >> 4)) & 0xFFFFF;
    uint32_t raw_temp = ((buf[3] & 0x0F) << 16) | (buf[4] << 8) | buf[5];

    *humidity = (float)raw_humidity / 0x100000 * 100;
    *temperature = ((float)raw_temp / 0x100000) * 200 - 50;

    return 0;
}

