    struct tm *tm_info;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address for TMP117
    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, TMP117_ADDR) < 0) {
        perror("Failed to set TMP117 I2C address");
        close(i2c_fd);
        return 1;
    }

    // Check TMP117 presence
    uint8_t tmp117_test;
    if (i2c_read(i2c_fd, &tmp117_test, 1) < 0) {
        fprintf(stderr, "Warning: TMP117 not detected\n");
    }

    // Open I2C bus for AHT20
    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, AHT20_ADDR) < 0) {
        perror("Failed to set AHT20 I2C address");
        close(i2c_fd);
        return 1;
    }

    // Initialize AHT20
    if (i2c_write(i2c_fd, AHT20_INIT_CMD, 3) < 0) {
