        close(i2c_fd);
        return 1;
    }

    // Check AHT20 presence
    uint8_t aht20_test[3];
    if (i2c_read(i2c_fd, aht20_test, 3) < 0) {
        fprintf(stderr, "Warning: AHT20 not detected\n");
    }

    // Open GPIO chip
    chip = gpiod_chip_open(PIR_GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get PIR GPIO line
    pir_line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!pir_line) {
        fprintf(stderr, "Failed to get PIR GPIO line\n");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Request PIR GPIO line as input
    if (gpiod_line_request_input(pir_line, "PIR Sensor") < 0) {
        fprintf(stderr, "Failed to request PIR GPIO line\n");
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    time(&now);
    last_midnight = now - (now % 86400);

    while (keep_running) {
        time(&now);
        if (now - last_midnight >= 86400) {
            if (log_file) {
                fclose(log_file);
            }

            time_t new_time;
            time(&new_time);
            tm_info = localtime(&new_time);
            strftime(filename, sizeof(filename), "%Y%m%d", tm_info);
            strcat(filename, LOG_FILE_SUFFIX);

            log_file = fopen(filename, "w");
            if (!log_file) {
                perror("Failed to open log file");
                continue;
            }

            fprintf(log_file, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
            last_midnight = new_time;
        }

        float temperature = read_tmp117(i2c_fd);
