            struct tm *local_time = localtime(&current_time);

            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%d\n",
                    local_time->tm_year + 1900, local_time->tm_mon + 1, local_time->tm_mday,
