#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define CHIP_NAME "gpiochip0"
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24
#define POLL_INTERVAL_SECONDS 2
#define MOTOR_RUN_TIME_SECONDS 5

static struct gpiod_chip *chip;
static struct gpiod_line *rain_sensor_line;
static struct gpiod_line *motor_enable_line;
static struct gpiod_line *motor_in1_line;
static struct gpiod_line *motor_in2_line;

void log_event(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    printf("[%s] %s\n", time_str, message);
}

void cleanup() {
    if (motor_in2_line) gpiod_line_release(motor_in2_line);
    if (motor_in1_line) gpiod_line_release(motor_in1_line);
    if (motor_enable_line) gpiod_line_release(motor_enable_line);
    if (rain_sensor_line) gpiod_line_release(rain_sensor_line);
    if (chip) gpiod_chip_close(chip);
}

void signal_handler(int signum) {
    log_event("Received signal, cleaning up and exiting.");
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }
    log_event("GPIO chip opened successfully.");

    rain_sensor_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    if (!rain_sensor_line) {
        fprintf(stderr, "Failed to get line for rain sensor on pin %d: %s\n", RAIN_SENSOR_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(rain_sensor_line, "rain_sensor") < 0) {
        fprintf(stderr, "Failed to request input on pin %d: %s\n", RAIN_SENSOR_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    log_event("Rain sensor line configured successfully.");

    motor_enable_line = gpiod_chip_get_line(chip, MOTOR_ENABLE_PIN);
    if (!motor_enable_line) {
        fprintf(stderr, "Failed to get line for motor enable on pin %d: %s\n", MOTOR_ENABLE_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(motor_enable_line, "motor_enable", 0) < 0) {
        fprintf(stderr, "Failed to request output on pin %d: %s\n", MOTOR_ENABLE_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    log_event("Motor enable line configured successfully.");

    motor_in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    if (!motor_in1_line) {
        fprintf(stderr, "Failed to get line for motor IN1 on pin %d: %s\n", MOTOR_IN1_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(motor_in1_line, "motor_in1", 0) < 0) {
        fprintf(stderr, "Failed to request output on pin %d: %s\n", MOTOR_IN1_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    log_event("Motor IN1 line configured successfully.");

    motor_in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);
    if (!motor_in2_line) {
        fprintf(stderr, "Failed to get line for motor IN2 on pin %d: %s\n", MOTOR_IN2_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(motor_in2_line, "motor_in2", 0) < 0) {
        fprintf(stderr, "Failed to request output on pin %d: %s\n", MOTOR_IN2_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    log_event("Motor IN2 line configured successfully.");

    while (1) {
        int rain_detected = gpiod_line_get_value(rain_sensor_line);
        if (rain_detected == 0) {
            log_event("Rain detected! Closing window.");
            gpiod_line_set_value(motor_enable_line, 1);
            gpiod_line_set_value(motor_in1_line, 1);
            gpiod_line_set_value(motor_in2_line, 0);
            sleep(MOTOR_RUN_TIME_SECONDS);
            gpiod_line_set_value(motor_enable_line, 0);
            log_event("Window closed. Motor stopped.");
        }
        sleep(POLL_INTERVAL_SECONDS);
    }

    return EXIT_SUCCESS;
}

