#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>

#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27
#define PWM_RANGE 255
#define SAMPLE_INTERVAL_MS 500

static volatile int keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

double get_cpu_load() {
    static unsigned long long prev_total = 0, prev_idle = 0;
    unsigned long long total = 0, idle = 0;
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("Failed to open /proc/stat");
        return -1;
    }
    char cpu[16];
    if (fscanf(fp, "%15s %llu %*u %*u %*u %*u %*u %*u %*u %*u %llu", cpu, &total, &idle) != 3) {
        fclose(fp);
        fprintf(stderr, "Failed to read CPU stats\n");
        return -1;
    }
    fclose(fp);

    unsigned long long total_diff = total - prev_total;
    unsigned long long idle_diff = idle - prev_idle;
    prev_total = total;
    prev_idle = idle;

    if (total_diff == 0) return 0.0;
    return (1.0 - (double)idle_diff / total_diff) * 100.0;
}

void set_rgb_color(double load) {
    unsigned char r, g, b;
    if (load < 50.0) {
        g = (unsigned char)(PWM_RANGE * (1.0 - load / 50.0));
        r = b = 0;
    } else {
        r = (unsigned char)(PWM_RANGE * (load - 50.0) / 50.0);
        g = PWM_RANGE;
        b = 0;
    }
    gpioPWM(RED_PIN, r);
    gpioPWM(GREEN_PIN, g);
    gpioPWM(BLUE_PIN, b);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        double load = get_cpu_load();
        if (load >= 0) {
            set_rgb_color(load);
        }
        time_sleep(0.5);
    }

    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();

    return 0;
}

