#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_CALIB_REG 0x88
#define BMP280_CALIB_SIZE 24
#define BMP280_CONTROL_REG 0xF4
#define BMP280_FORCED_MODE 0x27
#define BMP280_DATA_REG 0xF7
#define BMP280_DATA_SIZE 6

#define UDP_SERVER_IP "192.168.1.100"
#define UDP_SERVER_PORT 5000
#define SEND_INTERVAL 5

static int i2cHandle;
static int udpSocket;
static volatile sig_atomic_t keepRunning = 1;

void signalHandler(int signum) {
    keepRunning = 0;
}

int initI2C() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }
    i2cHandle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "I2C device open failed\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

int initUDP() {
    struct sockaddr_in serverAddr;
    udpSocket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udpSocket < 0) {
        fprintf(stderr, "UDP socket creation failed\n");
        return -1;
    }
    memset(&serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &serverAddr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address\n");
        close(udpSocket);
        return -1;
    }
    return 0;
}

int readCalibrationData(int16_t calibData[12]) {
    char data[BMP280_CALIB_SIZE];
    if (i2cReadI2CBlock(i2cHandle, BMP280_CALIB_REG, data, BMP280_CALIB_SIZE) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        return -1;
    }
    for (int i = 0; i < 12; i++) {
        calibData[i] = (data[2 * i + 1] << 8) | data[2 * i];
    }
    return 0;
}

int readSensorData(int32_t *temp, int32_t *press) {
    char data[BMP280_DATA_SIZE];
    if (i2cWriteByte(i2cHandle, BMP280_CONTROL_REG) < 0 ||
        i2cWriteByte(i2cHandle, BMP280_FORCED_MODE) < 0) {
        fprintf(stderr, "Failed to set sensor to forced mode\n");
        return -1;
    }
    usleep(100000); // Wait for measurement to complete

    if (i2cReadI2CBlock(i2cHandle, BMP280_DATA_REG, data, BMP280_DATA_SIZE) < 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }
    *press = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    *temp = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    return 0;
}

int sendUDPData(const char *jsonData) {
    struct sockaddr_in serverAddr;
    socklen_t addrLen = sizeof(serverAddr);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &serverAddr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address\n");
        return -1;
    }
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(UDP_SERVER_PORT);

    ssize_t bytesSent = sendto(udpSocket, jsonData, strlen(jsonData), 0,
                               (struct sockaddr *)&serverAddr, addrLen);
    if (bytesSent < 0) {
        fprintf(stderr, "UDP send failed\n");
        return -1;
    }
    return 0;
}

void cleanup() {
    if (i2cHandle >= 0) {
        i2cClose(i2cHandle);
    }
    if (udpSocket >= 0) {
        close(udpSocket);
    }
    gpioTerminate();
}

int main() {
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    if (initI2C() < 0 || initUDP() < 0) {
        return EXIT_FAILURE;
    }

    int16_t calibData[12];
    if (readCalibrationData(calibData) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (keepRunning) {
        int32_t tempRaw, pressRaw;
        if (readSensorData(&tempRaw, &pressRaw) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        // Compensation formulas (simplified for brevity)
        double temp = (tempRaw / 100.0) - (calibData[5] / 512.0);
        double press = (pressRaw / 25600.0) - (calibData[8] / 32768.0);

        char jsonData[100];
        snprintf(jsonData, sizeof(jsonData),
                 "{\"temperature\": %.2f, \"pressure\": %.2f}", temp, press);

        if (sendUDPData(jsonData) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        sleep(SEND_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

