#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define FAN_PIN 18
#define PWM_FREQ 1000
#define MAX31855_CS_PIN 8
#define BUFFER_SIZE 20

typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int log_index = 0;

void log_data(float temperature, int duty_cycle) {
    time_t now = time(NULL);
    log_buffer[log_index] = (LogEntry){now, temperature, duty_cycle};
    log_index = (log_index + 1) % BUFFER_SIZE;
}

void print_log_buffer() {
    printf("Timestamp\tTemperature (C)\tDuty Cycle\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (log_index + i) % BUFFER_SIZE;
        printf("%ld\t%.2f\t%d\n", log_buffer[idx].timestamp, log_buffer[idx].temperature, log_buffer[idx].duty_cycle);
    }
}

int calculate_duty_cycle(float temperature) {
    if (temperature < 25.0f) return 0;
    if (temperature < 40.0f) return (int)((temperature - 25.0f) / 25.0f * 50.0f);
    if (temperature < 60.0f) return 50 + (int)((temperature - 40.0f) / 20.0f * 150.0f);
    return 255;
}

void handle_sigint(int signum) {
    gpioSetPWM(FAN_PIN, 0, 0);
    gpioTerminate();
    print_log_buffer();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MAX31855_CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for MAX31855 CS pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for FAN_PIN\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioHardwarePWM(FAN_PIN, PWM_FREQ, 0) < 0) {
        fprintf(stderr, "Failed to set hardware PWM for FAN_PIN\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    uint8_t tx[4] = {0};
    uint8_t rx[4] = {0};

    while (1) {
        gpioWrite(MAX31855_CS_PIN, 0);
        int count = spiXfer(spi_handle, tx, rx, 4);
        gpioWrite(MAX31855_CS_PIN, 1);

        if (count < 0) {
            fprintf(stderr, "SPI transfer error\n");
            continue;
        }

        int16_t raw_temp = (rx[0] << 8) | rx[1];
        raw_temp >>= 2;  // 14-bit resolution
        float temperature = raw_temp * 0.25f;

        uint16_t fault = (rx[2] << 8) | rx[3];
        if (fault & 0x1000) {  // Fault bit set
            fprintf(stderr, "MAX31855 fault detected: OC=%d, SCG=%d, SCV=%d\n",
                    (fault & 0x0001) ? 1 : 0,
                    (fault & 0x0002) ? 1 : 0,
                    (fault & 0x0004) ? 1 : 0);
            continue;
        }

        int duty_cycle = calculate_duty_cycle(temperature);
        gpioPWM(FAN_PIN, PWM_FREQ, duty_cycle);

        log_data(temperature, duty_cycle);

        time_sleep(1);
    }

    return EXIT_SUCCESS;
}

