#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/signalfd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN 8
#define LOG_FILE "rtd_log.csv"
#define SPI_SPEED 1000000
#define READ_INTERVAL 5

// MAX31865 Register Addresses
#define RTD_MS_REG 0x00
#define CONFIG_REG 0x01
#define RTD_LSB_REG 0x02
#define FAULT_STATUS_REG 0x07

// MAX31865 Configuration
#define CONFIG_3WIRE 0x20
#define CONFIG_BIAS_ON 0x10
#define CONFIG_MODE_AUTO 0x00

// Fault Status Register Masks
#define FAULT_HIGH_THRESHOLD 0x80
#define FAULT_LOW_THRESHOLD 0x40
#define FAULT_REFIN_LOW 0x20
#define FAULT_REFIN_HIGH 0x10
#define FAULT_RTD_IN_HIGH 0x08
#define FAULT_RTD_IN_LOW 0x04
#define FAULT_OVERUNDER_VOLTAGE 0x02

// Function prototypes
static int spi_open(void);
static int spi_transfer(int fd, unsigned char *tx, unsigned char *rx, int len);
static void close_spi(int fd);
static int init_max31865(int spi_fd);
static float read_temperature(int spi_fd);
static void log_temperature(float temp);
static void handle_signal(int signum);
static void cleanup(int spi_fd, FILE *log_file);

int main() {
    int spi_fd = spi_open();
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return EXIT_FAILURE;
    }

    if (init_max31865(spi_fd) < 0) {
        fprintf(stderr, "Failed to initialize MAX31865\n");
        close_spi(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close_spi(spi_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handling\n");
        cleanup(spi_fd, log_file);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        float temperature = read_temperature(spi_fd);
        log_temperature(temperature);
        sleep(READ_INTERVAL);
    }

    cleanup(spi_fd, log_file);
    return EXIT_SUCCESS;
}

static int spi_open(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

static int spi_transfer(int fd, unsigned char *tx, unsigned char *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
    };

    return ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
}

static void close_spi(int fd) {
    close(fd);
}

static int init_max31865(int spi_fd) {
    unsigned char tx[2], rx[2];

    // Read current configuration
    tx[0] = CONFIG_REG;
    tx[1] = 0;
    if (spi_transfer(spi_fd, tx, rx, 2) < 0) {
        fprintf(stderr, "Failed to read configuration\n");
        return -1;
    }

    // Set 3-wire mode, enable bias, and set to auto conversion
    tx[0] = CONFIG_REG;
    tx[1] = CONFIG_3WIRE | CONFIG_BIAS_ON | CONFIG_MODE_AUTO;
    if (spi_transfer(spi_fd, tx, rx, 2) < 0) {
        fprintf(stderr, "Failed to write configuration\n");
        return -1;
    }

    return 0;
}

static float read_temperature(int spi_fd) {
    unsigned char tx[3], rx[3];
    float resistance, temp;

    // Read RTD MSB and LSB registers
    tx[0] = RTD_MS_REG;
    tx[1] = 0;
    tx[2] = 0;
    if (spi_transfer(spi_fd, tx, rx, 3) < 0) {
        fprintf(stderr, "Failed to read RTD registers\n");
        return -273.15; // Return a sentinel value for error
    }

    // Combine MSB and LSB to get resistance
    resistance = ((rx[0] << 8) | rx[1]) * 0.00390625; // LSB = 0.00390625 ohms

    // Calculate temperature using Callendar-Van Dusen equation
    // This is a simplified version and may need adjustment based on your specific RTD
    temp = -242.02;
    temp += 2.2228 * resistance;
    temp += (2.5859e-3) * resistance * resistance;

    return temp;
}

static void log_temperature(float temp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file for writing\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.3f\n", timestamp, temp);
    fclose(log_file);
}

static void handle_signal(int signum) {
    fprintf(stderr, "Received signal %d, shutting down...\n", signum);
    exit(EXIT_SUCCESS);
}

static void cleanup(int spi_fd, FILE *log_file) {
    if (log_file) {
        fclose(log_file);
    }
    close_spi(spi_fd);
}
