#define BME280_REG_TEMPERATURE_MSB 0xFA

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "bme280_log.csv"
#define LOG_INTERVAL 5

int i2c_fd;
FILE *log_fp;

