int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write error");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C read register error");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("I2C read data error");
        return -1;
    }
    return 0;
}

int bme280_init() {
    uint8_t chip_id;
    if (i2c_read(i2c_fd, BME280_REG_CHIPID, &chip_id, 1) != 0) {
        return -1;
    }
    if (chip_id != BME280_CHIP_ID) {
        fprintf(stderr, "BME280 chip ID mismatch: 0x%02X\n", chip_id);
        return -1;
    }

    // Set humidity, temperature, and pressure oversampling
    if (i2c_write(i2c_fd, BME280_REG_CONTROL_HUM, 0x03) != 0 ||
        i2c_write(i2c_fd, BME280_REG_CONTROL_MEAS, 0x73) != 0) {
        return -1;
    }
    return 0;
}

int bme280_read_sensor(int32_t *temp, int32_t *hum, int32_t *press) {
    uint8_t buf[8];
    if (i2c_read(i2c_fd, BME280_REG_PRESSURE_MSB, buf, 8) != 0) {
        return -1;
    }

    *press = (buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4);
    *temp = (buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4);
    *hum = (buf[6] << 8) | buf[7];

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("I2C bus open error");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("I2C slave address error");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (bme280_init() != 0) {
        fprintf(stderr, "BME280 initialization failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Log file open error");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (fseek(log_fp, 0, SEEK_END) == 0) {
        if (ftell(log_fp) == 0) {
            fprintf(log_fp, "timestamp,temperature_C,humidity_percent,pressure_hPa\n");
        }
    }

    while (1) {
        int32_t temp, hum, press;
        if (bme280_read_sensor(&temp, &hum, &press) != 0) {
            fprintf(stderr, "Failed to read BME280 sensor\n");
            sleep(LOG_INTERVAL);
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_fp, "%s,%.2f,%.2f,%.2f\n", timestamp,
                temp / 51200.0, hum / 1024.0, press / 25600.0);
        fflush(log_fp);

        sleep(LOG_INTERVAL);
    }

    return EXIT_SUCCESS;
}

