#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS 1
#define BMP180_ADDR 0x77
#define CALIB_START_REG 0xAA
#define CONTROL_REG 0xF4
#define DATA_REG 0xF6
#define ALERT_PIN 24
#define BUFFER_SIZE 120 // 60 seconds at 2 readings/second
#define ALERT_THRESHOLD 500 // 5 hPa

typedef struct {
    int16_t ac1, ac2, ac3, ac4, ac5, ac6, b1, b2, mb, mc, md;
    uint16_t ac11, ac12, ac13, ac14, ac15, ac16, ac17, ac18, ac19, ac20;
} CalibrationData;

typedef struct {
    double pressure;
    time_t timestamp;
} SensorReading;

CalibrationData calib;
SensorReading buffer[BUFFER_SIZE];
int bufferIndex = 0;
int i2cHandle;

void cleanup(int signum) {
    gpioSetMode(ALERT_PIN, PI_INPUT);
    gpioTerminate();
    i2cClose(i2cHandle);
    exit(0);
}

int readCalibrationData() {
    for (int i = 0; i < 22; i++) {
        int16_t value;
        int rc = i2cReadWordData(i2cHandle, CALIB_START_REG + i * 2);
        if (rc < 0) {
            fprintf(stderr, "Error reading calibration data: %s\n", gpioStrError(rc));
            return -1;
        }
        value = (int16_t)rc;
        switch (i) {
            case 0: calib.ac1 = value; break;
            case 1: calib.ac2 = value; break;
            case 2: calib.ac3 = value; break;
            case 3: calib.ac4 = value; break;
            case 4: calib.ac5 = value; break;
            case 5: calib.ac6 = value; break;
            case 6: calib.b1 = value; break;
            case 7: calib.b2 = value; break;
            case 8: calib.mb = value; break;
            case 9: calib.mc = value; break;
            case 10: calib.md = value; break;
            default: break;
        }
    }
    return 0;
}

double calculatePressure(int32_t ut) {
    int32_t x1, x2, x3, b3, b6, p;
    uint32_t b4, b7;

    x1 = ((int32_t)ut - calib.ac6) * calib.ac5 >> 15;
    x2 = (calib.mc << 11) / (x1 + calib.md);
    b5 = x1 + x2;
    b6 = b5 - 4000;
    x1 = (calib.b2 * (b6 * b6) >> 12) >> 11;
    x2 = (calib.ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((int32_t)calib.ac1) * 4 + x3) << OSS) + 2) / 4;
    x1 = (calib.ac3 * b6) >> 13;
    x2 = (calib.b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = (calib.ac4 * (uint32_t)(x3 + 32768)) >> 15;
    b7 = ((uint32_t)(ut - 76800)) * (((uint32_t)b6 * 2) >> 12);
    p = (((b7 << 11) - ((int32_t)b4 << 11)) + 32768) >> 12;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    return p + ((x1 + x2 + 3791) >> 4);
}

void sampleSensor() {
    int32_t ut;
    int rc;

    rc = i2cWriteByteData(i2cHandle, CONTROL_REG, 0x34);
    if (rc < 0) {
        fprintf(stderr, "Error starting pressure conversion: %s\n", gpioStrError(rc));
        return;
    }
    gpioSleep(PI_TIME_RELATIVE, 0, 5000000);

    rc = i2cReadWordData(i2cHandle, DATA_REG);
    if (rc < 0) {
        fprintf(stderr, "Error reading pressure data: %s\n", gpioStrError(rc));
        return;
    }
    ut = (int32_t)rc;

    double pressure = calculatePressure(ut);
    time_t now = time(NULL);

    buffer[bufferIndex].pressure = pressure;
    buffer[bufferIndex].timestamp = now;
    bufferIndex = (bufferIndex + 1) % BUFFER_SIZE;

    // Calculate rolling average
    double sum = 0;
    int count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (difftime(now, buffer[i].timestamp) <= 60) {
            sum += buffer[i].pressure;
            count++;
        }
    }

    if (count > 0) {
        double avg = sum / count;
        if (fabs(pressure - avg) > ALERT_THRESHOLD) {
            gpioWrite(ALERT_PIN, 1);
            fprintf(stderr, "ALERT: Pressure deviation %.2f hPa from average %.2f hPa at %s",
                    pressure - avg, avg, ctime(&now));
        } else {
            gpioWrite(ALERT_PIN, 0);
        }
    }

    printf("Pressure: %.2f hPa at %s", pressure, ctime(&now));
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, cleanup);

    i2cHandle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", gpioStrError(i2cHandle));
        gpioTerminate();
        return 1;
    }

    if (readCalibrationData() < 0) {
        cleanup(0);
        return 1;
    }

    gpioSetMode(ALERT_PIN, PI_OUTPUT);
    gpioWrite(ALERT_PIN, 0);

    if (gpioSetTimerFuncEx(50000, sampleSensor, NULL) < 0) {
        fprintf(stderr, "Error setting timer function: %s\n", gpioStrError(errno));
        cleanup(0);
        return 1;
    }

    while (1) {
        gpioSleep(PI_TIME_RELATIVE, 1, 0);
    }

    return 0;
}

