#include <time.h>
#include <errno.h>

#define FAN_PIN 18
#define PWM_FREQUENCY 25000
#define LOG_INTERVAL 5
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"

static FILE *log_fp;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

int read_cpu_temperature() {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Failed to open temperature file: %s\n", strerror(errno));
        return -1;
    }

    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Failed to read temperature\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp / 1000; // Convert millidegrees to degrees Celsius
}

int calculate_duty_cycle(int temp) {
    if (temp <= 40) return 0;
    if (temp >= 70) return 255;
    return (temp - 40) * 255 / 30;
}

void log_fan_status(int temp, int duty) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            return;
        }
    }

    if (fprintf(log_fp, "%s, Temperature: %d°C, Duty Cycle: %d%%\n", timestamp, temp, duty) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
    }
    fflush(log_fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int temp = read_cpu_temperature();
        if (temp < 0) {
            sleep(1);
            continue;
        }

        int duty = calculate_duty_cycle(temp);
        gpioPWM(FAN_PIN, duty);

        log_fan_status(temp, duty);
        sleep(LOG_INTERVAL);
    }

    gpioPWM(FAN_PIN, 0); // Stop the fan
    if (log_fp) fclose(log_fp);
    gpioTerminate();

    return EXIT_SUCCESS;
}

