#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pthread.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define LM75_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 60
#define LED_PIN 18
#define TEMP_THRESHOLD 28.0
#define I2C_RETRIES 3

typedef struct {
    float temperatures[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

static int i2c_fd;
static struct gpiod_line *led_line;
static CircularBuffer buffer = {.head = 0, .tail = 0, .count = 0};

void cleanup(int signum) {
    (void)signum;
    gpiod_line_release(led_line);
    gpiod_line_request_release(led_line);
    close(i2c_fd);
    pthread_mutex_destroy(&buffer.mutex);
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t data[2] = {reg, value};
    return write(fd, data, sizeof(data));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (i2c_write(fd, reg, 0) != 1) return -1;
    return read(fd, value, 1);
}

void *data_acquisition_thread(void *arg) {
    (void)arg;
    int retry_count;
    int16_t raw_temp;
    float temp;

    while (1) {
        retry_count = 0;
        while (retry_count < I2C_RETRIES) {
            if (i2c_read(i2c_fd, TEMP_REG, (uint8_t *)&raw_temp) == 1) {
                raw_temp = (raw_temp >> 5) * 256;
                temp = (float)raw_temp / 256.0;
                break;
            }
            retry_count++;
            usleep(100000);
        }

        if (retry_count == I2C_RETRIES) {
            fprintf(stderr, "Error reading temperature sensor\n");
            continue;
        }

        pthread_mutex_lock(&buffer.mutex);
        buffer.temperatures[buffer.head] = temp;
        buffer.head = (buffer.head + 1) % BUFFER_SIZE;
        if (buffer.count < BUFFER_SIZE) buffer.count++;
        else buffer.tail = (buffer.tail + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&buffer.mutex);

        if (temp > TEMP_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        sleep(1);
    }
    return NULL;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    pthread_t thread;
    pthread_mutex_init(&buffer.mutex, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (pthread_create(&thread, NULL, data_acquisition_thread, NULL) != 0) {
        perror("Failed to create thread");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    pthread_join(thread, NULL);

    return 0;
}

