#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define MAX_TEMP 80.0

static int spi_handle;
static volatile int keep_running = 1;

void cleanup(int sig) {
    keep_running = 0;
}

int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 1);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int write_register(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return spiWrite(spi_handle, buf, 2);
}

int read_register(uint8_t reg, uint8_t *value) {
    uint8_t buf[2] = {reg, 0};
    if (spiWrite(spi_handle, buf, 2) < 0) return -1;
    return spiRead(spi_handle, buf, 1);
}

int read_rtd_code(uint16_t *code) {
    uint8_t msb, lsb;
    if (read_register(0x01, &msb) < 0 || read_register(0x02, &lsb) < 0) return -1;
    *code = ((msb & 0x0F) << 8) | lsb;
    return 0;
}

int check_fault() {
    uint8_t msb;
    if (read_register(0x01, &msb) < 0) return -1;
    return msb & 0x10;
}

double rtd_to_temperature(uint16_t code) {
    double rtd_resistance = (double)code / 32768 * RTD_REF_RESISTOR;
    double temp = (rtd_resistance - RTD_NOMINAL_RESISTANCE) / RTD_COEFF_A;
    temp += (RTD_COEFF_B * temp * temp) / 2.0;
    return temp;
}

void pid_control(double setpoint, double kp, double ki, double kd) {
    static double integral = 0.0;
    static double prev_error = 0.0;
    double error = setpoint - rtd_to_temperature(0); // Placeholder for actual RTD reading
    integral += error * PID_INTERVAL_MS / 1000.0;
    double derivative = (error - prev_error) / (PID_INTERVAL_MS / 1000.0);
    double output = kp * error + ki * integral + kd * derivative;
    prev_error = error;

    if (output < 0) output = 0;
    if (output > PWM_RANGE) output = PWM_RANGE;

    gpioPWM(PWM_PIN, (uint16_t)output);
}

int load_config(double *target, double *kp, double *ki, double *kd) {
    struct json_object *parsed_json;
    struct json_object *j_target, *j_kp, *j_ki, *j_kd;

    FILE *config_file = fopen("config.json", "r");
    if (!config_file) {
        *target = 25.0;
        *kp = 1.0;
        *ki = 0.1;
        *kd = 0.01;
        return 0;
    }

    char *config_data = NULL;
    size_t config_size;
    fseek(config_file, 0, SEEK_END);
    config_size = ftell(config_file);
    fseek(config_file, 0, SEEK_SET);
    config_data = malloc(config_size + 1);
    fread(config_data, 1, config_size, config_file);
    fclose(config_file);
    config_data[config_size] = '\0';

    parsed_json = json_tokener_parse(config_data);
    free(config_data);

    if (!json_object_object_get_ex(parsed_json, "target", &j_target)) *target = 25.0;
    else *target = json_object_get_double(j_target);

    if (!json_object_object_get_ex(parsed_json, "kp", &j_kp)) *kp = 1.0;
    else *kp = json_object_get_double(j_kp);

    if (!json_object_object_get_ex(parsed_json, "ki", &j_ki)) *ki = 0.1;
    else *ki = json_object_get_double(j_ki);

    if (!json_object_object_get_ex(parsed_json, "kd", &j_kd)) *kd = 0.01;
    else *kd = json_object_get_double(j_kd);

    json_object_put(parsed_json);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (init_spi() < 0) {
        gpioTerminate();
        return 1;
    }

    if (write_register(0x80, 0xC1) < 0) {
        fprintf(stderr, "Failed to configure MAX31865\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    double target_temp, kp, ki, kd;
    if (load_config(&target_temp, &kp, &ki, &kd) < 0) {
        fprintf(stderr, "Failed to load configuration\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (keep_running) {
        uint16_t rtd_code;
        if (read_rtd_code(&rtd_code) < 0 || check_fault() || rtd_to_temperature(rtd_code) > MAX_TEMP) {
            fprintf(stderr, "Critical error: Temperature too high, SPI read failure, or MAX31865 fault\n");
            gpioPWM(PWM_PIN, 0);
            break;
        }

        pid_control(target_temp, kp, ki, kd);
        time_sleep(PID_INTERVAL_MS / 1000.0);
    }

    gpioPWM(PWM_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

