#define SAMPLE_INTERVAL 1
#define TEMP_THRESHOLD 3000 // 30.0°C in 0.1°C units
#define PRESSURE_THRESHOLD 95000 // 950 hPa in Pa

// BMP180 registers
#define BMP180_CAL_AC1 0xAA
#define BMP180_CAL_AC2 0xAC
#define BMP180_CAL_AC3 0xAE
#define BMP180_CAL_AC4 0xB0
#define BMP180_CAL_AC5 0xB2
#define BMP180_CAL_AC6 0xB4
#define BMP180_CAL_B1 0xB6
#define BMP180_CAL_B2 0xB8
#define BMP180_CAL_MB 0xBA
#define BMP180_CAL_MC 0xBC
#define BMP180_CAL_MD 0xBE
#define BMP180_CONTROL 0xF4
#define BMP180_TEMP_DATA 0xF6
#define BMP180_PRESSURE_DATA 0xF6

// Calibration data
static int16_t ac1, ac2, ac3, ac4, ac5, ac6;
static int16_t b1, b2;
static int16_t mb, mc, md;

int i2c_fd;
FILE *log_file;

void signal_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        syslog(LOG_INFO, "Received signal, cleaning up...");
        if (i2c_fd >= 0) {
            close(i2c_fd);
        }
        if (log_file) {
            fclose(log_file);
        }
        closelog();
        exit(EXIT_SUCCESS);
    }
}

int i2c_write(int reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    return write(i2c_fd, buf, 2);
}

int i2c_read(int reg, uint8_t *buf, int len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        return -1;
    }
    return read(i2c_fd, buf, len);
}

int read_calibration_data() {
    uint8_t buf[2];
    int retries = 3;

    while (retries--) {
        if (i2c_read(BMP180_CAL_AC1, buf, 2) == 2) {
            ac1 = (buf[0] << 8) | buf[1];
            if (i2c_read(BMP180_CAL_AC2, buf, 2) == 2) {
                ac2 = (buf[0] << 8) | buf[1];
                if (i2c_read(BMP180_CAL_AC3, buf, 2) == 2) {
                    ac3 = (buf[0] << 8) | buf[1];
                    if (i2c_read(BMP180_CAL_AC4, buf, 2) == 2) {
                        ac4 = (buf[0] << 8) | buf[1];
                        if (i2c_read(BMP180_CAL_AC5, buf, 2) == 2) {
                            ac5 = (buf[0] << 8) | buf[1];
                            if (i2c_read(BMP180_CAL_AC6, buf, 2) == 2) {
                                ac6 = (buf[0] << 8) | buf[1];
                                if (i2c_read(BMP180_CAL_B1, buf, 2) == 2) {
                                    b1 = (buf[0] << 8) | buf[1];
                                    if (i2c_read(BMP180_CAL_B2, buf, 2) == 2) {
                                        b2 = (buf[0] << 8) | buf[1];
                                        if (i2c_read(BMP180_CAL_MB, buf, 2) == 2) {
                                            mb = (buf[0] << 8) | buf[1];
                                            if (i2c_read(BMP180_CAL_MC, buf, 2) == 2) {
                                                mc = (buf[0] << 8) | buf[1];
                                                if (i2c_read(BMP180_CAL_MD, buf, 2) == 2) {
                                                    md = (buf[0] << 8) | buf[1];
                                                    return 0;
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        usleep(100000); // 100ms delay before retry
    }
    return -1;
}

int read_temperature(int32_t *temperature) {
    uint8_t buf[2];
    int retries = 3;

    while (retries--) {
        if (i2c_write(BMP180_CONTROL, 0x2E) == 1) {
            usleep(5000); // 5ms delay
            if (i2c_read(BMP180_TEMP_DATA, buf, 2) == 2) {
                int32_t UT = ((int32_t)buf[0] << 8) | buf[1];
                int32_t X1 = ((UT - (int32_t)ac6) * (int32_t)ac5) >> 15;
                int32_t X2 = ((int32_t)mc << 11) / (X1 + (int32_t)md);
                int32_t B5 = X1 + X2;
                *temperature = (B5 + 8) >> 4;
                return 0;
            }
        }
        usleep(100000); // 100ms delay before retry
    }
    return -1;
}

int read_pressure(int32_t *pressure) {
    uint8_t buf[3];
    int retries = 3;

    while (retries--) {
        if (i2c_write(BMP180_CONTROL, 0x34) == 1) {
            usleep(25000); // 25ms delay
            if (i2c_read(BMP180_PRESSURE_DATA, buf, 3) == 3) {
                int32_t UP = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | buf[2];
                UP >>= (8 - 3);

                int32_t X1 = ((int32_t)ac3 * 32768) >> 15;
                int32_t X2 = (X1 * (int32_t)b2) >> 11;
                int32_t X3 = ((int32_t)X2 + (int32_t)ac2) >> 11;
                int32_t B3 = (((int32_t)ac1 * 4 + X3) << 3) + ((int32_t)b1 * ((int32_t)X3 >> 2));
                int32_t X4 = (X2 * (int32_t)b2) >> 11;
                int32_t X5 = ((int32_t)X4 + (int32_t)b1) >> 11;
                int32_t X6 = (X5 * (int32_t)b1) >> 11;

                int32_t B4 = (((int32_t)ac4 * (int32_t)X6) >> 12) + ((int32_t)ac4 * (int32_t)X5);
                int32_t B7 = ((int32_t)UP - B3) * (50000 >> 3);

                if (B7 < 0x80000000) {
                    *pressure = (B7 * 2) / B4;
                } else {
                    *pressure = (B7 / B4) * 2;
