                X1 = (X6 >> 10) * (X6 >> 10);
                X1 = (X1 * 3038) >> 16;
                X2 = (-7357 * X6) >> 16;
                *pressure += (X1 + X2 + 3791) >> 4;

                return 0;
            }
        }
        usleep(100000); // 100ms delay before retry
    }
    return -1;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    openlog("bmp180_monitor", LOG_PID | LOG_CONS, LOG_USER);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, BMP180_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %s", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (read_calibration_data() != 0) {
        syslog(LOG_ERR, "Failed to read calibration data");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("breach_log.txt", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "BMP180 monitoring started");

    while (1) {
        int32_t temperature, pressure;
        time_t now;
        struct tm *tm_info;
        char timestamp[20];

        if (read_temperature(&temperature) != 0 || read_pressure(&pressure) != 0) {
            syslog(LOG_ERR, "Failed to read sensor data");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        now = time(NULL);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        if (temperature > TEMP_THRESHOLD || pressure < PRESSURE_THRESHOLD) {
            fprintf(log_file, "%s, Temperature: %.1f°C, Pressure: %.1f hPa\n",
                    timestamp, temperature / 10.0, pressure / 100.0);
            fflush(log_file);
            syslog(LOG_INFO, "Breach detected: Temp %.1f°C, Pressure %.1f hPa",
                   temperature / 10.0, pressure / 100.0);
        }

        sleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    close(i2c_fd);
    closelog();
    return EXIT_SUCCESS;
}

