#include <linux/i2c-dev.h>

#define BMP180_I2C_ADDR 0x77
#define LOG_FILE "pressure_log.txt"
#define LOG_INTERVAL_MS 2000
#define DEBOUNCE_TIME_MS 200
#define TOGGLE_GPIO 27

static int i2c_handle;
static int gpio_fd;
static FILE *log_file;
static volatile sig_atomic_t keep_running = 1;

// BMP180 calibration data
typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_calib_data;

bmp180_calib_data calib;

// Function prototypes
static void setup_signal_handlers(void);
static void cleanup_resources(void);
static int init_i2c(void);
static int init_gpio(void);
static int read_calibration_data(void);
static int32_t bmp180_compute_pressure(int32_t ut, int32_t up);
static int bmp180_read_raw_temp(void);
static int bmp180_read_raw_pressure(void);
static void log_pressure(void);
static void toggle_logging(int gpio, int level, uint32_t tick);

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup_resources();
        return EXIT_FAILURE;
    }

    setup_signal_handlers();

    if (read_calibration_data() < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        cleanup_resources();
        return EXIT_FAILURE;
    }

    gpioSetAlertFunc(TOGGLE_GPIO, toggle_logging);

    while (keep_running) {
        gpioSleep(PI_TIME_MILLISECONDS, LOG_INTERVAL_MS);
        if (keep_running) {
            log_pressure();
        }
    }

    cleanup_resources();
    return EXIT_SUCCESS;
}

static void setup_signal_handlers(void) {
    struct sigaction sa;
    sa.sa_handler = [](int signum) { keep_running = 0; };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

static void cleanup_resources(void) {
    gpioSetAlertFunc(TOGGLE_GPIO, NULL);
    fclose(log_file);
    close(i2c_handle);
    gpioTerminate();
}

static int init_i2c(void) {
    if ((i2c_handle = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_handle, I2C_SLAVE, BMP180_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_handle);
        return -1;
    }

    return 0;
}

static int init_gpio(void) {
    gpioSetMode(TOGGLE_GPIO, PI_INPUT);
    gpioSetPullUpDown(TOGGLE_GPIO, PI_PUD_UP);
    return 0;
}

static int read_calibration_data(void) {
    uint8_t data[22];
    if (read(i2c_handle, data, 22) != 22) {
        fprintf(stderr, "Failed to read calibration data\n");
        return -1;
    }

    calib.ac1 = (data[0] << 8) | data[1];
    calib.ac2 = (data[2] << 8) | data[3];
    calib.ac3 = (data[4] << 8) | data[5];
    calib.ac4 = (data[6] << 8) | data[7];
    calib.ac5 = (data[8] << 8) | data[9];
    calib.ac6 = (data[10] << 8) | data[11];
    calib.b1 = (data[12] << 8) | data[13];
    calib.b2 = (data[14] << 8) | data[15];
    calib.mb = (data[16] << 8) | data[17];
    calib.mc = (data[18] << 8) | data[19];
    calib.md = (data[20] << 8) | data[21];

    return 0;
}

static int32_t bmp180_compute_pressure(int32_t ut, int32_t up) {
    int32_t x1, x2, x3, b3, b6, p;
    uint32_t b4, b7;

    b6 = ut - calib.ac6;
