#include <errno.h>
#include <string.h>

#define TARGET_TEMP 25.0
#define MAX_DUTY_CYCLE 80.0
#define Kp 1.0
#define Ki 0.1
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define CS_PIN 8
#define RELAY_PIN 17

static volatile int keep_running = 1;
static FILE *log_file;
static int spi_handle;

void log_message(const char *message) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s, %s\n", timestamp, message);
    fflush(log_file);
}

void cleanup(int sig) {
    keep_running = 0;
    gpioSetMode(RELAY_PIN, PI_INPUT);
    gpioWrite(RELAY_PIN, PI_LOW);
    gpioSetPWMfrequency(RELAY_PIN, 0);
    gpioSetMode(CS_PIN, PI_INPUT);
    gpioWrite(CS_PIN, PI_LOW);
    if (spi_handle >= 0) {
        close(spi_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

double read_temperature() {
    char buf[4];
    int retry_count = 0;
    int ret;

    while (retry_count < 3) {
        ret = spiXfer(spi_handle, buf, buf, sizeof(buf));
        if (ret < 0) {
            log_message("SPI read error");
            retry_count++;
            gpioDelay(1000000); // 1 second delay
            continue;
        }

        if ((buf[1] & 0x02) != 0) {
            log_message("MAX31855 fault detected");
            return -100.0; // Indicate error
        }

        int32_t raw = (buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3];
        return (double)raw * 0.0625;
    }

    log_message("SPI read failed after retries");
    return -100.0; // Indicate error
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, PI_HIGH);

    spi_handle = spiOpen(CS_PIN, SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("heater_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    double integral = 0.0;
    double prev_temp = 0.0;
    double prev_error = 0.0;

    while (keep_running) {
        double temp = read_temperature();
        if (temp < -100.0) {
            gpioPWM(RELAY_PIN, 0);
            gpioDelay(1000000); // 1 second delay
            continue;
        }

        double error = TARGET_TEMP - temp;
        integral += error;
        integral = (integral > MAX_DUTY_CYCLE) ? MAX_DUTY_CYCLE : (integral < 0) ? 0 : integral;

        double derivative = error - prev_error;
        double output = Kp * error + Ki * integral;

        if (output > MAX_DUTY_CYCLE) {
            output = MAX_DUTY_CYCLE;
        } else if (output < 0) {
            output = 0;
        }

        int duty_cycle = (int)(output * 255.0 / 100.0);
        gpioPWM(RELAY_PIN, duty_cycle);

        char log_buf[128];
        snprintf(log_buf, sizeof(log_buf), "Temperature: %.2f°C, Duty Cycle: %d%%", temp, duty_cycle);
        log_message(log_buf);

        prev_error = error;
        prev_temp = temp;
        gpioDelay(1000000); // 1 second delay
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

