#define BLUE_PIN 17
#define GREEN_PIN 18
#define RED_PIN 27
#define UPDATE_INTERVAL_MS 500

volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

void set_rgb(int red, int green, int blue) {
    gpioPWM(RED_PIN, 255 - red);
    gpioPWM(GREEN_PIN, 255 - green);
    gpioPWM(BLUE_PIN, 255 - blue);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize gpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    gpioPWM(RED_PIN, 255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN, 255);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *temp_file = NULL;
    long temp;
    int red, green, blue;

    while (!terminate) {
        temp_file = fopen(TEMP_FILE, "r");
        if (temp_file == NULL) {
            fprintf(stderr, "Failed to open temperature file: %s\n", strerror(errno));
            sleep(UPDATE_INTERVAL_MS / 1000);
            continue;
        }

        if (fscanf(temp_file, "%ld", &temp) != 1) {
            fprintf(stderr, "Failed to read temperature\n");
            fclose(temp_file);
            sleep(UPDATE_INTERVAL_MS / 1000);
            continue;
        }

        fclose(temp_file);

        printf("Temperature: %ld m°C\n", temp);

        if (temp < 40000) {
            red = 0;
            green = 0;
            blue = 255;
        } else if (temp < 60000) {
            red = 0;
            green = 255;
            blue = 0;
        } else {
            red = 255;
            green = 0;
            blue = 0;
        }

        printf("RGB: (%d, %d, %d)\n", red, green, blue);
        set_rgb(red, green, blue);

        sleep(UPDATE_INTERVAL_MS / 1000);
    }

    set_rgb(255, 255, 255);
    gpioTerminate();
    return EXIT_SUCCESS;
}

