        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(BMP180_I2C_BUS, BMP180_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (bmp180_read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);
    gpioSetAlertFunc(BUTTON_GPIO, gpio_interrupt_callback);

    signal(SIGINT, signal_handler);

    while (1) {
        if (logging_enabled) {
            int32_t raw_temp = bmp180_read_raw_temp();
            int32_t raw_pressure = bmp180_read_raw_pressure();

            if (raw_temp == 0 || raw_pressure == 0) {
                fprintf(stderr, "Failed to read sensor data\n");
                continue;
            }

            int32_t temp = bmp180_compensate_temp(raw_temp);
            int32_t pressure = bmp180_compensate_pressure(raw_pressure);

            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                fprintf(stderr, "Failed to open log file\n");
                continue;
            }

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

