            printf("Logging disabled. Press button to enable.\n");
        }

        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_MS / 1000, (SAMPLE_INTERVAL_MS % 1000) * 1000);
    }

    return EXIT_SUCCESS;
}

static int bmp180_read_calibration_data(void) {
    int result = 0;

    result |= i2cReadWordData(i2c_handle, BMP180_CAL_AC1, &ac1);
    result |= i2cReadWordData(i2c_handle, BMP180_CAL_AC2, &ac2);
    result |= i2cReadWordData(i2c_handle, BMP180_CAL_AC3, &ac3);
    result |= i2cReadWordData(i2c_handle, BMP180_CAL_AC4, &ac4);
    result |= i2cReadWordData(i2c_handle, BMP180_CAL_AC5, &ac5);
    result |= i2cReadWordData(i2c_handle, BMP180_CAL_AC6, &ac6);
    result |= i2cReadWordData(i2c_handle, BMP180_CAL_B1, &b1);
    result |= i2cReadWordData(i2c_handle, BMP180_CAL_B2, &b2);
    result |= i2cReadWordData(i2c_handle, BMP180_CAL_MB, &mb);
    result |= i2cReadWordData(i2c_handle, BMP180_CAL_MC, &mc);
    result |= i2cReadWordData(i2c_handle, BMP180_CAL_MD, &md);

    return result;
}

static int bmp180_read_raw_temp(void) {
    unsigned char data[2];
    if (i2cWriteByte(i2c_handle, BMP180_READ_TEMP) != 0) return 0;
    gpioDelay(5000);  // 5ms delay for conversion
    if (i2cReadDevice(i2c_handle, data, 2) != 2) return 0;
    return (data[0] << 8) | data[1];
}

static int bmp180_read_raw_pressure(void) {
    unsigned char data[3];
    if (i2cWriteByte(i2c_handle, BMP180_READ_PRESSURE + (3 << 6)) != 0) return 0;
    gpioDelay(26000);  // 26ms delay for conversion
    if (i2cReadDevice(i2c_handle, data, 3) != 3) return 0;
    return (data[0] << 16) | (data[1] << 8) | data[2];
}

static int32_t bmp180_compensate_temp(int32_t ut) {
    int32_t x1 = ((ut - ac6) * ac5) >> 15;
    int32_t x2 = (mc << 11) / (x1 + md);
    return x1 + x2;
}

static int32_t bmp180_compensate_pressure(int32_t up) {
    int32_t x1 = (ac3 * 1024 - (up << 3)) * ac1 >> 11;
    int32_t x2 = (ac2 * (up << 11)) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = ((ac1 * 4 + x3) << 2) + 2;
    int32_t b6 = b3 >> 2;
    x1 = (ac1 * (x3 >> 2) * (x3 >> 2)) >> 11;
    x2 = (ac2 * x3) >> 11;
    int32_t x4 = (x1 + x2) >> 10;
    int32_t b4 = (ac4 * (x4 + 32768)) >> 13;
    int32_t b7 = (up - b6) * (b4 >> 3);
    int32_t p = (b7 << 1) + b3;

    x1 = (mc * (p >> 8) * (p >> 8)) >> 13;
    x2 = (mc * p) >> 6;
    return p + ((x1 + x2 + b2) >> 4);
}

static void gpio_interrupt_callback(int gpio, int level, uint32_t tick) {
    if (level == 0 && (tick - last_interrupt_time) > DEBOUNCE_TIME_US) {
        logging_enabled = !logging_enabled;
        last_interrupt_time = tick;
    }
}

static void signal_handler(int signo) {
    if (signo == SIGINT) {
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

