#include <time.h>
#include <syslog.h>

#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define FAN_LOG_FILE "/var/log/fan_control.log"
#define FAN_CHECK_INTERVAL 5
#define MAX_RETRIES 3

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int read_file(const char *path, char *buffer, size_t size) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        syslog(LOG_ERR, "Failed to open %s: %s", path, strerror(errno));
        return -1;
    }

    ssize_t bytes_read = read(fd, buffer, size - 1);
    close(fd);

    if (bytes_read == -1) {
        syslog(LOG_ERR, "Failed to read from %s: %s", path, strerror(errno));
        return -1;
    }

    buffer[bytes_read] = '\0';
    return 0;
}

int write_file(const char *path, const char *value) {
    int fd = open(path, O_WRONLY);
    if (fd == -1) {
        syslog(LOG_ERR, "Failed to open %s: %s", path, strerror(errno));
        return -1;
    }

    ssize_t bytes_written = write(fd, value, strlen(value));
    close(fd);

    if (bytes_written == -1) {
        syslog(LOG_ERR, "Failed to write to %s: %s", path, strerror(errno));
        return -1;
    }

    return 0;
}

int get_max_state() {
    char buffer[16];
    if (read_file("/sys/class/thermal/cooling_device0/max_state", buffer, sizeof(buffer)) != 0) {
        return -1;
    }
    return atoi(buffer);
}

int get_fan_state(int temp, int max_state) {
    if (temp < 45000) return 0;
    if (temp < 55000) return 1;
    if (temp < 65000) return 2;
    return (max_state >= 3) ? 3 : 2;
}

void log_fan_change(int new_state) {
    time_t now;
    time(&now);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0';  // Remove newline

    FILE *log_file = fopen(FAN_LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "[%s] Fan state changed to: %d\n", timestamp, new_state);
        fclose(log_file);
    } else {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
    }
}

int main() {
    openlog("fan_control", LOG_PID | LOG_CONS, LOG_USER);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int max_state = get_max_state();
    if (max_state == -1) {
        syslog(LOG_ERR, "Failed to get max state");
        closelog();
        return 1;
    }

    int current_state = -1;

    while (keep_running) {
        char temp_buffer[16];
        int temp = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && temp == -1) {
            if (read_file(CPU_TEMP_FILE, temp_buffer, sizeof(temp_buffer)) == 0) {
                temp = atoi(temp_buffer);
            } else {
                retries++;
                sleep(1);
            }
        }

        if (temp == -1) {
            syslog(LOG_ERR, "Failed to read CPU temperature after %d attempts", MAX_RETRIES);
            continue;
        }

        int new_state = get_fan_state(temp, max_state);

        if (new_state != current_state) {
            char state_buffer[16];
            snprintf(state_buffer, sizeof(state_buffer), "%d", new_state);

            if (write_file(FAN_STATE_FILE, state_buffer) == 0) {
                current_state = new_state;
                log_fan_change(new_state);
            }
        }

        sleep(FAN_CHECK_INTERVAL);
    }

    // Graceful shutdown
    if (current_state != 0) {
        if (write_file(FAN_STATE_FILE, "0") == 0) {
            log_fan_change(0);
            syslog(LOG_INFO, "Fan stopped during shutdown");
        } else {
            syslog(LOG_ERR, "Failed to stop fan during shutdown");
        }
    }

    closelog();
    return 0;
}

