#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

#define TARGET_TEMP 50.0
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define PWM_FREQ 1000
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_FLAGS 0
#define HEATER_PIN 18
#define SPI_CLK 11
#define SPI_CE 8
#define SPI_MISO 9

typedef struct {
    double setpoint;
    double integral;
    double previous_error;
} PIDController;

static volatile int keep_running = 1;
static FILE *log_file;

void signal_handler(int signo) {
    keep_running = 0;
}

double read_temperature(int handle) {
    char buffer[4];
    if (spiRead(handle, buffer, 4) < 0) {
        fprintf(log_file, "SPI read error: %s\n", strerror(errno));
        return -1;
    }

    uint32_t raw = (buffer[0] << 24) | (buffer[1] << 16) | (buffer[2] << 8) | buffer[3];
    uint16_t fault = raw & 0x7;
    double temp = ((raw >> 18) & 0x3FFF) * 0.25;

    if (fault != 0) {
        fprintf(log_file, "Thermocouple fault: %d\n", fault);
        return -1;
    }

    return temp;
}

double calculate_pid(PIDController *pid, double measured_value) {
    double error = pid->setpoint - measured_value;
    pid->integral += error;
    double derivative = error - pid->previous_error;
    double output = Kp * error + Ki * pid->integral + Kd * derivative;
    pid->previous_error = error;
    return output;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Cannot set signal handler\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("heater_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Cannot open log file\n");
        gpioTerminate();
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open error: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioHardwarePWM(HEATER_PIN, PWM_FREQ, 0);

    PIDController pid = {.setpoint = TARGET_TEMP, .integral = 0, .previous_error = 0};

    while (keep_running) {
        double temp = read_temperature(spi_handle);
        if (temp < 0 || temp > 100) {
            fprintf(log_file, "Temperature out of range: %.2f°C\n", temp);
            gpioPWM(HEATER_PIN, 0);
            pid.integral = 0;
            pid.previous_error = 0;
        } else {
            double pwm_duty = calculate_pid(&pid, temp);
            pwm_duty = (pwm_duty > 100) ? 100 : (pwm_duty < 0) ? 0 : pwm_duty;
            gpioPWM(HEATER_PIN, (unsigned int)(pwm_duty * 255 / 100));

            fprintf(log_file, "Temperature: %.2f°C, PWM: %.2f%%, PID Output: %.2f\n", temp, pwm_duty, pwm_duty);
        }

        fflush(log_file);
        sleep(1);
    }

    gpioPWM(HEATER_PIN, 0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

