#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define POLL_INTERVAL 5

static volatile int keep_running = 1;

void signal_handler(int signo) {
    keep_running = 0;
}

double get_cpu_temperature() {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1;
    }

    long temp_milli;
    if (fscanf(fp, "%ld", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp_milli / 1000.0;
}

int calculate_duty_cycle(double temp) {
    if (temp <= 40.0) return 0;
    if (temp >= 70.0) return 100;

