#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define I2C_BUS 1
#define MEASUREMENT_COMMAND 0x3608
#define MAX_RETRIES 3
#define CRC_POLYNOMIAL 0x131

static volatile int keep_running = 1;

void signal_handler(int signo) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

float convert_to_flow_rate(uint16_t raw_value) {
    return raw_value * 0.01f;
}

int read_sensor(int i2c_handle, uint8_t addr, uint8_t *buffer, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cReadI2CBlock(i2c_handle, addr, buffer, len) == PI_BAD_I2C_BUS) {
            printf("I2C bus error on sensor %02X, attempt %d\n", addr, attempt + 1);
            gpioDelay(100000);  // 100ms delay before retry
        } else {
            return 0;  // Success
        }
    }
    return -1;  // Failed after MAX_RETRIES
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t buffer[4];
    uint16_t raw_value1, raw_value2;
    float flow_rate1, flow_rate2;
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    while (keep_running) {
        i2cWriteWordData(i2c_handle, SENSOR1_ADDR, MEASUREMENT_COMMAND);
        if (read_sensor(i2c_handle, SENSOR1_ADDR, buffer, 3) == 0) {
            raw_value1 = (buffer[0] << 8) | buffer[1];
            if (calculate_crc8(buffer, 2) == buffer[2]) {
                flow_rate1 = convert_to_flow_rate(raw_value1);
            } else {
                printf("CRC check failed for sensor 1\n");
                continue;
            }
        } else {
            printf("Failed to read from sensor 1\n");
            continue;
        }

        i2cWriteWordData(i2c_handle, SENSOR2_ADDR, MEASUREMENT_COMMAND);
        if (read_sensor(i2c_handle, SENSOR2_ADDR, buffer, 3) == 0) {
            raw_value2 = (buffer[0] << 8) | buffer[1];
            if (calculate_crc8(buffer, 2) == buffer[2]) {
                flow_rate2 = convert_to_flow_rate(raw_value2);
            } else {
                printf("CRC check failed for sensor 2\n");
                continue;
            }
        } else {
            printf("Failed to read from sensor 2\n");
            continue;
        }

        time(&now);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow_rate1, flow_rate2);
        fflush(log_file);

        gpioDelay(1000000000);  // 1 second delay
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

