#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18
#define NUM_PULSES_PER_REVOLUTION 360

volatile int running = 1;
volatile int state = 0;
volatile int position = 0;
volatile int last_position = 0;
FILE *log_file;

void signal_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        running = 0;
    }
}

void log_state_change(int new_position) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, Position: %.2f\n", timestamp, (float)new_position / NUM_PULSES_PER_REVOLUTION * 360.0);
    fflush(log_file);
}

void gpio_callback(int gpio, int level, uint32_t tick) {
    int current_a = gpioRead(SENSOR_A_PIN);
    int current_b = gpioRead(SENSOR_B_PIN);

    state = (current_a << 1) | current_b;

    switch (state) {
        case 0:
        case 1:
            if (last_position != position) {
                log_state_change(position);
                last_position = position;
            }
            break;
        case 2:
            if (current_a == 0) position++;
            else position--;
            break;
        case 3:
            if (current_a == 1) position++;
            else position--;
            break;
    }

    if (position < 0) position += NUM_PULSES_PER_REVOLUTION;
    if (position >= NUM_PULSES_PER_REVOLUTION) position -= NUM_PULSES_PER_REVOLUTION;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_A_PIN, PI_INPUT);
    gpioSetMode(SENSOR_B_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP);

    log_file = fopen("encoder_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(SENSOR_A_PIN, gpio_callback) < 0 ||
        gpioSetAlertFunc(SENSOR_B_PIN, gpio_callback) < 0) {
        fprintf(stderr, "Failed to set GPIO alert function\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        gpioSleep(PI_TIME_RELATIVE, 1, 0);
    }

    gpioSetAlertFunc(SENSOR_A_PIN, NULL);
    gpioSetAlertFunc(SENSOR_B_PIN, NULL);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

