#include <sys/ioctl.h>
#include <sys/time.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x39
#define FIFO_DATA_REG 0x60
#define LED_GPIO_PIN 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

static int i2c_fd;
static struct gpiod_line *led_line;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, buf, len);
}

int read_adpd144ri_data(uint16_t *red, uint16_t *ir) {
    uint8_t buf[4];
    if (i2c_read(i2c_fd, FIFO_DATA_REG, buf, 4) != 4) {
        return -1;
    }
    *red = (buf[0] << 8) | buf[1];
    *ir = (buf[2] << 8) | buf[3];
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, ADPD144RI_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "ADPD144RI_LED", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("adpd144ri_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,red,ir\n");

    struct timeval last_sample_time;
    gettimeofday(&last_sample_time, NULL);

    while (1) {
        struct timeval current_time;
        gettimeofday(&current_time, NULL);

        long elapsed_ms = (current_time.tv_sec - last_sample_time.tv_sec) * 1000 +
                          (current_time.tv_usec - last_sample_time.tv_usec) / 1000;

        if (elapsed_ms >= SAMPLE_INTERVAL_MS) {
            uint16_t red, ir;
            if (read_adpd144ri_data(&red, &ir) == 0) {
                struct timeval tv;
                gettimeofday(&tv, NULL);
                fprintf(log_file, "%ld.%06ld,%u,%u\n",
                        (long)tv.tv_sec, (long)tv.tv_usec, red, ir);
                fflush(log_file);

                if (ir > IR_THRESHOLD) {
                    gpiod_line_set_value(led_line, 1);
                } else {
                    gpiod_line_set_value(led_line, 0);
                }

                last_sample_time = current_time;
            } else {
                fprintf(stderr, "Failed to read ADPD144RI data\n");
            }
        }

        usleep(10000);  // Sleep for 10ms to reduce CPU usage
    }

    return EXIT_SUCCESS;
}
