#include <signal.h>
#include <pigpio.h>
#include <pthread.h>
#include <time.h>

#define SENSOR_PIN 18
#define LOG_FILE "rpm_log.txt"
#define INTERVAL_MS 1000

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile int keep_running = 1;

void isr(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

void signal_handler(int signo) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN);

    if (gpioSetISRFunc(SENSOR_PIN, PI_FALLING_EDGE, 0, isr) < 0) {
        fprintf(stderr, "ISR registration failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t start_time = time(NULL);
    int previous_count = 0;

    while (keep_running) {
        time_t current_time = time(NULL);
        if (current_time - start_time >= 1) {
            pthread_mutex_lock(&pulse_mutex);
            int current_count = pulse_count;
            pulse_count = 0;
            pthread_mutex_unlock(&pulse_mutex);

            double rpm = (current_count - previous_count) * 60.0;
            previous_count = current_count;

            time_t log_time = time(NULL);
            struct tm *tm_info = localtime(&log_time);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s, %.2f RPM\n", timestamp, rpm);
            fflush(log_file);

            start_time = current_time;
        }
        gpioSleep(PI_TIME_RELATIVE, 0, 100000);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

