                time_t now;
                struct tm *tm_info;
                char timestamp[64];

                time(&now);
                tm_info = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

                fprintf(log_file, "%s,%u,%u\n", timestamp, red_data, ir_data);
