                if (ir_data > IR_THRESHOLD) {
                    gpiod_line_set_value(led_line, 1);
                } else {
                    gpiod_line_set_value(led_line, 0);
                }

                last_sample_time = current_time;
            }
        }
        usleep(10000);  // Sleep for 10ms to reduce CPU usage
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

