#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define OUT_PIN 17
#define GAIN_PIN 18
#define LOG_FILE "audio_log.txt"
#define POLL_INTERVAL_MS 10

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_event(int level) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s LEVEL %d\n", timestamp, level);
    fclose(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *out_line, *gain_line;
    int out_value, prev_out_value = -1;

    printf("Starting audio event detection...\n");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    out_line = gpiod_chip_get_line(chip, OUT_PIN);
    if (!out_line) {
        fprintf(stderr, "Failed to get line for OUT_PIN %d\n", OUT_PIN);
        goto cleanup;
    }

    gain_line = gpiod_chip_get_line(chip, GAIN_PIN);
    if (!gain_line) {
        fprintf(stderr, "Failed to get line for GAIN_PIN %d\n", GAIN_PIN);
        goto cleanup;
    }

    if (gpiod_line_request_input(out_line, "audio_input") < 0) {
        fprintf(stderr, "Failed to request OUT_PIN %d as input\n", OUT_PIN);
        goto cleanup;
    }

    if (gpiod_line_request_output(gain_line, "audio_gain", 0) < 0) {
        fprintf(stderr, "Failed to request GAIN_PIN %d as output\n", GAIN_PIN);
        goto cleanup;
    }

    while (keep_running) {
        out_value = gpiod_line_get_value(out_line);
        if (out_value < 0) {
            perror("Failed to read OUT_PIN value");
            break;
        }

        if (out_value == 1 && prev_out_value == 0) {
            log_event(1);
        }

        prev_out_value = out_value;
        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    if (gain_line) gpiod_line_release(gain_line);
    if (out_line) gpiod_line_release(out_line);
    if (chip) gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

