        fprintf(stderr, "Failed to request OUT_PIN %d as input\n", OUT_PIN);
        goto cleanup;
    }

    if (gpiod_line_request_output(gain_line, "audio_gain", 0) < 0) {
        fprintf(stderr, "Failed to request GAIN_PIN %d as output\n", GAIN_PIN);
        goto cleanup;
    }

    while (keep_running) {
        out_value = gpiod_line_get_value(out_line);
        if (out_value < 0) {
            perror("Failed to read OUT_PIN value");
            break;
        }

        if (out_value == 1 && prev_out_value == 0) {
            log_event(1);
        }

        prev_out_value = out_value;
        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    if (gain_line) gpiod_line_release(gain_line);
    if (out_line) gpiod_line_release(out_line);
    if (chip) gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
