        gpioI2CClose(i2c_handle);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = gpioI2COpen(I2C_BUS, SENSOR_ADDR);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t start_cmd[] = {0x36, 0x08};
    if (gpioI2CWriteDevice(i2c_handle, start_cmd, sizeof(start_cmd)) < 0) {
        log_error("Failed to start continuous measurement");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("flow_log.csv", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    while (1) {
        time(&now);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        uint8_t read_buffer[3];
        if (gpioI2CReadI2CBlock(i2c_handle, 0, read_buffer, sizeof(read_buffer)) < 0) {
