void cleanup(int signum) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int read_sensor_data(uint8_t *buffer, int length) {
    int ret = i2cReadI2CBlockData(i2c_handle, SENSOR_ADDR, 0x00, buffer, length);
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
    }
    return ret;
}

float clamp(float value, float min, float max) {
    if (value < min) return min;
    if (value > max) return max;
    return value;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C handle open failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    uint8_t sensor_data[7];
    time_t last_log_time = time(NULL);

    while (1) {
        if (read_sensor_data(sensor_data, sizeof(sensor_data)) == sizeof(sensor_data)) {
            uint16_t tvoc = (sensor_data[1] << 8) | sensor_data[2];
            uint16_t eco2 = (sensor_data[5] << 8) | sensor_data[6];

            float iaq = clamp(100.0f - (tvoc / 10.0f) - ((eco2 - 400.0f) / 50.0f), 0.0f, 100.0f);

            time_t current_time = time(NULL);
            if (current_time - last_log_time >= READ_INTERVAL) {
                fprintf(log_file, "%ld,%d,%d,%.1f\n", (long)current_time, tvoc, eco2, iaq);
                fflush(log_file);
                last_log_time = current_time;
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        time_sleep(1);
    }

    return EXIT_SUCCESS;
}

