#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define POLL_INTERVAL_MS 100
#define INTRUSION_THRESHOLD_MS 5000

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

static void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void signal_handler(int signum) {
    keep_running = 0;
}

int main(void) {
    struct timespec last_touch_time, current_time;
    int last_state = 0, current_state;
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_input(line, "ttp223_tamper");
    if (ret < 0) {
        fprintf(stderr, "Failed to request line as input: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &last_touch_time) != 0) {
        fprintf(stderr, "Failed to get initial time: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        current_state = gpiod_line_get_value(line);
        if (current_state < 0) {
            fprintf(stderr, "Failed to read sensor state: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        if (current_state == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &current_time) != 0) {
                fprintf(stderr, "Failed to get current time: %s\n", strerror(errno));
                cleanup();
                return EXIT_FAILURE;
            }

            long elapsed_ms = (current_time.tv_sec - last_touch_time.tv_sec) * 1000 +
                              (current_time.tv_nsec - last_touch_time.tv_nsec) / 1000000;

            if (elapsed_ms >= INTRUSION_THRESHOLD_MS) {
                printf("Intrusion alert!\n");
                last_touch_time = current_time;
            }
        } else {
            last_state = 0;
        }

        struct timespec sleep_time = {
            .tv_sec = POLL_INTERVAL_MS / 1000,
            .tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000
        };
        nanosleep(&sleep_time, NULL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

