#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>

#define PCM_DEVICE "default"
#define PCM_SUBDEVICE "hw:0,0"
#define CHANNEL_LEFT 0
#define CHANNEL_RIGHT 1
#define GPIO_PIN 17
#define BUFFER_SIZE 1024
#define PCM_FILE "audio_capture.pcm"

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int err;
    snd_pcm_t *capture_handle;
    snd_pcm_hw_params_t *params;
    unsigned int val;
    int dir;
    snd_pcm_uframes_t frames;
    char *buffer;
    FILE *file;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    err = gpiod_line_request_output(line, "INMP441_LR_select", 0);
    if (err < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open PCM device
    err = snd_pcm_open(&capture_handle, PCM_SUBDEVICE, SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "Unable to open PCM device: %s\n", snd_strerror(err));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Allocate hardware parameters object
    snd_pcm_hw_params_alloca(&params);

    // Fill it with default values
    snd_pcm_hw_params_any(capture_handle, params);

    // Set access type
    err = snd_pcm_hw_params_set_access(capture_handle, params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        fprintf(stderr, "Unable to set PCM access: %s\n", snd_strerror(err));
        goto cleanup;
    }

    // Set sample format
    err = snd_pcm_hw_params_set_format(capture_handle, params, SND_PCM_FORMAT_S24_3LE);
    if (err < 0) {
        fprintf(stderr, "Unable to set PCM format: %s\n", snd_strerror(err));
        goto cleanup;
    }

    // Set channels
    err = snd_pcm_hw_params_set_channels(capture_handle, params, 2);
    if (err < 0) {
        fprintf(stderr, "Unable to set PCM channels: %s\n", snd_strerror(err));
        goto cleanup;
    }

    // Set sample rate
    val = 48000;
    err = snd_pcm_hw_params_set_rate_near(capture_handle, params, &val, &dir);
    if (err < 0) {
        fprintf(stderr, "Unable to set PCM rate: %s\n", snd_strerror(err));
        goto cleanup;
    }

    // Apply hardware parameters
    err = snd_pcm_hw_params(capture_handle, params);
    if (err < 0) {
        fprintf(stderr, "Unable to set PCM parameters: %s\n", snd_strerror(err));
        goto cleanup;
    }

    // Get the period size
    err = snd_pcm_hw_params_get_period_size(params, &frames, &dir);
    if (err < 0) {
        fprintf(stderr, "Unable to get period size: %s\n", snd_strerror(err));
        goto cleanup;
    }

    // Allocate buffer
    buffer = (char *)malloc(frames * 4);
    if (!buffer) {
        fprintf(stderr, "Unable to allocate buffer\n");
        goto cleanup;
    }

    // Open output file
    file = fopen(PCM_FILE, "wb");
    if (!file) {
        perror("Failed to open output file");
        goto cleanup;
    }

    // Main loop
    while (keep_running) {
        // Select left channel
        gpiod_line_set_value(line, CHANNEL_LEFT);

        // Read from PCM
        err = snd_pcm_readi(capture_handle, buffer, frames);
        if (err != (int)frames) {
            fprintf(stderr, "Error reading from PCM: %s\n", snd_strerror(err));
            break;
        }

        // Write 24-bit data to file as 16-bit
