#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18
#define POLL_INTERVAL_MS 50
#define FAN_FREQUENCY 100
#define MAX_DUTY_CYCLE 80
#define SENSOR_TIMEOUT_MS 1000

static volatile int keep_running = 1;

void log_event(const char *message) {
    FILE *log_file = fopen("flame_log.txt", "a");
    if (log_file) {
        time_t now;
        time(&now);
        struct tm *tm_info = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fclose(log_file);
    }
}

void signal_handler(int signo) {
    keep_running = 0;
}

double calculate_duty_cycle(int flame_duration_ms) {
    // Exponential curve scaling from 0 to 80%
    return MAX_DUTY_CYCLE * (1 - exp(-flame_duration_ms / 1000.0));
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_PIN, FAN_FREQUENCY);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("System started");

    int flame_detected = 0;
    int flame_start_time = 0;
    int last_sensor_value = 1;
    int debounce_time = 0;

    while (keep_running) {
        int current_time = gpioTick();
        int sensor_value = gpioRead(FLAME_SENSOR_PIN);

        if (sensor_value != last_sensor_value) {
            debounce_time = current_time;
        }

        if (current_time - debounce_time >= POLL_INTERVAL_MS) {
            if (sensor_value == 0 && !flame_detected) {
                // Flame detected
                flame_detected = 1;
                flame_start_time = current_time;
                log_event("Flame detected");
            } else if (sensor_value == 1 && flame_detected) {
                // Flame ended
                flame_detected = 0;
                int flame_duration = current_time - flame_start_time;
                double duty_cycle = calculate_duty_cycle(flame_duration);
                gpioPWM(FAN_PIN, (int)(duty_cycle * 255 / 100));
                log_event("Flame ended");
            }

            if (!flame_detected) {
                gpioPWM(FAN_PIN, 0);
            }

            last_sensor_value = sensor_value;
        }

        gpioDelay(1000); // Sleep for 1ms to prevent busy-waiting
    }

    gpioPWM(FAN_PIN, 0);
    gpioTerminate();
    log_event("System shutdown");

    return 0;
}

