#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define GPIO_TRIGGER 23
#define GPIO_DATA_READY 24
#define FRAME_SIZE 32768
#define LOG_FILE "awr1642_log.bin"
#define MAGIC_NUMBER 0x52444144

typedef struct {
    uint32_t start_freq;
    uint32_t end_freq;
    uint16_t num_chirps;
    uint16_t num_samples;
    uint32_t frame_period;
} ConfigStruct;

typedef struct {
    uint32_t magic_number;
    uint64_t timestamp;
    ConfigStruct config;
} LogHeader;

int spi_fd;
FILE *log_file;

void cleanup(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        cleanup(0);
    }

    int ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret == -1) {
        fprintf(stderr, "Failed to set SPI mode\n");
        cleanup(0);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret == -1) {
        fprintf(stderr, "Failed to set SPI speed\n");
        cleanup(0);
    }

    gpioSetMode(GPIO_TRIGGER, PI_OUTPUT);
    gpioSetMode(GPIO_DATA_READY, PI_INPUT);
    gpioSetPullUpDown(GPIO_DATA_READY, PI_PUD_UP);

    log_file = fopen(LOG_FILE, "wb");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
    }

    LogHeader header = {
        .magic_number = MAGIC_NUMBER,
        .timestamp = 0,
        .config = {
            .start_freq = 770000000,
            .end_freq = 790000000,
            .num_chirps = 64,
            .num_samples = 256,
            .frame_period = 100000
        }
    };

    if (fwrite(&header, sizeof(LogHeader), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write log header\n");
        cleanup(0);
    }

    uint8_t *buffer = malloc(FRAME_SIZE);
    if (!buffer) {
        fprintf(stderr, "Failed to allocate memory for frame buffer\n");
        cleanup(0);
    }

    uint64_t frame_number = 0;
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)buffer,
        .rx_buf = (unsigned long)buffer,
        .len = FRAME_SIZE,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    while (1) {
        gpioWrite(GPIO_TRIGGER, 1);
        usleep(10);
        gpioWrite(GPIO_TRIGGER, 0);

        while (gpioRead(GPIO_DATA_READY) == PI_LOW) {
            // Wait for data ready
        }

        xfer.tx_buf = (unsigned long)buffer;
        xfer.rx_buf = (unsigned long)buffer;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
            fprintf(stderr, "Failed to perform SPI transfer\n");
            cleanup(0);
        }

        header.timestamp = time(NULL);
        if (fwrite(&header.timestamp, sizeof(uint64_t), 1, log_file) != 1 ||
            fwrite(&frame_number, sizeof(uint64_t), 1, log_file) != 1 ||
            fwrite(buffer, FRAME_SIZE, 1, log_file) != 1) {
            fprintf(stderr, "Failed to write frame data\n");
            cleanup(0);
        }

        frame_number++;
    }

    free(buffer);
    cleanup(0);
    return 0;
}

