static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_flame_state(int state) {
    time_t now;
    struct tm *utc_time;
    char timestamp[64];

    time(&now);
    utc_time = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    fprintf(log_file, "%s Flame %s\n", timestamp, state ? "detected" : "cleared");
    fflush(log_file);
}

int main() {
    int last_state = -1;
    int current_state;

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Unable to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!line) {
        fprintf(stderr, "Error: Unable to get GPIO line\n");
        goto cleanup;
    }

    // Request line as input
    if (gpiod_line_request_input(line, "flame_sensor") < 0) {
        fprintf(stderr, "Error: Unable to request GPIO line as input\n");
        goto cleanup;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Unable to open log file\n");
        goto cleanup;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        current_state = gpiod_line_get_value(line);
        if (current_state < 0) {
            fprintf(stderr, "Error: Unable to read GPIO line value\n");
            break;
        }

        if (current_state != last_state) {
            log_flame_state(current_state);
            last_state = current_state;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

