#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define RESULT_REG 0x00
#define CONFIG_REG 0x01
#define CONVERSION_TIME 100 // ms
#define RETRY_DELAY 1000 // ms

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

double compute_lux(uint16_t result) {
    uint16_t exponent = (result >> 12) & 0xF;
    uint16_t mantissa = result & 0x0FFF;
    return 0.01 * (1 << exponent) * mantissa;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    uint16_t config = 0xC610; // Continuous mode, 100ms conversion time, auto full-scale
    if (i2cWriteWordData(i2c_handle, CONFIG_REG, config) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("light_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        uint16_t result;
        int retries = 0;
        while (retries < 3) {
            if (i2cReadWordData(i2c_handle, RESULT_REG, &result) >= 0) {
                break;
            }
            retries++;
            usleep(RETRY_DELAY * 1000);
        }

        if (retries == 3) {
            fprintf(stderr, "Failed to read sensor data after 3 attempts\n");
            continue;
        }

        double lux = compute_lux(result);
        time_t now;
        struct tm *tm_info;
        char timestamp[64];

        time(&now);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

        fprintf(log_file, "%s, %.2f\n", timestamp, lux);
        fflush(log_file);

        usleep(CONVERSION_TIME * 1000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

