#include <errno.h>
#include <string.h>

#define CHIP "gpiochip0"
#define LINE_OFFSET 17
#define LOG_INTERVAL 1

volatile sig_atomic_t exit_flag = 0;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        exit_flag = 1;
    }
}

void log_flame_status(int line_value) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    printf("%s - Flame Detected: %s\n", timestamp, line_value == 0 ? "YES" : "NO");
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request_config config;
    struct gpiod_line_settings *settings;
    int line_value;

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    settings = gpiod_line_settings_new();
    if (!settings) {
        fprintf(stderr, "Failed to create line settings: %s\n", strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "Failed to set line direction: %s\n", strerror(errno));
        goto cleanup_settings;
    }

    if (gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to set line bias: %s\n", strerror(errno));
        goto cleanup_settings;
    }

    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.consumer = "Flame Detection";
    config.requested_settings = settings;

    line = gpiod_chip_get_line(chip, LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", LINE_OFFSET, strerror(errno));
        goto cleanup_settings;
    }

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Failed to request line %d: %s\n", LINE_OFFSET, strerror(errno));
        goto cleanup_line;
    }

    while (!exit_flag) {
        line_value = gpiod_line_get_value(line);
        if (line_value < 0) {
            fprintf(stderr, "Failed to read line value: %s\n", strerror(errno));
            break;
        }

        log_flame_status(line_value);
        sleep(LOG_INTERVAL);
    }

cleanup_line:
    gpiod_line_release(line);

cleanup_settings:
    gpiod_line_settings_free(settings);

cleanup_chip:
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

