#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define NUM_CHANNELS 8
#define CHIP_NAME "gpiochip0"
const int gpio_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[NUM_CHANNELS] = {NULL};
volatile sig_atomic_t keep_running = 1;

void cleanup(void) {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void signal_handler(int signum) {
    if (signum == SIGINT) {
        keep_running = 0;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d: %s\n", gpio_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        int ret = gpiod_line_request_input(lines[i], "TTP226_Channel");
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %d as input: %s\n", gpio_pins[i], strerror(-ret));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    while (keep_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to read value from GPIO %d: %s\n", gpio_pins[i], strerror(-value));
                cleanup();
                return EXIT_FAILURE;
            }
            printf("Channel %d: %d\n", i, value);
        }
        usleep(100000); // 100ms
    }

    cleanup();
    return EXIT_SUCCESS;
}

