#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define NUM_CHANNELS 8
#define CHANNEL_PINS[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9}
#define POLL_INTERVAL_MS 100

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(CHANNEL_PINS[i], PI_INPUT) < 0 ||
            gpioSetPullUpDown(CHANNEL_PINS[i], PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Failed to configure GPIO %d\n", CHANNEL_PINS[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct timespec start, current;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (keep_running) {
        char buffer[256];
        int offset = 0;
        offset += snprintf(buffer + offset, sizeof(buffer) - offset, "[");

        long long elapsed_ms;
        clock_gettime(CLOCK_MONOTOTIC, &current);
        elapsed_ms = (current.tv_sec - start.tv_sec) * 1000LL + (current.tv_nsec - start.tv_nsec) / 1000000LL;
        offset += snprintf(buffer + offset, sizeof(buffer) - offset, "+%lld ms] ", elapsed_ms);

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int state = gpioRead(CHANNEL_PINS[i]);
            offset += snprintf(buffer + offset, sizeof(buffer) - offset, "CH%d=%d ", i + 1, state);
        }

        printf("%s\n", buffer);
        fflush(stdout);

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

