#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_CHANNELS] = {NULL};
static volatile sig_atomic_t keep_running = 1;

void sigint_handler(int signum) {
    keep_running = 0;
}

int main() {
    int gpio_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};
    struct timespec poll_interval = {0, POLL_INTERVAL_MS * 1000000};
    struct timespec wait_interval = {0, 1000000}; // 1ms wait for signal

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return EXIT_FAILURE;
    }

    // Request lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", gpio_pins[i]);
            goto cleanup;
        }

        int ret = gpiod_line_request_input(lines[i], "TTP226_Channel");
        if (ret < 0) {
            fprintf(stderr, "Failed to request line for GPIO %d\n", gpio_pins[i]);
            goto cleanup;
        }
    }

    // Set up SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        goto cleanup;
    }

    printf("Timestamp,Channel0,Channel1,Channel2,Channel3,Channel4,Channel5,Channel6,Channel7\n");

    // Main loop
    while (keep_running) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        printf("%s,", timestamp);

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to read value from GPIO %d\n", gpio_pins[i]);
                goto cleanup;
            }
            printf("%d", value);
            if (i < NUM_CHANNELS - 1) printf(",");
        }
        printf("\n");
        fflush(stdout);

        nanosleep(&poll_interval, &wait_interval);
    }

cleanup:
    // Release resources
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

