#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define TILT_SENSOR_PIN 4

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_message(const char *message) {
    time_t now;
    time(&now);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize gpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TILT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_PIN, PI_PUD_UP);

    signal(SIGINT, signal_handler);

    log_message("Tilt Sensor Monitoring Started");

    int last_state = -1;
    while (keep_running) {
        int current_state = gpioRead(TILT_SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO pin\n");
            break;
        }

        if (current_state != last_state) {
            if (current_state == 0) {
                log_message("Tilted");
            } else {
                log_message("Not Tilted");
            }
            last_state = current_state;
        }

        gpioSleep(PI_TIME_RELATIVE, 0, 100000000); // Sleep for 100ms
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

