#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x60
#define PART_ID_REG 0x00
#define PART_ID 0x45
#define HW_KEY_REG 0x0B
#define HW_KEY 0x17
#define CHLIST_REG 0x10
#define CHLIST_UV_ALS 0x01
#define ALS_FORCE_CMD 0x06
#define UVINDEX_REG 0x2A
#define ALS_VIS_DATA_0_REG 0x22
#define ALS_VIS_DATA_1_REG 0x23

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (i2cOpen(I2C_BUS, SENSOR_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Verify PART ID
    uint8_t part_id;
    if (i2cReadByteData(I2C_BUS, SENSOR_ADDR, PART_ID_REG) != PART_ID) {
        fprintf(stderr, "Sensor PART ID verification failed\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Write HW_KEY
    if (i2cWriteByteData(I2C_BUS, SENSOR_ADDR, HW_KEY_REG, HW_KEY) < 0) {
        fprintf(stderr, "Failed to write HW_KEY\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure CHLIST
    if (i2cWriteByteData(I2C_BUS, SENSOR_ADDR, CHLIST_REG, CHLIST_UV_ALS) < 0) {
        fprintf(stderr, "Failed to configure CHLIST\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("uv_als_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "timestamp,uv_index,als_visible\n");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        // Trigger ALS measurement
        if (i2cWriteByteData(I2C_BUS, SENSOR_ADDR, ALS_FORCE_CMD, 0) < 0) {
            fprintf(stderr, "Failed to trigger ALS measurement\n");
            break;
        }

        // Wait for measurement to complete (approx. 100ms)
        time_sleep(0.1);

        // Read UV index
        int16_t uv_index = i2cReadWordData(I2C_BUS, SENSOR_ADDR, UVINDEX_REG);
        if (uv_index < 0) {
            fprintf(stderr, "Failed to read UV index\n");
            break;
        }

        // Read ALS Visible data
        uint16_t als_vis = i2cReadWordData(I2C_BUS, SENSOR_ADDR, ALS_VIS_DATA_0_REG);
        if (als_vis < 0) {
            fprintf(stderr, "Failed to read ALS Visible data\n");
            break;
        }

        // Print to console
        printf("UV Index: %d, ALS Visible: %d\n", uv_index, als_vis);

        // Log to CSV
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                t->tm_hour, t->tm_min, t->tm_sec, uv_index, als_vis);
        fflush(log_file);

        // Wait for 1 second
        time_sleep(1);
    }

    fclose(log_file);
    i2cClose(I2C_BUS);
    gpioTerminate();
    return EXIT_SUCCESS;
}

