#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESSES {0x36, 0x37}
#define START_MEASUREMENT_COMMAND 0x3608
#define MEASUREMENT_REGISTER 0x00
#define MEASUREMENT_SIZE 9
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define FLOW_SCALE_FACTOR 0.036
#define ALARM_GPIO 17
#define LOG_FILE "flow_log.txt"
#define LOG_INTERVAL 1

static int i2c_fd;
static struct gpiod_line *alarm_line;
static FILE *log_file;

static void cleanup(int signum) {
    if (alarm_line) {
        gpiod_line_release(alarm_line);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

static uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int16_t convert_raw_to_flow(const uint8_t *data) {
    return (int16_t)((data[0] << 16) | (data[1] << 8) | data[2]) * FLOW_SCALE_FACTOR;
}

static int read_sensor(int address, int16_t *flow_rate) {
    uint8_t buffer[MEASUREMENT_SIZE];
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[1];

    memset(&packets, 0, sizeof(packets));
    memset(&messages[0], 0, sizeof(struct i2c_msg));

    messages[0].addr = address;
    messages[0].flags = 0;
    messages[0].len = 1;
    messages[0].buf = &buffer[0];

    packets.msgs = messages;
    packets.nmsgs = 1;

    if (ioctl(i2c_fd, I2C_RDWR, &packets) < 0) {
        fprintf(stderr, "Error reading from sensor at address 0x%02X: %s\n", address, strerror(errno));
        return -1;
    }

    if (calculate_crc(buffer, MEASUREMENT_SIZE - 1) != buffer[MEASUREMENT_SIZE - 1]) {
        fprintf(stderr, "CRC check failed for sensor at address 0x%02X\n", address);
        return -1;
    }

    *flow_rate = convert_raw_to_flow(buffer);
    return 0;
}

int main() {
    int sensor_addresses[] = SENSOR_ADDRESSES;
    int16_t flow_rates[2] = {0};
    struct timespec sleep_time = {1, 0};
    struct timespec log_time = {0, 0};

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    alarm_line = gpiod_chip_get_line(chip, ALARM_GPIO);
    if (!alarm_line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(alarm_line, "flow_alarm", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    for (int address : sensor_addresses) {
        if (ioctl(i2c_fd, I2C_SLAVE_FORCE, address) < 0) {
            fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", address, strerror(errno));
            continue;
        }

        uint8_t start_command[] = {START_MEASUREMENT_COMMAND >> 8, START_MEASUREMENT_COMMAND & 0xFF};
