int buffer_index = 0;
int buffer_full = 0;

void cleanup(int sig) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[26];

    printf("\nCleaning up and printing buffer contents:\n");
    for (int i = 0; i < (buffer_full ? BUFFER_SIZE : buffer_index); i++) {
        time(&rawtime);
        timeinfo = localtime(&circular_buffer[i].timestamp);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("Timestamp: %s, Reading: %d\n", time_str, circular_buffer[i].reading);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP);

    signal(SIGINT, cleanup);

    while (1) {
        int reading = gpioRead(SENSOR_PIN);
        if (reading == 0) {
            time_t current_time = time(NULL);
            circular_buffer[buffer_index].timestamp = current_time;
            circular_buffer[buffer_index].reading = reading;
            printf("Obstacle detected! Timestamp: %ld, Reading: %d\n", (long)current_time, reading);

            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            if (buffer_index == 0) {
                buffer_full = 1;
            }
        }
        gpioSleep(PI_TIME_RELATIVE, 0, POLL_INTERVAL_MS * 1000);
    }

    return 0;
}

