#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x55
#define MODE_CONTROL_REG 0x1D
#define OPERATING_STATUS_REG 0x1B
#define ACCEL_X_LSB_REG 0x2A
#define ACCEL_X_MSB_REG 0x2B
#define ACCEL_Y_LSB_REG 0x2C
#define ACCEL_Y_MSB_REG 0x2D
#define ACCEL_Z_LSB_REG 0x2E
#define ACCEL_Z_MSB_REG 0x2F
#define SCALE_FACTOR 0.0009765625
#define RETRY_DELAY_MS 100
#define SAMPLE_INTERVAL_MS 500

static int i2c_fd;
static FILE *csv_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (csv_file) {
        fclose(csv_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    ssize_t bytes_written = write(fd, buf, sizeof(buf));
    if (bytes_written != sizeof(buf)) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (i2c_write(fd, reg, 0) != 0) {
        return -1;
    }
    ssize_t bytes_read = read(fd, value, 1);
    if (bytes_read != 1) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_word(int fd, uint8_t reg_lsb, uint8_t reg_msb, int16_t *value) {
    uint8_t lsb, msb;
    if (i2c_read(fd, reg_lsb, &lsb) != 0 || i2c_read(fd, reg_msb, &msb) != 0) {
        return -1;
    }
    *value = (msb << 8) | lsb;
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, MODE_CONTROL_REG, 0x10) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int retry_count = 0;
    uint8_t status;
    do {
        if (i2c_read(i2c_fd, OPERATING_STATUS_REG, &status) != 0) {
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (status & 0x01) {
            break;
        }
        usleep(RETRY_DELAY_MS * 1000);
        retry_count++;
    } while (retry_count < 100);

    if (!(status & 0x01)) {
        fprintf(stderr, "Sensor failed to activate within 1 second\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    csv_file = fopen("fan_health.csv", "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "Timestamp,X (g),Y (g),Z (g)\n");
    }

    struct timespec ts;
    char timestamp[64];
    int16_t x_raw, y_raw, z_raw;
    float x_g, y_g, z_g;

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));

        if (i2c_read_word(i2c_fd, ACCEL_X_LSB_REG, ACCEL_X_MSB_REG, &x_raw) == 0) {
            x_g = x_raw * SCALE_FACTOR;
        } else {
            x_g = 0;
        }

        if (i2c_read_word(i2c_fd, ACCEL_Y_LSB_REG, ACCEL_Y_MSB_REG, &y_raw) == 0) {
            y_g = y_raw * SCALE_FACTOR;
        } else {
            y_g = 0;
        }

        if (i2c_read_word(i2c_fd, ACCEL_Z_LSB_REG, ACCEL_Z_MSB_REG, &z_raw) == 0) {
            z_g = z_raw * SCALE_FACTOR;
        } else {
            z_g = 0;
        }

        fprintf(csv_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x_g, y_g, z_g);
        fflush(csv_file);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

