#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define LED_PIN 25
#define POLL_INTERVAL_MS 100
#define OBSTACLE_THRESHOLD 10 // cm

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR2_PIN, PI_INPUT) < 0 ||
        gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "GPIO mode setting failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "GPIO pull-up/down setting failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        int sensor1_state = gpioRead(SENSOR1_PIN);
        int sensor2_state = gpioRead(SENSOR2_PIN);

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "GPIO read failed\n");
            break;
        }

        if (sensor1_state == 0 || sensor2_state == 0) {
            if (gpioWrite(LED_PIN, 1) < 0) {
                fprintf(stderr, "Failed to turn on LED\n");
                break;
            }
        } else {
            if (gpioWrite(LED_PIN, 0) < 0) {
                fprintf(stderr, "Failed to turn off LED\n");
                break;
