#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x0E
#define DEVICE_ID_REG 0x00
#define EXPECTED_DEVICE_ID 0x8D
#define DATA_REG 0x01
#define LSB_SCALE_FACTOR 0.0078125 // 50 mT range

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int i2c_handle;
    FILE *log_file;
    char log_filename[] = "magnetic_log.csv";
    int16_t raw_data[3];
    float magnetic_field[3];
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    char device_id;
    if (i2cReadByteData(i2c_handle, DEVICE_ID_REG, &device_id) < 0) {
        fprintf(stderr, "Failed to read device ID: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Invalid device ID: 0x%02X\n", device_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file and write header
    log_file = fopen(log_filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (ftell(log_file) == 0) { // File is newly created
        fprintf(log_file, "Timestamp,X (mT),Y (mT),Z (mT)\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        // Read X, Y, Z data
        for (int i = 0; i < 3; i++) {
            if (i2cReadWordData(i2c_handle, DATA_REG + i * 2, (char *)&raw_data[i]) < 0) {
                fprintf(stderr, "Failed to read axis %d data: %s\n", i, strerror(errno));
                continue;
            }
            // Convert to signed 16-bit
            if (raw_data[i] & 0x8000) {
                raw_data[i] |= 0xFFFF0000;
            }
            // Convert to mT
            magnetic_field[i] = raw_data[i] * LSB_SCALE_FACTOR;
        }

        // Get current time
        time(&now);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        // Log data
        fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, magnetic_field[0], magnetic_field[1], magnetic_field[2]);
        fflush(log_file);

        gpioSleep(PI_TIME_RELATIVE, 0, 100000000); // Sleep for 100ms
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

