#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define PIN 4
#define PULSE_COUNT_PIN 4
#define LOG_FILE "rpm_log.txt"
#define WINDOW_SECONDS 1
#define PULSES_PER_REVOLUTION 1

static volatile int pulse_count = 0;
static FILE *log_file = NULL;
static int timer = -1;
static int callback = -1;

void signal_handler(int signum) {
    if (timer >= 0) {
        gpioSetTimerFunc(timer, 0, NULL);
    }
    if (callback >= 0) {
        gpioSetAlertFunc(PIN, NULL);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        __atomic_add_fetch(&pulse_count, 1, __ATOMIC_SEQ_CST);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(PIN, PI_INPUT);
    gpioSetPullUpDown(PIN, PI_PUD_UP);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    callback = gpioSetAlertFunc(PIN, pulse_callback);
    if (callback < 0) {
        fprintf(stderr, "Failed to set alert function: %s\n", gpioStrError(callback));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    timer = gpioSetTimerFunc(WINDOW_SECONDS * 1000000, pulse_callback, NULL);
    if (timer < 0) {
        fprintf(stderr, "Failed to set timer function: %s\n", gpioStrError(timer));
        gpioSetAlertFunc(PIN, NULL);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_log_time = time(NULL);
    while (1) {
        time_t current_time = time(NULL);
        if (current_time - last_log_time >= 1) {
            int pulses = __atomic_exchange_n(&pulse_count, 0, __ATOMIC_SEQ_CST);
            int rpm = pulses * 60;

            time_t now;
            struct tm *tm_info;
            char time_str[20];

            time(&now);
            tm_info = localtime(&now);
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s %d\n", time_str, rpm);
            fflush(log_file);
            printf("%s %d\n", time_str, rpm);

            last_log_time = current_time;
        }
        gpioSleep(PI_TIME_RELATIVE, 0, 100000);
    }

    return EXIT_SUCCESS;
}

