#define POLL_INTERVAL_MS 50

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *touch_sensor_line = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (touch_sensor_line) {
        gpiod_line_release(touch_sensor_line);
        touch_sensor_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main() {
    int ret;

    openlog("ttp223b_led", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting TTP223B LED program");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return EXIT_FAILURE;
    }

    touch_sensor_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_sensor_line) {
        syslog(LOG_ERR, "Failed to get touch sensor line: %s", strerror(errno));
        goto cleanup_chip;
    }

    ret = gpiod_line_request_input(touch_sensor_line, "TTP223B Touch Sensor");
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request touch sensor line: %s", strerror(-ret));
        goto cleanup_touch_sensor;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        syslog(LOG_ERR, "Failed to get LED line: %s", strerror(errno));
        goto cleanup_touch_sensor;
    }

    ret = gpiod_line_request_output(led_line, "LED", 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request LED line: %s", strerror(-ret));
        goto cleanup_led;
    }

    while (keep_running) {
        int value = gpiod_line_get_value(touch_sensor_line);
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor: %s", strerror(errno));
            break;
        }

        if (value) {
            gpiod_line_set_value(led_line, 1);
            syslog(LOG_INFO, "Touch detected, LED on");
        } else {
            gpiod_line_set_value(led_line, 0);
            syslog(LOG_INFO, "No touch, LED off");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup_led:
    gpiod_line_release(led_line);
cleanup_touch_sensor:
    gpiod_line_release(touch_sensor_line);
cleanup_chip:
    gpiod_chip_close(chip);

    cleanup();
    closelog();
    syslog(LOG_INFO, "TTP223B LED program terminated");

    return EXIT_SUCCESS;
}

