#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TOUCH_PIN 17
#define LED_PIN 18
#define DEBOUNCE_TIME_MS 50

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *touch_line = NULL;
static struct gpiod_line *led_line = NULL;
static volatile bool running = true;

void cleanup(void) {
    if (led_line) {
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
        touch_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

void signal_handler(int signum) {
    running = false;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        fprintf(stderr, "Failed to get touch line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(touch_line, "TTP223B") < 0) {
        fprintf(stderr, "Failed to request touch line as input\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct gpiod_line_event event;
    int last_value = -1;
    struct timespec wait_time = {0, 10000000}; // 10ms

    while (running) {
        int value = gpiod_line_get_value(touch_line);
        if (value < 0) {
            fprintf(stderr, "Failed to read touch line value\n");
            break;
        }

        if (value == 1 && last_value == 0) {
            // Rising edge detected
            usleep(DEBOUNCE_TIME_MS * 1000);
            value = gpiod_line_get_value(touch_line);
            if (value < 0) {
                fprintf(stderr, "Failed to read touch line value after debounce\n");
                break;
            }

            if (value == 1) {
                // Confirm rising edge
                int led_value = gpiod_line_get_value(led_line);
                if (led_value < 0) {
                    fprintf(stderr, "Failed to read LED line value\n");
                    break;
                }
                if (gpiod_line_set_value(led_line, !led_value) < 0) {
                    fprintf(stderr, "Failed to set LED line value\n");
                    break;
                }
            }
        }

        last_value = value;

        if (gpiod_line_event_wait(touch_line, &wait_time) > 0) {
            if (gpiod_line_event_read(touch_line, &event) < 0) {
                fprintf(stderr, "Failed to read line event\n");
                break;
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

