#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

#define BUFFER_SIZE 100
#define POLL_INTERVAL_MS 50
#define SENSOR_PIN_1 4
#define SENSOR_PIN_2 17
#define LED_PIN_1 27
#define LED_PIN_2 22

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int log_index = 0;
int overflow_count = 0;
volatile int keep_running = 1;

void log_event(int sensor_pin, int state) {
    log_buffer[log_index].sensor_pin = sensor_pin;
    log_buffer[log_index].timestamp = time(NULL);
    log_buffer[log_index].state = state;
    log_index = (log_index + 1) % BUFFER_SIZE;
    if (log_index == 0) {
        overflow_count++;
    }
}

void print_log_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("Sensor: %d, Time: %ld, State: %d\n",
               log_buffer[i].sensor_pin,
               log_buffer[i].timestamp,
               log_buffer[i].state);
    }
    printf("Overflow count: %d\n", overflow_count);
}

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize gpio\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_PIN_1, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_PIN_2, PI_INPUT) < 0 ||
        gpioSetMode(LED_PIN_1, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_PIN_2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        int state1 = gpioRead(SENSOR_PIN_1);
        int state2 = gpioRead(SENSOR_PIN_2);

        if (state1 < 0 || state2 < 0) {
            fprintf(stderr, "Failed to read GPIO states\n");
            break;
        }

        gpioWrite(LED_PIN_1, state1);
        gpioWrite(LED_PIN_2, state2);

        if (state1 != gpioRead(SENSOR_PIN_1) || state2 != gpioRead(SENSOR_PIN_2)) {
            fprintf(stderr, "GPIO read inconsistent\n");
        }

        log_event(SENSOR_PIN_1, state1);
        log_event(SENSOR_PIN_2, state2);

        time_sleep(POLL_INTERVAL_MS / 1000.0);
    }

    gpioWrite(LED_PIN_1, 0);
    gpioWrite(LED_PIN_2, 0);

    print_log_buffer();

    gpioTerminate();
    return 0;
}

