#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define RAIN_SENSOR_PIN 17
#define LOG_FILE_PATH "/var/log/rain_events.log"
#define POLL_INTERVAL_MS 500

static FILE *log_file = NULL;

void log_event(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] %s\n", time_str, message);
    fflush(log_file);
}

void signal_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (gpioInitialised()) {
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    log_file = fopen(LOG_FILE_PATH, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = gpioRead(RAIN_SENSOR_PIN);
    if (last_state < 0) {
        fprintf(stderr, "Failed to read initial sensor state\n");
        signal_handler(0);
        return EXIT_FAILURE;
    }

    while (1) {
        int current_state = gpioRead(RAIN_SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Failed to read sensor state\n");
            signal_handler(0);
            return EXIT_FAILURE;
        }

        if (current_state != last_state) {
            if (current_state == 0) {
                log_event("Rain Detected");
            } else {
                log_event("No Rain");
            }
            last_state = current_state;
        }

        time_sleep(POLL_INTERVAL_MS / 1000.0);
    }

    return EXIT_SUCCESS;
}

