#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define PIN1 17
#define PIN2 18
#define DEBOUNCE_TIME_MS 5
#define PULSES_PER_REVOLUTION 2

volatile sig_atomic_t keep_running = 1;
volatile int pulse_count = 0;
volatile time_t last_pulse_time = 0;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = 0;
    }
}

void log_to_csv(FILE *file, int pin1_state, int pin2_state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s,%d,%d\n", timestamp, pin1_state, pin2_state);
    fflush(file);
}

void gpio_callback(int gpio, int level, uint32_t tick) {
    static int last_level1 = -1;
    static int last_level2 = -1;
    time_t current_time = time(NULL);

    if (gpio == PIN1) {
        if (level != last_level1 && (current_time - last_pulse_time) > DEBOUNCE_TIME_MS / 1000) {
            pulse_count++;
            last_pulse_time = current_time;
            last_level1 = level;
        }
    } else if (gpio == PIN2) {
        if (level != last_level2 && (current_time - last_pulse_time) > DEBOUNCE_TIME_MS / 1000) {
            pulse_count++;
            last_pulse_time = current_time;
            last_level2 = level;
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    FILE *log_file = fopen("shaft_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIN1, PI_INPUT) < 0 || gpioSetMode(PIN2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIN1, PI_PUD_OFF) < 0 || gpioSetPullUpDown(PIN2, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set GPIO pull-up/down\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(PIN1, gpio_callback) < 0 || gpioSetAlertFunc(PIN2, gpio_callback) < 0) {
        fprintf(stderr, "Failed to set GPIO alert function\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring RPM. Press Ctrl+C to exit.\n");

    time_t start_time = time(NULL);
    while (keep_running) {
        time_t current_time = time(NULL);
        if (current_time - start_time >= 1) {
            double rpm = (pulse_count / PULSES_PER_REVOLUTION) / ((current_time - start_time) / 60.0);
            printf("RPM: %.2f\n", rpm);
            pulse_count = 0;
            start_time = current_time;
        }

        int pin1_state = gpioRead(PIN1);
        int pin2_state = gpioRead(PIN2);
        log_to_csv(log_file, pin1_state, pin2_state);

        gpioSleep(PI_TIME_RELATIVE, 0, 100000); // Sleep for 100ms
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

