#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x28
#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HEART_RATE_REG 0x02
#define SPO2_REG 0x04

static FILE *log_file;
static int i2c_handle;

void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        closeI2C(i2c_handle);
    }
    if (gpioInitialised()) {
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    char part_id;
    if (i2cReadByteData(i2c_handle, PART_ID_REG, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        closeI2C(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Sensor PART_ID: 0x%02X\n", part_id);

    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        closeI2C(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        closeI2C(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    time_t last_log_time = 0;
    while (1) {
        time_t current_time = time(NULL);
        if (current_time - last_log_time >= 1) {
            last_log_time = current_time;

            char heart_rate, spo2;
            if (i2cReadByteData(i2c_handle, HEART_RATE_REG, &heart_rate) < 0 ||
                i2cReadByteData(i2c_handle, SPO2_REG, &spo2) < 0) {
                fprintf(stderr, "Failed to read sensor data\n");
                continue;
            }

            struct tm *tm_info = localtime(&current_time);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
            fflush(log_file);
        }
        gpioSleep(1, 0, 100000); // Sleep for 100ms
    }

    return EXIT_SUCCESS;
}

