#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define ALARM_PIN 27
#define CHECK_INTERVAL 100000 // 100 ms in microseconds
#define THRESHOLD_TIME 2000 // 2 seconds in microseconds

FILE *logfile;

void log_event(const char *event) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(logfile, "%s - %s\n", timestamp, event);
    fflush(logfile);
}

void cleanup(int signum) {
    gpioWrite(ALARM_PIN, LOW);
    log_event("Alarm deactivated");
    fclose(logfile);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN);

    gpioWrite(ALARM_PIN, LOW);

    logfile = fopen("bridge_integrity.log", "a");
    if (logfile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    log_event("Bridge integrity monitoring started");

    uint32_t last_tilt_time = 0;
    uint32_t tilt_start_time = 0;
    int sensor1_state = 0, sensor2_state = 0;
    int both_low_count = 0;

    while (1) {
        int sensor1 = gpioRead(SENSOR1_PIN);
        int sensor2 = gpioRead(SENSOR2_PIN);

        if (sensor1 < 0 || sensor2 < 0) {
            fprintf(stderr, "Error reading sensor values\n");
            cleanup(0);
        }

        if (sensor1 || sensor2) {
            if (!sensor1_state || !sensor2_state) {
                tilt_start_time = gpioTick();
                log_event("Tilt detected");
                sensor1_state = 1;
                sensor2_state = 1;
            }

            if (gpioTick() - tilt_start_time > THRESHOLD_TIME) {
                gpioWrite(ALARM_PIN, HIGH);
                log_event("Threshold exceeded");
            }
        } else {
            if (sensor1_state || sensor2_state) {
                log_event("Tilt ended");
            }
            sensor1_state = 0;
            sensor2_state = 0;
        }

        gpioDelay(CHECK_INTERVAL);
    }

    return EXIT_SUCCESS;
}

