#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>

#define SENSOR_ADDR 0x1D
#define CTRL1_REG 0x1F
#define ACCEL_REG 0x28
#define I2C_BUS 1
#define LED_PIN 17
#define THRESHOLD 500
#define RETRY_LIMIT 3
#define POLL_INTERVAL_MS 100

static FILE *log_file;

void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int i2c_read_retry(int handle, uint8_t reg, uint8_t *data, int len) {
    int retries = 0;
    while (retries < RETRY_LIMIT) {
        if (i2cReadI2CBlock(handle, reg, data, len) == len) {
            return 0;
        }
        retries++;
        gpioSleep(MILLISECONDS, 10, 0);
    }
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("seismic_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t ctrl1;
    if (i2c_read_retry(i2c_handle, CTRL1_REG, &ctrl1, 1) != 0) {
        fprintf(stderr, "Failed to read CTRL1 register\n");
        cleanup(0);
    }

    ctrl1 &= ~0x20; // Clear power-down bit
    if (i2cWriteByteData(i2c_handle, CTRL1_REG, ctrl1) != 0) {
        fprintf(stderr, "Failed to write CTRL1 register\n");
        cleanup(0);
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    uint8_t accel_data[6];
    int16_t x, y, z;
    double magnitude;
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    while (1) {
        if (i2c_read_retry(i2c_handle, ACCEL_REG, accel_data, 6) != 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue;
        }

        x = (int16_t)(accel_data[1] << 8 | accel_data[0]);
        y = (int16_t)(accel_data[3] << 8 | accel_data[2]);
        z = (int16_t)(accel_data[5] << 8 | accel_data[4]);

        magnitude = sqrt(x * x + y * y + z * z);

        if (magnitude > THRESHOLD) {
            gpioWrite(LED_PIN, 1);
            sleep(1);
            gpioWrite(LED_PIN, 0);

            time(&now);
            tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

            fprintf(log_file, "%s, %.2f\n", timestamp, magnitude);
            fflush(log_file);
        }

        gpioSleep(MILLISECONDS, POLL_INTERVAL_MS, 0);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

