#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>

#define NUM_SENSORS 4
#define SENSOR_PINS[NUM_SENSORS] = {4, 17, 27, 22}
#define LED_PIN 18
#define POLL_INTERVAL_US 50000

static struct gpiod_chip *chip;
static struct gpiod_line *sensors[NUM_SENSORS];
static struct gpiod_line *led;

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int signum) {
    keep_running = 0;
}

static int init_gpio() {
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        sensors[i] = gpiod_chip_get_line(chip, SENSOR_PINS[i]);
        if (!sensors[i]) {
            fprintf(stderr, "Failed to get line for sensor %d: %s\n", i, strerror(errno));
            goto error;
        }

        ret = gpiod_line_request_input(sensors[i], "obstacle_sensor");
        if (ret < 0) {
            fprintf(stderr, "Failed to request input for sensor %d: %s\n", i, strerror(errno));
            goto error;
        }
    }

    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "Failed to get line for LED: %s\n", strerror(errno));
        goto error;
    }

    ret = gpiod_line_request_output(led, "obstacle_led", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request output for LED: %s\n", strerror(errno));
        goto error;
    }

    return 0;

error:
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensors[i]) {
            gpiod_line_release(sensors[i]);
        }
    }
    if (led) {
        gpiod_line_release(led);
    }
    gpiod_chip_close(chip);
    return -1;
}

static void cleanup_gpio() {
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensors[i]) {
            gpiod_line_release(sensors[i]);
        }
    }
    if (led) {
        gpiod_line_release(led);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct timespec sleep_time = {0, POLL_INTERVAL_US * 1000};

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        int any_object_detected = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int value = gpiod_line_get_value(sensors[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to read sensor %d: %s\n", i, strerror(errno));
                keep_running = 0;
                break;
            }
            if (value == 0) {  // Active-low: 0 means object detected
                any_object_detected = 1;
                break;
            }
        }

        int led_value = any_object_detected ? 1 : 0;
        int ret = gpiod_line_set_value(led, led_value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
            keep_running = 0;
        }

        nanosleep(&sleep_time, NULL);
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

