#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>

#define NUM_SENSORS 5
#define DEBOUNCE_TIME_MS 50
#define LOG_FILE "/var/log/flame_events.log"

struct sensor {
    int gpio;
    struct gpiod_line *line;
};

struct sensor sensors[NUM_SENSORS] = {
    {2, NULL},
    {3, NULL},
    {4, NULL},
    {17, NULL},
    {27, NULL}
};

volatile sig_atomic_t terminate = 0;

void sig_handler(int signum) {
    terminate = 1;
}

void cleanup(struct gpiod_chip *chip) {
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensors[i].line) {
            gpiod_line_release(sensors[i].line);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
}

int main() {
    struct gpiod_chip *chip;
    FILE *log_file;
    struct timespec ts;
    int ret;

    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Flame monitor started");

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        cleanup(chip);
        return EXIT_FAILURE;
    }

    if (flock(fileno(log_file), LOCK_EX) != 0) {
        syslog(LOG_ERR, "Failed to lock log file: %s", strerror(errno));
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    for (int i = 0; i < NUM_SENSORS; i++) {
        sensors[i].line = gpiod_chip_get_line(chip, sensors[i].gpio);
        if (!sensors[i].line) {
            syslog(LOG_ERR, "Failed to get line for GPIO %d: %s", sensors[i].gpio, strerror(errno));
            cleanup(chip);
            fclose(log_file);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_input(sensors[i].line, "flame_sensor");
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to request line for GPIO %d: %s", sensors[i].gpio, strerror(errno));
            cleanup(chip);
            fclose(log_file);
            return EXIT_FAILURE;
        }
    }

    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int value = gpiod_line_get_value(sensors[i].line);
            if (value < 0) {
                syslog(LOG_ERR, "Failed to read value from GPIO %d: %s", sensors[i].gpio, strerror(errno));
                continue;
            }

            if (value == 0) {  // Flame detected
                usleep(DEBOUNCE_TIME_MS * 1000);
                int debounced_value = gpiod_line_get_value(sensors[i].line);
                if (debounced_value < 0) {
                    syslog(LOG_ERR, "Failed to read debounced value from GPIO %d: %s", sensors[i].gpio, strerror(errno));
                    continue;
                }

                if (debounced_value == 0) {
                    time_t now = time(NULL);
                    char timestamp[64];
                    struct tm tm_info;
                    gmtime_r(&now, &tm_info);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_info);

                    fprintf(log_file, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n",
                            timestamp, i + 1, sensors[i].gpio);
                    fflush(log_file);
                }
            }
        }

        ts.tv_sec = 1;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    fclose(log_file);
    cleanup(chip);
    syslog(LOG_INFO, "Flame monitor stopped");
    closelog();
    return EXIT_SUCCESS;
}

