#define NUM_TOUCH_SENSORS 8
#define POLL_INTERVAL_MS 50

const int gpio_pins[NUM_TOUCH_SENSORS] = {5, 6, 13, 19, 26, 12, 16, 20};
volatile sig_atomic_t keep_running = 1;

