#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x10
#define ALS_CONFIG_REG 0x00
#define ALS_DATA_REG 0x04
#define LED_GPIO 18
#define PWM_FREQ 1000
#define LOG_FILE "grow_log.txt"

static FILE *log_file;
static int i2c_handle;

void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioHardwarePWM(LED_GPIO, PWM_FREQ, 0);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        cleanup(0);
        return EXIT_FAILURE;
    }

    // Configure ALS
    uint16_t config = 0x0000; // ALS gain 1/8, ALS integration time 100ms
    if (i2cWriteWordData(i2c_handle, ALS_CONFIG_REG, config) < 0) {
        fprintf(stderr, "Failed to configure ALS: %s\n", strerror(errno));
        cleanup(0);
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioHardwarePWM(LED_GPIO, PWM_FREQ, 0);

    time_t last_log_time = 0;
    while (1) {
        time_t current_time = time(NULL);
        if (current_time - last_log_time >= 1) {
            last_log_time = current_time;

            int raw = i2cReadWordData(i2c_handle, ALS_DATA_REG);
            if (raw < 0) {
                fprintf(stderr, "Failed to read ALS data: %s\n", strerror(errno));
                cleanup(0);
                return EXIT_FAILURE;
            }

            float lux = raw * 0.0576;
            int brightness;
            if (lux < 100) {
                brightness = 1000000; // 100%
            } else if (lux < 500) {
                brightness = 750000;  // 75%
            } else if (lux < 1000) {
                brightness = 500000;  // 50%
            } else {
                brightness = 250000;  // 25%
            }

            gpioPWM(LED_GPIO, brightness);

            struct tm *tm_info = localtime(&current_time);
            char timestamp[26];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

            fprintf(log_file, "%s %.2f %d 0\n", timestamp, lux, brightness);
            fflush(log_file);
        }
        gpioSleep(PI_TIME_RELATIVE, 0, 100000); // Sleep for 100ms
    }

    return EXIT_SUCCESS;
}

