#define NUM_CHANNELS 8
#define TOUCH_LOG_FILE "touch_log.txt"
#define DEBOUNCE_TIME_MS 50

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_touch(int channel) {
    FILE *file = fopen(TOUCH_LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t now;
    time(&now);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s - Channel %d Touched\n", timestamp, channel);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    for (int i = 2; i < 10; i++) {
        gpioSetMode(i, PI_INPUT);
        gpioSetPullUpDown(i, PI_PUD_DOWN);
    }

    gpioSetMode(17, PI_OUTPUT);
    gpioWrite(17, 0);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state[NUM_CHANNELS] = {0};
    int current_state[NUM_CHANNELS] = {0};

    while (keep_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            current_state[i] = gpioRead(i + 2);
            if (current_state[i] == 1 && last_state[i] == 0) {
                log_touch(i + 1);
                gpioWrite(17, 1);
            }
        }

        int all_released = 1;
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (current_state[i] == 1) {
                all_released = 0;
                break;
            }
        }

        if (all_released) {
            gpioWrite(17, 0);
        }

        memcpy(last_state, current_state, sizeof(current_state));
        gpioSleep(PI_TIME_MILLISECONDS, DEBOUNCE_TIME_MS, 0);
    }

    gpioWrite(17, 0);
    gpioTerminate();
    return 0;
}

