#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_WORD 0xC810
#define I2C_BUS 1
#define LOG_FILE "light_data.txt"
#define CONVERSION_DELAY 100
#define READ_INTERVAL 1000

static int i2cHandle;
static FILE *logFile;

void sigintHandler(int signo) {
    if (i2cHandle >= 0) {
        i2cClose(i2cHandle);
    }
    if (logFile) {
        fflush(logFile);
        fclose(logFile);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

uint16_t swapEndian(uint16_t val) {
    return ((val & 0xFF) << 8) | ((val >> 8) & 0xFF);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    i2cHandle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    logFile = fopen(LOG_FILE, "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigintHandler);

    if (i2cWriteWordData(i2cHandle, CONFIG_REG, swapEndian(CONFIG_WORD)) < 0) {
        fprintf(stderr, "Failed to write configuration to OPT3001\n");
        sigintHandler(SIGINT);
    }

    time_t lastReadTime = time(NULL) - READ_INTERVAL;

    while (1) {
        time_t currentTime = time(NULL);
        if (currentTime - lastReadTime >= READ_INTERVAL / 1000) {
            uint16_t result;
            if (i2cReadWordData(i2cHandle, RESULT_REG, &result) < 0) {
                fprintf(stderr, "Failed to read result from OPT3001\n");
            } else {
                result = swapEndian(result);
                uint16_t exponent = (result >> 12) & 0xF;
                uint16_t mantissa = result & 0x0FFF;
                double lux = mantissa * 0.01 * (1 << exponent);

                time_t rawTime;
                struct tm *timeInfo;
                char timeBuffer[80];

                time(&rawTime);
                timeInfo = localtime(&rawTime);
                strftime(timeBuffer, sizeof(timeBuffer), "%Y-%m-%d %H:%M:%S", timeInfo);

                fprintf(logFile, "%s, %.2f\n", timeBuffer, lux);
                fflush(logFile);
                printf("%.2f\n", lux);

                lastReadTime = currentTime;
            }
            time_sleep(CONVERSION_DELAY / 1000);
        }
        time_sleep(1);
    }

    return EXIT_SUCCESS;
}

