#include <time.h>
#include <signal.h>
#include <unistd.h>

#define FLAME_SENSOR_PIN 4
#define ALERT_PIN 17
#define POLL_INTERVAL_MS 500

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_event(const char *message) {
    FILE *log_file = fopen("fire_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0';  // Remove newline

    fprintf(log_file, "[%s] %s\n", time_str, message);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    signal(SIGINT, signal_handler);

    log_event("Flame sensor monitoring started");

    while (keep_running) {
        int flame_detected = gpioRead(FLAME_SENSOR_PIN);

        if (flame_detected < 0) {
            log_event("Error reading flame sensor");
        } else if (flame_detected == 0) {
            log_event("Flame detected!");
            gpioWrite(ALERT_PIN, 1);
            time_sleep(1);
            gpioWrite(ALERT_PIN, 0);
        }

        gpioSleep(Time_release_time, 0, POLL_INTERVAL_MS * 1000);
    }

    log_event("Flame sensor monitoring stopped");

    gpioTerminate();
    return 0;
}

