            if (last_state == -1 || (current_time.tv_sec - debounce_time.tv_sec) * 1000 +
                                    (current_time.tv_nsec - debounce_time.tv_nsec) / 1000000 >= DEBOUNCE_INTERVAL_MS) {
                log_event(current_state ? "Touch Detected" : "Touch Released");
