#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define SENSOR_ADDRESS 0x08
#define I2C_BUS 1
#define SAMPLE_INTERVAL_MS 1000
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define RAW_TO_ML_MIN_RATIO 90.0
#define MIN_FLOW_RATE 0.0
#define MAX_FLOW_RATE 100.0

static FILE *log_file = NULL;
static int i2c_handle = -1;

void cleanup(int sig) {
    if (i2c_handle >= 0) {
        gpI2CClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpTerminate();
    exit(EXIT_SUCCESS);
}

uint8_t calculate_crc8(const uint8_t *data, int length) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    i2c_handle = gpI2COpen(I2C_BUS, SENSOR_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        cleanup(0);
    }

    uint8_t start_cmd[] = {0x36, 0x08};
    if (gpI2CWriteDevice(i2c_handle, start_cmd, sizeof(start_cmd)) < 0) {
        fprintf(stderr, "Failed to send start command\n");
        cleanup(0);
    }

    gpSleep(2000);  // 2 ms delay

    log_file = fopen("cooling_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup(0);
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }

    time_t last_sample_time = time(NULL);

    while (1) {
        uint8_t read_buffer[3];
        if (gpI2CReadI2CBlock(i2c_handle, 0, read_buffer, sizeof(read_buffer)) != sizeof(read_buffer)) {
            fprintf(stderr, "I2C read error\n");
            gpI2CClose(i2c_handle);
            i2c_handle = gpI2COpen(I2C_BUS, SENSOR_ADDRESS);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C device: %s\n", strerror(errno));
                cleanup(0);
            }
            fprintf(log_file, "%ld,ERROR,ERROR\n", (long)time(NULL));
            fflush(log_file);
            continue;
        }

        uint16_t raw_value = (read_buffer[0] << 8) | read_buffer[1];
        uint8_t crc = read_buffer[2];

        if (calculate_crc8(read_buffer, 2) != crc) {
            fprintf(stderr, "CRC check failed\n");
            fprintf(log_file, "%ld,ERROR,ERROR\n", (long)time(NULL));
        } else {
            float flow_rate = (float)raw_value / RAW_TO_ML_MIN_RATIO;
            const char *status = "OK";
            if (flow_rate < MIN_FLOW_RATE || flow_rate > MAX_FLOW_RATE) {
                status = "INVALID";
            }
            fprintf(log_file, "%ld,%.2f,%s\n", (long)time(NULL), flow_rate, status);
        }

        fflush(log_file);

        time_t current_time = time(NULL);
        if (difftime(current_time, last_sample_time) < SAMPLE_INTERVAL_MS / 1000.0) {
            gpSleep((SAMPLE_INTERVAL_MS - difftime(current_time, last_sample_time) * 1000) * 1000);
        }
        last_sample_time = time(NULL);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

