#include <gpiod.h>

#define LEFT_PIN 17
#define MIDDLE_PIN 27
#define RIGHT_PIN 22
#define CHIP_NAME "gpiochip0"
#define LOG_FILE_NAME "path_log.csv"
#define POLL_INTERVAL_MS 50

static struct gpiod_chip *chip;
static struct gpiod_line *lines[3];
static FILE *log_file;

void cleanup(int signum) {
    (void)signum; // Suppress unused parameter warning
    printf("Cleaning up...\n");

    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }

    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec poll_interval = { .tv_sec = 0, .tv_nsec = POLL_INTERVAL_MS * 1000000 };
    struct timespec wait_interval = { .tv_sec = 0, .tv_nsec = 1000000 }; // 1ms wait for signal

    // Open GPIO chip
    chip = gpiod_chip_open(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Request lines as input
    for (int i = 0; i < 3; i++) {
        unsigned int offset = (i == 0) ? LEFT_PIN : (i == 1) ? MIDDLE_PIN : RIGHT_PIN;
        lines[i] = gpiod_chip_get_line(chip, offset);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %u: %s\n", offset, strerror(errno));
            cleanup(0);
            return EXIT_FAILURE;
        }

        int ret = gpiod_line_request_input(lines[i], "obstacle_sensor");
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %u as input: %s\n", offset, strerror(errno));
            cleanup(0);
            return EXIT_FAILURE;
        }
    }

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup(0);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        cleanup(0);
        return EXIT_FAILURE;
    }

    // Main loop
    while (true) {
        int values[3];
        for (int i = 0; i < 3; i++) {
            values[i] = gpiod_line_get_value(lines[i]);
            if (values[i] < 0) {
                fprintf(stderr, "Error reading line %u: %s\n", i, strerror(errno));
                cleanup(0);
                return EXIT_FAILURE;
            }
        }

        time_t now;
        struct tm *tm_info;
        char timestamp[64];

        time(&now);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, values[0], values[1], values[2]);
        fflush(log_file);

        nanosleep(&poll_interval, &wait_interval);
    }

    return EXIT_SUCCESS;
}

