#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define POLL_INTERVAL_MS 500
#define BUZZER_DURATION_MS 2000
#define SHUTDOWN_SLEEP_MS 100

static volatile sig_atomic_t shutdown_flag = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_sensor_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_file = NULL;

void signal_handler(int signum) {
    shutdown_flag = 1;
}

void log_event(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] %s\n", time_str, message);
    fflush(log_file);
}

void cleanup() {
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (flame_sensor_line) {
        gpiod_line_release(flame_sensor_line);
        flame_sensor_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        log_event("System stopped");
        fclose(log_file);
        log_file = NULL;
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        fprintf(stderr, "Failed to get line for flame sensor: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get line for buzzer: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request input for flame sensor: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request output for buzzer: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("alert_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("System started");

    int last_flame_state = 1; // Assume no flame initially
    struct timespec sleep_time = {0, SHUTDOWN_SLEEP_MS * 1000000};

    while (!shutdown_flag) {
        int flame_state = gpiod_line_get_value(flame_sensor_line);
        if (flame_state < 0) {
            fprintf(stderr, "Failed to read flame sensor: %s\n", strerror(errno));
            break;
        }

        if (flame_state == 0 && last_flame_state == 1) {
            log_event("Flame detected!");
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                fprintf(stderr, "Failed to activate buzzer: %s\n", strerror(errno));
            }

            struct timespec buzzer_on_time = {0, BUZZER_DURATION_MS * 1000000};
            nanosleep(&buzzer_on_time, NULL);

            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                fprintf(stderr, "Failed to deactivate buzzer: %s\n", strerror(errno));
            }
        }

        last_flame_state = flame_state;
        nanosleep(&sleep_time, NULL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

