#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define TTP223B_PIN 4
#define LED_PIN 17
#define DEBOUNCE_TIME 200

static FILE *log_file;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_touch() {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Warning: Failed to write to log file\n");
    }
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TTP223B_PIN, PI_INPUT);
    gpioSetPullUpDown(TTP223B_PIN, PI_PUD_UP);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to set up signal handler\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_state = gpioRead(TTP223B_PIN);
    uint32_t last_change_time = gpioTick();

    while (keep_running) {
        int current_state = gpioRead(TTP223B_PIN);
        uint32_t current_time = gpioTick();

        if (current_state != last_state && 
            (current_time - last_change_time) > DEBOUNCE_TIME) {
            if (current_state == PI_LOW) {  // Rising edge
                gpioWrite(LED_PIN, !gpioRead(LED_PIN));
                log_touch();
            }
            last_change_time = current_time;
        }

        last_state = current_state;
        gpioDelay(10000);  // 10 ms delay
    }

    gpioWrite(LED_PIN, PI_LOW);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

