int sensor_pins[SENSOR_COUNT] = {4, 17, 27};
int sensor_states[SENSOR_COUNT] = {0};
FILE *log_file = NULL;

void signal_handler(int signo) {
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

void log_state_change(int sensor_index, int new_state) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s Sensor %d: %s\n", timestamp, sensor_index, new_state ? "Magnet removed" : "Magnet present");
    fflush(log_file);
}

