    for (int i = 0; i < SENSOR_COUNT; i++) {
        int state = gpioRead(sensor_pins[i]);
        if (state < 0) {
            fprintf(stderr, "Error reading sensor %d\n", i);
            continue;
        }
        sensor_states[i] = state;
        log_state_change(i, state);
    }

    // Main loop
    while (1) {
        for (int i = 0; i < SENSOR_COUNT; i++) {
            int state = gpioRead(sensor_pins[i]);
            if (state < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
                continue;
            }
            if (state != sensor_states[i]) {
                sensor_states[i] = state;
                log_state_change(i, state);
            }
        }
        gpioDelay(POLL_INTERVAL);
    }

