#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x4A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define LED_CURRENT_REG 0x3F
#define AVERAGING_REG 0x04
#define ENABLE_REG 0x01
#define HEART_RATE_REG 0x2A

#define SAMPLES 5
#define MIN_BPM 30
#define MAX_BPM 220

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("heart_rate.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    uint8_t part_id, hw_rev;
    if (i2cReadByteData(i2c_handle, PART_ID_REG, &part_id) < 0 || part_id != 0x02) {
        fprintf(stderr, "Invalid PART_ID\n");
        goto cleanup;
    }
    if (i2cReadByteData(i2c_handle, HW_REV_REG, &hw_rev) < 0 || hw_rev != 0x01) {
        fprintf(stderr, "Invalid HW_REV\n");
        goto cleanup;
    }

    if (i2cWriteByteData(i2c_handle, LED_CURRENT_REG, 0x3F) < 0 ||
        i2cWriteByteData(i2c_handle, AVERAGING_REG, 0x04) < 0 ||
        i2cWriteByteData(i2c_handle, ENABLE_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        goto cleanup;
    }

    int16_t heart_rate_samples[SAMPLES] = {0};
    int sample_index = 0;

    while (keep_running) {
        int16_t raw_hr;
        if (i2cReadWordData(i2c_handle, HEART_RATE_REG, &raw_hr) < 0) {
            fprintf(stderr, "Failed to read heart rate\n");
            sleep(1);
            continue;
        }

        float bpm = raw_hr * 0.5;
        if (bpm < MIN_BPM || bpm > MAX_BPM) {
            fprintf(stderr, "Invalid BPM: %.2f\n", bpm);
            continue;
        }

        heart_rate_samples[sample_index] = (int16_t)bpm;
        sample_index = (sample_index + 1) % SAMPLES;

        int64_t sum = 0;
        for (int i = 0; i < SAMPLES; i++) {
            sum += heart_rate_samples[i];
        }
        float filtered_bpm = (float)sum / SAMPLES;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.2f\n", timestamp, filtered_bpm);
        fflush(log_file);

        sleep(1);
    }

cleanup:
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

