#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "flame_log.txt"
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

void signal_handler(int signum) {
    printf("Shutting down...\n");
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    struct timespec poll_interval = {0, POLL_INTERVAL_MS * 1000000};
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "flame_sensor", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring flame sensor...\n");

    while (1) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line value\n");
            break;
        }

        if (value == 0) {  // LOW, falling edge detected
            printf("FLAME DETECTED\n");
            time_t now = time(NULL);
            char *timestamp = ctime(&now);
            timestamp[strlen(timestamp) - 1] = '\0';  // Remove newline
            fprintf(log_file, "%s - FLAME DETECTED\n", timestamp);
            fflush(log_file);
        }

        nanosleep(&poll_interval, NULL);
    }

    cleanup();
    return EXIT_FAILURE;
}

