#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

#define NUM_CHANNELS 8
#define COUNTER_PIN_START 17
#define TTP226_PIN_START 5
#define POLL_INTERVAL_US 10000
#define STABILIZATION_DELAY_MS 200

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_touch(int channel, int counter, FILE *log_file) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    if (log_file) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
    }
    printf("Touch on channel %d | Counter: %d\n", channel, counter);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_CHANNELS];
    struct gpiod_line *counter_lines[NUM_CHANNELS];
    struct gpiod_line_bulk request_lines;
    struct gpiod_line_bulk request_counter_lines;
    int values[NUM_CHANNELS] = {0};
    int counter = 0;
    FILE *log_file = NULL;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, TTP226_PIN_START + i);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", TTP226_PIN_START + i, strerror(errno));
            goto cleanup;
        }

        counter_lines[i] = gpiod_chip_get_line(chip, COUNTER_PIN_START + i);
        if (!counter_lines[i]) {
            fprintf(stderr, "Error getting counter line %d: %s\n", COUNTER_PIN_START + i, strerror(errno));
            goto cleanup;
        }
    }

    gpiod_line_bulk_init(&request_lines);
    gpiod_line_bulk_init(&request_counter_lines);

    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_bulk_add(&request_lines, lines[i]);
        gpiod_line_bulk_add(&request_counter_lines, counter_lines[i]);
    }

    if (gpiod_line_request_input_bulk(&request_lines, "touch_sensor") < 0) {
        fprintf(stderr, "Error requesting input lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output_bulk(&request_counter_lines, "counter_display", 0) < 0) {
        fprintf(stderr, "Error requesting output lines: %s\n", strerror(errno));
        goto cleanup;
    }

    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Warning: Could not open log file. Logging to stdout only.\n");
    }

    usleep(STABILIZATION_DELAY_MS * 1000);

    while (keep_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int new_value;
            if (gpiod_line_get_value(lines[i]) < 0) {
                fprintf(stderr, "Error reading channel %d: %s\n", i + 1, strerror(errno));
                continue;
            }
            new_value = gpiod_line_get_value(lines[i]);
            if (new_value == 0 && values[i] == 1) {
                counter = (counter + 1) % 256;
                log_touch(i + 1, counter, log_file);
                for (int j = 0; j < NUM_CHANNELS; j++) {
                    int bit = (counter >> j) & 1;
                    if (gpiod_line_set_value(counter_lines[j], bit) < 0) {
                        fprintf(stderr, "Error setting counter line %d: %s\n", COUNTER_PIN_START + j, strerror(errno));
                    }
                }
            }
            values[i] = new_value;
        }
        usleep(POLL_INTERVAL_US);
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
        if (counter_lines[i]) {
            gpiod_line_release(counter_lines[i]);
        }
    }
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

