        goto cleanup;
    }

    if (gpiod_line_request_output_bulk(&request_counter_lines, "counter_display", 0) < 0) {
        fprintf(stderr, "Error requesting output lines: %s\n", strerror(errno));
        goto cleanup;
    }

    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Warning: Could not open log file. Logging to stdout only.\n");
    }

    usleep(STABILIZATION_DELAY_MS * 1000);

    while (keep_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int new_value;
            if (gpiod_line_get_value(lines[i]) < 0) {
                fprintf(stderr, "Error reading channel %d: %s\n", i + 1, strerror(errno));
                continue;
            }
            new_value = gpiod_line_get_value(lines[i]);
            if (new_value == 0 && values[i] == 1) {
                counter = (counter + 1) % 256;
                log_touch(i + 1, counter, log_file);
                for (int j = 0; j < NUM_CHANNELS; j++) {
                    int bit = (counter >> j) & 1;
                    if (gpiod_line_set_value(counter_lines[j], bit) < 0) {
                        fprintf(stderr, "Error setting counter line %d: %s\n", COUNTER_PIN_START + j, strerror(errno));
                    }
                }
            }
            values[i] = new_value;
        }
        usleep(POLL_INTERVAL_US);
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
        if (counter_lines[i]) {
            gpiod_line_release(counter_lines[i]);
        }
    }
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}
