        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO17);
    line18 = gpiod_chip_get_line(chip, GPIO18);

    if (!line17 || !line18) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        cleanup(0);
    }

    struct gpiod_line_request_config config = {
        .consumer = "tilt_sensor_monitor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW,
    };

    if (gpiod_line_request(line17, &config, 0) < 0 || gpiod_line_request(line18, &config, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(errno));
        cleanup(0);
    }

    log_file = fopen("/var/log/tilt_events.log", "a");
