    struct timespec poll_interval = {0, POLL_INTERVAL_MS * 1000000};
    struct timespec debounce_interval = {0, DEBOUNCE_TIME_MS * 1000000};

    while (1) {
        int state17 = gpiod_line_get_value(line17);
        int state18 = gpiod_line_get_value(line18);

        if (state17 < 0 || state18 < 0) {
            fprintf(stderr, "Failed to read GPIO lines: %s\n", strerror(errno));
            continue;
        }

        if (state17 == 0 && last_state17 == 1) {
            nanosleep(&debounce_interval, NULL);
            state17 = gpiod_line_get_value(line17);
            if (state17 == 0) {
                log_event(1);
            }
        }

        if (state18 == 0 && last_state18 == 1) {
            nanosleep(&debounce_interval, NULL);
            state18 = gpiod_line_get_value(line18);
            if (state18 == 0) {
                log_event(2);
            }
        }

        last_state17 = state17;
        last_state18 = state18;

        nanosleep(&poll_interval, NULL);
    }

    return EXIT_SUCCESS;
}

