#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>

#define MIC_PIN 4
#define LED_PIN 17
#define SAMPLE_INTERVAL_US 125
#define LED_DURATION_MS 100

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        keep_running = 0;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) < 0 || gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct timespec ts;
    long long last_sample_time = 0;

    while (keep_running) {
        int level = gpioRead(MIC_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed: %s\n", strerror(errno));
            break;
        }

        long long current_time;
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
            fprintf(stderr, "Error: clock_gettime failed\n");
            break;
        }
        current_time = ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;

        if (level == PI_HIGH && (current_time - last_sample_time) >= SAMPLE_INTERVAL_US / 2) {
            printf("%lld\n", current_time);

            if (gpioWrite(LED_PIN, PI_HIGH) < 0) {
