#define LOG_INTERVAL_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *lines[3];
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void cleanup() {
    if (lines[0]) gpiod_line_release(lines[0]);
    if (lines[1]) gpiod_line_release(lines[1]);
    if (lines[2]) gpiod_line_release(lines[2]);
    if (chip) gpiod_chip_close(chip);
}

int main() {
    struct gpiod_line_request_config config = {
        .consumer = "3-Way Tracing Sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW | GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
    };

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open(CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        int pin = (i == 0) ? LEFT_PIN : (i == 1) ? CENTER_PIN : RIGHT_PIN;
        lines[i] = gpiod_chip_get_line(chip, pin);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d: %s\n", pin, strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        int ret = gpiod_line_request(lines[i], &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line for GPIO %d: %s\n", pin, strerror(-ret));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    while (keep_running) {
        int values[3];
        for (int i = 0; i < 3; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to read value from GPIO %d: %s\n", 
                        (i == 0) ? LEFT_PIN : (i == 1) ? CENTER_PIN : RIGHT_PIN, 
                        strerror(-value));
                cleanup();
                return EXIT_FAILURE;
            }
            values[i] = value;
        }

        printf("Left: %d, Center: %d, Right: %d\n", values[0], values[1], values[2]);
        usleep(LOG_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

