#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x49
#define ALS_VISIBLE_LSB 0x24
#define ALS_VISIBLE_MSB 0x25
#define I2C_SLAVE_FORCE 0x0706
#define SLEEP_INTERVAL_MS 100

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int i2c_fd;
    uint16_t als_value;
    struct i2c_msg messages[2];
    __u8 write_buf[1], read_buf[2];
    struct timespec sleep_time;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SI1175_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Reading ALS visible data from Si1175 sensor...\n");

    while (keep_running) {
        // Prepare messages for reading ALS LSB and MSB
        write_buf[0] = ALS_VISIBLE_LSB;
        messages[0].addr = SI1175_ADDR;
        messages[0].flags = 0;
        messages[0].len = 1;
        messages[0].buf = write_buf;

        messages[1].addr = SI1175_ADDR;
        messages[1].flags = I2C_M_RD;
        messages[1].len = 2;
        messages[1].buf = read_buf;

        // Transfer messages
        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            perror("Failed to read ALS data");
            break;
        }

        // Combine LSB and MSB into a 16-bit value
        als_value = (read_buf[1] << 8) | read_buf[0];

        // Log the raw sensor value
        printf("ALS Visible: 0x%04X\n", als_value);

        // Sleep for the specified interval
        sleep_time.tv_sec = SLEEP_INTERVAL_MS / 1000;
        sleep_time.tv_nsec = (SLEEP_INTERVAL_MS % 1000) * 1000000;
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    close(i2c_fd);
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

