#include <errno.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

const int gpio_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[NUM_CHANNELS] = {NULL};

void cleanup(int signum) {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d: %s\n", gpio_pins[i], strerror(errno));
            cleanup(0);
        }

        int ret = gpiod_line_request_input(lines[i], "TTP226");
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %d as input: %s\n", gpio_pins[i], strerror(errno));
            cleanup(0);
        }
    }

    struct timespec start, current;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        nanosleep(&(struct timespec){0, POLL_INTERVAL_MS * 1000000}, NULL);

        printf("[");
        clock_gettime(CLOCK_MONOTONIC, &current);
        double elapsed = (current.tv_sec - start.tv_sec) + (current.tv_nsec - start.tv_nsec) / 1e9;
        printf("%.3fs] ", elapsed);

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to read value from line %d: %s\n", gpio_pins[i], strerror(errno));
                cleanup(0);
            }
            printf("CH%d=%d ", i + 1, value);
        }
        printf("\n");
    }

    return EXIT_SUCCESS;
}

