#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27
#define FADE_STEPS 50
#define FADE_DELAY_MS 100
#define PWM_FREQUENCY 1000

volatile sig_atomic_t keep_running = 1;

void sigint_handler(int signum) {
    keep_running = 0;
}

void set_rgb(int red, int green, int blue) {
    gpioPWM(RED_PIN, 255 - red);
    gpioPWM(GREEN_PIN, 255 - green);
    gpioPWM(BLUE_PIN, 255 - blue);
}

void hue_to_rgb(float hue, int *r, int *g, int *b) {
    float c = 1.0;
    float x = c * (1 - fabs(fmod(hue / 60.0, 2) - 1));
    float m = 0.0;

    if (hue >= 0 && hue < 60) {
        c = 1.0; x = 0.0;
    } else if (hue >= 60 && hue < 120) {
        c = 1.0; m = x; x = 0.0;
    } else if (hue >= 120 && hue < 180) {
        c = x; x = 0.0;
    } else if (hue >= 180 && hue < 240) {
        c = x; m = 0.0; x = 0.0;
    } else if (hue >= 240 && hue < 300) {
        c = 1.0; x = 0.0; m = x;
    } else if (hue >= 300 && hue < 360) {
        c = 1.0; m = 0.0;
    }

    *r = (int)((c + m) * 255);
    *g = (int)((x + m) * 255);
    *b = (int)((0.0 + m) * 255);
}

int main() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode");
        gpioTerminate();
        return 1;
    }

    if (gpioHardwarePWM(RED_PIN, PWM_FREQUENCY, 0) < 0 ||
        gpioHardwarePWM(GREEN_PIN, PWM_FREQUENCY, 0) < 0 ||
        gpioHardwarePWM(BLUE_PIN, PWM_FREQUENCY, 0) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        gpioTerminate();
        return 1;
    }

    srand(time(NULL));
    FILE *urandom = fopen("/dev/urandom", "r");
    if (urandom == NULL) {
        syslog(LOG_ERR, "Failed to open /dev/urandom: %s", strerror(errno));
        gpioTerminate();
        return 1;
    }

    unsigned int seed;
    if (fread(&seed, sizeof(seed), 1, urandom) != 1) {
        syslog(LOG_ERR, "Failed to read from /dev/urandom");
        fclose(urandom);
        gpioTerminate();
        return 1;
    }
    fclose(urandom);
    srand(seed);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    int r, g, b;
    int r1, g1, b1;
    float hue = (float)rand() / RAND_MAX * 360.0;

    while (keep_running) {
        hue_to_rgb(hue, &r1, &g1, &b1);
        hue = (float)rand() / RAND_MAX * 360.0;
        hue_to_rgb(hue, &r, &g, &b);

        for (int step = 0; step < FADE_STEPS; step++) {
            int r_fade = r1 + (r - r1) * step / FADE_STEPS;
            int g_fade = g1 + (g - g1) * step / FADE_STEPS;
            int b_fade = b1 + (b - b1) * step / FADE_STEPS;

            set_rgb(r_fade, g_fade, b_fade);
            time_sleep(FADE_DELAY_MS / 1000.0);
        }
    }

    set_rgb(0, 0, 0);
    gpioTerminate();
    closelog();
    return 0;
}

