#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ID 0x12
#define TCS34725_ID_VALUE 0x44
#define TCS34725_POWER 0x00
#define TCS34725_CONTROL 0x0F
#define TCS34725_ATIME 0x01
#define TCS34725_CDATAL 0x14
#define TCS34725_RDATAL 0x16
#define TCS34725_GDATAL 0x18
#define TCS34725_BDATAL 0x1A
#define TCS34725_PON 0x01
#define TCS34725_AEN 0x02
#define TCS34725_ATIME_VALUE 0xEB // ~154ms
#define TCS34725_GAIN 0x00 // 1x
#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define RED_THRESHOLD 200

int i2c_fd;
struct gpiod_line *led_line;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    exit(EXIT_SUCCESS);
}

int write_i2c_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int read_i2c_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write_i2c_reg(fd, reg, 0) != 2) {
        return -1;
    }
    return read(fd, value, 1);
}

int read_i2c_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (read_i2c_reg(fd, reg, &buf[0]) != 1 || read_i2c_reg(fd, reg + 1, &buf[1]) != 1) {
        return -1;
    }
    *value = (buf[1] << 8) | buf[0];
    return 0;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, TCS34725_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t id;
    if (read_i2c_reg(i2c_fd, TCS34725_COMMAND_BIT | TCS34725_ID, &id) != 1 || id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Failed to verify sensor ID\n");
        cleanup(0);
    }

    if (write_i2c_reg(i2c_fd, TCS34725_COMMAND_BIT | TCS34725_POWER, TCS34725_PON) != 2 ||
        write_i2c_reg(i2c_fd, TCS34725_COMMAND_BIT | TCS34725_ATIME, TCS34725_ATIME_VALUE) != 2 ||
        write_i2c_reg(i2c_fd, TCS34725_COMMAND_BIT | TCS34725_CONTROL, TCS34725_GAIN) != 2) {
        fprintf(stderr, "Failed to configure sensor\n");
        cleanup(0);
    }

    usleep(200000); // Wait for sensor to power up

    while (1) {
        uint16_t clear, red, green, blue;
        if (read_i2c_word(i2c_fd, TCS34725_COMMAND_BIT | TCS34725_CDATAL, &clear) != 0 ||
            read_i2c_word(i2c_fd, TCS34725_COMMAND_BIT | TCS34725_RDATAL, &red) != 0 ||
            read_i2c_word(i2c_fd, TCS34725_COMMAND_BIT | TCS34725_GDATAL, &green) != 0 ||
            read_i2c_word(i2c_fd, TCS34725_COMMAND_BIT | TCS34725_BDATAL, &blue) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            cleanup(0);
        }

        // Apply calibration (example values, adjust as needed)
        float r_cal = red * 1.0;
        float g_cal = green * 1.0;
        float b_cal = blue * 1.0;
        float c_cal = clear * 1.0;

        printf("Calibrated RGB: R=%f G=%f B=%f C=%f\n", r_cal, g_cal, b_cal, c_cal);

        if (r_cal > RED_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        usleep(200000); // Poll every 200ms
    }

    cleanup(0);
}

