#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <errno.h>
#include <math.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define LED_GPIO_PIN 18
#define NUM_LEDS 10
#define MAX_LUX 1000.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

static int i2c_handle;
static int gpio_handle;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        close(i2c_handle);
    }
    if (gpio_handle >= 0) {
        gpioHardwarePWM(LED_GPIO_PIN, 0, 0);
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t *buf, int len) {
    int retries = 0;
    while (retries < RETRY_COUNT) {
        int bytes_written = write(fd, buf, len);
        if (bytes_written == len) {
            return 0;
        }
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int i2c_read(int fd, uint8_t *buf, int len) {
    int retries = 0;
    while (retries < RETRY_COUNT) {
        int bytes_read = read(fd, buf, len);
        if (bytes_read == len) {
            return 0;
        }
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

float read_bh1750() {
    uint8_t cmd = 0x10;
    uint8_t data[2];

    if (i2c_write(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Failed to write to BH1750\n");
        return -1;
    }
    usleep(180 * 1000);

    if (i2c_read(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Failed to read from BH1750\n");
        return -1;
    }

    return (float)((data[0] << 8) | data[1]) / 1.2;
}

void set_led_brightness(uint8_t brightness) {
    uint32_t pwm_range = 255;
    uint32_t pwm_duty = (uint32_t)((float)brightness / 255.0 * pwm_range);
    gpioPWM(LED_GPIO_PIN, pwm_duty);
}

uint8_t map_brightness(float lux) {
    if (lux <= 0) return 0;
    if (lux >= MAX_LUX) return 255;

    float log_lux = log10f(lux / MAX_LUX);
    return (uint8_t)(255.0 * (1.0 - log_lux));
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    i2c_handle = open("/dev/i2c-1", O_RDWR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_handle, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO_PIN, PI_OUTPUT);
    gpioHardwarePWM(LED_GPIO_PIN, 800000, 0);  // 800 kHz PWM frequency

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        float lux = read_bh1750();
        if (lux >= 0) {
            uint8_t brightness = map_brightness(lux);
            set_led_brightness(brightness);
        }
        usleep(100000);  // 100ms delay between readings
    }

    return EXIT_SUCCESS;
}

