    if (i2c_write(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Failed to write to BH1750\n");
        return -1;
    }
    usleep(180 * 1000);

    if (i2c_read(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Failed to read from BH1750\n");
        return -1;
    }

    return (float)((data[0] << 8) | data[1]) / 1.2;
}

void set_led_brightness(uint8_t brightness) {
    uint32_t pwm_range = 255;
    uint32_t pwm_duty = (uint32_t)((float)brightness / 255.0 * pwm_range);
    gpioPWM(LED_GPIO_PIN, pwm_duty);
}

uint8_t map_brightness(float lux) {
    if (lux <= 0) return 0;
    if (lux >= MAX_LUX) return 255;

    float log_lux = log10f(lux / MAX_LUX);
    return (uint8_t)(255.0 * (1.0 - log_lux));
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    i2c_handle = open("/dev/i2c-1", O_RDWR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_handle, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO_PIN, PI_OUTPUT);
    gpioHardwarePWM(LED_GPIO_PIN, 800000, 0);  // 800 kHz PWM frequency

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        float lux = read_bh1750();
        if (lux >= 0) {
            uint8_t brightness = map_brightness(lux);
            set_led_brightness(brightness);
        }
        usleep(100000);  // 100ms delay between readings
    }

    return EXIT_SUCCESS;
}
