#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define NUM_SENSORS 3
#define I2C_BUS 1
#define SENSOR_ADDRESSES {0x23, 0x5C}
#define APA102_MOSI_PIN 10
#define APA102_SCLK_PIN 11
#define FADE_DURATION_MS 500
#define FADE_STEPS 50
#define SAMPLE_DELAY_MS 100
#define SENSOR_READ_DELAY_MS 180
#define MAX_BRIGHTNESS 31

static int i2c_handles[NUM_SENSORS];
static int spi_handle;
static int brightness_level = MAX_BRIGHTNESS;

void cleanup(int signum) {
    printf("Cleaning up...\n");
    gpioWrite(APA102_MOSI_PIN, 0);
    gpioWrite(APA102_SCLK_PIN, 0);
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
        }
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

float read_sensor(int handle) {
    char data[2];
    if (i2cReadI2CBlock(handle, 0x00, data, 2) == 2) {
        return (data[0] << 8) | data[1];
    }
    return -1;
}

void set_apa102_brightness(int brightness) {
    unsigned char frame[4] = {0x00, 0x00, 0x00, 0xE0 | brightness};
    gpioWrite(APA102_SCLK_PIN, 0);
    for (int i = 0; i < 4; i++) {
        for (int bit = 7; bit >= 0; bit--) {
            gpioWrite(APA102_MOSI_PIN, (frame[i] >> bit) & 1);
            gpioWrite(APA102_SCLK_PIN, 1);
            gpioWrite(APA102_SCLK_PIN, 0);
        }
    }
}

void fade_brightness(int target_brightness) {
    int current_brightness = brightness_level;
    int step = (target_brightness > current_brightness) ? 1 : -1;
    for (int i = 0; i < FADE_STEPS; i++) {
        brightness_level = current_brightness + (step * i);
        set_apa102_brightness(brightness_level);
        usleep((FADE_DURATION_MS * 1000) / FADE_STEPS);
    }
    brightness_level = target_brightness;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    int sensor_addresses[] = SENSOR_ADDRESSES;
    int sensor_count = 0;

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2cOpen(I2C_BUS, sensor_addresses[i], 0);
        if (i2c_handles[i] >= 0) {
            if (i2cWriteByte(i2c_handles[i], 0x21) == 0) {
                usleep(SENSOR_READ_DELAY_MS * 1000);
                sensor_count++;
            } else {
                i2cClose(i2c_handles[i]);
                i2c_handles[i] = -1;
            }
        }
    }

    if (sensor_count == 0) {
        fprintf(stderr, "No valid sensors found\n");
        cleanup(0);
    }

    spi_handle = spiOpen(APA102_MOSI_PIN, APA102_SCLK_PIN, 8000000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        cleanup(0);
    }

    while (1) {
        float total_lux = 0;
        int valid_sensors = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] >= 0) {
                float lux = read_sensor(i2c_handles[i]);
                if (lux >= 0) {
                    total_lux += lux;
                    valid_sensors++;
                }
            }
        }

        if (valid_sensors > 0) {
            float avg_lux = total_lux / valid_sensors;
            int new_brightness = (int)(MAX_BRIGHTNESS - (avg_lux / 1000.0));
            new_brightness = (new_brightness < 0) ? 0 : (new_brightness > MAX_BRIGHTNESS) ? MAX_BRIGHTNESS : new_brightness;
            fade_brightness(new_brightness);
        }

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

