#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define ALS_REG 0x04
#define CONFIG_REG 0x00
#define INTEGRATION_TIME 100
#define GAIN 8
#define LUX_FACTOR (0.0288)
#define MAX_LUX 120000
#define LED_GPIO_PIN 18
#define BIT_BANG_FREQ 800000
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

static int i2c_fd;
static struct gpiod_line *led_line;
static int running = 1;

void signal_handler(int signum) {
    running = 0;
}

int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

int init_veml7700() {
    uint16_t config = 0x0000;
    if (write(i2c_fd, &config, sizeof(config)) != sizeof(config)) {
        perror("Failed to write to VEML7700 config register");
        return -1;
    }
    return 0;
}

int read_als(uint16_t *als_value) {
    uint8_t reg = ALS_REG;
    if (write(i2c_fd, &reg, sizeof(reg)) != sizeof(reg)) {
        perror("Failed to write ALS register address");
        return -1;
    }
    if (read(i2c_fd, als_value, sizeof(*als_value)) != sizeof(*als_value)) {
        perror("Failed to read ALS value");
        return -1;
    }
    return 0;
}

int init_gpio() {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }
    led_line = gpiod_chip_get_line(chip, LED_GPIO_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(led_line, "WS2812B", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }
    gpiod_chip_close(chip);
    return 0;
}

void set_led_brightness(uint8_t brightness) {
    // Implement bit-banging or threshold-based control here
    // For simplicity, we'll use a basic threshold-based approach
    int value = (brightness > 128) ? 1 : 0;
    gpiod_line_set_value(led_line, value);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_i2c() < 0 || init_veml7700() < 0 || init_gpio() < 0) {
        fprintf(stderr, "Initialization failed\n");
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t als_value = 0;
        int retries = 0;
        while (retries < RETRY_COUNT) {
            if (read_als(&als_value) == 0) {
                break;
            }
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
        }
        if (retries == RETRY_COUNT) {
            fprintf(stderr, "Failed to read ALS value after %d retries\n", RETRY_COUNT);
            continue;
        }

        float lux = als_value * LUX_FACTOR;
        float brightness = 255 * pow(lux / MAX_LUX, 1.0 / 2.2);
        brightness = fminf(fmaxf(brightness, 0), 255);

        printf("Lux: %.2f, Brightness: %.2f\n", lux, brightness);
        set_led_brightness((uint8_t)brightness);

        usleep(LOOP_DELAY_MS * 1000);
    }

    gpiod_line_release(led_line);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

