#include <time.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18
#define NUM_SELF_TEST_READS 5
#define SELF_TEST_DELAY_MS 100
#define POLL_DELAY_MS 50
#define ERROR_BLINK_CYCLES 5
#define ERROR_BUZZ_PATTERN_MS {200, 200, 600, 200}
#define NUM_ERROR_BUZZ_REPEATS 3

static struct gpiod_chip *chip;
static struct gpiod_line *flame_sensor_line, *buzzer_line, *led_line;

void cleanup_and_exit(int status) {
    if (flame_sensor_line) gpiod_line_release(flame_sensor_line);
    if (buzzer_line) gpiod_line_release(buzzer_line);
    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);
    exit(status);
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up and exiting.\n", signum);
    cleanup_and_exit(0);
}

void log_event(const char *event) {
    time_t now;
    time(&now);
    printf("%s: %s\n", ctime(&now), event);
}

int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO value: %s\n", strerror(errno));
    }
    return ret;
}

int get_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Failed to get GPIO value: %s\n", strerror(errno));
    }
    return value;
}

void blink_led(int count, int on_ms, int off_ms) {
    for (int i = 0; i < count; i++) {
        set_gpio_value(led_line, 0);
        usleep(on_ms * 1000);
        set_gpio_value(led_line, 1);
        usleep(off_ms * 1000);
    }
}

void sound_buzzer(int count, const int *pattern_ms, int pattern_length) {
    for (int i = 0; i < count; i++) {
        for (int j = 0; j < pattern_length; j++) {
            set_gpio_value(buzzer_line, 0);
            usleep(pattern_ms[j] / 2 * 1000);
            set_gpio_value(buzzer_line, 1);
            usleep(pattern_ms[j] / 2 * 1000);
        }
    }
}

int self_test() {
    int failures = 0;
    blink_led(2, 500, 500);
    set_gpio_value(buzzer_line, 1);

    for (int i = 0; i < NUM_SELF_TEST_READS; i++) {
        if (get_gpio_value(flame_sensor_line) == 0) {
            failures++;
        }
        usleep(SELF_TEST_DELAY_MS * 1000);
    }

    set_gpio_value(buzzer_line, 1);
    if (failures == NUM_SELF_TEST_READS) {
        log_event("Self-test failed: Consistent flame detection");
        for (int i = 0; i < ERROR_BUZZ_PATTERN_MS; i++) {
            blink_led(ERROR_BLINK_CYCLES, 100, 100);
            sound_buzzer(NUM_ERROR_BUZZ_REPEATS, ERROR_BUZZ_PATTERN_MS, sizeof(ERROR_BUZZ_PATTERN_MS) / sizeof(ERROR_BUZZ_PATTERN_MS[0]));
        }
        return 0;
    }
    log_event("Self-test passed");
    return 1;
}

int main() {
    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);

    if (!flame_sensor_line || !buzzer_line || !led_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup_and_exit(1);
    }

    if (gpiod_line_request_input(flame_sensor_line, "flame-sensor") < 0 ||
        gpiod_line_request_output(buzzer_line, "buzzer", 1) < 0 ||
        gpiod_line_request_output(led_line, "led", 1) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        cleanup_and_exit(1);
    }

    if (!self_test()) {
        cleanup_and_exit(1);
    }

    int flame_detected = 0;
    int consecutive_low_samples = 0;

    while (1) {
        if (get_gpio_value(flame_sensor_line) == 0) {
            if (!flame_detected) {
                log_event("Flame detected");
                set_gpio_value(buzzer_line, 0);
                set_gpio_value(led_line, 0);
                flame_detected = 1;
            }
            consecutive_low_samples++;
        } else {
            if (flame_detected && consecutive_low_samples >= 1) {
                log_event("Flame gone");
                set_gpio_value(buzzer_line, 1);
                set_gpio_value(led_line, 1);
                flame_detected = 0;
                consecutive_low_samples = 0;
            } else if (flame_detected) {
                consecutive_low_samples++;
            }
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    cleanup_and_exit(0);
}

