#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define SENSOR_COMMAND 0x10
#define BUFFER_SIZE 60
#define LED_GPIO_PATH "/sys/class/gpio/gpio17"
#define LED_GPIO_PIN 17

int i2c_fd;
int gpio_fd;
int lux_buffer[BUFFER_SIZE];
int buffer_index = 0;
int running = 1;

void cleanup(int signum) {
    running = 0;
    if (gpio_fd >= 0) {
        char path[64];
        snprintf(path, sizeof(path), "%s/value", LED_GPIO_PATH);
        int fd = open(path, O_WRONLY);
        if (fd >= 0) {
            write(fd, "0", 1);
            close(fd);
        }
        close(gpio_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

int init_gpio() {
    gpio_fd = open("/sys/class/gpio/export", O_WRONLY);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO export");
        return -1;
    }
    char buf[32];
    snprintf(buf, sizeof(buf), "%d", LED_GPIO_PIN);
    if (write(gpio_fd, buf, strlen(buf)) < 0) {
        perror("Failed to export GPIO");
        close(gpio_fd);
        return -1;
    }
    close(gpio_fd);

    gpio_fd = open("/sys/class/gpio/gpio17/direction", O_WRONLY);
    if (gpio_fd < 0) {
        perror("Failed to set GPIO direction");
        return -1;
    }
    if (write(gpio_fd, "out", 3) < 0) {
        perror("Failed to set GPIO direction");
        close(gpio_fd);
        return -1;
    }
    close(gpio_fd);

    gpio_fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO value");
        return -1;
    }
    return 0;
}

int read_sensor() {
    unsigned char data[2];
    if (write(i2c_fd, &SENSOR_COMMAND, 1) != 1) {
        perror("Failed to write to sensor");
        return -1;
    }
    usleep(180000);  // Wait for measurement (120ms)
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from sensor");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

void update_buffer(int lux) {
    lux_buffer[buffer_index] = lux;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

float calculate_average() {
    long sum = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += lux_buffer[i];
    }
    return (float)sum / BUFFER_SIZE;
}

void set_led(float avg_lux) {
    float rate = 0.5 + (avg_lux / 1000) * 4.5;
    if (rate > 5.0) rate = 5.0;
    if (rate < 0.5) rate = 0.5;

    struct timespec on_time, off_time;
    on_time.tv_sec = 0;
    on_time.tv_nsec = (long)(500000000 / rate / 2);
    off_time.tv_sec = 0;
    off_time.tv_nsec = on_time.tv_nsec;

    while (running) {
        if (write(gpio_fd, "1", 1) < 0) {
            perror("Failed to set GPIO high");
            break;
        }
        nanosleep(&on_time, NULL);
        if (write(gpio_fd, "0", 1) < 0) {
            perror("Failed to set GPIO low");
            break;
        }
        nanosleep(&off_time, NULL);
    }
}

int main() {
    signal(SIGINT, cleanup);

    if (init_i2c() < 0 || init_gpio() < 0) {
        return 1;
    }

    while (running) {
        int raw = read_sensor();
        if (raw >= 0) {
            int lux = (int)(raw / 1.2);
            update_buffer(lux);
            float avg_lux = calculate_average();
            printf("Lux: %d, Average: %.2f\n", lux, avg_lux);
            set_led(avg_lux);
        }
        sleep(1);
    }

    cleanup(0);
    return 0;
}

