#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define the segment patterns for the digit '5'
const unsigned char digit_5_pattern = 0b01110110;

// Function to shift out 8 bits to the 74HC595
void shift_out(struct gpiod_line *data_line, struct gpiod_line *clock_line, struct gpiod_line *latch_line, unsigned char value) {
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(data_line, (value >> i) & 0x01);
        gpiod_line_set_value(clock_line, 1);
        usleep(1); // 1 microsecond delay
        gpiod_line_set_value(clock_line, 0);
        usleep(1); // 1 microsecond delay
    }
    gpiod_line_set_value(latch_line, 1);
    usleep(1); // 1 microsecond delay
    gpiod_line_set_value(latch_line, 0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *data_line, *clock_line, *latch_line;
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines for data, clock, and latch
    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);

    if (!data_line || !clock_line || !latch_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines as outputs
    ret = gpiod_line_request_output(data_line, "74HC595 Data", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request data line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(clock_line, "74HC595 Clock", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request clock line\n");
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(latch_line, "74HC595 Latch", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request latch line\n");
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop to blink the digit
    while (1) {
        shift_out(data_line, clock_line, latch_line, digit_5_pattern);
        usleep(500000); // 500 ms on
        shift_out(data_line, clock_line, latch_line, 0x00); // Turn off all segments
        usleep(500000); // 500 ms off
    }

    // Cleanup (this part will never be reached due to infinite loop)
    gpiod_line_release(data_line);
    gpiod_line_release(clock_line);
    gpiod_line_release(latch_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

