#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define LED_PIN 17
#define BUTTON_PIN 18
#define BLINK_INTERVAL 2
#define TIMEOUT 1

volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        terminate = 1;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *led_line, *button_line;
    int ret;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        goto cleanup_chip;
    }

    ret = gpiod_line_request_output(led_line, "LED", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(-ret));
        goto cleanup_led;
    }

    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Failed to get button line\n");
        goto cleanup_led;
    }

    ret = gpiod_line_request_input(button_line, "Button");
    if (ret < 0) {
        fprintf(stderr, "Failed to request button line as input: %s\n", strerror(-ret));
        goto cleanup_button;
    }

    ret = gpiod_line_request_both_edges(button_line, "Button");
    if (ret < 0) {
        fprintf(stderr, "Failed to request button line for edge detection: %s\n", strerror(-ret));
        goto cleanup_button;
    }

    while (!terminate) {
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set LED line high: %s\n", strerror(-ret));
            break;
        }
        sleep(BLINK_INTERVAL / 2);

        if (terminate) break;

        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set LED line low: %s\n", strerror(-ret));
            break;
        }
        sleep(BLINK_INTERVAL / 2);

        struct gpiod_line_event event;
        ret = gpiod_line_event_wait(button_line, TIMEOUT * 1000000000);
        if (ret > 0) {
            ret = gpiod_line_event_read(button_line, &event);
            if (ret == 0 && event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                printf("Button pressed, stopping blink\n");
                break;
            }
        } else if (ret < 0) {
            fprintf(stderr, "Failed to wait for button event: %s\n", strerror(-ret));
            break;
        }
    }

    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;

cleanup_button:
    gpiod_line_release(button_line);
cleanup_led:
    gpiod_line_release(led_line);
cleanup_chip:
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

