#include <stdio.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 5
#define DELAY_MS 750

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        gpioWrite(LED_PIN, LOW);
        gpioTerminate();
        keep_running = 0;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (keep_running) {
        gpioWrite(LED_PIN, HIGH);
        printf("LED ON\n");
        fflush(stdout);
        gpioDelay(DELAY_MS * 1000);

        gpioWrite(LED_PIN, LOW);
        printf("LED OFF\n");
        fflush(stdout);
        gpioDelay(DELAY_MS * 1000);
    }

    return 0;
}

