    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        goto error;
    }

    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Failed to get BUTTON line\n");
        goto error;
    }

    int ret = gpiod_line_request_output(led_line, "LED", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line as output\n");
        goto error;
    }

    ret = gpiod_line_request_input(button_line, "BUTTON");
    if (ret < 0) {
        fprintf(stderr, "Failed to request BUTTON line as input\n");
        goto error;
    }

    ret = gpiod_line_set_flags(button_line, GPIOD_LINE_FLAG_BIAS_PULL_DOWN);
    if (ret < 0) {
        fprintf(stderr, "Failed to set internal pull-down for BUTTON line\n");
        goto error;
    }

    while (running) {
        int value = gpiod_line_get_value(button_line);
        if (value < 0) {
            fprintf(stderr, "Failed to read BUTTON line value\n");
            break;
        }

        if (value == 0) {  // Button pressed
            gpiod_line_set_value(led_line, 1);
            usleep(BLINK_INTERVAL_MS * 1000);
            gpiod_line_set_value(led_line, 0);
            usleep(BLINK_INTERVAL_MS * 1000);
        } else {  // Button released
            gpiod_line_set_value(led_line, 0);
            usleep(10000);  // Debounce delay
        }
    }

error:
    cleanup(0);
    return EXIT_FAILURE;
}

