    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    printf("\nCleaned up and exiting.\n");
    exit(EXIT_SUCCESS);
}

void set_pwm_duty_cycle(struct gpiod_line *line, int duty_cycle) {
    struct timespec ts = {0, PWM_DURATION_US * 1000};
    for (int i = 0; i < PWM_DUTY_CYCLE_STEPS; i++) {
        if (!running) return;
        if (i < duty_cycle) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }
        clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);
    }
}

int main() {
    srand(time(NULL));
    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup(SIGINT);
    }

    if (gpiod_line_request_output(red_line, "RGB_LED_RED", 0) < 0 ||
        gpiod_line_request_output(green_line, "RGB_LED_GREEN", 0) < 0 ||
        gpiod_line_request_output(blue_line, "RGB_LED_BLUE", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as output\n");
        cleanup(SIGINT);
    }

    struct timespec delay = {0, 100000000}; // 100 ms

    while (running) {
        int red = rand() % (PWM_DUTY_CYCLE_STEPS + 1);
        int green = rand() % (PWM_DUTY_CYCLE_STEPS + 1);
        int blue = rand() % (PWM_DUTY_CYCLE_STEPS + 1);

        set_pwm_duty_cycle(red_line, red);
        set_pwm_duty_cycle(green_line, green);
        set_pwm_duty_cycle(blue_line, blue);

        clock_nanosleep(CLOCK_MONOTONIC, 0, &delay, NULL);
    }

    cleanup(SIGINT);
    return EXIT_SUCCESS;
}
