#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x19
#define OUT_X_L_A 0x28
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define SAMPLE_RATE 10
#define POLL_INTERVAL_MS 100
#define IMPACT_THRESHOLD_DEFAULT 2.0
#define PULSE_DURATION_MS 50
#define LOG_FILE "impact_log.txt"

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int write_i2c(int i2c_handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, gpioStrError(result));
        return -1;
    }
    return 0;
}

int read_i2c(int i2c_handle, uint8_t reg, uint8_t *buffer, int length) {
    int result = i2cReadI2CBlockData(i2c_handle, reg, buffer, length);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, gpioStrError(result));
        return -1;
    }
    return 0;
}

float calculate_g_force(int16_t x, int16_t y, int16_t z) {
    return sqrtf(x * x + y * y + z * z) / 16384.0;
}

int main(int argc, char *argv[]) {
    float threshold = IMPACT_THRESHOLD_DEFAULT;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (write_i2c(i2c_handle, CTRL_REG1_A, 0x27) != 0 ||
        write_i2c(i2c_handle, CTRL_REG4_A, 0x00) != 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(17, PI_OUTPUT);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    time_t last_log_time = 0;

    while (keep_running) {
        uint8_t data[6];
        if (read_i2c(i2c_handle, OUT_X_L_A | 0x80, data, 6) != 0) {
            continue;
        }

        int16_t x = (int16_t)((data[1] << 8) | data[0]);
        int16_t y = (int16_t)((data[3] << 8) | data[2]);
        int16_t z = (int16_t)((data[5] << 8) | data[4]);

        float g_force = calculate_g_force(x, y, z);

        if (g_force > threshold) {
            gpioWrite(17, PI_HIGH);
            gpioDelay(PULSE_DURATION_MS * 1000);
            gpioWrite(17, PI_LOW);

            time_t current_time = time(NULL);
            if (current_time - last_log_time >= 1) {
                fprintf(log_file, "%ld,%d,%d,%d,%.2f\n",
                        (long)current_time, x, y, z, g_force);
                fflush(log_file);
                last_log_time = current_time;
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

