#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x39
#define ALS_REG_LSB 0x64
#define ALS_REG_MSB 0x65
#define RED_REG_LSB 0x66
#define GREEN_REG_LSB 0x68
#define BLUE_REG_LSB 0x6A
#define MODE_REG 0x0D
#define LED_PIN 18
#define SAMPLE_INTERVAL_MS 500
#define RETRY_DELAY_MS 100

static FILE *csv_file;
static int i2c_handle;

void cleanup(int signum) {
    if (csv_file) {
        fclose(csv_file);
    }
    if (i2c_handle >= 0) {
        gpioI2CClose(i2c_handle);
    }
    gpioHardwarePWM(LED_PIN, 0, 0);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_handle = gpioI2COpen(I2C_BUS, SENSOR_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioI2CWriteByteData(i2c_handle, MODE_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to set sensor mode\n");
        cleanup(0);
    }

    csv_file = fopen("color_log.csv", "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        cleanup(0);
    }

    fprintf(csv_file, "Timestamp,ALS,R,G,B\n");
    fflush(csv_file);

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioHardwarePWM(LED_PIN, 1000, 0); // 1 kHz frequency, 0% duty cycle

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        uint16_t als, red, green, blue;
        int retry_count = 0;

        while (retry_count < 3) {
            als = gpioI2CReadWordData(i2c_handle, ALS_REG_LSB);
            red = gpioI2CReadWordData(i2c_handle, RED_REG_LSB);
            green = gpioI2CReadWordData(i2c_handle, GREEN_REG_LSB);
            blue = gpioI2CReadWordData(i2c_handle, BLUE_REG_LSB);

            if (als >= 0 && red >= 0 && green >= 0 && blue >= 0) {
                break;
            }

            retry_count++;
            usleep(RETRY_DELAY_MS * 1000);
        }

        if (retry_count == 3) {
            fprintf(stderr, "Failed to read sensor data after 3 attempts\n");
            continue;
        }

        fprintf(csv_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
        fflush(csv_file);

        // Map ALS value (0-65535) to PWM duty cycle (0-255)
        unsigned int pwm_duty = (als * 255) / 65535;
        gpioPWM(LED_PIN, pwm_duty);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

