#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define FXOS8700CQ_SLAVE_ADDR 0x1F
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define XYZ_DATA_CFG_REG 0x0E
#define OUT_X_MSB_REG 0x01
#define SENSITIVITY_2G 4096.0
#define GRAVITY 9.81
#define IMPACT_THRESHOLD 19.62
#define SAMPLE_INTERVAL_MS 50

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_impact(double x, double y, double z, double magnitude) {
    FILE *file = fopen("impact_log.txt", "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, FXOS8700CQ_SLAVE_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I
    char who_am_i;
    if (i2cReadByteData(i2c_handle, WHO_AM_I_REG, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (who_am_i != 0xC7) {
        fprintf(stderr, "Sensor WHO_AM_I mismatch: 0x%02X\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Failed to set CTRL_REG1 to standby\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, XYZ_DATA_CFG_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure XYZ_DATA_CFG\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Failed to activate sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    unsigned char data[6];
    int16_t x, y, z;
    double magnitude;

    while (keep_running) {
        if (i2cReadI2CBlock(i2c_handle, OUT_X_MSB_REG, data, 6) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue;
        }

        x = ((int16_t)data[0] << 8) | data[1];
        y = ((int16_t)data[2] << 8) | data[3];
        z = ((int16_t)data[4] << 8) | data[5];

        x = x >> 2;
        y = y >> 2;
        z = z >> 2;

        double x_g = (double)x / SENSITIVITY_2G;
        double y_g = (double)y / SENSITIVITY_2G;
        double z_g = (double)z / SENSITIVITY_2G;

        magnitude = sqrt(x_g * x_g + y_g * y_g + z_g * z_g) * GRAVITY;

        if (magnitude > IMPACT_THRESHOLD) {
            log_impact(x_g, y_g, z_g, magnitude);
        }

        time_sleep(0.05);  // 50ms delay
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

