        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, XYZ_DATA_CFG_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure XYZ_DATA_CFG\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Failed to activate sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    unsigned char data[6];
    int16_t x, y, z;
    double magnitude;

    while (keep_running) {
        if (i2cReadI2CBlock(i2c_handle, OUT_X_MSB_REG, data, 6) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue;
        }

        x = ((int16_t)data[0] << 8) | data[1];
        y = ((int16_t)data[2] << 8) | data[3];
        z = ((int16_t)data[4] << 8) | data[5];

        x = x >> 2;
        y = y >> 2;
        z = z >> 2;

        double x_g = (double)x / SENSITIVITY_2G;
        double y_g = (double)y / SENSITIVITY_2G;
        double z_g = (double)z / SENSITIVITY_2G;

        magnitude = sqrt(x_g * x_g + y_g * y_g + z_g * z_g) * GRAVITY;

        if (magnitude > IMPACT_THRESHOLD) {
            log_impact(x_g, y_g, z_g, magnitude);
        }

        time_sleep(0.05);  // 50ms delay
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}
