#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define SENSITIVITY 0.00875
#define CALIBRATION_SAMPLES 100
#define LOG_FILE "gyro_log.txt"
#define SAMPLE_RATE 20
#define SAMPLE_INTERVAL_MS 50

static int i2c_fd;
static FILE *log_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int write_i2c(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, sizeof(buf)) != sizeof(buf)) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int read_i2c(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int calibrate_gyro(float *offsets) {
    int16_t raw[3];
    float sum[3] = {0};

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (read_i2c(i2c_fd, OUT_X_L | 0x80, (uint8_t *)raw, 6) != 0) {
            return -1;
        }
        for (int j = 0; j < 3; j++) {
            sum[j] += raw[j] * SENSITIVITY;
        }
        usleep(10000); // 10ms delay between samples
    }

    for (int i = 0; i < 3; i++) {
        offsets[i] = sum[i] / CALIBRATION_SAMPLES;
    }

    return 0;
}

