    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, GYRO_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t who_am_i;
    if (read_i2c(i2c_fd, WHO_AM_I, &who_am_i, 1) != 0 || who_am_i != 0xD3) {
        fprintf(stderr, "Gyroscope not detected or communication error\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write_i2c(i2c_fd, CTRL_REG1, 0x0F) != 0 || write_i2c(i2c_fd, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Failed to configure gyroscope\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    float offsets[3];
    if (calibrate_gyro(offsets) != 0) {
        fprintf(stderr, "Failed to calibrate gyroscope\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int16_t raw[3];
    float dps[3];
    struct timespec ts;
    char timestamp[64];

    while (1) {
        if (read_i2c(i2c_fd, OUT_X_L | 0x80, (uint8_t *)raw, 6) != 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            continue;
        }

        for (int i = 0; i < 3; i++) {
            dps[i] = (raw[i] * SENSITIVITY) - offsets[i];
            if (fabs(dps[i]) > 50.0) {
                fprintf(stderr, "Warning: Axis %c exceeds 50 dps\n", "XYZ"[i]);
                fprintf(log_file, "ALERT: Axis %c exceeds 50 dps\n", "XYZ"[i]);
            }
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));
        fprintf(log_file, "%s.%09ldZ,%.2f,%.2f,%.2f\n", timestamp, ts.tv_nsec, dps[0], dps[1], dps[2]);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

