#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define DEVID_REG 0x00
#define DATA_FORMAT_REG 0x31
#define DATAX0_REG 0x32
#define DATAX1_REG 0x33
#define DATAY0_REG 0x34
#define DATAY1_REG 0x35
#define DATAZ0_REG 0x36
#define DATAZ1_REG 0x37
#define LED_PIN 17
#define SAMPLE_INTERVAL_MS 100
#define ACCEL_THRESHOLD 2.0

static int i2cHandle;
static FILE *logFile;

void cleanup(int signum) {
    if (i2cHandle >= 0) {
        i2cClose(i2cHandle);
    }
    if (logFile) {
        fclose(logFile);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_LOW);

    i2cHandle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        cleanup(0);
    }

    unsigned char devId;
    if (i2cReadByteData(i2cHandle, DEVID_REG, &devId) < 0 || devId != 0xE5) {
        fprintf(stderr, "ADXL345 device ID check failed\n");
        cleanup(0);
    }

    unsigned char config = 0x0B; // Full resolution, ±2g range
    if (i2cWriteByteData(i2cHandle, DATA_FORMAT_REG, config) < 0) {
        fprintf(stderr, "Failed to configure ADXL345\n");
        cleanup(0);
    }

    logFile = fopen("accel_log.txt", "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
    }

    time_t lastLogTime = 0;
    struct timespec sleepTime = {0, SAMPLE_INTERVAL_MS * 1000000};

    while (1) {
        char data[6];
        if (i2cReadI2CBlock(i2cHandle, DATAX0_REG, 6, data) < 0) {
            fprintf(stderr, "I2C read error, skipping sample\n");
            gpioSleep(PI_TIME_RELATIVE, sleepTime.tv_sec, sleepTime.tv_nsec);
            continue;
        }

        short x = (data[1] << 8) | data[0];
        short y = (data[3] << 8) | data[2];
        short z = (data[5] << 8) | data[4];

        float x_g = x * 0.004;
        float y_g = y * 0.004;
        float z_g = z * 0.004;

        time_t currentTime = time(NULL);
        if (currentTime != lastLogTime) {
            fprintf(logFile, "%ld,%.3f,%.3f,%.3f\n", (long)currentTime, x_g, y_g, z_g);
            fflush(logFile);
            lastLogTime = currentTime;
        }

        if (fabs(x_g) > ACCEL_THRESHOLD || fabs(y_g) > ACCEL_THRESHOLD || fabs(z_g) > ACCEL_THRESHOLD) {
            gpioWrite(LED_PIN, PI_HIGH);
        } else {
            gpioWrite(LED_PIN, PI_LOW);
        }

        gpioSleep(PI_TIME_RELATIVE, sleepTime.tv_sec, sleepTime.tv_nsec);
    }

    return EXIT_SUCCESS;
}

