#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>

#define I2C_BUS 1
#define ACCEL_ADDR 0x19
#define MAGNETO_ADDR 0x1E

#define CTRL_REG1_A 0x20
#define MR_REG_M 0x02

#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D

#define OUT_X_L_M 0x03
#define OUT_X_H_M 0x04
#define OUT_Y_L_M 0x05
#define OUT_Y_H_M 0x06
#define OUT_Z_L_M 0x07
#define OUT_Z_H_M 0x08

#define SAMPLE_INTERVAL_MS 100

volatile int keep_running = 1;

void signal_handler(int signo) {
    keep_running = 0;
}

int i2c_read_word(int fd, int addr, int reg) {
    char buf[2];
    if (i2cReadI2CBlockData(fd, addr, reg, 2, buf) < 0) {
        fprintf(stderr, "Error reading from I2C device at address 0x%02X\n", addr);
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

int i2c_read_word_16(int fd, int addr, int reg) {
    int value = i2c_read_word(fd, addr, reg);
    if (value < 0) return -1;
    return (int16_t)value;
}

void log_data(FILE *log_file, int16_t ax, int16_t ay, int16_t az, int16_t mx, int16_t my, int16_t mz, float heading) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0';  // Remove newline

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            time_str, heading, ax / 16384.0, ay / 16384.0, az / 16384.0,
            mx * 0.001, my * 0.001, mz * 0.001);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, ACCEL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    int i2c_handle_mag = i2cOpen(I2C_BUS, MAGNETO_ADDR, 0);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Failed to open I2C bus for magnetometer\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize accelerometer
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Failed to initialize accelerometer\n");
        i2cClose(i2c_handle);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Initialize magnetometer
    if (i2cWriteByteData(i2c_handle_mag, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to initialize magnetometer\n");
        i2cClose(i2c_handle);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("compass_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Heading (deg),Accel X (g),Accel Y (g),Accel Z (g),Mag X (gauss),Mag Y (gauss),Mag Z (gauss)\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        int16_t ax = i2c_read_word_16(i2c_handle, ACCEL_ADDR, OUT_X_L_A);
        int16_t ay = i2c_read_word_16(i2c_handle, ACCEL_ADDR, OUT_Y_L_A);
        int16_t az = i2c_read_word_16(i2c_handle, ACCEL_ADDR, OUT_Z_L_A);

        int16_t mx = i2c_read_word_16(i2c_handle_mag, MAGNETO_ADDR, OUT_X_L_M);
        int16_t my = i2c_read_word_16(i2c_handle_mag, MAGNETO_ADDR, OUT_Y_L_M);
        int16_t mz = i2c_read_word_16(i2c_handle_mag, MAGNETO_ADDR, OUT_Z_L_M);

