    ret = write_i2c(handle, SYS_MODE_REG, 0x02);
    if (ret < 0) return -1;

    sleep(1);

    ret = write_i2c(handle, SYS_MODE_REG, 0x00);
    if (ret < 0) return -1;

    return 0;
}

