        fprintf(stderr, "Sensor initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        if (read_i2c(i2c_handle, RANGE_STATUS_REG, &range_status) < 0) {
            fprintf(stderr, "Failed to read range status\n");
            break;
        }

        if (range_status & SYS_ERROR) {
            fprintf(stderr, "Sensor error detected\n");
            break;
        }

        now = time(NULL);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (range_status < 100) {
            fprintf(log_file, "%s DOOR_OPEN\n", timestamp);
        } else {
            fprintf(log_file, "%s DOOR_CLOSED\n", timestamp);
        }
        fflush(log_file);

        usleep(100000);  // 100ms
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

