#define CTRL_REG 0x00
#define ENABLE_MEASURE 0x80
#define I2C_BUS 1
#define SAMPLE_INTERVAL_MS 10

static FILE *log_file;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int setup_i2c(int i2c_bus) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }
    if (i2cOpen(i2c_bus, SENSOR1_ADDR, 0) < 0 || i2cOpen(i2c_bus, SENSOR2_ADDR, 0) < 0) {
        fprintf(stderr, "I2C bus open failed\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

void cleanup_i2c(int i2c_bus) {
    i2cClose(i2c_bus, SENSOR1_ADDR);
    i2cClose(i2c_bus, SENSOR2_ADDR);
    gpioTerminate();
}

int read_sensor(int i2c_bus, int addr) {
    if (i2cWriteByteData(i2c_bus, addr, CTRL_REG, ENABLE_MEASURE) < 0) {
        fprintf(stderr, "Failed to write to control register of sensor at 0x%02X\n", addr);
        return 0;
    }
    gpioSleep(PI_TIME_RELATIVE, 0, 10000); // 10ms delay for sensor to stabilize
    int sample = i2cReadWordData(i2c_bus, addr, DATA_REG);
    if (sample < 0) {
        fprintf(stderr, "Failed to read from data register of sensor at 0x%02X\n", addr);
        return 0;
    }
    return sample;
}

int main() {
    if (setup_i2c(I2C_BUS) < 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("audio_log.dat", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_i2c(I2C_BUS);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    struct timespec ts;
    int sensor1_sample, sensor2_sample;

    fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");

    while (keep_running) {
        clock_gettime(CLOCK_REALTIME, &ts);

        sensor1_sample = read_sensor(I2C_BUS, SENSOR1_ADDR);
        sensor2_sample = read_sensor(I2C_BUS, SENSOR2_ADDR);

        if (sensor1_sample && sensor2_sample) {
            int tdoa = sensor1_sample - sensor2_sample;
            fprintf(log_file, "%ld,%ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, sensor1_sample, sensor2_sample, tdoa);
            fflush(log_file);
        }

        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_MS / 1000, (SAMPLE_INTERVAL_MS % 1000) * 1000);
    }

    fclose(log_file);
    cleanup_i2c(I2C_BUS);
    return EXIT_SUCCESS;
}

