    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

void signal_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec ts;
    struct tm *tm_info;
    char timestamp[20];
    uint16_t data[2];
    int16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    csv_file = fopen("imu_data.csv", "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    atexit(cleanup);

    while (running) {
        clock_gettime(CLOCK_REALTIME, &ts);
        tm_info = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(csv_file, "%s.%03ld,", timestamp, ts.tv_nsec / 1000000);

        for (int reg = X_GYRO; reg <= Z_ACCEL; reg += 2) {
            data[0] = (reg << 8) & 0xFF00;
            data[1] = 0;

            if (spiXfer(spi_handle, data, data, 2) < 0) {
                fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
                fprintf(csv_file, "0,0,0,");
                continue;
            }

            usleep(40);

            data[0] = 0;
            data[1] = 0;

            if (spiXfer(spi_handle, data, data, 2) < 0) {
                fprintf(stderr, "SPI transfer failed for data read of register 0x%02X\n", reg);
                fprintf(csv_file, "0,0,");
                continue;
            }

            int16_t value = (data[1] << 8) | data[0];

            switch (reg) {
                case X_GYRO:
                    gyro_x = value;
                    break;
                case Y_GYRO:
                    gyro_y = value;
                    break;
                case Z_GYRO:
                    gyro_z = value;
                    break;
                case X_ACCEL:
                    accel_x = value;
                    break;
                case Y_ACCEL:
                    accel_y = value;
                    break;
                case Z_ACCEL:
                    accel_z = value;
                    break;
            }

            fprintf(csv_file, "%f,%f,", (float)gyro_x * GYRO_SENSITIVITY, (float)accel_x * ACCEL_SENSITIVITY);
        }

        fprintf(csv_file, "\n");
        fflush(csv_file);

        for (int i = 0; i < SAMPLE_INTERVAL_MS / SAMPLE_DELAY_MS; i++) {
            usleep(SAMPLE_DELAY_MS * 1000);
            if (!running) break;
        }
    }

    return EXIT_SUCCESS;
}
