    uint8_t tx[2] = {READ_REGISTER(reg), 0};
    uint8_t rx[2] = {0};
    int ret;

    gpiod_line_set_value(cs_line, 0);
    ret = spi_transfer(tx, rx, 2);
    gpiod_line_set_value(cs_line, 1);

    if (ret < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return (int16_t)((rx[0] << 8) | rx[1]);
}

