    if (!chip) {
        perror("Cannot open GPIO chip");
        goto error;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        perror("Cannot get GPIO line");
        goto error;
    }

    ret = gpiod_line_request_output(cs_line, "ADIS16448_CS", 1);
    if (ret < 0) {
        perror("Cannot request GPIO line");
        goto error;
    }

