        int16_t gyro_x = read_register(0x04);
        int16_t gyro_y = read_register(0x06);
        int16_t gyro_z = read_register(0x08);
        int16_t accel_x = read_register(0x0A);
        int16_t accel_y = read_register(0x0C);
        int16_t accel_z = read_register(0x0E);

        if (gyro_x < 0 || gyro_y < 0 || gyro_z < 0 ||
            accel_x < 0 || accel_y < 0 || accel_z < 0) {
            fprintf(stderr, "Error reading sensor data\n");
            continue;
        }

        printf("Gyro X: %.2f dps, Y: %.2f dps, Z: %.2f dps\n",
