        printf("Accel X: %.4f g, Y: %.4f g, Z: %.4f g\n",
               accel_x * ACCEL_SCALE, accel_y * ACCEL_SCALE, accel_z * ACCEL_SCALE);

        usleep(100000);  // 100ms
    }

error:
    cleanup(0);
    return EXIT_FAILURE;
}

