        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE_FORCE, MPU6886_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return EXIT_FAILURE;
    }

    // Verify sensor presence
    for (int i = 0; i < RETRY_LIMIT; i++) {
        if (i2c_read(fd, WHO_AM_I_REG, buf, 1) == 1 && buf[0] == 0x68) {
            printf("MPU6886 detected\n");
            break;
        }
        if (i == RETRY_LIMIT - 1) {
            fprintf(stderr, "Failed to detect MPU6886\n");
            close(fd);
            return EXIT_FAILURE;
        }
        usleep(100000);
    }

    // Wake up the sensor
    if (i2c_write(fd, PWR_MGMT_1_REG, 0x00) != 1) {
        perror("Failed to wake up MPU6886");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set accelerometer and gyroscope configurations
    if (i2c_write(fd, ACCEL_CONFIG_REG, 0x00) != 1 ||
        i2c_write(fd, GYRO_CONFIG_REG, 0x00) != 1) {
        perror("Failed to configure MPU6886");
        close(fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        for (int i = 0; i < RETRY_LIMIT; i++) {
            if (i2c_read(fd, ACCEL_OUT_REG, buf, 14) == 14) {
                accel[0] = (int16_t)(buf[0] << 8 | buf[1]);
                accel[1] = (int16_t)(buf[2] << 8 | buf[3]);
                accel[2] = (int16_t)(buf[4] << 8 | buf[5]);
                gyro[0] = (int16_t)(buf[8] << 8 | buf[9]);
                gyro[1] = (int16_t)(buf[10] << 8 | buf[11]);
                gyro[2] = (int16_t)(buf[12] << 8 | buf[13]);
                break;
            }
            if (i == RETRY_LIMIT - 1) {
                fprintf(stderr, "Failed to read sensor data\n");
            }
            usleep(100000);
        }

        printf("Accel: X=%d Y=%d Z=%d | Gyro: X=%d Y=%d Z=%d\n",
               accel[0], accel[1], accel[2], gyro[0], gyro[1], gyro[2]);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    close(fd);
    return EXIT_SUCCESS;
}
