#define ADXL345_DATAY0_REG 0x34
#define ADXL345_DATAZ0_REG 0x36

#define RED_LED_PIN 17
#define I2C_BUS 1
#define SAMPLE_INTERVAL_MS 10
#define IMPACT_THRESHOLD 2.5
#define IMPACT_DURATION_MS 500

static int i2cHandle;
static FILE *logFile;

void cleanup(int signum) {
    if (i2cHandle >= 0) {
        gpioI2CClose(i2cHandle);
    }
    if (logFile) {
        fclose(logFile);
    }
    if (gpioInitialised()) {
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2cHandle = gpioI2COpen(I2C_BUS, ADXL345_ADDR);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        cleanup(0);
    }

    unsigned char deviceId;
    if (gpioI2CReadByte(i2cHandle, ADXL345_ID_REG) != 0) {
        fprintf(stderr, "I2C read error\n");
        cleanup(0);
    }
    deviceId = gpioI2CReadByte(i2cHandle, ADXL345_ID_REG);
    if (deviceId != 0xE5) {
        fprintf(stderr, "ADXL345 device ID mismatch: 0x%02X\n", deviceId);
        cleanup(0);
    }

    gpioSetMode(RED_LED_PIN, PI_OUTPUT);
    gpioWrite(RED_LED_PIN, PI_LOW);

    logFile = fopen("impact_log.txt", "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
    }

    unsigned char dataFormat = 0x0B; // Full resolution, +-2g range
    if (gpioI2CWriteByte(i2cHandle, ADXL345_DATA_FORMAT_REG, dataFormat) != 0) {
        fprintf(stderr, "Failed to set ADXL345 data format\n");
        cleanup(0);
    }

    time_t lastImpactTime = 0;

    while (1) {
        int16_t x, y, z;
        if (gpioI2CReadWordData(i2cHandle, ADXL345_DATAX0_REG, &x) != 0 ||
            gpioI2CReadWordData(i2cHandle, ADXL345_DATAY0_REG, &y) != 0 ||
            gpioI2CReadWordData(i2cHandle, ADXL345_DATAZ0_REG, &z) != 0) {
            fprintf(stderr, "I2C read error\n");
            cleanup(0);
        }

        float magnitude = sqrtf(x*x + y*y + z*z) / 256.0;

        if (magnitude > IMPACT_THRESHOLD) {
            time_t now = time(NULL);
            if (now - lastImpactTime >= IMPACT_DURATION_MS / 1000) {
                gpioWrite(RED_LED_PIN, PI_HIGH);
                lastImpactTime = now;

                fprintf(logFile, "[%s] Impact detected! Magnitude: %.2f g, X: %d, Y: %d, Z: %d\n",
                        ctime(&now), magnitude, x, y, z);
                fflush(logFile);

                gpioSleep(PI_TIME_RELATIVE, IMPACT_DURATION_MS / 1000, (IMPACT_DURATION_MS % 1000) * 1000);
                gpioWrite(RED_LED_PIN, PI_LOW);
            }
        }

        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_MS / 1000, (SAMPLE_INTERVAL_MS % 1000) * 1000);
    }

    return EXIT_SUCCESS;
}

