#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Wake the device
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake the device\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    time_sleep(0.1); // Wait for the device to be ready

    // Set accelerometer range
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set gyroscope range
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set gyroscope range\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I register
    char who_am_i;
    if (i2cReadByteData(i2c_handle, WHO_AM_I, &who_am_i) < 0 || who_am_i != 0x12) {
        fprintf(stderr, "Sensor not found or incorrect WHO_AM_I value\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    FILE *csv_file = fopen("imu_log.csv", "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(csv_file, "Timestamp,AccelX,AccelY,AccelZ,GyroX,GyroY,GyroZ\n");

    signal(SIGINT, signal_handler);

    unsigned char data[14];
    struct timespec ts;

    while (keep_running) {
        if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, 14, data) < 0) {
            fprintf(stderr, "Failed to read IMU data\n");
            break;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(csv_file, "%ld.%09ld,", ts.tv_sec, ts.tv_nsec);

        // Accelerometer data
        fprintf(csv_file, "%d,%d,%d,", 
                (int16_t)(data[0] << 8 | data[1]),
                (int16_t)(data[2] << 8 | data[3]),
                (int16_t)(data[4] << 8 | data[5]));

        // Gyroscope data
        fprintf(csv_file, "%d,%d,%d\n", 
                (int16_t)(data[6] << 8 | data[7]),
                (int16_t)(data[8] << 8 | data[9]),
                (int16_t)(data[10] << 8 | data[11]));

        fflush(csv_file);
        time_sleep(0.1); // 10 Hz
    }

    fclose(csv_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

