#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <math.h>

#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define STATUS_REG 0x00
#define OUT_X_MSB_REG 0x01
#define OUT_Y_MSB_REG 0x03
#define OUT_Z_MSB_REG 0x05
#define SENSITIVITY_2G 1024
#define IMPACT_THRESHOLD (2.0 * SENSITIVITY_2G)
#define LED_GPIO 17
#define POLL_INTERVAL_MS 100
#define IMPACT_LOG_FILE "impact_log.txt"

static int i2c_fd;
static struct gpiod_line *led_line;
static int running = 1;

void signal_handler(int signum) {
    running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) return -1;
    return read(fd, value, 1);
}

int read_accel_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read(i2c_fd, OUT_X_MSB_REG, buf) != 1 ||
        i2c_read(i2c_fd, OUT_X_MSB_REG + 1, buf + 1) != 1 ||
        i2c_read(i2c_fd, OUT_Y_MSB_REG, buf + 2) != 1 ||
        i2c_read(i2c_fd, OUT_Y_MSB_REG + 1, buf + 3) != 1 ||
        i2c_read(i2c_fd, OUT_Z_MSB_REG, buf + 4) != 1 ||
        i2c_read(i2c_fd, OUT_Z_MSB_REG + 1, buf + 5) != 1) {
        return -1;
    }
    *x = ((int16_t)buf[0] << 8) | buf[1];
    *y = ((int16_t)buf[2] << 8) | buf[3];
    *z = ((int16_t)buf[4] << 8) | buf[5];
    return 0;
}

void log_impact() {
    FILE *file = fopen(IMPACT_LOG_FILE, "a");
    if (file) {
        time_t now;
        time(&now);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0';  // Remove newline
        fprintf(file, "Impact detected at %s\n", timestamp);
        fclose(file);
    }
}

int main() {
    char filename[20];
    int16_t x, y, z;

    // Open I2C bus
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, MMA8451Q_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify sensor identity
    uint8_t who_am_i;
    if (i2c_read(i2c_fd, WHO_AM_I_REG, &who_am_i) != 1 || who_am_i != 0x1A) {
        fprintf(stderr, "Sensor identity verification failed\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize MMA8451Q
    i2c_write(i2c_fd, 0x2A, 0x01);  // Set to standby mode
    i2c_write(i2c_fd, 0x2A, 0x05);  // Set to active mode, 100 Hz data rate

    // Set up GPIO
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get LED GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        perror("Failed to request LED GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        close(i2c_fd);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring accelerometer...\n");

    while (running) {
        if (read_accel_data(&x, &y, &z) == 0) {
            double magnitude = sqrt(x*x + y*y + z*z);
            if (magnitude > IMPACT_THRESHOLD) {
                gpiod_line_set_value(led_line, 1);
                log_impact();
                usleep(500000);  // 500 ms
                gpiod_line_set_value(led_line, 0);
            }
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("Program terminated\n");

    return 0;
}

