    uint8_t who_am_i;
    if (i2c_read(i2c_fd, WHO_AM_I_REG, &who_am_i) != 1 || who_am_i != 0x1A) {
        fprintf(stderr, "Sensor identity verification failed\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize MMA8451Q
    i2c_write(i2c_fd, 0x2A, 0x01);  // Set to standby mode
    i2c_write(i2c_fd, 0x2A, 0x05);  // Set to active mode, 100 Hz data rate

    // Set up GPIO
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get LED GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        perror("Failed to request LED GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        close(i2c_fd);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring accelerometer...\n");

    while (running) {
        if (read_accel_data(&x, &y, &z) == 0) {
            double magnitude = sqrt(x*x + y*y + z*z);
            if (magnitude > IMPACT_THRESHOLD) {
                gpiod_line_set_value(led_line, 1);
                log_impact();
                usleep(500000);  // 500 ms
                gpiod_line_set_value(led_line, 0);
            }
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("Program terminated\n");

    return 0;
}
