    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }

    time_t last_log_time = 0;

    while (1) {
        time_t current_time = time(NULL);
        if (current_time != last_log_time) {
            uint16_t x = read_register(i2c_fd, X_REG);
            uint16_t y = read_register(i2c_fd, Y_REG);
            uint16_t z = read_register(i2c_fd, Z_REG);

            if (x || y || z) {
                time_t now;
                struct tm *tm_info;
                char timestamp[20];

                time(&now);
                tm_info = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

                fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
                fflush(log_file);
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }

            last_log_time = current_time;
        }
        sleep(1);
    }

    return EXIT_SUCCESS;
}

