#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/signalfd.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_MAP 0x2F
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_THRESH_FF 0x0A
#define ADXL345_REG_TIME_FF 0x20

#define EXPECTED_DEVID 0xE5
#define FREEFALL_THRESHOLD 300 // ~300 mg
#define FREEFALL_TIME 100 // ~100 ms
#define GPIO_PIN 17

static int i2c_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

static void i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, sizeof(buf)) != sizeof(buf)) {
        perror("I2C write error");
        exit(EXIT_FAILURE);
    }
}

static uint8_t i2c_read(int fd, uint8_t reg) {
    if (write(fd, &reg, sizeof(reg)) != sizeof(reg)) {
        perror("I2C read register error");
        exit(EXIT_FAILURE);
    }
    uint8_t value;
    if (read(fd, &value, sizeof(value)) != sizeof(value)) {
        perror("I2C read value error");
        exit(EXIT_FAILURE);
    }
    return value;
}

static void i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, sizeof(reg)) != sizeof(reg)) {
        perror("I2C read block register error");
        exit(EXIT_FAILURE);
    }
    if (read(fd, buf, len) != len) {
        perror("I2C read block data error");
        exit(EXIT_FAILURE);
    }
}

static void setup_sensor() {
    i2c_write(i2c_fd, ADXL345_REG_POWER_CTL, 0x00); // Enter standby mode
    usleep(10000); // Wait 10ms

    uint8_t devid = i2c_read(i2c_fd, ADXL345_REG_DEVID);
    if (devid != EXPECTED_DEVID) {
        fprintf(stderr, "Unexpected device ID: 0x%02X\n", devid);
        exit(EXIT_FAILURE);
    }

    i2c_write(i2c_fd, ADXL345_REG_THRESH_FF, FREEFALL_THRESHOLD / 62.5);
    i2c_write(i2c_fd, ADXL345_REG_TIME_FF, FREEFALL_TIME / 5);
    i2c_write(i2c_fd, ADXL345_REG_INT_ENABLE, 0x04); // Enable freefall interrupt
    i2c_write(i2c_fd, ADXL345_REG_INT_MAP, 0x00); // Map to INT1
    i2c_write(i2c_fd, ADXL345_REG_POWER_CTL, 0x08); // Enter measurement mode
}

static void log_freefall(int16_t x, int16_t y, int16_t z) {
    struct timespec ts;
    char timestamp[64];
    char data[128];

    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm *tm_info = localtime(&ts.tv_sec);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    snprintf(data, sizeof(data), "%s.%03ld,%d,%d,%d\n", timestamp, ts.tv_nsec / 1000000, x, y, z);

    if (fputs(data, log_file) == EOF || fflush(log_file) != 0) {
        perror("Error writing to log file");
        exit(EXIT_FAILURE);
    }
}

static void handle_freefall() {
    uint8_t int_source = i2c_read(i2c_fd, ADXL345_REG_INT_SOURCE);
    if (int_source & 0x04) { // Check freefall bit
        uint8_t data[6];
        i2c_read_block(i2c_fd, ADXL345_REG_DATAX0, data, sizeof(data));
        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];
        log_freefall(x, y, z);
    }
}

static void cleanup(int signum) {
    i2c_write(i2c_fd, ADXL345_REG_INT_ENABLE, 0x00); // Disable all interrupts
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    fclose(log_file);
    exit(EXIT_SUCCESS);
}

int main() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("I2C bus open error");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, ADXL345_ADDR) < 0) {
        perror("I2C set address error");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    setup_sensor();

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("GPIO chip open error");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("GPIO line get error");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_falling_edge_events(line, "ADXL345-Freefall-Interrupt") < 0) {
        perror("GPIO line request error");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    log_file = fopen("freefall_log.csv", "a");
    if (!log_file) {
        perror("Log file open error");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (ftell(log_file) == 0) {
        if (fputs("Timestamp,X,Y,Z\n", log_file) == EOF || fflush(log_file) != 0) {
            perror("Error writing header to log file");
            fclose(log_file);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }
    }

    struct signalfd_siginfo fdsi;
    int sfd = signalfd(-1, &(struct signalfd_sigevent){.sigev_notify = SIGFD}, SFD_CLOEXEC);
    if (sfd == -1) {
        perror("Signal file descriptor creation failed");
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    fd_set readfds;
    struct timeval tv;
    int gpio_fd = gpiod_line_event_fd(line);

    while (1) {
        FD_ZERO(&readfds);
        FD_SET(sfd, &readfds);
        FD_SET(gpio_fd, &readfds);

        tv.tv_sec = 1;
        tv.tv_usec = 0;

        int ret = select(FD_SETSIZE, &readfds, NULL, NULL, &tv);
        if (ret == -1) {
            perror("Select error");
            break;
        }

        if (ret > 0) {
            if (FD_ISSET(sfd, &readfds)) {
                if (read(sfd, &fdsi, sizeof(fdsi)) != sizeof(fdsi)) {
                    perror("Signal read error");
                    break;
                }
                cleanup(fdsi.ssi_signo);
            }

            if (FD_ISSET(gpio_fd, &readfds)) {
                handle_freefall();
            }
        }
    }

    cleanup(0);
    return 0;
}

