        exit(EXIT_FAILURE);
    }

    log_file = fopen("freefall_log.csv", "a");
    if (!log_file) {
        perror("Log file open error");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (ftell(log_file) == 0) {
        if (fputs("Timestamp,X,Y,Z\n", log_file) == EOF || fflush(log_file) != 0) {
            perror("Error writing header to log file");
            fclose(log_file);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }
    }

    struct signalfd_siginfo fdsi;
    int sfd = signalfd(-1, &(struct signalfd_sigevent){.sigev_notify = SIGFD}, SFD_CLOEXEC);
    if (sfd == -1) {
        perror("Signal file descriptor creation failed");
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    fd_set readfds;
    struct timeval tv;
    int gpio_fd = gpiod_line_event_fd(line);

    while (1) {
        FD_ZERO(&readfds);
        FD_SET(sfd, &readfds);
        FD_SET(gpio_fd, &readfds);

        tv.tv_sec = 1;
        tv.tv_usec = 0;

        int ret = select(FD_SETSIZE, &readfds, NULL, NULL, &tv);
        if (ret == -1) {
            perror("Select error");
            break;
        }

        if (ret > 0) {
            if (FD_ISSET(sfd, &readfds)) {
                if (read(sfd, &fdsi, sizeof(fdsi)) != sizeof(fdsi)) {
                    perror("Signal read error");
                    break;
                }
                cleanup(fdsi.ssi_signo);
            }

            if (FD_ISSET(gpio_fd, &readfds)) {
                handle_freefall();
            }
        }
    }

    cleanup(0);
    return 0;
}
