#define I2C_ADDR 0x6A
#define SDA_PIN 2
#define SCL_PIN 3
#define LOG_FILE "motion_log.txt"
#define ACCEL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 2.5
#define WINDOW_DURATION 1.0
#define SAMPLE_RATE 104

typedef enum {
    IDLE,
    FREEFALL,
    IMPACT
} State;

static volatile int keep_running = 1;

void signal_handler(int signo) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    return i2cWriteDevice(fd, buf, 2);
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    return i2cWriteDevice(fd, &reg, 1) && i2cReadDevice(fd, value, 1);
}

int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read(fd, 0x28, buf) != 2) return -1;
    *x = (buf[0] | (buf[1] << 8));
    if (i2c_read(fd, 0x2A, buf) != 2) return -1;
    *y = (buf[0] | (buf[1] << 8));
    if (i2c_read(fd, 0x2C, buf) != 2) return -1;
    *z = (buf[0] | (buf[1] << 8));
    return 0;
}

float accel_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrtf(x*x + y*y + z*z) / 16384.0; // LSB/g for +-2g
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i;
    if (i2c_read(i2c_handle, 0x0F, &who_am_i) != 1 || who_am_i != 0x69) {
        fprintf(stderr, "Sensor not detected or communication error\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure accelerometer and gyroscope
    i2c_write(i2c_handle, 0x10, 0x60); // ODR = 104 Hz, FS = +-2g
    i2c_write(i2c_handle, 0x11, 0x60); // ODR = 104 Hz, FS = +-250 dps

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    State state = IDLE;
    time_t fall_start_time = 0;
    float max_accel = 0;

    fprintf(log_file, "Timestamp,AccelX,AccelY,AccelZ,State\n");

    while (keep_running) {
        int16_t accel_x, accel_y, accel_z;
        if (read_accel(i2c_handle, &accel_x, &accel_y, &accel_z) != 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        float accel_mag = accel_magnitude(accel_x, accel_y, accel_z);
        time_t current_time = time(NULL);
        struct tm *tm_info = localtime(&current_time);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.3f,%.3f,%.3f,%d\n", timestamp, 
                accel_x / 16384.0, accel_y / 16384.0, accel_z / 16384.0, state);
        fflush(log_file);

        switch (state) {
            case IDLE:
                if (accel_mag < ACCEL_THRESHOLD) {
                    state = FREEFALL;
                    fall_start_time = current_time;
                    max_accel = accel_mag;
                }
                break;
            case FREEFALL:
                if (current_time - fall_start_time > WINDOW_DURATION) {
                    state = IDLE;
                } else if (accel_mag > max_accel) {
                    max_accel = accel_mag;
                }
                if (max_accel > IMPACT_THRESHOLD) {
                    state = IMPACT;
                }
                break;
            case IMPACT:
                if (accel_mag < ACCEL_THRESHOLD) {
                    state = FREEFALL;
                    fall_start_time = current_time;
                    max_accel = accel_mag;
                } else {
                    state = IDLE;
                }
                break;
        }

        usleep((1000000 / SAMPLE_RATE) - 1000); // Adjust for actual processing time
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

