#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define WHO_AM_I 0x00
#define X_GYRO_OUT 0x14
#define WHO_AM_I_EXPECTED 0x3F5A
#define SCALE_FACTOR 0.0305
#define READ_INTERVAL_MS 10

static FILE *log_file;
static int spi_handle;

void cleanup(int sig) {
    if (spi_handle >= 0) {
        gpioSPIClose(spi_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (gpioInitialised()) {
        gpioTerminate();
    }
    exit(sig);
}

int spi_transfer(int handle, uint8_t *tx, uint8_t *rx, int len) {
    int ret = gpioSPIXfer(handle, tx, rx, len);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", gpioFunction(ret));
        return -1;
    }
    return 0;
}

uint16_t read_register(uint8_t reg_addr) {
    uint8_t tx[2] = {reg_addr | 0x80, 0x00};
    uint8_t rx[2] = {0};

    if (spi_transfer(spi_handle, tx, rx, 2) != 0) {
        return 0xFFFF; // Error indicator
    }

    return (rx[0] << 8) | rx[1];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = gpioSPIOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI channel %d open failed: %s\n", SPI_CHANNEL, gpioFunction(spi_handle));
        gpioTerminate();
        return 1;
    }

    uint16_t who_am_i = read_register(WHO_AM_I);
    if (who_am_i != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "WHO_AM_I check failed: got 0x%04X, expected 0x%04X\n", who_am_i, WHO_AM_I_EXPECTED);
        cleanup(1);
    }

    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(1);
    }

    fprintf(log_file, "Timestamp (s),X_GYRO_OUT (deg/s)\n");
    fflush(log_file);

    signal(SIGINT, cleanup);

    struct timespec ts;
    double last_time = 0.0;

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        double current_time = ts.tv_sec + ts.tv_nsec * 1e-9;

        uint16_t gyro_value = read_register(X_GYRO_OUT);
        if (gyro_value != 0xFFFF) {
            double gyro_deg_sec = gyro_value * SCALE_FACTOR;
            fprintf(log_file, "%.6f,%.2f\n", current_time, gyro_deg_sec);
            fflush(log_file);
        }

        double sleep_time = last_time + READ_INTERVAL_MS / 1000.0 - current_time;
        if (sleep_time > 0) {
            nanosleep((const struct timespec[]){{0, (long)(sleep_time * 1e9)}}, NULL);
        }
        last_time = current_time;
    }

    return 0;
}

