#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define SAMPLE_RATE 10000 // 10 ms
#define SENSITIVITY 114.285

volatile sig_atomic_t terminate = 0;

void signalHandler(int signum) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2cHandle;
    for (int attempt = 0; attempt < 3; attempt++) {
        i2cHandle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
        if (i2cHandle >= 0) break;
        fprintf(stderr, "I2C open failed, attempt %d: %s\n", attempt + 1, strerror(errno));
        gpioSleep(1, 0, 200000000); // 200ms delay
    }

    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C device after 3 attempts\n");
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I register
    char whoAmI;
    if (i2cReadByteData(i2cHandle, WHO_AM_I, &whoAmI) < 0 || whoAmI != 0xD3) {
        fprintf(stderr, "WHO_AM_I verification failed\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (i2cWriteByteData(i2cHandle, CTRL_REG1, 0x0F) < 0 ||
        i2cWriteByteData(i2cHandle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    FILE *logFile = fopen("gyro_log.csv", "w");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    fprintf(logFile, "Timestamp,X,Y,Z\n");

    struct timespec ts;
    char buffer[20];
    char data[6];

    signal(SIGINT, signalHandler);

    while (!terminate) {
        if (i2cReadI2CBlock(i2cHandle, OUT_X_L, data, 6) < 0) {
            fprintf(stderr, "I2C read error\n");
            break;
        }

        clock_gettime(CLOCK_REALTIME_NS, &ts);
        snprintf(buffer, sizeof(buffer), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

        float x = (int16_t)(data[0] | (data[1] << 8)) / SENSITIVITY;
        float y = (int16_t)(data[2] | (data[3] << 8)) / SENSITIVITY;
        float z = (int16_t)(data[4] | (data[5] << 8)) / SENSITIVITY;

        fprintf(logFile, "%s,%.3f,%.3f,%.3f\n", buffer, x, y, z);
        fflush(logFile);

        gpioSleep(1, 0, SAMPLE_RATE);
    }

    fclose(logFile);
    i2cClose(i2cHandle);
    gpioTerminate();
    return 0;
}

