#define I2C_BUS "/dev/i2c-1"
#define SLAVE_ADDR 0x53
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "vibration_log.csv"

int i2c_fd;
FILE *log_file;

void signal_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C register");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return (buf[1] << 8) | buf[0];
}

int main() {
    struct timespec ts;
    struct tm *tm_info;
    char timestamp[64];

    signal(SIGINT, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SLAVE_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);

    while (1) {
        int16_t x, y, z;
        int16_t raw_x, raw_y, raw_z;

        raw_x = i2c_read_word(i2c_fd, 0x28);
        raw_y = i2c_read_word(i2c_fd, 0x2A);
        raw_z = i2c_read_word(i2c_fd, 0x2C);

        if (raw_x == -1 || raw_y == -1 || raw_z == -1) {
            fprintf(stderr, "Error reading sensor data, skipping sample\n");
            continue;
        }

        x = (int16_t)raw_x;
        y = (int16_t)raw_y;
        z = (int16_t)raw_z;

        clock_gettime(CLOCK_REALTIME, &ts);
        tm_info = gmtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
        fprintf(log_file, "%s.%09ldZ,%d,%d,%d\n", timestamp, ts.tv_nsec, x, y, z);
        fflush(log_file);

        nanosleep(&(struct timespec){0, SAMPLE_INTERVAL_MS * 1000000}, NULL);
    }

    return 0;
}

