#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LOG_FILE "conveyor_log.txt"
#define LOG_INTERVAL_MS 50

static struct gpiod_chip *chip;
static struct gpiod_line *sensor1_line, *sensor2_line;
static FILE *log_file;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_sensor_state(int sensor1_state, int sensor2_state) {
    struct timespec ts;
    char timestamp[64];

    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm *tm_info = localtime(&ts.tv_sec);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s.%03ld, Sensor1: %d, Sensor2: %d\n",
            timestamp, ts.tv_nsec / 1000000, sensor1_state, sensor2_state);
    fflush(log_file);
}

int main() {
    int ret;
    int sensor1_state, sensor2_state;

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines for sensors
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", SENSOR1_PIN);
        goto cleanup;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", SENSOR2_PIN);
        goto cleanup;
    }

    // Configure lines as inputs with pull-up
    ret = gpiod_line_request_input(sensor1_line, "sensor1", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to request input for GPIO %d\n", SENSOR1_PIN);
        goto cleanup;
    }

    ret = gpiod_line_request_input(sensor2_line, "sensor2", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to request input for GPIO %d\n", SENSOR2_PIN);
        goto cleanup;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (keep_running) {
        sensor1_state = gpiod_line_get_value(sensor1_line);
        sensor2_state = gpiod_line_get_value(sensor2_line);

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "Failed to read sensor values\n");
            break;
        }

        log_sensor_state(sensor1_state, sensor2_state);

        if (sensor1_state && sensor2_state) {
            printf("Both sensors triggered! Halting conveyor.\n");
            break;
        }

        usleep(LOG_INTERVAL_MS * 1000);
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

