#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <math.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define TILT_THRESHOLD 45.0
#define SAMPLE_RATE_HZ 100
#define SAMPLE_INTERVAL_US (1000000 / SAMPLE_RATE_HZ)

static int i2c_fd;
static FILE *log_file;

void signal_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    ssize_t bytes_written = write(fd, buf, sizeof(buf));
    if (bytes_written != sizeof(buf)) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting I2C register: %s\n", strerror(errno));
        return -1;
    }
    ssize_t bytes_read = read(fd, buf, len);
    if (bytes_read != len) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int16_t combine_bytes(uint8_t msb, uint8_t lsb) {
    return ((int16_t)msb << 8) | lsb;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t who_am_i;
    if (i2c_read(i2c_fd, WHO_AM_I_REG, &who_am_i, 1) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (who_am_i != 0x2A) {
        fprintf(stderr, "Error: Sensor WHO_AM_I mismatch. Got 0x%02X, expected 0x2A\n", who_am_i);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t ctrl_reg1;
    if (i2c_read(i2c_fd, CTRL_REG1, &ctrl_reg1, 1) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    ctrl_reg1 &= ~0x01;  // Clear active bit
    ctrl_reg1 &= ~0x38;  // Clear data rate bits
    ctrl_reg1 |= 0x02;   // Set data rate to 100 Hz
    ctrl_reg1 |= 0x01;   // Set active bit

    if (i2c_write(i2c_fd, CTRL_REG1, ctrl_reg1) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("fall_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t data[6];
    struct timespec ts;
    char timestamp[64];

    while (1) {
        if (i2c_read(i2c_fd, OUT_X_MSB, data, 6) != 0) {
            continue;
        }

        int16_t x = combine_bytes(data[0], data[1]) >> 4;
        int16_t y = combine_bytes(data[2], data[3]) >> 4;
        int16_t z = combine_bytes(data[4], data[5]) >> 4;

        double tilt_x = atan2(x, sqrt(y * y + z * z)) * 180.0 / M_PI;

        if (fabs(tilt_x) > TILT_THRESHOLD) {
            clock_gettime(CLOCK_REALTIME, &ts);
            struct tm *tm_info = localtime(&ts.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(log_file, "%s.%09ld X:%d Y:%d Z:%d\n", timestamp, ts.tv_nsec, x, y, z);
            fflush(log_file);
        }

        nanosleep(&ts, NULL);
    }

