#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADXL354B_SPI_READ 0x80
#define ADXL354B_SPI_MULTI 0x40
#define ADXL354B_XDATA 0x08
#define ADXL354B_YDATA 0x0B
#define ADXL354B_ZDATA 0x0E
#define ADXL354B_PARTID 0x01
#define ADXL354B_PARTID_EXPECTED 0x1D
#define ADXL354B_RESET 0x1F
#define ADXL354B_POWER_CTL 0x2D
#define ADXL354B_STATUS 0x04
#define ADXL354B_RUN 0x02
#define ADXL354B_STABLE 0x04
#define RETRY_COUNT 3
#define LOG_INTERVAL_MS 100

static int spi_handle;
static FILE *log_file;

void cleanup(int signum) {
    if (spi_handle >= 0) {
        gpioCloseSPI(spi_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int spi_transfer(uint8_t *tx, uint8_t *rx, int len) {
    int retries = 0;
    while (retries < RETRY_COUNT) {
        if (gpioSPIXfer(spi_handle, tx, rx, len) == len) {
            return 0;
        }
        retries++;
        usleep(1000); // 1ms delay before retry
    }
    return -1;
}

int adxl354b_read_register(uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = {ADXL354B_SPI_READ | ADXL354B_SPI_MULTI | reg, 0x00};
    uint8_t rx[2];
    if (spi_transfer(tx, rx, 2) != 0) {
        return -1;
    }
    *value = rx[1];
    return 0;
}

int adxl354b_write_register(uint8_t reg, uint8_t value) {
    uint8_t tx[2] = {reg, value};
    return spi_transfer(tx, NULL, 2);
}

int adxl354b_reset() {
    if (adxl354b_write_register(ADXL354B_RESET, 0x52) != 0) {
        return -1;
    }
    gpioDelay(1000); // 1ms delay
    return 0;
}

int adxl354b_init() {
    uint8_t partid;
    if (adxl354b_read_register(ADXL354B_PARTID, &partid) != 0 || partid != ADXL354B_PARTID_EXPECTED) {
        return -1;
    }

    if (adxl354b_reset() != 0) {
        return -1;
    }

    uint8_t power_ctl;
    if (adxl354b_read_register(ADXL354B_POWER_CTL, &power_ctl) != 0) {
        return -1;
    }
    power_ctl &= ~ADXL354B_RUN;
    if (adxl354b_write_register(ADXL354B_POWER_CTL, power_ctl) != 0) {
        return -1;
    }

    uint8_t status;
    do {
        if (adxl354b_read_register(ADXL354B_STATUS, &status) != 0) {
            return -1;
        }
    } while (!(status & ADXL354B_STABLE));

    power_ctl |= ADXL354B_RUN;
    if (adxl354b_write_register(ADXL354B_POWER_CTL, power_ctl) != 0) {
        return -1;
    }

    return 0;
}

int adxl354b_read_accel(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (adxl354b_read_register(ADXL354B_XDATA, data) != 0) {
        return -1;
    }
    *x = ((int16_t)data[0] << 8) | data[1];
    *x >>= 4; // 20-bit to 16-bit

    if (adxl354b_read_register(ADXL354B_YDATA, data) != 0) {
        return -1;
    }
    *y = ((int16_t)data[0] << 8) | data[1];
    *y >>= 4;

    if (adxl354b_read_register(ADXL354B_ZDATA, data) != 0) {
        return -1;
    }
    *z = ((int16_t)data[0] << 8) | data[1];
    *z >>= 4;

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = gpioSPIOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl354b_init() != 0) {
        fprintf(stderr, "ADXL354B initialization failed\n");
        gpioCloseSPI(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("vibration_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioCloseSPI(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    time_t last_log_time = time(NULL);
    while (1) {
        int16_t x, y, z;
        if (adxl354b_read_accel(&x, &y, &z) == 0) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_log_time) >= LOG_INTERVAL_MS / 1000.0) {
                fprintf(log_file, "%ld,%d,%d,%d\n", (long)current_time, x, y, z);
                fflush(log_file);
                last_log_time = current_time;
            }
        }
        gpioDelay(10000); // 10ms loop delay
    }

    return EXIT_SUCCESS;
}

