    while (1) {
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "clock_gettime failed\n");
            break;
        }
        timestamp = ts.tv_sec + ts.tv_nsec * 1e-9;

        gyro_x = spi_read_word(spi_handle, X_GYRO);
        gyro_y = spi_read_word(spi_handle, Y_GYRO);
        gyro_z = spi_read_word(spi_handle, Z_GYRO);
        accel_x = spi_read_word(spi_handle, X_ACCL);
        accel_y = spi_read_word(spi_handle, Y_ACCL);
        accel_z = spi_read_word(spi_handle, Z_ACCL);

        if (gyro_x >= 0 && gyro_y >= 0 && gyro_z >= 0 &&
            accel_x >= 0 && accel_y >= 0 && accel_z >= 0) {
            fprintf(log_file, "%.9f,%.2f,%.2f,%.2f,%.4f,%.4f,%.4f\n",
