                    gyro_z * GYRO_SCALE,
                    accel_x * ACCL_SCALE,
                    accel_y * ACCL_SCALE,
                    accel_z * ACCL_SCALE);
            fflush(log_file);
        }

        time_sleep(READ_DELAY_MS / 1000.0);
    }

    signal_handler(SIGINT);
    return EXIT_SUCCESS;
