#include <time.h>

#define GPIO_CHIP "gpiochip4"
#define GPIO_PIN 17
#define POLL_INTERVAL_SECONDS 1

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void cleanup(int signum) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Cleanup completed.\n");
    exit(EXIT_SUCCESS);
}

int main() {
    int value;
    struct timespec ts;
    struct tm *tm_info;
    char timestamp[64];

    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open gpiochip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", GPIO_PIN);
        cleanup(0);
    }

    int ret = gpiod_line_request_input(line, "IR_Sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request line as input\n");
        cleanup(0);
    }

    while (1) {
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line value\n");
            cleanup(0);
        }

        time(&ts.tv_sec);
        tm_info = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        if (value == 0) {
            printf("[%s] Obstacle detected. Self-parking sequence started.\n", timestamp);
            sleep(2); // Simulate self-parking duration
            printf("[%s] Self-parking sequence completed.\n", timestamp);
        }

        sleep(POLL_INTERVAL_SECONDS);
    }

    return EXIT_SUCCESS;
}

