#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

#define CHIP_PATH "/dev/gpiochip0"
#define LINE_OFFSETS {17, 27}
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    (void)signum;
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[2];
    struct gpiod_line_bulk bulk;
    int values[2];
    int ret;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open(CHIP_PATH);
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip\n");
        return EXIT_FAILURE;
    }

    gpiod_line_bulk_init(&bulk);
    for (int i = 0; i < 2; i++) {
        lines[i] = gpiod_chip_get_line(chip, LINE_OFFSETS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d\n", LINE_OFFSETS[i]);
            goto cleanup;
        }
        gpiod_line_bulk_add(&bulk, lines[i]);
    }

    ret = gpiod_line_request_bulk_input(&bulk, "obstacle_sensors");
    if (ret < 0) {
        fprintf(stderr, "Error requesting bulk input\n");
        goto cleanup;
    }

    printf("Starting obstacle avoidance system...\n");

    while (keep_running) {
        ret = gpiod_line_request_get_values(&bulk, values);
        if (ret < 0) {
            fprintf(stderr, "Error reading sensor values\n");
            break;
        }

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        printf("[%s] Sensor 1: %s, Sensor 2: %s\n",
               timestamp,
               values[0] ? "Path clear" : "Obstacle detected",
               values[1] ? "Path clear" : "Obstacle detected");

        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    gpiod_line_release_bulk(&bulk);
    for (int i = 0; i < 2; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

