#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN 8
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000
#define READ_INTERVAL_MS 100
#define MSC_CTRL_REG 0x24
#define X_GYRO_REG 0x04
#define Y_GYRO_REG 0x06
#define Z_GYRO_REG 0x08
#define SCALE_FACTOR 0.02

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    return ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
}

int main() {
    int spi_fd, gpio_fd;
    struct gpiod_line *cs_line;
    struct gpiod_line_request_config cs_config = {
        .consumer = "ADIS16266_CS",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .flags = 0,
    };
    uint8_t tx[2], rx[6];
    int16_t gyro_x, gyro_y, gyro_z;

    signal(SIGINT, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Configure SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to configure SPI");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    gpio_fd = gpiod_open("/dev/gpiochip0");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Get CS line
    cs_line = gpiod_get_line(gpio_fd, CS_PIN);
    if (!cs_line) {
        perror("Failed to get CS line");
        gpiod_close(gpio_fd);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Request CS line
    if (gpiod_line_request(cs_line, &cs_config, 0) < 0) {
        perror("Failed to request CS line");
        gpiod_line_release(cs_line);
        gpiod_close(gpio_fd);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Enable data ready mode
    tx[0] = MSC_CTRL_REG | 0x80;
    tx[1] = 0x01;
    if (spi_transfer(spi_fd, tx, rx, 2) < 0) {
        perror("Failed to enable data ready mode");
        gpiod_line_release(cs_line);
        gpiod_close(gpio_fd);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("ADIS16266 gyroscope data logging started\n");

    while (keep_running) {
        // Read X gyro
        tx[0] = X_GYRO_REG | 0x80;
        if (spi_transfer(spi_fd, tx, rx, 2) < 0) {
            perror("Failed to read X gyro");
            continue;
        }
        gyro_x = (int16_t)((rx[0] << 8) | rx[1]);

        // Read Y gyro
        tx[0] = Y_GYRO_REG | 0x80;
        if (spi_transfer(spi_fd, tx, rx, 2) < 0) {
            perror("Failed to read Y gyro");
            continue;
        }
        gyro_y = (int16_t)((rx[0] << 8) | rx[1]);

        // Read Z gyro
        tx[0] = Z_GYRO_REG | 0x80;
        if (spi_transfer(spi_fd, tx, rx, 2) < 0) {
            perror("Failed to read Z gyro");
            continue;
        }
        gyro_z = (int16_t)((rx[0] << 8) | rx[1]);

        // Convert and log results
        printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n",
               gyro_x * SCALE_FACTOR, gyro_y * SCALE_FACTOR, gyro_z * SCALE_FACTOR);

        usleep(READ_INTERVAL_MS * 1000);
    }

    printf("ADIS16266 gyroscope data logging stopped\n");

    // Clean up
    gpiod_line_release(cs_line);
    gpiod_close(gpio_fd);
    close(spi_fd);

    return EXIT_SUCCESS;
}

