#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x1D
#define WHO_AM_I 0x0D
#define WHO_AM_I_EXPECTED 0xC7
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define M_CTRL_REG1 0x5B
#define M_CTRL_REG2 0x5C
#define OUT_X_MSB 0x01
#define READ_RETRIES 3
#define RETRY_DELAY_MS 100

void cleanup(int sig) {
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    int i2c_handle;
    int retry_count;
    uint8_t who_am_i;

    for (retry_count = 0; retry_count < READ_RETRIES; retry_count++) {
        if ((i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0)) < 0) {
            fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (i2cReadByteData(i2c_handle, WHO_AM_I, &who_am_i) < 0) {
            fprintf(stderr, "Failed to read WHO_AM_I\n");
            i2cClose(i2c_handle);
            continue;
        }

        if (who_am_i == WHO_AM_I_EXPECTED) {
            break;
        } else {
            fprintf(stderr, "WHO_AM_I mismatch: 0x%02X\n", who_am_i);
            i2cClose(i2c_handle);
            usleep(RETRY_DELAY_MS * 1000);
        }
    }

    if (retry_count == READ_RETRIES) {
        fprintf(stderr, "Failed to verify sensor presence after %d attempts\n", READ_RETRIES);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure sensor for hybrid mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x27) < 0 || // Active, 100Hz data rate
        i2cWriteByteData(i2c_handle, CTRL_REG2, 0x00) < 0 || // Hybrid mode
        i2cWriteByteData(i2c_handle, M_CTRL_REG1, 0x1F) < 0 || // Active, 100Hz data rate
        i2cWriteByteData(i2c_handle, M_CTRL_REG2, 0x20) < 0) { // Hybrid mode
        fprintf(stderr, "Failed to configure sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t data[12];
    int16_t accel[3], mag[3];

    while (1) {
        if (i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, data, 12) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        // Parse accelerometer data (14-bit left-aligned)
        accel[0] = ((int16_t)data[0] << 6) | (data[1] >> 2);
        accel[1] = ((int16_t)data[2] << 6) | (data[3] >> 2);
        accel[2] = ((int16_t)data[4] << 6) | (data[5] >> 2);

        // Parse magnetometer data (16-bit)
        mag[0] = (int16_t)((data[6] << 8) | data[7]);
        mag[1] = (int16_t)((data[8] << 8) | data[9]);
        mag[2] = (int16_t)((data[10] << 8) | data[11]);

        printf("Accel: X=%d Y=%d Z=%d | Mag: X=%d Y=%d Z=%d\n",
               accel[0], accel[1], accel[2], mag[0], mag[1], mag[2]);

        usleep(100000); // 100ms
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

