#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define DATA_FORMAT_REG 0x31
#define DATAX0_REG 0x32
#define DATAY0_REG 0x34
#define DATAZ0_REG 0x36
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define LOG_INTERVAL_MS 100

int i2c_fd;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, value, 1);
}

int16_t read_accel(int fd, uint8_t reg) {
    uint8_t buf[2];
    if (i2c_read(fd, reg, buf) != 2) {
        return 0;
    }
    return (int16_t)((buf[1] << 8) | buf[0]);
}

void log_tilt_event(double x_tilt, double y_tilt) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0';  // Remove newline

    fprintf(log_file, "[%s] Tilt Event - X: %.2f°, Y: %.2f°\n", time_str, x_tilt, y_tilt);
    fclose(log_file);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set data format to full resolution, +/- 2g
    if (i2c_write(i2c_fd, DATA_FORMAT_REG, 0x0B) != 2) {
        perror("Failed to set data format");
        cleanup(0);
    }

    struct timespec last_log_time = {0, 0};
    while (1) {
        int16_t x = read_accel(i2c_fd, DATAX0_REG);
        int16_t y = read_accel(i2c_fd, DATAY0_REG);
        int16_t z = read_accel(i2c_fd, DATAZ0_REG);

        if (x == 0 && y == 0 && z == 0) {
            fprintf(stderr, "Sensor read error or no sensor detected\n");
            cleanup(0);
        }

        double x_tilt = atan2(y, sqrt(x * x + z * z)) * 180 / M_PI;
        double y_tilt = atan2(x, sqrt(y * y + z * z)) * 180 / M_PI;

        struct timespec current_time;
        clock_gettime(CLOCK_MONOTONIC, &current_time);

        long elapsed_ms = (current_time.tv_sec - last_log_time.tv_sec) * 1000 +
                          (current_time.tv_nsec - last_log_time.tv_nsec) / 1000000;

        if (elapsed_ms >= LOG_INTERVAL_MS) {
            if (fabs(x_tilt) > TILT_THRESHOLD || fabs(y_tilt) > TILT_THRESHOLD) {
                log_tilt_event(x_tilt, y_tilt);
            }
            last_log_time = current_time;
        }

        usleep(10000);  // 10ms delay
    }

    cleanup(0);
}

