#include <time.h>

#define PIN 17
#define WINDOW_DURATION 5000 // 5 seconds in milliseconds
#define SAMPLE_INTERVAL 1 // 1 millisecond
#define ALERT_INTERVAL 1000 // 1 second

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    int threshold;
    char *endptr;
    threshold = strtol(argv[1], &endptr, 10);

    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold. Please provide a positive integer.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_alert_time = 0;

    while (keep_running) {
        int high_count = 0;
        time_t start_time = time(NULL);

        for (int i = 0; i < WINDOW_DURATION / SAMPLE_INTERVAL; i++) {
            if (gpioRead(PIN) == PI_HIGH) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL * 1000); // gpioDelay uses microseconds

            if (!keep_running) break;
        }

        time_t current_time = time(NULL);
        if (high_count >= threshold) {
            printf("[%s] ALERT: High readings (%d) exceeded threshold (%d)\n", 
                   ctime(&current_time), high_count, threshold);
            last_alert_time = current_time;
        } else {
            printf("[%s] Status: High readings (%d) below threshold (%d)\n", 
                   ctime(&current_time), high_count, threshold);
        }

        // Ensure at least 1 second between monitoring windows
        time_t elapsed = current_time - start_time;
        if (elapsed < 1) {
            gpioDelay((1 - elapsed) * 1000000);
        }

        // Ensure at least 1 second between alerts
        if (difftime(current_time, last_alert_time) < 1) {
            time_t wait_time = last_alert_time + 1 - current_time;
            gpioDelay(wait_time * 1000000);
        }
    }

    gpioTerminate();
    return 0;
}

