#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

#define DOOR_A_PIN 17
#define DOOR_B_PIN 27
#define DOOR_UNLOCK_TIME 5

volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int signum) {
    exit_flag = 1;
}

void set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO value: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *door_a, *door_b;
    int random_code;
    FILE *log_file;
    char log_entry[50];
    time_t now;
    struct tm *timeinfo;

    srand(time(NULL));
    random_code = rand() % 900000 + 100000;
    printf("Security Code: %d\n", random_code);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    door_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!door_a) {
        fprintf(stderr, "Failed to get line for Door A: %s\n", strerror(errno));
        goto cleanup;
    }

    door_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!door_b) {
        fprintf(stderr, "Failed to get line for Door B: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(door_a, "DoorA", 0) < 0 ||
        gpiod_line_request_output(door_b, "DoorB", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as output: %s\n", strerror(errno));
        goto cleanup;
    }

    log_file = fopen("access_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        goto cleanup;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (!exit_flag) {
        int input_code;
        printf("Enter the security code: ");
        if (scanf("%d", &input_code) != 1) {
            printf("Invalid input. Please enter a numeric code.\n");
            while (getchar() != '\n'); // Clear input buffer
            continue;
        }

        if (input_code == random_code) {
            set_gpio_value(door_a, 1);
            time(&now);
            timeinfo = localtime(&now);
            strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S,%06d\n", timeinfo, random_code);
            fputs(log_entry, log_file);
            fflush(log_file);
            printf("Access granted. Door A unlocked.\n");
            sleep(DOOR_UNLOCK_TIME);
            set_gpio_value(door_a, 0);
            printf("Door A locked.\n");
            random_code = rand() % 900000 + 100000;
            printf("New security code: %d\n", random_code);
        } else {
            printf("Access denied.\n");
        }
    }

cleanup:
    if (log_file) fclose(log_file);
    if (door_a) gpiod_line_release(door_a);
    if (door_b) gpiod_line_release(door_b);
    if (chip) gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

