#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <syslog.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x23
#define SENSOR_COMMAND 0x21
#define CONVERSION_TIME_MS 180
#define LOG_FILE "light_log.txt"

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    int file_desc, ret;
    unsigned char buffer[2];
    FILE *log_file;
    struct timespec ts;
    struct tm *tm_info;
    char timestamp[64];

    // Open I2C bus
    file_desc = open(I2C_BUS, O_RDWR);
    if (file_desc < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(file_desc, I2C_SLAVE_FORCE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(file_desc);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(file_desc);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    while (keep_running) {
        // Send command to sensor
        buffer[0] = SENSOR_COMMAND;
        ret = write(file_desc, buffer, 1);
        if (ret != 1) {
            perror("Failed to write to sensor");
            break;
        }

        // Wait for conversion time
        usleep(CONVERSION_TIME_MS * 1000);

        // Read data from sensor
        ret = read(file_desc, buffer, 2);
        if (ret != 2) {
            perror("Failed to read from sensor");
            break;
        }

        // Calculate lux
        unsigned int raw_value = (buffer[0] << 8) | buffer[1];
        float lux = (float)raw_value / 1.2;

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        tm_info = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Log the reading
        fprintf(log_file, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
        fflush(log_file);

        // Wait for 5 seconds before next reading
        sleep(5);
    }

    // Clean up
    fclose(log_file);
    close(file_desc);

    return EXIT_SUCCESS;
}

