#define SERVER_PORT 12345
#define SHARED_SECRET "MySecretKey"
#define MOTION_DETECTED_PREFIX "MOTION_DETECTED:"
#define SAMPLE_INTERVAL_MS 20
#define PLAYBACK_DURATION_MS 5000
#define MIN_FREQ 220.0
#define MAX_FREQ 880.0
#define LOG_FILE "frequency_log.txt"

static int i2c_handle;
static int gpio_pwm;
static int server_socket;
static int client_socket;

void cleanup(void) {
    if (gpio_pwm >= 0) {
        gpioPWM(gpio_pwm, 0);
        gpioSetMode(gpio_pwm, PI_INPUT);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (client_socket >= 0) {
        close(client_socket);
    }
    if (server_socket >= 0) {
        close(server_socket);
    }
    gpioTerminate();
}

void signal_handler(int signo) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int init_mpr121(void) {
    unsigned char data[2];
    // Soft reset
    data[0] = 0x60;
    data[1] = 0x00;
    if (i2cWriteDevice(i2c_handle, data, 2) < 0) return -1;
    time_sleep(0.01);

    // Configure electrodes
    data[0] = 0x5E;
    data[1] = 0x00;
    if (i2cWriteDevice(i2c_handle, data, 2) < 0) return -1;
    time_sleep(0.01);

    return 0;
}

float map_to_frequency(int value) {
    return MIN_FREQ + (MAX_FREQ - MIN_FREQ) * log10f(1 + (float)value / 4095);
}

void play_theremin(void) {
    unsigned char data[2];
    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t start_time = time(NULL);
    while (difftime(time(NULL), start_time) * 1000 < PLAYBACK_DURATION_MS) {
        data[0] = 0x00;
        if (i2cReadI2CBlock(i2c_handle, 0x00, data, 2) < 0) {
            fprintf(stderr, "Failed to read touch data\n");
            fclose(log_file);
            return;
        }

        int touch_value = (data[0] << 4) | (data[1] >> 4);
        float frequency = map_to_frequency(touch_value);
        fprintf(log_file, "%.2f\n", frequency);

        int pwm_duty = (int)(frequency * 255 / 1000);
        gpioPWM(gpio_pwm, pwm_duty);

        time_sleep(SAMPLE_INTERVAL_MS / 1000.0);
    }

    fclose(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_mpr121() < 0) {
        fprintf(stderr, "Failed to initialize MPR121\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpio_pwm = PWM_PIN;
    gpioSetMode(gpio_pwm, PI_OUTPUT);
    gpioPWM(gpio_pwm, 0);

    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        fprintf(stderr, "Failed to create socket\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(SERVER_PORT);

    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Failed to bind socket\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (listen(server_socket, 1) < 0) {
        fprintf(stderr, "Failed to listen on socket\n");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Waiting for client connection...\n");
    client_socket = accept(server_socket, NULL, NULL);
    if (client_socket < 0) {
        fprintf(stderr, "Failed to accept client connection\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Client connected. Waiting for motion detection...\n");
    char buffer[256];
    ssize_t bytes_read = read(client_socket, buffer, sizeof(buffer) - 1);
    if (bytes_read > 0) {
        buffer[bytes_read] = '\0';
        if (strncmp(buffer, MOTION_DETECTED_PREFIX, strlen(MOTION_DETECTED_PREFIX)) == 0 &&
            strstr(buffer, SHARED_SECRET) != NULL) {
            printf("Motion detected with valid secret. Playing theremin...\n");
            play_theremin();
        } else {
            printf("Invalid motion detection message\n");
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}
