#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define MAGNETOMETER_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define LED_GPIO 17
#define PWM_FREQUENCY 1000
#define SAMPLE_INTERVAL_MS 100

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static int running = 1;

void cleanup(int signum) {
    running = 0;
    if (led_line) {
        gpiod_line_release(led_line);
        gpiod_line_close(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MAGNETOMETER_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int init_magnetometer() {
    unsigned char init_data = 0x18; // 10 Hz continuous conversion
    if (write(i2c_fd, &init_data, 1) != 1) {
        perror("Failed to write to CTRL_REG1_M");
        return -1;
    }
    return 0;
}

int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    unsigned char buffer[6];
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Failed to read magnetometer data");
        return -1;
    }

    *x = (buffer[1] << 8) | buffer[0];
    *y = (buffer[3] << 8) | buffer[2];
    *z = (buffer[5] << 8) | buffer[4];

    return 0;
}

int init_led_pwm() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request(led_line, "LED", GPIOD_LINE_REQ_DIR_OUT, 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_close(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Set PWM frequency
    char pwm_path[64];
    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwm0");
    if (mkdir(pwm_path, 0755) < 0 && errno != EEXIST) {
        perror("Failed to create PWM directory");
        return -1;
    }

    FILE *fp = fopen("/sys/class/pwm/pwm0/period", "w");
    if (!fp) {
        perror("Failed to set PWM period");
        return -1;
    }
    fprintf(fp, "%u", 1000000000 / PWM_FREQUENCY);
    fclose(fp);

    fp = fopen("/sys/class/pwm/pwm0/duty_cycle", "w");
    if (!fp) {
        perror("Failed to set PWM duty cycle");
        return -1;
    }
    fprintf(fp, "0");
    fclose(fp);

    fp = fopen("/sys/class/pwm/pwm0/enable", "w");
    if (!fp) {
        perror("Failed to enable PWM");
        return -1;
    }
    fprintf(fp, "1");
    fclose(fp);

    return 0;
}

int set_led_brightness(int brightness) {
    char pwm_path[64];
    snprintf(pwm_path, sizeof(pwm_path), "/sys/class/pwm/pwm0/duty_cycle");
    FILE *fp = fopen(pwm_path, "w");
    if (!fp) {
        perror("Failed to set PWM duty cycle");
        return -1;
    }
    fprintf(fp, "%d", brightness);
    fclose(fp);
    return 0;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (init_i2c() < 0 || init_magnetometer() < 0 || init_led_pwm() < 0) {
        fprintf(stderr, "Initialization failed\n");
        cleanup(0);
    }

    while (running) {
        int16_t x, y, z;
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            float z_magnitude = sqrtf(x*x + y*y + z*z);
            int brightness = (int)(z_magnitude / 1000.0 * 1000000); // Scale to 0-1000000
            set_led_brightness(brightness);
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup(0);
    return 0;
}

