#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define SAMPLES 100
#define SAMPLE_INTERVAL_MS 500
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA 0x03

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Configure HMC5883L
    if (i2cWriteByteData(I2C_ADDR, HMC5883L_CONFIG_A, 0x70) < 0 ||
        i2cWriteByteData(I2C_ADDR, HMC5883L_CONFIG_B, 0x20) < 0 ||
        i2cWriteByteData(I2C_ADDR, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Failed to configure HMC5883L\n");
        i2cClose(I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    int16_t offsets[3] = {0};
    int16_t raw[3] = {0};
    int16_t corrected[3] = {0};

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        // Collect raw readings
        for (int i = 0; i < SAMPLES; i++) {
            if (i2cReadI2CBlock(I2C_ADDR, HMC5883L_DATA, 6, (char *)raw) < 0) {
                fprintf(stderr, "I2C read error\n");
                continue;
            }

            for (int j = 0; j < 3; j++) {
                offsets[j] += raw[j];
            }

            usleep(10000); // 10ms delay between samples
        }

        // Calculate average offsets
        for (int i = 0; i < 3; i++) {
            offsets[i] /= SAMPLES;
        }

        // Apply offsets and print corrected values
        while (keep_running) {
            if (i2cReadI2CBlock(I2C_ADDR, HMC5883L_DATA, 6, (char *)raw) < 0) {
                fprintf(stderr, "I2C read error\n");
                continue;
            }

            for (int i = 0; i < 3; i++) {
                corrected[i] = raw[i] - offsets[i];
            }

            printf("X: %d, Y: %d, Z: %d\n", corrected[0], corrected[1], corrected[2]);

            usleep(SAMPLE_INTERVAL_MS * 1000);
        }
    }

    i2cClose(I2C_ADDR);
    gpioTerminate();
    return 0;
}

