#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define LSM303D_ADDR 0x1D
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VAL 0x49
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define INT1_CFG 0x30
#define INT1_THS 0x32
#define INT1_DURATION 0x33
#define OUT_X_L_A 0x28 | 0x80
#define BUFFER_SIZE 64
#define SAMPLE_INTERVAL_MS 10

typedef struct {
    int16_t x, y, z;
} AccelSample;

AccelSample buffer[BUFFER_SIZE];
int buffer_index = 0;
int i2c_fd;
struct gpiod_line *int1_line;

void die(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (int1_line) {
        gpiod_line_release(int1_line);
    }
}

void signal_handler(int signum) {
    if (signum == SIGINT) {
        // Disable accelerometer
        if (ioctl(i2c_fd, I2C_SLAVE_FORCE, LSM303D_ADDR) < 0) {
            die("Failed to set I2C slave address");
        }
        if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG1, 0x00) < 0) {
            die("Failed to disable accelerometer");
        }
        cleanup();
        exit(EXIT_SUCCESS);
    }
}

void init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        die("Failed to open I2C bus");
    }
    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, LSM303D_ADDR) < 0) {
        die("Failed to set I2C slave address");
    }
    uint8_t who_am_i = i2c_smbus_read_byte_data(i2c_fd, WHO_AM_I_REG);
    if (who_am_i != WHO_AM_I_VAL) {
        die("WHO_AM_I check failed");
    }
    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG1, 0x57) < 0) {
        die("Failed to configure accelerometer");
    }
    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG4, 0x00) < 0) {
        die("Failed to set accelerometer full-scale");
    }
    if (i2c_smbus_write_byte_data(i2c_fd, INT1_CFG, 0x2A) < 0) {
        die("Failed to configure interrupt");
    }
    if (i2c_smbus_write_byte_data(i2c_fd, INT1_THS, 0x7D) < 0) {
        die("Failed to set interrupt threshold");
    }
    if (i2c_smbus_write_byte_data(i2c_fd, INT1_DURATION, 0x00) < 0) {
        die("Failed to set interrupt duration");
    }
}

void init_gpio() {
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        die("Failed to open GPIO chip");
    }
