int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SOLENOID1_PIN);
    if (!line1) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", SOLENOID1_PIN);
        cleanup(0);
    }

    line2 = gpiod_chip_get_line(chip, SOLENOID2_PIN);
    if (!line2) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", SOLENOID2_PIN);
        cleanup(0);
    }

    if (gpiod_line_request_output(line1, "solenoid1", 0) < 0 ||
        gpiod_line_request_output(line2, "solenoid2", 0) < 0) {
        fprintf(stderr, "Failed to request lines as output\n");
        cleanup(0);
    }

    struct timespec delay = {
        .tv_sec = DELAY_MS / 1000,
        .tv_nsec = (DELAY_MS % 1000) * 1000000
    };

    while (1) {
        if (gpiod_line_set_value(line1, 1) < 0) {
            fprintf(stderr, "Failed to set solenoid1 HIGH\n");
            cleanup(0);
        }
        if (nanosleep(&delay, NULL) < 0) {
            perror("nanosleep failed");
            cleanup(0);
        }

        if (gpiod_line_set_value(line1, 0) < 0) {
            fprintf(stderr, "Failed to set solenoid1 LOW\n");
            cleanup(0);
        }

        if (gpiod_line_set_value(line2, 1) < 0) {
            fprintf(stderr, "Failed to set solenoid2 HIGH\n");
            cleanup(0);
        }
        if (nanosleep(&delay, NULL) < 0) {
            perror("nanosleep failed");
            cleanup(0);
        }

        if (gpiod_line_set_value(line2, 0) < 0) {
            fprintf(stderr, "Failed to set solenoid2 LOW\n");
            cleanup(0);
        }
    }

    return EXIT_SUCCESS;
}

