#define LOCK_PIN_1 17
#define LOCK_PIN_2 27
#define PRIMARY_UART "/dev/serial0"
#define SECONDARY_UART "/dev/serial1"
#define BAUD_RATE B9600
#define EXPECTED_CODE "123456"
#define TIMEOUT_MS 5000

static int uart0_fd = -1, uart1_fd = -1;

void cleanup(int sig) {
    if (uart0_fd != -1) close(uart0_fd);
    if (uart1_fd != -1) close(uart1_fd);
    gpioWrite(LOCK_PIN_1, LOW);
    gpioWrite(LOCK_PIN_2, LOW);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int set_interface_attribs(int fd, int speed, int parity) {
    struct termios tty;
    if (tcgetattr(fd, &tty) < 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        return -1;
    }

    cfsetospeed(&tty, speed);
    cfsetispeed(&tty, speed);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;                         // disable break processing
    tty.c_lflag = 0;                                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                                // no remapping, no delays
    tty.c_cc[VMIN]  = 0;                            // read doesn't block
    tty.c_cc[VTIME] = 5;                            // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);         // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);                // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD);              // shut off parity
    tty.c_cflag |= parity;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(LOCK_PIN_1, PI_OUTPUT);
    gpioSetMode(LOCK_PIN_2, PI_OUTPUT);
    gpioWrite(LOCK_PIN_1, LOW);
    gpioWrite(LOCK_PIN_2, LOW);

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    uart0_fd = open(PRIMARY_UART, O_RDWR | O_NOCTTY | O_SYNC);
    uart1_fd = open(SECONDARY_UART, O_RDWR | O_NOCTTY | O_SYNC);

    if (uart0_fd < 0 || uart1_fd < 0) {
        fprintf(stderr, "Error opening serial ports\n");
        cleanup(0);
    }

    if (set_interface_attribs(uart0_fd, BAUD_RATE, 0) < 0 ||
        set_interface_attribs(uart1_fd, BAUD_RATE, 0) < 0) {
        cleanup(0);
    }

    char code0[7] = {0}, code1[7] = {0};
    int code0_len = 0, code1_len = 0;
    struct timeval tv = {.tv_sec = 0, .tv_usec = 100000}; // 100ms timeout for non-blocking read

    while (1) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(uart0_fd, &readfds);
        FD_SET(uart1_fd, &readfds);

        if (select(FD_SETSIZE, &readfds, NULL, NULL, &tv) > 0) {
            if (FD_ISSET(uart0_fd, &readfds)) {
                int n = read(uart0_fd, code0 + code0_len, 1);
                if (n > 0 && code0_len < 6 && (code0[code0_len] = code0[code0_len]) >= '0' && code0[code0_len] <= '9') {
                    code0_len++;
                } else {
                    code0_len = 0;
                }
            }
            if (FD_ISSET(uart1_fd, &readfds)) {
                int n = read(uart1_fd, code1 + code1_len, 1);
                if (n > 0 && code1_len < 6 && (code1[code1_len] = code1[code1_len]) >= '0' && code1[code1_len] <= '9') {
                    code1_len++;
                } else {
                    code1_len = 0;
                }
            }
        }

        if (code0_len == 6 && code1_len == 6) {
            if (timing_safe_memcmp(code0, EXPECTED_CODE, 6) == 0 &&
                timing_safe_memcmp(code1, EXPECTED_CODE, 6) == 0) {
                gpioWrite(LOCK_PIN_1, HIGH);
                gpioWrite(LOCK_PIN_2, HIGH);
                usleep(2000000); // 2 seconds
            }
            code0_len = code1_len = 0;
        }
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

