#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <syslog.h>
#include <time.h>

#define RELAY_PINS[4] = {4, 17, 27, 22}
#define RELAY_COUNT 4
#define ACTIVATION_TIME 300
#define DEACTIVATION_TIME 0
#define PAUSE_TIME 60

volatile sig_atomic_t keep_running = 1;
int relay_states[RELAY_COUNT];
int current_relay = 0;
time_t last_action_time;
enum ActionState {ACTIVATING, DEACTIVATING, PAUSING};
enum ActionState current_state = DEACTIVATING;

void log_relay_state(int relay, int state) {
    time_t now;
    time(&now);
    char *state_str = state ? "ON" : "OFF";
    syslog(LOG_INFO, "Relay %d set to %s at %s", relay, state_str, ctime(&now));
}

void handle_signal(int signum) {
    keep_running = 0;
}

void activate_relay(int relay) {
    if (gpioWrite(RELAY_PINS[relay], 0) == PI_BAD_GPIO) {
        syslog(LOG_ERR, "Failed to activate relay %d", relay);
        exit(EXIT_FAILURE);
    }
    relay_states[relay] = 1;
    log_relay_state(relay, relay_states[relay]);
}

void deactivate_relay(int relay) {
    if (gpioWrite(RELAY_PINS[relay], 1) == PI_BAD_GPIO) {
        syslog(LOG_ERR, "Failed to deactivate relay %d", relay);
        exit(EXIT_FAILURE);
    }
    relay_states[relay] = 0;
    log_relay_state(relay, relay_states[relay]);
}

void timer_callback(uint32_t timer, uint32_t ticks) {
    time_t now = time(NULL);
    if (difftime(now, last_action_time) >= PAUSE_TIME && current_state == PAUSING) {
        current_relay = (current_relay + 1) % RELAY_COUNT;
        current_state = ACTIVATING;
        last_action_time = now;
    } else if (difftime(now, last_action_time) >= ACTIVATION_TIME && current_state == ACTIVATING) {
        current_state = DEACTIVATING;
        last_action_time = now;
    } else if (difftime(now, last_action_time) >= DEACTIVATION_TIME && current_state == DEACTIVATING) {
        current_state = PAUSING;
        last_action_time = now;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    for (int i = 0; i < RELAY_COUNT; i++) {
        if (gpioSetMode(RELAY_PINS[i], PI_OUTPUT) == PI_BAD_GPIO) {
            syslog(LOG_ERR, "Failed to set mode for GPIO %d", RELAY_PINS[i]);
            gpioTerminate();
            closelog();
            exit(EXIT_FAILURE);
        }
        deactivate_relay(i);
    }

    if (gpioSetTimerFuncEx(0, 60000000000ULL, timer_callback) < 0) {
        syslog(LOG_ERR, "Failed to set timer function");
        for (int i = 0; i < RELAY_COUNT; i++) {
            deactivate_relay(i);
        }
        gpioTerminate();
        closelog();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    last_action_time = time(NULL);

    while (keep_running) {
        switch (current_state) {
            case ACTIVATING:
                activate_relay(current_relay);
                break;
            case DEACTIVATING:
                deactivate_relay(current_relay);
                break;
            case PAUSING:
                // Do nothing, just wait for the next timer callback
                break;
        }
        sleep(1);
    }

    for (int i = 0; i < RELAY_COUNT; i++) {
        deactivate_relay(i);
    }

    gpioTerminate();
    closelog();
    return 0;
}

