#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/timerfd.h>

#define MPU6050_ADDR 0x68
#define I2C_BUS "/dev/i2c-1"
#define BUFFER_SIZE 100
#define ACCEL_XOUT_H 0x3B
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C

typedef struct {
    float x, y, z;
} AccelData;

AccelData buffer[BUFFER_SIZE];
int buffer_index = 0;
int i2c_fd;
int timer_fd;
int sysfs_fd;
char sysfs_path[256];

void cleanup(int signum) {
    printf("Cleaning up...\n");
    if (i2c_fd >= 0) close(i2c_fd);
    if (timer_fd >= 0) close(timer_fd);
    if (sysfs_fd >= 0) close(sysfs_fd);
    unlink(sysfs_path);
    exit(0);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, 2);
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    return read(fd, buf, len);
}

void read_accel_data() {
    uint8_t data[6];
    if (i2c_read(i2c_fd, ACCEL_XOUT_H, data, 6) != 6) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return;
    }

    AccelData accel;
    accel.x = (int16_t)(data[0] << 8 | data[1]) / 16384.0;
    accel.y = (int16_t)(data[2] << 8 | data[3]) / 16384.0;
    accel.z = (int16_t)(data[4] << 8 | data[5]) / 16384.0;

    buffer[buffer_index] = accel;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    char buffer_str[64];
    snprintf(buffer_str, sizeof(buffer_str), "%.3f,%.3f,%.3f\n", accel.x, accel.y, accel.z);
    lseek(sysfs_fd, 0, SEEK_SET);
    write(sysfs_fd, buffer_str, strlen(buffer_str));
}

void timer_handler(union sigval sv) {
    read_accel_data();
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (i2c_write(i2c_fd, PWR_MGMT_1, 0x00) != 2) {
        fprintf(stderr, "Failed to wake MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    if (i2c_write(i2c_fd, ACCEL_CONFIG, 0x00) != 2) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        close(i2c_fd);
        return 1;
    }

    timer_fd = timerfd_create(CLOCK_MONOTONIC, 0);
    if (timer_fd < 0) {
        perror("Failed to create timer");
        close(i2c_fd);
        return 1;
    }

    struct itimerspec ts;
    ts.it_value.tv_sec = 0;
    ts.it_value.tv_nsec = 10000000; // 100 Hz
    ts.it_interval = ts.it_value;

    if (timerfd_settime(timer_fd, 0, &ts, NULL) < 0) {
        perror("Failed to set timer");
        close(i2c_fd);
        close(timer_fd);
        return 1;
    }

    struct sigevent sev;
    memset(&sev, 0, sizeof(struct sigevent));
    sev.sigev_notify = SIGEV_THREAD;
    sev.sigev_notify_function = timer_handler;

    if (timer_create(CLOCK_MONOTONIC, &sev, NULL) < 0) {
        perror("Failed to create POSIX timer");
        close(i2c_fd);
        close(timer_fd);
        return 1;
    }

    snprintf(sysfs_path, sizeof(sysfs_path), "/sys/kernel/debug/mpu6050_accel/latest");
    sysfs_fd = open(sysfs_path, O_RDWR | O_CREAT, 0644);
    if (sysfs_fd < 0) {
        perror("Failed to create sysfs interface");
        close(i2c_fd);
        close(timer_fd);
        return 1;
    }

    printf("MPU6050 data collection started. Press Ctrl+C to exit.\n");

    while (1) {
        pause();
    }

    return 0;
}

