#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <stdbool.h>

#define NUM_RELAYS 4
#define GPIO_PINS[NUM_RELAYS] = {18, 23, 24, 25}
#define INTERVALS[NUM_RELAYS] = {2, 3, 5, 7}

static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_RELAYS];
static volatile sig_atomic_t keep_running = true;

void cleanup(int signum) {
    keep_running = false;
}

void set_relay(int index, bool state) {
    int ret = gpiod_line_set_value(lines[index], state);
    if (ret < 0) {
        fprintf(stderr, "Failed to set relay %d to %s\n", index, state ? "ON" : "OFF");
    }
}

int main() {
    struct timespec last_toggle[NUM_RELAYS] = {0};
    struct timespec current_time;
    int ret;

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PINS[i]);
            goto cleanup_chip;
        }

        ret = gpiod_line_request_output(lines[i], "relay_control", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output\n", GPIO_PINS[i]);
            goto cleanup_lines;
        }
    }

    // Main loop
    while (keep_running) {
        ret = clock_gettime(CLOCK_MONOTONIC, &current_time);
        if (ret != 0) {
            perror("clock_gettime failed");
            break;
        }

        for (int i = 0; i < NUM_RELAYS; i++) {
            long elapsed = (current_time.tv_sec - last_toggle[i].tv_sec) +
                           (current_time.tv_nsec - last_toggle[i].tv_nsec) / 1000000000.0;

            if (elapsed >= INTERVALS[i]) {
                set_relay(i, !gpiod_line_get_value(lines[i]));
                last_toggle[i] = current_time;
            }
        }
    }

cleanup_lines:
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

cleanup_chip:
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

