#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27
#define POLL_INTERVAL_MS 100
#define ALARM_DURATION_MS 3000
#define DEBOUNCE_TIME_MS 500

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_alarm(const char *message) {
    FILE *file = fopen("alarm_log.txt", "a");
    if (file) {
        time_t now;
        time(&now);
        char *time_str = ctime(&now);
        time_str[strlen(time_str) - 1] = '\0'; // Remove newline
        fprintf(file, "[%s] %s\n", time_str, message);
        fclose(file);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetPullUpDown(SOUND_SENSOR_PIN, PI_PUD_DOWN);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler\n");
        gpioTerminate();
        return 1;
    }

    time_t last_alarm_time = 0;

    while (keep_running) {
        if (gpioRead(SOUND_SENSOR_PIN) == PI_HIGH) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_alarm_time) >= DEBOUNCE_TIME_MS / 1000.0) {
                gpioWrite(RELAY_PIN, PI_HIGH);
                log_alarm("Relay activated");
                gpioDelay(ALARM_DURATION_MS * 1000);
                gpioWrite(RELAY_PIN, PI_LOW);
                log_alarm("Relay deactivated");
                last_alarm_time = current_time;
            }
        }
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    gpioWrite(RELAY_PIN, PI_LOW);
    gpioTerminate();
    return 0;
}

