#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define SAMPLES 100
#define THRESHOLD 50.0

typedef struct {
    float x, y, z;
} Vector3;

typedef struct {
    Vector3 data[SAMPLES];
    int head;
} CircularBuffer;

int i2c_fd;
CircularBuffer buffer = { .head = 0 };

void cleanup(int signum) {
    printf("Cleaning up...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int write_i2c(int fd, uint8_t reg, uint8_t value) {
    uint8_t data[2] = { reg, value };
    return write(fd, data, sizeof(data));
}

int read_i2c(int fd, uint8_t reg, uint8_t *value, int len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, value, len);
}

int init_mpu6050() {
    if (write_i2c(i2c_fd, PWR_MGMT_1, 0x00) != 1) {
        perror("Failed to wake up MPU6050");
        return -1;
    }
    usleep(100000); // Wait for the sensor to be ready

    uint8_t who_am_i;
    if (read_i2c(i2c_fd, WHO_AM_I, &who_am_i, 1) != 1 || who_am_i != MPU6050_ADDR) {
        fprintf(stderr, "MPU6050 not found or communication error\n");
        return -1;
    }
    return 0;
}

int read_gyroscope(Vector3 *gyro) {
    uint8_t data[6];
    if (read_i2c(i2c_fd, GYRO_XOUT_H, data, 6) != 6) {
        return -1;
    }

    gyro->x = (int16_t)(data[0] << 8 | data[1]) / 131.0;
    gyro->y = (int16_t)(data[2] << 8 | data[3]) / 131.0;
    gyro->z = (int16_t)(data[4] << 8 | data[5]) / 131.0;
    return 0;
}

void update_buffer(Vector3 *gyro) {
    buffer.data[buffer.head] = *gyro;
    buffer.head = (buffer.head + 1) % SAMPLES;
}

float vector_magnitude(Vector3 *v) {
    return sqrt(v->x * v->x + v->y * v->y + v->z * v->z);
}

void check_threshold(Vector3 *gyro) {
    float magnitude = vector_magnitude(gyro);
    if (magnitude > THRESHOLD) {
        printf("Threshold exceeded: %.2f degrees/s\n", magnitude);
    }
}

int main() {
    signal(SIGINT, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_mpu6050() < 0) {
        cleanup(0);
        return EXIT_FAILURE;
    }

    printf("MPU6050 initialized and ready\n");

    while (1) {
        Vector3 gyro;
        if (read_gyroscope(&gyro) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            continue;
        }

        update_buffer(&gyro);
        check_threshold(&gyro);

        usleep(10000); // 100 Hz
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

