    unsigned char read_command[READ_COMMAND_SIZE] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, READ_COMMAND_BYTE_8};
    unsigned char response[READ_COMMAND_SIZE];

    while (1) {
        if (serWrite(serial_handle, read_command, READ_COMMAND_SIZE) < READ_COMMAND_SIZE) {
            log_error("Failed to write to serial port");
        } else {
            time_sleep(RETRY_DELAY_MS / 1000.0);
            if (read_co2(serial_handle, response) == 0) {
                unsigned int ppm = (response[2] << 8) | response[3];
                unsigned char checksum = 0xFF - ((response[1] + response[2] + response[3] + response[4] + response[5] + response[6]) & 0xFF) + 1;
                if (checksum == response[7]) {
                    write_json_log(CO2_LOG_FILE, ppm, 0);
                    printf("{\"timestamp\":%ld,\"ppm\":%u,\"error\":false}\n", (long)time(NULL), ppm);
                } else {
                    log_error("Checksum mismatch");
                    write_json_log(CO2_LOG_FILE, ppm, 1);
                    printf("{\"timestamp\":%ld,\"ppm\":%u,\"error\":true}\n", (long)time(NULL), ppm);
                }
            }
        }
        time_sleep(READ_INTERVAL_SECONDS);
    }

    serClose(serial_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

void log_error(const char *message) {
    FILE *error_log = fopen(ERROR_LOG_FILE, "a");
    if (error_log) {
        time_t now = time(NULL);
        char *time_str = ctime(&now);
        time_str[strlen(time_str) - 1] = '\0'; // Remove newline
        fprintf(error_log, "[%s] %s\n", time_str, message);
        fclose(error_log);
    }
}

void signal_handler(int signo) {
    log_error("Received termination signal");
    exit(EXIT_SUCCESS);
}

int read_co2(int serial_handle, unsigned char *buffer) {
    int bytes_received = 0;
    time_t start_time = time(NULL);

    while (bytes_received < READ_COMMAND_SIZE) {
        if (serDataAvailable(serial_handle) > 0) {
            int result = serRead(serial_handle, &buffer[bytes_received], READ_COMMAND_SIZE - bytes_received);
            if (result > 0) {
                bytes_received += result;
            } else if (result < 0) {
                log_error("Error reading from serial port");
                return -1;
            }
        }

        if (difftime(time(NULL), start_time) > TIMEOUT_MS / 1000.0) {
            log_error("Read timeout");
            return -1;
        }

        time_sleep(RETRY_DELAY_MS / 1000.0);
    }

    return 0;
}

void write_json_log(const char *filename, unsigned int ppm, int error_flag) {
    FILE *log_file = fopen(filename, "a");
    if (log_file) {
        time_t now = time(NULL);
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        long microseconds = ts.tv_nsec / 1000;
        fprintf(log_file, "{\"timestamp\":%ld.%06ld,\"ppm\":%u,\"error\":%s}\n", (long)now, microseconds, ppm, error_flag ? "true" : "false");
        fflush(log_file);
        fclose(log_file);
    } else {
        log_error("Failed to open log file");
    }
}
