#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define CONFIG_A 0x00
#define CONFIG_B 0x01
#define MODE 0x02
#define DATA_OUT_X_L 0x03
#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0
#define SAMPLE_INTERVAL_MS 100
#define BUFFER_SIZE 100

typedef struct {
    float x, y, z;
} HeadingData;

HeadingData circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

void cleanup(int signum) {
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int write_i2c_register(int fd, uint8_t reg, uint8_t value) {
    int retries = 3;
    while (retries--) {
        if (i2cWriteByteData(fd, reg, value) == 0) {
            return 0;
        }
        usleep(1000);
    }
    fprintf(stderr, "Failed to write to register 0x%02X\n", reg);
    return -1;
}

int read_i2c_data(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 3;
    while (retries--) {
        if (i2cReadI2CBlockData(fd, reg, data, len) == len) {
            return 0;
        }
        usleep(1000);
    }
    fprintf(stderr, "Failed to read from register 0x%02X\n", reg);
    return -1;
}

HeadingData read_heading(int fd) {
    uint8_t data[6];
    if (read_i2c_data(fd, DATA_OUT_X_L, data, 6) != 0) {
        return (HeadingData){0, 0, 0};
    }
    HeadingData heading;
    heading.x = (int16_t)(data[0] | (data[1] << 8));
    heading.z = (int16_t)(data[2] | (data[3] << 8));
    heading.y = (int16_t)(data[4] | (data[5] << 8));
    return heading;
}

float calculate_heading(HeadingData heading) {
    return atan2(heading.y, heading.x) * 180.0 / M_PI;
}

void update_circular_buffer(float heading) {
    circular_buffer[buffer_index] = (HeadingData){heading, 0, 0};
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_i2c_register(i2c_handle, CONFIG_A, 0x70) != 0 ||
        write_i2c_register(i2c_handle, CONFIG_B, 0x20) != 0 ||
        write_i2c_register(i2c_handle, MODE, 0x00) != 0) {
        fprintf(stderr, "Failed to configure HMC5883L\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(17, PI_OUTPUT);

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        HeadingData raw_heading = read_heading(i2c_handle);
        if (raw_heading.x == 0 && raw_heading.y == 0 && raw_heading.z == 0) {
            fprintf(stderr, "Failed to read heading data\n");
            continue;
        }

        float compensated_x = raw_heading.x - 100;
        float compensated_y = raw_heading.y + 50;
        float heading = calculate_heading((HeadingData){compensated_x, compensated_y, raw_heading.z});

        update_circular_buffer(heading);

        if (fabs(heading - TARGET_HEADING) > DEVIATION_THRESHOLD) {
            gpioWrite(17, PI_HIGH);
        } else {
            gpioWrite(17, PI_LOW);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

