#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_COMMAND 0x10
#define LOG_FILE "lighting_log.txt"
#define RED_PIN 17
#define GREEN_PIN 27
#define BLUE_PIN 22

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *red_line, *green_line, *blue_line;
static FILE *log_file;

void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int setup_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(red_line, "red_relay", 0) < 0 ||
        gpiod_line_request_output(green_line, "green_relay", 0) < 0 ||
        gpiod_line_request_output(blue_line, "blue_relay", 0) < 0) {
        perror("Failed to request GPIO lines");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int read_bh1750(float *lux) {
    unsigned char data[2];
    if (write(i2c_fd, &BH1750_COMMAND, 1) != 1) {
        perror("Failed to write to BH1750");
        return -1;
    }

    usleep(120000);  // Wait for conversion

    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from BH1750");
        return -1;
    }

    *lux = (data[0] << 8 | data[1]) / 1.2;
    return 0;
}

void set_relays(float lux) {
    int red_state = (lux < 50) ? 1 : 0;
    int green_state = (lux >= 50 && lux < 150) ? 1 : 0;
    int blue_state = (lux >= 150 && lux < 300) ? 1 : 0;

    gpiod_line_set_value(red_line, red_state);
    gpiod_line_set_value(green_line, green_state);
    gpiod_line_set_value(blue_line, blue_state);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (setup_i2c() < 0 || setup_gpio() < 0) {
        fprintf(stderr, "Setup failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup(0);
    }

    while (1) {
        float lux;
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        if (read_bh1750(&lux) < 0) {
            fprintf(stderr, "Failed to read lux value\n");
            continue;
        }

        set_relays(lux);

        fprintf(log_file, "%s, %.2f, %d,%d,%d\n", timestamp, lux,
                gpiod_line_get_value(red_line),
                gpiod_line_get_value(green_line),
                gpiod_line_get_value(blue_line));
        fflush(log_file);

        sleep(1);
    }

    return EXIT_SUCCESS;
}

