#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_RANGE 255
#define PWM_FREQ 1000

static volatile int keep_running = 1;

void signal_handler(int signo) {
    keep_running = 0;
}

int map_distance_to_pwm(int distance) {
    if (distance < 10) distance = 10;
    if (distance > 100) distance = 100;
    return PWM_RANGE - ((distance - 10) * PWM_RANGE / 90);
}

void control_motor(int gpio_in1, int gpio_in2, int distance) {
    int pwm_duty = map_distance_to_pwm(distance);

    if (distance < 50) {
        gpioWrite(gpio_in1, 1);
        gpioWrite(gpio_in2, 0);
        gpioPWM(gpio_in2, PWM_FREQ, pwm_duty);
    } else {
        gpioWrite(gpio_in1, 0);
        gpioWrite(gpio_in2, 1);
        gpioPWM(gpio_in2, PWM_FREQ, pwm_duty);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_motor_a> <distance_motor_b>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int distance_a = atoi(argv[1]);
    int distance_b = atoi(argv[2]);

    if (distance_a < 10 || distance_a > 100 || distance_b < 10 || distance_b > 100) {
        fprintf(stderr, "Distance values must be between 10 and 100\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        control_motor(MOTOR_A_IN1, MOTOR_A_IN2, distance_a);
        control_motor(MOTOR_B_IN3, MOTOR_B_IN4, distance_b);
        usleep(100000);  // 100ms
    }

    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);

    gpioTerminate();
    return EXIT_SUCCESS;
}

