#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define SERVO_PWM_PIN 18
#define PWM_CHIP "/sys/class/pwm/pwmchip2"
#define PWM_EXPORT_FILE PWM_CHIP "/export"
#define PWM_UNEXPORT_FILE PWM_CHIP "/unexport"
#define PWM_PERIOD 20000000 // 20ms period for 50Hz servo
#define LOG_FILE "solar_tracker.log"

static int i2c_fd;
static int pwm_fd;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int setup_i2c() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int setup_pwm() {
    char pwm_export[10];
    int fd;

    // Export PWM
    fd = open(PWM_UNEXPORT_FILE, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM unexport file");
        return -1;
    }
    snprintf(pwm_export, sizeof(pwm_export), "%d", 0);
    if (write(fd, pwm_export, strlen(pwm_export)) < 0) {
        perror("Failed to unexport PWM");
        close(fd);
        return -1;
    }
    close(fd);

    usleep(10000); // Wait for PWM to be ready

    fd = open(PWM_EXPORT_FILE, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM export file");
        return -1;
    }
    snprintf(pwm_export, sizeof(pwm_export), "%d", 0);
    if (write(fd, pwm_export, strlen(pwm_export)) < 0) {
        perror("Failed to export PWM");
        close(fd);
        return -1;
    }
    close(fd);

    char pwm_path[100];
    snprintf(pwm_path, sizeof(pwm_path), "%s/pwm0", PWM_CHIP);

    // Set PWM period
    fd = open(strcat(strdup(pwm_path), "/period"), O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM period file");
        return -1;
    }
    char period[20];
    snprintf(period, sizeof(period), "%d", PWM_PERIOD);
    if (write(fd, period, strlen(period)) < 0) {
        perror("Failed to set PWM period");
        close(fd);
        return -1;
    }
    close(fd);

    // Set PWM duty cycle (start at 90 degrees)
    fd = open(strcat(strdup(pwm_path), "/duty_cycle"), O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM duty cycle file");
        return -1;
    }
    char duty_cycle[20];
    snprintf(duty_cycle, sizeof(duty_cycle), "%d", PWM_PERIOD * 90 / 180);
    if (write(fd, duty_cycle, strlen(duty_cycle)) < 0) {
        perror("Failed to set PWM duty cycle");
        close(fd);
        return -1;
    }
    close(fd);

    // Enable PWM
    fd = open(strcat(strdup(pwm_path), "/enable"), O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM enable file");
        return -1;
    }
    if (write(fd, "1", 1) < 0) {
        perror("Failed to enable PWM");
        close(fd);
        return -1;
    }
    close(fd);

    return open(strcat(strdup(pwm_path), "/duty_cycle"), O_WRONLY);
}

void log_data(double pitch, double roll, int servo_position) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm *tm = localtime(&tv.tv_sec);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_position);
    fclose(log_file);
}

int read_mpu6050(short *accel, short *gyro) {
    unsigned char buffer[14];
    if (read(i2c_fd, buffer, 14) != 14) {
        return -1;
    }

    accel[0] = (buffer[0] << 8) | buffer[1];
    accel[1] = (buffer[2] << 8) | buffer[3];
    accel[2] = (buffer[4] << 8) | buffer[5];
    gyro[0] = (buffer[8] << 8) | buffer[9];
    gyro[1] = (buffer[10] << 8) | buffer[11];
    gyro[2] = (buffer[12] << 8) | buffer[13];

    return 0;
}

void calculate_tilt_and_adjust_servo(short *accel, short *gyro) {
    double ax = accel[0] / 16384.0;
    double ay = accel[1] / 16384.0;
    double az = accel[2] / 16384.0;

    double pitch = atan2(ay, sqrt(ax * ax + az * az)) * 180 / M_PI;
    double roll = atan2(ax, sqrt(ay * ay + az * az)) * 180 / M_PI;

    // Simple PID controller (you may want to tune these values)
    static double integral_pitch = 0, integral_roll = 0;
    double Kp = 0.1, Ki = 0.01;
    integral_pitch += pitch;
    integral_roll += roll;

    double servo_adjustment = (Kp * pitch + Ki * integral_pitch + Kp * roll + Ki * integral_roll);
    int servo_position = 90 + (int)servo_adjustment;
    servo_position = (servo_position < 0) ? 0 : (servo_position > 180) ? 180 : servo_position;

    // Set PWM duty cycle
    char duty_cycle[20];
    snprintf(duty_cycle, sizeof(duty_cycle), "%d", PWM_PERIOD * servo_position / 180);
    lseek(pwm_fd, 0, SEEK_SET);
    write(pwm_fd, duty_cycle, strlen(duty_cycle));

    log_data(pitch, roll, servo_position);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = setup_i2c();
    if (i2c_fd < 0) {
        return 1;
    }

    pwm_fd = setup_pwm();
    if (pwm_fd < 0) {
        close(i2c_fd);
        return 1;
    }

    while (keep_running) {
        short accel[3], gyro[3];
        int retries = 0;
        while (retries < 5) {
            if (read_mpu6050(accel, gyro) == 0) {
                calculate_tilt_and_adjust_servo(accel, gyro);
                break;
            }
            retries++;
            usleep(100000); // 100ms delay before retry
        }
        if (retries == 5) {
            fprintf(stderr, "Failed to read MPU6050 after 5 attempts\n");
        }
        usleep(100000); // 100ms delay between readings
    }

    close(pwm_fd);
    close(i2c_fd);
    return 0;
}

