#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MIN_DISTANCE 2
#define MAX_DISTANCE 30
#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000
#define TRIGGER_PULSE_WIDTH 10 // microseconds
#define MEASUREMENT_INTERVAL 60000 // microseconds (60 ms)
#define MAIN_LOOP_INTERVAL 20000 // microseconds (20 ms)

static volatile int keep_running = 1;

void sigint_handler(int signum) {
    keep_running = 0;
}

double map(double x, double in_min, double in_max, double out_min, double out_max) {
    return (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    gpioSetPullUpDown(ECHO_PIN, PI_PUD_OFF);

    signal(SIGINT, sigint_handler);

    unsigned long last_measurement_time = gpioTick();
    unsigned long last_loop_time = gpioTick();

    while (keep_running) {
        unsigned long current_time = gpioTick();

        if (current_time - last_measurement_time >= MEASUREMENT_INTERVAL) {
            gpioWrite(TRIG_PIN, PI_LOW);
            gpioDelay(2);
            gpioWrite(TRIG_PIN, PI_HIGH);
            gpioDelay(TRIGGER_PULSE_WIDTH);
            gpioWrite(TRIG_PIN, PI_LOW);

            unsigned long start_time = current_time;
            unsigned long timeout = start_time + 100000; // 100 ms timeout

            while (gpioRead(ECHO_PIN) == 0) {
                if (gpioTick() > timeout) {
                    fprintf(stderr, "Echo pulse timeout\n");
                    break;
                }
            }

            start_time = gpioTick();
            while (gpioRead(ECHO_PIN) == 1) {
                if (gpioTick() > timeout) {
                    fprintf(stderr, "Echo pulse timeout\n");
                    break;
                }
            }

            unsigned long pulse_width = gpioTick() - start_time;
            double distance = pulse_width / 58.0; // Speed of sound ~343 m/s, so 34300 / 2 = 17150

            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                double frequency = map(distance, MIN_DISTANCE, MAX_DISTANCE, MIN_FREQUENCY, MAX_FREQUENCY);
                frequency = (frequency < MIN_FREQUENCY) ? MIN_FREQUENCY : ((frequency > MAX_FREQUENCY) ? MAX_FREQUENCY : frequency);

                gpioSetPWMfrequency(BUZZER_PIN, frequency);
                gpioPWM(BUZZER_PIN, 128); // 50% duty cycle
            } else {
                gpioPWM(BUZZER_PIN, 0); // Silence the buzzer
            }

            last_measurement_time = current_time;
        }

        unsigned long sleep_time = MAIN_LOOP_INTERVAL - (gpioTick() - last_loop_time);
        if (sleep_time > 0) {
            gpioDelay(sleep_time);
        }
        last_loop_time = gpioTick();
    }

    gpioPWM(BUZZER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

