#include <signal.h>
#include <pigpio.h>
#include <math.h>

#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27
#define PWM_FREQ 1000

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = 0;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioHardwarePWM(RED_PIN, PWM_FREQ, 0) < 0 ||
        gpioHardwarePWM(GREEN_PIN, PWM_FREQ, 0) < 0 ||
        gpioHardwarePWM(BLUE_PIN, PWM_FREQ, 0) < 0) {
        fprintf(stderr, "Failed to initialize PWM\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    double time = 0.0;
    const double increment = 0.01;

    while (keep_running) {
        double proximity = 0.5 * (sin(time) + 1.0);  // Range 0.0 to 1.0

        unsigned int red_duty = (unsigned int)(255 * proximity);
        unsigned int green_duty = (unsigned int)(255 * (1.0 - proximity));
        unsigned int blue_duty = 0;

        if (gpioSetPWMdutycycle(RED_PIN, red_duty) < 0 ||
            gpioSetPWMdutycycle(GREEN_PIN, green_duty) < 0 ||
            gpioSetPWMdutycycle(BLUE_PIN, blue_duty) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            break;
        }

        gpioSleep(PI_TIME_RELATIVE, 0, 100000);  // Sleep for 100ms
        time += increment;
    }

    gpioSetPWMdutycycle(RED_PIN, 0);
    gpioSetPWMdutycycle(GREEN_PIN, 0);
    gpioSetPWMdutycycle(BLUE_PIN, 0);

    gpioTerminate();
    return 0;
}

