#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_OUT_REG 0x43
#define SENSITIVITY 131.0
#define LOG_INTERVAL_MS 100

static int i2c_fd;
static FILE *log_file;

void signal_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct i2c_msg messages[1];
    char buffer[7];
    int16_t x, y, z;
    struct timeval tv;
    struct timezone tz;
    char timestamp[64];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    buffer[0] = PWR_MGMT_1;
    buffer[1] = 0x00;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to wake up MPU-6050");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        messages[0].addr = MPU6050_ADDR;
        messages[0].flags = 0;
        messages[0].len = 7;
        messages[0].buf = buffer;

        if (ioctl(i2c_fd, I2C_RDWR, messages) < 0) {
            perror("Failed to read from MPU-6050");
            continue;
        }

        x = (buffer[1] << 8) | buffer[0];
        y = (buffer[3] << 8) | buffer[2];
        z = (buffer[5] << 8) | buffer[4];

        gettimeofday(&tv, &tz);
        struct tm *timeinfo = localtime(&tv.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s.%06ld, %.2f, %.2f, %.2f\n", 
                timestamp, tv.tv_usec, 
                x / SENSITIVITY, y / SENSITIVITY, z / SENSITIVITY);
        fflush(log_file);

        usleep(LOG_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

