#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_TIME_MS 50
#define MELODY_NOTES 8
#define PWM_RANGE 1024
#define PWM_FREQ 1000

// Melody: A4, A4, A4, G4, G4, A4, F4, F4
const unsigned int melody[] = {
    440, 440, 440, 392, 392, 440, 349, 349
};

volatile sig_atomic_t stop_playback = 0;
volatile sig_atomic_t button_pressed = 0;

void play_melody(void) {
    for (int i = 0; i < MELODY_NOTES && !stop_playback; i++) {
        if (gpioHardwarePWM(BUZZER_PIN, melody[i], PWM_RANGE / 2) < 0) {
            fprintf(stderr, "Failed to set PWM for frequency %u Hz\n", melody[i]);
            return;
        }
        usleep(500000); // Play each note for half a second
        gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop PWM
        usleep(100000); // Pause between notes
    }
}

void button_callback(gpioint_t gpio, uint32_t level, uint32_t tick) {
    if (!button_pressed) {
        button_pressed = 1;
        time_sleep(DEBOUNCE_TIME_MS / 1000.0);
        if (!stop_playback) {
            play_melody();
        }
        button_pressed = 0;
    }
}

void signal_handler(int signum) {
    stop_playback = 1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set up button pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_ALT0) < 0) {
        fprintf(stderr, "Failed to set up buzzer pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
