#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define GPIO_PIN 17
#define LOG_FILE "vibration_events.log"
#define WINDOW_SIZE 5
#define EARTHQUAKE_THRESHOLD 3

volatile sig_atomic_t terminate = 0;

void sig_handler(int signum) {
    terminate = 1;
}

void log_event(int value) {
    static FILE *log_file = NULL;
    if (!log_file) {
        log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return;
        }
    }

    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s %d\n", timestamp, value);
    fflush(log_file);
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int poll_timeout = 1000;
    int event_count = 0;
    int event_values[WINDOW_SIZE] = {0};
    int event_index = 0;

    if (argc > 1) {
        poll_timeout = atoi(argv[1]);
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int ret = gpiod_line_request_input(line, "vibration-sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return 1;
    }

    while (!terminate) {
        struct gpiod_line_event event;
        int event_type = gpiod_line_event_wait(line, poll_timeout);

        if (event_type < 0) {
            fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
            break;
        } else if (event_type > 0) {
            ret = gpiod_line_event_read(line, &event);
            if (ret < 0) {
                fprintf(stderr, "Error reading GPIO event: %s\n", strerror(errno));
                break;
            }

            int value = gpiod_line_event_get_value(&event);
            log_event(value);

            event_values[event_index] = value;
            event_index = (event_index + 1) % WINDOW_SIZE;
            event_count++;

            if (event_count >= WINDOW_SIZE) {
                int earthquake_count = 0;
                for (int i = 0; i < WINDOW_SIZE; i++) {
                    if (event_values[i] == 1) {
                        earthquake_count++;
                    }
                }

                if (earthquake_count >= EARTHQUAKE_THRESHOLD) {
                    time_t now;
                    struct tm *tm_info;
                    char timestamp[64];

                    time(&now);
                    tm_info = localtime(&now);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

                    printf("EARTHQUAKE ALERT: %s\n", timestamp);
                }
            }
        }
    }

    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

