#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MAGNETOMETER_ADDR 0x1E
#define CRA_REG_M 0x00
#define MR_REG_M 0x02
#define OUT_X_L 0x08
#define OUT_X_H 0x09
#define OUT_Y_L 0x0A
#define OUT_Y_H 0x0B
#define OUT_Z_L 0x0C
#define OUT_Z_H 0x0D
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20
#define CSV_FILE "mag_log.csv"

int i2c_fd;
FILE *csv_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (csv_file) {
        fclose(csv_file);
    }
    exit(EXIT_SUCCESS);
}

int write_i2c_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int read_i2c_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, value, 1);
}

int read_i2c_block(int fd, uint8_t reg, uint8_t *buf, uint8_t len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, buf, len);
}

int16_t combine_bytes(uint8_t msb, uint8_t lsb) {
    return (int16_t)((msb << 8) | lsb);
}

float calculate_heading(float x, float y) {
    float heading = atan2f(y, x) * (180.0f / M_PI);
    if (heading < 0) {
        heading += 360.0f;
    }
    return heading;
}

const char* get_direction(float heading) {
    static const char* directions[] = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};
    int index = (int)((heading + 22.5f) % 360.0f) / 45;
    return directions[index];
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, MAGNETOMETER_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write_i2c_reg(i2c_fd, CRA_REG_M, 0x14) < 0 ||
        write_i2c_reg(i2c_fd, MR_REG_M, 0x00) < 0) {
        perror("Failed to configure magnetometer");
        cleanup(0);
    }

    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        cleanup(0);
    }

    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }

    uint8_t buf[6];
    float x, y, z, heading;
    time_t last_log_time = 0;

    while (1) {
        if (read_i2c_block(i2c_fd, OUT_X_L, buf, 6) != 6) {
            fprintf(stderr, "Failed to read magnetometer data\n");
            sleep(1);
            continue;
        }

        x = combine_bytes(buf[1], buf[0]) - X_OFFSET;
        y = combine_bytes(buf[3], buf[2]) - Y_OFFSET;
        z = combine_bytes(buf[5], buf[4]) - Z_OFFSET;

        heading = calculate_heading(x, y);
        const char* direction = get_direction(heading);

        printf("Heading: %.2f degrees (%s)\n", heading, direction);

        time_t current_time = time(NULL);
        if (current_time != last_log_time) {
            fprintf(csv_file, "%ld,%.2f,%.2f,%.2f,%.2f\n",
                    (long)current_time, x, y, z, heading);
            fflush(csv_file);
            last_log_time = current_time;
        }

        sleep(1);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

