#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_TIME_MS 200

volatile int last_touch_time = 0;
volatile int relay_state = 0;

void log_relay_state(const char *state) {
    FILE *file = fopen("relay_log.json", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(file, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, state);
    fclose(file);
}

void touch_callback(int gpio, int level, uint32_t tick) {
    int current_time = time(NULL) * 1000;
    if (current_time - last_touch_time >= DEBOUNCE_TIME_MS) {
        last_touch_time = current_time;

        relay_state = !relay_state;
        gpioWrite(RELAY_PIN, relay_state);

        log_relay_state(relay_state ? "ON" : "OFF");
    }
}

void signal_handler(int signo) {
    if (signo == SIGINT) {
        gpioWrite(RELAY_PIN, 0);
        log_relay_state("OFF");
        gpioTerminate();
        exit(0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize gpio\n");
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistor\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFunc(TOUCH_PIN, RISING_EDGE, 0, touch_callback) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        gpioSleep(PI_TIME_SECONDS, 1, 0);
    }

    return 0;
}

