#define WATER_VALVE_PIN 17
#define NOZZLE_SERVO_PIN 18
#define MOISTURE_THRESHOLD 50
#define WATERING_DELAY 2
#define WATERING_HOLD 5
#define CYCLE_DELAY 5
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

int gpioServoWithRetry(int gpio, int pulse, int retries) {
    int result;
    for (int i = 0; i < retries; i++) {
        result = gpioServo(gpio, pulse);
        if (result >= 0) return result;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

void water_plant() {
    int moisture_readings[] = {20, 40, 60, 80, 100};
    int num_readings = sizeof(moisture_readings) / sizeof(moisture_readings[0]);

    for (int i = 0; i < num_readings && !terminate; i++) {
        int moisture = moisture_readings[i];
        printf("Moisture reading: %d%%\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            // Open valve
            if (gpioServoWithRetry(WATER_VALVE_PIN, 1500, MAX_RETRIES) < 0) {
                fprintf(stderr, "Critical warning: Failed to open valve\n");
                continue;
            }
            sleep(1); // Wait for servo to move

            // Sweep nozzle
            int angles[] = {0, 45, 90, 135, 180};
            for (int j = 0; j < sizeof(angles) / sizeof(angles[0]) && !terminate; j++) {
                int pulse = 500 + (angles[j] * 2000 / 180);
                if (gpioServoWithRetry(NOZZLE_SERVO_PIN, pulse, MAX_RETRIES) < 0) {
                    fprintf(stderr, "Error: Failed to set nozzle angle to %d\n", angles[j]);
                    continue;
                }
                sleep(WATERING_DELAY);
            }

            sleep(WATERING_HOLD);

            // Close valve
            if (gpioServoWithRetry(WATER_VALVE_PIN, 500, MAX_RETRIES) < 0) {
                fprintf(stderr, "Error: Failed to close valve\n");
            }
            sleep(1); // Wait for servo to move
        }

        sleep(CYCLE_DELAY);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    water_plant();

    gpioServo(WATER_VALVE_PIN, 500); // Ensure valve is closed
    gpioServo(NOZZLE_SERVO_PIN, 500); // Ensure nozzle is at 0 degrees
    gpioTerminate();

    return EXIT_SUCCESS;
}

