#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <time.h>
#include <signal.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define SENSITIVITY 131.0
#define SAMPLE_RATE 10
#define LOG_FILE "gyro_log.txt"

int i2c_fd;
FILE *log_file;

void signal_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        printf("Exiting...\n");
        if (i2c_fd >= 0) {
            close(i2c_fd);
        }
        if (log_file) {
            fclose(log_file);
        }
        exit(EXIT_SUCCESS);
    }
}

int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int wake_mpu6050() {
    unsigned char data = 0x00;
    if (write(i2c_fd, &data, 1) != 1) {
        perror("Failed to wake MPU-6050");
        return -1;
    }
    return 0;
}

int read_gyro_data(short *x, short *y, short *z) {
    unsigned char buffer[6];
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Failed to read gyro data");
        return -1;
    }

    *x = (buffer[0] << 8) | buffer[1];
    *y = (buffer[2] << 8) | buffer[3];
    *z = (buffer[4] << 8) | buffer[5];

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        return EXIT_FAILURE;
    }

    if (wake_mpu6050() < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,x,y,z\n");

    short x, y, z;
    struct timespec ts;
    long long prev_ns = 0;

    while (1) {
        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
            perror("Failed to get current time");
            break;
        }

        long long current_ns = ts.tv_sec * 1000000000LL + ts.tv_nsec;
        long long elapsed_ns = current_ns - prev_ns;
        long long target_ns = 1000000000LL / SAMPLE_RATE;

        if (elapsed_ns < target_ns) {
            usleep((target_ns - elapsed_ns) / 1000);
            continue;
        }

        if (read_gyro_data(&x, &y, &z) < 0) {
            break;
        }

        double x_deg = (double)x / SENSITIVITY;
        double y_deg = (double)y / SENSITIVITY;
        double z_deg = (double)z / SENSITIVITY;

        fprintf(log_file, "%lld,%f,%f,%f\n", current_ns / 1000000, x_deg, y_deg, z_deg);
        fflush(log_file);

        prev_ns = current_ns;
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

