#include <time.h>
#include <errno.h>
#include <string.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define SPEED_OF_SOUND 343.0 // m/s
#define DISTANCE_FACTOR 0.01715 // cm/us
#define MEASUREMENT_TIMEOUT_US 50000 // 50 ms
#define MIN_GUARD_TIME_US 60000 // 60 ms

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;

void cleanup(int signum) {
    if (trigger_line) gpiod_line_release(trigger_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec start, end;
    long duration_us;
    double distance_cm;

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Request trigger line as output
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line: %s\n", strerror(errno));
        goto cleanup_chip;
    }
    if (gpiod_line_request_output(trigger_line, "HC-SR04 Trigger", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line: %s\n", strerror(errno));
        goto cleanup_trigger;
    }

    // Request echo line as input
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line: %s\n", strerror(errno));
        goto cleanup_trigger;
    }
    if (gpiod_line_request_input(echo_line, "HC-SR04 Echo") < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", strerror(errno));
        goto cleanup_echo;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        goto cleanup_echo;
    }

    // Set up signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        // Generate 10us pulse on trigger
        gpiod_line_set_value(trigger_line, 1);
        nanosleep(&(struct timespec){0, 10000}, NULL); // 10us
        gpiod_line_set_value(trigger_line, 0);

        // Wait for rising edge
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_line) == 0) {
            if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 >= MEASUREMENT_TIMEOUT_US) {
                fprintf(log_file, "-1\n");
                fflush(log_file);
                break;
            }
            clock_gettime(CLOCK_MONOTONIC, &end);
        }
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 >= MEASUREMENT_TIMEOUT_US) {
            continue;
        }

        // Measure pulse width
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_line) == 1) {
            if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 >= MEASUREMENT_TIMEOUT_US) {
                fprintf(log_file, "-1\n");
                fflush(log_file);
                break;
            }
            clock_gettime(CLOCK_MONOTONIC, &end);
        }
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 >= MEASUREMENT_TIMEOUT_US) {
            continue;
        }

        duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        distance_cm = duration_us * DISTANCE_FACTOR;

        fprintf(log_file, "%.2f\n", distance_cm);
        fflush(log_file);

        // Enforce minimum guard time
        nanosleep(&(struct timespec){0, MIN_GUARD_TIME_US * 1000}, NULL);
    }

cleanup_echo:
    gpiod_line_release(echo_line);
cleanup_trigger:
    gpiod_line_release(trigger_line);
cleanup_chip:
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

