#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define VL53L1X_I2C_ADDR 0x29
#define VL53L1X_REG_RESET 0x0000
#define VL53L1X_REG_MODE 0x0080
#define VL53L1X_REG_INT_STATUS 0x0044
#define VL53L1X_REG_DISTANCE_MSB 0x0096
#define VL53L1X_REG_DISTANCE_LSB 0x0097

#define DOOR_RELAY_PIN 18
#define POLL_INTERVAL_MS 100
#define DOOR_THRESHOLD_CM 50

static int i2c_handle;

void cleanup(int sig) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(DOOR_RELAY_PIN, LOW);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(DOOR_RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for relay\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, VL53L1X_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Software reset
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RESET, 0x00) < 0) {
        fprintf(stderr, "Failed to perform software reset\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    usleep(100000); // Wait 100ms for reset to complete

    // Set ranging mode
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_MODE, 0x01) < 0) {
        fprintf(stderr, "Failed to set ranging mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    while (1) {
        // Check interrupt status for data ready
        int status = i2cReadByteData(i2c_handle, VL53L1X_REG_INT_STATUS);
        if (status < 0) {
            fprintf(stderr, "Failed to read interrupt status\n");
            break;
        }

        if (status & 0x01) { // Data ready
            int distance_msb = i2cReadByteData(i2c_handle, VL53L1X_REG_DISTANCE_MSB);
            int distance_lsb = i2cReadByteData(i2c_handle, VL53L1X_REG_DISTANCE_LSB);

            if (distance_msb < 0 || distance_lsb < 0) {
                fprintf(stderr, "Failed to read distance data\n");
                break;
            }

            int distance = (distance_msb << 8) | distance_lsb;
            printf("Current distance: %d cm\n", distance);

            if (distance <= DOOR_THRESHOLD_CM) {
                gpioWrite(DOOR_RELAY_PIN, HIGH);
            } else {
                gpioWrite(DOOR_RELAY_PIN, LOW);
            }
        }

        time_sleep(POLL_INTERVAL_MS / 1000.0);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

