#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <stdint.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_OUT_REG 0x43
#define LSB_SENSITIVITY 131.0

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int i2c_write(int file, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(file, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read(int file, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(file, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(file, buf, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int main() {
    int file;
    int16_t raw_data[3];
    float gyro_data[3];

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to set signal handler");
        return 1;
    }

    file = open(I2C_BUS, O_RDWR);
    if (file < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(file, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return 1;
    }

    // Wake up the MPU-6050
    if (i2c_write(file, PWR_MGMT_1, 0x00) < 0) {
        close(file);
        return 1;
    }

    // Set gyroscope full scale range to ±250 dps
    if (i2c_write(file, GYRO_CONFIG, 0x00) < 0) {
        close(file);
        return 1;
    }

    printf("Reading gyroscope data...\n");

    while (keep_running) {
        uint8_t buffer[6];
        if (i2c_read(file, GYRO_OUT_REG, buffer, 6) < 0) {
            fprintf(stderr, "Error reading gyroscope data\n");
            continue;
        }

        for (int i = 0; i < 3; i++) {
            raw_data[i] = (buffer[i*2] << 8) | buffer[i*2+1];
            gyro_data[i] = (float)raw_data[i] / LSB_SENSITIVITY;
        }

        printf("Gyroscope (x, y, z): %.2f, %.2f, %.2f dps\n", gyro_data[0], gyro_data[1], gyro_data[2]);
        usleep(100000); // 100ms delay
    }

    close(file);
    return 0;
}

