    while (keep_running) {
        uint8_t buffer[6];
        if (i2c_read(file, GYRO_OUT_REG, buffer, 6) < 0) {
            fprintf(stderr, "Error reading gyroscope data\n");
            continue;
        }

        for (int i = 0; i < 3; i++) {
            raw_data[i] = (buffer[i*2] << 8) | buffer[i*2+1];
            gyro_data[i] = (float)raw_data[i] / LSB_SENSITIVITY;
        }

        printf("Gyroscope (x, y, z): %.2f, %.2f, %.2f dps\n", gyro_data[0], gyro_data[1], gyro_data[2]);
        usleep(100000); // 100ms delay
    }

    close(file);
    return 0;
}
