void log_event(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    FILE *log_file = fopen("smart_lighting.log", "a");
    if (log_file) {
        fprintf(log_file, "[%s] %s\n", time_str, message);
        fclose(log_file);
    }
}

void cleanup(int sig) {
    log_event("Cleaning up and exiting...");
    gpioHardwarePWM(GPIO_PINS[0], 0, 0);
    gpioHardwarePWM(GPIO_PINS[1], 0, 0);
    gpioHardwarePWM(GPIO_PINS[2], 0, 0);
    gpioHardwarePWM(GPIO_PINS[3], 0, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        log_event("Failed to initialize gpio");
        return 1;
    }
    log_event("GPIO initialized");

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(GPIO_PINS[i], PI_OUTPUT) != 0) {
            log_event("Failed to set GPIO mode");
            gpioTerminate();
            return 1;
        }
        if (gpioHardwarePWM(GPIO_PINS[i], PWM_FREQUENCY, 0) != 0) {
            log_event("Failed to set up PWM");
            gpioTerminate();
            return 1;
        }
        log_event("PWM set up on GPIO pin");
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    for (int duty_cycle = 0; duty_cycle <= 255; duty_cycle++) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpioHardwarePWM(GPIO_PINS[i], PWM_FREQUENCY, duty_cycle * 10000);
        }
        time_sleep(STEP_INTERVAL_MS / 1000.0);
    }

    cleanup(0);
    return 0;
}

