#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

#define MPU6050_ADDR 0x68
#define WHO_AM_I_REG 0x75
#define PWR_MGMT_1_REG 0x6B
#define SMPLRT_DIV_REG 0x19
#define GYRO_CONFIG_REG 0x1B
#define GYRO_XOUT_H_REG 0x43
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 20
#define SAMPLE_INTERVAL_MS 50
#define LED_PIN 17
#define GYRO_THRESHOLD 250.0f

typedef struct {
    int16_t x, y, z;
    uint64_t timestamp;
} GyroData;

GyroData gyroBuffer[BUFFER_SIZE];
int bufferIndex = 0;
int i2cHandle;

void cleanup(int signum) {
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    if (i2cHandle >= 0) {
        close(i2cHandle);
    }
    exit(EXIT_SUCCESS);
}

int initMPU6050() {
    int retries = 3;
    while (retries--) {
        i2cHandle = i2cOpen(1, MPU6050_ADDR, 0);
        if (i2cHandle < 0) {
            fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        uint8_t whoAmI;
        if (i2cReadByteData(i2cHandle, WHO_AM_I_REG, &whoAmI) < 0) {
            fprintf(stderr, "Failed to read WHO_AM_I register\n");
            i2cClose(i2cHandle);
            sleep(1);
            continue;
        }

        if (whoAmI != 0x68) {
            fprintf(stderr, "Invalid WHO_AM_I value: 0x%02X\n", whoAmI);
            i2cClose(i2cHandle);
            sleep(1);
            continue;
        }

        if (i2cWriteByteData(i2cHandle, PWR_MGMT_1_REG, 0x00) < 0 ||
            i2cWriteByteData(i2cHandle, SMPLRT_DIV_REG, 0x07) < 0 ||
            i2cWriteByteData(i2cHandle, GYRO_CONFIG_REG, 0x00) < 0) {
            fprintf(stderr, "Failed to configure MPU6050\n");
            i2cClose(i2cHandle);
            sleep(1);
            continue;
        }

        return 0;
    }

    fprintf(stderr, "Failed to initialize MPU6050 after 3 attempts\n");
    return -1;
}

int16_t combineBytes(uint8_t msb, uint8_t lsb) {
    return ((int16_t)msb << 8) | lsb;
}

void readGyroData() {
    uint8_t buffer[6];
    if (i2cReadI2CBlock(i2cHandle, GYRO_XOUT_H_REG, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read gyroscope data\n");
        return;
    }

    GyroData data;
    data.x = combineBytes(buffer[0], buffer[1]);
    data.y = combineBytes(buffer[2], buffer[3]);
    data.z = combineBytes(buffer[4], buffer[5]);
    data.timestamp = time(NULL) * 1000;

    gyroBuffer[bufferIndex] = data;
    bufferIndex = (bufferIndex + 1) % BUFFER_SIZE;

    float maxAngularVelocity = fmaxf(fabsf(data.x), fmaxf(fabsf(data.y), fabsf(data.z)));
    gpioWrite(LED_PIN, maxAngularVelocity > GYRO_THRESHOLD ? 1 : 0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (initMPU6050() < 0) {
        cleanup(0);
    }

    while (1) {
        readGyroData();
        gpioSleep(PI_TIME_RELATIVE, 0, SAMPLE_INTERVAL_MS * 1000000);
    }

    return EXIT_SUCCESS;
}

