#define SPI_DEVICE "/dev/spidev0.0"
#define GYRO_XOUT_H 0x43
#define GYRO_SCALE_FACTOR 131.0
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define CS_PIN 8
#define LOG_FILE "gyro_log.txt"
#define MAX_RETRIES 3

static int spi_fd;
static struct gpiod_line *cs_line;
static FILE *log_file;

void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void handle_signal(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int setup_spi(void) {
    int ret;
    struct spi_ioc_transfer xfer = {
        .bits_per_word = SPI_BITS_PER_WORD,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int setup_gpio(void) {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(cs_line, "mpu9250_cs", 1);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

int read_gyro_data(int16_t *x_rate, int16_t *y_rate, int16_t *z_rate) {
    uint8_t tx[7] = {GYRO_XOUT_H, 0, 0, 0, 0, 0, 0};
    uint8_t rx[7];
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .cs_change = 0,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    gpiod_line_set_value(cs_line, 0);
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
        if (ret < 0) {
            perror("SPI transfer failed");
            retries++;
            usleep(10000); // 10ms delay before retry
            continue;
        }
        *x_rate = ((int16_t)rx[1] << 8) | rx[2];
        *y_rate = ((int16_t)rx[3] << 8) | rx[4];
        *z_rate = ((int16_t)rx[5] << 8) | rx[6];
        gpiod_line_set_value(cs_line, 1);
        return 0;
    }
    fprintf(stderr, "Failed to read gyro data after %d retries\n", MAX_RETRIES);
    gpiod_line_set_value(cs_line, 1);
    return -1;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (setup_spi() < 0 || setup_gpio() < 0) {
        fprintf(stderr, "Failed to initialize SPI or GPIO\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        int16_t x_rate, y_rate, z_rate;
        if (read_gyro_data(&x_rate, &y_rate, &z_rate) == 0) {
            struct timespec ts;
            char timestamp[64];

            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));
            fprintf(log_file, "%s.%09ld,%f,%f,%f\n", timestamp, ts.tv_nsec,
                    x_rate / GYRO_SCALE_FACTOR, y_rate / GYRO_SCALE_FACTOR, z_rate / GYRO_SCALE_FACTOR);
            fflush(log_file);
        }
        usleep(10000); // 10ms delay
    }

    cleanup();
    return EXIT_SUCCESS;
}
