        circular_buffer[buffer_index] = data;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        float max_dps = fmaxf(fabsf(gyro_x / LSB_TO_DPS),
                              fmaxf(fabsf(gyro_y / LSB_TO_DPS),
                                    fabsf(gyro_z / LSB_TO_DPS)));

