#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_OUT_X 0x3B
#define ACCEL_OUT_Y 0x3D
#define ACCEL_OUT_Z 0x3F
#define LED_PIN 21
#define I2C_BUS 1
#define SAMPLE_INTERVAL_MS 100

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_LOW);

    int i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Wake the sensor
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU6050\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set accelerometer full-scale range to ±2g
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set accelerometer config\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("tilt_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    char buffer[7];
    time_t now;
    struct tm *timeinfo;
    double roll, pitch;

    while (keep_running) {
        if (i2cReadI2CBlock(i2c_handle, ACCEL_OUT_X, 6, buffer) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        short x = (buffer[0] << 8) | buffer[1];
        short y = (buffer[2] << 8) | buffer[3];
        short z = (buffer[4] << 8) | buffer[5];

        roll = atan2(y, z) * 180.0 / M_PI;
        pitch = atan2(-x, sqrt(y * y + z * z)) * 180.0 / M_PI;

        printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);

        now = time(NULL);
        timeinfo = localtime(&now);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
                roll, pitch);

        fflush(log_file);

        if (fabs(roll) > 45.0 || fabs(pitch) > 45.0) {
            gpioWrite(LED_PIN, PI_HIGH);
        } else {
            gpioWrite(LED_PIN, PI_LOW);
        }

        gpioSleep(PI_TIME_RELATIVE, 0, SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, PI_LOW);
    gpioTerminate();

    return 0;
}

