#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x5A
#define AMBIENT_LIGHT_REG 0x20
#define PROXIMITY_REG 0x22
#define LED_PIN 17
#define LOG_FILE "biometric_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

int i2c_fd;
FILE *log_file;
struct gpiod_chip *chip;
struct gpiod_line *led_line;

void cleanup(int signum) {
    printf("Cleaning up...\n");
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t reg, uint8_t *data, size_t len) {
    uint8_t buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    return write(fd, buf, len + 1);
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, data, len);
}

int read_sensor_data(uint16_t *ambient_light, uint16_t *proximity) {
    uint8_t buf[4];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (i2c_read(i2c_fd, AMBIENT_LIGHT_REG, buf, 2) == 2 &&
            i2c_read(i2c_fd, PROXIMITY_REG, buf + 2, 2) == 2) {
            *ambient_light = buf[1] | (buf[0] << 8);
            *proximity = buf[3] | (buf[2] << 8);
            return 0;
        }
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "Si1145 LED", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    time_t now;
    struct tm *timeinfo;
    char timestamp[20];
    uint16_t ambient_light, proximity;

    while (1) {
        if (read_sensor_data(&ambient_light, &proximity) == 0) {
            time(&now);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, ambient_light, proximity);
            fflush(log_file);

            if (proximity > 100) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        usleep(100000);  // 100ms
    }

    return EXIT_SUCCESS;
}

