#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define X_RATE_REG 0x02
#define Y_RATE_REG 0x04
#define READ_BIT 0x80
#define SAMPLE_DELAY_MS 10
#define MAX_REINIT_ATTEMPTS 3

FILE *file;
int spi_handle;

void cleanup(int signum) {
    if (file) {
        fflush(file);
        fclose(file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int init_spi() {
    int attempts = 0;
    while (attempts < MAX_REINIT_ATTEMPTS) {
        if (gpioInitialise() < 0) {
            fprintf(stderr, "pigpio initialisation failed\n");
            return -1;
        }

        spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
        if (spi_handle < 0) {
            fprintf(stderr, "SPI open failed, attempt %d\n", attempts + 1);
            gpioTerminate();
            attempts++;
            sleep(1);
        } else {
            return 0;
        }
    }
    return -1;
}

int16_t read_register(uint8_t reg) {
    uint8_t tx[2] = {reg | READ_BIT, 0x00};
    uint8_t rx[2];
    if (spiXfer(spi_handle, tx, rx, 2) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return 0;
    }
    return (int16_t)((rx[0] << 8) | rx[1]);
}

int main() {
    struct timespec ts;
    struct tm *tm_info;
    char timestamp[64];

    signal(SIGINT, cleanup);

    file = fopen("gyro_data.csv", "w");
    if (!file) {
        fprintf(stderr, "Failed to open gyro_data.csv\n");
        return EXIT_FAILURE;
    }
    fprintf(file, "timestamp,X rate,Y rate\n");

    if (init_spi() < 0) {
        fprintf(stderr, "Failed to initialise SPI after %d attempts\n", MAX_REINIT_ATTEMPTS);
        return EXIT_FAILURE;
    }

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        tm_info = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(file, "%s.%06ld,", timestamp, ts.tv_nsec / 1000);

        int16_t x_rate = read_register(X_RATE_REG);
        int16_t y_rate = read_register(Y_RATE_REG);

        if (x_rate == 0 && y_rate == 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            cleanup(SIGINT);
        }

        fprintf(file, "%d,%d\n", x_rate, y_rate);
        fflush(file);

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    return EXIT_SUCCESS;
}

