#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define ALERT_PIN 17
#define ALERT_DURATION_MS 2000
#define SEISMIC_THRESHOLD_MS 500

static FILE *log_file = NULL;
static volatile int seismic_event = 0;
static volatile time_t seismic_start_time = 0;

void log_seismic_event() {
    time_t now;
    time(&now);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
    fflush(log_file);
}

void alert_seismic_event() {
    gpioWrite(ALERT_PIN, 1);
    time_sleep(ALERT_DURATION_MS / 1000.0);
    gpioWrite(ALERT_PIN, 0);
}

void seismic_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        if (seismic_start_time == 0) {
            seismic_start_time = tick;
        }
    } else {
        if (seismic_start_time != 0) {
            uint32_t duration = tick - seismic_start_time;
            if (duration >= SEISMIC_THRESHOLD_MS * 1000) {
                seismic_event = 1;
            }
            seismic_start_time = 0;
        }
    }
}

void signal_handler(int signo) {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR2_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN) < 0 ||
        gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-up/down for sensors\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR1_PIN, seismic_callback) < 0 ||
        gpioSetAlertFunc(SENSOR2_PIN, seismic_callback) < 0) {
        fprintf(stderr, "Failed to set GPIO callbacks\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        if (seismic_event) {
            log_seismic_event();
            alert_seismic_event();
            seismic_event = 0;
        }
        gpioSleep(PI_TIME_RELATIVE, 0, 100000); // Sleep for 100ms
    }

    return EXIT_SUCCESS;
}

