#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define BUFFER_SIZE 100
#define RATE_XL 0x02
#define RATE_XH 0x03
#define LED_PIN 17
#define THRESHOLD 20.0

typedef struct {
    int16_t rate;
    struct timespec timestamp;
} GyroData;

typedef struct {
    GyroData data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

CircularBuffer buffer = {.head = 0, .tail = 0, .count = 0};

void buffer_init() {
    pthread_mutex_init(&buffer.mutex, NULL);
}

void buffer_push(GyroData *gyroData) {
    pthread_mutex_lock(&buffer.mutex);
    if (buffer.count < BUFFER_SIZE) {
        buffer.data[buffer.head] = *gyroData;
        buffer.head = (buffer.head + 1) % BUFFER_SIZE;
        buffer.count++;
    } else {
        buffer.tail = (buffer.tail + 1) % BUFFER_SIZE;
        buffer.data[buffer.head] = *gyroData;
        buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    }
    pthread_mutex_unlock(&buffer.mutex);
}

void cleanup(int signum) {
    gpioWrite(LED_PIN, 0);
    gpioSetMode(LED_PIN, PI_INPUT);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int16_t read_gyro_register(uint8_t reg) {
    uint8_t tx[2] = {reg | 0x80, 0x00};
    uint8_t rx[2] = {0};
    if (gpioSPIXfer(SPI_CHANNEL, SPI_CE, tx, rx, 2) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return 0;
    }
    return (int16_t)((rx[0] << 8) | rx[1]);
}

void *gyro_read_thread(void *arg) {
    (void)arg;
    while (1) {
        int16_t rate_xl = read_gyro_register(RATE_XL);
        int16_t rate_xh = read_gyro_register(RATE_XH);
        int16_t rate = (rate_xh << 8) | rate_xl;
