#include <unistd.h>

#define GPIO_LAMP1 17
#define GPIO_LAMP2 18
#define GPIO_LAMP3 27
#define PWM_FREQ 100
#define PWM_RANGE 255

volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

void cleanup(int gpio1, int gpio2, int gpio3) {
    gpioSetPWMfrequency(gpio1, 0);
    gpioSetPWMfrequency(gpio2, 0);
    gpioSetPWMfrequency(gpio3, 0);
    gpioTerminate();
    printf("All lamps turned off and resources released.\n");
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_in_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int duration = atoi(argv[1]);
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: Duration must be between 1 and 3600 seconds.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LAMP1, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_LAMP2, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_LAMP3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(GPIO_LAMP1, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GPIO_LAMP2, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GPIO_LAMP3, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency.\n");
        cleanup(GPIO_LAMP1, GPIO_LAMP2, GPIO_LAMP3);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Smart Sunset Simulator started.\n");
    printf("Fading duration: %d seconds.\n", duration);

    for (int lamp = GPIO_LAMP1; lamp <= GPIO_LAMP3; lamp++) {
        if (terminate) break;

        printf("Starting fade for lamp on GPIO%d.\n", lamp);
        for (int duty = PWM_RANGE; duty >= 0; duty--) {
            if (terminate) break;
            gpioPWM(lamp, duty);
            usleep((duration * 1000000) / PWM_RANGE);
        }
        printf("Lamp on GPIO%d has finished fading.\n", lamp);
    }

    if (!terminate) {
        printf("Smart Sunset Simulator completed.\n");
    } else {
        printf("Smart Sunset Simulator terminated.\n");
    }

    cleanup(GPIO_LAMP1, GPIO_LAMP2, GPIO_LAMP3);
    return EXIT_SUCCESS;
}

