#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RED_PIN 17
#define YELLOW_PIN 22
#define GREEN_PIN 23
#define BLUE_PIN 24

#define RED_TIME 10
#define RED_YELLOW_TIME 2
#define GREEN_TIME 10
#define YELLOW_TIME 3

static struct gpiod_chip *chip;
static struct gpiod_line *lines[4];

void cleanup(int signum) {
    printf("Cleaning up and exiting...\n");
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    int gpio_pins[] = {RED_PIN, YELLOW_PIN, GREEN_PIN, BLUE_PIN};
    const char *state_names[] = {"Red", "Red+Yellow", "Green", "Yellow"};
    int num_states = sizeof(state_names) / sizeof(state_names[0]);

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", gpio_pins[i]);
            cleanup(0);
        }

        int ret = gpiod_line_request_output(lines[i], "traffic_light", 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line for GPIO %d\n", gpio_pins[i]);
            cleanup(0);
        }
    }

    while (1) {
        for (int i = 0; i < num_states; i++) {
            printf("State: %s\n", state_names[i]);

            // Set all lines to HIGH (OFF)
            for (int j = 0; j < 4; j++) {
                int ret = gpiod_line_set_value(lines[j], 1);
                if (ret < 0) {
                    fprintf(stderr, "Failed to set GPIO %d to HIGH\n", gpio_pins[j]);
                    cleanup(0);
                }
            }

            // Set the current state line to LOW (ON)
            int ret = gpiod_line_set_value(lines[i], 0);
            if (ret < 0) {
                fprintf(stderr, "Failed to set GPIO %d to LOW\n", gpio_pins[i]);
                cleanup(0);
            }

            sleep(i == 0 ? RED_TIME : (i == 1 ? RED_YELLOW_TIME : (i == 2 ? GREEN_TIME : YELLOW_TIME)));
        }
    }

    return EXIT_SUCCESS;
}

