#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define I2C_FILE "/dev/i2c-1"
#define LOG_FILE "touch_relay.log"
#define DEBOUNCE_TIME_MS 100
#define CHECK_INTERVAL_MS 10

static int i2c_handle;
static FILE *log_file;

void log_message(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] %s\n", time_str, message);
    fflush(log_file);
}

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        close(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (gpioInitialised()) {
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    if (gpioInitialise() < 0) {
        log_message("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, PI_LOW);

    i2c_handle = open(I2C_FILE, O_RDWR);
    if (i2c_handle < 0) {
        log_message("Failed to open I2C bus");
        cleanup(0);
    }

    if (ioctl(i2c_handle, I2C_SLAVE, MPR121_ADDR) < 0) {
        log_message("Failed to set I2C slave address");
        cleanup(0);
    }

    uint8_t init_sequence[][2] = {
        {0x80, 0x63}, {0x5E, 0x00}, {0x5D, 0x01},
        {0x41, 0x0A}, {0x42, 0x08}, {0x5B, 0x21},
        {0x5C, 0x0D}, {0x5E, 0x0D}
    };

    for (size_t i = 0; i < sizeof(init_sequence) / sizeof(init_sequence[0]); i++) {
        if (i2c_smbus_write_byte_data(i2c_handle, init_sequence[i][0], init_sequence[i][1]) < 0) {
            char buffer[100];
            snprintf(buffer, sizeof(buffer), "Failed to configure MPR121 register 0x%02X", init_sequence[i][0]);
            log_message(buffer);
            cleanup(0);
        }
    }

    log_message("System initialized successfully");

    uint8_t last_touch_state = 0;
    time_t last_touch_time = 0;

    while (1) {
        uint8_t touch_data[2];
        if (i2c_smbus_read_i2c_block_data(i2c_handle, 0x00, 2, touch_data) < 0) {
            log_message("Failed to read touch data from MPR121");
            continue;
        }

        uint8_t touch_state = touch_data[0] | (touch_data[1] << 8);
        if (touch_state & 0x01) { // electrode 0 is touched
            time_t current_time = time(NULL);
            if (current_time - last_touch_time > DEBOUNCE_TIME_MS / 1000) {
                gpioWrite(RELAY_PIN, !gpioRead(RELAY_PIN));
                last_touch_time = current_time;
                log_message("Relay toggled");
            }
        }

        gpioDelay(CHECK_INTERVAL_MS * 1000);
    }

    return 0;
}

