#define SOLENOID1_PIN 17
#define SOLENOID2_PIN 27
#define DISPENSE_DURATION_MS 1000
#define DISPENSE_INTERVAL_MS 5000

void log_dispense_event(int solenoid1, int solenoid2, int duration_ms) {
    FILE *log_file = fopen("dispense_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline

    fprintf(log_file, "[%s] Solenoid1: %d, Solenoid2: %d, Duration: %d ms\n",
            time_str, solenoid1, solenoid2, duration_ms);
    fclose(log_file);
}

void dispense_solenoids() {
    gpioWrite(SOLENOID1_PIN, 1);
    gpioDelay(DISPENSE_DURATION_MS * 500); // Half of the total duration
    gpioWrite(SOLENOID1_PIN, 0);

    gpioWrite(SOLENOID2_PIN, 1);
    gpioDelay(DISPENSE_DURATION_MS * 500); // Remaining half
    gpioWrite(SOLENOID2_PIN, 0);

    log_dispense_event(SOLENOID1_PIN, SOLENOID2_PIN, DISPENSE_DURATION_MS);
}

void signal_handler(int signo) {
    if (signo == SIGINT) {
        gpioWrite(SOLENOID1_PIN, 0);
        gpioWrite(SOLENOID2_PIN, 0);
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(SOLENOID2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        dispense_solenoids();
        gpioDelay(DISPENSE_INTERVAL_MS * 1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

