#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>
#include <math.h>
#include <float.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENABLE_A 24
#define ENABLE_B 25
#define PID_KP 1.0
#define PID_KI 0.01
#define PID_KD 0.1
#define MOTOR_SPEED_LIMIT 255
#define CONTROL_INTERVAL_MS 50
#define LOG_FILE "balance_log.txt"

typedef struct {
    double integral;
    double previous_error;
} PIDController;

void initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENABLE_A, PI_OUTPUT);
    gpioSetMode(ENABLE_B, PI_OUTPUT);
    gpioWrite(ENABLE_A, PI_HIGH);
    gpioWrite(ENABLE_B, PI_HIGH);
}

void terminate_gpio() {
    gpioTerminate();
}

double get_random_float(double min, double max) {
    return min + (max - min) * ((double)rand() / RAND_MAX);
}

double simulate_tilt_error() {
    return get_random_float(-10.0, 10.0);
}

double simulate_distance_sensor() {
    return get_random_float(2.0, 400.0);
}

double calculate_pid_output(PIDController *pid, double setpoint, double measured_value, double dt) {
    double error = setpoint - measured_value;
    pid->integral += error * dt;
    double derivative = (error - pid->previous_error) / dt;
    double output = PID_KP * error + PID_KI * pid->integral + PID_KD * derivative;
    pid->previous_error = error;
    return output;
}

void set_motor_speeds(int motor_a_speed, int motor_b_speed) {
    if (motor_a_speed > 0) {
        gpioWrite(MOTOR_A_FORWARD, PI_HIGH);
        gpioPWM(MOTOR_A_BACKWARD, 0);
        gpioPWM(MOTOR_A_FORWARD, motor_a_speed);
    } else if (motor_a_speed < 0) {
        gpioWrite(MOTOR_A_BACKWARD, PI_HIGH);
        gpioPWM(MOTOR_A_FORWARD, 0);
        gpioPWM(MOTOR_A_BACKWARD, -motor_a_speed);
    } else {
        gpioPWM(MOTOR_A_FORWARD, 0);
        gpioPWM(MOTOR_A_BACKWARD, 0);
    }

    if (motor_b_speed > 0) {
        gpioWrite(MOTOR_B_FORWARD, PI_HIGH);
        gpioPWM(MOTOR_B_BACKWARD, 0);
        gpioPWM(MOTOR_B_FORWARD, motor_b_speed);
    } else if (motor_b_speed < 0) {
        gpioWrite(MOTOR_B_BACKWARD, PI_HIGH);
        gpioPWM(MOTOR_B_FORWARD, 0);
        gpioPWM(MOTOR_B_BACKWARD, -motor_b_speed);
    } else {
        gpioPWM(MOTOR_B_FORWARD, 0);
        gpioPWM(MOTOR_B_BACKWARD, 0);
    }
}

void log_data(FILE *log_file, double tilt_error, double distance, int motor_a_speed, int motor_b_speed) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f, %d, %d\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec,
            tilt_error, distance, motor_a_speed, motor_b_speed);
}

void handle_sigint(int sig) {
    printf("Received SIGINT, stopping motors and exiting...\n");
    set_motor_speeds(0, 0);
    terminate_gpio();
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);
    initialize_gpio();

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        terminate_gpio();
        exit(1);
    }

    PIDController pid = {0, 0};
    double setpoint = 0.0;
    struct timespec last_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &last_time);

    while (1) {
        double tilt_error = simulate_tilt_error();
        double distance = simulate_distance_sensor();

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double dt = (current_time.tv_sec - last_time.tv_sec) + (current_time.tv_nsec - last_time.tv_nsec) / 1e9;
        last_time = current_time;

        double pid_output = calculate_pid_output(&pid, setpoint, tilt_error, dt);
        int motor_a_speed = (int)pid_output;
        int motor_b_speed = (int)pid_output;

        if (distance < 20.0) {
            motor_a_speed = -MOTOR_SPEED_LIMIT / 2;
            motor_b_speed = -MOTOR_SPEED_LIMIT / 2;
        }

        motor_a_speed = (motor_a_speed > MOTOR_SPEED_LIMIT) ? MOTOR_SPEED_LIMIT : (motor_a_speed < -MOTOR_SPEED_LIMIT) ? -MOTOR_SPEED_LIMIT : motor_a_speed;
        motor_b_speed = (motor_b_speed > MOTOR_SPEED_LIMIT) ? MOTOR_SPEED_LIMIT : (motor_b_speed < -MOTOR_SPEED_LIMIT) ? -MOTOR_SPEED_LIMIT : motor_b_speed;

        set_motor_speeds(motor_a_speed, motor_b_speed);
        log_data(log_file, tilt_error, distance, motor_a_speed, motor_b_speed);

        gpioDelay(CONTROL_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    return 0;
}

