#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define TOUCH_SENSOR_PIN 4
#define DEBOUNCE_TIME_MS 50

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Smart light switch running. Press Ctrl+C to exit.\n");

    while (keep_running) {
        if (gpioRead(TOUCH_SENSOR_PIN) == PI_HIGH) {
            gpioSleep(PI_TIME_MILLISECONDS, DEBOUNCE_TIME_MS, 0);

            if (gpioRead(TOUCH_SENSOR_PIN) == PI_HIGH) {
                int current_state = gpioRead(RELAY_PIN);
                gpioWrite(RELAY_PIN, !current_state);
                printf("Relay toggled to %s\n", !current_state ? "ON" : "OFF");

                while (gpioRead(TOUCH_SENSOR_PIN) == PI_HIGH) {
                    gpioSleep(PI_TIME_MILLISECONDS, 10, 0);
                }
            }
        }
        gpioSleep(PI_TIME_MILLISECONDS, 10, 0);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

