float compute_rms_amplitude(short *buffer, int size) {
    long long sum = 0;
    for (int i = 0; i < size; i++) {
        sum += (long long)buffer[i] * buffer[i];
    }
    float mean_square = (float)sum / size;
    return sqrt(mean_square);
