    float normalized = amplitude / 32767.0;
    normalized = pow(normalized, 2.0);  // Non-linear mapping
    normalized = fminf(normalized * sensitivity, 1.0);

    *red = (int)(255 * (1 - normalized));
    *green = (int)(255 * normalized);
    *blue = 0;
