#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x29
#define POWER_ON_REG 0x80
#define ENABLE_REG 0x80
#define INTEGRATION_TIME_REG 0x81
#define DATA_REG 0x14
#define INTEGRATION_TIME 0xD5
#define SAMPLE_INTERVAL_MS 500

static int i2cHandle;
static FILE *csvFile;

void signalHandler(int signo) {
    if (i2cHandle >= 0) {
        gpioI2CClose(i2cHandle);
    }
    if (csvFile) {
        fclose(csvFile);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2cHandle = gpioI2COpen(I2C_BUS, SENSOR_ADDR);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioI2CWriteByteData(i2cHandle, POWER_ON_REG, 0x03) < 0) {
        fprintf(stderr, "Failed to set power-on and enable\n");
        gpioI2CClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioI2CWriteByteData(i2cHandle, INTEGRATION_TIME_REG, INTEGRATION_TIME) < 0) {
        fprintf(stderr, "Failed to set integration time\n");
        gpioI2CClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    csvFile = fopen("color_data.csv", "w");
    if (!csvFile) {
        fprintf(stderr, "Failed to open CSV file\n");
        gpioI2CClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(csvFile, "Timestamp,C,R,G,B\n");

    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    while (1) {
        time_t now = time(NULL);
        unsigned char data[8];
        int result;

        result = gpioI2CReadI2CBlock(i2cHandle, DATA_REG, data, 8);
        if (result < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            data[0] = data[1] = data[2] = data[3] = data[4] = data[5] = data[6] = data[7] = 0;
        }

        unsigned int clear = (data[1] << 8) | data[0];
        unsigned int red = (data[3] << 8) | data[2];
        unsigned int green = (data[5] << 8) | data[4];
        unsigned int blue = (data[7] << 8) | data[6];

        fprintf(csvFile, "%ld,%u,%u,%u,%u\n", now, clear, red, green, blue);
        fflush(csvFile);

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

