#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>

#define NUM_RELAYS 4
#define GPIO_PINS[NUM_RELAYS] = {17, 27, 22, 23}
#define RELAY_PIN_NAMES[NUM_RELAYS] = {"GPIO17", "GPIO27", "GPIO22", "GPIO23"}
#define PHASE_DURATION_SUNRISE 3600
#define PHASE_DURATION_DAYTIME 21600
#define PHASE_DURATION_SUNSET 3600
#define PHASE_DURATION_NIGHTTIME 51840
#define MAX_DUTY_CYCLE 100
#define DUTY_CYCLE_STEP 1

struct gpiod_line *lines[NUM_RELAYS];
struct gpiod_chip *chip;

void cleanup(int signum) {
    printf("Cleaning up and exiting...\n");
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1); // Active-low, so set to 1 to turn off
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

bool initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Unable to open GPIO chip\n");
        return false;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error: Unable to get line for GPIO %d\n", GPIO_PINS[i]);
            return false;
        }

        int ret = gpiod_line_request_output(lines[i], "RelayControl", 1);
        if (ret < 0) {
            fprintf(stderr, "Error: Unable to request line for GPIO %d\n", GPIO_PINS[i]);
            return false;
        }
    }
    return true;
}

void set_relay_state(int duty_cycle) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_set_value(lines[i], duty_cycle > 0 ? 0 : 1);
    }
}

void simulate_phase(int duration, int start_duty_cycle, int end_duty_cycle) {
    int step = (start_duty_cycle < end_duty_cycle) ? DUTY_CYCLE_STEP : -DUTY_CYCLE_STEP;
    for (int duty_cycle = start_duty_cycle; (step > 0 && duty_cycle <= end_duty_cycle) || (step < 0 && duty_cycle >= end_duty_cycle); duty_cycle += step) {
        set_relay_state(duty_cycle);
        sleep(1);
    }
    sleep(duration - (abs(start_duty_cycle - end_duty_cycle) * 2));
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (!initialize_gpio()) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting...\n");
        return EXIT_FAILURE;
    }

    while (1) {
