        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(MOTION_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up/down\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(MOTION_PIN, motion_callback) < 0) {
        fprintf(stderr, "Failed to set alert function\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Motion detection system started");

    while (1) {
        gpioSleep(PI_TIME_SECONDS, 1, 0);
    }

    return EXIT_SUCCESS;
}

