#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>

#define MPU6050_ADDR 0x68
#define SAMPLE_RATE_DIV 124
#define GYRO_FS_SEL 0x00
#define GYRO_CONFIG_REG 0x1B
#define SMPLRT_DIV_REG 0x19
#define PWR_MGMT_1_REG 0x6B
#define GYRO_OUT_REG 0x43
#define GYRO_LSB_SENSITIVITY 131.0
#define SAMPLE_INTERVAL_MS 10
#define MAX_REINIT_ATTEMPTS 3

FILE *log_file;
int i2c_handle;

void signal_handler(int signo) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int initialize_sensor() {
    int attempts = 0;
    while (attempts < MAX_REINIT_ATTEMPTS) {
        if (i2cWriteByteData(i2c_handle, PWR_MGMT_1_REG, 0x00) < 0) {
            attempts++;
            continue;
        }
        gpioSleep(MILLISECONDS, 10, 0); // Wait 10ms for sensor to wake up
        if (i2cWriteByteData(i2c_handle, SMPLRT_DIV_REG, SAMPLE_RATE_DIV) < 0) {
            attempts++;
            continue;
        }
        if (i2cWriteByteData(i2c_handle, GYRO_CONFIG_REG, GYRO_FS_SEL) < 0) {
            attempts++;
            continue;
        }
        return 0; // Success
    }
    return -1; // Failure
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor() != 0) {
        fprintf(stderr, "Failed to initialize sensor after %d attempts\n", MAX_REINIT_ATTEMPTS);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");

    char buffer[14];
    struct timespec ts;
    long long timestamp;

    while (1) {
        if (i2cReadI2CBlockData(i2c_handle, GYRO_OUT_REG, buffer, 14) < 0) {
            if (initialize_sensor() != 0) {
                fprintf(stderr, "Failed to reinitialize sensor after read failure\n");
                continue;
            }
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        timestamp = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

        int16_t x = (buffer[0] << 8) | buffer[1];
        int16_t y = (buffer[2] << 8) | buffer[3];
        int16_t z = (buffer[4] << 8) | buffer[5];

        float x_degps = x / GYRO_LSB_SENSITIVITY;
        float y_degps = y / GYRO_LSB_SENSITIVITY;
        float z_degps = z / GYRO_LSB_SENSITIVITY;

        fprintf(log_file, "%lld,%.2f,%.2f,%.2f\n", timestamp, x_degps, y_degps, z_degps);
        fflush(log_file);

        gpioSleep(MILLISECONDS, SAMPLE_INTERVAL_MS, 0);
    }

    return EXIT_SUCCESS;
}

