#define ADXL345_ADDR 0x53
#define DATA_FORMAT_REG 0x31
#define POWER_CTL_REG 0x2D
#define DATAX0_REG 0x32
#define FREEFALL_THRESHOLD 0.2
#define FREEFALL_DURATION 0.5
#define ALARM_PIN 27
#define I2C_BUS 1
#define SCALE_FACTOR 256.0

static int i2cHandle;

void signalHandler(int signo) {
    if (signo == SIGINT) {
        gpioWrite(ALARM_PIN, LOW);
        gpioTerminate();
        if (i2cHandle >= 0) {
            close(i2cHandle);
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2cHandle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2cHandle, DATA_FORMAT_REG, 0x0B) < 0) {
        fprintf(stderr, "Failed to set DATA_FORMAT register\n");
        close(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
