#define TRIG_PIN 4
#define ECHO_PIN 18
#define TRIGGER_INTERVAL_MS 200
#define MAX_ECHO_WIDTH_US 23200
#define TIMEOUT_US 100000
#define LOG_FILE "distance_log.txt"

static volatile uint32_t last_echo_start_tick = 0;
static volatile uint32_t last_echo_end_tick = 0;
static volatile int echo_received = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static int gpio_initialized = 0;
static int callback_initialized = 0;

void cleanup(int sig) {
    if (callback_initialized) {
        gpioSetAlertFunc(ECHO_PIN, NULL);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_initialized) {
        gpioTerminate();
    }
    pthread_mutex_destroy(&mutex);
    exit(EXIT_SUCCESS);
}

void echo_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    if (level == 1) {
        last_echo_start_tick = tick;
        echo_received = 1;
    } else {
        last_echo_end_tick = tick;
    }
    pthread_mutex_unlock(&mutex);
}

void trigger_pulse() {
    gpioWrite(TRIG_PIN, PI_HIGH);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, PI_LOW);
}

uint32_t get_pulse_width() {
    uint32_t start_tick, end_tick;
    pthread_mutex_lock(&mutex);
    start_tick = last_echo_start_tick;
    end_tick = last_echo_end_tick;
    echo_received = 0;
    pthread_mutex_unlock(&mutex);

    if (start_tick == 0 || end_tick == 0) {
        return 0;
    }

    if (end_tick >= start_tick) {
        return end_tick - start_tick;
    } else {
        return (0xFFFFFFFF - start_tick) + end_tick + 1;
    }
}

void log_distance(uint32_t distance_cm, uint64_t timestamp_ns) {
    if (log_file) {
        fprintf(log_file, "%llu,%u\n", timestamp_ns, distance_cm);
        fflush(log_file);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }
    gpio_initialized = 1;

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Failed to set echo callback\n");
        cleanup(SIGINT);
    }
    callback_initialized = 1;

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(SIGINT);
    }

    struct timespec ts;
    uint64_t last_trigger_time = 0;

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        uint64_t current_time_ns = ts.tv_sec * 1000000000ULL + ts.tv_nsec;

        if (current_time_ns - last_trigger_time >= TRIGGER_INTERVAL_MS * 1000000ULL) {
            trigger_pulse();
            last_trigger_time = current_time_ns;
        }

        uint32_t pulse_width = get_pulse_width();
        if (echo_received && pulse_width > 0 && pulse_width <= MAX_ECHO_WIDTH_US) {
            uint32_t distance_cm = pulse_width / 58;
            log_distance(distance_cm, current_time_ns);
        }

        gpioDelay(1000);
    }

    cleanup(SIGINT);
    return EXIT_SUCCESS;
}

