#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define OUT_X_L 0x28
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define BUZZER_PIN 17
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5
#define SENSITIVITY 16384.0
#define RETRY_LIMIT 3

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int init_i2c() {
    int i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", gpioStrError(i2c_handle));
        return -1;
    }
    return i2c_handle;
}

int configure_lis3dh(int i2c_handle, float freefall_threshold, float impact_threshold) {
    int retries = 0;
    while (retries < RETRY_LIMIT) {
        char ctrl_reg1 = 0x77; // 100 Hz, ±2g
        char ctrl_reg4 = 0x00; // High resolution mode

        if (i2cWriteByteData(i2c_handle, CTRL_REG1, ctrl_reg1) < 0 ||
            i2cWriteByteData(i2c_handle, CTRL_REG4, ctrl_reg4) < 0) {
            fprintf(stderr, "Failed to configure LIS3DH, retry %d\n", retries + 1);
            retries++;
            gpioSleep(1, 0, 100000000); // 100ms delay
        } else {
            return 0;
        }
    }
    return -1;
}

int read_acceleration(int i2c_handle, int16_t *ax, int16_t *ay, int16_t *az) {
    char buffer[6];
    if (i2cReadI2CBlock(i2c_handle, OUT_X_L, buffer, 6) < 0) {
        return -1;
    }
    *ax = (buffer[1] << 8) | buffer[0];
    *ay = (buffer[3] << 8) | buffer[2];
    *az = (buffer[5] << 8) | buffer[4];
    return 0;
}

void activate_buzzer(int duration_ms) {
    gpioWrite(BUZZER_PIN, 1);
    gpioSleep(1, 0, duration_ms * 1000000);
    gpioWrite(BUZZER_PIN, 0);
}

int main(int argc, char *argv[]) {
    float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    float impact_threshold = DEFAULT_IMPACT_THRESHOLD;

    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    int i2c_handle = init_i2c();
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    if (configure_lis3dh(i2c_handle, freefall_threshold, impact_threshold) < 0) {
        fprintf(stderr, "Failed to configure LIS3DH\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Fall detection system started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int16_t ax, ay, az;
        if (read_acceleration(i2c_handle, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue;
        }

        float ax_g = (float)ax / SENSITIVITY;
        float ay_g = (float)ay / SENSITIVITY;
        float az_g = (float)az / SENSITIVITY;

        float magnitude = sqrt(ax_g * ax_g + ay_g * ay_g + az_g * az_g);

        if (magnitude < freefall_threshold) {
            printf("Freefall detected!\n");
            activate_buzzer(1000);
        } else if (magnitude > impact_threshold) {
            printf("Impact detected!\n");
            activate_buzzer(1000);
        }

        gpioSleep(1, 0, 10000000); // 100ms delay
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

