#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>
#include <syslog.h>

#define DEFAULT_I2C_ADDR 0x18
#define DEFAULT_THRESHOLD 2.0
#define SAMPLE_INTERVAL_MS 100
#define SENSOR_READ_INTERVAL_MS 1000
#define ACCEL_SCALE 0.0009765625

static int i2cHandle;
static int i2cAddress;
static float threshold;

void cleanup(int sig) {
    if (i2cHandle >= 0) {
        i2cClose(i2cHandle);
    }
    gpioTerminate();
    closelog();
    exit(0);
}

int configureSensor() {
    if (i2cWriteByteData(i2cHandle, 0x20, 0x57) < 0 || // CTRL_REG1: 100 Hz, high-res mode
        i2cWriteByteData(i2cHandle, 0x23, 0x88) < 0) { // CTRL_REG4: ±2g range
        return -1;
    }
    return 0;
}

int readAccelData(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    if (i2cReadI2CBlockData(i2cHandle, 0x28 | 0x80, buffer, 6) != 6) {
        return -1;
    }
    *x = (buffer[0] | (buffer[1] << 8)) >> 4;
    *y = (buffer[2] | (buffer[3] << 8)) >> 4;
    *z = (buffer[4] | (buffer[5] << 8)) >> 4;
    return 0;
}

void logHighAccel(float x, float y, float z) {
    time_t now;
    time(&now);
    char *timeStr = ctime(&now);
    timeStr[strlen(timeStr) - 1] = '\0'; // Remove newline

    syslog(LOG_ALERT, "High acceleration detected at %s: X=%.3f g, Y=%.3f g, Z=%.3f g",
           timeStr, x, y, z);

    system("sudo shutdown -h now");
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2cAddress = strtol(optarg, NULL, 16);
                if (i2cAddress < 0x08 || i2cAddress > 0x77) {
                    fprintf(stderr, "Invalid I2C address. Must be between 0x08 and 0x77.\n");
                    return 1;
                }
                break;
            case 't':
                threshold = atof(optarg);
                if (threshold <= 0) {
                    fprintf(stderr, "Invalid threshold. Must be greater than 0.\n");
                    return 1;
                }
                break;
            default:
                return 1;
        }
    }

    i2cAddress = (i2cAddress == 0) ? DEFAULT_I2C_ADDR : i2cAddress;
    threshold = (threshold == 0) ? DEFAULT_THRESHOLD : threshold;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2cHandle = i2cOpen(1, i2cAddress, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X\n", i2cAddress);
        gpioTerminate();
        return 1;
    }

    if (configureSensor() < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    openlog("high_accel_monitor", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, cleanup);

    while (1) {
        int16_t x, y, z;
        if (readAccelData(&x, &y, &z) == 0) {
            float x_g = x * ACCEL_SCALE;
            float y_g = y * ACCEL_SCALE;
            float z_g = z * ACCEL_SCALE;

            if (fabs(x_g) > threshold || fabs(y_g) > threshold || fabs(z_g) > threshold) {
                logHighAccel(x_g, y_g, z_g);
            }
        }
        time_sleep(SAMPLE_INTERVAL_MS / 1000.0);
    }

    return 0;
}

