#define LEFT_PIN 4
#define CENTER_PIN 17
#define RIGHT_PIN 27
#define ALERT_PIN 22
#define BUFFER_SIZE 5
#define ALERT_DURATION 2
#define POLL_INTERVAL_US 10000

typedef struct {
    int left;
    int center;
    int right;
} SensorReading;

SensorReading buffer[BUFFER_SIZE];
int bufferIndex = 0;
int consecutiveNoLineCount = 0;

struct gpiod_chip *chip;
struct gpiod_line *leftLine, *centerLine, *rightLine, *alertLine;

void cleanup() {
    if (leftLine) gpiod_line_release(leftLine);
    if (centerLine) gpiod_line_release(centerLine);
    if (rightLine) gpiod_line_release(rightLine);
    if (alertLine) gpiod_line_release(alertLine);
    if (chip) gpiod_chip_close(chip);
}

void signalHandler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(0);
}

void logReading(int left, int center, int right) {
    buffer[bufferIndex] = (SensorReading){left, center, right};
    bufferIndex = (bufferIndex + 1) % BUFFER_SIZE;
}

void checkAlert(int center) {
    if (center == 1) {
        consecutiveNoLineCount++;
    } else {
        consecutiveNoLineCount = 0;
    }

    if (consecutiveNoLineCount >= BUFFER_SIZE) {
        gpiod_line_set_value(alertLine, 1);
        usleep(ALERT_DURATION * 1000000);
        gpiod_line_set_value(alertLine, 0);
        consecutiveNoLineCount = 0;
    }
}

void followLine() {
    int left = gpiod_line_get_value(leftLine);
    int center = gpiod_line_get_value(centerLine);
    int right = gpiod_line_get_value(rightLine);

    logReading(left, center, right);
    checkAlert(center);

    if (center == 0) {
        // Move forward
        printf("Moving forward\n");
    } else if (left == 0) {
        // Turn left
        printf("Turning left\n");
    } else if (right == 0) {
        // Turn right
        printf("Turning right\n");
    } else {
        // Stop
        printf("Stopping\n");
    }
}

int main() {
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    leftLine = gpiod_chip_get_line(chip, LEFT_PIN);
    centerLine = gpiod_chip_get_line(chip, CENTER_PIN);
    rightLine = gpiod_chip_get_line(chip, RIGHT_PIN);
    alertLine = gpiod_chip_get_line(chip, ALERT_PIN);

    if (!leftLine || !centerLine || !rightLine || !alertLine) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(leftLine, "left-sensor") < 0 ||
        gpiod_line_request_input(centerLine, "center-sensor") < 0 ||
        gpiod_line_request_input(rightLine, "right-sensor") < 0 ||
        gpiod_line_request_output(alertLine, "alert", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        cleanup();
        return 1;
    }

    printf("Starting line following robot\n");

    while (1) {
        followLine();
        usleep(POLL_INTERVAL_US);
    }

    return 0;
}

