#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x30
#define REGISTER_COMMAND 0xC1
#define REGISTER_DATA 0xC0
#define RELAY_PIN 17
#define THRESHOLD_MT 5.0
#define SAMPLE_INTERVAL_MS 100
#define MAX_POLL_ATTEMPTS 50

static int i2cHandle;
static FILE *logFile;

void logMessage(const char *message) {
    time_t now;
    time(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    fprintf(logFile, "[%s] %s\n", timestamp, message);
    fflush(logFile);
}

void cleanup(int sig) {
    logMessage("Shutting down...");
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    i2cClose(i2cHandle);
    fclose(logFile);
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    logFile = fopen("magnetic_events.txt", "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2cHandle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2cHandle < 0) {
        logMessage("Failed to open I2C device");
        gpioTerminate();
        fclose(logFile);
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    signal(SIGINT, cleanup);

    while (1) {
        int pollAttempts = 0;
        int field_raw;

        // Start conversion
        if (i2cWriteByteData(i2cHandle, REGISTER_COMMAND, 0x01) < 0) {
            logMessage("Failed to start conversion");
            gpioWrite(RELAY_PIN, 0);
            sleep_ms(SAMPLE_INTERVAL_MS);
            continue;
        }

        // Poll for conversion completion
        while (pollAttempts < MAX_POLL_ATTEMPTS) {
            if (i2cReadByteData(i2cHandle, REGISTER_COMMAND, &field_raw) < 0) {
                logMessage("Failed to read command register");
                gpioWrite(RELAY_PIN, 0);
                break;
            }
            if (field_raw == 0x00) break;
            pollAttempts++;
            sleep_ms(10); // 10 ms delay between polls
        }

        if (pollAttempts >= MAX_POLL_ATTEMPTS) {
            logMessage("Conversion timeout");
            gpioWrite(RELAY_PIN, 0);
            sleep_ms(SAMPLE_INTERVAL_MS);
            continue;
        }

        // Read field data
        uint8_t lsb, msb;
