#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <time.h>
#include <ctype.h>

#define PORT 5000
#define RELAY_PIN 18
#define LOG_FILE "relay_log.txt"

int server_fd, client_fd;
FILE *log_file;

void log_event(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] %s\n", time_str, message);
    fflush(log_file);
}

void cleanup() {
    if (client_fd != -1) {
        close(client_fd);
    }
    if (server_fd != -1) {
        close(server_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_PIN, 0); // Turn off relay
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void signal_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    cleanup();
}

int main() {
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);
    char buffer[1024] = {0};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off initially

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        cleanup();
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        cleanup();
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        cleanup();
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        cleanup();
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Server listening on port %d\n", PORT);

    while (1) {
        if ((client_fd = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue;
        }

        ssize_t valread = read(client_fd, buffer, 1024);
        if (valread > 0) {
            buffer[valread] = '\0'; // Null-terminate the string

            // Trim trailing whitespace
            char *end = buffer + strlen(buffer) - 1;
            while (end > buffer && isspace((unsigned char)*end)) {
                end--;
            }
            *(end + 1) = '\0';

            // Convert to uppercase for case-insensitive comparison
            for (char *p = buffer; *p; p++) {
                *p = toupper((unsigned char)*p);
            }

            if (strcmp(buffer, "ON") == 0) {
                gpioWrite(RELAY_PIN, 1);
                log_event("Relay turned ON");
            } else if (strcmp(buffer, "OFF") == 0) {
                gpioWrite(RELAY_PIN, 0);
                log_event("Relay turned OFF");
            } else {
                log_event("Invalid command received");
            }
        }

        close(client_fd);
        client_fd = -1;
    }

    return EXIT_SUCCESS;
}

