#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>

#define SENSOR_1_ADDR 0x08
#define SENSOR_2_ADDR 0x09
#define I2C_BUS 1
#define GPIO_RELAY 18
#define MEASURE_CMD_SIZE 2
#define MEASURE_CMD_DATA {0x36, 0x08}
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define FLOW_THRESHOLD 5.0
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int signum) {
    terminate = 1;
}

static uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            crc = (crc & 0x80) ? (crc << 1) ^ CRC_POLYNOMIAL : (crc << 1);
        }
    }
    return crc;
}

static int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }
    return 0;
}

static void cleanup_pigpio(int i2c_handle_1, int i2c_handle_2) {
    if (i2c_handle_1 >= 0) {
        i2cClose(i2c_handle_1);
    }
    if (i2c_handle_2 >= 0) {
        i2cClose(i2c_handle_2);
    }
    gpioTerminate();
}

int main() {
    int i2c_handle_1 = -1, i2c_handle_2 = -1;
    FILE *log_file = NULL;
    struct timespec start_time, current_time;

    if (initialize_pigpio() < 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_handle_1 = i2cOpen(I2C_BUS, SENSOR_1_ADDR, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Failed to open I2C handle for sensor 1\n");
        cleanup_pigpio(i2c_handle_1, i2c_handle_2);
        return EXIT_FAILURE;
    }

    i2c_handle_2 = i2cOpen(I2C_BUS, SENSOR_2_ADDR, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Failed to open I2C handle for sensor 2\n");
        cleanup_pigpio(i2c_handle_1, i2c_handle_2);
        return EXIT_FAILURE;
    }

    uint8_t measure_cmd[MEASURE_CMD_SIZE] = MEASURE_CMD_DATA;
    if (i2cWriteDevice(i2c_handle_1, measure_cmd, MEASURE_CMD_SIZE) != MEASURE_CMD_SIZE ||
        i2cWriteDevice(i2c_handle_2, measure_cmd, MEASURE_CMD_SIZE) != MEASURE_CMD_SIZE) {
        fprintf(stderr, "Failed to send measurement command to sensors\n");
        cleanup_pigpio(i2c_handle_1, i2c_handle_2);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0 || gpioWrite(GPIO_RELAY, 0) < 0) {
        fprintf(stderr, "Failed to set up GPIO for relay\n");
        cleanup_pigpio(i2c_handle_1, i2c_handle_2);
        return EXIT_FAILURE;
    }

    log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_pigpio(i2c_handle_1, i2c_handle_2);
        return EXIT_FAILURE;
    }

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (!terminate) {
        uint8_t buffer[3];
        int16_t flow_rate_1 = 0, flow_rate_2 = 0;

        if (i2cReadDevice(i2c_handle_1, buffer, sizeof(buffer)) == sizeof(buffer) &&
            calculate_crc8(buffer, 2) == buffer[2]) {
            flow_rate_1 = (buffer[0] << 8) | buffer[1];
        } else {
            fprintf(stderr, "Warning: Read error or CRC mismatch for sensor 1\n");
        }

        if (i2cReadDevice(i2c_handle_2, buffer, sizeof(buffer)) == sizeof(buffer) &&
            calculate_crc8(buffer, 2) == buffer[2]) {
            flow_rate_2 = (buffer[0] << 8) | buffer[1];
        } else {
            fprintf(stderr, "Warning: Read error or CRC mismatch for sensor 2\n");
        }

        if (flow_rate_1 != 0 && flow_rate_2 != 0) {
            float flow_1 = (float)flow_rate_1 / 1500.0;
            float flow_2 = (float)flow_rate_2 / 1500.0;

            clock_gettime(CLOCK_MONOTONIC, &current_time);
            long long elapsed_ms = (current_time.tv_sec - start_time.tv_sec) * 1000LL +
                                   (current_time.tv_nsec - start_time.tv_nsec) / 1000000LL;

            fprintf(log_file, "%lld,%.3f,%.3f\n", elapsed_ms, flow_1, flow_2);
            fflush(log_file);

            if (flow_1 < FLOW_THRESHOLD || flow_2 < FLOW_THRESHOLD) {
                gpioWrite(GPIO_RELAY, 1);
            } else {
                gpioWrite(GPIO_RELAY, 0);
            }
        }

        gpioSleep(PI_TIME_RELATIVE, 0, POLL_INTERVAL_MS * 1000);
    }

    gpioWrite(GPIO_RELAY, 0);
    fclose(log_file);
    cleanup_pigpio(i2c_handle_1, i2c_handle_2);
    printf("Shutting down...\n");

    return EXIT_SUCCESS;
}

