#define PIR_PIN 4
#define FLOODLIGHT_PIN 17
#define LOG_FILE "security_log.txt"
#define ACTIVATION_DURATION 60000 // 60 seconds in milliseconds

volatile sig_atomic_t terminate = 0;

void log_event(const char *event, int duration) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s %s", timestamp, event);
    if (duration >= 0) {
        fprintf(log_file, " Duration: %d seconds", duration);
    }
    fprintf(log_file, "\n");

    if (fclose(log_file) != 0) {
        fprintf(stderr, "Error closing log file\n");
    }
}

void signal_handler(int signum) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0 || gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t activation_start = 0;
    int last_pir_state = 0;

    while (!terminate) {
        int pir_state = gpioRead(PIR_PIN);
        if (pir_state != last_pir_state) {
            if (pir_state == PI_HIGH) {
                gpioWrite(FLOODLIGHT_PIN, PI_HIGH);
                activation_start = time(NULL);
                log_event("Motion detected. Floodlight activated.", -1);
            } else {
                gpioWrite(FLOODLIGHT_PIN, PI_LOW);
                time_t activation_end = time(NULL);
                int duration = (int)difftime(activation_end, activation_start);
                log_event("Motion ended. Floodlight deactivated.", duration);
            }
            last_pir_state = pir_state;
        }

        gpioDelay(100000); // 100ms delay
    }

    gpioWrite(FLOODLIGHT_PIN, PI_LOW);
    gpioTerminate();
    return 0;
}

