#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define TOUCH_PIN 0
#define DEBOUNCE_TIME_MS 200

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int mpr121_init(int i2c_bus, int addr) {
    unsigned char data;

    // Soft reset
    if (i2c_write_byte_data(i2c_bus, addr, 0x63) < 0) return -1;
    gpioDelay(10000); // 10ms delay

    // Configure baseline filtering
    if (i2c_write_byte_data(i2c_bus, addr, 0x24) < 0) return -1;
    if (i2c_write_byte_data(i2c_bus, addr, 0x14) < 0) return -1;

    // Set debounce
    if (i2c_write_byte_data(i2c_bus, addr, 0x5B) < 0) return -1;
    if (i2c_write_byte_data(i2c_bus, addr, 0x01) < 0) return -1;

    // Set FFI/SFI/CDT
    if (i2c_write_byte_data(i2c_bus, addr, 0x2C) < 0) return -1;
    if (i2c_write_byte_data(i2c_bus, addr, 0x10) < 0) return -1;

    // Set auto-config
    if (i2c_write_byte_data(i2c_bus, addr, 0x7B) < 0) return -1;
    if (i2c_write_byte_data(i2c_bus, addr, 0x1E) < 0) return -1;
    if (i2c_write_byte_data(i2c_bus, addr, 0x01) < 0) return -1;

    // Enable 12 electrodes
    if (i2c_write_byte_data(i2c_bus, addr, 0x5E) < 0) return -1;
    if (i2c_write_byte_data(i2c_bus, addr, 0x0C) < 0) return -1;

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (mpr121_init(I2C_BUS, MPR121_ADDR) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, PI_LOW); // Ensure relay is OFF on startup

    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN);

    struct timespec last_touch_time = {0, 0};

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        unsigned char touch_data[2];
        if (i2c_read_i2c_block_data(I2C_BUS, MPR121_ADDR, 0x00, 2, touch_data) < 0) {
            fprintf(stderr, "Failed to read touch data\n");
            continue;
        }

        unsigned short touch_status = (touch_data[0] << 8) | touch_data[1];
        if (touch_status & (1 << TOUCH_PIN)) {
            struct timespec current_time;
            clock_gettime(CLOCK_MONOTONIC, &current_time);

            long elapsed_ms = (current_time.tv_sec - last_touch_time.tv_sec) * 1000 +
                              (current_time.tv_nsec - last_touch_time.tv_nsec) / 1000000;

            if (elapsed_ms >= DEBOUNCE_TIME_MS) {
                gpioWrite(RELAY_PIN, !gpioRead(RELAY_PIN));
                last_touch_time = current_time;
            }
        }

        gpioDelay(10000); // 10ms delay to prevent excessive CPU usage
    }

    gpioWrite(RELAY_PIN, PI_LOW); // Ensure relay is OFF on shutdown
    gpioTerminate();
    return 0;
}

