#define SERVO_PIN 17
#define PIR_PIN 4
#define TCP_PORT 5000
#define PWM_FREQUENCY 50
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)
#define PWM_PULSE_WIDTH_MIN_US 1000
#define PWM_PULSE_WIDTH_MAX_US 2000

static struct gpiod_chip *chip;
static struct gpiod_line *servo_line;
static struct gpiod_line *pir_line;
static int server_fd;
static FILE *log_file;
static pthread_t pwm_thread;
static volatile int running = 1;

void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);

    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "[%s] ", timestamp);
    vfprintf(log_file, format, args);
    fprintf(log_file, "\n");
    fflush(log_file);

    va_end(args);

    va_start(args, format);
    syslog(LOG_USER | LOG_INFO, format, args);
    va_end(args);
}

void *pwm_thread_func(void *arg) {
    struct timespec sleep_time = {0, PWM_PERIOD_US * 1000};
    int pulse_width_us = PWM_PULSE_WIDTH_MIN_US;
    int direction = 1;

    while (running) {
        gpiod_line_set_value(servo_line, 1);
        nanosleep(&sleep_time, NULL);

        gpiod_line_set_value(servo_line, 0);
        nanosleep(&sleep_time, NULL);

        if (direction) {
            pulse_width_us += 10;
            if (pulse_width_us >= PWM_PULSE_WIDTH_MAX_US) {
                direction = 0;
            }
        } else {
            pulse_width_us -= 10;
            if (pulse_width_us <= PWM_PULSE_WIDTH_MIN_US) {
                direction = 1;
            }
        }
    }

    return NULL;
}

void signal_handler(int signum) {
    running = 0;
}

