#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define SENSOR_ADDR 0x23
#define RELAY_PIN 23
#define I2C_BUS 1
#define SAMPLE_INTERVAL 2
#define LUX_THRESHOLD 150.0
#define CONVERSION_FACTOR 1.2
#define LOG_FILE "grow_log.txt"

static volatile int keep_running = 1;

void signal_handler(int signo) {
    keep_running = 0;
}

int main() {
    int i2c_handle, relay_state = 0;
    FILE *log_file;
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];
    unsigned char raw_data[2];
    float lux;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, relay_state);

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        if (i2cWriteByte(i2c_handle, 0x20) < 0) {
            fprintf(stderr, "Failed to send command to sensor\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        usleep(120000);  // Wait for conversion (120 ms)

        if (i2cReadDevice(i2c_handle, raw_data, 2) < 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        lux = (raw_data[0] << 8 | raw_data[1]) / CONVERSION_FACTOR;

        time(&now);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s, %.2f\n", timestamp, lux);
        fflush(log_file);

        if (lux < LUX_THRESHOLD && !relay_state) {
            gpioWrite(RELAY_PIN, 1);
            relay_state = 1;
        } else if (lux >= LUX_THRESHOLD && relay_state) {
            gpioWrite(RELAY_PIN, 0);
            relay_state = 0;
        }

        sleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();

    return 0;
}

