    if (!dout_line || !sck_line || !solenoid_line) {
        syslog(LOG_ERR, "Failed to get GPIO lines: %s", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(dout_line, "hx711_dout") < 0 ||
        gpiod_line_request_output(sck_line, "hx711_sck", 0) < 0 ||
        gpiod_line_request_output(solenoid_line, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO lines: %s", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void release_gpio() {
    if (solenoid_line) gpiod_line_release(solenoid_line);
    if (sck_line) gpiod_line_release(sck_line);
    if (dout_line) gpiod_line_release(dout_line);
    if (chip) gpiod_chip_close(chip);
}

int read_hx711() {
    unsigned long long value = 0;
    int retry_count = 0;

    while (retry_count < MAX_RETRIES) {
        struct timespec start, current;
        clock_gettime(CLOCK_MONOTONIC, &start);

        while (gpiod_line_get_value(dout_line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &current);
            if ((current.tv_sec - start.tv_sec) * 1000000 + (current.tv_nsec - start.tv_nsec) / 1000 >= TIMEOUT_US) {
                syslog(LOG_ERR, "Timeout waiting for DOUT to go LOW");
                retry_count++;
                break;
            }
            usleep(100);
        }

        if (retry_count >= MAX_RETRIES) break;

        for (int i = 0; i < 24; i++) {
            gpiod_line_set_value(sck_line, 1);
            usleep(1);
            value = (value << 1) | gpiod_line_get_value(dout_line);
            gpiod_line_set_value(sck_line, 0);
            usleep(1);
        }

        gpiod_line_set_value(sck_line, 1);
        usleep(1);
        gpiod_line_set_value(sck_line, 0);
        usleep(1);

        if (gpiod_line_get_value(dout_line) == 0) break;
    }

    if (retry_count >= MAX_RETRIES) {
        syslog(LOG_ERR, "Max retries reached, exiting");
        exit(1);
    }

    return (int)((value ^ 0x800000) - 0x800000);
}

double average_readings(int num_readings) {
    long long sum = 0;
    for (int i = 0; i < num_readings; i++) {
        sum += read_hx711();
    }
    return (double)sum / num_readings;
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    double scale = DEFAULT_SCALE;
    int duration = DEFAULT_DURATION;
    double tare_offset;

    openlog("hx711_loadcell", LOG_PID | LOG_CONS, LOG_USER);

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--threshold") == 0 && i + 1 < argc) {
            threshold = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--scale") == 0 && i + 1 < argc) {
            scale = atof(argv[++i]);
        } else if (strcmp(argv[i], "--duration") == 0 && i + 1 < argc) {
            duration = atoi(argv[++i]);
        }
    }

    if (setup_gpio() < 0) {
        closelog();
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    tare_offset = average_readings(STARTUP_READINGS);
    syslog(LOG_INFO, "Tare offset: %.2f", tare_offset);

    while (keep_running) {
        double avg_raw = average_readings(NUM_READINGS);
        double weight = (avg_raw - tare_offset) / scale;
        syslog(LOG_INFO, "Weight: %.2f g", weight);

        if (weight > threshold) {
            gpiod_line_set_value(solenoid_line, 1);
            usleep(duration * 1000);
            gpiod_line_set_value(solenoid_line, 0);
        }

        usleep(500000);
    }

    gpiod_line_set_value(solenoid_line, 0);
    release_gpio();
    closelog();
    return 0;
}
