#define MQTT_TOPIC "home/lights/control"

static volatile sig_atomic_t keep_running = 1;
mosquitto *mosq = NULL;

void log_mosquitto_event(int event, void *userdata, void *message) {
    const char *event_str;
    switch (event) {
        case MOSQ_EVENT_CONNECT:
            event_str = "CONNECT";
            break;
        case MOSQ_EVENT_DISCONNECT:
            event_str = "DISCONNECT";
            break;
        case MOSQ_EVENT_SUBSCRIBE:
            event_str = "SUBSCRIBE";
            break;
        case MOSQ_EVENT_LOG:
            event_str = "LOG";
            break;
        case MOSQ_EVENT_ERROR:
            event_str = "ERROR";
            break;
        default:
            event_str = "UNKNOWN";
    }
    syslog(LOG_INFO, "Mosquitto event: %s", event_str);
}

void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == 0) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to topic: %s", MQTT_TOPIC);
        }
    } else {
        syslog(LOG_ERR, "Connection failed with code %d: %s", result, mosquitto_connack_string(result));
    }
}

void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *msg) {
    syslog(LOG_INFO, "Received message on topic %s: %s", msg->topic, (char *)msg->payload);
    if (strcmp((char *)msg->payload, "ON") == 0) {
        if (gpioWrite(RELAY_PIN, 1) != 0) {
            syslog(LOG_ERR, "Failed to set GPIO %d HIGH", RELAY_PIN);
        }
    } else if (strcmp((char *)msg->payload, "OFF") == 0) {
        if (gpioWrite(RELAY_PIN, 0) != 0) {
            syslog(LOG_ERR, "Failed to set GPIO %d LOW", RELAY_PIN);
        }
    } else {
        syslog(LOG_ERR, "Invalid message payload: %s", (char *)msg->payload);
    }
}

void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "Disconnected from MQTT broker with code %d", rc);
    while (keep_running) {
        syslog(LOG_INFO, "Attempting to reconnect...");
        mosquitto_reconnect(mosq);
        sleep(5);
    }
}

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d mode", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d LOW at startup", RELAY_PIN);
    }

    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create Mosquitto client");
        closelog();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    mosquitto_log_callback_set(mosq, log_mosquitto_event);
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        closelog();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running && mosquitto_loop(mosq, -1, 1) == MOSQ_ERR_SUCCESS) {
        // Main loop
    }

    syslog(LOG_INFO, "Shutting down...");
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    closelog();
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

