#include <stdio.h>
#include <pigpio.h>
#include <time.h>

#define NUM_SERVOS 5
#define SERVO_PINS[NUM_SERVOS] = {7, 8, 9, 10, 11}
#define SERVO_POSITIONS[NUM_SERVOS] = {1000, 1500, 2000, 500, 2500}
#define PWM_FREQUENCY 50
#define PWM_RANGE 10000 // 20 ms period at 50 Hz
#define HOLD_TIME 3 // seconds

int main() {
    int i, ret;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    // Set PWM frequency and range for each pin
    for (i = 0; i < NUM_SERVOS; i++) {
        gpioSetMode(SERVO_PINS[i], PI_OUTPUT);
        gpioSetPWMfrequency(SERVO_PINS[i], PWM_FREQUENCY);
        gpioSetPWMrange(SERVO_PINS[i], PWM_RANGE);
    }

    // Apply pulse widths
    for (i = 0; i < NUM_SERVOS; i++) {
        gpioPWM(SERVO_PINS[i], SERVO_POSITIONS[i] * PWM_RANGE / 20000);
    }

    // Hold the signals for 3 seconds
    time_t start_time = time(NULL);
    while (time(NULL) - start_time < HOLD_TIME) {
        gpioSleep(1); // Sleep for 1 second
    }

    // Clean up
    for (i = 0; i < NUM_SERVOS; i++) {
        gpioPWM(SERVO_PINS[i], 0); // Stop PWM
    }

    gpioTerminate();

    return 0;
}

