double calculate_rpm(int encoder_count, long last_tick_time) {
    long current_time = time(NULL) * 1000;
    long delta_time_ms = current_time - last_tick_time;
    if (delta_time_ms == 0) return 0;
    double rev_per_sec = (double)encoder_count / (delta_time_ms / 1000.0);
    return rev_per_sec * 60;
}

void set_motor_pwm(int gpio_pwm, int gpio_dir, int pwm_duty_cycle, int direction) {
    gpioSetPWMfrequency(gpio_pwm, PWM_FREQUENCY);
    gpioSetPWMrange(gpio_pwm, PWM_RANGE);
    gpioPWM(gpio_pwm, pwm_duty_cycle);
    gpioWrite(gpio_dir, direction);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    if (gpioSetMode(MOTOR_A_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_DIR, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_DIR, PI_OUTPUT) < 0 ||
        gpioSetMode(ENCODER_A_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_A_B, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_B, PI_INPUT) < 0) {
        fprintf(stderr, "GPIO mode setting failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFunc(ENCODER_A_A, EITHER_EDGE, 0, encoder_isr) < 0 ||
        gpioSetISRFunc(ENCODER_A_B, EITHER_EDGE, 0, encoder_isr) < 0 ||
        gpioSetISRFunc(ENCODER_B_A, EITHER_EDGE, 0, encoder_isr) < 0 ||
        gpioSetISRFunc(ENCODER_B_B, EITHER_EDGE, 0, encoder_isr) < 0) {
        fprintf(stderr, "ISR registration failed\n");
        gpioTerminate();
        return 1;
    }

    double target_speed_rad_per_sec = TARGET_RPM * RPM_TO_RAD_PER_SEC;
    double integral = 0;
    long last_control_time = gpioTick();

    while (running) {
        long current_time = gpioTick();
        if (current_time - last_control_time < CONTROL_PERIOD_MS * 1000) {
            continue;
        }
        last_control_time = current_time;

        int current_a_count = atomic_load(&encoder_a_count);
        int current_b_count = atomic_load(&encoder_b_count);
        long last_tick = atomic_load(&last_tick_time);

        double current_speed_a = calculate_rpm(current_a_count, last_tick) * RPM_TO_RAD_PER_SEC;
        double current_speed_b = calculate_rpm(current_b_count, last_tick) * RPM_TO_RAD_PER_SEC;

        double error_a = target_speed_rad_per_sec - current_speed_a;
        double error_b = target_speed_rad_per_sec - current_speed_b;

        integral += (error_a + error_b) * (CONTROL_PERIOD_MS / 1000.0);
        integral = fmin(fmax(integral, -1000), 1000);  // Anti-windup

        double output_a = Kp * error_a + Ki * integral;
        double output_b = Kp * error_b + Ki * integral;

        int pwm_a = fmin(fmax((int)output_a, 0), PWM_RANGE);
        int pwm_b = fmin(fmax((int)output_b, 0), PWM_RANGE);

        set_motor_pwm(MOTOR_A_PWM, MOTOR_A_DIR, pwm_a, pwm_a >= 0 ? 1 : 0);
        set_motor_pwm(MOTOR_B_PWM, MOTOR_B_DIR, pwm_b, pwm_b >= 0 ? 1 : 0);

        printf("Motor A RPM: %.2f, PWM: %d\n", current_speed_a * 60 / (2 * M_PI), pwm_a);
        printf("Motor B RPM: %.2f, PWM: %d\n", current_speed_b * 60 / (2 * M_PI), pwm_b);

        if (current_time - last_tick > STALL_THRESHOLD_MS * 1000) {
            printf("Warning: Encoder stall detected!\n");
        }

        atomic_store(&last_encoder_a_count, current_a_count);
        atomic_store(&last_encoder_b_count, current_b_count);
    }

    gpioSetPWMdutycycle(MOTOR_A_PWM, 0);
    gpioSetPWMdutycycle(MOTOR_B_PWM, 0);
    gpioTerminate();
    return 0;
}
