#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define SENSOR_POLL_INTERVAL 5
#define LUX_THRESHOLD_LOW 50.0
#define LUX_THRESHOLD_HIGH 200.0
#define LOG_FILE "chicken_coop_log.txt"
#define RELAY_GPIO 17

static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t keep_running = 1;

void log_message(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_file, "%s: %s\n", time_str, message);
    fflush(log_file);
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
}

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, PI_LOW);

    float current_lux = 0.0;
    int relay_state = PI_LOW;

    while (keep_running) {
        // Send command for One-Time High-Resolution Mode 2
        char cmd = 0x21;
        if (i2cWriteDevice(i2c_handle, &cmd, 1) < 0) {
            log_message("Failed to send command to BH1750");
            gpioWrite(RELAY_GPIO, PI_LOW);
            relay_state = PI_LOW;
        } else {
            usleep(180000); // Wait 180 ms

            char data[2];
            if (i2cReadDevice(i2c_handle, data, 2) == 2) {
                unsigned int raw_lux = (data[0] << 8) | data[1];
                current_lux = raw_lux / 1.2;
                char log_buffer[100];
                snprintf(log_buffer, sizeof(log_buffer), "Lux = %.2f, Relay = %s", current_lux, relay_state ? "ON" : "OFF");
                log_message(log_buffer);

                if (current_lux < LUX_THRESHOLD_LOW && relay_state == PI_LOW) {
                    gpioWrite(RELAY_GPIO, PI_HIGH);
                    relay_state = PI_HIGH;
                } else if (current_lux > LUX_THRESHOLD_HIGH && relay_state == PI_HIGH) {
                    gpioWrite(RELAY_GPIO, PI_LOW);
                    relay_state = PI_LOW;
                }
            } else {
                log_message("Failed to read lux data from BH1750");
                gpioWrite(RELAY_GPIO, PI_LOW);
                relay_state = PI_LOW;
            }
        }

        sleep(SENSOR_POLL_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

