#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define RELAY_PIN 17
#define TOUCH_SENSOR_PIN 4
#define DEBOUNCE_DELAY 50
#define MAIN_LOOP_DELAY 10

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        keep_running = 0;
    }
}

void log_relay_state(int state) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    printf("%s Relay is %s\n", timestamp, state ? "ON" : "OFF");
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for touch sensor pin\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for relay pin\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up/down for touch sensor pin\n");
        gpioTerminate();
        return 1;
    }

    int relay_state = 0;
    int last_touch_state = 1;
    int touch_stable = 1;

    signal(SIGINT, signal_handler);

    while (keep_running) {
        int current_touch_state = gpioRead(TOUCH_SENSOR_PIN);

        if (current_touch_state == 0 && last_touch_state == 1 && touch_stable) {
            touch_stable = 0;
            gpioSleep(PI_TIME_MILLISECONDS, DEBOUNCE_DELAY, 0);

            if (gpioRead(TOUCH_SENSOR_PIN) == 0) {
                relay_state = !relay_state;
                gpioWrite(RELAY_PIN, relay_state);
                log_relay_state(relay_state);
            }
        }

        if (current_touch_state == 1) {
            touch_stable = 1;
        }

        last_touch_state = current_touch_state;
        gpioSleep(PI_TIME_MILLISECONDS, MAIN_LOOP_DELAY, 0);
    }

    gpioWrite(RELAY_PIN, 0);
    log_relay_state(0);
    gpioTerminate();
    printf("Program exited gracefully\n");

    return 0;
}

