#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define PULSE_THRESHOLD 450
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define DEBOUNCE_TIME_MS 1000

static volatile unsigned int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

void log_message(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] %s\n", time_str, message);
    fflush(log_file);
}

void pulse_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)level;
    (void)tick;

    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

void *sample_pulses(void *arg) {
    (void)arg;
    while (1) {
        sleep(1);
        pthread_mutex_lock(&pulse_mutex);
        double lpm = (pulse_count / (double)PULSE_THRESHOLD) * 60.0;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        char buffer[100];
        snprintf(buffer, sizeof(buffer), "LPM: %.2f", lpm);
        log_message(buffer);

        if (lpm > LPM_THRESHOLD_HIGH) {
            gpioWrite(SOLENOID_PIN, LOW);
            log_message("Solenoid: CLOSED");
        } else if (lpm < LPM_THRESHOLD_LOW) {
            gpioWrite(SOLENOID_PIN, HIGH);
            log_message("Solenoid: OPEN");
        }
    }
    return NULL;
}

void signal_handler(int signum) {
    const char *signal_name;
    switch (signum) {
        case SIGINT:
            signal_name = "SIGINT";
            break;
        case SIGTERM:
            signal_name = "SIGTERM";
            break;
        default:
            return;
    }

    char buffer[100];
    snprintf(buffer, sizeof(buffer), "Received %s", signal_name);
    log_message(buffer);

    gpioWrite(SOLENOID_PIN, HIGH);
    log_message("Solenoid: OPEN (reopened safely)");

    if (log_file) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_DOWN);
    gpioWrite(SOLENOID_PIN, HIGH); // Solenoid open by default

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, DEBOUNCE_TIME_MS, pulse_callback) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("water_flow.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    pthread_t sampling_thread;
    if (pthread_create(&sampling_thread, NULL, sample_pulses, NULL) != 0) {
        fprintf(stderr, "Failed to create sampling thread\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    pthread_join(sampling_thread, NULL);

    return EXIT_SUCCESS;
}

