    while (!data_ready && attempts < MAX_READING_ATTEMPTS) {
        gpioWrite(HX711_SCK_PIN, 1);
        usleep(1);
        gpioWrite(HX711_SCK_PIN, 0);
        usleep(1);

        if (gpioRead(HX711_DATA_PIN) == 0) {
