        gpioWrite(HX711_SCK_PIN, 1);
        usleep(1);
        gpioWrite(HX711_SCK_PIN, 0);
        usleep(1);

        value = (value << 1) | gpioRead(HX711_DATA_PIN);
    }

    gpioWrite(HX711_SCK_PIN, 1);
    usleep(1);
    gpioWrite(HX711_SCK_PIN, 0);
    usleep(1);

    value ^= 0x800000;

    return (double)value;
}

