    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        fprintf(stderr, "Error: Unable to create socket\n");
        gpioTerminate();
        return 1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(server_ip);
    server_addr.sin_port = htons(server_port);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error: Unable to bind socket\n");
        close(server_fd);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 1) < 0) {
        fprintf(stderr, "Error: Unable to listen on socket\n");
        close(server_fd);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on %s:%d\n", server_ip, server_port);

    while (keep_running) {
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            fprintf(stderr, "Error: Unable to accept client connection\n");
            continue;
        }

        double target_weight;
        if (recv(client_fd, &target_weight, sizeof(target_weight), 0) != sizeof(target_weight)) {
            fprintf(stderr, "Error: Unable to receive target weight from client\n");
            close(client_fd);
            continue;
        }

        set_servo_pulse(SERVO_PIN, SERVO_MIN_PULSE);
        usleep(1000000);

        double actual_weight = read_hx711() * calibration_factor;

        if (actual_weight < 0) {
            log_dispensing_event(target_weight, actual_weight, "HX711 read error");
        } else {
            log_dispensing_event(target_weight, actual_weight, NULL);
        }

        if (send(client_fd, &actual_weight, sizeof(actual_weight), 0) != sizeof(actual_weight)) {
            fprintf(stderr, "Error: Unable to send actual weight to client\n");
        }

        close(client_fd);
    }

    close(server_fd);
    gpioTerminate();
    return 0;
}

