#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define RELAY_PIN 17
#define TOUCH_SENSOR_PIN 4
#define DEFAULT_DEBOUNCE_TIME 50

volatile sig_atomic_t keep_running = 1;

void log_relay_state(int state) {
    time_t now;
    time(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
}

void handle_signal(int signum) {
    keep_running = 0;
}

int main(int argc, char *argv[]) {
    int debounce_time = DEFAULT_DEBOUNCE_TIME;

    if (argc == 3 && strcmp(argv[1], "-d") == 0) {
        debounce_time = atoi(argv[2]);
        if (debounce_time <= 0) {
            fprintf(stderr, "Invalid debounce time\n");
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_state = LOW;
    int stable_state = LOW;
    unsigned long last_change_time = 0;

    while (keep_running) {
        int current_state = gpioRead(TOUCH_SENSOR_PIN);

        if (current_state != last_state) {
            last_change_time = time(NULL) * 1000;
        }

        if ((time(NULL) * 1000 - last_change_time) > debounce_time) {
            if (current_state == HIGH && last_state == LOW) {
                stable_state = HIGH;
            } else if (current_state == LOW && last_state == HIGH) {
                stable_state = LOW;
                if (gpioWrite(RELAY_PIN, stable_state) < 0) {
                    fprintf(stderr, "Failed to write to relay pin\n");
                } else {
                    log_relay_state(stable_state);
                }
            }
            last_state = current_state;
        }

        gpioDelay(10000); // 10ms delay to reduce CPU usage
    }

    gpioWrite(RELAY_PIN, LOW);
    gpioTerminate();
    return 0;
}

