#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <termios.h>
#include <unistd.h>

#define SERVO_PIN 18
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define PWM_FREQUENCY 50
#define DEFAULT_ANGLE 90

static struct termios old_term, new_term;
static volatile sig_atomic_t running = 1;

void restore_terminal(void) {
    tcsetattr(STDIN_FILENO, TCSANOW, &old_term);
}

void signal_handler(int signum) {
    running = 0;
}

int main(void) {
    int angle = DEFAULT_ANGLE;
    int gpio_initialized = gpioInitialise();

    if (gpio_initialized < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    if (tcgetattr(STDIN_FILENO, &old_term) != 0) {
        perror("Failed to get terminal attributes");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    new_term = old_term;
    new_term.c_lflag &= ~(ICANON | ECHO);
    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_term) != 0) {
        perror("Failed to set terminal attributes");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        int key = getchar();
        switch (key) {
            case '+':
                angle = (angle + 10 <= MAX_ANGLE) ? angle + 10 : MAX_ANGLE;
                break;
            case '-':
                angle = (angle - 10 >= MIN_ANGLE) ? angle - 10 : MIN_ANGLE;
                break;
            case 'q':
                running = 0;
                break;
            default:
                continue;
        }

        int pulse_width = MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / MAX_ANGLE);
        if (gpioServo(SERVO_PIN, pulse_width) < 0) {
            fprintf(stderr, "Failed to set servo position\n");
        } else {
            printf("Current angle: %d\n", angle);
        }
    }

    gpioSetServoPulsewidth(SERVO_PIN, 0);
    gpioTerminate();
    restore_terminal();

    return EXIT_SUCCESS;
}

