void log_rpm(double rpm) {
    struct timespec ts;
    char timestamp[64];
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    if (gmtime_r(&ts.tv_sec, &tm_info) == NULL) {
        perror("gmtime_r");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(log_file, "%s,%0.2f\n", timestamp, rpm);
    fflush(log_file);
}

int main() {
    struct gpiod_line_event event;
    struct timespec last_pulse_time, current_time;
    struct itimerspec debounce_timer;
    timer_t debounce_timerid;
    sigset_t sigset;
    struct sigaction sa;

    sa.sa_handler = signal_handler;
