#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define RELAY_PIN 17
#define TOUCH_SENSOR_PIN 4
#define POLL_INTERVAL_MS 50
#define FAILSAFE_TIMEOUT_MS 10000

volatile sig_atomic_t terminate = 0;

void signalHandler(int signum) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signalHandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handlers\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(RELAY_PIN, PI_LOW);  // Ensure relay is initially OFF

    time_t lastTouchTime = time(NULL);
    int relayState = PI_LOW;

    while (!terminate) {
        int sensorState = gpioRead(TOUCH_SENSOR_PIN);

        if (sensorState == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading touch sensor\n");
            break;
        }

        if (sensorState == PI_HIGH) {
            time_t currentTime = time(NULL);
            if (difftime(currentTime, lastTouchTime) * 1000 > FAILSAFE_TIMEOUT_MS) {
                // Failsafe: force relay OFF
                gpioWrite(RELAY_PIN, PI_LOW);
                relayState = PI_LOW;
                printf("Failsafe activated: Relay OFF\n");
            } else if (relayState == PI_LOW) {
                // Toggle relay state
                relayState = PI_HIGH;
                gpioWrite(RELAY_PIN, PI_HIGH);
                printf("Relay ON\n");
            }
            lastTouchTime = currentTime;
        } else {
            // Sensor released, reset failsafe
            relayState = PI_LOW;
        }

        gpioSleep(PI_TIME_RELATIVE, 0, POLL_INTERVAL_MS * 1000);
    }

    // Cleanup
    gpioWrite(RELAY_PIN, PI_LOW);  // Ensure relay is OFF
    gpioTerminate();

    return 0;
}

