#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

#define FLOW_SENSOR_PIN 24
#define VALVE_ENABLE_PIN 23
#define VALVE_PWM_PIN 18
#define PULSES_PER_LITER 450
#define SAMPLE_INTERVAL_MS 100
#define Kp 1.0

static volatile unsigned long pulse_count = 0;
static FILE *log_file = NULL;
static volatile int keep_running = 1;

void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

void signal_handler(int signo) {
    keep_running = 0;
}

int main(int argc, char *argv[]) {
    double target_flow_rate = 0.0;
    char *endptr;

    if (argc != 3 || strcmp(argv[1], "-t") != 0) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
        return EXIT_FAILURE;
    }

    target_flow_rate = strtod(argv[2], &endptr);
    if (*endptr != '\0' || target_flow_rate <= 0) {
        fprintf(stderr, "Error: Invalid target flow rate\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(VALVE_PWM_PIN, PI_ALT0) < 0 ||
        gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_OFF);

    if (gpioSetAlertFunc(FLOW_SENSOR_PIN, pulse_callback) < 0) {
        fprintf(stderr, "Error: Failed to set up interrupt\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(VALVE_ENABLE_PIN, PI_HIGH);
    gpioHardwarePWM(VALVE_PWM_PIN, 1000, 0);  // 1 kHz frequency, 0% duty cycle

    log_file = fopen("flow_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioWrite(VALVE_ENABLE_PIN, PI_LOW);
        gpioHardwarePWM(VALVE_PWM_PIN, 0, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp_ms,flow_rate,valve_position\n");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct timespec start, current;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (keep_running) {
        nanosleep(&(struct timespec){0, SAMPLE_INTERVAL_MS * 1000000}, NULL);

        clock_gettime(CLOCK_MONOTONIC, &current);
        double elapsed_ms = (current.tv_sec - start.tv_sec) * 1000.0 +
                            (current.tv_nsec - start.tv_nsec) / 1000000.0;

        double flow_rate = (pulse_count / PULSES_PER_LITER) / (elapsed_ms / 60000.0);
        pulse_count = 0;

        double error = target_flow_rate - flow_rate;
        int valve_position = (int)(Kp * error);
        valve_position = (valve_position < 0) ? 0 : (valve_position > 255) ? 255 : valve_position;

        gpioHardwarePWM(VALVE_PWM_PIN, 1000, valve_position * 1000 / 255);

        fprintf(log_file, "%.0f,%.2f,%d\n", elapsed_ms, flow_rate, valve_position);
        fflush(log_file);

        start = current;
    }

    fclose(log_file);
    gpioWrite(VALVE_ENABLE_PIN, PI_LOW);
    gpioHardwarePWM(VALVE_PWM_PIN, 0, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

