#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define RFID_TAG_SIZE 10
#define VALID_TAG {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A}
#define LOCK_GPIO_1 17
#define LOCK_GPIO_2 27
#define BUTTON_GPIO 22
#define DEBOUNCE_TIME 50000 // 50 ms
#define SPI_CHANNEL 0
#define SPI_SPEED 100000 // 100 kHz

static const uint8_t valid_tag[RFID_TAG_SIZE] = VALID_TAG;
static FILE *log_file;
static int spi_handle;

void log_message(const char *message) {
    time_t now;
    struct tm *tm_info;
    char timestamp[26];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

void cleanup(int signum) {
    log_message("Shutting down...");
    gpioWrite(LOCK_GPIO_1, 1); // Re-engage lock 1
    gpioWrite(LOCK_GPIO_2, 1); // Re-engage lock 2
    gpioSetMode(LOCK_GPIO_1, PI_INPUT);
    gpioSetMode(LOCK_GPIO_2, PI_INPUT);
    gpioTerminate();
    spiClose(spi_handle);
    fclose(log_file);
    exit(EXIT_SUCCESS);
}

int read_rfid_tag(uint8_t *buffer) {
    int count;
    if ((count = spiXfer(spi_handle, buffer, buffer, RFID_TAG_SIZE)) < 0) {
        log_message("SPI read failure");
        return -1;
    }
    return count;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("/var/log/door_access.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failure\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LOCK_GPIO_1, PI_OUTPUT);
    gpioSetMode(LOCK_GPIO_2, PI_OUTPUT);
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    log_message("System initialized");

    while (1) {
        uint8_t rfid_buffer[RFID_TAG_SIZE] = {0};
        int button_state = gpioRead(BUTTON_GPIO);

        if (button_state == 0) { // Button pressed
            gpioDelay(DEBOUNCE_TIME);
            button_state = gpioRead(BUTTON_GPIO);

            if (button_state == 0) {
                log_message("Button press detected without valid RFID tag");
                continue;
            }
        }

        if (read_rfid_tag(rfid_buffer) != RFID_TAG_SIZE) {
            log_message("RFID read failure");
            continue;
        }

        if (memcmp(rfid_buffer, valid_tag, RFID_TAG_SIZE) == 0) {
            log_message("Valid RFID tag detected");

            gpioDelay(DEBOUNCE_TIME);
            button_state = gpioRead(BUTTON_GPIO);

            if (button_state == 0) { // Button pressed
                gpioDelay(DEBOUNCE_TIME);
                button_state = gpioRead(BUTTON_GPIO);

                if (button_state == 0) {
                    log_message("Successful two-factor authentication");

                    gpioWrite(LOCK_GPIO_1, 0); // Disengage lock 1
                    gpioWrite(LOCK_GPIO_2, 0); // Disengage lock 2
                    gpioDelay(5000000); // 5 seconds
                    gpioWrite(LOCK_GPIO_1, 1); // Re-engage lock 1
                    gpioWrite(LOCK_GPIO_2, 1); // Re-engage lock 2
                } else {
                    log_message("Button press without valid RFID tag");
                }
            }
        } else {
            log_message("Invalid RFID tag");
        }

        gpioDelay(100000); // 100 ms delay to prevent busy-waiting
    }

    return EXIT_SUCCESS;
}
