#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>
#include <math.h>

#define TARGET_RPM 60.0
#define SAMPLE_TIME_MS 100
#define ENCODER_PULSES_PER_REV 600
#define PWM_FREQUENCY 100
#define KP 1.0
#define KI 0.1
#define KD 0.01

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

static volatile int running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *motor1_ena, *motor1_in1, *motor1_in2;
static struct gpiod_line *motor2_enb, *motor2_in3, *motor2_in4;
static struct gpiod_line *encoder1_a, *encoder1_b;
static struct gpiod_line *encoder2_a, *encoder2_b;

static pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;
static int encoder1_count = 0;
static int encoder2_count = 0;

static FILE *log_file;

void signal_handler(int signum) {
    running = 0;
}

void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    motor1_ena = gpiod_chip_get_line(chip, MOTOR1_ENA);
    motor1_in1 = gpiod_chip_get_line(chip, MOTOR1_IN1);
    motor1_in2 = gpiod_chip_get_line(chip, MOTOR1_IN2);
    motor2_enb = gpiod_chip_get_line(chip, MOTOR2_ENB);
    motor2_in3 = gpiod_chip_get_line(chip, MOTOR2_IN3);
    motor2_in4 = gpiod_chip_get_line(chip, MOTOR2_IN4);
    encoder1_a = gpiod_chip_get_line(chip, ENCODER1_A);
    encoder1_b = gpiod_chip_get_line(chip, ENCODER1_B);
    encoder2_a = gpiod_chip_get_line(chip, ENCODER2_A);
    encoder2_b = gpiod_chip_get_line(chip, ENCODER2_B);

    if (!motor1_ena || !motor1_in1 || !motor1_in2 || !motor2_enb || !motor2_in3 || !motor2_in4 ||
        !encoder1_a || !encoder1_b || !encoder2_a || !encoder2_b) {
        perror("Failed to get GPIO lines");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(motor1_ena, "motor1_ena", 0);
    gpiod_line_request_output(motor1_in1, "motor1_in1", 0);
    gpiod_line_request_output(motor1_in2, "motor1_in2", 0);
    gpiod_line_request_output(motor2_enb, "motor2_enb", 0);
    gpiod_line_request_output(motor2_in3, "motor2_in3", 0);
    gpiod_line_request_output(motor2_in4, "motor2_in4", 0);
    gpiod_line_request_input(encoder1_a, "encoder1_a");
    gpiod_line_request_input(encoder1_b, "encoder1_b");
    gpiod_line_request_input(encoder2_a, "encoder2_a");
    gpiod_line_request_input(encoder2_b, "encoder2_b");
}

void *encoder_thread(void *arg) {
    struct gpiod_line_event event;
    int last_state1 = 0, last_state2 = 0;

    while (running) {
        if (gpiod_line_event_wait(encoder1_a, 1000) > 0) {
            gpiod_line_event_read(encoder1_a, &event);
            int current_state = gpiod_line_get_value(encoder1_b);
            if (current_state != last_state1) {
                pthread_mutex_lock(&encoder_mutex);
                encoder1_count += (current_state == last_state1) ? 1 : -1;
                pthread_mutex_unlock(&encoder_mutex);
            }
            last_state1 = current_state;
        }

        if (gpiod_line_event_wait(encoder2_a, 1000) > 0) {
            gpiod_line_event_read(encoder2_a, &event);
            int current_state = gpiod_line_get_value(encoder2_b);
            if (current_state != last_state2) {
                pthread_mutex_lock(&encoder_mutex);
                encoder2_count += (current_state == last_state2) ? 1 : -1;
                pthread_mutex_unlock(&encoder_mutex);
            }
            last_state2 = current_state;
        }
    }
    return NULL;
}

double get_rpm(int encoder_count) {
    return (encoder_count / (ENCODER_PULSES_PER_REV / 60.0)) / (SAMPLE_TIME_MS / 1000.0);
}

void set_motor_duty_cycle(struct gpiod_line *ena, struct gpiod_line *in1, struct gpiod_line *in2, double duty_cycle) {
    int value = (duty_cycle > 0) ? 1 : 0;
    gpiod_line_set_value(ena, value);
    gpiod_line_set_value(in1, value);
    gpiod_line_set_value(in2, !value);
}

void control_loop() {
    double integral1 = 0, integral2 = 0;
    double prev_error1 = 0, prev_error2 = 0;
    struct timespec sleep_time = {0, SAMPLE_TIME_MS * 1000000};

    while (running) {
        double rpm1, rpm2;
        pthread_mutex_lock(&encoder_mutex);
        rpm1 = get_rpm(encoder1_count);
        rpm2 = get_rpm(encoder2_count);
        pthread_mutex_unlock(&encoder_mutex);

        double error1 = TARGET_RPM - rpm1;
        double error2 = TARGET_RPM - rpm2;

        integral1 += error1 * (SAMPLE_TIME_MS / 1000.0);
        integral2 += error2 * (SAMPLE_TIME_MS / 1000.0);

        double derivative1 = (error1 - prev_error1) / (SAMPLE_TIME_MS / 1000.0);
        double derivative2 = (error2 - prev_error2) / (SAMPLE_TIME_MS / 1000.0);

        double output1 = KP * error1 + KI * integral1 + KD * derivative1;
        double output2 = KP * error2 + KI * integral2 + KD * derivative2;

        set_motor_duty_cycle(motor1_ena, motor1_in1, motor1_in2, output1);
        set_motor_duty_cycle(motor2_enb, motor2_in3, motor2_in4, output2);

        fprintf(log_file, "%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
                rpm1, rpm2, output1, output2, integral1, integral2);
        fflush(log_file);

        prev_error1 = error1;
        prev_error2 = error2;

        nanosleep(&sleep_time, NULL);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();

    log_file = fopen("motor_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "RPM1,RPM2,Output1,Output2,Integral1,Integral2\n");

    pthread_t encoder_thread1, encoder_thread2;
    if (pthread_create(&encoder_thread1, NULL, encoder_thread, NULL) != 0 ||
        pthread_create(&encoder_thread2, NULL, encoder_thread, NULL) != 0) {
        perror("Failed to create encoder threads");
        exit(EXIT_FAILURE);
    }

    control_loop();

    pthread_join(encoder_thread1, NULL);
    pthread_join(encoder_thread2, NULL);

    fclose(log_file);
    gpiod_line_release(motor1_ena);
    gpiod_line_release(motor1_in1);
    gpiod_line_release(motor1_in2);
    gpiod_line_release(motor2_enb);
    gpiod_line_release(motor2_in3);
    gpiod_line_release(motor2_in4);
    gpiod_line_release(encoder1_a);
    gpiod_line_release(encoder1_b);
    gpiod_line_release(encoder2_a);
    gpiod_line_release(encoder2_b);
    gpiod_chip_close(chip);

    return 0;
}

