#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define MPR121_I2C_ADDR 0x5A
#define MPR121_I2C_BUS 1
#define RELAY_GPIO 17
#define POLL_INTERVAL_MS 50

#define MPR121_TOUCH_STATUS_00 0x00
#define MPR121_TOUCH_STATUS_01 0x01
#define MPR121_SOFT_RESET 0x80
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_TOUCH_THRESHOLD 0x41
#define MPR121_RELEASE_THRESHOLD 0x42
#define MPR121_MHDPROXR 0x5B
#define MPR121_NHDPROXR 0x5C
#define MPR121_NCLPROXR 0x5D
#define MPR121_FDLPROXR 0x5E
#define MPR121_MHDPROXL 0x5F
#define MPR121_NHDPROXL 0x60
#define MPR121_NCLPROXL 0x61
#define MPR121_FDLPROXL 0x62
#define MPR121_ECR 0x5E
#define MPR121_CONFIG 0x5C

FILE *log_file;

void cleanup(int sig) {
    gpioSetMode(RELAY_GPIO, PI_INPUT);
    gpioWrite(RELAY_GPIO, PI_LOW);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write_byte(int i2c_handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_byte(int i2c_handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int mpr121_init(int i2c_handle) {
    // Soft reset
    if (i2c_write_byte(i2c_handle, MPR121_SOFT_RESET, 0x63) != 0) return -1;
    sleep(1);

    // Configure filtering
    if (i2c_write_byte(i2c_handle, MPR121_MHDR, 0x01) != 0) return -1;
    if (i2c_write_byte(i2c_handle, MPR121_NHDR, 0x01) != 0) return -1;
    if (i2c_write_byte(i2c_handle, MPR121_NCLR, 0x01) != 0) return -1;
    if (i2c_write_byte(i2c_handle, MPR121_FDLR, 0x01) != 0) return -1;
    if (i2c_write_byte(i2c_handle, MPR121_MHDF, 0x01) != 0) return -1;
    if (i2c_write_byte(i2c_handle, MPR121_NHDF, 0x01) != 0) return -1;
    if (i2c_write_byte(i2c_handle, MPR121_NCLF, 0x01) != 0) return -1;
    if (i2c_write_byte(i2c_handle, MPR121_FDLF, 0x01) != 0) return -1;
    if (i2c_write_byte(i2c_handle, MPR121_NHDT, 0x01) != 0) return -1;
    if (i2c_write_byte(i2c_handle, MPR121_NCLT, 0x01) != 0) return -1;
    if (i2c_write_byte(i2c_handle, MPR121_FDLT, 0x01) != 0) return -1;

    // Set touch and release thresholds
    for (int i = 0; i < 12; i++) {
