    printf("Received signal %d, cleaning up...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    valve1_line = gpiod_chip_get_line(chip, VALVE1_PIN);
    valve2_line = gpiod_chip_get_line(chip, VALVE2_PIN);

    if (!valve1_line || !valve2_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(valve1_line, "valve1", 0) < 0 ||
        gpiod_line_request_output(valve2_line, "valve2", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as output: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        gpiod_line_set_value(valve1_line, 1);
        log_event("Valve 1 activated");
        usleep(500000);  // 500 ms

        gpiod_line_set_value(valve1_line, 0);
        sleep(5);

        gpiod_line_set_value(valve2_line, 1);
        log_event("Valve 2 activated");
        usleep(1000000);  // 1000 ms

        gpiod_line_set_value(valve2_line, 0);
        sleep(10);
    }

    return EXIT_SUCCESS;
}

