#define ELE_TOUCH_STATUS_1 0x01
#define ELE_COUNT 12
#define TOUCH_THRESHOLD 0x10
#define RELEASE_THRESHOLD 0x0A
#define FILTER_CHARGE_TIME 0x20
#define ELE_CURRENT 0x01
#define RUN_MODE 0x20
#define ELE_EN 0x20

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    int ret = i2cWriteByteData(fd, reg, value);
    if (ret < 0) {
        fprintf(stderr, "Error writing to I2C register 0x%02X: %s\n", reg, gpioStrError(ret));
        return -1;
    }
    return 0;
}

int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    int ret = i2cReadByteData(fd, reg, value);
    if (ret < 0) {
        fprintf(stderr, "Error reading from I2C register 0x%02X: %s\n", reg, gpioStrError(ret));
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_fd = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for relay pin\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    gpioWrite(RELAY_PIN, PI_OFF);

    for (int i = 0; i < ELE_COUNT; i++) {
        if (i2c_write_byte(i2c_fd, 0x41 + i, TOUCH_THRESHOLD) < 0 ||
            i2c_write_byte(i2c_fd, 0x4B + i, RELEASE_THRESHOLD) < 0) {
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }
    }

    if (i2c_write_byte(i2c_fd, FILTER_CHARGE_TIME, 0x20) < 0 ||
        i2c_write_byte(i2c_fd, ELE_CURRENT, 0x01) < 0 ||
        i2c_write_byte(i2c_fd, RUN_MODE, ELE_EN) < 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    usleep(100000);  // 100ms stabilization

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        uint8_t touch_status[2];
        if (i2c_read_byte(i2c_fd, ELE_TOUCH_STATUS_0, &touch_status[0]) < 0 ||
            i2c_read_byte(i2c_fd, ELE_TOUCH_STATUS_1, &touch_status[1]) < 0) {
            break;
        }

        uint16_t full_status = (touch_status[1] << 8) | touch_status[0];
        if (full_status > 0) {
            int current_state = gpioRead(RELAY_PIN);
            gpioWrite(RELAY_PIN, !current_state);
            printf("Relay toggled. New state: %s\n", current_state ? "OFF" : "ON");
        }

        usleep(100000);  // 100ms delay
    }

    i2cClose(i2c_fd);
    gpioTerminate();
    return 0;
}

