#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define DATA_PIN 4
#define CLOCK_PIN 17
#define SOLENOID_PIN 27
#define READ_TIMEOUT 500000 // 0.5 seconds in microseconds
#define NUM_CALIBRATION_SAMPLES 100
#define WEIGHT_THRESHOLD 10.0

static volatile int keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT) {
        keep_running = 0;
    }
}

long read_hx711() {
    unsigned long count = 0;
    unsigned char data[3] = {0};
    int i;

    gpioWrite(CLOCK_PIN, 0);
    gpioDelay(1);

    for (i = 0; i < 24; i++) {
        gpioWrite(CLOCK_PIN, 1);
        gpioDelay(1);
        count = (count << 1) | gpioRead(DATA_PIN);
        gpioWrite(CLOCK_PIN, 0);
        gpioDelay(1);
    }

    gpioWrite(CLOCK_PIN, 1);
    gpioDelay(1);
    data[2] = gpioRead(DATA_PIN);
    gpioWrite(CLOCK_PIN, 0);
    gpioDelay(1);

    data[1] = gpioRead(DATA_PIN);
    gpioWrite(CLOCK_PIN, 1);
    gpioDelay(1);
    data[0] = gpioRead(DATA_PIN);
    gpioWrite(CLOCK_PIN, 0);
    gpioDelay(1);

    count ^= ((unsigned long)data[2] << 24);
    count ^= ((unsigned long)data[1] << 16);
    count ^= ((unsigned long)data[0] << 8);

    return (long)count;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(DATA_PIN, PI_INPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    double scale_factor = 1.0;
    double offset = 0.0;

    FILE *calib_file = fopen("calibration.txt", "r");
    if (calib_file) {
        if (fscanf(calib_file, "%lf %lf", &scale_factor, &offset) != 2) {
            fprintf(stderr, "Invalid calibration data, using defaults\n");
        }
        fclose(calib_file);
    } else {
        fprintf(stderr, "Calibration file not found, using defaults\n");
    }

    // Perform one-time startup calibration
    double total = 0.0;
    for (int i = 0; i < NUM_CALIBRATION_SAMPLES; i++) {
        long raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "HX711 read timeout\n");
            continue;
        }
        total += (double)raw_value;
        gpioDelay(5000); // 5ms delay between readings
    }
    offset = total / NUM_CALIBRATION_SAMPLES;

    calib_file = fopen("calibration.txt", "w");
    if (calib_file) {
        fprintf(calib_file, "%.6f %.6f\n", scale_factor, offset);
        fclose(calib_file);
    }

    FILE *log_file = fopen("weight_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    while (keep_running) {
        long raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "HX711 read timeout\n");
            gpioDelay(READ_TIMEOUT);
            continue;
        }

        double weight = (raw_value - offset) * scale_factor;

        time(&now);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s: %.2f kg\n", timestamp, weight);
        fflush(log_file);

        if (weight > WEIGHT_THRESHOLD) {
            gpioWrite(SOLENOID_PIN, 1);
        } else {
            gpioWrite(SOLENOID_PIN, 0);
        }

        gpioDelay(500000); // 500ms delay between readings
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

