#include <signal.h>
#include <syslog.h>
#include <time.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_MS 50
#define RAIN_DETECTED_THRESHOLD 3
#define MOTOR_RUN_TIME_SEC 5
#define CHECK_INTERVAL_SEC 60

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_message(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    syslog(LOG_INFO, "[%s] %s", time_str, message);
}

int read_rain_sensor() {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        if (gpioRead(RAIN_SENSOR_PIN) == PI_LOW) {
            low_count++;
        }
        gpioSleep(Time_release_time, DEBOUNCE_DELAY_MS / 1000, (DEBOUNCE_DELAY_MS % 1000) * 1000);
    }
    return low_count >= RAIN_DETECTED_THRESHOLD;
}

void run_motor() {
    gpioWrite(MOTOR_IN1_PIN, PI_HIGH);
    gpioWrite(MOTOR_IN2_PIN, PI_LOW);
    gpioPWM(MOTOR_PWM_PIN, 1000, 150); // 1000 Hz, 150/255 duty cycle
    sleep(MOTOR_RUN_TIME_SEC);
    gpioWrite(MOTOR_IN1_PIN, PI_LOW);
    gpioWrite(MOTOR_IN2_PIN, PI_LOW);
    gpioPWM(MOTOR_PWM_PIN, 0, 0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (setlogmask(LOG_UPTO(LOG_INFO)) == -1) {
        fprintf(stderr, "Failed to set log mask\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    openlog("window_control", LOG_CONS | LOG_PID | LOG_NDELAY, LOG_USER);

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        closelog();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        if (read_rain_sensor()) {
            log_message("Rain detected. Closing window.");
            run_motor();
            log_message("Window closed.");
        }
        sleep(CHECK_INTERVAL_SEC);
    }

    closelog();
    gpioTerminate();
    return EXIT_SUCCESS;
}

