#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>

#define DT_PIN 23
#define SCK_PIN 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD 100
#define CHECK_INTERVAL 1

static volatile int keep_running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        keep_running = 0;
    }
}

int hx711_read(int dt, int sck) {
    unsigned long int value = 0;
    int i;
    int timeout = 1000; // 1ms timeout

    gpioWrite(sck, 0);
    usleep(1);

    for (i = 0; i < 24; i++) {
        gpioWrite(sck, 1);
        usleep(1);
        value = (value << 1) | gpioRead(dt);
        gpioWrite(sck, 0);
        usleep(1);
    }

    gpioWrite(sck, 1);
    usleep(1);
    value ^= 0x800000;
    gpioWrite(sck, 0);
    usleep(1);

    // Check for timeout or stuck high
    if (gpioRead(dt) == 1 || timeout-- <= 0) {
        return -1; // Error
    }

    return (int)value;
}

void log_event(const char* message) {
    FILE* file = fopen("stock_events.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t now;
    time(&now);
    char* time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline

    fprintf(file, "[%s] %s\n", time_str, message);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(DT_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SCK_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "GPIO mode setting failed\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        int weight = hx711_read(DT_PIN, SCK_PIN);
        if (weight < 0) {
            fprintf(stderr, "Error reading HX711\n");
        } else {
            printf("Current weight: %d g\n", weight);
            if (weight < WEIGHT_THRESHOLD) {
                gpioWrite(SOLENOID_PIN, 1);
                log_event("Solenoid activated");
                sleep(5);
                gpioWrite(SOLENOID_PIN, 0);
            }
        }
