#define SOLENOID_PIN 27
#define TIMEOUT 100000 // 100 ms
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"

volatile sig_atomic_t terminate = 0;

void sigint_handler(int signum) {
    terminate = 1;
}

int hx711_read() {
    unsigned long int value = 0;
    int count;
    struct timespec start, current;

    gpioWrite(CLOCK_PIN, 0);
    nanosleep(&(struct timespec){0, 1000}, NULL); // 1 microsecond delay

    for (count = 0; count < 24; count++) {
        gpioWrite(CLOCK_PIN, 1);
        nanosleep(&(struct timespec){0, 1000}, NULL); // 1 microsecond delay
        gpioWrite(CLOCK_PIN, 0);
        nanosleep(&(struct timespec){0, 1000}, NULL); // 1 microsecond delay

        value = (value << 1) | gpioRead(DATA_PIN);
    }

    gpioWrite(CLOCK_PIN, 1);
    nanosleep(&(struct timespec){0, 1000}, NULL); // 1 microsecond delay
    gpioWrite(CLOCK_PIN, 0);
    nanosleep(&(struct timespec){0, 1000}, NULL); // 1 microsecond delay

    value ^= 0x800000; // Convert to signed 24-bit

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpioRead(DATA_PIN) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &current);
        if ((current.tv_sec - start.tv_sec) * 1000000 + (current.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT) {
            return -1; // Timeout
        }
    }

    return (int)value;
}

double read_calibration() {
    FILE *file = fopen(CALIBRATION_FILE, "r");
    if (!file) {
        return -1;
    }

