    if (fscanf(file, "%lf", &calibration) != 1) {
        fclose(file);
        return -1;
    }

    fclose(file);
    return calibration;
}

void write_calibration(double calibration) {
    FILE *file = fopen(CALIBRATION_FILE, "w");
    if (!file) {
        fprintf(stderr, "Failed to open calibration file for writing\n");
        return;
    }

    fprintf(file, "%lf\n", calibration);
    fclose(file);
}

void log_event(double weight) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(file, "[%s] Weight exceeded: %.2f kg\n", timestamp, weight);
    fclose(file);
}

