    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(DATA_PIN, PI_INPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    signal(SIGINT, sigint_handler);

    double calibration = read_calibration();
    if (calibration < 0) {
        printf("Calibration file not found or invalid. Please place a known weight on the scale.\n");
        printf("Enter the weight in kilograms: ");
