        if (scanf("%lf", &known_weight) != 1 || known_weight <= 0) {
            fprintf(stderr, "Invalid weight input\n");
            gpioTerminate();
            return 1;
        }

        int raw_value = hx711_read();
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read from HX711 during calibration\n");
            gpioTerminate();
            return 1;
        }

        calibration = (double)raw_value / known_weight;
        write_calibration(calibration);
        printf("Calibration complete. Saved to %s\n", CALIBRATION_FILE);
    }

    printf("System ready. Monitoring weight...\n");

    while (!terminate) {
        int raw_value = hx711_read();
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read from HX711\n");
            continue;
