        double weight = (double)raw_value / calibration;

        if (weight > 5.0) {
            log_event(weight);
            gpioWrite(SOLENOID_PIN, 1);
            sleep(5);
            gpioWrite(SOLENOID_PIN, 0);
        }

        usleep(100000); // 100ms delay between readings
    }

    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is unlocked
    gpioTerminate();
    return 0;
}

