#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define SENSOR_PIN 16
#define RELAY_PIN 20
#define LOG_FILE "relay_events.log"

static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line, *relay_line;

void cleanup(int signum) {
    if (relay_line) gpiod_line_release(relay_line);
    if (sensor_line) gpiod_line_release(sensor_line);
    if (chip) gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fclose(log_file);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);

    if (!sensor_line || !relay_line) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        cleanup(0);
    }

    struct gpiod_line_request_config sensor_config = {
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .flags = 0,
    };

    struct gpiod_line_request_config relay_config = {
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .flags = 0,
    };

    if (gpiod_line_request(sensor_line, &sensor_config, "obstacle_sensor") < 0 ||
        gpiod_line_request(relay_line, &relay_config, "relay_module") < 0) {
        fprintf(stderr, "Error requesting GPIO lines: %s\n", strerror(errno));
        cleanup(0);
    }

    int relay_state = 0;
    gpiod_line_set_value(relay_line, relay_state);

    while (1) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor: %s\n", strerror(errno));
            cleanup(0);
        }

        if (sensor_value == 0) {  // Obstacle detected (active-low)
            relay_state = !relay_state;
            gpiod_line_set_value(relay_line, relay_state);

            const char *state_str = relay_state ? "ON" : "OFF";
            char log_message[64];
            snprintf(log_message, sizeof(log_message), "Relay toggled to %s", state_str);
            log_event(log_message);
        }

        // Small delay to prevent busy-waiting
        usleep(100000);
    }

    return EXIT_SUCCESS;
}

