        cleanup(0);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup(0);
    }

    printf("Monitoring motion...\n");

    while (1) {
        pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            fprintf(stderr, "Error reading PIR sensor: %s\n", strerror(errno));
            cleanup(0);
        }

        if (pir_value) {
            log_motion_event();
            activate_buzzer();
        }

        usleep(100000);  // 100ms delay to prevent excessive CPU usage
    }

    return EXIT_SUCCESS;
