#include <errno.h>
#include <gpiod.h>

#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"
#define MIN_DURATION 1
#define MAX_DURATION 3600

volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

int parse_configuration(const char *filename, int *duration) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening configuration file: %s\n", strerror(errno));
        return -1;
    }

    char line[128];
    if (!fgets(line, sizeof(line), file)) {
        fprintf(stderr, "Configuration file is empty\n");
        fclose(file);
        return -1;
    }

    fclose(file);

    if (sscanf(line, "duration=%d", duration) != 1) {
        fprintf(stderr, "Malformed configuration line\n");
        return -1;
    }

    if (*duration < MIN_DURATION || *duration > MAX_DURATION) {
        fprintf(stderr, "Duration out of range (%d-%d seconds)\n", MIN_DURATION, MAX_DURATION);
        return -1;
    }

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int duration;

    if (parse_configuration(CONFIG_FILE, &duration) != 0) {
        return EXIT_FAILURE;
    }

    printf("Configured watering duration: %d seconds\n", duration);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int ret = gpiod_line_request_output(line, "watering-controller", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Valve activated\n");
    gpiod_line_set_value(line, 1);

    while (!terminate) {
        if (duration > 0) {
            sleep(duration);
            duration = 0;
        }
    }

    printf("Valve deactivated\n");
    gpiod_line_set_value(line, 0);

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

