#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27
#define LEFT_MOTOR_PWM 22
#define RIGHT_MOTOR_PWM 23
#define BASE_SPEED 150
#define PWM_FREQUENCY 1000

FILE *log_file;

void cleanup(int signum) {
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetPWMfrequency(LEFT_MOTOR_PWM, 0);
    gpioSetPWMfrequency(RIGHT_MOTOR_PWM, 0);
    gpioSetPWMdutycycle(LEFT_MOTOR_PWM, 0);
    gpioSetPWMdutycycle(RIGHT_MOTOR_PWM, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (setjmp(gpioJmpBuffer) != 0) {
        fprintf(stderr, "pigpio error occurred\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);

    gpioSetPWMfrequency(LEFT_MOTOR_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(RIGHT_MOTOR_PWM, PWM_FREQUENCY);

    log_file = fopen("trace_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
    }

    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    while (1) {
        int left = gpioRead(LEFT_SENSOR);
        int middle = gpioRead(MIDDLE_SENSOR);
        int right = gpioRead(RIGHT_SENSOR);

        int left_speed = BASE_SPEED;
        int right_speed = BASE_SPEED;

        if (middle == 0) {
            // Drive straight
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left == 0) {
            // Turn right
            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (right == 0) {
            // Turn left
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        } else {
            // Stop
            left_speed = 0;
            right_speed = 0;
        }

        gpioSetPWMdutycycle(LEFT_MOTOR_PWM, left_speed);
        gpioSetPWMdutycycle(RIGHT_MOTOR_PWM, right_speed);

        time(&now);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp, left, middle, right, left_speed, right_speed);
        fflush(log_file);

        gpioSleep(PI_TIME_RELATIVE, 0, 10000000); // 10 ms
    }

    return EXIT_SUCCESS;
}

