#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>

#define SENSOR_ADDR 0x23
#define RELAY_PIN 23
#define I2C_BUS 1
#define LUX_THRESHOLD 150
#define MEASUREMENT_DELAY_MS 180

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_message(const char *message) {
    FILE *log_file = fopen("grow_log.txt", "a");
    if (log_file) {
        time_t now;
        struct tm *tm_info;
        char timestamp[64];

        time(&now);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "[%s.%03ld] %s\n", timestamp, (long)(now * 1000 % 1000), message);
        fclose(log_file);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, PI_LOW);

    if (i2cOpen(I2C_BUS, SENSOR_ADDR, 0) < 0) {
        log_message("Error: BH1750 sensor not detected");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (keep_running) {
        char command = 0x10;
        if (i2cWriteDevice(I2C_BUS, SENSOR_ADDR, &command, 1) < 0) {
            log_message("Error: Failed to send command to BH1750");
            sleep(1);
            continue;
        }

        usleep(24 * 1000);  // Wait for measurement (24 ms)

        char data[2];
        if (i2cReadI2CBlock(I2C_BUS, SENSOR_ADDR, data, 2) < 0) {
            log_message("Error: Failed to read from BH1750");
            sleep(1);
            continue;
        }

        float lux = (data[0] << 8 | data[1]) / 1.2f;
        char lux_msg[64];
        snprintf(lux_msg, sizeof(lux_msg), "Lux: %.2f", lux);
        log_message(lux_msg);

        int relay_state = (lux < LUX_THRESHOLD) ? PI_HIGH : PI_LOW;
        gpioWrite(RELAY_PIN, relay_state);

        char relay_msg[64];
        snprintf(relay_msg, sizeof(relay_msg), "Relay: %s", relay_state ? "ON" : "OFF");
        log_message(relay_msg);

        sleep(MEASUREMENT_DELAY_MS / 1000);
    }

    i2cClose(I2C_BUS);
    gpioWrite(RELAY_PIN, PI_LOW);
    gpioTerminate();

    return EXIT_SUCCESS;
}

