#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define LOCK_POSITION 1000
#define UNLOCK_POSITION 2000
#define DEBOUNCE_TIME 100

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    signal(SIGINT, signal_handler);

    printf("Door lock system initialized. Press Ctrl+C to exit.\n");

    while (keep_running) {
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            usleep(DEBOUNCE_TIME * 1000);
            if (gpioRead(LOCK_BUTTON_PIN) == 0) {
                int position = LOCK_POSITION;
                if (position < 500) position = 500;
                if (position > 2500) position = 2500;
                gpioServo(SERVO_PIN, position);
                printf("Locking servo to %d microseconds\n", position);
                while (gpioRead(LOCK_BUTTON_PIN) == 0) {
                    usleep(10000);
                }
            }
        }

        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            usleep(DEBOUNCE_TIME * 1000);
            if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
                int position = UNLOCK_POSITION;
                if (position < 500) position = 500;
                if (position > 2500) position = 2500;
                gpioServo(SERVO_PIN, position);
                printf("Unlocking servo to %d microseconds\n", position);
                while (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
                    usleep(10000);
                }
            }
        }

        usleep(10000);
    }

    gpioTerminate();
    printf("Door lock system terminated.\n");
    return 0;
}

