#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MOTOR1_DURATION_MS 200
#define MOTOR2_DURATION_MS 300

static struct gpiod_chip *chip;
static struct gpiod_line *motor1_line;
static struct gpiod_line *motor2_line;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    motor1_line = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!motor1_line) {
        fprintf(stderr, "Failed to get line for motor 1\n");
        goto cleanup;
    }

    motor2_line = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!motor2_line) {
        fprintf(stderr, "Failed to get line for motor 2\n");
        goto cleanup;
    }

    if (gpiod_line_request_output(motor1_line, "haptic_motor1", 0) < 0) {
        fprintf(stderr, "Failed to request motor 1 line as output\n");
        goto cleanup;
    }

    if (gpiod_line_request_output(motor2_line, "haptic_motor2", 0) < 0) {
        fprintf(stderr, "Failed to request motor 2 line as output\n");
        goto cleanup;
    }

    while (keep_running) {
        if (gpiod_line_set_value(motor1_line, 1) < 0) {
            fprintf(stderr, "Failed to set motor 1 line high\n");
            break;
        }
        usleep(MOTOR1_DURATION_MS * 1000);

