#include <unistd.h>
#include <cjson/cJSON.h>
#include <mosquitto.h>

#define IR_PIN 17
#define BUFFER_SIZE 1000
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_BIT_SPACE_0 560
#define NEC_BIT_SPACE_1 1690
#define NEC_TIMEOUT 10000000

volatile int buffer[BUFFER_SIZE];
volatile int buffer_index = 0;
volatile int last_tick = 0;
volatile int in_sync = 0;
volatile uint32_t address = 0;
volatile uint32_t command = 0;
volatile int bits = 0;
volatile int extended = 0;

struct mosquitto *mosq = NULL;

void gpio_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_FALLING_EDGE) {
        int duration = tick - last_tick;
        last_tick = tick;

        if (buffer_index < BUFFER_SIZE) {
            buffer[buffer_index++] = duration;
        }
    }
}

void decode_nec() {
    int i;
    uint32_t raw_data = 0;
    int bit_count = 0;

    for (i = 0; i < buffer_index; i++) {
        if (buffer[i] >= NEC_BIT_MARK && buffer[i] <= NEC_BIT_SPACE_1) {
            if (buffer[i] >= NEC_BIT_SPACE_0) {
                raw_data = (raw_data << 1) | 1;
            } else {
                raw_data = (raw_data << 1) & 0xFFFFFFFE;
            }
            bit_count++;
        }
    }

    if (bit_count == 32) {
        address = (raw_data >> 16) & 0xFFFF;
        command = raw_data & 0xFFFF;
        syslog(LOG_INFO, "Decoded NEC: Address: 0x%04X, Command: 0x%04X", address, command);

        cJSON *json = cJSON_CreateObject();
        cJSON_AddNumberToObject(json, "address", address);
        cJSON_AddNumberToObject(json, "command", command);
        char *json_str = cJSON_Print(json);
        mosquitto_publish(mosq, NULL, "ir/decoded", strlen(json_str), json_str, 0, false);
        cJSON_Delete(json);
        free(json_str);
    }

    buffer_index = 0;
}

void check_sync() {
    if (buffer_index > 10) {
        int i;
        for (i = 0; i < 10; i++) {
            if (buffer[i] < NEC_HEADER_MARK - 500 || buffer[i] > NEC_HEADER_MARK + 500) {
                in_sync = 0;
                break;
            }
        }
        for (; i < 20; i++) {
            if (buffer[i] < NEC_HEADER_SPACE - 500 || buffer[i] > NEC_HEADER_SPACE + 500) {
                in_sync = 0;
                break;
            }
        }
        if (in_sync) {
            decode_nec();
        }
    }
}

void mqtt_on_connect(struct mosquitto *mosq, void *obj, int result) {
    if (result == 0) {
        mosquitto_subscribe(mosq, NULL, "ir/decoded", 0);
    }
}

void mqtt_on_message(struct mosquitto *mosq, void *obj, const struct mosquitto_message *msg) {
    // Handle incoming messages if needed
}

void signal_handler(int signum) {
    if (mosq) {
        mosquitto_destroy(mosq);
    }
    closelog();
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioSetMode(IR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(IR_PIN, gpio_callback) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO alert function");
        gpioTerminate();
        return 1;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, mqtt_on_connect);
    mosquitto_message_callback_set(mosq, mqtt_on_message);

    if (mosquitto_connect(mosq, "localhost", 1883, 60) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        check_sync();
        mosquitto_loop(mosq, 1000, 1);
    }

    return 0;
}

