static int i2c_fd;
static FILE *log_file;

void sigint_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t *buf, size_t len) {
    ssize_t ret;
    ret = write(fd, buf, len);
    if (ret < 0) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *buf, size_t len) {
    ssize_t ret;
    int retries = 0;
    do {
        ret = read(fd, buf, len);
        if (ret < 0) {
            if (errno == EIO || (errno == ENXIO && retries == 0)) {
                retries++;
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            }
            perror("I2C read failed");
            return -1;
        }
        return 0;
    } while (retries < MAX_RETRIES);
    return -1;
}

int main() {
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[2];
    uint8_t write_buf[1] = {0};
    uint8_t read_buf[2];
    int16_t raw_value;
    float flow_rate;
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    signal(SIGINT, sigint_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        memset(&packets, 0, sizeof(packets));
        memset(&messages, 0, sizeof(messages));

        messages[0].addr = SENSOR_ADDR;
        messages[0].flags = 0;
        messages[0].len = sizeof(write_buf);
        messages[0].buf = write_buf;

        messages[1].addr = SENSOR_ADDR;
        messages[1].flags = I2C_M_RD;
        messages[1].len = sizeof(read_buf);
        messages[1].buf = read_buf;

        packets.msgs = messages;
        packets.nmsgs = 2;

        if (ioctl(i2c_fd, I2C_RDWR, &packets) < 0) {
            perror("I2C transfer failed");
            continue;
        }

        raw_value = (read_buf[0] << 8) | read_buf[1];
        raw_value &= 0x3FFF;
        flow_rate = (raw_value - 3277) * 0.1;

        time(&now);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s: %.2f SLPM\n", timestamp, flow_rate);
        fflush(log_file);

        sleep(1);
    }

    return EXIT_SUCCESS;
}

