#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define AS7341_ADDR 0x39
#define WHO_AM_I_REG 0x24
#define ENABLE_REG 0x80
#define CFG6_REG 0xAF
#define STATUS_REG 0x81
#define DATA_REG 0x60
#define NUM_CHANNELS 10
#define LOG_FILE "spectral_log.csv"
#define LOG_INTERVAL 5

int i2c_fd;
FILE *log_file;

void cleanup(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    return read(fd, value, 1);
}

int main() {
    uint8_t who_am_i, enable, cfg6, status, data[NUM_CHANNELS * 2];
    time_t last_log_time = 0;

    signal(SIGINT, cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (i2c_read(i2c_fd, WHO_AM_I_REG, &who_am_i) != 1 || who_am_i != 0x19) {
        fprintf(stderr, "Sensor not found or communication error\n");
        cleanup(1);
    }

    if (i2c_write(i2c_fd, ENABLE_REG, 0x01) != 1) {
        perror("Failed to power on sensor");
        cleanup(1);
    }

    usleep(10000);  // Wait for power-on

    if (i2c_write(i2c_fd, CFG6_REG, 0x00) != 1) {
        perror("Failed to configure SMUX");
        cleanup(1);
    }

    if (i2c_write(i2c_fd, ENABLE_REG, 0x03) != 1) {
        perror("Failed to enable spectral measurement");
        cleanup(1);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup(1);
    }

    fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR\n");

    while (1) {
        if (i2c_read(i2c_fd, STATUS_REG, &status) != 1 || !(status & 0x01)) {
            fprintf(stderr, "Sensor not ready\n");
            sleep(1);
            continue;
        }

        for (int i = 0; i < NUM_CHANNELS * 2; i += 2) {
            if (i2c_read(i2c_fd, DATA_REG + i, &data[i]) != 1 ||
                i2c_read(i2c_fd, DATA_REG + i + 1, &data[i + 1]) != 1) {
                fprintf(stderr, "Failed to read channel data\n");
                cleanup(1);
            }
        }

        time_t now = time(NULL);
        if (now - last_log_time >= LOG_INTERVAL) {
            fprintf(log_file, "%ld,", now);
            for (int i = 0; i < NUM_CHANNELS * 2; i += 2) {
                fprintf(log_file, "%d,", (data[i] << 8) | data[i + 1]);
            }
            fprintf(log_file, "\n");
            fflush(log_file);
            last_log_time = now;
        }

        usleep(100000);  // 100ms delay between readings
    }

    cleanup(0);
}

