#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>
#include <time.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDR 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define BUFFER_SIZE 1024

static int i2c_fd = -1;
static FILE *csv_file = NULL;
static FILE *error_log = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_error(const char *message) {
    time_t now;
    time(&now);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(error_log, "[%s] %s\n", time_str, message);
    fflush(error_log);
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    return write(fd, buf, sizeof(buf));
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (i2c_write(fd, reg, 0) != 2) {
        return -1;
    }
    return read(fd, buf, len);
}

int retry_transient(int (*func)(int, uint8_t, uint8_t*), int fd, uint8_t reg, uint8_t *buf) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (func(fd, reg, buf) == len) {
            return 0;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

void read_sensor_data(int i2c_addr, int interval, const char *filename) {
    int16_t raw_data[3];
    float g_data[3];
    char buffer[BUFFER_SIZE];

    csv_file = fopen(filename, "w");
    if (!csv_file) {
        log_error("Failed to open CSV file");
        return;
    }
    fprintf(csv_file, "timestamp,x_g,y_g,z_g\n");

    while (keep_running) {
