#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x23
#define UDP_MULTICAST_ADDR "239.255.255.250"
#define UDP_PORT 5000
#define TTL 1
#define RETRY_DELAY 1

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int init_i2c() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int init_udp_socket() {
    int sock = socket(AF_INET, SOCK_DGRAM, I2C_BUS);
    if (sock < 0) {
        perror("Failed to create UDP socket");
        return -1;
    }

    int ttl = TTL;
    if (setsockopt(sock, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Failed to set UDP TTL");
        close(sock);
        return -1;
    }

    return sock;
}

int write_i2c(int fd, uint8_t *data, size_t len) {
    ssize_t bytes_written = write(fd, data, len);
    if (bytes_written < 0) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int read_i2c(int fd, uint8_t *data, size_t len) {
    ssize_t bytes_read = read(fd, data, len);
    if (bytes_read < 0) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return bytes_read;
}

int send_udp(int sock, const char *msg, size_t len) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(UDP_MULTICAST_ADDR);
    addr.sin_port = htons(UDP_PORT);

    ssize_t bytes_sent = sendto(sock, msg, len, 0, (struct sockaddr *)&addr, sizeof(addr));
    if (bytes_sent < 0) {
        perror("Failed to send UDP packet");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    int udp_sock = init_udp_socket();
    if (udp_sock < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t init_cmd[] = {0x01, 0x10};
    if (write_i2c(i2c_fd, init_cmd, sizeof(init_cmd)) < 0) {
        close(i2c_fd);
        close(udp_sock);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint8_t data[2];
        if (read_i2c(i2c_fd, data, sizeof(data)) < 0) {
            fprintf(stderr, "Error reading from sensor, retrying in %d seconds...\n", RETRY_DELAY);
            sleep(RETRY_DELAY);
            continue;
        }

        uint16_t raw = (data[0] << 8) | data[1];
        float lux = raw / 1.2;

        char msg[32];
        snprintf(msg, sizeof(msg), "%.2f", lux);

        if (send_udp(udp_sock, msg, strlen(msg)) < 0) {
            fprintf(stderr, "Error sending UDP packet, retrying in %d seconds...\n", RETRY_DELAY);
        }

        sleep(1);
    }

    close(i2c_fd);
    close(udp_sock);
    return EXIT_SUCCESS;
}

