#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>

#define UART_DEV "/dev/ttyS0"
#define BAUD_RATE 921600
#define BUFFER_SIZE 4096
#define MAGIC_WORD_SIZE 8
#define MAGIC_WORD 0x0204030608050709
#define TLV_HEADER_SIZE 8
#define CSV_FILE "radar_data.csv"

static volatile int keep_running = 1;
static int uart_fd;
static FILE *csv_file;

void signal_handler(int signum) {
    keep_running = 0;
}

int init_uart() {
    uart_fd = serialOpen(UART_DEV, BAUD_RATE);
    if (uart_fd < 0) {
        fprintf(stderr, "Error opening UART: %s\n", strerror(errno));
        return -1;
    }
    serialSetBlocking(uart_fd, 0);
    return 0;
}

void close_uart() {
    if (uart_fd >= 0) {
        serialClose(uart_fd);
    }
}

int init_csv() {
    csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return -1;
    }
    fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    return 0;
}

void close_csv() {
    if (csv_file) {
        fflush(csv_file);
        fclose(csv_file);
    }
}

int read_magic_word() {
    uint8_t buffer[MAGIC_WORD_SIZE];
    int bytes_read = 0;

    while (bytes_read < MAGIC_WORD_SIZE) {
        int result = serialRead(uart_fd, buffer + bytes_read, MAGIC_WORD_SIZE - bytes_read);
        if (result < 0) {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        }
        bytes_read += result;
    }

    return *(uint64_t *)buffer == MAGIC_WORD;
}

int read_tlv_header(uint8_t *buffer) {
    int bytes_read = 0;
    while (bytes_read < TLV_HEADER_SIZE) {
        int result = serialRead(uart_fd, buffer + bytes_read, TLV_HEADER_SIZE - bytes_read);
        if (result < 0) {
            fprintf(stderr, "Error reading TLV header: %s\n", strerror(errno));
            return -1;
        }
        bytes_read += result;
    }
    return 0;
}

int read_tlv_payload(uint8_t *buffer, int payload_size) {
    int bytes_read = 0;
    while (bytes_read < payload_size) {
        int result = serialRead(uart_fd, buffer + bytes_read, payload_size - bytes_read);
        if (result < 0) {
            fprintf(stderr, "Error reading TLV payload: %s\n", strerror(errno));
            return -1;
        }
        bytes_read += result;
    }
    return 0;
}

void process_tlv(uint8_t *tlv_buffer, int tlv_size) {
    static int object_index = 0;
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = ts.tv_sec + ts.tv_nsec * 1e-9;

    for (int i = 0; i < tlv_size; i += 12) {
        if (i + 12 > tlv_size) break;

        float range = *(float *)(tlv_buffer + i);
        float velocity = *(float *)(tlv_buffer + i + 4);

        fprintf(csv_file, "%.6f,%d,%.2f,%.2f\n", timestamp, object_index++, range, velocity);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO\n");
        return 1;
    }

    if (init_uart() < 0 || init_csv() < 0) {
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t buffer[BUFFER_SIZE];
    uint8_t tlv_buffer[BUFFER_SIZE];

    while (keep_running) {
        if (read_magic_word()) {
            if (read_tlv_header(buffer) == 0) {
                uint16_t tlv_type = buffer[0] | (buffer[1] << 8);
                uint16_t tlv_length = buffer[2] | (buffer[3] << 8);

                if (tlv_type == 1 && tlv_length <= BUFFER_SIZE - TLV_HEADER_SIZE) {
                    if (read_tlv_payload(tlv_buffer, tlv_length) == 0) {
                        process_tlv(tlv_buffer, tlv_length);
                    }
                }
            }
        }
    }

    close_uart();
    close_csv();
    gpioTerminate();
    return 0;
}

