#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>

#define UART_DEV "/dev/serial0"
#define BAUD_RATE B115200
#define BUFFER_SIZE 1024
#define TIMEOUT_SECONDS 2
#define INTER_BYTE_TIMEOUT_MS 500

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void print_error(const char *msg) {
    fprintf(stderr, "%s: %s\n", msg, strerror(errno));
}

int configure_uart(int fd) {
    struct termios options;

    if (tcgetattr(fd, &options) < 0) {
        print_error("tcgetattr");
        return -1;
    }

    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);

    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;

    options.c_cc[VMIN] = 0;
    options.c_cc[VTIME] = (INTER_BYTE_TIMEOUT_MS + 99) / 100;

    if (tcsetattr(fd, TCSANOW, &options) < 0) {
        print_error("tcsetattr");
        return -1;
    }

    return 0;
}

int main() {
    int fd;
    char buffer[BUFFER_SIZE];
    char line_buffer[BUFFER_SIZE];
    int line_index = 0;
    struct sigaction sa;
    fd_set read_fds;
    struct timeval tv;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        print_error("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(UART_DEV, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        print_error("open");
        return EXIT_FAILURE;
    }

    if (configure_uart(fd) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        FD_ZERO(&read_fds);
        FD_SET(fd, &read_fds);

        tv.tv_sec = TIMEOUT_SECONDS;
        tv.tv_usec = 0;

        int ready = select(fd + 1, &read_fds, NULL, NULL, &tv);
        if (ready < 0) {
            print_error("select");
            break;
        } else if (ready == 0) {
            continue;
        }

        ssize_t bytes_read = read(fd, buffer, sizeof(buffer));
        if (bytes_read < 0) {
            print_error("read");
            break;
        }

        for (ssize_t i = 0; i < bytes_read; ++i) {
            char c = buffer[i];
            if (c == '\n') {
                line_buffer[line_index] = '\0';
                char *line_copy = strdup(line_buffer);
                if (line_copy == NULL) {
                    print_error("strdup");
                    break;
                }

                char *timestamp_str = strtok(line_copy, ",");
                char *range_str = strtok(NULL, ",");

                if (timestamp_str && range_str) {
                    time_t timestamp = (time_t)strtod(timestamp_str, NULL);
                    double range = strtod(range_str, NULL);

                    struct tm *tm_info = localtime(&timestamp);
                    if (tm_info) {
                        char time_str[26];
                        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
                        printf("Timestamp: %s, Range: %.2f meters\n", time_str, range);
                    }
                }

                free(line_copy);
                line_index = 0;
            } else {
                if (line_index < BUFFER_SIZE - 1) {
                    line_buffer[line_index++] = c;
                } else {
                    fprintf(stderr, "Line buffer overflow\n");
                    line_index = 0;
                }
            }
        }
    }

    close(fd);
    return EXIT_SUCCESS;
}

