#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>

#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27
#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE B115200
#define LOOP_DELAY_MS 100

int serial_fd;

void cleanup(int sig) {
    if (serial_fd != -1) {
        close(serial_fd);
    }
    gpioTerminate();
    exit(0);
}

int setup_serial() {
    serial_fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_NDELAY);
    if (serial_fd == -1) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios options;
    tcgetattr(serial_fd, &options);
    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CRTSCTS;
    tcsetattr(serial_fd, TCSANOW, &options);

    return 0;
}

int write_serial(const char *data) {
    ssize_t bytes_written = write(serial_fd, data, strlen(data));
    if (bytes_written == -1) {
        perror("Error writing to serial port");
    }
    return bytes_written;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (setup_serial() != 0) {
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);

    gpioSetPullUpDown(LEFT_SENSOR, PI_PUD_UP);
    gpioSetPullUpDown(MIDDLE_SENSOR, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_SENSOR, PI_PUD_UP);

    time_t last_time = time(NULL);

    while (1) {
        int left = gpioRead(LEFT_SENSOR);
        int middle = gpioRead(MIDDLE_SENSOR);
        int right = gpioRead(RIGHT_SENSOR);

        if (left == -1 || middle == -1 || right == -1) {
            fprintf(stderr, "Error reading GPIO\n");
            continue;
        }

        time_t current_time = time(NULL);
        struct tm *time_info = localtime(&current_time);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);

        if (left == 0 && middle == 0 && right == 0) {
            if (write_serial("EMERGENCY STOP!\n") == -1) {
                fprintf(stderr, "Error writing to serial port\n");
            }
        }

        time_t sleep_time = current_time - last_time;
        if (sleep_time < 1) {
            usleep((1 - sleep_time) * 1000000);
        }
        last_time = time(NULL);
    }

    return 0;
}

